-- Name: archive_related_entry_readable_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.archive_related_entry_readable_v1(p_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
