$$;


--
-- Name: assign_word_entry_management(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.assign_word_entry_management() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_kind text;
    v_expected_management text;
BEGIN
    SELECT kind
    INTO v_dictionary_kind
    FROM public.dictionaries
    WHERE id = NEW.dictionary_id;

    IF v_dictionary_kind IS NULL THEN
        RAISE EXCEPTION 'word_entry_dictionary_not_found';
    END IF;

    v_expected_management := CASE
        WHEN v_dictionary_kind = 'user' THEN 'user'
        ELSE 'source'
    END;

    NEW.management_kind := COALESCE(
        NEW.management_kind,
        v_expected_management
    );
    IF NEW.management_kind <> v_expected_management THEN
        RAISE EXCEPTION 'word_entry_management_mismatch';
    END IF;

    IF NEW.management_kind = 'source' THEN
        NEW.source_lifecycle := COALESCE(NEW.source_lifecycle, 'active');
        NEW.normalized_pos_status := COALESCE(
            NEW.normalized_pos_status,
            'unresolved'
        );
    ELSE
        NEW.source_lifecycle := NULL;
        NEW.normalized_pos_status := NULL;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: attach_platform_v2_presentation_identity_v1(jsonb, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.attach_platform_v2_presentation_identity_v1(p_payload jsonb, p_user_id uuid, p_catalog boolean) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_entry_ids uuid[];
    v_identity_payload jsonb;
    v_enriched_items jsonb;
    v_item_count integer;
    v_identity_count integer;
BEGIN
    IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object'
       OR jsonb_typeof(p_payload->'items') IS DISTINCT FROM 'array'
       OR jsonb_array_length(p_payload->'items') = 0 THEN
        RETURN p_payload;
    END IF;

    SELECT
        array_agg((item.value->>'id')::uuid ORDER BY item.ordinality),
        count(*)::integer
    INTO v_entry_ids, v_item_count
    FROM jsonb_array_elements(p_payload->'items') WITH ORDINALITY
        AS item(value, ordinality);

    v_identity_payload := public.read_platform_v2_presentation_identity(
        p_user_id,
        v_entry_ids,
        p_catalog
    );

    WITH identity_rows AS MATERIALIZED (
        SELECT identity.value
        FROM jsonb_array_elements(
            COALESCE(v_identity_payload->'entries', '[]'::jsonb)
        ) AS identity(value)
    ),
    enriched AS (
        SELECT
            item.ordinality,
            item.value || jsonb_build_object(
                'platform_v2_identity',
                identity.value
            ) AS value
        FROM jsonb_array_elements(p_payload->'items') WITH ORDINALITY
            AS item(value, ordinality)
        JOIN identity_rows AS identity
          ON identity.value->>'entryId' = item.value->>'id'
    )
    SELECT
        count(*)::integer,
        jsonb_agg(value ORDER BY ordinality)
    INTO v_identity_count, v_enriched_items
    FROM enriched;

    IF v_identity_count <> v_item_count THEN
        RETURN jsonb_build_object(
            'error',
            'presentation_identity_incomplete'
        );
    END IF;

    RETURN jsonb_set(p_payload, '{items}', v_enriched_items, false);
END;
$$;


--
-- Name: author_entry_active_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.author_entry_active_v1(p_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
