$$;


--
-- Name: author_entry_archive_guard_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.author_entry_archive_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
BEGIN
  IF OLD.archived_at IS NOT NULL AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'author_entry_archived' USING ERRCODE='42501';
  END IF;
  IF OLD.archived_at IS NULL AND NEW.archived_at IS NOT NULL THEN
    IF (select auth.uid()) IS NULL OR OLD.management_kind IS DISTINCT FROM 'user' THEN
      RAISE EXCEPTION 'author_entry_archive_forbidden' USING ERRCODE='42501';
    END IF;
    PERFORM public.assert_editable_user_dictionary((select auth.uid()),OLD.dictionary_id);
    IF (to_jsonb(NEW)-'archived_at'-'updated_at'-'content_version') IS DISTINCT FROM (to_jsonb(OLD)-'archived_at'-'updated_at'-'content_version') THEN
      RAISE EXCEPTION 'author_entry_archive_content_changed' USING ERRCODE='22023';
    END IF;
    NEW.archived_at := clock_timestamp();
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: author_entry_content_version_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.author_entry_content_version_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP='INSERT' THEN NEW.content_version:=1;
  ELSIF (to_jsonb(NEW)-'content_version'-'archived_at'-'updated_at') IS DISTINCT FROM
        (to_jsonb(OLD)-'content_version'-'archived_at'-'updated_at') THEN
    NEW.content_version:=OLD.content_version+1;
  ELSE NEW.content_version:=OLD.content_version;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: begin_collection_share_command_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.begin_collection_share_command_v1(p_operation_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); receipt private.collection_sharing_command_receipts%rowtype;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF p_operation_id IS NULL OR p_request IS NULL OR octet_length(p_request::text)>4096 THEN
    RAISE EXCEPTION 'invalid_share_command' USING ERRCODE='22023';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('collection-share-operation:'||principal||':'||p_operation_id,0));
  SELECT * INTO receipt FROM private.collection_sharing_command_receipts r
    WHERE r.user_id=principal AND r.operation_id=p_operation_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF receipt.request_hash<>sha256(convert_to(p_request::text,'UTF8')) THEN
    RAISE EXCEPTION 'share_operation_conflict' USING ERRCODE='22023';
  END IF;
  RETURN private.collection_share_projection_v1(principal,receipt.response);
END;
$$;


--
-- Name: begin_platform_v2_source_import_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.begin_platform_v2_source_import_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF to_regclass('pg_temp.platform_v2_import_refresh_entries') IS NOT NULL THEN
    RAISE EXCEPTION 'platform_v2_source_import_already_started';
  END IF;

  CREATE TEMP TABLE pg_temp.platform_v2_import_refresh_entries (
    entry_id uuid PRIMARY KEY
  ) ON COMMIT DROP;
  CREATE TEMP TABLE pg_temp.platform_v2_import_refresh_groups (
    dictionary_id uuid NOT NULL,
    identity_scheme_version text NOT NULL,
    source_group_key text NOT NULL,
    PRIMARY KEY (dictionary_id, identity_scheme_version, source_group_key)
  ) ON COMMIT DROP;
END;
$$;


--
-- Name: begin_staged_source_import_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.begin_staged_source_import_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  PERFORM private.begin_platform_v2_source_import_v1();
  CREATE TEMP TABLE pg_temp.platform_v2_source_stage (
    payload jsonb NOT NULL
  ) ON COMMIT DROP;
END;
$$;


--
-- Name: broadcast_app_row_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_app_row_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE r jsonb; prior jsonb; principal uuid; resource text; kind text := TG_ARGV[0]; language text;
BEGIN
  r := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
  IF TG_OP = 'UPDATE' THEN
    prior := to_jsonb(OLD);
    IF r = prior THEN RETURN NEW; END IF;
  END IF;
  IF kind = 'translation' THEN
    -- Cache publication covers both durable jobs and synchronous fallback.
    IF r->>'status' NOT IN ('ready','failed') THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND r->>'status' = prior->>'status'
      AND r->>'updated_at' = prior->>'updated_at' THEN RETURN NEW; END IF;
    resource := r->>'word_entry_id'; language := r->>'target_lang';
    kind := 'translation.' || (r->>'status');
    PERFORM private.send_app_event_v1('app:translation:' || resource || ':' || language,
      kind, resource, language, r->>'updated_at');
  ELSIF kind = 'translation-job' THEN
    -- Ready already emits through the cache trigger in the same transaction.
    IF r->>'status' <> 'failed' OR (TG_OP = 'UPDATE' AND prior->>'status' = 'failed') THEN RETURN NEW; END IF;
    resource := r->>'word_entry_id'; language := r->>'target_lang';
    PERFORM private.send_app_event_v1('app:translation:' || resource || ':' || language,
      'translation.failed', resource, language, r->>'updated_at');
  ELSE
    principal := (r->>'user_id')::uuid;
    IF TG_TABLE_NAME = 'user_word_list_items' THEN
      SELECT l.user_id INTO principal FROM public.user_word_lists l WHERE l.id = (r->>'list_id')::uuid;
    END IF;
    -- Parent collection DELETE carries the cascade hint when its rows are gone.
    IF principal IS NOT NULL THEN
      PERFORM private.send_app_event_v1('app:user:' || principal::text, kind,
        CASE WHEN kind = 'account.changed' THEN TG_TABLE_NAME ELSE NULL END, NULL, txid_current()::text);
    END IF;
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $$;


--
-- Name: broadcast_collection_label_catalog_hint_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_collection_label_catalog_hint_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
BEGIN
 PERFORM private.send_app_event_v1('app:user:'||COALESCE(NEW.user_id,OLD.user_id)::text,'collections.changed',NULL,NULL,txid_current()::text);
 RETURN NULL;
END;
$$;


--
-- Name: broadcast_collection_list_hint_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_collection_list_hint_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE root record;
BEGIN
 IF NEW IS NOT DISTINCT FROM OLD THEN RETURN NEW; END IF;
 FOR root IN SELECT r.* FROM private.collection_sharing_roots r WHERE r.collection_id=NEW.id LOOP
  PERFORM private.broadcast_collection_material_hint_v1(root.id,root.owner_user_id,root.access_lifetime,root.is_open);
 END LOOP;
 RETURN NEW;
END;
$$;


--
-- Name: broadcast_collection_material_hint_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_collection_material_hint_v1(p_root uuid, p_owner uuid, p_lifetime uuid, p_open boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE recipient uuid; dedupe text:='app_event.collection_'||md5(p_root::text||':'||p_owner::text||':'||p_lifetime::text||':'||p_open::text);
BEGIN
 -- A whole transaction publishes one domain-wide invalidation per recipient.
 -- Subscription row triggers independently cover newly accepted recipients.
 IF current_setting(dedupe,true)=txid_current()::text THEN RETURN; END IF;
 PERFORM set_config(dedupe,txid_current()::text,true);
 FOR recipient IN
  SELECT p_owner WHERE p_owner IS NOT NULL
  UNION
  SELECT subscription.user_id FROM private.collection_sharing_subscriptions subscription
  WHERE subscription.root_id=p_root AND subscription.is_active
    AND subscription.access_lifetime=p_lifetime AND p_open
 LOOP
  PERFORM private.send_app_event_v1('app:user:'||recipient::text,'collections.changed',NULL,NULL,txid_current()::text);
  PERFORM private.send_app_event_v1('app:user:'||recipient::text,'notes.changed',NULL,NULL,txid_current()::text);
 END LOOP;
END;
$$;


--
-- Name: broadcast_collection_member_hint_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_collection_member_hint_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE lists uuid[]; root record; principal uuid;
BEGIN
 lists:=CASE WHEN TG_OP='INSERT' THEN ARRAY[NEW.list_id] WHEN TG_OP='DELETE' THEN ARRAY[OLD.list_id] ELSE ARRAY[OLD.list_id,NEW.list_id] END;
 FOR principal IN SELECT DISTINCT user_id FROM public.user_word_lists WHERE id=ANY(lists) LOOP
  PERFORM private.send_app_event_v1('app:user:'||principal::text,'collections.changed',NULL,NULL,txid_current()::text);
 END LOOP;
 FOR root IN SELECT r.* FROM private.collection_sharing_roots r WHERE r.collection_id=ANY(lists) LOOP
  PERFORM private.broadcast_collection_material_hint_v1(root.id,root.owner_user_id,root.access_lifetime,root.is_open);
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: broadcast_collection_root_hint_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_collection_root_hint_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  -- BEFORE the FK cascades erase subscriptions. Delivery is commit-bound.
  PERFORM private.broadcast_collection_material_hint_v1(OLD.id,OLD.owner_user_id,OLD.access_lifetime,OLD.is_open);
  RETURN OLD;
 END IF;
 IF TG_OP='INSERT' THEN
  PERFORM private.broadcast_collection_material_hint_v1(NEW.id,NEW.owner_user_id,NEW.access_lifetime,NEW.is_open);
 ELSIF OLD.is_open IS DISTINCT FROM NEW.is_open OR OLD.access_lifetime IS DISTINCT FROM NEW.access_lifetime
   OR OLD.owner_user_id IS DISTINCT FROM NEW.owner_user_id OR OLD.collection_id IS DISTINCT FROM NEW.collection_id THEN
  PERFORM private.broadcast_collection_material_hint_v1(OLD.id,OLD.owner_user_id,OLD.access_lifetime,OLD.is_open);
  PERFORM private.broadcast_collection_material_hint_v1(NEW.id,NEW.owner_user_id,NEW.access_lifetime,NEW.is_open);
 ELSE
  -- Rotating an invitation preserves accepted readers and their note material.
  PERFORM private.send_app_event_v1('app:user:'||NEW.owner_user_id::text,'collections.changed',NULL,NULL,txid_current()::text);
 END IF;
 RETURN NEW;
END;
$$;


--
-- Name: broadcast_collection_subscription_hint_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_collection_subscription_hint_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE row_data private.collection_sharing_subscriptions%rowtype; principal uuid;
BEGIN
 row_data:=CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
 FOR principal IN
  SELECT row_data.user_id UNION SELECT root.owner_user_id FROM private.collection_sharing_roots root WHERE root.id=row_data.root_id
 LOOP
  PERFORM private.send_app_event_v1('app:user:'||principal::text,'collections.changed',NULL,NULL,txid_current()::text);
  PERFORM private.send_app_event_v1('app:user:'||principal::text,'notes.changed',NULL,NULL,txid_current()::text);
 END LOOP;
 IF TG_OP='UPDATE' AND (OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.root_id IS DISTINCT FROM NEW.root_id) THEN
  FOR principal IN SELECT OLD.user_id UNION SELECT root.owner_user_id FROM private.collection_sharing_roots root WHERE root.id=OLD.root_id LOOP
   PERFORM private.send_app_event_v1('app:user:'||principal::text,'collections.changed',NULL,NULL,txid_current()::text);
   PERFORM private.send_app_event_v1('app:user:'||principal::text,'notes.changed',NULL,NULL,txid_current()::text);
  END LOOP;
 END IF;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


--
-- Name: broadcast_entry_note_hint_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_entry_note_hint_v1(p_owner uuid, p_entry uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE recipient uuid;
BEGIN
 FOR recipient IN
  SELECT p_owner WHERE p_owner IS NOT NULL
  UNION
  SELECT scope.user_id FROM private.live_collection_sharing_subscriptions_v1 scope
  JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
  WHERE scope.owner_user_id=p_owner AND item.word_id=p_entry
    AND private.entry_access_v1(scope.user_id,p_entry,'browse')
 LOOP
  -- Deliberately no entry/note/owner/text in payload. Domain-wide coalescing
  -- remains correct when several notes change in the same transaction.
  PERFORM private.send_app_event_v1('app:user:'||recipient::text,'notes.changed',NULL,NULL,txid_current()::text);
 END LOOP;
END;
$$;


--
-- Name: broadcast_entry_note_row_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_entry_note_row_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
BEGIN
 IF TG_OP='DELETE' THEN
  PERFORM private.broadcast_entry_note_hint_v1(OLD.user_id,OLD.word_entry_id);
  RETURN OLD;
 END IF;
 IF TG_OP='UPDATE' AND (OLD.user_id IS DISTINCT FROM NEW.user_id OR OLD.word_entry_id IS DISTINCT FROM NEW.word_entry_id) THEN
  PERFORM private.broadcast_entry_note_hint_v1(OLD.user_id,OLD.word_entry_id);
 END IF;
 PERFORM private.broadcast_entry_note_hint_v1(NEW.user_id,NEW.word_entry_id);
 RETURN NEW;
END;
$$;


--
-- Name: broadcast_shared_entry_material_hint_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.broadcast_shared_entry_material_hint_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE root record;
BEGIN
 IF TG_OP='UPDATE' AND NEW.content_version=OLD.content_version AND NEW.archived_at IS NOT DISTINCT FROM OLD.archived_at THEN RETURN NEW; END IF;
 FOR root IN SELECT r.* FROM public.user_word_list_items item
  JOIN private.collection_sharing_roots r ON r.collection_id=item.list_id WHERE item.word_id=OLD.id LOOP
  PERFORM private.broadcast_collection_material_hint_v1(root.id,root.owner_user_id,root.access_lifetime,root.is_open);
 END LOOP;
 IF TG_OP='DELETE' THEN RETURN OLD; END IF;
 RETURN NEW;
END;
$$;


