$$;


--
-- Name: can_receive_app_event_v1(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.can_receive_app_event_v1(p_topic text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
DECLARE principal uuid := auth.uid(); entry uuid;
BEGIN
  IF principal IS NULL THEN RETURN false; END IF;
  IF p_topic = 'app:releases' OR p_topic = 'app:user:' || principal::text THEN RETURN true; END IF;
  IF p_topic !~ '^app:translation:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}:[a-z]{2,3}(-[a-z0-9]{2,8}){0,3}$' THEN RETURN false; END IF;
  entry := split_part(p_topic, ':', 3)::uuid;
  RETURN EXISTS (SELECT 1 FROM private.active_word_entries w WHERE w.id = entry
    AND public.can_access_dictionary(principal, w.dictionary_id, 'read'));
END $_$;


--
-- Name: claim_inserted_training_session_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.claim_inserted_training_session_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_previous_session_id uuid;
BEGIN
  PERFORM pg_advisory_xact_lock(
    hashtext('training-active-run:' || NEW.user_id::text)
  );
  SELECT session_id INTO v_previous_session_id
  FROM public.training_active_runs
  WHERE user_id = NEW.user_id
  FOR UPDATE;

  IF v_previous_session_id IS NOT NULL
     AND v_previous_session_id IS DISTINCT FROM NEW.id THEN
    UPDATE public.training_sessions
    SET superseded_at = COALESCE(superseded_at, now()),
        superseded_by_session_id = NEW.id
    WHERE id = v_previous_session_id
      AND completed_at IS NULL;
  END IF;

  INSERT INTO public.training_active_runs (user_id, session_id, generation, updated_at)
  VALUES (NEW.user_id, NEW.id, 1, now())
  ON CONFLICT (user_id) DO UPDATE
  SET session_id = EXCLUDED.session_id,
      generation = public.training_active_runs.generation + 1,
      updated_at = EXCLUDED.updated_at;
  RETURN NEW;
END;
$$;


--
-- Name: claim_training_session_start_v1(uuid, text[], uuid, text, text, jsonb, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.claim_training_session_start_v1(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_request_hash text;
  v_receipt public.training_run_start_receipts%rowtype;
  v_latched jsonb;
  v_session_id uuid;
  v_previous_session_id uuid;
  v_generation bigint;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'missing_training_run_start_request_id';
  END IF;

  v_request_hash := encode(digest(jsonb_build_object(
    'modes', COALESCE(p_card_type_ids, ARRAY[]::text[]),
    'listId', p_list_id,
    'listType', p_list_type,
    'filter', p_card_filter,
    'trainingFilter', COALESCE(p_training_filter, '{}'::jsonb),
    'size', p_session_size
  )::text, 'sha256'), 'hex');

  PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));
  SELECT * INTO v_receipt
  FROM public.training_run_start_receipts
  WHERE user_id = p_user_id AND request_id = p_request_id
  FOR UPDATE;
  IF FOUND THEN
    IF v_receipt.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'training_run_start_idempotency_conflict';
    END IF;
    RETURN private.training_session_run_response_v1(p_user_id, v_receipt.session_id);
  END IF;

  v_latched := private.start_training_session_latch_v1(
    p_user_id, p_card_type_ids, p_list_id, p_list_type, p_card_filter,
    p_training_filter, p_session_size
  );
  v_session_id := (v_latched->>'sessionId')::uuid;

  SELECT session_id, generation INTO v_previous_session_id, v_generation
  FROM public.training_active_runs
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_previous_session_id IS DISTINCT FROM v_session_id THEN
    -- The insert trigger normally claims the queue. This fallback only
    -- protects a manually repaired/legacy row that has no trigger state.
    INSERT INTO public.training_active_runs (user_id, session_id, generation, updated_at)
    VALUES (p_user_id, v_session_id, COALESCE(v_generation, 0) + 1, now())
    ON CONFLICT (user_id) DO UPDATE
    SET session_id = EXCLUDED.session_id,
        generation = public.training_active_runs.generation + 1,
        updated_at = EXCLUDED.updated_at;
  END IF;

  INSERT INTO public.training_run_start_receipts (
    user_id, request_id, request_hash, session_id
  ) VALUES (
    p_user_id, p_request_id, v_request_hash, v_session_id
  );

  RETURN private.training_session_run_response_v1(p_user_id, v_session_id);
END;
$$;


--
-- Name: claim_training_session_start_v1(uuid, text[], uuid, text, text, jsonb, text, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.claim_training_session_start_v1(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text, p_request_id uuid, p_new_review_ratio integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_request_hash text;
  v_receipt public.training_run_start_receipts%rowtype;
  v_latched jsonb;
  v_session_id uuid;
  v_previous_session_id uuid;
  v_generation bigint;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF p_request_id IS NULL THEN
    RAISE EXCEPTION 'missing_training_run_start_request_id';
  END IF;

  IF p_card_filter = 'both' AND (
    p_new_review_ratio IS NULL OR p_new_review_ratio NOT BETWEEN 1 AND 5
  ) THEN
    RAISE EXCEPTION 'invalid new/review ratio: %', p_new_review_ratio;
  END IF;

  v_request_hash := encode(digest(jsonb_build_object(
    'modes', COALESCE(p_card_type_ids, ARRAY[]::text[]),
    'listId', p_list_id,
    'listType', p_list_type,
    'filter', p_card_filter,
    'trainingFilter', COALESCE(p_training_filter, '{}'::jsonb),
    'size', p_session_size,
    'newReviewRatio', CASE WHEN p_card_filter = 'both' THEN p_new_review_ratio ELSE 2 END
  )::text, 'sha256'), 'hex');

  PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));
  SELECT * INTO v_receipt
  FROM public.training_run_start_receipts
  WHERE user_id = p_user_id AND request_id = p_request_id
  FOR UPDATE;
  IF FOUND THEN
    IF v_receipt.request_hash <> v_request_hash THEN
      RAISE EXCEPTION 'training_run_start_idempotency_conflict';
    END IF;
    RETURN private.training_session_run_response_v1(p_user_id, v_receipt.session_id);
  END IF;

  v_latched := private.start_training_session_latch_v1(
    p_user_id, p_card_type_ids, p_list_id, p_list_type, p_card_filter,
    p_training_filter, p_session_size,
    CASE WHEN p_card_filter = 'both' THEN p_new_review_ratio ELSE 2 END
  );
  v_session_id := (v_latched->>'sessionId')::uuid;

  SELECT session_id, generation INTO v_previous_session_id, v_generation
  FROM public.training_active_runs
  WHERE user_id = p_user_id
  FOR UPDATE;

  IF v_previous_session_id IS DISTINCT FROM v_session_id THEN
    -- The insert trigger normally claims the queue. This fallback only
    -- protects a manually repaired/legacy row that has no trigger state.
    INSERT INTO public.training_active_runs (user_id, session_id, generation, updated_at)
    VALUES (p_user_id, v_session_id, COALESCE(v_generation, 0) + 1, now())
    ON CONFLICT (user_id) DO UPDATE
    SET session_id = EXCLUDED.session_id,
        generation = public.training_active_runs.generation + 1,
        updated_at = EXCLUDED.updated_at;
  END IF;

  INSERT INTO public.training_run_start_receipts (
    user_id, request_id, request_hash, session_id
  ) VALUES (
    p_user_id, p_request_id, v_request_hash, v_session_id
  );

  RETURN private.training_session_run_response_v1(p_user_id, v_session_id);
END;
$$;


--
-- Name: clean_dictionary_search_groups_v1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.clean_dictionary_search_groups_v1(p_groups jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT COALESCE(jsonb_agg(cleaned_group ORDER BY ord), '[]'::jsonb)
    FROM jsonb_array_elements(COALESCE(p_groups, '[]'::jsonb)) WITH ORDINALITY AS g(group_payload, ord)
    CROSS JOIN LATERAL (
        SELECT CASE
            WHEN jsonb_typeof(g.group_payload->'items') = 'array' THEN
                jsonb_set(
                    g.group_payload,
                    '{items}',
                    (
                        SELECT COALESCE(
                            jsonb_agg(item_payload) FILTER (WHERE item_payload <> 'null'::jsonb),
                            '[]'::jsonb
                        )
                        FROM jsonb_array_elements(g.group_payload->'items') AS items(item_payload)
                    ),
                    false
                )
            ELSE g.group_payload
        END AS cleaned_group
    ) cleaned;
$$;


--
-- Name: collection_copy_admission_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collection_copy_admission_v1(p_user_id uuid, p_list_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE entries uuid[]; dictionary_ids uuid[]; owners uuid[]; roots uuid[]; member_count integer; author uuid; root record;
BEGIN
 IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 BEGIN
  PERFORM id FROM auth.users WHERE id=p_user_id FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  -- A point copy holds its source before this mutex. Never wait in reverse order.
  IF NOT pg_try_advisory_xact_lock(hashtextextended('independent-copy-recipient:'||p_user_id,0)) THEN
   RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  PERFORM id FROM public.user_word_lists WHERE id=p_list_id AND user_id=p_user_id FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'collection_unavailable' USING ERRCODE='42501'; END IF;
  SELECT count(*) INTO member_count FROM (SELECT 1 FROM public.user_word_list_items WHERE list_id=p_list_id LIMIT 5001) bounded;
  IF member_count>5000 THEN RAISE EXCEPTION 'copy_collection_too_large' USING ERRCODE='22023'; END IF;
  PERFORM word_id FROM public.user_word_list_items WHERE list_id=p_list_id ORDER BY word_id FOR UPDATE NOWAIT;
  SELECT COALESCE(array_agg(entry.id ORDER BY entry.id),'{}'::uuid[]) INTO entries
   FROM public.user_word_list_items item JOIN public.word_entries entry ON entry.id=item.word_id
   JOIN public.dictionaries dictionary ON dictionary.id=entry.dictionary_id
   WHERE item.list_id=p_list_id AND dictionary.kind='user' AND dictionary.owner_user_id IS DISTINCT FROM p_user_id;
  IF cardinality(entries)>50 THEN RAISE EXCEPTION 'copy_collection_too_large' USING ERRCODE='22023'; END IF;
  SELECT COALESCE(array_agg(DISTINCT dictionary_id ORDER BY dictionary_id),'{}'::uuid[]) INTO dictionary_ids
   FROM public.word_entries WHERE id=ANY(entries);
  SELECT COALESCE(array_agg(DISTINCT scope.root_id ORDER BY scope.root_id),'{}'::uuid[]) INTO roots
   FROM private.live_collection_sharing_subscriptions_v1 scope JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
   WHERE scope.user_id=p_user_id AND item.word_id=ANY(entries);
  IF cardinality(roots)>1000 THEN RAISE EXCEPTION 'copy_collection_too_large' USING ERRCODE='22023'; END IF;
  SELECT array_agg(id ORDER BY id) INTO owners FROM(
   SELECT p_user_id id UNION SELECT owner_user_id FROM public.dictionaries WHERE id=ANY(dictionary_ids) AND owner_user_id IS NOT NULL
   UNION SELECT owner_user_id FROM private.collection_sharing_roots WHERE id=ANY(roots)
  ) authors;
  PERFORM id FROM auth.users WHERE id=ANY(owners) ORDER BY id FOR KEY SHARE NOWAIT;
  IF (SELECT count(*) FROM auth.users WHERE id=ANY(owners))<>cardinality(owners) THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
  PERFORM id FROM public.dictionaries WHERE id=ANY(dictionary_ids) ORDER BY id FOR KEY SHARE NOWAIT;
  -- Membership writes acquire exclusive author admission. Pre-admit every
  -- participating author without waiting while list/member rows are held.
  FOREACH author IN ARRAY owners LOOP
   IF NOT pg_try_advisory_xact_lock(hashtextextended('collection-author-scope:'||author::text,0)) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
   END IF;
  END LOOP;
  FOR root IN SELECT r.id,r.owner_user_id FROM private.collection_sharing_roots r
   WHERE r.id=ANY(roots) OR r.collection_id=p_list_id ORDER BY r.id LOOP
   IF root.owner_user_id=p_user_id THEN
    PERFORM id FROM private.collection_sharing_roots WHERE id=root.id FOR UPDATE NOWAIT;
   ELSE
    PERFORM id FROM private.collection_sharing_roots WHERE id=root.id FOR SHARE NOWAIT;
   END IF;
  END LOOP;
  PERFORM id FROM public.word_entries WHERE id=ANY(entries) ORDER BY id FOR UPDATE NOWAIT;
 EXCEPTION WHEN lock_not_available THEN
  RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
 END;
 RETURN jsonb_build_object('entries',entries,'dictionaries',dictionary_ids,'owners',owners,'roots',roots);
END;
$$;


--
-- Name: collection_copy_plan_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collection_copy_plan_v1(p_user_id uuid, p_list_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE cohort jsonb; candidates jsonb:='[]'; item uuid; snapshot jsonb; available boolean:=true;
 digest text; revision text; total_bytes integer:=0;
BEGIN
 cohort:=private.collection_copy_admission_v1(p_user_id,p_list_id);
 digest:=private.collection_membership_digest_v1(p_list_id);
 FOR item IN SELECT value::uuid FROM jsonb_array_elements_text(cohort->'entries') ORDER BY value LOOP
  BEGIN
   snapshot:=private.independent_copy_snapshot_in_cohort_v1(p_user_id,item,cohort);
   total_bytes:=total_bytes+octet_length((snapshot->'content')::text);
   IF total_bytes>1048576 THEN RAISE EXCEPTION 'copy_collection_too_large' USING ERRCODE='22023'; END IF;
   candidates:=candidates||jsonb_build_array(jsonb_build_object('entryId',item,'revision',snapshot->>'revision','snapshot',snapshot));
  EXCEPTION WHEN SQLSTATE '42501' THEN
   available:=false;
   candidates:=candidates||jsonb_build_array(jsonb_build_object('entryId',item,'unavailable',true));
  END;
 END LOOP;
 -- Internal snapshots never leave the private plan. Hash the complete provided
 -- text/token; public preview exposes only counts, availability and revision.
 revision:=encode(sha256(convert_to(jsonb_build_object('membership',digest,'sources',candidates)::text,'UTF8')),'hex');
 RETURN jsonb_build_object('listId',p_list_id,'revision',revision,'membershipDigest',digest,
  'candidates',candidates,'canCopy',available,'borrowedCount',jsonb_array_length(candidates));
EXCEPTION WHEN lock_not_available THEN
 RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
END;
$$;


--
-- Name: collection_labels_before_collection_delete_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collection_labels_before_collection_delete_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE v_revision integer;
BEGIN
    IF EXISTS (SELECT 1 FROM private.collection_label_assignments
               WHERE user_id = OLD.user_id AND collection_id = OLD.id) THEN
        SELECT revision INTO v_revision FROM private.collection_label_catalogs
        WHERE user_id = OLD.user_id FOR UPDATE;
        -- Account deletion may already have removed its catalog by cascade.
        IF FOUND THEN
            IF v_revision >= 2147483646 THEN RAISE EXCEPTION 'label_catalog_limit'; END IF;
            UPDATE private.collection_label_catalogs SET revision = revision + 1 WHERE user_id = OLD.user_id;
        END IF;
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: collection_membership_digest_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collection_membership_digest_v1(p_list_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
 SELECT encode(sha256(convert_to(COALESCE(jsonb_agg(word_id ORDER BY word_id),'[]'::jsonb)::text,'UTF8')),'hex')
 FROM public.user_word_list_items WHERE list_id=p_list_id;
$$;


--
-- Name: collection_share_command_core_v1(uuid, text, uuid, integer, text, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collection_share_command_core_v1(p_operation_id uuid, p_action text, p_collection_id uuid DEFAULT NULL::uuid, p_expected_revision integer DEFAULT NULL::integer, p_code text DEFAULT NULL::text, p_reconcile_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE principal uuid:=(select auth.uid()); request jsonb; replay jsonb; result jsonb;
BEGIN
 IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF p_reconcile_only IS NULL OR p_operation_id IS NULL OR p_action IS NULL OR p_action NOT IN('open','rotate','close','accept','unsubscribe') OR
  (p_action IN('open','rotate','close') AND (p_collection_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision NOT BETWEEN 0 AND 2147483645 OR p_code IS NOT NULL)) OR
  (p_action='accept' AND (p_collection_id IS NOT NULL OR p_expected_revision IS NOT NULL OR p_code IS NULL OR p_code !~ '^[0-9A-HJKMNP-TV-Z]{26}$')) OR
  (p_action='unsubscribe' AND (p_collection_id IS NULL OR p_expected_revision IS NOT NULL OR p_code IS NOT NULL)) THEN
  RAISE EXCEPTION 'invalid_share_command' USING ERRCODE='22023';
 END IF;
 PERFORM 1 FROM auth.users WHERE id=principal FOR KEY SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 request:=CASE p_action WHEN 'accept' THEN jsonb_build_object('action','accept','code',p_code)
  WHEN 'unsubscribe' THEN jsonb_build_object('action','unsubscribe','collectionId',p_collection_id)
  ELSE jsonb_build_object('action',p_action,'collectionId',p_collection_id,'expectedRevision',p_expected_revision) END;
 replay:=private.begin_collection_share_command_v1(p_operation_id,request);
 IF replay IS NOT NULL THEN RETURN private.collection_share_command_response_v1(replay); END IF;
 IF p_reconcile_only THEN RETURN jsonb_build_object('operationId',p_operation_id,'status','unknown'); END IF;
 IF p_action NOT IN('close','unsubscribe') THEN PERFORM private.require_collection_sharing_writes_v1(); END IF;
 result:=CASE p_action WHEN 'accept' THEN private.accept_collection_share_v1(p_operation_id,p_code)
  WHEN 'unsubscribe' THEN private.unsubscribe_collection_share_v1(p_operation_id,p_collection_id)
  ELSE private.mutate_collection_share_v1(p_operation_id,p_action,p_collection_id,p_expected_revision) END;
 RETURN private.collection_share_command_response_v1(result);
END;
$_$;


--
-- Name: collection_share_command_response_v1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collection_share_command_response_v1(p_state jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
 SELECT CASE WHEN p_state->>'status'='unknown' THEN jsonb_build_object('operationId',p_state->'operationId','status','unknown')
 ELSE jsonb_build_object('operationId',p_state->'operationId','status','committed','action',p_state->'action',
  'collectionId',p_state->'collectionId','available',p_state->'available','role',p_state->'role') ||
  CASE WHEN p_state->>'role'='owner' AND (p_state->>'available')::boolean THEN jsonb_build_object(
   'isOpen',p_state->'isOpen','revision',p_state->'revision','invitationCode',p_state->'invitationCode') ELSE '{}'::jsonb END END
$$;


--
-- Name: collection_share_projection_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.collection_share_projection_v1(p_user_id uuid, p_facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE root private.collection_sharing_roots%rowtype; code text; available boolean;
BEGIN
  SELECT * INTO root FROM private.collection_sharing_roots r WHERE r.id=(p_facts->>'rootId')::uuid;
  IF NOT FOUND THEN RETURN p_facts||jsonb_build_object('available',false,'role',NULL); END IF;
  IF root.owner_user_id=p_user_id THEN
    SELECT i.code INTO code FROM private.collection_sharing_invitations i
      WHERE i.root_id=root.id AND i.role='viewer' AND root.is_open;
    RETURN p_facts||jsonb_build_object('available',true,'role','owner',
      'isOpen',root.is_open,'revision',root.revision,'invitationCode',code);
  END IF;
  available:=root.is_open AND EXISTS(
    SELECT 1 FROM private.collection_sharing_subscriptions s
    WHERE s.user_id=p_user_id AND s.root_id=root.id AND s.is_active
      AND s.access_lifetime=root.access_lifetime);
  RETURN p_facts||jsonb_build_object('available',available,'role',CASE WHEN available THEN 'viewer' END);
END;
$$;


--
-- Name: commit_collection_copy_plan_v1(uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commit_collection_copy_plan_v1(p_user_id uuid, p_operation_id uuid, p_list_id uuid, p_expected_revision text, p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE item jsonb; copied jsonb; count_copied integer:=0;
BEGIN
 IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF p_plan->>'revision' IS DISTINCT FROM p_expected_revision OR p_plan->>'canCopy' IS DISTINCT FROM 'true'
    OR p_plan->>'listId' IS DISTINCT FROM p_list_id::text THEN
  RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('independent-copy-recipient:'||p_user_id,0));
 PERFORM 1 FROM public.user_word_lists WHERE id=p_list_id AND user_id=p_user_id FOR UPDATE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'collection_unavailable' USING ERRCODE='42501'; END IF;
 -- Parent UPDATE blocks FK insertion. Existing rows are locked before the final
 -- membership check, so concurrent removal either precedes it or waits to commit.
 PERFORM 1 FROM public.user_word_list_items WHERE list_id=p_list_id ORDER BY word_id FOR UPDATE NOWAIT;
 IF private.collection_membership_digest_v1(p_list_id) IS DISTINCT FROM p_plan->>'membershipDigest' THEN
  RAISE EXCEPTION 'copy_collection_changed' USING ERRCODE='40001';
 END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(p_plan->'candidates') ORDER BY value->>'entryId' LOOP
  IF NOT EXISTS(SELECT 1 FROM public.user_word_list_items WHERE list_id=p_list_id AND word_id=(item->>'entryId')::uuid) THEN
   RAISE EXCEPTION 'copy_collection_changed' USING ERRCODE='40001';
  END IF;
  copied:=private.commit_independent_copy_snapshot_v1(
    p_user_id,gen_random_uuid(),(item->>'entryId')::uuid,item->>'revision',NULL,true,item->'snapshot');
  UPDATE public.user_word_list_items SET word_id=(copied->>'entryId')::uuid
    WHERE list_id=p_list_id AND word_id=(item->>'entryId')::uuid;
  count_copied:=count_copied+1;
 END LOOP;
 INSERT INTO private.collection_copy_receipts(user_id,operation_id,list_id,expected_revision,copied_count)
  VALUES(p_user_id,p_operation_id,p_list_id,p_expected_revision,count_copied);
 RETURN jsonb_build_object('operationId',p_operation_id,'listId',p_list_id,'status','completed','copiedCount',count_copied);
END;
$$;


--
-- Name: commit_independent_copy_snapshot_v1(uuid, uuid, uuid, text, uuid, boolean, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.commit_independent_copy_snapshot_v1(principal uuid, p_operation_id uuid, p_source_entry_id uuid, p_expected_revision text, p_target_dictionary_id uuid, p_include_shared_material boolean, snapshot jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
 DECLARE payload jsonb; target public.dictionaries%rowtype; target_id uuid; entry_id uuid; next_meaning integer;
 BEGIN
  IF principal IS DISTINCT FROM (select auth.uid()) THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF snapshot->>'revision' IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
   payload:=snapshot->'content';
  -- Entry lock precedes recipient dictionary allocation, consistently with the
  -- legacy command. Different intentional copies get fresh identities.
  PERFORM pg_advisory_xact_lock(hashtextextended('independent-copy-recipient:'||principal,0));
  target_id:=p_target_dictionary_id;
  IF target_id IS NULL THEN
    IF p_include_shared_material THEN
      BEGIN
      SELECT id INTO target_id FROM public.dictionaries
        WHERE language_code=payload->>'languageCode' AND slug='user-'||replace(principal::text,'-','')||'-'||(payload->>'languageCode')
        FOR KEY SHARE NOWAIT;
      EXCEPTION WHEN lock_not_available THEN
        RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
      END;
      IF target_id IS NULL THEN
        -- The legacy allocator can wait on an uncommitted unique-key insertion.
        -- Bound that wait locally; restore the caller setting on both paths.
        DECLARE prior_timeout text:=current_setting('lock_timeout');
        BEGIN
          PERFORM set_config('lock_timeout','1ms',true);
          target_id:=public.ensure_user_dictionary(principal,payload->>'languageCode','My dictionary');
          PERFORM set_config('lock_timeout',prior_timeout,true);
        EXCEPTION WHEN lock_not_available THEN
          RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
        END;
      END IF;
    ELSE
      target_id:=public.ensure_user_dictionary(principal,payload->>'languageCode','My dictionary');
    END IF;
  END IF;
  IF p_include_shared_material THEN
    BEGIN
      PERFORM id FROM public.dictionaries WHERE id=target_id AND owner_user_id=principal AND kind='user' FOR KEY SHARE NOWAIT;
      IF NOT FOUND THEN RAISE EXCEPTION 'target_dictionary_not_editable' USING ERRCODE='42501'; END IF;
    EXCEPTION WHEN lock_not_available THEN
      RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
    END;
  END IF;
  target:=public.assert_editable_user_dictionary(principal,target_id);
  IF target.language_code IS DISTINCT FROM payload->>'languageCode' THEN
    RAISE EXCEPTION 'language_mismatch' USING ERRCODE='22023';
  END IF;
  SELECT COALESCE(max(meaning_id),0)+1 INTO next_meaning FROM public.word_entries
    WHERE dictionary_id=target_id AND language_code=payload->>'languageCode'
      AND headword=payload->>'headword' AND management_kind='user';
  INSERT INTO public.word_entries(dictionary_id,language_code,headword,meaning_id,part_of_speech,gender,is_nt2_2000,raw,management_kind)
    VALUES(target_id,payload->>'languageCode',payload->>'headword',next_meaning,
      payload->>'partOfSpeech',payload->>'gender',false,payload,'user') RETURNING id INTO entry_id;
  INSERT INTO private.independent_entry_copy_receipts(user_id,operation_id,source_entry_id,
    requested_dictionary_id,expected_revision,copied_entry_id,dictionary_id,headword,language_code)
    VALUES(principal,p_operation_id,p_source_entry_id,p_target_dictionary_id,p_expected_revision,entry_id,target_id,payload->>'headword',payload->>'languageCode');
  RETURN jsonb_build_object('operationId',p_operation_id,'entryId',entry_id,'dictionaryId',target_id,'headword',payload->>'headword','languageCode',payload->>'languageCode','status','completed');
END;
$$;


--
-- Name: consume_platform_v2_training_exercise_session_member_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.consume_platform_v2_training_exercise_session_member_v1(p_user_id uuid, p_session_id uuid, p_target_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_session public.training_sessions%rowtype;
    v_member public.training_session_exercise_members%rowtype;
    v_expected public.training_session_exercise_members%rowtype;
    v_completed integer;
    v_remaining integer;
    v_now timestamptz := private.training_reference_now_v1();
BEGIN
    SELECT * INTO v_session
      FROM public.training_sessions
     WHERE id = p_session_id AND user_id = p_user_id
     FOR UPDATE;
    IF NOT FOUND OR v_session.exercise_family NOT IN ('idiom', 'translation') THEN
        RAISE EXCEPTION 'training_exercise_session_family_mismatch';
    END IF;
    IF v_session.completed_at IS NOT NULL THEN
        RAISE EXCEPTION 'training_exercise_session_completed';
    END IF;

    SELECT * INTO v_member
      FROM public.training_session_exercise_members
     WHERE session_id = p_session_id AND target_id = p_target_id
     FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'training_exercise_session_member_missing'; END IF;
    IF v_member.consumed_at IS NOT NULL THEN RAISE EXCEPTION 'training_exercise_session_member_already_consumed'; END IF;
    IF v_member.unavailable_at IS NOT NULL THEN RAISE EXCEPTION 'training_exercise_session_member_unavailable'; END IF;

    SELECT * INTO v_expected
      FROM public.training_session_exercise_members
     WHERE session_id = p_session_id
       AND consumed_at IS NULL
       AND unavailable_at IS NULL
     ORDER BY ordinal LIMIT 1;
    IF NOT FOUND OR v_expected.target_id IS DISTINCT FROM v_member.target_id THEN
        RAISE EXCEPTION 'training_exercise_session_member_out_of_order';
    END IF;

    UPDATE public.training_session_exercise_members
       SET consumed_at = v_now
     WHERE session_id = p_session_id AND target_id = p_target_id;
    SELECT count(*) FILTER (WHERE consumed_at IS NOT NULL)::integer,
           count(*) FILTER (WHERE consumed_at IS NULL AND unavailable_at IS NULL)::integer
      INTO v_completed, v_remaining
      FROM public.training_session_exercise_members
     WHERE session_id = p_session_id;

    IF v_completed >= v_session.requested_total OR v_remaining = 0 THEN
        UPDATE public.training_sessions
           SET completed_at = COALESCE(completed_at, v_now),
               exhausted_at = CASE WHEN v_completed < v_session.requested_total
                   THEN COALESCE(exhausted_at, v_now) ELSE exhausted_at END,
               completion_reason = CASE WHEN v_completed >= v_session.requested_total
                   THEN 'completed' ELSE 'exhausted' END
         WHERE id = p_session_id;
    END IF;
    RETURN jsonb_build_object(
        'status', CASE WHEN v_completed >= v_session.requested_total OR v_remaining = 0
            THEN 'consumed-complete' ELSE 'consumed' END,
        'ordinal', v_member.ordinal,
        'remaining', v_remaining,
        'completedActions', v_completed,
        'requestedTotal', v_session.requested_total
    );
END;
$$;


--
-- Name: consume_training_session_member(uuid, uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.consume_training_session_member(p_user_id uuid, p_session_id uuid, p_entry_id uuid, p_card_type_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_member public.training_session_members%rowtype;
  v_expected_member public.training_session_members%rowtype;
  v_requested_total integer;
  v_completed_at timestamptz;
  v_remaining integer;
  v_completed_actions integer;
  v_status text;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;

  SELECT session.requested_total, session.completed_at
  INTO v_requested_total, v_completed_at
  FROM public.training_sessions session
  WHERE session.id = p_session_id AND session.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not-member'); END IF;

  SELECT member.* INTO v_member
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.entry_id = p_entry_id
    AND member.card_type_id = p_card_type_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not-member'); END IF;
  IF v_member.consumed_at IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'duplicate', 'ordinal', v_member.ordinal);
  END IF;
  IF v_member.unavailable_at IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'unavailable', 'ordinal', v_member.ordinal);
  END IF;
  IF v_completed_at IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'completed', 'ordinal', v_member.ordinal);
  END IF;

  SELECT member.* INTO v_expected_member
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.consumed_at IS NULL
    AND member.unavailable_at IS NULL
  ORDER BY member.ordinal
  LIMIT 1;
  IF NOT FOUND
     OR v_expected_member.entry_id IS DISTINCT FROM v_member.entry_id
     OR v_expected_member.card_type_id IS DISTINCT FROM v_member.card_type_id THEN
    RETURN jsonb_build_object(
      'status', 'out-of-order',
      'ordinal', v_member.ordinal,
      'expectedOrdinal', v_expected_member.ordinal
    );
  END IF;

  UPDATE public.training_session_members
  SET consumed_at = private.training_reference_now_v1()
  WHERE session_id = v_member.session_id
    AND entry_id = v_member.entry_id
    AND card_type_id = v_member.card_type_id;

  SELECT (count(*) FILTER (WHERE member.consumed_at IS NULL AND member.unavailable_at IS NULL))::integer,
    (count(*) FILTER (WHERE member.consumed_at IS NOT NULL))::integer
  INTO v_remaining, v_completed_actions
  FROM public.training_session_members member
  WHERE member.session_id = v_member.session_id;

  IF v_completed_actions >= v_requested_total THEN
    UPDATE public.training_sessions
    SET completed_at = COALESCE(completed_at, private.training_reference_now_v1()),
        completion_reason = COALESCE(completion_reason, 'completed')
    WHERE id = v_member.session_id;
    v_status := 'consumed-complete';
  ELSIF v_remaining = 0 THEN
    UPDATE public.training_sessions
    SET completed_at = COALESCE(completed_at, private.training_reference_now_v1()),
        exhausted_at = COALESCE(exhausted_at, private.training_reference_now_v1()),
        completion_reason = COALESCE(completion_reason, 'exhausted')
    WHERE id = v_member.session_id;
    -- The caller accepts the same terminal completion status for a normal
    -- budget finish and for an exhausted pool; the persisted reason tells
    -- the UI which completion screen to show.
    v_status := 'consumed-complete';
  ELSE
    v_status := 'consumed';
  END IF;

  RETURN jsonb_build_object(
    'status', v_status,
    'ordinal', v_member.ordinal,
    'remaining', v_remaining,
    'completedActions', v_completed_actions,
    'requestedTotal', v_requested_total
  );
END;
$$;


--
-- Name: copy_independent_entry_core_v1(uuid, uuid, text, uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copy_independent_entry_core_v1(p_operation_id uuid, p_source_entry_id uuid, p_expected_revision text, p_target_dictionary_id uuid DEFAULT NULL::uuid, p_include_shared_material boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE principal uuid:=(select auth.uid()); snapshot jsonb; payload jsonb;
  receipt private.independent_entry_copy_receipts%rowtype;
  target public.dictionaries%rowtype; target_id uuid; entry_id uuid; next_meaning integer;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF p_operation_id IS NULL OR p_source_entry_id IS NULL OR p_expected_revision IS NULL
     OR p_expected_revision !~ '^[a-f0-9]{64}$' THEN
    RAISE EXCEPTION 'invalid_copy_request' USING ERRCODE='22023';
  END IF;
  -- Serialize the same operation before checking its receipt; replay does not
  -- require the source to remain readable or even present.
  PERFORM pg_advisory_xact_lock(hashtextextended('independent-copy-operation:'||principal||':'||p_operation_id,0));
  SELECT * INTO receipt FROM private.independent_entry_copy_receipts
    WHERE user_id=principal AND operation_id=p_operation_id;
  IF FOUND THEN
    IF receipt.source_entry_id IS DISTINCT FROM p_source_entry_id OR
       receipt.requested_dictionary_id IS DISTINCT FROM p_target_dictionary_id OR
       receipt.expected_revision IS DISTINCT FROM p_expected_revision THEN
      RAISE EXCEPTION 'copy_operation_conflict' USING ERRCODE='22023';
    END IF;
    RETURN jsonb_build_object('operationId',p_operation_id,'entryId',receipt.copied_entry_id,'dictionaryId',receipt.dictionary_id,'headword',receipt.headword,'languageCode',receipt.language_code,'status','completed');
  END IF;
  IF p_include_shared_material THEN
    snapshot:=private.independent_copy_snapshot_with_notes_v1(principal,p_source_entry_id);
  ELSE
    snapshot:=private.independent_copy_snapshot_v1(principal,p_source_entry_id);
  END IF;
  IF snapshot->>'revision' IS DISTINCT FROM p_expected_revision THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  RETURN private.commit_independent_copy_snapshot_v1(principal,p_operation_id,p_source_entry_id,p_expected_revision,p_target_dictionary_id,p_include_shared_material,snapshot);
END;
$_$;


--
-- Name: copy_instructional_json_v1(jsonb, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copy_instructional_json_v1(p_value jsonb, p_depth integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE item jsonb; key text;
BEGIN
  IF p_depth > 4 OR octet_length(p_value::text) > 131072 THEN
    RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023';
  END IF;
  CASE jsonb_typeof(p_value)
    WHEN 'string' THEN
      IF octet_length(p_value #>> '{}') > 16384 THEN
        RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023';
      END IF;
    WHEN 'array' THEN
      IF jsonb_array_length(p_value)>1000 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
      FOR item IN SELECT value FROM jsonb_array_elements(p_value) LOOP
        PERFORM private.copy_instructional_json_v1(item,p_depth+1);
      END LOOP;
    WHEN 'object' THEN
      IF (SELECT count(*) FROM jsonb_object_keys(p_value))>100 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
      FOR key,item IN SELECT * FROM jsonb_each(p_value) LOOP
        IF length(key)>80 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
        PERFORM private.copy_instructional_json_v1(item,p_depth+1);
      END LOOP;
    WHEN 'number', 'boolean', 'null' THEN NULL;
    ELSE RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
  END CASE;
  RETURN p_value;
END;
$$;


--
-- Name: copy_legacy_owned_entry_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copy_legacy_owned_entry_v1(p_user_id uuid, p_source_entry_id uuid, p_target_dictionary_id uuid DEFAULT NULL::uuid, p_overrides jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_source word_entries%rowtype;
    v_target_dictionary dictionaries%rowtype;
    v_target_dictionary_id uuid;
    v_payload jsonb;
    v_headword text;
    v_language_code text;
    v_part_of_speech text;
    v_gender text;
    v_copied_entry_id uuid;
    v_portable jsonb;
    v_note text;
    v_next_meaning integer;
BEGIN
    IF (select auth.uid()) IS NULL
       OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    SELECT * INTO v_source
    FROM private.active_word_entries
    WHERE id = p_source_entry_id FOR UPDATE;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'entry_not_found';
    END IF;

    IF v_source.dictionary_id IS NOT NULL
       AND NOT can_browse_dictionary(
           p_user_id,
           v_source.dictionary_id,
           'read'
       ) THEN
        RAISE EXCEPTION 'entry_not_accessible';
    END IF;

    SELECT notes INTO v_note FROM public.user_word_notes
      WHERE user_id=p_user_id AND word_entry_id=p_source_entry_id FOR SHARE;
    v_portable:=private.copy_source_content_v1(CASE WHEN v_source.raw ? 'meanings' THEN private.merge_owned_entry_edit_v1(v_source.raw,COALESCE(p_overrides,'{}'::jsonb)) ELSE v_source.raw||COALESCE(p_overrides,'{}'::jsonb) END,v_note,(SELECT kind FROM public.dictionaries WHERE id=v_source.dictionary_id));
    PERFORM pg_advisory_xact_lock(hashtextextended('independent-copy-recipient:'||p_user_id,0));
    v_target_dictionary_id := COALESCE(
        p_target_dictionary_id,
        ensure_user_dictionary(
            p_user_id,
            v_source.language_code,
            'My dictionary'
        )
    );

    SELECT * INTO v_target_dictionary
    FROM dictionaries
    WHERE id = v_target_dictionary_id;
    IF NOT FOUND
       OR v_target_dictionary.kind <> 'user'
       OR v_target_dictionary.owner_user_id <> p_user_id
       OR NOT v_target_dictionary.is_editable
       OR v_target_dictionary.schema_key <> 'user-entry-v1'
       OR v_target_dictionary.schema_version <> 1 THEN
        RAISE EXCEPTION 'target_dictionary_not_editable';
    END IF;

    v_payload := jsonb_strip_nulls(jsonb_build_object(
        'headword', v_source.headword,
        'languageCode', v_source.language_code,
        'definition', COALESCE(
            NULLIF(p_overrides->>'definition', ''),
            NULLIF(v_source.raw#>>'{meanings,0,definition}', ''),
            NULLIF(v_source.raw#>>'{definition}', '')
        ),
        'partOfSpeech', v_source.part_of_speech,
        'gender', v_source.gender,
        'notes', NULLIF(p_overrides->>'notes', ''),
        'sourceEntryId', v_source.id::text
    )) || COALESCE(p_overrides, '{}'::jsonb);

    v_payload:=public.validate_user_entry_v1_payload(v_payload||v_portable,v_source.language_code);
    v_headword := NULLIF(v_payload->>'headword', '');
    v_language_code := NULLIF(v_payload->>'languageCode', '');
    v_part_of_speech := NULLIF(v_payload->>'partOfSpeech', '');
    v_gender := NULLIF(v_payload->>'gender', '');

    IF v_headword IS NULL OR v_language_code IS NULL THEN
        RAISE EXCEPTION 'invalid_user_entry';
    END IF;
    IF NOT (
        v_payload ? 'definition'
        OR v_payload ? 'translation'
        OR v_payload ? 'example'
        OR v_payload ? 'notes'
    ) THEN
        RAISE EXCEPTION 'invalid_user_entry';
    END IF;
    IF NOT EXISTS (
        SELECT 1 FROM languages WHERE code = v_language_code
    ) THEN
        RAISE EXCEPTION 'language_not_found';
    END IF;
    IF v_language_code <> v_target_dictionary.language_code THEN
        RAISE EXCEPTION 'language_mismatch';
    END IF;

    SELECT COALESCE(max(meaning_id),0)+1 INTO v_next_meaning FROM public.word_entries
      WHERE dictionary_id=v_target_dictionary_id AND language_code=v_language_code
        AND headword=v_headword AND management_kind='user';
    INSERT INTO word_entries (
        dictionary_id,
        language_code,
        headword,
        meaning_id,
        part_of_speech,
        gender,
        is_nt2_2000,
        raw,
        management_kind
    )
    VALUES (
        v_target_dictionary_id,
        v_language_code,
        v_headword,
        v_next_meaning,
        v_part_of_speech,
        v_gender,
        false,
        v_payload,
        'user'
    )
    RETURNING id INTO v_copied_entry_id;

    RETURN v_copied_entry_id;
END;
$$;


--
-- Name: copy_source_content_v1(jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copy_source_content_v1(p_raw jsonb, p_overlay_note text, p_dictionary_kind text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $$
DECLARE projected jsonb; source_meanings jsonb;
BEGIN
 BEGIN
  projected:=private.portable_owned_entry_content_v1(p_raw);
 EXCEPTION WHEN SQLSTATE '22023' THEN
  IF SQLERRM<>'copy_content_unsupported' THEN RAISE; END IF;
 END;
 SELECT COALESCE(jsonb_agg(CASE WHEN item->'definition' IS NULL OR item->'definition'='null'::jsonb
   THEN item||jsonb_build_object('definition',item->'text') ELSE item END),'[]'::jsonb)
 INTO source_meanings FROM jsonb_array_elements(COALESCE(p_raw->'meanings','[]')) item;
 -- Curated readers use root notes as a definition only when no rich sections
 -- exist. Owned rich entries instead treat their root notes as an owned note.
 IF p_dictionary_kind IS DISTINCT FROM 'user'
   AND NULLIF(trim(p_raw->>'definition'),'') IS NULL
   AND NULLIF(trim(p_raw->>'notes'),'') IS NOT NULL
   AND jsonb_array_length(private.platform_v2_user_entry_content_nodes(jsonb_build_object('meanings',source_meanings)))=0
   AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(COALESCE(p_raw->'meanings','[]')) item WHERE NULLIF(trim(item->>'note'),'') IS NOT NULL) THEN
  RETURN private.portable_owned_entry_content_v1((p_raw-'notes')||jsonb_build_object('definition',p_raw->>'notes'),p_overlay_note);
 END IF;
 IF projected IS NULL THEN RAISE EXCEPTION 'copy_content_unsupported' USING ERRCODE='22023'; END IF;
 IF NULLIF(p_overlay_note,'') IS NULL THEN RETURN projected; END IF;
 RETURN private.portable_owned_entry_content_v1(p_raw,p_overlay_note);
END;
$$;


--
-- Name: copy_text_array_v1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.copy_text_array_v1(p_value jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_value IS NULL OR p_value='null'::jsonb THEN RETURN '[]'::jsonb; END IF;
  IF jsonb_typeof(p_value)<>'array' OR EXISTS(
    SELECT 1 FROM jsonb_array_elements(p_value) item WHERE jsonb_typeof(item)<>'string'
  ) THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
  RETURN private.copy_instructional_json_v1(p_value);
END;
$$;


--
-- Name: current_training_entry_permitted_v1(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_entry_permitted_v1(p_user_id uuid, p_entry_id uuid, p_card_type_id text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT EXISTS(SELECT 1 FROM private.training_current_card_permits permit
    WHERE permit.user_id=p_user_id AND permit.entry_id=p_entry_id
      AND (p_card_type_id IS NULL OR permit.card_type_id=p_card_type_id)
      AND private.current_training_permit_valid_v1(permit));
$$;


--
-- Name: current_training_handle_card_review_v1(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_handle_card_review_v1(p_user_id uuid, p_entry_id uuid, p_card_type_id text, p_result text, p_turn_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
    v_status user_card_status%rowtype;
    v_grade smallint;
    v_params numeric[];
    v_target numeric;
    v_compute jsonb;
    v_review_type text;
    v_scheduled timestamptz;
    v_interval numeric;
    v_meta jsonb;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT dictionary_id INTO v_dictionary_id
    FROM private.current_training_review_delegate_entries_v1(p_user_id,p_card_type_id)
    WHERE id = p_entry_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'word entry not found';
    END IF;

    IF NOT (private.entry_access_v1(p_user_id,p_entry_id,'train') OR EXISTS(
      SELECT 1 FROM private.training_current_card_permits permit
      WHERE permit.user_id=p_user_id AND permit.entry_id=p_entry_id AND permit.card_type_id=p_card_type_id
        AND permit.target_id IS NULL AND private.current_training_permit_binding_valid_v1(permit))) THEN
        RAISE EXCEPTION 'dictionary access denied';
    END IF;

    IF p_card_type_id IN ('word-to-definition','definition-to-word') THEN
      PERFORM pg_advisory_xact_lock(hashtext('training-headword:'||p_user_id::text||':'||
        private.training_headword_group_v1(p_entry_id)::text));
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('training-pair:' || p_user_id::text || ':' ||
        private.training_pair_key_v1('meaning', p_entry_id, NULL, NULL, p_card_type_id)));

    -- Reject before the consumed-turn shortcut; hide is no longer an action.
    IF p_result = 'hide' THEN
        RAISE EXCEPTION 'legacy_hide_disabled' USING ERRCODE = '22023';
    END IF;

    IF p_turn_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtext(p_turn_id::text));

        IF EXISTS (
            SELECT 1
            FROM user_review_log
            WHERE turn_id = p_turn_id
        ) THEN
            RETURN;
        END IF;
    END IF;

    PERFORM private.require_training_pair_available_v1(
        p_user_id, 'meaning', p_entry_id, NULL, NULL, p_card_type_id);

    IF p_result = 'freeze' THEN
        INSERT INTO user_card_status (
            user_id, entry_id, card_type_id, frozen_until, last_result, last_seen_at
        )
        VALUES (p_user_id, p_entry_id, p_card_type_id, private.training_reference_now_v1() + interval '1 day', 'freeze', private.training_reference_now_v1())
        ON CONFLICT (user_id, entry_id, card_type_id) DO UPDATE
        SET frozen_until = private.training_reference_now_v1() + interval '1 day',
            last_result = 'freeze',
            last_seen_at = private.training_reference_now_v1();

        INSERT INTO user_events (user_id, word_id, mode, event_type)
        VALUES (p_user_id, p_entry_id, p_card_type_id, 'freeze');
        RETURN;
    END IF;

    v_grade := CASE p_result
        WHEN 'fail' THEN 1
        WHEN 'hard' THEN 2
        WHEN 'success' THEN 3
        WHEN 'easy' THEN 4
        ELSE 1
    END;

    SELECT * INTO v_status
    FROM user_card_status
    WHERE user_id = p_user_id
      AND entry_id = p_entry_id
      AND card_type_id = p_card_type_id;

    IF p_turn_id IS NULL
        AND v_status.last_reviewed_at IS NOT NULL
        AND (private.training_reference_now_v1() - v_status.last_reviewed_at) < interval '10 seconds' THEN
        RETURN;
    END IF;

    v_params := fsrs6_parameters();
    SELECT COALESCE(target_retention, 0.9) INTO v_target
    FROM user_settings
    WHERE user_id = p_user_id;

    v_review_type := CASE WHEN v_status.fsrs_stability IS NULL THEN 'new' ELSE 'review' END;
    v_scheduled := v_status.next_review_at;

    v_compute := fsrs6_compute(
        v_status.fsrs_stability,
        v_status.fsrs_difficulty,
        v_status.last_reviewed_at,
        v_grade,
        v_target,
        v_status.fsrs_reps,
        v_status.fsrs_lapses,
        v_params
    );

    v_interval := (v_compute->>'interval')::numeric;
    v_meta := jsonb_build_object(
        'elapsed_days', (v_compute->>'elapsed')::numeric,
        'retrievability', (v_compute->>'retrievability')::numeric,
        'same_day', (v_compute->>'same_day')::boolean,
        'last_reviewed_at_before', v_status.last_reviewed_at
    );

    INSERT INTO user_card_status (
        user_id, entry_id, card_type_id,
        fsrs_stability, fsrs_difficulty, fsrs_reps, fsrs_lapses, fsrs_last_grade,
        fsrs_last_interval, fsrs_target_retention, fsrs_params_version, fsrs_enabled,
        next_review_at, last_result, last_seen_at, last_reviewed_at,
        click_count, seen_count
    )
    VALUES (
        p_user_id, p_entry_id, p_card_type_id,
        (v_compute->>'stability')::numeric,
        (v_compute->>'difficulty')::numeric,
        (v_compute->>'reps')::int,
        (v_compute->>'lapses')::int,
        v_grade,
        v_interval,
        v_target,
        'fsrs-6-default',
        true,
        private.training_reference_now_v1() + (v_interval || ' days')::interval,
        p_result,
        private.training_reference_now_v1(),
        private.training_reference_now_v1(),
        COALESCE(v_status.click_count, 0),
        COALESCE(v_status.seen_count, 0) + 1
    )
    ON CONFLICT (user_id, entry_id, card_type_id) DO UPDATE
    SET fsrs_stability = excluded.fsrs_stability,
        fsrs_difficulty = excluded.fsrs_difficulty,
        fsrs_reps = excluded.fsrs_reps,
        fsrs_lapses = excluded.fsrs_lapses,
        fsrs_last_grade = excluded.fsrs_last_grade,
        fsrs_last_interval = excluded.fsrs_last_interval,
        fsrs_target_retention = excluded.fsrs_target_retention,
        fsrs_params_version = excluded.fsrs_params_version,
        fsrs_enabled = true,
        next_review_at = excluded.next_review_at,
        last_result = excluded.last_result,
        last_seen_at = excluded.last_seen_at,
        last_reviewed_at = excluded.last_reviewed_at,
        seen_count = user_card_status.seen_count + 1;

    INSERT INTO user_review_log (
        user_id, word_id, mode, turn_id, grade, review_type,
        scheduled_at, reviewed_at,
        stability_before, difficulty_before,
        stability_after, difficulty_after,
        interval_after, params_version, metadata
    ) VALUES (
        p_user_id, p_entry_id, p_card_type_id, p_turn_id, v_grade, v_review_type,
        v_scheduled, private.training_reference_now_v1(),
        v_status.fsrs_stability, v_status.fsrs_difficulty,
        (v_compute->>'stability')::numeric,
        (v_compute->>'difficulty')::numeric,
        v_interval,
        'fsrs-6-default',
        v_meta
    );

    INSERT INTO user_events (user_id, word_id, mode, event_type)
    VALUES (p_user_id, p_entry_id, p_card_type_id, 'review_' || p_result);
END;
$$;


SET LOCAL default_tablespace = '';

SET LOCAL default_table_access_method = heap;

--
-- Name: training_current_card_permits; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.training_current_card_permits (
    user_id uuid NOT NULL,
    permit_id uuid DEFAULT gen_random_uuid() NOT NULL,
    session_id uuid NOT NULL,
    run_generation bigint NOT NULL,
    entry_id uuid NOT NULL,
    card_type_id text NOT NULL,
    content_version bigint NOT NULL,
    state_revision text NOT NULL,
    target_id uuid,
    direction text,
    source_revision text,
    source_text_fingerprint text,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    shared_author_dictionary_id uuid,
    shared_author_user_id uuid,
    CONSTRAINT training_current_card_permits_check CHECK ((expires_at > issued_at)),
    CONSTRAINT training_current_card_permits_check1 CHECK ((((target_id IS NULL) AND (direction IS NULL)) OR ((target_id IS NOT NULL) AND (direction IS NOT NULL)))),
    CONSTRAINT training_current_card_permits_content_version_check CHECK ((content_version > 0)),
    CONSTRAINT training_permit_shared_author_pair CHECK (((shared_author_dictionary_id IS NULL) = (shared_author_user_id IS NULL)))
);


--
-- Name: current_training_permit_binding_valid_v1(private.training_current_card_permits); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_permit_binding_valid_v1(p private.training_current_card_permits) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT p.user_id IS NOT DISTINCT FROM (select auth.uid())
    AND p.expires_at>private.training_reference_now_v1()
    AND EXISTS(
      SELECT 1 FROM public.training_active_runs active
      JOIN public.training_sessions session ON session.id=active.session_id AND session.user_id=active.user_id
      JOIN public.word_entries entry ON entry.id=p.entry_id
      WHERE active.user_id=p.user_id AND active.session_id=p.session_id AND active.generation=p.run_generation
        AND session.completed_at IS NULL AND session.superseded_at IS NULL
        AND session.expires_at>private.training_reference_now_v1()
        AND entry.content_version=p.content_version
        AND (CASE WHEN p.shared_author_dictionary_id IS NOT NULL THEN
    entry.dictionary_id=p.shared_author_dictionary_id AND entry.management_kind='user'
    AND EXISTS(SELECT 1 FROM public.dictionaries dictionary WHERE dictionary.id=entry.dictionary_id
      AND dictionary.kind='user' AND dictionary.owner_user_id=p.shared_author_user_id
      AND dictionary.owner_user_id IS DISTINCT FROM p.user_id)
    ELSE entry.dictionary_id IS NULL OR public.can_access_dictionary(p.user_id,entry.dictionary_id,'read') END)
    )
    AND CASE WHEN p.target_id IS NULL THEN
      EXISTS(SELECT 1 FROM public.training_session_members member
        WHERE member.session_id=p.session_id AND member.entry_id=p.entry_id AND member.card_type_id=p.card_type_id
          AND member.consumed_at IS NULL AND member.unavailable_at IS NULL)
    ELSE
      EXISTS(SELECT 1 FROM public.training_session_exercise_members member
        JOIN private.platform_v2_training_exercise_targets target ON target.id=member.target_id
        LEFT JOIN private.platform_v2_content_nodes node ON node.id=target.content_node_id
        WHERE member.session_id=p.session_id AND member.target_id=p.target_id
          AND member.consumed_at IS NULL AND member.unavailable_at IS NULL
          AND target.entry_id=p.entry_id AND target.direction=p.direction
          AND target.visibility_state='active'
          AND target.source_revision IS NOT DISTINCT FROM p.source_revision
          AND target.source_text_fingerprint IS NOT DISTINCT FROM p.source_text_fingerprint
          AND (target.content_node_id IS NULL OR (node.binding_state='active' AND node.source_text_fingerprint=target.source_text_fingerprint)))
    END;
$$;


--
-- Name: current_training_permit_valid_v1(private.training_current_card_permits); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_permit_valid_v1(p private.training_current_card_permits) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT private.current_training_permit_binding_valid_v1(p) AND
    p.state_revision=CASE WHEN p.target_id IS NULL THEN
      COALESCE((SELECT state_revision::text FROM public.user_card_status
        WHERE user_id=p.user_id AND entry_id=p.entry_id AND card_type_id=p.card_type_id),'untracked')
    ELSE COALESCE((SELECT state_revision::text FROM public.user_training_exercise_state
        WHERE user_id=p.user_id AND target_id=p.target_id),'untracked') END;
$$;


--
-- Name: word_entries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.word_entries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    dictionary_id uuid,
    language_code text NOT NULL,
    headword text NOT NULL,
    meaning_id integer DEFAULT 1 NOT NULL,
    part_of_speech text,
    gender text,
    is_nt2_2000 boolean DEFAULT false,
    source_rank integer,
    raw jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now(),
    management_kind text NOT NULL,
    source_lifecycle text,
    normalized_pos_status text,
    archived_at timestamp with time zone,
    content_version bigint DEFAULT 1 NOT NULL,
    CONSTRAINT word_entries_content_version_check CHECK ((content_version > 0)),
    CONSTRAINT word_entries_management_fields_check CHECK ((((management_kind = 'source'::text) AND (source_lifecycle = ANY (ARRAY['active'::text, 'retired'::text])) AND (normalized_pos_status = ANY (ARRAY['known'::text, 'source-none'::text, 'unresolved'::text]))) OR ((management_kind = 'user'::text) AND (source_lifecycle IS NULL) AND (normalized_pos_status IS NULL)))),
    CONSTRAINT word_entries_management_kind_check CHECK ((management_kind = ANY (ARRAY['source'::text, 'user'::text])))
);


--
-- Name: COLUMN word_entries.source_rank; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.word_entries.source_rank IS 'Optional source-provided ordinal; not an entry identity.';


--
-- Name: current_training_review_delegate_entries_v1(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_review_delegate_entries_v1(p_user_id uuid, p_card_type_id text) RETURNS SETOF public.word_entries
    LANGUAGE sql STABLE
    AS $$
 SELECT entry.* FROM public.word_entries entry
 WHERE entry.archived_at IS NULL OR EXISTS(
   SELECT 1 FROM private.training_current_card_permits permit
   WHERE permit.user_id=p_user_id AND permit.entry_id=entry.id AND permit.card_type_id=p_card_type_id
     AND permit.target_id IS NULL AND private.current_training_permit_binding_valid_v1(permit));
$$;


--
-- Name: current_training_review_entries_v1(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_review_entries_v1(p_user_id uuid, p_card_type_id text) RETURNS SETOF public.word_entries
    LANGUAGE sql STABLE
    AS $$
 SELECT entry.* FROM public.word_entries entry
 WHERE entry.archived_at IS NULL OR (
   EXISTS(SELECT 1 FROM private.training_current_card_permits permit
     WHERE permit.user_id=p_user_id AND permit.entry_id=entry.id AND permit.target_id IS NULL)
   AND private.current_training_entry_permitted_v1(p_user_id,entry.id,p_card_type_id));
$$;


--
-- Name: current_training_start_learning_entry_card_v1(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_start_learning_entry_card_v1(p_user_id uuid, p_entry_id uuid, p_card_type_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
    v_other_card_type text := private.shared_meaning_other_direction(p_card_type_id);
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT dictionary_id INTO v_dictionary_id
    FROM private.current_training_review_delegate_entries_v1(p_user_id,p_card_type_id)
    WHERE id = p_entry_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'word entry not found';
    END IF;

    IF NOT (private.entry_access_v1(p_user_id,p_entry_id,'train') OR EXISTS(
      SELECT 1 FROM private.training_current_card_permits permit
      WHERE permit.user_id=p_user_id AND permit.entry_id=p_entry_id AND permit.card_type_id=p_card_type_id
        AND permit.target_id IS NULL AND private.current_training_permit_binding_valid_v1(permit))) THEN
        RAISE EXCEPTION 'dictionary access denied';
    END IF;

    -- Serialize against directional Known changes; never mutate a Known sibling.
    PERFORM pg_advisory_xact_lock(hashtext('shared-meaning-known:' || p_user_id::text || ':' || p_entry_id::text));

    INSERT INTO public.user_card_status (
        user_id, entry_id, card_type_id, fsrs_enabled, next_review_at,
        last_seen_at, seen_count, in_learning, hidden, frozen_until
    )
    VALUES (
        p_user_id, p_entry_id, p_card_type_id, true, private.training_reference_now_v1(), private.training_reference_now_v1(), 1,
        true, false, null
    )
    ON CONFLICT (user_id, entry_id, card_type_id) DO UPDATE
    SET fsrs_enabled = true,
        next_review_at = COALESCE(user_card_status.next_review_at, private.training_reference_now_v1()),
        last_seen_at = private.training_reference_now_v1(),
        seen_count = public.user_card_status.seen_count + 1,
        in_learning = CASE WHEN user_card_status.fsrs_last_grade IS NULL THEN true ELSE user_card_status.in_learning END,
        hidden = false,
        frozen_until = null;

    IF v_other_card_type IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.user_card_known_marks known
        WHERE known.user_id = p_user_id AND known.entry_id = p_entry_id
          AND known.card_type_id = v_other_card_type AND known.cleared_at IS NULL
    ) THEN
        INSERT INTO public.user_card_status (
            user_id, entry_id, card_type_id, fsrs_enabled, next_review_at,
            last_seen_at, seen_count, in_learning, hidden, frozen_until
        )
        VALUES (
            p_user_id, p_entry_id, v_other_card_type, true, private.training_reference_now_v1(), null, 0,
            true, false, null
        )
        ON CONFLICT (user_id, entry_id, card_type_id) DO UPDATE
        SET fsrs_enabled = true,
            next_review_at = COALESCE(user_card_status.next_review_at, private.training_reference_now_v1()),
            in_learning = CASE WHEN user_card_status.fsrs_last_grade IS NULL THEN true ELSE user_card_status.in_learning END,
            hidden = false,
            frozen_until = null;
    END IF;
END;
$$;


--
-- Name: current_training_target_permitted_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.current_training_target_permitted_v1(p_user_id uuid, p_target_id uuid, p_session_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT EXISTS(SELECT 1 FROM private.training_current_card_permits permit
    WHERE permit.user_id=p_user_id AND permit.target_id=p_target_id AND permit.session_id=p_session_id
      AND private.current_training_permit_valid_v1(permit));
$$;


--
-- Name: decode_dictionary_search_cursor_v1(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.decode_dictionary_search_cursor_v1(p_cursor text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    IF NULLIF(trim(COALESCE(p_cursor, '')), '') IS NULL THEN
        RETURN '{}'::jsonb;
    END IF;

    RETURN convert_from(decode(p_cursor, 'base64'), 'UTF8')::jsonb;
EXCEPTION WHEN others THEN
    RETURN '{}'::jsonb;
END;
$$;


--
-- Name: diagnostic_report_closed_shape(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.diagnostic_report_closed_shape(p_payload jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE v_feedback jsonb := p_payload->'feedback'; v_target jsonb := p_payload->'target';
  v_source jsonb := p_payload->'sourceContext'; v_card jsonb := p_payload->'cardContent';
  v_obs jsonb := p_payload->'observations'; v_item jsonb; v_kind text;
  v_stages text[] := ARRAY['lookup-selection','lookup-fetch','translation-cache','translation-provider','audio-cache','audio-provider','review-mutation','transition-render','report-capture','report-persist','report-send'];
  v_codes text[] := ARRAY['network-interrupted','timeout','unauthorized','forbidden','validation-rejected','provider-unavailable','render-failed','storage-failed','unknown'];
BEGIN
  IF NOT private.jsonb_has_exact_keys(v_feedback, ARRAY['kind','problemType','comment'])
     OR NOT private.jsonb_has_exact_keys(v_obs, ARRAY['capturedAt','timezoneOffsetMinutes','timezoneName','route','browserFamily','browserMajorVersion','osFamily','osMajorVersion','isPwa','isOnline','correlationIds','errorChain','recentEvents','omittedEventCount','actionObservation'])
     OR v_obs->>'route' NOT IN ('training','library','statistics','settings','unknown')
     OR v_obs->>'browserFamily' NOT IN ('chromium','safari','firefox','unknown')
     OR v_obs->>'osFamily' NOT IN ('android','ios','macos','windows','linux','unknown')
     OR v_obs->>'timezoneName' !~ '^[A-Za-z0-9_+/-]{1,64}$'
     OR jsonb_typeof(v_obs->'correlationIds') <> 'array'
     OR jsonb_array_length(v_obs->'correlationIds') > 8
     OR jsonb_typeof(v_obs->'errorChain') <> 'array'
     OR jsonb_array_length(v_obs->'errorChain') > 4
     OR jsonb_typeof(v_obs->'recentEvents') <> 'array'
     OR jsonb_array_length(v_obs->'recentEvents') > 30 THEN RETURN false; END IF;
  IF v_feedback->>'kind' = 'content-quality' AND v_feedback->>'problemType' NOT IN ('wrong-sense','bad-generated-definition','other-content')
     OR v_feedback->>'kind' = 'translation-quality' AND v_feedback->>'problemType' NOT IN ('bad-headword-translation','bad-definition-translation','bad-example-translation','other-translation')
     OR v_feedback->>'kind' = 'rendering' AND v_feedback->>'problemType' <> 'rendering-layout-issue'
     OR v_feedback->>'kind' = 'loading' AND v_feedback->>'problemType' <> 'loading-failure'
     OR v_feedback->>'kind' = 'training-action' AND v_feedback->>'problemType' <> 'training-action-failure'
     OR v_feedback->>'kind' = 'other' AND v_feedback->>'problemType' <> 'other' THEN RETURN false; END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_obs->'errorChain') LOOP
    IF NOT private.jsonb_has_exact_keys(v_item, ARRAY['category','stage','safeCode','httpStatus','correlationId','appFrameFingerprints'])
       OR v_item->>'category' NOT IN ('network','timeout','auth','validation','provider','render','storage','unknown')
       OR NOT (v_item->>'stage' = ANY(v_stages)) OR NOT (v_item->>'safeCode' = ANY(v_codes))
       OR jsonb_typeof(v_item->'appFrameFingerprints') <> 'array'
       OR EXISTS (SELECT 1 FROM jsonb_array_elements_text(v_item->'appFrameFingerprints') x WHERE x !~ '^[0-9a-f]{64}$')
    THEN RETURN false; END IF;
  END LOOP;
  FOR v_item IN SELECT value FROM jsonb_array_elements(v_obs->'recentEvents') LOOP
    IF NOT private.jsonb_has_exact_keys(v_item, ARRAY['stage','relativeMs','durationMs','outcome','safeCode','correlationId'])
       OR NOT (v_item->>'stage' = ANY(v_stages))
       OR v_item->>'outcome' NOT IN ('started','succeeded','failed','cancelled','unknown')
       OR (v_item->'safeCode' <> 'null'::jsonb AND NOT (v_item->>'safeCode' = ANY(v_codes)))
    THEN RETURN false; END IF;
  END LOOP;
  IF v_source <> 'null'::jsonb AND (
      NOT private.jsonb_has_exact_keys(v_source, ARRAY['contractVersion','source','location'])
      OR NOT private.jsonb_has_exact_keys(v_source->'source', ARRAY['kind','provider','externalId','languageCode'])
      OR v_source->>'contractVersion' <> 'diagnostic-source-context-v1'
      OR v_source#>>'{source,kind}' <> 'youtube_video' OR v_source#>>'{source,provider}' <> 'youtube'
      OR v_source#>>'{source,externalId}' !~ '^[A-Za-z0-9_-]{11}$'
      OR (v_source->'location' <> 'null'::jsonb AND NOT private.jsonb_has_exact_keys(v_source->'location', ARRAY['kind','startMs','endMs','phraseIndex','locatorConfidence']))
    ) THEN RETURN false; END IF;
  IF v_card <> 'null'::jsonb THEN
    IF NOT private.jsonb_has_exact_keys(v_card, ARRAY['atoms','omittedAtomCount']) OR jsonb_typeof(v_card->'atoms') <> 'array' OR jsonb_array_length(v_card->'atoms') NOT BETWEEN 1 AND 32 THEN RETURN false; END IF;
    FOR v_item IN SELECT value FROM jsonb_array_elements(v_card->'atoms') LOOP
      IF v_item->>'role' = 'displayed-translation' THEN
        IF NOT private.jsonb_has_exact_keys(v_item, ARRAY['role','contentNodeId','text','truncated','artifact'])
           OR jsonb_typeof(v_item->'artifact') IS DISTINCT FROM 'object'
           OR v_item->'contentNodeId' IS DISTINCT FROM v_item->'artifact'->'contentNodeId'
        THEN RETURN false; END IF;
      ELSIF NOT private.jsonb_has_exact_keys(v_item, ARRAY['role','contentNodeId','text','truncated'])
         OR v_item->>'role' NOT IN ('headword','definition','usage-pattern','example','idiom','idiom-explanation','usage-note')
      THEN RETURN false; END IF;
    END LOOP;
  END IF;
  v_kind := v_target->>'kind';
  IF v_kind = 'entry' THEN RETURN private.jsonb_has_exact_keys(v_target, ARRAY['kind','entryId','contentRevision']);
  ELSIF v_kind = 'sense-card' THEN RETURN private.jsonb_has_exact_keys(v_target, ARRAY['kind','entryId','cardTypeId','contentRevision','stateRevision']);
  ELSIF v_kind = 'content-node' THEN RETURN private.jsonb_has_exact_keys(v_target, ARRAY['kind','entryId','contentNodeId','nodeKind','sourceTextFingerprint']);
  ELSIF v_kind = 'translation-artifact' AND v_target->>'targetKind' = 'entry' THEN
    RETURN private.jsonb_has_exact_keys(v_target, ARRAY['kind','targetKind','entryId','contentNodeId','translationId','sourceContentFingerprint','targetLanguageCode','translationPolicyVersion','providerRevision']);
  ELSIF v_kind = 'translation-artifact' AND v_target->>'targetKind' = 'content-node' THEN
    RETURN private.jsonb_has_exact_keys(v_target, ARRAY['kind','targetKind','entryId','contentNodeId','translationId','sourceTextFingerprint','targetLanguageCode','translationPolicyVersion','providerRevision']);
  ELSIF v_kind = 'training-action' THEN RETURN private.jsonb_has_exact_keys(v_target, ARRAY['kind','entryId','cardTypeId','stateRevision','contentRevision','actionId','clientEventId','reviewResult','activeKnownMarkId','knownMarkRevision']);
  ELSIF v_kind = 'app-operation' THEN RETURN private.jsonb_has_exact_keys(v_target, ARRAY['kind','route','stage','operationCorrelationId','entryId']);
  END IF;
  RETURN false;
EXCEPTION WHEN OTHERS THEN RETURN false;
END;
$_$;


--
-- Name: diagnostic_report_target_entry_id(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.diagnostic_report_target_entry_id(p_target jsonb) RETURNS uuid
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    IF p_target->>'kind' = 'app-operation' AND p_target->>'entryId' IS NULL THEN
        RETURN NULL;
    END IF;
    RETURN (p_target->>'entryId')::uuid;
EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'invalid_target';
END;
$$;


--
-- Name: diagnostic_translation_text_at_locator(jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.diagnostic_translation_text_at_locator(p_overlay jsonb, p_locator text, p_kind text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE v_text text;
BEGIN
    v_text := CASE p_locator
        WHEN 'raw.headword' THEN p_overlay->>'headword'
        WHEN 'raw.definition' THEN p_overlay#>>'{meanings,0,definition}'
        WHEN 'raw.example.source' THEN p_overlay#>>'{meanings,0,examples,0}'
        WHEN 'raw.notes' THEN p_overlay#>>'{meanings,0,context}'
        ELSE private.platform_v2_text_at_diagnostic_locator(
            p_overlay,
            p_locator,
            p_kind
        )
    END;
    v_text := NULLIF(trim(v_text), '');
    RETURN CASE WHEN v_text IS NULL THEN NULL ELSE normalize(v_text, NFC) END;
END;
$$;


--
-- Name: dictionaries; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dictionaries (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    language_code text NOT NULL,
    slug text NOT NULL,
    name text NOT NULL,
    description text,
    kind text DEFAULT 'curated'::text NOT NULL,
    visibility text DEFAULT 'private'::text NOT NULL,
    owner_user_id uuid,
    is_editable boolean DEFAULT false NOT NULL,
    minimum_subscription_tier text DEFAULT 'free'::text,
    access_policy_key text,
    schema_key text,
    schema_version integer,
    source_provider text,
    source_version text,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    publication_state text NOT NULL,
    CONSTRAINT dictionaries_kind_check CHECK ((kind = ANY (ARRAY['curated'::text, 'user'::text]))),
    CONSTRAINT dictionaries_publication_state_check CHECK ((publication_state = ANY (ARRAY['unpublished'::text, 'restricted'::text, 'general'::text]))),
    CONSTRAINT dictionaries_visibility_check CHECK ((visibility = ANY (ARRAY['system'::text, 'private'::text, 'shared'::text, 'public'::text])))
);


--
-- Name: dictionary_metadata_for_entry_read_v1(uuid, public.dictionaries); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dictionary_metadata_for_entry_read_v1(p_user_id uuid, p_dictionary public.dictionaries) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
  SELECT CASE WHEN (p_dictionary).kind='user' AND (p_dictionary).owner_user_id IS DISTINCT FROM p_user_id THEN
    jsonb_build_object('id',(p_dictionary).id,'language_code',(p_dictionary).language_code,
      'slug',(p_dictionary).slug,'name',(p_dictionary).name,'kind',(p_dictionary).kind,
      'visibility',(p_dictionary).visibility,'owner_user_id',(p_dictionary).owner_user_id,
      'is_editable',false,'schema_key',(p_dictionary).schema_key,'schema_version',(p_dictionary).schema_version)
    ELSE to_jsonb(p_dictionary) END
$$;


--
-- Name: dictionary_search_index_ready_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.dictionary_search_index_ready_v1() RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    SELECT
        EXISTS (SELECT 1 FROM dictionary_search_documents LIMIT 1)
        AND EXISTS (SELECT 1 FROM dictionary_search_fields LIMIT 1);
$$;


--
-- Name: display_entry_notes_from_scope_v1(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.display_entry_notes_from_scope_v1(p_entry jsonb, p_scope jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT COALESCE(jsonb_agg(item-'entryId' ORDER BY ordinal),'[]'::jsonb)
  FROM jsonb_array_elements(p_scope) WITH ORDINALITY material(item,ordinal)
  WHERE item->>'entryId'=p_entry->>'id' AND item->>'noteId' IS NOT NULL AND NULLIF(item->>'text','') IS NOT NULL
    AND (item->>'text') IS DISTINCT FROM (p_entry#>>'{raw,notes}')
    AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_entry#>'{raw,meanings}')='array'
      THEN p_entry#>'{raw,meanings}' ELSE '[]'::jsonb END) meaning WHERE meaning->>'note'=item->>'text')
$$;


--
-- Name: drain_platform_v2_source_import_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.drain_platform_v2_source_import_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE v_count integer;
BEGIN
  IF to_regclass('pg_temp.platform_v2_import_refresh_entries') IS NULL THEN
    RETURN 0;
  END IF;
  INSERT INTO pg_temp.platform_v2_import_refresh_entries (entry_id)
  SELECT binding.word_entry_id
  FROM private.source_entry_bindings AS binding
  JOIN pg_temp.platform_v2_import_refresh_groups AS queued
    USING (dictionary_id, identity_scheme_version, source_group_key)
  WHERE binding.binding_state = 'active'
  ON CONFLICT DO NOTHING;
  SELECT count(*) INTO v_count FROM pg_temp.platform_v2_import_refresh_entries;
  IF v_count = 0 THEN RETURN 0; END IF;
  ANALYZE pg_temp.platform_v2_import_refresh_entries;
  DELETE FROM private.unrenderable_ordinary_direct_entries_v1 AS target
  USING pg_temp.platform_v2_import_refresh_entries AS affected
  WHERE target.entry_id = affected.entry_id;
  WITH root_content AS MATERIALIZED (
    SELECT node.entry_id, bool_or(node.kind = 'definition') AS has_definition,
           bool_or(node.kind = 'example') AS has_example
    FROM private.platform_v2_content_nodes AS node
    WHERE node.binding_state = 'active'
      AND node.parent_content_node_id IS NULL
      AND node.kind IN ('definition', 'example')
    GROUP BY node.entry_id
  ), first_ordinary AS MATERIALIZED (
    SELECT binding.dictionary_id, binding.identity_scheme_version,
           binding.source_group_key, min(binding.sense_ordinal) AS ordinal
    FROM private.source_entry_bindings AS binding
    JOIN root_content ON root_content.entry_id = binding.word_entry_id
    WHERE binding.binding_state = 'active' AND root_content.has_definition
    GROUP BY binding.dictionary_id, binding.identity_scheme_version,
             binding.source_group_key
  )
  INSERT INTO private.unrenderable_ordinary_direct_entries_v1 (entry_id)
  SELECT entry.id
  FROM pg_temp.platform_v2_import_refresh_entries AS affected
  JOIN public.word_entries AS entry ON entry.id = affected.entry_id
  JOIN root_content ON root_content.entry_id = entry.id
  LEFT JOIN private.source_entry_bindings AS binding
    ON binding.word_entry_id = entry.id AND binding.binding_state = 'active'
  LEFT JOIN first_ordinary
    ON first_ordinary.dictionary_id = binding.dictionary_id
   AND first_ordinary.identity_scheme_version = binding.identity_scheme_version
   AND first_ordinary.source_group_key = binding.source_group_key
  WHERE root_content.has_definition AND NOT root_content.has_example
    AND (first_ordinary.ordinal < binding.sense_ordinal OR
         (binding.word_entry_id IS NULL AND COALESCE(entry.meaning_id, 1) > 1));
  TRUNCATE pg_temp.platform_v2_import_refresh_entries;
  TRUNCATE pg_temp.platform_v2_import_refresh_groups;
  RETURN v_count;
END;
$$;


--
-- Name: encode_dictionary_search_cursor_v1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.encode_dictionary_search_cursor_v1(p_cursor jsonb) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT encode(convert_to(COALESCE(p_cursor, '{}'::jsonb)::text, 'UTF8'), 'base64');
$$;


--
-- Name: enroll_familiar_meaning_directions_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.enroll_familiar_meaning_directions_v1(p_user_id uuid, p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
 INSERT INTO public.user_card_status(user_id,entry_id,card_type_id,fsrs_enabled,next_review_at,in_learning,seen_count)
 SELECT p_user_id,p_entry_id,direction,true,private.training_reference_now_v1(),true,0
 FROM unnest(ARRAY['word-to-definition','definition-to-word']) direction
 WHERE NOT EXISTS(SELECT 1 FROM public.user_card_known_marks k WHERE k.user_id=p_user_id AND k.entry_id=p_entry_id AND k.card_type_id=direction AND k.cleared_at IS NULL)
 ON CONFLICT(user_id,entry_id,card_type_id) DO UPDATE
 SET fsrs_enabled=true,in_learning=true,next_review_at=COALESCE(user_card_status.next_review_at,EXCLUDED.next_review_at)
 WHERE user_card_status.fsrs_last_grade IS NULL AND NOT user_card_status.fsrs_enabled;
END;$$;


--
-- Name: ensure_platform_v2_source_group(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_platform_v2_source_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    IF NEW.binding_state = 'active' THEN
        INSERT INTO private.platform_v2_headword_groups (
            dictionary_id,
            management_kind,
            identity_scheme_version,
            source_group_key
        )
        VALUES (
            NEW.dictionary_id,
            'source',
            NEW.identity_scheme_version,
            NEW.source_group_key
        )
        ON CONFLICT (
            dictionary_id,
            identity_scheme_version,
            source_group_key
        ) WHERE management_kind = 'source'
        DO NOTHING;
    END IF;

    RETURN NEW;
END;
$$;


