-- Name: ensure_platform_v2_source_import_flushed_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_platform_v2_source_import_flushed_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  PERFORM private.flush_platform_v2_source_import_v1();
  RETURN NULL;
END;
$$;


--
-- Name: ensure_platform_v2_training_exercise_target_v1(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_platform_v2_training_exercise_target_v1(p_entry_id uuid, p_content_node_id uuid, p_family text, p_direction text, p_source_revision text, p_source_text_fingerprint text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_existing private.platform_v2_training_exercise_targets%rowtype;
    v_target_id uuid;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM private.active_word_entries WHERE id = p_entry_id
    ) THEN
        RAISE EXCEPTION 'training_exercise_entry_not_found';
    END IF;

    SELECT *
      INTO v_existing
      FROM private.platform_v2_training_exercise_targets
     WHERE entry_id = p_entry_id
       AND content_node_id IS NOT DISTINCT FROM p_content_node_id
       AND family = p_family
       AND direction = p_direction
     FOR UPDATE;

    IF FOUND THEN
        IF v_existing.source_text_fingerprint IS DISTINCT FROM p_source_text_fingerprint THEN
            RAISE EXCEPTION 'training_exercise_target_rebind_requires_new_node';
        END IF;

        IF p_content_node_id IS NOT NULL AND NOT EXISTS (
            SELECT 1
              FROM private.platform_v2_content_nodes node
             WHERE node.id = p_content_node_id
               AND node.entry_id = p_entry_id
               AND node.binding_state = 'active'
               AND node.source_text_fingerprint = p_source_text_fingerprint
        ) THEN
            RAISE EXCEPTION 'training_exercise_target_source_not_active';
        END IF;

        UPDATE private.platform_v2_training_exercise_targets
           SET source_revision = p_source_revision,
               visibility_state = 'active',
               retired_at = NULL,
               retirement_reason = NULL,
               updated_at = private.training_reference_now_v1()
         WHERE id = v_existing.id
           AND content_node_id IS NOT DISTINCT FROM p_content_node_id;
        RETURN v_existing.id;
    END IF;

    INSERT INTO private.platform_v2_training_exercise_targets (
        entry_id,
        content_node_id,
        family,
        direction,
        source_revision,
        source_text_fingerprint
    )
    VALUES (
        p_entry_id,
        p_content_node_id,
        p_family,
        p_direction,
        p_source_revision,
        p_source_text_fingerprint
    )
    RETURNING id INTO v_target_id;

    RETURN v_target_id;
END;
$$;


--
-- Name: ensure_platform_v2_user_group(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.ensure_platform_v2_user_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_owner_user_id uuid;
BEGIN
    IF NEW.management_kind <> 'user' THEN
        RETURN NEW;
    END IF;

    SELECT owner_user_id
    INTO v_owner_user_id
    FROM public.dictionaries
    WHERE id = NEW.dictionary_id;

    IF v_owner_user_id IS NULL THEN
        RAISE EXCEPTION 'platform_v2_user_group_owner_missing';
    END IF;

    INSERT INTO private.platform_v2_headword_groups (
        dictionary_id,
        management_kind,
        owner_user_id,
        singleton_entry_id
    )
    VALUES (
        NEW.dictionary_id,
        'user',
        v_owner_user_id,
        NEW.id
    )
    ON CONFLICT (singleton_entry_id)
        WHERE management_kind = 'user'
    DO NOTHING;

    RETURN NEW;
END;
$$;


--
-- Name: entry_access_v1(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.entry_access_v1(p_user_id uuid, p_entry_id uuid, p_mode text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT EXISTS(SELECT 1 FROM private.active_word_entries entry
    LEFT JOIN public.dictionaries dictionary ON dictionary.id=entry.dictionary_id
    WHERE entry.id=p_entry_id AND p_mode IN ('browse','train') AND CASE
      WHEN entry.dictionary_id IS NULL THEN true
      WHEN dictionary.kind='user' THEN dictionary.owner_user_id=p_user_id
        OR private.can_read_shared_author_entry_v1(p_user_id,entry.id)
      WHEN p_mode='browse' THEN public.can_browse_dictionary(p_user_id,entry.dictionary_id)
      WHEN p_mode='train' THEN public.can_access_dictionary(p_user_id,entry.dictionary_id,'read')
      ELSE false END)
$$;


--
-- Name: entry_note_display_material_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.entry_note_display_material_v1(p_user uuid, p_entry jsonb) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT private.display_entry_notes_from_scope_v1(p_entry,private.entry_note_scope_material_v1(p_user,ARRAY[(p_entry->>'id')::uuid]))
$$;


--
-- Name: entry_note_scope_material_v1(uuid, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.entry_note_scope_material_v1(p_user uuid, p_entries uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE result jsonb:='[]'; item record;
BEGIN
  IF p_user IS NULL THEN RETURN result; END IF;
  IF p_entries IS NULL OR cardinality(p_entries)>50 THEN RAISE EXCEPTION 'invalid_note_scope' USING ERRCODE='22023'; END IF;
  FOR item IN
    WITH readable AS MATERIALIZED(
      SELECT DISTINCT entry.id FROM unnest(p_entries) requested(id)
      JOIN private.active_word_entries entry ON entry.id=requested.id
      WHERE private.entry_access_v1(p_user,entry.id,'browse')
    ), authors AS MATERIALIZED(
      SELECT DISTINCT entry.id AS entry_id,scope.owner_user_id
      FROM readable entry JOIN public.user_word_list_items membership ON membership.word_id=entry.id
      JOIN private.live_collection_sharing_subscriptions_v1 scope ON scope.collection_id=membership.list_id
      WHERE scope.user_id=p_user AND scope.owner_user_id<>p_user
    ), participants AS (
      SELECT id AS entry_id,p_user AS owner_id,true AS is_own FROM readable
      UNION ALL SELECT entry_id,owner_user_id,false FROM authors
    )
    SELECT participant.entry_id,participant.owner_id,participant.is_own,note.id AS note_id,note.notes,
      COALESCE(clock.revision,0)::text AS revision
    FROM participants participant
    LEFT JOIN public.user_word_notes note ON note.user_id=participant.owner_id AND note.word_entry_id=participant.entry_id
    LEFT JOIN private.user_word_note_revisions clock ON clock.user_id=participant.owner_id AND clock.word_entry_id=participant.entry_id
    ORDER BY participant.entry_id,participant.is_own DESC,participant.owner_id
    LIMIT 1001
  LOOP
    IF jsonb_array_length(result)>=1000 THEN RAISE EXCEPTION 'note_material_too_large' USING ERRCODE='22023'; END IF;
    result:=result||jsonb_build_array(jsonb_build_object('entryId',item.entry_id,'ownerUserId',item.owner_id,
      'noteId',item.note_id,'text',item.notes,'revision',item.revision,'isOwn',item.is_own));
    IF octet_length(result::text)>1048576 THEN RAISE EXCEPTION 'note_material_too_large' USING ERRCODE='22023'; END IF;
  END LOOP;
  RETURN result;
END;
$$;


--
-- Name: entry_payload_for_reader_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.entry_payload_for_reader_v1(p_user_id uuid, p_entry jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  result:=private.entry_payload_without_note_material_v1(p_user_id,p_entry);
  IF result IS NULL OR p_user_id IS NULL THEN RETURN result; END IF;
  RETURN result||jsonb_build_object('note_material',private.entry_note_display_material_v1(p_user_id,p_entry));
END;
$$;


--
-- Name: entry_payload_without_note_material_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.entry_payload_without_note_material_v1(p_user_id uuid, p_entry jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE result jsonb;
BEGIN
  IF p_entry IS NULL THEN RETURN NULL; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.dictionaries d WHERE d.id=(p_entry->>'dictionary_id')::uuid
    AND d.kind='user' AND d.owner_user_id IS DISTINCT FROM p_user_id) THEN RETURN p_entry; END IF;
  SELECT COALESCE(jsonb_object_agg(key,value),'{}') INTO result FROM jsonb_each(p_entry)
    WHERE key=ANY(ARRAY['id','dictionary_id','dictionary_name','dictionary_slug','dictionary_kind','language_code',
      'headword','meaning_id','part_of_speech','gender','is_nt2_2000','meanings_count','content_version','management_kind']);
  RETURN result||jsonb_build_object('raw',private.shared_instructional_raw_v1(p_entry->'raw'));
END;
$$;


--
-- Name: finish_collection_share_command_v1(uuid, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finish_collection_share_command_v1(p_operation_id uuid, p_request jsonb, p_facts jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); facts jsonb;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  facts:=p_facts||jsonb_build_object('operationId',p_operation_id,'status','committed');
  INSERT INTO private.collection_sharing_command_receipts(user_id,operation_id,request_hash,response)
    VALUES(principal,p_operation_id,sha256(convert_to(p_request::text,'UTF8')),facts);
  RETURN private.collection_share_projection_v1(principal,facts);
END;
$$;


--
-- Name: finish_platform_v2_source_import_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.finish_platform_v2_source_import_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF to_regclass('pg_temp.platform_v2_import_refresh_entries') IS NULL THEN
    RAISE EXCEPTION 'platform_v2_source_import_not_started';
  END IF;
  RETURN private.flush_platform_v2_source_import_v1();
END;
$$;


--
-- Name: flatten_copy_note_overlays_v1(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.flatten_copy_note_overlays_v1(p_raw jsonb, p_material jsonb) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE item jsonb; seen jsonb:='{}'; texts text[]:='{}'; id text; value text;
BEGIN
  FOR item IN SELECT note.body FROM jsonb_array_elements(p_material) note(body)
    ORDER BY (note.body->>'isOwn')::boolean,note.body->>'ownerUserId',note.body->>'noteId'
  LOOP
    id:=item->>'noteId';value:=item->>'text';
    IF id IS NULL OR NULLIF(value,'') IS NULL THEN CONTINUE; END IF;
    IF seen ? id THEN
      IF seen->>id IS DISTINCT FROM value THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
      CONTINUE;
    END IF;
    seen:=seen||jsonb_build_object(id,value);
    IF value IS NOT DISTINCT FROM p_raw->>'notes' OR EXISTS(
      SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(p_raw->'meanings')='array' THEN p_raw->'meanings' ELSE '[]'::jsonb END) meaning(body)
      WHERE meaning.body->>'note'=value) THEN CONTINUE; END IF;
    texts:=array_append(texts,value);
  END LOOP;
  RETURN array_to_string(texts,E'\n\n');
END;
$$;


--
-- Name: flush_platform_v2_source_import_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.flush_platform_v2_source_import_v1() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_count integer;
BEGIN
  IF to_regclass('pg_temp.platform_v2_import_refresh_entries') IS NULL
     OR to_regclass('pg_temp.platform_v2_import_refresh_groups') IS NULL THEN
    RETURN 0;
  END IF;
  v_count := private.drain_platform_v2_source_import_v1();
  DROP TABLE pg_temp.platform_v2_import_refresh_groups;
  DROP TABLE pg_temp.platform_v2_import_refresh_entries;
  RETURN v_count;
END;
$$;


--
-- Name: generate_collection_share_code_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.generate_collection_share_code_v1() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'extensions', 'pg_temp'
    AS $$
DECLARE alphabet constant text:='0123456789ABCDEFGHJKMNPQRSTVWXYZ';
  entropy bytea:=extensions.gen_random_bytes(26); result text:=''; i integer;
BEGIN
  FOR i IN 0..25 LOOP
    result:=result||substr(alphabet,(get_byte(entropy,i) & 31)+1,1);
  END LOOP;
  RETURN result;
END;
$$;


--
-- Name: get_detailed_training_stats_utc_legacy_v1(uuid, text[], uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.get_detailed_training_stats_utc_legacy_v1(p_user_id uuid, p_modes text[] DEFAULT ARRAY['word-to-definition'::text], p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT 'curated'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_new_words_today int;
    v_new_cards_today int;
    v_learning_started_today int;
    v_graduated_new_words_today int;
    v_daily_new_limit int;
    v_review_words_done int;
    v_review_cards_done int;
    v_review_words_due int;
    v_review_cards_due int;
    v_total_words_learned int;
    v_total_words_in_list int;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF p_modes IS NULL OR array_length(p_modes, 1) IS NULL THEN
        p_modes := ARRAY['word-to-definition'];
    END IF;

    IF p_list_id IS NOT NULL AND p_list_type IS NULL THEN
        p_list_type := 'curated';
    END IF;

    SELECT COALESCE(daily_new_limit, 10) INTO v_daily_new_limit
    FROM user_settings WHERE user_id = p_user_id;
    v_daily_new_limit := COALESCE(v_daily_new_limit, 10);

    -- A card is introduced when Learn is accepted. The review-log fallback
    -- keeps direct/older first grades visible while no historical rewrite is
    -- needed. Counts are exact entry + card type, not word-only guesses.
    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    ), introduced_cards AS (
        SELECT e.entry_id, e.card_type_id
        FROM user_card_action_events e
        WHERE e.user_id = p_user_id
          AND e.card_type_id = ANY(p_modes)
          AND e.action = 'start-learning'
          AND e.created_at::date = current_date
        UNION
        SELECT rl.word_id, rl.mode
        FROM user_review_log rl
        WHERE rl.user_id = p_user_id
          AND rl.mode = ANY(p_modes)
          AND rl.review_type = 'new'
          AND rl.reviewed_at::date = current_date
    )
    SELECT COUNT(DISTINCT ic.entry_id), COUNT(*)
    INTO v_new_words_today, v_new_cards_today
    FROM introduced_cards ic
    JOIN accessible_entries ae ON ae.id = ic.entry_id;

    SELECT COUNT(*)
    INTO v_learning_started_today
    FROM (
        SELECT DISTINCT e.entry_id, e.card_type_id
        FROM user_card_action_events e
        JOIN word_entries w ON w.id = e.entry_id
        WHERE e.user_id = p_user_id
          AND e.card_type_id = ANY(p_modes)
          AND e.action = 'start-learning'
          AND e.created_at::date = current_date
          AND (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    ) started;

    -- A graduated-new metric is kept separate from the introduced metric so
    -- callers can explain both concepts without overloading `newWordsToday`.
    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(DISTINCT rl.word_id)
    INTO v_graduated_new_words_today
    FROM user_review_log rl
    JOIN accessible_entries ae ON ae.id = rl.word_id
    WHERE rl.user_id = p_user_id
      AND rl.mode = ANY(p_modes)
      AND rl.review_type = 'new'
      AND rl.reviewed_at::date = current_date
      AND rl.interval_after >= 1.0;

    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(DISTINCT rl.word_id), COUNT(*)
    INTO v_review_words_done, v_review_cards_done
    FROM user_review_log rl
    JOIN accessible_entries ae ON ae.id = rl.word_id
    WHERE rl.user_id = p_user_id
      AND rl.mode = ANY(p_modes)
      AND rl.review_type = 'review'
      AND rl.reviewed_at::date = current_date
      AND rl.interval_after >= 1.0;

    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(DISTINCT s.entry_id), COUNT(*)
    INTO v_review_words_due, v_review_cards_due
    FROM user_card_status s
    JOIN accessible_entries ae ON ae.id = s.entry_id
    JOIN private.active_word_entries available ON available.id = s.entry_id
    WHERE s.user_id = p_user_id
      AND s.card_type_id = ANY(p_modes)
      AND s.next_review_at < (current_date + interval '1 day')
      AND (s.frozen_until IS NULL OR s.frozen_until <= now())
      AND s.hidden = false
      AND s.fsrs_enabled = true
      AND NOT EXISTS (
          SELECT 1 FROM user_review_log rl
          WHERE rl.user_id = s.user_id
            AND rl.word_id = s.entry_id
            AND rl.mode = s.card_type_id
            AND rl.review_type = 'new'
            AND rl.reviewed_at::date = current_date
      );

    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(DISTINCT s.entry_id)
    INTO v_total_words_learned
    FROM user_card_status s
    JOIN accessible_entries ae ON ae.id = s.entry_id
    WHERE s.user_id = p_user_id
      AND s.card_type_id = ANY(p_modes)
      AND s.fsrs_enabled = true;

    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(*) INTO v_total_words_in_list FROM accessible_entries scope JOIN private.active_word_entries available ON available.id=scope.id;

    RETURN jsonb_build_object(
        'newWordsToday', v_new_words_today,
        'newCardsToday', v_new_cards_today,
        'learningStartedToday', v_learning_started_today,
        'graduatedNewWordsToday', v_graduated_new_words_today,
        'dailyNewLimit', v_daily_new_limit,
        'reviewWordsDone', v_review_words_done,
        'reviewCardsDone', v_review_cards_done,
        'reviewWordsDue', v_review_words_due,
        'reviewCardsDue', v_review_cards_due,
        'totalWordsLearned', v_total_words_learned,
        'totalWordsInList', v_total_words_in_list
    );
END;
$$;


--
-- Name: FUNCTION get_detailed_training_stats_utc_legacy_v1(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.get_detailed_training_stats_utc_legacy_v1(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text) IS 'Authenticated training statistics with explicit introduced, learning-started, graduated, and review projections.';


--
-- Name: get_last_review_debug(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.get_last_review_debug(p_user_id uuid, p_entry_id uuid, p_mode text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private'
    AS $$
DECLARE
    v_row user_review_log%rowtype;
BEGIN
    IF p_user_id != (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT *
    INTO v_row
    FROM user_review_log
    WHERE user_id = p_user_id
      AND word_id = p_entry_id
      AND mode = p_mode
    ORDER BY reviewed_at DESC
    LIMIT 1;

    IF v_row.id IS NULL THEN
        RETURN NULL;
    END IF;

    RETURN jsonb_build_object(
        'reviewed_at', v_row.reviewed_at,
        'scheduled_at', v_row.scheduled_at,
        'review_type', v_row.review_type,
        'grade', v_row.grade,
        'interval_after', v_row.interval_after,
        'stability_before', v_row.stability_before,
        'stability_after', v_row.stability_after,
        'metadata', v_row.metadata
    );
END;
$$;


--
-- Name: get_next_training_session_card_latch_v1(uuid, uuid, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.get_next_training_session_card_latch_v1(p_user_id uuid, p_session_id uuid, p_exclude_card_keys text[]) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_session public.training_sessions%rowtype;
  v_member public.training_session_members%rowtype;
  v_filter jsonb;
  v_filtered boolean;
  v_card jsonb;
  v_card_key text;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;

  SELECT * INTO v_session
  FROM public.training_sessions
  WHERE id = p_session_id
    AND user_id = p_user_id
    AND completed_at IS NULL
    AND expires_at > private.training_reference_now_v1();
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- Walk the latched order. A permanent access/projection failure is returned
  -- as a diagnostic for the explicit mutation RPC. The selector remains a
  -- read-only lookup: it never changes membership or session completion.
  FOR v_member IN
    SELECT member.*
    FROM public.training_session_members member
    WHERE member.session_id = v_session.id
      AND member.consumed_at IS NULL
      AND member.unavailable_at IS NULL
    ORDER BY member.ordinal
  LOOP
    v_card_key := v_member.entry_id::text || ':' || v_member.card_type_id;
    IF v_card_key = ANY(COALESCE(p_exclude_card_keys, ARRAY[]::text[])) THEN
      CONTINUE;
    END IF;

    IF EXISTS(SELECT 1 FROM public.word_entries entry
      WHERE entry.id=v_member.entry_id AND entry.archived_at IS NOT NULL) THEN
      RETURN NEXT jsonb_build_object('trainingSessionUnavailable',true,
        'trainingSessionId',v_session.id,'trainingSessionOrdinal',v_member.ordinal,
        'entryId',v_member.entry_id,'cardTypeId',v_member.card_type_id,'reason','entry-archived');
      RETURN;
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM private.active_word_entries entry
      WHERE entry.id = v_member.entry_id
    ) THEN
      RETURN NEXT jsonb_build_object(
        'trainingSessionUnavailable', true,
        'trainingSessionId', v_session.id,
        'trainingSessionOrdinal', v_member.ordinal,
        'entryId', v_member.entry_id,
        'cardTypeId', v_member.card_type_id,
        'reason', 'entry-not-found'
      );
      RETURN;
    END IF;

    IF NOT EXISTS (
      SELECT 1
      FROM private.active_word_entries entry
      WHERE entry.id = v_member.entry_id
        AND private.entry_access_v1(p_user_id,entry.id,'train')
    ) THEN
      RETURN NEXT jsonb_build_object(
        'trainingSessionUnavailable', true,
        'trainingSessionId', v_session.id,
        'trainingSessionOrdinal', v_member.ordinal,
        'entryId', v_member.entry_id,
        'cardTypeId', v_member.card_type_id,
        'reason', 'dictionary-access-revoked'
      );
      RETURN;
    END IF;

    IF private.training_pair_excluded_v1(
      p_user_id,'meaning',v_member.entry_id,NULL,NULL,v_member.card_type_id) THEN
      RETURN NEXT jsonb_build_object('trainingSessionUnavailable',true,
        'trainingSessionId',v_session.id,'trainingSessionOrdinal',v_member.ordinal,
        'entryId',v_member.entry_id,'cardTypeId',v_member.card_type_id,'reason','pair-excluded');
      RETURN;
    END IF;

    v_filter := COALESCE(v_session.training_filter, '{}'::jsonb);
    v_filtered := private.training_filter_target_date(v_filter) IS NOT NULL
      OR NULLIF(v_filter->>'sourceId', '') IS NOT NULL
      OR NULLIF(trim(v_filter->>'sourceKind'), '') IS NOT NULL
      OR NULLIF(trim(v_filter->>'externalId'), '') IS NOT NULL;

    v_card := private.project_training_scheduler_candidate_v1(
      p_user_id,
      v_member.entry_id,
      v_member.card_type_id,
      v_member.queue_source,
      v_filter,
      v_filtered,
      0,
      0,
      0,
      0,
      0
    );
    IF v_card IS NULL THEN
      RETURN NEXT jsonb_build_object(
        'trainingSessionUnavailable', true,
        'trainingSessionId', v_session.id,
        'trainingSessionOrdinal', v_member.ordinal,
        'entryId', v_member.entry_id,
        'cardTypeId', v_member.card_type_id,
        'reason', 'projection-missing'
      );
      RETURN;
    END IF;

    RETURN NEXT v_card || jsonb_build_object(
      'trainingSessionId', v_session.id,
      'trainingSessionOrdinal', v_member.ordinal
    );
    RETURN;
  END LOOP;
END;
$$;


--
-- Name: get_training_session_snapshot_latch_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.get_training_session_snapshot_latch_v1(p_user_id uuid, p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_session public.training_sessions%rowtype;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  SELECT * INTO v_session
  FROM public.training_sessions
  WHERE id = p_session_id AND user_id = p_user_id;
  IF NOT FOUND THEN RETURN NULL; END IF;

  RETURN jsonb_build_object(
    'sessionId', v_session.id,
    'sessionSize', v_session.session_size,
    'requestedTotal', v_session.requested_total,
    'plannedNew', v_session.planned_new,
    'plannedReview', v_session.planned_review,
    'plannedPractice', v_session.planned_practice,
    'plannedTotal', v_session.planned_total,
    'completedActions', COALESCE((
      SELECT count(*)::integer
      FROM public.training_session_members member
      WHERE member.session_id = v_session.id AND member.consumed_at IS NOT NULL
    ), 0),
    'completionReason', v_session.completion_reason,
    'plannedAt', v_session.created_at,
    'members', COALESCE((
      SELECT jsonb_agg(jsonb_build_object(
        'ordinal', member.ordinal,
        'entryId', member.entry_id,
        'cardTypeId', member.card_type_id,
        'queueSource', member.queue_source,
        'consumedAt', member.consumed_at,
        'unavailableAt', member.unavailable_at,
        'unavailableReason', member.unavailable_reason
      ) ORDER BY member.ordinal)
      FROM public.training_session_members member
      WHERE member.session_id = v_session.id
    ), '[]'::jsonb)
  );
END;
$$;


--
-- Name: get_word_list_summary_owner_base_v1(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.get_word_list_summary_owner_base_v1(p_user_id uuid, p_list_id uuid, p_list_type text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF p_list_type = 'user' THEN
        SELECT jsonb_build_object(
            'id', l.id,
            'name', l.name,
            'description', l.description,
            'language_code', l.language_code,
            'primary_language_code', l.primary_language_code,
            'default_scenario_id', l.default_scenario_id,
            'card_policy', l.card_policy,
            'card_type_ids', l.card_type_ids,
            'created_at', l.created_at,
            'user_word_list_items', jsonb_build_array(jsonb_build_object(
                'count', (
                    SELECT COUNT(*)::int
                    FROM user_word_list_items item
                    WHERE item.list_id = l.id
                )
            ))
        )
        INTO v_result
        FROM user_word_lists l
        WHERE l.id = p_list_id
          AND l.user_id = p_user_id;

        RETURN v_result;
    END IF;

    SELECT jsonb_build_object(
        'id', l.id,
        'name', l.name,
        'description', l.description,
        'language_code', l.language_code,
        'primary_language_code', l.primary_language_code,
        'default_scenario_id', l.default_scenario_id,
        'card_policy', l.card_policy,
        'card_type_ids', l.card_type_ids,
        'is_primary', l.is_primary,
        'word_list_items', jsonb_build_array(jsonb_build_object(
            'count', (
                SELECT COUNT(*)::int
                FROM word_list_items item
                WHERE item.list_id = l.id
            )
        ))
    )
    INTO v_result
    FROM word_lists l
    WHERE l.id = p_list_id;

    RETURN v_result;
END;
$$;


--
-- Name: guard_shared_collection_delete_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_shared_collection_delete_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  PERFORM 1 FROM public.user_word_list_items item WHERE item.list_id=OLD.id ORDER BY item.word_id FOR UPDATE;
  PERFORM private.lock_sharing_author_scope_v1(OLD.user_id,true);
  PERFORM 1 FROM private.collection_sharing_roots root WHERE root.collection_id=OLD.id ORDER BY root.id FOR UPDATE;
  RETURN OLD;
END;
$$;


--
-- Name: guard_shared_collection_member_source_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.guard_shared_collection_member_source_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE root private.collection_sharing_roots%rowtype; collection_ids uuid[]; author uuid;
BEGIN
  IF TG_OP='INSERT' THEN collection_ids:=ARRAY[NEW.list_id];
  ELSIF TG_OP='DELETE' THEN collection_ids:=ARRAY[OLD.list_id];
  ELSE collection_ids:=ARRAY[OLD.list_id,NEW.list_id]; END IF;
  -- AFTER runs after RLS and immediate FK checks. Never take a parent lock
  -- from a row trigger: the membership tuple is already locked by its writer.
  FOR author IN SELECT DISTINCT r.owner_user_id FROM private.collection_sharing_roots r
    WHERE r.collection_id=ANY(collection_ids) ORDER BY r.owner_user_id LOOP
    PERFORM private.lock_sharing_author_scope_v1(author,true);
  END LOOP;
  PERFORM 1 FROM private.collection_sharing_roots r WHERE r.collection_id=ANY(collection_ids) ORDER BY r.id FOR UPDATE;
  IF TG_OP='DELETE' THEN RETURN OLD; END IF;
  SELECT * INTO root FROM private.collection_sharing_roots r WHERE r.collection_id=NEW.list_id;
  IF FOUND AND root.is_open AND EXISTS(SELECT 1 FROM public.word_entries e
    JOIN public.dictionaries d ON d.id=e.dictionary_id
    WHERE e.id=NEW.word_id AND d.kind='user' AND d.owner_user_id IS DISTINCT FROM root.owner_user_id) THEN
    RAISE EXCEPTION 'share_copy_required' USING ERRCODE='22023';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: independent_copy_snapshot_in_cohort_v1(uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.independent_copy_snapshot_in_cohort_v1(p_user_id uuid, p_source_entry_id uuid, p_cohort jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE source public.word_entries%rowtype; dictionary public.dictionaries%rowtype; source_dictionary_id uuid;
  roots uuid[]; owners uuid[]; source_owner_id uuid; material jsonb; grants jsonb; content jsonb; revision text;
BEGIN
  -- Freeze the candidate parent cohort before any child wait. Never expand it
  -- after waiting: a newly accepted teacher requires a fresh snapshot.
  SELECT dictionary_id INTO source_dictionary_id FROM public.word_entries WHERE id=p_source_entry_id;
  IF NOT FOUND OR source_dictionary_id IS NULL THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
  SELECT owner_user_id INTO source_owner_id FROM public.dictionaries WHERE id=source_dictionary_id;
  SELECT COALESCE(array_agg(root_id ORDER BY root_id),'{}'::uuid[]) INTO roots FROM(
    SELECT DISTINCT ON(scope.owner_user_id) scope.root_id
    FROM private.live_collection_sharing_subscriptions_v1 scope
    JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
    WHERE scope.user_id=p_user_id AND item.word_id=p_source_entry_id AND scope.owner_user_id<>p_user_id
    ORDER BY scope.owner_user_id,scope.root_id LIMIT 1001
  ) covering;
  IF cardinality(roots)>1000 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
  SELECT array_agg(id ORDER BY id) INTO owners FROM (
    SELECT p_user_id id UNION SELECT source_owner_id WHERE source_owner_id IS NOT NULL
    UNION SELECT owner_user_id FROM private.live_collection_sharing_subscriptions_v1 WHERE user_id=p_user_id AND root_id=ANY(roots)
  ) candidates;
  IF p_cohort IS NULL OR NOT(p_cohort->'entries' ? p_source_entry_id::text)
    OR NOT(p_cohort->'dictionaries' ? source_dictionary_id::text)
    OR EXISTS(SELECT 1 FROM unnest(owners) id WHERE NOT(p_cohort->'owners' ? id::text))
    OR EXISTS(SELECT 1 FROM unnest(roots) id WHERE NOT(p_cohort->'roots' ? id::text)) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  BEGIN
    PERFORM id FROM auth.users WHERE id=ANY(owners) ORDER BY id FOR KEY SHARE NOWAIT;
    IF (SELECT count(*) FROM auth.users WHERE id=ANY(owners))<>cardinality(owners) THEN
      RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
    END IF;
    SELECT * INTO dictionary FROM public.dictionaries WHERE id=source_dictionary_id FOR KEY SHARE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
    IF dictionary.owner_user_id IS DISTINCT FROM source_owner_id THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END;
  SELECT * INTO source FROM private.active_word_entries WHERE id=p_source_entry_id FOR UPDATE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
  IF source.dictionary_id IS DISTINCT FROM source_dictionary_id THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
  PERFORM root.id FROM private.collection_sharing_roots root WHERE root.id=ANY(roots) ORDER BY root.id FOR SHARE NOWAIT;
  IF EXISTS(SELECT 1 FROM private.live_collection_sharing_subscriptions_v1
    WHERE user_id=p_user_id AND root_id=ANY(roots) AND NOT(owner_user_id=ANY(owners))) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  SELECT * INTO dictionary FROM public.dictionaries WHERE id=source.dictionary_id;
  IF dictionary.owner_user_id IS DISTINCT FROM source_owner_id THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
  IF source.dictionary_id IS NULL OR NOT private.entry_access_v1(p_user_id,source.id,'browse') THEN
    RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501';
  END IF;
  IF dictionary.kind='user' AND dictionary.owner_user_id IS DISTINCT FROM p_user_id AND NOT EXISTS(
    SELECT 1 FROM private.shared_author_entry_memberships_v1 membership
    WHERE membership.user_id=p_user_id AND membership.entry_id=source.id AND membership.root_id=ANY(roots)) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  -- Preserve present-note serialization, including trusted maintenance writes.
  PERFORM note.id FROM public.user_word_notes note WHERE note.word_entry_id=source.id
    AND (note.user_id=p_user_id OR EXISTS(SELECT 1 FROM private.live_collection_sharing_subscriptions_v1 scope
      JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
      WHERE scope.user_id=p_user_id AND scope.owner_user_id=note.user_id AND item.word_id=source.id AND scope.root_id=ANY(roots)))
    ORDER BY note.user_id FOR SHARE NOWAIT;
  BEGIN
    material:=private.entry_note_scope_material_v1(p_user_id,ARRAY[source.id]);
  EXCEPTION WHEN SQLSTATE '22023' THEN
    IF SQLERRM='note_material_too_large' THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
    RAISE;
  END;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(material) note WHERE NOT (note->>'isOwn')::boolean AND NOT EXISTS(
    SELECT 1 FROM private.live_collection_sharing_subscriptions_v1 scope
    JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
    WHERE scope.user_id=p_user_id AND scope.owner_user_id=(note->>'ownerUserId')::uuid
      AND item.word_id=source.id AND scope.root_id=ANY(roots))) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('rootId',root.id,'lifetime',root.access_lifetime) ORDER BY root.id),'[]') INTO grants
  FROM private.live_collection_sharing_subscriptions_v1 scope JOIN private.collection_sharing_roots root ON root.id=scope.root_id
  JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
  WHERE scope.user_id=p_user_id AND item.word_id=source.id AND root.id=ANY(roots);
  content:=private.copy_source_content_v1(source.raw,private.flatten_copy_note_overlays_v1(source.raw,material),dictionary.kind);
  content:=content||jsonb_strip_nulls(jsonb_build_object('headword',source.headword,'languageCode',source.language_code,
    'partOfSpeech',source.part_of_speech,'gender',source.gender));
  content:=public.validate_user_entry_v1_payload(content,source.language_code);
  revision:=encode(sha256(convert_to(jsonb_build_object('contract','direct-instructional-copy-v1',
    'version',source.content_version,'raw',source.raw,'headword',source.headword,'language',source.language_code,
    'pos',source.part_of_speech,'gender',source.gender,'dictionaryId',dictionary.id,'dictionaryKind',dictionary.kind,
    'dictionaryOwner',dictionary.owner_user_id,'notes',material,'grants',grants)::text,'UTF8')),'hex');
  RETURN jsonb_build_object('content',content,'revision',revision,'sourceDictionaryName',dictionary.name,'sourceDictionaryId',dictionary.id);
END;
$$;


--
-- Name: independent_copy_snapshot_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.independent_copy_snapshot_v1(p_user_id uuid, p_source_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE source public.word_entries%rowtype; note public.user_word_notes%rowtype;
  note_revision bigint; content jsonb; dictionary_name text; dictionary_kind text; revision text;
BEGIN
  SELECT * INTO source FROM private.active_word_entries
    WHERE id=p_source_entry_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
  IF source.dictionary_id IS NULL OR NOT public.can_browse_dictionary(p_user_id,source.dictionary_id) THEN
    RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501';
  END IF;
  SELECT name,kind INTO dictionary_name,dictionary_kind FROM public.dictionaries WHERE id=source.dictionary_id;
  -- The source row lock also serializes FK insertion of a previously absent note.
  -- Only the caller's authorized overlay participates at this stage.
  SELECT * INTO note FROM public.user_word_notes
    WHERE word_entry_id=source.id AND user_id=p_user_id FOR SHARE;
  SELECT COALESCE((SELECT clock.revision FROM private.user_word_note_revisions clock WHERE clock.user_id=p_user_id AND clock.word_entry_id=source.id),0) INTO note_revision;
  content:=private.copy_source_content_v1(source.raw,note.notes,dictionary_kind);
  content:=content||jsonb_strip_nulls(jsonb_build_object(
    'headword',source.headword,'languageCode',source.language_code,
    'partOfSpeech',source.part_of_speech,'gender',source.gender));
  content:=public.validate_user_entry_v1_payload(content,source.language_code);
  revision:=encode(sha256(convert_to(jsonb_build_object(
    'version',source.content_version,'raw',source.raw,'headword',source.headword,
    'language',source.language_code,'pos',source.part_of_speech,'gender',source.gender,
    'noteId',note.id,'note',note.notes,'noteUpdatedAt',note.updated_at,'noteRevision',note_revision)::text,'UTF8')),'hex');
  RETURN jsonb_build_object('content',content,'revision',revision,
    'sourceDictionaryName',dictionary_name,'sourceDictionaryId',source.dictionary_id);
END;
$$;


--
-- Name: independent_copy_snapshot_with_notes_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.independent_copy_snapshot_with_notes_v1(p_user_id uuid, p_source_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE source public.word_entries%rowtype; dictionary public.dictionaries%rowtype; source_dictionary_id uuid;
  roots uuid[]; owners uuid[]; source_owner_id uuid; material jsonb; grants jsonb; content jsonb; revision text;
BEGIN
  -- Freeze the candidate parent cohort before any child wait. Never expand it
  -- after waiting: a newly accepted teacher requires a fresh snapshot.
  SELECT dictionary_id INTO source_dictionary_id FROM public.word_entries WHERE id=p_source_entry_id;
  IF NOT FOUND OR source_dictionary_id IS NULL THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
  SELECT owner_user_id INTO source_owner_id FROM public.dictionaries WHERE id=source_dictionary_id;
  SELECT COALESCE(array_agg(root_id ORDER BY root_id),'{}'::uuid[]) INTO roots FROM(
    SELECT DISTINCT ON(scope.owner_user_id) scope.root_id
    FROM private.live_collection_sharing_subscriptions_v1 scope
    JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
    WHERE scope.user_id=p_user_id AND item.word_id=p_source_entry_id AND scope.owner_user_id<>p_user_id
    ORDER BY scope.owner_user_id,scope.root_id LIMIT 1001
  ) covering;
  IF cardinality(roots)>1000 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
  SELECT array_agg(id ORDER BY id) INTO owners FROM (
    SELECT p_user_id id UNION SELECT source_owner_id WHERE source_owner_id IS NOT NULL
    UNION SELECT owner_user_id FROM private.live_collection_sharing_subscriptions_v1 WHERE user_id=p_user_id AND root_id=ANY(roots)
  ) candidates;
  BEGIN
    PERFORM id FROM auth.users WHERE id=ANY(owners) ORDER BY id FOR KEY SHARE NOWAIT;
    IF (SELECT count(*) FROM auth.users WHERE id=ANY(owners))<>cardinality(owners) THEN
      RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
    END IF;
    SELECT * INTO dictionary FROM public.dictionaries WHERE id=source_dictionary_id FOR KEY SHARE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
    IF dictionary.owner_user_id IS DISTINCT FROM source_owner_id THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
  EXCEPTION WHEN lock_not_available THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END;
  SELECT * INTO source FROM private.active_word_entries WHERE id=p_source_entry_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
  IF source.dictionary_id IS DISTINCT FROM source_dictionary_id THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
  PERFORM root.id FROM private.collection_sharing_roots root WHERE root.id=ANY(roots) ORDER BY root.id FOR SHARE;
  IF EXISTS(SELECT 1 FROM private.live_collection_sharing_subscriptions_v1
    WHERE user_id=p_user_id AND root_id=ANY(roots) AND NOT(owner_user_id=ANY(owners))) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  SELECT * INTO dictionary FROM public.dictionaries WHERE id=source.dictionary_id;
  IF dictionary.owner_user_id IS DISTINCT FROM source_owner_id THEN RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001'; END IF;
  IF source.dictionary_id IS NULL OR NOT private.entry_access_v1(p_user_id,source.id,'browse') THEN
    RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501';
  END IF;
  IF dictionary.kind='user' AND dictionary.owner_user_id IS DISTINCT FROM p_user_id AND NOT EXISTS(
    SELECT 1 FROM private.shared_author_entry_memberships_v1 membership
    WHERE membership.user_id=p_user_id AND membership.entry_id=source.id AND membership.root_id=ANY(roots)) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  -- Preserve present-note serialization, including trusted maintenance writes.
  PERFORM note.id FROM public.user_word_notes note WHERE note.word_entry_id=source.id
    AND (note.user_id=p_user_id OR EXISTS(SELECT 1 FROM private.live_collection_sharing_subscriptions_v1 scope
      JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
      WHERE scope.user_id=p_user_id AND scope.owner_user_id=note.user_id AND item.word_id=source.id AND scope.root_id=ANY(roots)))
    ORDER BY note.user_id FOR SHARE;
  BEGIN
    material:=private.entry_note_scope_material_v1(p_user_id,ARRAY[source.id]);
  EXCEPTION WHEN SQLSTATE '22023' THEN
    IF SQLERRM='note_material_too_large' THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
    RAISE;
  END;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(material) note WHERE NOT (note->>'isOwn')::boolean AND NOT EXISTS(
    SELECT 1 FROM private.live_collection_sharing_subscriptions_v1 scope
    JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
    WHERE scope.user_id=p_user_id AND scope.owner_user_id=(note->>'ownerUserId')::uuid
      AND item.word_id=source.id AND scope.root_id=ANY(roots))) THEN
    RAISE EXCEPTION 'copy_source_changed' USING ERRCODE='40001';
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('rootId',root.id,'lifetime',root.access_lifetime) ORDER BY root.id),'[]') INTO grants
  FROM private.live_collection_sharing_subscriptions_v1 scope JOIN private.collection_sharing_roots root ON root.id=scope.root_id
  JOIN public.user_word_list_items item ON item.list_id=scope.collection_id
  WHERE scope.user_id=p_user_id AND item.word_id=source.id AND root.id=ANY(roots);
  content:=private.copy_source_content_v1(source.raw,private.flatten_copy_note_overlays_v1(source.raw,material),dictionary.kind);
  content:=content||jsonb_strip_nulls(jsonb_build_object('headword',source.headword,'languageCode',source.language_code,
    'partOfSpeech',source.part_of_speech,'gender',source.gender));
  content:=public.validate_user_entry_v1_payload(content,source.language_code);
  revision:=encode(sha256(convert_to(jsonb_build_object('contract','direct-instructional-copy-v1',
    'version',source.content_version,'raw',source.raw,'headword',source.headword,'language',source.language_code,
    'pos',source.part_of_speech,'gender',source.gender,'dictionaryId',dictionary.id,'dictionaryKind',dictionary.kind,
    'dictionaryOwner',dictionary.owner_user_id,'notes',material,'grants',grants)::text,'UTF8')),'hex');
  RETURN jsonb_build_object('content',content,'revision',revision,'sourceDictionaryName',dictionary.name,'sourceDictionaryId',dictionary.id);
END;
$$;


--
-- Name: is_pointer_only_dictionary_entry_v1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.is_pointer_only_dictionary_entry_v1(p_raw jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT COALESCE(
        NULLIF(BTRIM(p_raw ->> 'cross_reference'), '') IS NOT NULL
        AND CASE
            WHEN jsonb_typeof(p_raw -> 'meanings') = 'array'
                THEN jsonb_array_length(p_raw -> 'meanings') = 0
            ELSE true
        END,
        false
    );
$$;


--
-- Name: jsonb_has_exact_keys(jsonb, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.jsonb_has_exact_keys(p_value jsonb, p_keys text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT jsonb_typeof(p_value) = 'object'
     AND p_value ?& p_keys
     AND (SELECT count(*) FROM jsonb_object_keys(p_value)) = cardinality(p_keys)
$$;


--
-- Name: known_meaning_familiarity_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.known_meaning_familiarity_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
 IF NEW.card_type_id IN ('word-to-definition','definition-to-word') THEN
  PERFORM private.enroll_familiar_meaning_directions_v1(NEW.user_id,NEW.entry_id);
 END IF;
 RETURN NEW;
END;$$;


--
-- Name: library_entry_matches_filters_v1(text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.library_entry_matches_filters_v1(p_part text, p_gender text, p_selection jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  WITH normalized AS (
    SELECT CASE lower(trim(COALESCE(p_part,'')))
      WHEN 'zn' THEN 'noun' WHEN 'ww' THEN 'verb' WHEN 'bn' THEN 'adjective'
      WHEN 'bw' THEN 'adverb' WHEN 'vnw' THEN 'pronoun' WHEN 'vz' THEN 'preposition'
      WHEN 'vw' THEN 'conjunction' WHEN 'tw' THEN 'numeral' WHEN 'lidw' THEN 'article'
      WHEN 'tsw' THEN 'interjection' ELSE lower(trim(COALESCE(p_part,''))) END AS part
  )
  SELECT (p_selection->'parts'='[]'::jsonb OR (p_selection->'parts') ? part)
    AND (p_selection->>'article' IS NULL OR part<>'noun'
      OR (p_selection->>'article')=ANY(regexp_split_to_array(lower(trim(COALESCE(p_gender,''))), '\s*[/,]\s*')))
  FROM normalized;
$$;


--
-- Name: library_material_entry_ids_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.library_material_entry_ids_v1(p_user_id uuid, p_material jsonb) RETURNS TABLE(entry_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  WITH RECURSIVE labels AS (
    SELECT id FROM private.collection_labels
    WHERE user_id=p_user_id AND id=(p_material->>'id')::uuid AND p_material->>'kind'='label'
    UNION
    SELECT child.id FROM private.collection_labels child
    JOIN labels parent ON child.parent_id=parent.id WHERE child.user_id=p_user_id
  ), collections AS (
    SELECT list.id FROM public.user_word_lists list
    WHERE (list.user_id=p_user_id OR EXISTS (
      SELECT 1 FROM private.shared_collection_ids_v1(p_user_id) shared
      WHERE shared.collection_id=list.id
    )) AND p_material->>'kind'='collection'
      AND p_material->>'collectionType'='user' AND list.id=(p_material->>'id')::uuid
    UNION
    SELECT assignment.collection_id FROM private.collection_label_assignments assignment
    JOIN labels ON labels.id=assignment.label_id WHERE assignment.user_id=p_user_id
    UNION
    SELECT placement.collection_id FROM private.received_collection_label_placements placement
    JOIN labels ON labels.id=placement.label_id
    JOIN private.live_collection_sharing_subscriptions_v1 scope ON scope.collection_id=placement.collection_id
      AND scope.user_id=placement.user_id
    WHERE placement.user_id=p_user_id
  )
  SELECT DISTINCT item.word_id FROM public.user_word_list_items item
  JOIN collections ON collections.id=item.list_id
  UNION
  SELECT item.word_id FROM public.word_list_items item
  WHERE p_material->>'kind'='collection' AND p_material->>'collectionType'='curated'
    AND item.list_id=(p_material->>'id')::uuid;
$$;


--
-- Name: lock_shared_learning_source_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_shared_learning_source_v1(p_user uuid, p_entry uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE author uuid;
BEGIN
  -- Match ACK/archive ordering before consulting mutable sharing authority.
  PERFORM entry.id FROM public.word_entries entry WHERE entry.id=p_entry FOR SHARE;
  SELECT dictionary.owner_user_id INTO author FROM public.word_entries entry
  JOIN public.dictionaries dictionary ON dictionary.id=entry.dictionary_id
  WHERE entry.id=p_entry AND dictionary.kind='user' AND dictionary.owner_user_id IS DISTINCT FROM p_user;
  PERFORM private.lock_sharing_author_scope_v1(author,false);
END;
$$;


--
-- Name: lock_sharing_author_scope_v1(uuid, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lock_sharing_author_scope_v1(p_author uuid, p_exclusive boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
BEGIN
  IF p_author IS NULL THEN RETURN; END IF;
  IF p_exclusive THEN
    PERFORM pg_advisory_xact_lock(hashtextextended('collection-author-scope:'||p_author::text,0));
  ELSE
    PERFORM pg_advisory_xact_lock_shared(hashtextextended('collection-author-scope:'||p_author::text,0));
  END IF;
END;
$$;


--
-- Name: lookup_platform_v2_entries_base_v1(uuid, boolean, text, text, text, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lookup_platform_v2_entries_base_v1(p_user_id uuid, p_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text :=
        NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_group_limit integer :=
        LEAST(GREATEST(COALESCE(p_group_limit, 10), 1), 25);
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_cursor jsonb :=
        private.decode_dictionary_search_cursor_v1(p_cursor);
    v_query_key text;
    v_cursor_tier_rank integer;
    v_cursor_match_rank integer;
    v_cursor_dictionary_rank integer;
    v_cursor_sort_headword text;
    v_cursor_group_id uuid;
    v_items jsonb;
    v_has_more boolean;
    v_next_cursor text;
    v_missing_identity_count integer;
    v_oversized_group jsonb;
BEGIN
    IF p_catalog AND p_user_id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF NOT p_catalog AND p_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF v_raw_query IS NULL THEN
        RETURN jsonb_build_object(
            'query', p_query,
            'items', '[]'::jsonb,
            'page', jsonb_build_object(
                'selectedTierComplete', true,
                'nextGroupCursor', NULL
            )
        );
    END IF;

    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent :=
        normalize_dictionary_search_text_unaccent(v_raw_query);
    v_query_key := encode(
        digest(
            concat_ws(
                chr(31),
                'platform-v2-group-cursor-v1',
                COALESCE(p_user_id::text, 'catalog'),
                p_catalog::text,
                v_raw_query,
                v_query,
                v_query_unaccent,
                COALESCE(v_language_code, '')
            ),
            'sha256'
        ),
        'hex'
    );

    IF NULLIF(trim(COALESCE(p_cursor, '')), '') IS NOT NULL THEN
        IF v_cursor = '{}'::jsonb
           OR v_cursor->>'version' <> 'platform-v2-group-cursor-v1'
           OR v_cursor->>'queryKey' IS DISTINCT FROM v_query_key THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
        BEGIN
            v_cursor_tier_rank := (v_cursor->>'tierRank')::integer;
            v_cursor_match_rank := (v_cursor->>'matchRank')::integer;
            v_cursor_dictionary_rank :=
                (v_cursor->>'dictionaryRank')::integer;
            v_cursor_sort_headword := v_cursor->>'sortHeadword';
            v_cursor_group_id := (v_cursor->>'headwordGroupId')::uuid;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END;
        IF v_cursor_sort_headword IS NULL
           OR v_cursor_group_id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
    END IF;

    IF p_catalog
       AND EXISTS (
           SELECT 1
           FROM private.active_word_entries AS entry
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = entry.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR entry.language_code = v_language_code
             )
           LIMIT 1
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.dictionary_search_documents AS document
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = document.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR document.language_code = v_language_code
             )
           LIMIT 1
       ) THEN
        RETURN jsonb_build_object('error', 'search_index_not_ready');
    END IF;

    WITH user_context AS MATERIALIZED (
        SELECT COALESCE(
            (
                SELECT subscription_tier
                FROM public.user_settings
                WHERE user_id = p_user_id
            ),
            'free'
        ) AS subscription_tier
    ),
    eligible_dictionaries AS MATERIALIZED (
        SELECT
            dictionary.*,
            CASE
                WHEN NOT p_catalog AND dictionary.kind = 'user'
                     AND dictionary.owner_user_id = p_user_id THEN 0
                WHEN dictionary.kind = 'curated' THEN 1
                ELSE 2
            END AS dictionary_rank
        FROM public.dictionaries AS dictionary
        WHERE (p_catalog
               AND dictionary.visibility IN ('system', 'public')
               AND dictionary.kind <> 'user')
           OR (NOT p_catalog
               AND public.can_browse_dictionary(p_user_id, dictionary.id))
    ),
    indexed_headword_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'exact-headword'::text AS resolved_by,
            document.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id
        WHERE (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND document.normalized_headword = v_query

        UNION ALL

        SELECT
            document.entry_id,
            'exact-headword'::text,
            document.headword,
            1,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id
        WHERE (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND document.normalized_headword_unaccent =
              v_query_unaccent
          AND document.normalized_headword <> v_query
    ),
    legacy_user_headword_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'exact-headword'::text AS resolved_by,
            entry.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN entry.headword = v_raw_query THEN 0
                WHEN lower(entry.headword) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM private.active_word_entries AS entry
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE NOT p_catalog
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR entry.language_code = v_language_code
          )
          AND (
              lower(entry.headword) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(
                  entry.headword
              ) = v_query_unaccent
          )
    ),
    headword_matches AS MATERIALIZED (
        SELECT * FROM indexed_headword_matches
        UNION ALL
        SELECT * FROM legacy_user_headword_matches
    ),
    headword_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM headword_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.headword),
            match.meaning_id
    ),
    indexed_form_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            field.display_text AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text = v_query

        UNION ALL

        SELECT
            document.entry_id,
            'lemma-or-inflection'::text,
            field.display_text,
            2,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text_unaccent = v_query_unaccent
          AND field.normalized_text <> v_query
    ),
    legacy_user_form_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            form.form AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN form.form = v_raw_query THEN 0
                WHEN lower(form.form) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM public.word_forms AS form
        JOIN private.active_word_entries AS entry
          ON entry.id = form.word_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE NOT p_catalog
          AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR form.language_code = v_language_code
          )
          AND form.language_code = entry.language_code
          AND (
              form.dictionary_id IS NULL
              OR form.dictionary_id = entry.dictionary_id
          )
          AND (
              lower(form.form) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(form.form) =
                  v_query_unaccent
          )
    ),
    form_matches AS MATERIALIZED (
        SELECT * FROM indexed_form_matches
        UNION ALL
        SELECT * FROM legacy_user_form_matches
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM form_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.matched_text)
    ),
    candidates AS MATERIALIZED (
        SELECT * FROM headword_candidates
        UNION ALL
        SELECT * FROM form_candidates
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
    ),
    candidate_identity AS MATERIALIZED (
        SELECT
            candidate.*,
            dictionary.dictionary_rank,
            COALESCE(
                source_group.id,
                user_group.id
            ) AS headword_group_id
        FROM candidates AS candidate
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = candidate.dictionary_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON binding.word_entry_id = candidate.entry_id
         AND binding.binding_state = 'active'
        LEFT JOIN private.platform_v2_headword_groups AS source_group
          ON source_group.management_kind = 'source'
         AND source_group.dictionary_id = binding.dictionary_id
         AND source_group.identity_scheme_version =
             binding.identity_scheme_version
         AND source_group.source_group_key = binding.source_group_key
        LEFT JOIN private.platform_v2_headword_groups AS user_group
          ON user_group.management_kind = 'user'
         AND user_group.singleton_entry_id = candidate.entry_id
    ),
    candidate_groups AS MATERIALIZED (
        SELECT
            headword_group_id,
            min(tier_rank) AS tier_rank,
            min(match_rank) AS match_rank,
            min(dictionary_rank) AS dictionary_rank,
            min(normalize_dictionary_search_text(headword))
                AS sort_headword,
            (array_agg(
                resolved_by
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS resolved_by,
            (array_agg(
                matched_text
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS matched_text
        FROM candidate_identity
        WHERE headword_group_id IS NOT NULL
        GROUP BY headword_group_id
    ),
    after_cursor AS MATERIALIZED (
        SELECT *
        FROM candidate_groups
        WHERE v_cursor_group_id IS NULL
           OR (
                tier_rank,
                match_rank,
                dictionary_rank,
                sort_headword,
                headword_group_id
           ) > (
                v_cursor_tier_rank,
                v_cursor_match_rank,
                v_cursor_dictionary_rank,
                v_cursor_sort_headword,
                v_cursor_group_id
           )
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit + 1
    ),
    returned_groups AS MATERIALIZED (
        SELECT *
        FROM after_cursor
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit
    ),
    group_entry_ids AS MATERIALIZED (
        SELECT
            group_page.*,
            entry.id AS entry_id,
            COALESCE(binding.sense_ordinal, entry.meaning_id)
                AS group_meaning_order
        FROM returned_groups AS group_page
        JOIN private.platform_v2_headword_groups AS headword_group
          ON headword_group.id = group_page.headword_group_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
         AND binding.binding_state = 'active'
        JOIN private.active_word_entries AS entry
          ON entry.id = COALESCE(
              binding.word_entry_id,
              headword_group.singleton_entry_id
          )
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
    ),
    group_sizes AS MATERIALIZED (
        SELECT
            headword_group_id,
            count(*)::integer AS entry_count
        FROM group_entry_ids
        GROUP BY headword_group_id
    ),
    oversized_groups AS MATERIALIZED (
        SELECT jsonb_build_object(
            'headwordGroupId', size.headword_group_id,
            'entryCount', size.entry_count,
            'safetyBound', v_group_entry_bound
        ) AS error_payload
        FROM group_sizes AS size
        WHERE size.entry_count > v_group_entry_bound
        ORDER BY size.entry_count DESC, size.headword_group_id
        LIMIT 1
    ),
    group_entries AS MATERIALIZED (
        SELECT
            member.tier_rank,
            member.match_rank,
            member.dictionary_rank,
            member.sort_headword,
            member.resolved_by,
            member.matched_text,
            member.headword_group_id,
            member.group_meaning_order,
            entry.*,
            dictionary.language_code AS dictionary_language_code,
            dictionary.slug AS dictionary_slug,
            dictionary.name AS dictionary_name,
            dictionary.kind AS dictionary_kind,
            dictionary.visibility AS dictionary_visibility,
            dictionary.owner_user_id AS dictionary_owner_user_id,
            dictionary.is_editable AS dictionary_is_editable,
            dictionary.schema_key AS dictionary_schema_key,
            dictionary.schema_version AS dictionary_schema_version
        FROM group_entry_ids AS member
        JOIN private.active_word_entries AS entry
          ON entry.id = member.entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
        WHERE NOT EXISTS (SELECT 1 FROM oversized_groups)
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', entry.id,
                'dictionary_id', entry.dictionary_id,
                'language_code', entry.language_code,
                'headword', entry.headword,
                'meaning_id', entry.meaning_id,
                'part_of_speech', entry.part_of_speech,
                'gender', entry.gender,
                'raw', entry.raw,
                'is_nt2_2000', entry.is_nt2_2000,
                'meanings_count', size.entry_count,
                'dictionary', jsonb_build_object(
                    'id', entry.dictionary_id,
                    'language_code', entry.dictionary_language_code,
                    'slug', entry.dictionary_slug,
                    'name', entry.dictionary_name,
                    'kind', entry.dictionary_kind,
                    'visibility', entry.dictionary_visibility,
                    'owner_user_id',
                        entry.dictionary_owner_user_id,
                    'is_editable', entry.dictionary_is_editable,
                    'schema_key', entry.dictionary_schema_key,
                    'schema_version',
                        entry.dictionary_schema_version
                ),
                'dictionary_name', entry.dictionary_name,
                'dictionary_slug', entry.dictionary_slug,
                'dictionary_kind', entry.dictionary_kind,
                'search_match_group', entry.resolved_by,
                'search_matched_text', entry.matched_text
            )) AS payload,
            entry.tier_rank,
            entry.match_rank,
            entry.dictionary_rank,
            entry.sort_headword,
            entry.headword_group_id,
            entry.group_meaning_order,
            entry.id
        FROM group_entries AS entry
        JOIN group_sizes AS size
          ON size.headword_group_id = entry.headword_group_id
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    payload
                    ORDER BY
                        tier_rank,
                        match_rank,
                        dictionary_rank,
                        sort_headword,
                        headword_group_id,
                        group_meaning_order,
                        id
                )
                FROM payloads
            ),
            '[]'::jsonb
        ),
        (SELECT count(*) > v_group_limit FROM after_cursor),
        (
            SELECT private.encode_dictionary_search_cursor_v1(
                jsonb_build_object(
                    'version', 'platform-v2-group-cursor-v1',
                    'queryKey', v_query_key,
                    'tierRank', tier_rank,
                    'matchRank', match_rank,
                    'dictionaryRank', dictionary_rank,
                    'sortHeadword', sort_headword,
                    'headwordGroupId', headword_group_id
                )
            )
            FROM returned_groups
            ORDER BY
                tier_rank DESC,
                match_rank DESC,
                dictionary_rank DESC,
                sort_headword DESC,
                headword_group_id DESC
            LIMIT 1
        ),
        (
            SELECT count(*)::integer
            FROM candidate_identity
            WHERE headword_group_id IS NULL
        ),
        (
            SELECT error_payload
            FROM oversized_groups
        )
    INTO
        v_items,
        v_has_more,
        v_next_cursor,
        v_missing_identity_count,
        v_oversized_group;

    IF v_missing_identity_count > 0 THEN
        RETURN jsonb_build_object(
            'error', 'presentation_identity_incomplete'
        );
    END IF;
    IF v_oversized_group IS NOT NULL THEN
        RETURN jsonb_build_object(
            'error', 'group-too-large',
            'group', v_oversized_group
        );
    END IF;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'selectedTierComplete', NOT COALESCE(v_has_more, false),
            'nextGroupCursor', CASE
                WHEN COALESCE(v_has_more, false) THEN v_next_cursor
                ELSE NULL
            END
        )
    );
END;
$$;


--
-- Name: lookup_platform_v2_library_browse_entries_v1(uuid, boolean, text, text, text, integer, integer, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lookup_platform_v2_library_browse_entries_v1(p_user_id uuid, p_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50, p_library_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text :=
        NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_group_limit integer :=
        LEAST(GREATEST(COALESCE(p_group_limit, 10), 1), 25);
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_cursor jsonb :=
        private.decode_dictionary_search_cursor_v1(p_cursor);
    v_query_key text;
    v_cursor_tier_rank integer;
    v_cursor_match_rank integer;
    v_cursor_dictionary_rank integer;
    v_cursor_sort_headword text;
    v_cursor_group_id uuid;
    v_items jsonb;
    v_has_more boolean;
    v_next_cursor text;
    v_missing_identity_count integer;
    v_total_groups integer; v_oversized_group jsonb;
BEGIN
    IF p_catalog AND p_user_id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF NOT p_catalog AND p_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF v_raw_query IS NOT NULL THEN RETURN jsonb_build_object('error','browse_query_required'); END IF;
    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent :=
        normalize_dictionary_search_text_unaccent(v_raw_query);
    v_query_key := encode(
        digest(
            concat_ws(
                chr(31),
                'platform-v2-group-cursor-v1',
                COALESCE(p_user_id::text, 'catalog'),
                p_catalog::text,
                v_raw_query,
                v_query,
                v_query_unaccent,
                COALESCE(v_language_code, ''), p_library_selection::text
            ),
            'sha256'
        ),
        'hex'
    );

    IF NULLIF(trim(COALESCE(p_cursor, '')), '') IS NOT NULL THEN
        IF v_cursor = '{}'::jsonb
           OR v_cursor->>'version' <> 'platform-v2-group-cursor-v1'
           OR v_cursor->>'queryKey' IS DISTINCT FROM v_query_key THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
        BEGIN
            v_cursor_tier_rank := (v_cursor->>'tierRank')::integer;
            v_cursor_match_rank := (v_cursor->>'matchRank')::integer;
            v_cursor_dictionary_rank :=
                (v_cursor->>'dictionaryRank')::integer;
            v_cursor_sort_headword := v_cursor->>'sortHeadword';
            v_cursor_group_id := (v_cursor->>'headwordGroupId')::uuid;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END;
        IF v_cursor_sort_headword IS NULL
           OR v_cursor_group_id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
    END IF;

    IF p_catalog
       AND EXISTS (
           SELECT 1
           FROM private.active_word_entries AS entry
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = entry.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR entry.language_code = v_language_code
             )
           LIMIT 1
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.dictionary_search_documents AS document
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = document.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR document.language_code = v_language_code
             )
           LIMIT 1
       ) THEN
        RETURN jsonb_build_object('error', 'search_index_not_ready');
    END IF;

    WITH shared_entries AS MATERIALIZED (
      SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(p_user_id) shared WHERE NOT p_catalog
    ), shared_dictionaries AS MATERIALIZED (
      SELECT DISTINCT entry.dictionary_id FROM shared_entries shared
      JOIN private.active_word_entries entry ON entry.id=shared.entry_id
    ), user_context AS MATERIALIZED (
        SELECT COALESCE(
            (
                SELECT subscription_tier
                FROM public.user_settings
                WHERE user_id = p_user_id
            ),
            'free'
        ) AS subscription_tier
    ),
    eligible_dictionaries AS MATERIALIZED (
      SELECT dictionary.*, CASE WHEN dictionary.kind='user' THEN 0 WHEN dictionary.kind='curated' THEN 1 ELSE 2 END AS dictionary_rank
      FROM public.dictionaries dictionary
      WHERE private.training_material_entry_selected_v1(dictionary.language_code,
        CASE WHEN dictionary.kind='user' THEN NULL ELSE dictionary.id END,p_library_selection)
        AND (p_library_selection->'dictionaryIds'='null'::jsonb OR (p_library_selection->'dictionaryIds') ? dictionary.id::text)
        AND ((p_catalog AND dictionary.publication_state='general' AND dictionary.kind<>'user')
          OR (NOT p_catalog AND (
            (public.can_browse_dictionary(p_user_id, dictionary.id) AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id))
            OR (dictionary.kind='user' AND dictionary.id IN (SELECT dictionary_id FROM shared_dictionaries)))))
    ),
    -- Empty browse has one headword tier. Do not sort/deduplicate the same
    -- primary-key document stream through the exact/form search tiers.
    candidates AS MATERIALIZED (
        -- Separate guarded branches also skip wide entry reads in a cached
        -- generic plan, where an optional LEFT JOIN would still scan its heap.
        SELECT document.entry_id, document.headword, document.meaning_id,
            document.dictionary_id, normalize_dictionary_search_text(document.headword) AS sort_headword,
            'exact-headword'::text AS resolved_by, document.headword AS matched_text,
            1 AS tier_rank, CASE WHEN document.normalized_headword=v_query THEN 1 ELSE 2 END AS match_rank
        FROM public.dictionary_search_documents document
        JOIN eligible_dictionaries dictionary ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        WHERE p_library_selection->'parts'='[]'::jsonb AND p_library_selection->>'article' IS NULL
          AND (v_language_code IS NULL OR document.language_code=v_language_code)
        UNION ALL
        SELECT document.entry_id, document.headword, document.meaning_id,
            document.dictionary_id, normalize_dictionary_search_text(document.headword) AS sort_headword,
            'exact-headword'::text AS resolved_by, document.headword AS matched_text,
            1 AS tier_rank, CASE WHEN document.normalized_headword=v_query THEN 1 ELSE 2 END AS match_rank
        FROM public.dictionary_search_documents document
        JOIN eligible_dictionaries dictionary ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        JOIN private.active_word_entries filter_entry ON filter_entry.id=document.entry_id
        WHERE NOT (p_library_selection->'parts'='[]'::jsonb AND p_library_selection->>'article' IS NULL)
          AND (v_language_code IS NULL OR document.language_code=v_language_code)
          AND private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection)
        UNION ALL
        SELECT entry.id, entry.headword, entry.meaning_id, entry.dictionary_id,
            normalize_dictionary_search_text(entry.headword),
            'exact-headword'::text, entry.headword, 1, 2
        FROM private.active_word_entries entry
        JOIN eligible_dictionaries dictionary ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        LEFT JOIN public.dictionary_search_documents document ON document.entry_id=entry.id
        WHERE NOT p_catalog AND dictionary.kind='user' AND document.entry_id IS NULL
          AND EXISTS (SELECT 1 FROM eligible_dictionaries WHERE kind='user')
          AND (v_language_code IS NULL OR entry.language_code=v_language_code)
          AND private.library_entry_matches_filters_v1(entry.part_of_speech,entry.gender,p_library_selection)
    ),
    -- Resolve identities in one narrow pass. Candidate CTE cardinality estimates
    -- otherwise turn a catalogue browse into tens of thousands of index probes.
    source_identities AS MATERIALIZED (
        SELECT binding.word_entry_id, source_group.id
        FROM private.source_entry_bindings binding
        JOIN eligible_dictionaries dictionary ON dictionary.id=binding.dictionary_id
        JOIN private.platform_v2_headword_groups source_group
          ON source_group.management_kind='source'
         AND source_group.dictionary_id=binding.dictionary_id
         AND source_group.identity_scheme_version=binding.identity_scheme_version
         AND source_group.source_group_key=binding.source_group_key
        WHERE binding.binding_state='active'
    ),
    candidate_identity AS MATERIALIZED (
        SELECT candidate.*, 0 AS dictionary_rank,
            COALESCE(source_identity.id,user_group.id) AS headword_group_id
        FROM candidates candidate
        LEFT JOIN source_identities source_identity ON source_identity.word_entry_id=candidate.entry_id
        LEFT JOIN private.platform_v2_headword_groups user_group
          ON user_group.management_kind='user' AND user_group.singleton_entry_id=candidate.entry_id
    ),
    candidate_groups AS MATERIALIZED (
        SELECT
            headword_group_id,
            min(tier_rank) AS tier_rank,
            min(match_rank) AS match_rank,
            min(dictionary_rank) AS dictionary_rank,
            min(sort_headword)
                AS sort_headword,
            (array_agg(
                resolved_by
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    sort_headword,
                    entry_id
            ))[1] AS resolved_by,
            (array_agg(
                matched_text
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    sort_headword,
                    entry_id
            ))[1] AS matched_text
        FROM candidate_identity
        WHERE headword_group_id IS NOT NULL
        GROUP BY headword_group_id
    ),
    after_cursor AS MATERIALIZED (
        SELECT *
        FROM candidate_groups
        WHERE v_cursor_group_id IS NULL
           OR (
                tier_rank,
                match_rank,
                dictionary_rank,
                sort_headword,
                headword_group_id
           ) > (
                v_cursor_tier_rank,
                v_cursor_match_rank,
                v_cursor_dictionary_rank,
                v_cursor_sort_headword,
                v_cursor_group_id
           )
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit + 1
    ),
    returned_groups AS MATERIALIZED (
        SELECT *
        FROM after_cursor
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit
    ),
    group_entry_ids AS MATERIALIZED (
        SELECT
            group_page.*,
            entry.id AS entry_id,
            COALESCE(binding.sense_ordinal, entry.meaning_id)
                AS group_meaning_order
        FROM returned_groups AS group_page
        JOIN private.platform_v2_headword_groups AS headword_group
          ON headword_group.id = group_page.headword_group_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
         AND binding.binding_state = 'active'
        JOIN private.active_word_entries AS entry
          ON entry.id = COALESCE(
              binding.word_entry_id,
              headword_group.singleton_entry_id
          )
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
    ),
    group_sizes AS MATERIALIZED (
        SELECT
            headword_group_id,
            count(*)::integer AS entry_count
        FROM group_entry_ids
        GROUP BY headword_group_id
    ),
    oversized_groups AS MATERIALIZED (
        SELECT jsonb_build_object(
            'headwordGroupId', size.headword_group_id,
            'entryCount', size.entry_count,
            'safetyBound', v_group_entry_bound
        ) AS error_payload
        FROM group_sizes AS size
        WHERE size.entry_count > v_group_entry_bound
        ORDER BY size.entry_count DESC, size.headword_group_id
        LIMIT 1
    ),
    group_entries AS MATERIALIZED (
        SELECT
            member.tier_rank,
            member.match_rank,
            member.dictionary_rank,
            member.sort_headword,
            member.resolved_by,
            member.matched_text,
            member.headword_group_id,
            member.group_meaning_order,
            entry.*,
            dictionary.language_code AS dictionary_language_code,
            dictionary.slug AS dictionary_slug,
            dictionary.name AS dictionary_name,
            dictionary.kind AS dictionary_kind,
            dictionary.visibility AS dictionary_visibility,
            dictionary.owner_user_id AS dictionary_owner_user_id,
            dictionary.is_editable AS dictionary_is_editable,
            dictionary.schema_key AS dictionary_schema_key,
            dictionary.schema_version AS dictionary_schema_version
        FROM group_entry_ids AS member
        JOIN private.active_word_entries AS entry
          ON entry.id = member.entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        WHERE NOT EXISTS (SELECT 1 FROM oversized_groups)
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', entry.id,
                'dictionary_id', entry.dictionary_id,
                'language_code', entry.language_code,
                'headword', entry.headword,
                'meaning_id', entry.meaning_id,
                'part_of_speech', entry.part_of_speech,
                'gender', entry.gender,
                'raw', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN private.shared_instructional_raw_v1(entry.raw) ELSE entry.raw END,
                'is_nt2_2000', entry.is_nt2_2000,
                'meanings_count', size.entry_count,
                'dictionary', jsonb_build_object(
                    'id', entry.dictionary_id,
                    'language_code', entry.dictionary_language_code,
                    'slug', entry.dictionary_slug,
                    'name', entry.dictionary_name,
                    'kind', entry.dictionary_kind,
                    'visibility', entry.dictionary_visibility,
                    'owner_user_id',
                        entry.dictionary_owner_user_id,
                    'is_editable', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN false ELSE entry.dictionary_is_editable END,
                    'schema_key', entry.dictionary_schema_key,
                    'schema_version',
                        entry.dictionary_schema_version
                ),
                'dictionary_name', entry.dictionary_name,
                'dictionary_slug', entry.dictionary_slug,
                'dictionary_kind', entry.dictionary_kind,
                'search_match_group', entry.resolved_by,
                'search_matched_text', entry.matched_text
            )) AS payload,
            entry.tier_rank,
            entry.match_rank,
            entry.dictionary_rank,
            entry.sort_headword,
            entry.headword_group_id,
            entry.group_meaning_order,
            entry.id
        FROM group_entries AS entry
        JOIN group_sizes AS size
          ON size.headword_group_id = entry.headword_group_id
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    payload
                    ORDER BY
                        tier_rank,
                        match_rank,
                        dictionary_rank,
                        sort_headword,
                        headword_group_id,
                        group_meaning_order,
                        id
                )
                FROM payloads
            ),
            '[]'::jsonb
        ),
        (SELECT count(*) > v_group_limit FROM after_cursor),
        (
            SELECT private.encode_dictionary_search_cursor_v1(
                jsonb_build_object(
                    'version', 'platform-v2-group-cursor-v1',
                    'queryKey', v_query_key,
                    'tierRank', tier_rank,
                    'matchRank', match_rank,
                    'dictionaryRank', dictionary_rank,
                    'sortHeadword', sort_headword,
                    'headwordGroupId', headword_group_id
                )
            )
            FROM returned_groups
            ORDER BY
                tier_rank DESC,
                match_rank DESC,
                dictionary_rank DESC,
                sort_headword DESC,
                headword_group_id DESC
            LIMIT 1
        ),
        (
            SELECT count(*)::integer
            FROM candidate_identity
            WHERE headword_group_id IS NULL
        ),
        (
            SELECT error_payload
            FROM oversized_groups
        ), (SELECT count(*)::integer FROM candidate_groups)
    INTO
        v_items,
        v_has_more,
        v_next_cursor,
        v_missing_identity_count,
        v_oversized_group,v_total_groups;

    IF v_missing_identity_count > 0 THEN
        RETURN jsonb_build_object(
            'error', 'presentation_identity_incomplete'
        );
    END IF;
    IF v_oversized_group IS NOT NULL THEN
        RETURN jsonb_build_object(
            'error', 'group-too-large',
            'group', v_oversized_group
        );
    END IF;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'totalGroups', v_total_groups,
            'selectedTierComplete', NOT COALESCE(v_has_more, false),
            'nextGroupCursor', CASE
                WHEN COALESCE(v_has_more, false) THEN v_next_cursor
                ELSE NULL
            END
        )
    );
END;
$$;


--
-- Name: lookup_platform_v2_library_entries_base_v1(uuid, boolean, text, text, text, integer, integer, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lookup_platform_v2_library_entries_base_v1(p_user_id uuid, p_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50, p_library_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text :=
        NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_group_limit integer :=
        LEAST(GREATEST(COALESCE(p_group_limit, 10), 1), 25);
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_cursor jsonb :=
        private.decode_dictionary_search_cursor_v1(p_cursor);
    v_query_key text;
    v_cursor_tier_rank integer;
    v_cursor_match_rank integer;
    v_cursor_dictionary_rank integer;
    v_cursor_sort_headword text;
    v_cursor_group_id uuid;
    v_items jsonb;
    v_has_more boolean;
    v_next_cursor text;
    v_missing_identity_count integer;
    v_oversized_group jsonb;
BEGIN
    IF p_catalog AND p_user_id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF NOT p_catalog AND p_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent :=
        normalize_dictionary_search_text_unaccent(v_raw_query);
    v_query_key := encode(
        digest(
            concat_ws(
                chr(31),
                'platform-v2-group-cursor-v1',
                COALESCE(p_user_id::text, 'catalog'),
                p_catalog::text,
                v_raw_query,
                v_query,
                v_query_unaccent,
                COALESCE(v_language_code, ''), p_library_selection::text
            ),
            'sha256'
        ),
        'hex'
    );

    IF NULLIF(trim(COALESCE(p_cursor, '')), '') IS NOT NULL THEN
        IF v_cursor = '{}'::jsonb
           OR v_cursor->>'version' <> 'platform-v2-group-cursor-v1'
           OR v_cursor->>'queryKey' IS DISTINCT FROM v_query_key THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
        BEGIN
            v_cursor_tier_rank := (v_cursor->>'tierRank')::integer;
            v_cursor_match_rank := (v_cursor->>'matchRank')::integer;
            v_cursor_dictionary_rank :=
                (v_cursor->>'dictionaryRank')::integer;
            v_cursor_sort_headword := v_cursor->>'sortHeadword';
            v_cursor_group_id := (v_cursor->>'headwordGroupId')::uuid;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END;
        IF v_cursor_sort_headword IS NULL
           OR v_cursor_group_id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
    END IF;

    IF p_catalog
       AND EXISTS (
           SELECT 1
           FROM private.active_word_entries AS entry
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = entry.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR entry.language_code = v_language_code
             )
           LIMIT 1
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.dictionary_search_documents AS document
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = document.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR document.language_code = v_language_code
             )
           LIMIT 1
       ) THEN
        RETURN jsonb_build_object('error', 'search_index_not_ready');
    END IF;

    WITH shared_entries AS MATERIALIZED (
      SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(p_user_id) shared WHERE NOT p_catalog
    ), shared_dictionaries AS MATERIALIZED (
      SELECT DISTINCT entry.dictionary_id FROM shared_entries shared
      JOIN private.active_word_entries entry ON entry.id=shared.entry_id
    ), user_context AS MATERIALIZED (
        SELECT COALESCE(
            (
                SELECT subscription_tier
                FROM public.user_settings
                WHERE user_id = p_user_id
            ),
            'free'
        ) AS subscription_tier
    ),
    eligible_dictionaries AS MATERIALIZED (
      SELECT dictionary.*, CASE WHEN dictionary.kind='user' THEN 0 WHEN dictionary.kind='curated' THEN 1 ELSE 2 END AS dictionary_rank
      FROM public.dictionaries dictionary
      WHERE private.training_material_entry_selected_v1(dictionary.language_code,
        CASE WHEN dictionary.kind='user' THEN NULL ELSE dictionary.id END,p_library_selection)
        AND (p_library_selection->'dictionaryIds'='null'::jsonb OR (p_library_selection->'dictionaryIds') ? dictionary.id::text)
        AND ((p_catalog AND dictionary.publication_state='general' AND dictionary.kind<>'user')
          OR (NOT p_catalog AND (
            (public.can_browse_dictionary(p_user_id, dictionary.id) AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id))
            OR (dictionary.kind='user' AND dictionary.id IN (SELECT dictionary_id FROM shared_dictionaries)))))
    ),
    indexed_headword_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'exact-headword'::text AS resolved_by,
            document.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        WHERE (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND (v_raw_query IS NULL OR document.normalized_headword = v_query)

        UNION ALL

        SELECT
            document.entry_id,
            'exact-headword'::text,
            document.headword,
            1,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        WHERE (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND document.normalized_headword_unaccent =
              v_query_unaccent
          AND document.normalized_headword <> v_query
    ),
    legacy_user_headword_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'exact-headword'::text AS resolved_by,
            entry.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN entry.headword = v_raw_query THEN 0
                WHEN lower(entry.headword) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM private.active_word_entries AS entry
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE NOT p_catalog
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR entry.language_code = v_language_code
          )
          AND (
              v_raw_query IS NULL OR lower(entry.headword) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(
                  entry.headword
              ) = v_query_unaccent
          )
    ),
    headword_matches AS MATERIALIZED (
        SELECT * FROM indexed_headword_matches
        UNION ALL
        SELECT * FROM legacy_user_headword_matches
    ),
    headword_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM headword_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.headword),
            match.meaning_id
    ),
    indexed_form_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            field.display_text AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text = v_query

        UNION ALL

        SELECT
            document.entry_id,
            'lemma-or-inflection'::text,
            field.display_text,
            2,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text_unaccent = v_query_unaccent
          AND field.normalized_text <> v_query
    ),
    legacy_user_form_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            form.form AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN form.form = v_raw_query THEN 0
                WHEN lower(form.form) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM public.word_forms AS form
        JOIN private.active_word_entries AS entry
          ON entry.id = form.word_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE NOT p_catalog
          AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR form.language_code = v_language_code
          )
          AND form.language_code = entry.language_code
          AND (
              form.dictionary_id IS NULL
              OR form.dictionary_id = entry.dictionary_id
          )
          AND (
              lower(form.form) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(form.form) =
                  v_query_unaccent
          )
    ),
    form_matches AS MATERIALIZED (
        SELECT * FROM indexed_form_matches
        UNION ALL
        SELECT * FROM legacy_user_form_matches
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM form_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.matched_text)
    ),
    candidates AS MATERIALIZED (
        SELECT * FROM headword_candidates
        UNION ALL
        SELECT * FROM form_candidates
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
    ),
    candidate_identity AS MATERIALIZED (
        SELECT
            candidate.*,
            CASE WHEN v_raw_query IS NULL THEN 0 ELSE dictionary.dictionary_rank END AS dictionary_rank,
            COALESCE(
                source_group.id,
                user_group.id
            ) AS headword_group_id
        FROM candidates AS candidate
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = candidate.dictionary_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON binding.word_entry_id = candidate.entry_id
         AND binding.binding_state = 'active'
        LEFT JOIN private.platform_v2_headword_groups AS source_group
          ON source_group.management_kind = 'source'
         AND source_group.dictionary_id = binding.dictionary_id
         AND source_group.identity_scheme_version =
             binding.identity_scheme_version
         AND source_group.source_group_key = binding.source_group_key
        LEFT JOIN private.platform_v2_headword_groups AS user_group
          ON user_group.management_kind = 'user'
         AND user_group.singleton_entry_id = candidate.entry_id
    ),
    candidate_groups AS MATERIALIZED (
        SELECT
            headword_group_id,
            min(tier_rank) AS tier_rank,
            min(match_rank) AS match_rank,
            min(dictionary_rank) AS dictionary_rank,
            min(normalize_dictionary_search_text(headword))
                AS sort_headword,
            (array_agg(
                resolved_by
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS resolved_by,
            (array_agg(
                matched_text
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS matched_text
        FROM candidate_identity
        WHERE headword_group_id IS NOT NULL
        GROUP BY headword_group_id
    ),
    after_cursor AS MATERIALIZED (
        SELECT *
        FROM candidate_groups
        WHERE v_cursor_group_id IS NULL
           OR (
                tier_rank,
                match_rank,
                dictionary_rank,
                sort_headword,
                headword_group_id
           ) > (
                v_cursor_tier_rank,
                v_cursor_match_rank,
                v_cursor_dictionary_rank,
                v_cursor_sort_headword,
                v_cursor_group_id
           )
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit + 1
    ),
    returned_groups AS MATERIALIZED (
        SELECT *
        FROM after_cursor
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit
    ),
    group_entry_ids AS MATERIALIZED (
        SELECT
            group_page.*,
            entry.id AS entry_id,
            COALESCE(binding.sense_ordinal, entry.meaning_id)
                AS group_meaning_order
        FROM returned_groups AS group_page
        JOIN private.platform_v2_headword_groups AS headword_group
          ON headword_group.id = group_page.headword_group_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
         AND binding.binding_state = 'active'
        JOIN private.active_word_entries AS entry
          ON entry.id = COALESCE(
              binding.word_entry_id,
              headword_group.singleton_entry_id
          )
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
    ),
    group_sizes AS MATERIALIZED (
        SELECT
            headword_group_id,
            count(*)::integer AS entry_count
        FROM group_entry_ids
        GROUP BY headword_group_id
    ),
    oversized_groups AS MATERIALIZED (
        SELECT jsonb_build_object(
            'headwordGroupId', size.headword_group_id,
            'entryCount', size.entry_count,
            'safetyBound', v_group_entry_bound
        ) AS error_payload
        FROM group_sizes AS size
        WHERE size.entry_count > v_group_entry_bound
        ORDER BY size.entry_count DESC, size.headword_group_id
        LIMIT 1
    ),
    group_entries AS MATERIALIZED (
        SELECT
            member.tier_rank,
            member.match_rank,
            member.dictionary_rank,
            member.sort_headword,
            member.resolved_by,
            member.matched_text,
            member.headword_group_id,
            member.group_meaning_order,
            entry.*,
            dictionary.language_code AS dictionary_language_code,
            dictionary.slug AS dictionary_slug,
            dictionary.name AS dictionary_name,
            dictionary.kind AS dictionary_kind,
            dictionary.visibility AS dictionary_visibility,
            dictionary.owner_user_id AS dictionary_owner_user_id,
            dictionary.is_editable AS dictionary_is_editable,
            dictionary.schema_key AS dictionary_schema_key,
            dictionary.schema_version AS dictionary_schema_version
        FROM group_entry_ids AS member
        JOIN private.active_word_entries AS entry
          ON entry.id = member.entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        WHERE NOT EXISTS (SELECT 1 FROM oversized_groups)
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', entry.id,
                'dictionary_id', entry.dictionary_id,
                'language_code', entry.language_code,
                'headword', entry.headword,
                'meaning_id', entry.meaning_id,
                'part_of_speech', entry.part_of_speech,
                'gender', entry.gender,
                'raw', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN private.shared_instructional_raw_v1(entry.raw) ELSE entry.raw END,
                'is_nt2_2000', entry.is_nt2_2000,
                'meanings_count', size.entry_count,
                'dictionary', jsonb_build_object(
                    'id', entry.dictionary_id,
                    'language_code', entry.dictionary_language_code,
                    'slug', entry.dictionary_slug,
                    'name', entry.dictionary_name,
                    'kind', entry.dictionary_kind,
                    'visibility', entry.dictionary_visibility,
                    'owner_user_id',
                        entry.dictionary_owner_user_id,
                    'is_editable', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN false ELSE entry.dictionary_is_editable END,
                    'schema_key', entry.dictionary_schema_key,
                    'schema_version',
                        entry.dictionary_schema_version
                ),
                'dictionary_name', entry.dictionary_name,
                'dictionary_slug', entry.dictionary_slug,
                'dictionary_kind', entry.dictionary_kind,
                'search_match_group', entry.resolved_by,
                'search_matched_text', entry.matched_text
            )) AS payload,
            entry.tier_rank,
            entry.match_rank,
            entry.dictionary_rank,
            entry.sort_headword,
            entry.headword_group_id,
            entry.group_meaning_order,
            entry.id
        FROM group_entries AS entry
        JOIN group_sizes AS size
          ON size.headword_group_id = entry.headword_group_id
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    payload
                    ORDER BY
                        tier_rank,
                        match_rank,
                        dictionary_rank,
                        sort_headword,
                        headword_group_id,
                        group_meaning_order,
                        id
                )
                FROM payloads
            ),
            '[]'::jsonb
        ),
        (SELECT count(*) > v_group_limit FROM after_cursor),
        (
            SELECT private.encode_dictionary_search_cursor_v1(
                jsonb_build_object(
                    'version', 'platform-v2-group-cursor-v1',
                    'queryKey', v_query_key,
                    'tierRank', tier_rank,
                    'matchRank', match_rank,
                    'dictionaryRank', dictionary_rank,
                    'sortHeadword', sort_headword,
                    'headwordGroupId', headword_group_id
                )
            )
            FROM returned_groups
            ORDER BY
                tier_rank DESC,
                match_rank DESC,
                dictionary_rank DESC,
                sort_headword DESC,
                headword_group_id DESC
            LIMIT 1
        ),
        (
            SELECT count(*)::integer
            FROM candidate_identity
            WHERE headword_group_id IS NULL
        ),
        (
            SELECT error_payload
            FROM oversized_groups
        )
    INTO
        v_items,
        v_has_more,
        v_next_cursor,
        v_missing_identity_count,
        v_oversized_group;

    IF v_missing_identity_count > 0 THEN
        RETURN jsonb_build_object(
            'error', 'presentation_identity_incomplete'
        );
    END IF;
    IF v_oversized_group IS NOT NULL THEN
        RETURN jsonb_build_object(
            'error', 'group-too-large',
            'group', v_oversized_group
        );
    END IF;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'selectedTierComplete', NOT COALESCE(v_has_more, false),
            'nextGroupCursor', CASE
                WHEN COALESCE(v_has_more, false) THEN v_next_cursor
                ELSE NULL
            END
        )
    );
END;
$$;


--
-- Name: lookup_platform_v2_library_filtered_entries_base_v1(uuid, boolean, text, text, text, integer, integer, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lookup_platform_v2_library_filtered_entries_base_v1(p_user_id uuid, p_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50, p_library_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text :=
        NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_group_limit integer :=
        LEAST(GREATEST(COALESCE(p_group_limit, 10), 1), 25);
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_cursor jsonb :=
        private.decode_dictionary_search_cursor_v1(p_cursor);
    v_query_key text;
    v_cursor_tier_rank integer;
    v_cursor_match_rank integer;
    v_cursor_dictionary_rank integer;
    v_cursor_sort_headword text;
    v_cursor_group_id uuid;
    v_items jsonb;
    v_has_more boolean;
    v_next_cursor text;
    v_missing_identity_count integer;
    v_total_groups integer; v_oversized_group jsonb;
BEGIN
    IF p_catalog AND p_user_id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF NOT p_catalog AND p_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF v_raw_query IS NULL THEN
        RETURN private.lookup_platform_v2_library_browse_entries_v1(
            p_user_id,p_catalog,p_query,p_language_code,p_cursor,p_group_limit,p_group_entry_bound,p_library_selection);
    END IF;
    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent :=
        normalize_dictionary_search_text_unaccent(v_raw_query);
    v_query_key := encode(
        digest(
            concat_ws(
                chr(31),
                'platform-v2-group-cursor-v1',
                COALESCE(p_user_id::text, 'catalog'),
                p_catalog::text,
                v_raw_query,
                v_query,
                v_query_unaccent,
                COALESCE(v_language_code, ''), p_library_selection::text
            ),
            'sha256'
        ),
        'hex'
    );

    IF NULLIF(trim(COALESCE(p_cursor, '')), '') IS NOT NULL THEN
        IF v_cursor = '{}'::jsonb
           OR v_cursor->>'version' <> 'platform-v2-group-cursor-v1'
           OR v_cursor->>'queryKey' IS DISTINCT FROM v_query_key THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
        BEGIN
            v_cursor_tier_rank := (v_cursor->>'tierRank')::integer;
            v_cursor_match_rank := (v_cursor->>'matchRank')::integer;
            v_cursor_dictionary_rank :=
                (v_cursor->>'dictionaryRank')::integer;
            v_cursor_sort_headword := v_cursor->>'sortHeadword';
            v_cursor_group_id := (v_cursor->>'headwordGroupId')::uuid;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END;
        IF v_cursor_sort_headword IS NULL
           OR v_cursor_group_id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
    END IF;

    IF p_catalog
       AND EXISTS (
           SELECT 1
           FROM private.active_word_entries AS entry
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = entry.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR entry.language_code = v_language_code
             )
           LIMIT 1
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.dictionary_search_documents AS document
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = document.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR document.language_code = v_language_code
             )
           LIMIT 1
       ) THEN
        RETURN jsonb_build_object('error', 'search_index_not_ready');
    END IF;

    WITH shared_entries AS MATERIALIZED (
      SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(p_user_id) shared WHERE NOT p_catalog
    ), shared_dictionaries AS MATERIALIZED (
      SELECT DISTINCT entry.dictionary_id FROM shared_entries shared
      JOIN private.active_word_entries entry ON entry.id=shared.entry_id
    ), user_context AS MATERIALIZED (
        SELECT COALESCE(
            (
                SELECT subscription_tier
                FROM public.user_settings
                WHERE user_id = p_user_id
            ),
            'free'
        ) AS subscription_tier
    ),
    eligible_dictionaries AS MATERIALIZED (
      SELECT dictionary.*, CASE WHEN dictionary.kind='user' THEN 0 WHEN dictionary.kind='curated' THEN 1 ELSE 2 END AS dictionary_rank
      FROM public.dictionaries dictionary
      WHERE private.training_material_entry_selected_v1(dictionary.language_code,
        CASE WHEN dictionary.kind='user' THEN NULL ELSE dictionary.id END,p_library_selection)
        AND (p_library_selection->'dictionaryIds'='null'::jsonb OR (p_library_selection->'dictionaryIds') ? dictionary.id::text)
        AND ((p_catalog AND dictionary.publication_state='general' AND dictionary.kind<>'user')
          OR (NOT p_catalog AND (
            (public.can_browse_dictionary(p_user_id, dictionary.id) AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id))
            OR (dictionary.kind='user' AND dictionary.id IN (SELECT dictionary_id FROM shared_dictionaries)))))
    ),
    indexed_headword_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'exact-headword'::text AS resolved_by,
            document.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND (v_raw_query IS NULL OR document.normalized_headword = v_query)

        UNION ALL

        SELECT
            document.entry_id,
            'exact-headword'::text,
            document.headword,
            1,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND document.normalized_headword_unaccent =
              v_query_unaccent
          AND document.normalized_headword <> v_query
    ),
    legacy_user_headword_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'exact-headword'::text AS resolved_by,
            entry.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN entry.headword = v_raw_query THEN 0
                WHEN lower(entry.headword) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM private.active_word_entries AS entry
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE private.library_entry_matches_filters_v1(entry.part_of_speech,entry.gender,p_library_selection) AND NOT p_catalog
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR entry.language_code = v_language_code
          )
          AND (
              v_raw_query IS NULL OR lower(entry.headword) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(
                  entry.headword
              ) = v_query_unaccent
          )
    ),
    headword_matches AS MATERIALIZED (
        SELECT * FROM indexed_headword_matches
        UNION ALL
        SELECT * FROM legacy_user_headword_matches
    ),
    headword_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM headword_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.headword),
            match.meaning_id
    ),
    indexed_form_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            field.display_text AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text = v_query

        UNION ALL

        SELECT
            document.entry_id,
            'lemma-or-inflection'::text,
            field.display_text,
            2,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=document.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR document.entry_id IN (SELECT entry_id FROM shared_entries))
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text_unaccent = v_query_unaccent
          AND field.normalized_text <> v_query
    ),
    legacy_user_form_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            form.form AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN form.form = v_raw_query THEN 0
                WHEN lower(form.form) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM public.word_forms AS form
        JOIN private.active_word_entries AS entry
          ON entry.id = form.word_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE private.library_entry_matches_filters_v1(entry.part_of_speech,entry.gender,p_library_selection) AND NOT p_catalog
          AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR form.language_code = v_language_code
          )
          AND form.language_code = entry.language_code
          AND (
              form.dictionary_id IS NULL
              OR form.dictionary_id = entry.dictionary_id
          )
          AND (
              lower(form.form) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(form.form) =
                  v_query_unaccent
          )
    ),
    form_matches AS MATERIALIZED (
        SELECT * FROM indexed_form_matches
        UNION ALL
        SELECT * FROM legacy_user_form_matches
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM form_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.matched_text)
    ),
    candidates AS MATERIALIZED (
        SELECT * FROM headword_candidates
        UNION ALL
        SELECT * FROM form_candidates
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
    ),
    candidate_identity AS MATERIALIZED (
        SELECT
            candidate.*,
            CASE WHEN v_raw_query IS NULL THEN 0 ELSE dictionary.dictionary_rank END AS dictionary_rank,
            COALESCE(
                source_group.id,
                user_group.id
            ) AS headword_group_id
        FROM candidates AS candidate
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = candidate.dictionary_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON binding.word_entry_id = candidate.entry_id
         AND binding.binding_state = 'active'
        LEFT JOIN private.platform_v2_headword_groups AS source_group
          ON source_group.management_kind = 'source'
         AND source_group.dictionary_id = binding.dictionary_id
         AND source_group.identity_scheme_version =
             binding.identity_scheme_version
         AND source_group.source_group_key = binding.source_group_key
        LEFT JOIN private.platform_v2_headword_groups AS user_group
          ON user_group.management_kind = 'user'
         AND user_group.singleton_entry_id = candidate.entry_id
    ),
    candidate_groups AS MATERIALIZED (
        SELECT
            headword_group_id,
            min(tier_rank) AS tier_rank,
            min(match_rank) AS match_rank,
            min(dictionary_rank) AS dictionary_rank,
            min(normalize_dictionary_search_text(headword))
                AS sort_headword,
            (array_agg(
                resolved_by
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS resolved_by,
            (array_agg(
                matched_text
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS matched_text
        FROM candidate_identity
        WHERE headword_group_id IS NOT NULL
        GROUP BY headword_group_id
    ),
    after_cursor AS MATERIALIZED (
        SELECT *
        FROM candidate_groups
        WHERE v_cursor_group_id IS NULL
           OR (
                tier_rank,
                match_rank,
                dictionary_rank,
                sort_headword,
                headword_group_id
           ) > (
                v_cursor_tier_rank,
                v_cursor_match_rank,
                v_cursor_dictionary_rank,
                v_cursor_sort_headword,
                v_cursor_group_id
           )
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit + 1
    ),
    returned_groups AS MATERIALIZED (
        SELECT *
        FROM after_cursor
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit
    ),
    group_entry_ids AS MATERIALIZED (
        SELECT
            group_page.*,
            entry.id AS entry_id,
            COALESCE(binding.sense_ordinal, entry.meaning_id)
                AS group_meaning_order
        FROM returned_groups AS group_page
        JOIN private.platform_v2_headword_groups AS headword_group
          ON headword_group.id = group_page.headword_group_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
         AND binding.binding_state = 'active'
        JOIN private.active_word_entries AS entry
          ON entry.id = COALESCE(
              binding.word_entry_id,
              headword_group.singleton_entry_id
          )
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
    ),
    group_sizes AS MATERIALIZED (
        SELECT
            headword_group_id,
            count(*)::integer AS entry_count
        FROM group_entry_ids
        GROUP BY headword_group_id
    ),
    oversized_groups AS MATERIALIZED (
        SELECT jsonb_build_object(
            'headwordGroupId', size.headword_group_id,
            'entryCount', size.entry_count,
            'safetyBound', v_group_entry_bound
        ) AS error_payload
        FROM group_sizes AS size
        WHERE size.entry_count > v_group_entry_bound
        ORDER BY size.entry_count DESC, size.headword_group_id
        LIMIT 1
    ),
    group_entries AS MATERIALIZED (
        SELECT
            member.tier_rank,
            member.match_rank,
            member.dictionary_rank,
            member.sort_headword,
            member.resolved_by,
            member.matched_text,
            member.headword_group_id,
            member.group_meaning_order,
            entry.*,
            dictionary.language_code AS dictionary_language_code,
            dictionary.slug AS dictionary_slug,
            dictionary.name AS dictionary_name,
            dictionary.kind AS dictionary_kind,
            dictionary.visibility AS dictionary_visibility,
            dictionary.owner_user_id AS dictionary_owner_user_id,
            dictionary.is_editable AS dictionary_is_editable,
            dictionary.schema_key AS dictionary_schema_key,
            dictionary.schema_version AS dictionary_schema_version
        FROM group_entry_ids AS member
        JOIN private.active_word_entries AS entry
          ON entry.id = member.entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id=entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        WHERE NOT EXISTS (SELECT 1 FROM oversized_groups)
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', entry.id,
                'dictionary_id', entry.dictionary_id,
                'language_code', entry.language_code,
                'headword', entry.headword,
                'meaning_id', entry.meaning_id,
                'part_of_speech', entry.part_of_speech,
                'gender', entry.gender,
                'raw', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN private.shared_instructional_raw_v1(entry.raw) ELSE entry.raw END,
                'is_nt2_2000', entry.is_nt2_2000,
                'meanings_count', size.entry_count,
                'dictionary', jsonb_build_object(
                    'id', entry.dictionary_id,
                    'language_code', entry.dictionary_language_code,
                    'slug', entry.dictionary_slug,
                    'name', entry.dictionary_name,
                    'kind', entry.dictionary_kind,
                    'visibility', entry.dictionary_visibility,
                    'owner_user_id',
                        entry.dictionary_owner_user_id,
                    'is_editable', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN false ELSE entry.dictionary_is_editable END,
                    'schema_key', entry.dictionary_schema_key,
                    'schema_version',
                        entry.dictionary_schema_version
                ),
                'dictionary_name', entry.dictionary_name,
                'dictionary_slug', entry.dictionary_slug,
                'dictionary_kind', entry.dictionary_kind,
                'search_match_group', entry.resolved_by,
                'search_matched_text', entry.matched_text
            )) AS payload,
            entry.tier_rank,
            entry.match_rank,
            entry.dictionary_rank,
            entry.sort_headword,
            entry.headword_group_id,
            entry.group_meaning_order,
            entry.id
        FROM group_entries AS entry
        JOIN group_sizes AS size
          ON size.headword_group_id = entry.headword_group_id
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    payload
                    ORDER BY
                        tier_rank,
                        match_rank,
                        dictionary_rank,
                        sort_headword,
                        headword_group_id,
                        group_meaning_order,
                        id
                )
                FROM payloads
            ),
            '[]'::jsonb
        ),
        (SELECT count(*) > v_group_limit FROM after_cursor),
        (
            SELECT private.encode_dictionary_search_cursor_v1(
                jsonb_build_object(
                    'version', 'platform-v2-group-cursor-v1',
                    'queryKey', v_query_key,
                    'tierRank', tier_rank,
                    'matchRank', match_rank,
                    'dictionaryRank', dictionary_rank,
                    'sortHeadword', sort_headword,
                    'headwordGroupId', headword_group_id
                )
            )
            FROM returned_groups
            ORDER BY
                tier_rank DESC,
                match_rank DESC,
                dictionary_rank DESC,
                sort_headword DESC,
                headword_group_id DESC
            LIMIT 1
        ),
        (
            SELECT count(*)::integer
            FROM candidate_identity
            WHERE headword_group_id IS NULL
        ),
        (
            SELECT error_payload
            FROM oversized_groups
        ), (SELECT count(*)::integer FROM candidate_groups)
    INTO
        v_items,
        v_has_more,
        v_next_cursor,
        v_missing_identity_count,
        v_oversized_group,v_total_groups;

    IF v_missing_identity_count > 0 THEN
        RETURN jsonb_build_object(
            'error', 'presentation_identity_incomplete'
        );
    END IF;
    IF v_oversized_group IS NOT NULL THEN
        RETURN jsonb_build_object(
            'error', 'group-too-large',
            'group', v_oversized_group
        );
    END IF;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'totalGroups', v_total_groups,
            'selectedTierComplete', NOT COALESCE(v_has_more, false),
            'nextGroupCursor', CASE
                WHEN COALESCE(v_has_more, false) THEN v_next_cursor
                ELSE NULL
            END
        )
    );
END;
$$;


--
-- Name: lookup_platform_v2_library_material_browse_entries_v1(uuid, boolean, text, text, text, integer, integer, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lookup_platform_v2_library_material_browse_entries_v1(p_user_id uuid, p_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50, p_library_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text :=
        NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_group_limit integer :=
        LEAST(GREATEST(COALESCE(p_group_limit, 10), 1), 25);
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_cursor jsonb :=
        private.decode_dictionary_search_cursor_v1(p_cursor);
    v_query_key text;
    v_cursor_tier_rank integer;
    v_cursor_match_rank integer;
    v_cursor_dictionary_rank integer;
    v_cursor_sort_headword text;
    v_cursor_group_id uuid;
    v_items jsonb;
    v_has_more boolean;
    v_next_cursor text;
    v_missing_identity_count integer;
    v_matching_ids jsonb; v_total_groups integer; v_oversized_group jsonb;
BEGIN
    IF p_catalog AND p_user_id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF NOT p_catalog AND p_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF v_raw_query IS NOT NULL THEN RETURN jsonb_build_object('error','browse_query_required'); END IF;
    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent :=
        normalize_dictionary_search_text_unaccent(v_raw_query);
    v_query_key := encode(
        digest(
            concat_ws(
                chr(31),
                'platform-v2-group-cursor-v1',
                COALESCE(p_user_id::text, 'catalog'),
                p_catalog::text,
                v_raw_query,
                v_query,
                v_query_unaccent,
                COALESCE(v_language_code, ''), p_library_selection::text
            ),
            'sha256'
        ),
        'hex'
    );

    IF NULLIF(trim(COALESCE(p_cursor, '')), '') IS NOT NULL THEN
        IF v_cursor = '{}'::jsonb
           OR v_cursor->>'version' <> 'platform-v2-group-cursor-v1'
           OR v_cursor->>'queryKey' IS DISTINCT FROM v_query_key THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
        BEGIN
            v_cursor_tier_rank := (v_cursor->>'tierRank')::integer;
            v_cursor_match_rank := (v_cursor->>'matchRank')::integer;
            v_cursor_dictionary_rank :=
                (v_cursor->>'dictionaryRank')::integer;
            v_cursor_sort_headword := v_cursor->>'sortHeadword';
            v_cursor_group_id := (v_cursor->>'headwordGroupId')::uuid;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END;
        IF v_cursor_sort_headword IS NULL
           OR v_cursor_group_id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
    END IF;

    IF p_catalog
       AND EXISTS (
           SELECT 1
           FROM private.active_word_entries AS entry
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = entry.dictionary_id AND private.entry_access_v1(p_user_id,entry.id,'browse')
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR entry.language_code = v_language_code
             )
           LIMIT 1
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.dictionary_search_documents AS document
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = document.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR document.language_code = v_language_code
             )
           LIMIT 1
       ) THEN
        RETURN jsonb_build_object('error', 'search_index_not_ready');
    END IF;

    WITH shared_entries AS MATERIALIZED (SELECT entry_id FROM private.shared_author_entry_ids_v1(p_user_id)), material_entries AS MATERIALIZED (SELECT entry_id FROM private.readable_material_entry_ids_v1(p_user_id,p_library_selection->'material')), user_context AS MATERIALIZED (
        SELECT COALESCE(
            (
                SELECT subscription_tier
                FROM public.user_settings
                WHERE user_id = p_user_id
            ),
            'free'
        ) AS subscription_tier
    ),
    eligible_dictionaries AS MATERIALIZED (
      SELECT dictionary.*, CASE WHEN dictionary.kind='user' THEN 0 WHEN dictionary.kind='curated' THEN 1 ELSE 2 END AS dictionary_rank
      FROM public.dictionaries dictionary
      WHERE (
      (public.can_browse_dictionary(p_user_id,dictionary.id)
        AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id))
      OR (dictionary.kind='user' AND EXISTS (
        SELECT 1 FROM material_entries selected
        JOIN private.active_word_entries shared_entry ON shared_entry.id=selected.entry_id
        WHERE shared_entry.dictionary_id=dictionary.id
      )))
        AND private.training_material_entry_selected_v1(dictionary.language_code,
          CASE WHEN dictionary.kind='user' THEN NULL ELSE dictionary.id END,p_library_selection)
    ),
    -- Empty browse has one headword tier. Do not sort/deduplicate the same
    -- primary-key document stream through the exact/form search tiers.
    candidates AS MATERIALIZED (
        -- Separate guarded branches also skip wide entry reads in a cached
        -- generic plan, where an optional LEFT JOIN would still scan its heap.
        SELECT document.entry_id, document.headword, document.meaning_id,
            document.dictionary_id, normalize_dictionary_search_text(document.headword) AS sort_headword,
            'exact-headword'::text AS resolved_by, document.headword AS matched_text,
            1 AS tier_rank, CASE WHEN document.normalized_headword=v_query THEN 1 ELSE 2 END AS match_rank
        FROM public.dictionary_search_documents document
        JOIN eligible_dictionaries dictionary ON dictionary.id=document.dictionary_id JOIN material_entries material_member ON material_member.entry_id=document.entry_id
        WHERE p_library_selection->'parts'='[]'::jsonb AND p_library_selection->>'article' IS NULL
          AND (v_language_code IS NULL OR document.language_code=v_language_code)
        UNION ALL
        SELECT document.entry_id, document.headword, document.meaning_id,
            document.dictionary_id, normalize_dictionary_search_text(document.headword) AS sort_headword,
            'exact-headword'::text AS resolved_by, document.headword AS matched_text,
            1 AS tier_rank, CASE WHEN document.normalized_headword=v_query THEN 1 ELSE 2 END AS match_rank
        FROM public.dictionary_search_documents document
        JOIN eligible_dictionaries dictionary ON dictionary.id=document.dictionary_id JOIN material_entries material_member ON material_member.entry_id=document.entry_id
        JOIN private.active_word_entries filter_entry ON filter_entry.id=document.entry_id
        WHERE NOT (p_library_selection->'parts'='[]'::jsonb AND p_library_selection->>'article' IS NULL)
          AND (v_language_code IS NULL OR document.language_code=v_language_code)
          AND private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection)
        UNION ALL
        SELECT entry.id, entry.headword, entry.meaning_id, entry.dictionary_id,
            normalize_dictionary_search_text(entry.headword),
            'exact-headword'::text, entry.headword, 1, 2
        FROM private.active_word_entries entry
        JOIN eligible_dictionaries dictionary ON dictionary.id=entry.dictionary_id JOIN material_entries material_member ON material_member.entry_id=entry.id
        LEFT JOIN public.dictionary_search_documents document ON document.entry_id=entry.id
        WHERE NOT p_catalog AND dictionary.kind='user' AND document.entry_id IS NULL
          AND EXISTS (SELECT 1 FROM eligible_dictionaries WHERE kind='user')
          AND (v_language_code IS NULL OR entry.language_code=v_language_code)
          AND private.library_entry_matches_filters_v1(entry.part_of_speech,entry.gender,p_library_selection)
    ),
    -- Resolve identities in one narrow pass. Candidate CTE cardinality estimates
    -- otherwise turn a catalogue browse into tens of thousands of index probes.
    source_identities AS MATERIALIZED (
        SELECT binding.word_entry_id, source_group.id
        FROM private.source_entry_bindings binding JOIN material_entries material_identity ON material_identity.entry_id=binding.word_entry_id
        JOIN eligible_dictionaries dictionary ON dictionary.id=binding.dictionary_id
        JOIN private.platform_v2_headword_groups source_group
          ON source_group.management_kind='source'
         AND source_group.dictionary_id=binding.dictionary_id
         AND source_group.identity_scheme_version=binding.identity_scheme_version
         AND source_group.source_group_key=binding.source_group_key
        WHERE binding.binding_state='active'
    ),
    candidate_identity AS MATERIALIZED (
        SELECT candidate.*, 0 AS dictionary_rank,
            COALESCE(source_identity.id,user_group.id) AS headword_group_id
        FROM candidates candidate
        LEFT JOIN source_identities source_identity ON source_identity.word_entry_id=candidate.entry_id
        LEFT JOIN private.platform_v2_headword_groups user_group
          ON user_group.management_kind='user' AND user_group.singleton_entry_id=candidate.entry_id
    ),
    candidate_groups AS MATERIALIZED (
        SELECT
            headword_group_id,
            min(tier_rank) AS tier_rank,
            min(match_rank) AS match_rank,
            min(dictionary_rank) AS dictionary_rank,
            min(sort_headword)
                AS sort_headword,
            (array_agg(
                resolved_by
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    sort_headword,
                    entry_id
            ))[1] AS resolved_by,
            (array_agg(
                matched_text
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    sort_headword,
                    entry_id
            ))[1] AS matched_text
        FROM candidate_identity
        WHERE headword_group_id IS NOT NULL
        GROUP BY headword_group_id
    ),
    after_cursor AS MATERIALIZED (
        SELECT *
        FROM candidate_groups
        WHERE v_cursor_group_id IS NULL
           OR (
                tier_rank,
                match_rank,
                dictionary_rank,
                sort_headword,
                headword_group_id
           ) > (
                v_cursor_tier_rank,
                v_cursor_match_rank,
                v_cursor_dictionary_rank,
                v_cursor_sort_headword,
                v_cursor_group_id
           )
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit + 1
    ),
    returned_groups AS MATERIALIZED (
        SELECT *
        FROM after_cursor
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit
    ),
    group_entry_ids AS MATERIALIZED (
        SELECT
            group_page.*,
            entry.id AS entry_id,
            COALESCE(binding.sense_ordinal, entry.meaning_id)
                AS group_meaning_order
        FROM returned_groups AS group_page
        JOIN private.platform_v2_headword_groups AS headword_group
          ON headword_group.id = group_page.headword_group_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
         AND binding.binding_state = 'active'
        JOIN private.active_word_entries AS entry
          ON entry.id = COALESCE(
              binding.word_entry_id,
              headword_group.singleton_entry_id
          )
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
    ),
    group_sizes AS MATERIALIZED (
        SELECT
            headword_group_id,
            count(*)::integer AS entry_count
        FROM group_entry_ids
        GROUP BY headword_group_id
    ),
    oversized_groups AS MATERIALIZED (
        SELECT jsonb_build_object(
            'headwordGroupId', size.headword_group_id,
            'entryCount', size.entry_count,
            'safetyBound', v_group_entry_bound
        ) AS error_payload
        FROM group_sizes AS size
        WHERE size.entry_count > v_group_entry_bound
        ORDER BY size.entry_count DESC, size.headword_group_id
        LIMIT 1
    ),
    group_entries AS MATERIALIZED (
        SELECT
            member.tier_rank,
            member.match_rank,
            member.dictionary_rank,
            member.sort_headword,
            member.resolved_by,
            member.matched_text,
            member.headword_group_id,
            member.group_meaning_order,
            entry.*,
            dictionary.language_code AS dictionary_language_code,
            dictionary.slug AS dictionary_slug,
            dictionary.name AS dictionary_name,
            dictionary.kind AS dictionary_kind,
            dictionary.visibility AS dictionary_visibility,
            dictionary.owner_user_id AS dictionary_owner_user_id,
            dictionary.is_editable AS dictionary_is_editable,
            dictionary.schema_key AS dictionary_schema_key,
            dictionary.schema_version AS dictionary_schema_version
        FROM group_entry_ids AS member
        JOIN private.active_word_entries AS entry
          ON entry.id = member.entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        WHERE NOT EXISTS (SELECT 1 FROM oversized_groups)
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', entry.id,
                'dictionary_id', entry.dictionary_id,
                'language_code', entry.language_code,
                'headword', entry.headword,
                'meaning_id', entry.meaning_id,
                'part_of_speech', entry.part_of_speech,
                'gender', entry.gender,
                'raw', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN private.shared_instructional_raw_v1(entry.raw) ELSE entry.raw END,
                'is_nt2_2000', entry.is_nt2_2000,
                'meanings_count', size.entry_count,
                'dictionary', jsonb_build_object(
                    'id', entry.dictionary_id,
                    'language_code', entry.dictionary_language_code,
                    'slug', entry.dictionary_slug,
                    'name', entry.dictionary_name,
                    'kind', entry.dictionary_kind,
                    'visibility', entry.dictionary_visibility,
                    'owner_user_id',
                        entry.dictionary_owner_user_id,
                    'is_editable', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN false ELSE entry.dictionary_is_editable END,
                    'schema_key', entry.dictionary_schema_key,
                    'schema_version',
                        entry.dictionary_schema_version
                ),
                'dictionary_name', entry.dictionary_name,
                'dictionary_slug', entry.dictionary_slug,
                'dictionary_kind', entry.dictionary_kind,
                'search_match_group', entry.resolved_by,
                'search_matched_text', entry.matched_text
            )) AS payload,
            entry.tier_rank,
            entry.match_rank,
            entry.dictionary_rank,
            entry.sort_headword,
            entry.headword_group_id,
            entry.group_meaning_order,
            entry.id
        FROM group_entries AS entry
        JOIN group_sizes AS size
          ON size.headword_group_id = entry.headword_group_id
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    payload
                    ORDER BY
                        tier_rank,
                        match_rank,
                        dictionary_rank,
                        sort_headword,
                        headword_group_id,
                        group_meaning_order,
                        id
                )
                FROM payloads
            ),
            '[]'::jsonb
        ),
        (SELECT count(*) > v_group_limit FROM after_cursor),
        (
            SELECT private.encode_dictionary_search_cursor_v1(
                jsonb_build_object(
                    'version', 'platform-v2-group-cursor-v1',
                    'queryKey', v_query_key,
                    'tierRank', tier_rank,
                    'matchRank', match_rank,
                    'dictionaryRank', dictionary_rank,
                    'sortHeadword', sort_headword,
                    'headwordGroupId', headword_group_id
                )
            )
            FROM returned_groups
            ORDER BY
                tier_rank DESC,
                match_rank DESC,
                dictionary_rank DESC,
                sort_headword DESC,
                headword_group_id DESC
            LIMIT 1
        ),
        (
            SELECT count(*)::integer
            FROM candidate_identity
            WHERE headword_group_id IS NULL
        ),
        (
            SELECT error_payload
            FROM oversized_groups
        ), (SELECT count(*)::integer FROM candidate_groups), (SELECT COALESCE(jsonb_agg(DISTINCT candidate.entry_id),'[]'::jsonb) FROM candidate_identity candidate JOIN returned_groups page ON page.headword_group_id=candidate.headword_group_id)
    INTO
        v_items,
        v_has_more,
        v_next_cursor,
        v_missing_identity_count,
        v_oversized_group,v_total_groups,v_matching_ids;

    IF v_missing_identity_count > 0 THEN
        RETURN jsonb_build_object(
            'error', 'presentation_identity_incomplete'
        );
    END IF;
    IF v_oversized_group IS NOT NULL THEN
        RETURN jsonb_build_object(
            'error', 'group-too-large',
            'group', v_oversized_group
        );
    END IF;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'matchingEntryIds', v_matching_ids, 'totalGroups', v_total_groups,
            'selectedTierComplete', NOT COALESCE(v_has_more, false),
            'nextGroupCursor', CASE
                WHEN COALESCE(v_has_more, false) THEN v_next_cursor
                ELSE NULL
            END
        )
    );
END;
$$;


--
-- Name: lookup_platform_v2_library_material_filtered_entries_base_v1(uuid, boolean, text, text, text, integer, integer, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.lookup_platform_v2_library_material_filtered_entries_base_v1(p_user_id uuid, p_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50, p_library_selection jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text :=
        NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_group_limit integer :=
        LEAST(GREATEST(COALESCE(p_group_limit, 10), 1), 25);
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_cursor jsonb :=
        private.decode_dictionary_search_cursor_v1(p_cursor);
    v_query_key text;
    v_cursor_tier_rank integer;
    v_cursor_match_rank integer;
    v_cursor_dictionary_rank integer;
    v_cursor_sort_headword text;
    v_cursor_group_id uuid;
    v_items jsonb;
    v_has_more boolean;
    v_next_cursor text;
    v_missing_identity_count integer;
    v_matching_ids jsonb; v_total_groups integer; v_oversized_group jsonb;
BEGIN
    IF p_catalog AND p_user_id IS NOT NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF NOT p_catalog AND p_user_id IS NULL THEN
        RETURN jsonb_build_object('error', 'invalid_principal');
    END IF;
    IF v_raw_query IS NULL THEN
        RETURN private.lookup_platform_v2_library_material_browse_entries_v1(
            p_user_id,p_catalog,p_query,p_language_code,p_cursor,p_group_limit,p_group_entry_bound,p_library_selection);
    END IF;
    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent :=
        normalize_dictionary_search_text_unaccent(v_raw_query);
    v_query_key := encode(
        digest(
            concat_ws(
                chr(31),
                'platform-v2-group-cursor-v1',
                COALESCE(p_user_id::text, 'catalog'),
                p_catalog::text,
                v_raw_query,
                v_query,
                v_query_unaccent,
                COALESCE(v_language_code, ''), p_library_selection::text
            ),
            'sha256'
        ),
        'hex'
    );

    IF NULLIF(trim(COALESCE(p_cursor, '')), '') IS NOT NULL THEN
        IF v_cursor = '{}'::jsonb
           OR v_cursor->>'version' <> 'platform-v2-group-cursor-v1'
           OR v_cursor->>'queryKey' IS DISTINCT FROM v_query_key THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
        BEGIN
            v_cursor_tier_rank := (v_cursor->>'tierRank')::integer;
            v_cursor_match_rank := (v_cursor->>'matchRank')::integer;
            v_cursor_dictionary_rank :=
                (v_cursor->>'dictionaryRank')::integer;
            v_cursor_sort_headword := v_cursor->>'sortHeadword';
            v_cursor_group_id := (v_cursor->>'headwordGroupId')::uuid;
        EXCEPTION WHEN others THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END;
        IF v_cursor_sort_headword IS NULL
           OR v_cursor_group_id IS NULL THEN
            RETURN jsonb_build_object('error', 'invalid_cursor');
        END IF;
    END IF;

    IF p_catalog
       AND EXISTS (
           SELECT 1
           FROM private.active_word_entries AS entry
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = entry.dictionary_id AND private.entry_access_v1(p_user_id,entry.id,'browse')
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR entry.language_code = v_language_code
             )
           LIMIT 1
       )
       AND NOT EXISTS (
           SELECT 1
           FROM public.dictionary_search_documents AS document
           JOIN public.dictionaries AS dictionary
             ON dictionary.id = document.dictionary_id
           WHERE dictionary.visibility IN ('system', 'public')
             AND dictionary.kind <> 'user'
             AND (
                 v_language_code IS NULL
                 OR document.language_code = v_language_code
             )
           LIMIT 1
       ) THEN
        RETURN jsonb_build_object('error', 'search_index_not_ready');
    END IF;

    WITH shared_entries AS MATERIALIZED (SELECT entry_id FROM private.shared_author_entry_ids_v1(p_user_id)), material_entries AS MATERIALIZED (SELECT entry_id FROM private.readable_material_entry_ids_v1(p_user_id,p_library_selection->'material')), user_context AS MATERIALIZED (
        SELECT COALESCE(
            (
                SELECT subscription_tier
                FROM public.user_settings
                WHERE user_id = p_user_id
            ),
            'free'
        ) AS subscription_tier
    ),
    eligible_dictionaries AS MATERIALIZED (
      SELECT dictionary.*, CASE WHEN dictionary.kind='user' THEN 0 WHEN dictionary.kind='curated' THEN 1 ELSE 2 END AS dictionary_rank
      FROM public.dictionaries dictionary
      WHERE (
      (public.can_browse_dictionary(p_user_id,dictionary.id)
        AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id))
      OR (dictionary.kind='user' AND EXISTS (
        SELECT 1 FROM material_entries selected
        JOIN private.active_word_entries shared_entry ON shared_entry.id=selected.entry_id
        WHERE shared_entry.dictionary_id=dictionary.id
      )))
        AND private.training_material_entry_selected_v1(dictionary.language_code,
          CASE WHEN dictionary.kind='user' THEN NULL ELSE dictionary.id END,p_library_selection)
    ),
    indexed_headword_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'exact-headword'::text AS resolved_by,
            document.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id JOIN material_entries material_member ON material_member.entry_id=document.entry_id
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND (v_raw_query IS NULL OR document.normalized_headword = v_query)

        UNION ALL

        SELECT
            document.entry_id,
            'exact-headword'::text,
            document.headword,
            1,
            CASE
                WHEN document.headword = v_raw_query THEN 0
                WHEN document.normalized_headword = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_documents AS document
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id JOIN material_entries material_member ON material_member.entry_id=document.entry_id
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND (
            v_language_code IS NULL
            OR document.language_code = v_language_code
        )
          AND document.normalized_headword_unaccent =
              v_query_unaccent
          AND document.normalized_headword <> v_query
    ),
    legacy_user_headword_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'exact-headword'::text AS resolved_by,
            entry.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN entry.headword = v_raw_query THEN 0
                WHEN lower(entry.headword) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM private.active_word_entries AS entry
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries)) JOIN material_entries material_member ON material_member.entry_id=entry.id
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE private.library_entry_matches_filters_v1(entry.part_of_speech,entry.gender,p_library_selection) AND NOT p_catalog
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR entry.language_code = v_language_code
          )
          AND (
              v_raw_query IS NULL OR lower(entry.headword) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(
                  entry.headword
              ) = v_query_unaccent
          )
    ),
    headword_matches AS MATERIALIZED (
        SELECT * FROM indexed_headword_matches
        UNION ALL
        SELECT * FROM legacy_user_headword_matches
    ),
    headword_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM headword_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.headword),
            match.meaning_id
    ),
    indexed_form_matches AS MATERIALIZED (
        SELECT
            document.entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            field.display_text AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END AS match_rank,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id JOIN material_entries material_member ON material_member.entry_id=document.entry_id
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text = v_query

        UNION ALL

        SELECT
            document.entry_id,
            'lemma-or-inflection'::text,
            field.display_text,
            2,
            CASE
                WHEN field.display_text = v_raw_query THEN 0
                WHEN field.normalized_text = v_query THEN 1
                ELSE 2
            END,
            document.headword,
            document.meaning_id,
            document.dictionary_id
        FROM public.dictionary_search_fields AS field
        JOIN public.dictionary_search_documents AS document
          ON document.entry_id = field.entry_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = document.dictionary_id JOIN material_entries material_member ON material_member.entry_id=document.entry_id
        JOIN private.active_word_entries AS filter_entry ON filter_entry.id=document.entry_id
        WHERE private.library_entry_matches_filters_v1(filter_entry.part_of_speech,filter_entry.gender,p_library_selection) AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND field.field_group = 'form'
          AND (
              v_language_code IS NULL
              OR field.language_code = v_language_code
          )
          AND field.normalized_text_unaccent = v_query_unaccent
          AND field.normalized_text <> v_query
    ),
    legacy_user_form_matches AS MATERIALIZED (
        SELECT
            entry.id AS entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            form.form AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN form.form = v_raw_query THEN 0
                WHEN lower(form.form) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            entry.headword,
            entry.meaning_id,
            entry.dictionary_id
        FROM public.word_forms AS form
        JOIN private.active_word_entries AS entry
          ON entry.id = form.word_id
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries)) JOIN material_entries material_member ON material_member.entry_id=entry.id
        LEFT JOIN public.dictionary_search_documents AS document
          ON document.entry_id = entry.id
        WHERE private.library_entry_matches_filters_v1(entry.part_of_speech,entry.gender,p_library_selection) AND NOT p_catalog
          AND NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND dictionary.kind = 'user'
          AND document.entry_id IS NULL
          AND (
              v_language_code IS NULL
              OR form.language_code = v_language_code
          )
          AND form.language_code = entry.language_code
          AND (
              form.dictionary_id IS NULL
              OR form.dictionary_id = entry.dictionary_id
          )
          AND (
              lower(form.form) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(form.form) =
                  v_query_unaccent
          )
    ),
    form_matches AS MATERIALIZED (
        SELECT * FROM indexed_form_matches
        UNION ALL
        SELECT * FROM legacy_user_form_matches
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (match.entry_id)
            match.*
        FROM form_matches AS match
        ORDER BY
            match.entry_id,
            match.match_rank,
            normalize_dictionary_search_text(match.matched_text)
    ),
    candidates AS MATERIALIZED (
        SELECT * FROM headword_candidates
        UNION ALL
        SELECT * FROM form_candidates
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
    ),
    candidate_identity AS MATERIALIZED (
        SELECT
            candidate.*,
            CASE WHEN v_raw_query IS NULL THEN 0 ELSE dictionary.dictionary_rank END AS dictionary_rank,
            COALESCE(
                source_group.id,
                user_group.id
            ) AS headword_group_id
        FROM candidates AS candidate
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = candidate.dictionary_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON binding.word_entry_id = candidate.entry_id
         AND binding.binding_state = 'active'
        LEFT JOIN private.platform_v2_headword_groups AS source_group
          ON source_group.management_kind = 'source'
         AND source_group.dictionary_id = binding.dictionary_id
         AND source_group.identity_scheme_version =
             binding.identity_scheme_version
         AND source_group.source_group_key = binding.source_group_key
        LEFT JOIN private.platform_v2_headword_groups AS user_group
          ON user_group.management_kind = 'user'
         AND user_group.singleton_entry_id = candidate.entry_id
    ),
    candidate_groups AS MATERIALIZED (
        SELECT
            headword_group_id,
            min(tier_rank) AS tier_rank,
            min(match_rank) AS match_rank,
            min(dictionary_rank) AS dictionary_rank,
            min(normalize_dictionary_search_text(headword))
                AS sort_headword,
            (array_agg(
                resolved_by
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS resolved_by,
            (array_agg(
                matched_text
                ORDER BY
                    tier_rank,
                    match_rank,
                    dictionary_rank,
                    normalize_dictionary_search_text(headword),
                    entry_id
            ))[1] AS matched_text
        FROM candidate_identity
        WHERE headword_group_id IS NOT NULL
        GROUP BY headword_group_id
    ),
    after_cursor AS MATERIALIZED (
        SELECT *
        FROM candidate_groups
        WHERE v_cursor_group_id IS NULL
           OR (
                tier_rank,
                match_rank,
                dictionary_rank,
                sort_headword,
                headword_group_id
           ) > (
                v_cursor_tier_rank,
                v_cursor_match_rank,
                v_cursor_dictionary_rank,
                v_cursor_sort_headword,
                v_cursor_group_id
           )
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit + 1
    ),
    returned_groups AS MATERIALIZED (
        SELECT *
        FROM after_cursor
        ORDER BY
            tier_rank,
            match_rank,
            dictionary_rank,
            sort_headword,
            headword_group_id
        LIMIT v_group_limit
    ),
    group_entry_ids AS MATERIALIZED (
        SELECT
            group_page.*,
            entry.id AS entry_id,
            COALESCE(binding.sense_ordinal, entry.meaning_id)
                AS group_meaning_order
        FROM returned_groups AS group_page
        JOIN private.platform_v2_headword_groups AS headword_group
          ON headword_group.id = group_page.headword_group_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
         AND binding.binding_state = 'active'
        JOIN private.active_word_entries AS entry
          ON entry.id = COALESCE(
              binding.word_entry_id,
              headword_group.singleton_entry_id
          )
        JOIN eligible_dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
    ),
    group_sizes AS MATERIALIZED (
        SELECT
            headword_group_id,
            count(*)::integer AS entry_count
        FROM group_entry_ids
        GROUP BY headword_group_id
    ),
    oversized_groups AS MATERIALIZED (
        SELECT jsonb_build_object(
            'headwordGroupId', size.headword_group_id,
            'entryCount', size.entry_count,
            'safetyBound', v_group_entry_bound
        ) AS error_payload
        FROM group_sizes AS size
        WHERE size.entry_count > v_group_entry_bound
        ORDER BY size.entry_count DESC, size.headword_group_id
        LIMIT 1
    ),
    group_entries AS MATERIALIZED (
        SELECT
            member.tier_rank,
            member.match_rank,
            member.dictionary_rank,
            member.sort_headword,
            member.resolved_by,
            member.matched_text,
            member.headword_group_id,
            member.group_meaning_order,
            entry.*,
            dictionary.language_code AS dictionary_language_code,
            dictionary.slug AS dictionary_slug,
            dictionary.name AS dictionary_name,
            dictionary.kind AS dictionary_kind,
            dictionary.visibility AS dictionary_visibility,
            dictionary.owner_user_id AS dictionary_owner_user_id,
            dictionary.is_editable AS dictionary_is_editable,
            dictionary.schema_key AS dictionary_schema_key,
            dictionary.schema_version AS dictionary_schema_version
        FROM group_entry_ids AS member
        JOIN private.active_word_entries AS entry
          ON entry.id = member.entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id OR entry.id IN (SELECT entry_id FROM shared_entries))
        WHERE NOT EXISTS (SELECT 1 FROM oversized_groups)
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', entry.id,
                'dictionary_id', entry.dictionary_id,
                'language_code', entry.language_code,
                'headword', entry.headword,
                'meaning_id', entry.meaning_id,
                'part_of_speech', entry.part_of_speech,
                'gender', entry.gender,
                'raw', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN private.shared_instructional_raw_v1(entry.raw) ELSE entry.raw END,
                'is_nt2_2000', entry.is_nt2_2000,
                'meanings_count', size.entry_count,
                'dictionary', jsonb_build_object(
                    'id', entry.dictionary_id,
                    'language_code', entry.dictionary_language_code,
                    'slug', entry.dictionary_slug,
                    'name', entry.dictionary_name,
                    'kind', entry.dictionary_kind,
                    'visibility', entry.dictionary_visibility,
                    'owner_user_id',
                        entry.dictionary_owner_user_id,
                    'is_editable', CASE
      WHEN entry.dictionary_kind='user' AND entry.dictionary_owner_user_id IS DISTINCT FROM p_user_id
      THEN false ELSE entry.dictionary_is_editable END,
                    'schema_key', entry.dictionary_schema_key,
                    'schema_version',
                        entry.dictionary_schema_version
                ),
                'dictionary_name', entry.dictionary_name,
                'dictionary_slug', entry.dictionary_slug,
                'dictionary_kind', entry.dictionary_kind,
                'search_match_group', entry.resolved_by,
                'search_matched_text', entry.matched_text
            )) AS payload,
            entry.tier_rank,
            entry.match_rank,
            entry.dictionary_rank,
            entry.sort_headword,
            entry.headword_group_id,
            entry.group_meaning_order,
            entry.id
        FROM group_entries AS entry
        JOIN group_sizes AS size
          ON size.headword_group_id = entry.headword_group_id
    )
    SELECT
        COALESCE(
            (
                SELECT jsonb_agg(
                    payload
                    ORDER BY
                        tier_rank,
                        match_rank,
                        dictionary_rank,
                        sort_headword,
                        headword_group_id,
                        group_meaning_order,
                        id
                )
                FROM payloads
            ),
            '[]'::jsonb
        ),
        (SELECT count(*) > v_group_limit FROM after_cursor),
        (
            SELECT private.encode_dictionary_search_cursor_v1(
                jsonb_build_object(
                    'version', 'platform-v2-group-cursor-v1',
                    'queryKey', v_query_key,
                    'tierRank', tier_rank,
                    'matchRank', match_rank,
                    'dictionaryRank', dictionary_rank,
                    'sortHeadword', sort_headword,
                    'headwordGroupId', headword_group_id
                )
            )
            FROM returned_groups
            ORDER BY
                tier_rank DESC,
                match_rank DESC,
                dictionary_rank DESC,
                sort_headword DESC,
                headword_group_id DESC
            LIMIT 1
        ),
        (
            SELECT count(*)::integer
            FROM candidate_identity
            WHERE headword_group_id IS NULL
        ),
        (
            SELECT error_payload
            FROM oversized_groups
        ), (SELECT count(*)::integer FROM candidate_groups), (SELECT COALESCE(jsonb_agg(DISTINCT candidate.entry_id),'[]'::jsonb) FROM candidate_identity candidate JOIN returned_groups page ON page.headword_group_id=candidate.headword_group_id)
    INTO
        v_items,
        v_has_more,
        v_next_cursor,
        v_missing_identity_count,
        v_oversized_group,v_total_groups,v_matching_ids;

    IF v_missing_identity_count > 0 THEN
        RETURN jsonb_build_object(
            'error', 'presentation_identity_incomplete'
        );
    END IF;
    IF v_oversized_group IS NOT NULL THEN
        RETURN jsonb_build_object(
            'error', 'group-too-large',
            'group', v_oversized_group
        );
    END IF;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'matchingEntryIds', v_matching_ids, 'totalGroups', v_total_groups,
            'selectedTierComplete', NOT COALESCE(v_has_more, false),
            'nextGroupCursor', CASE
                WHEN COALESCE(v_has_more, false) THEN v_next_cursor
                ELSE NULL
            END
        )
    );
END;
$$;


--
-- Name: mark_training_session_member_unavailable(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mark_training_session_member_unavailable(p_user_id uuid, p_session_id uuid, p_entry_id uuid, p_card_type_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_session public.training_sessions%rowtype;
  v_member public.training_session_members%rowtype;
  v_expected_member public.training_session_members%rowtype;
  v_entry public.word_entries%rowtype;
  v_remaining integer;
BEGIN
  IF p_reason NOT IN ('direct-example-missing','pair-excluded') THEN
    RETURN private.mark_training_session_member_unavailable_base_v1(
      p_user_id, p_session_id, p_entry_id, p_card_type_id, p_reason
    );
  END IF;

  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;

  SELECT * INTO v_session
  FROM public.training_sessions session
  WHERE session.id = p_session_id AND session.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not-member'); END IF;

  SELECT member.* INTO v_member
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.entry_id = p_entry_id
    AND member.card_type_id = p_card_type_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not-member'); END IF;
  IF v_member.consumed_at IS NOT NULL THEN
    RETURN jsonb_build_object('status', 'consumed', 'ordinal', v_member.ordinal);
  END IF;
  IF v_member.unavailable_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'unavailable', 'ordinal', v_member.ordinal,
      'reason', v_member.unavailable_reason
    );
  END IF;

  SELECT entry.* INTO v_entry
  FROM private.active_word_entries entry
  WHERE entry.id = v_member.entry_id;
  IF NOT FOUND
     OR (p_reason='pair-excluded' AND NOT private.training_pair_excluded_v1(
       p_user_id,'meaning',v_member.entry_id,NULL,NULL,v_member.card_type_id))
     OR (p_reason='direct-example-missing' AND private.training_ordinary_direct_recall_renderable_v1(
       v_entry.id, v_entry.meaning_id, v_member.card_type_id
     )) THEN
    RAISE EXCEPTION
      'training session unavailable evidence mismatch: requested %, observed %',
      p_reason,
      CASE WHEN NOT FOUND THEN 'entry-not-found' ELSE 'member-renderable' END;
  END IF;

  SELECT member.* INTO v_expected_member
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.consumed_at IS NULL
    AND member.unavailable_at IS NULL
  ORDER BY member.ordinal
  LIMIT 1;
  IF NOT FOUND
     OR v_expected_member.entry_id IS DISTINCT FROM v_member.entry_id
     OR v_expected_member.card_type_id IS DISTINCT FROM v_member.card_type_id THEN
    RETURN jsonb_build_object(
      'status', 'out-of-order', 'ordinal', v_member.ordinal,
      'expectedOrdinal', v_expected_member.ordinal
    );
  END IF;

  UPDATE public.training_session_members
  SET unavailable_at = private.training_reference_now_v1(), unavailable_reason = p_reason
  WHERE session_id = v_member.session_id AND ordinal = v_member.ordinal;

  SELECT count(*)::integer INTO v_remaining
  FROM public.training_session_members member
  WHERE member.session_id = v_member.session_id
    AND member.consumed_at IS NULL
    AND member.unavailable_at IS NULL;
  IF v_remaining = 0 THEN
    UPDATE public.training_sessions
    SET completed_at = COALESCE(completed_at, private.training_reference_now_v1())
    WHERE id = v_member.session_id;
  END IF;

  RETURN jsonb_build_object(
    'status', CASE WHEN v_remaining = 0 THEN 'unavailable-complete' ELSE 'unavailable' END,
    'ordinal', v_member.ordinal,
    'reason', p_reason,
    'remaining', v_remaining
  );
END;
$$;


--
-- Name: mark_training_session_member_unavailable_base_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mark_training_session_member_unavailable_base_v1(p_user_id uuid, p_session_id uuid, p_entry_id uuid, p_card_type_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_session public.training_sessions%rowtype;
  v_member public.training_session_members%rowtype;
  v_expected_member public.training_session_members%rowtype;
  v_entry public.word_entries%rowtype;
  v_projected_card jsonb;
  v_platform_group jsonb;
  v_schema_key text;
  v_render_capabilities text[];
  v_evidence_reason text;
  v_remaining integer;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;

  IF p_reason NOT IN (
    'dictionary-access-revoked',
    'projection-missing',
    'entry-not-found',
    'entry-archived',
    'model-invalid',
    'reverse-definition-missing'
  ) THEN
    RAISE EXCEPTION 'invalid training session unavailable reason: %', p_reason;
  END IF;

  -- Serialize status changes with accepted card actions. This also makes the
  -- remaining count and completion transition deterministic under retries.
  SELECT * INTO v_session
  FROM public.training_sessions session
  WHERE session.id = p_session_id
    AND session.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not-member');
  END IF;

  SELECT member.* INTO v_member
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.entry_id = p_entry_id
    AND member.card_type_id = p_card_type_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('status', 'not-member');
  END IF;
  IF v_member.consumed_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'consumed',
      'ordinal', v_member.ordinal
    );
  END IF;
  IF v_member.unavailable_at IS NOT NULL THEN
    RETURN jsonb_build_object(
      'status', 'unavailable',
      'ordinal', v_member.ordinal,
      'reason', v_member.unavailable_reason
    );
  END IF;

  -- Do not let a client retire an otherwise valid member by naming an
  -- arbitrary allowed reason. Re-check the current server state at the
  -- mutation boundary. The selector is read-only, so this check is the
  -- authoritative evidence that makes the retirement legal.
  SELECT entry.* INTO v_entry
  FROM public.word_entries entry
  WHERE entry.id = v_member.entry_id;
  IF NOT FOUND THEN
    v_evidence_reason := 'entry-not-found';
  ELSIF v_entry.archived_at IS NOT NULL THEN
    v_evidence_reason := 'entry-archived';
  ELSIF NOT private.entry_access_v1(p_user_id,v_entry.id,'train') THEN
    v_evidence_reason := 'dictionary-access-revoked';
  ELSE
    -- Keep the evidence order aligned with the client lookup contract when
    -- the observed lookup failure is projection-missing. A missing Platform
    -- presentation identity is then authoritative even when the underlying
    -- raw payload is also malformed; otherwise the mark RPC could reject the
    -- exact diagnostic that caused the retry. For other requested reasons we
    -- preserve the more specific model checks below and only use identity as
    -- the fallback.
    IF p_reason = 'projection-missing' THEN
      v_platform_group := public.read_platform_v2_training_group(
        p_user_id,
        v_member.entry_id,
        50
      );
      IF v_platform_group->>'error' = 'presentation_identity_incomplete'
         OR (
           v_platform_group->>'error' IS NULL
           AND NOT EXISTS (
             SELECT 1
             FROM jsonb_array_elements(COALESCE(v_platform_group->'items', '[]'::jsonb)) item
             WHERE item->>'id' = v_member.entry_id::text
           )
         ) THEN
        v_evidence_reason := 'projection-missing';
      END IF;
    END IF;

    IF v_evidence_reason IS NULL THEN
      SELECT dictionary.schema_key, schema_row.render_capabilities
      INTO v_schema_key, v_render_capabilities
      FROM public.dictionaries dictionary
      LEFT JOIN public.dictionary_schemas schema_row
        ON schema_row.schema_key = dictionary.schema_key
       AND schema_row.version = dictionary.schema_version
      WHERE dictionary.id = v_entry.dictionary_id;

      v_projected_card := private.project_training_scheduler_candidate_v1(
        p_user_id,
        v_member.entry_id,
        v_member.card_type_id,
        v_member.queue_source,
        COALESCE(v_session.training_filter, '{}'::jsonb),
        private.training_filter_target_date(COALESCE(v_session.training_filter, '{}'::jsonb)) IS NOT NULL
          OR NULLIF(COALESCE(v_session.training_filter, '{}'::jsonb)->>'sourceId', '') IS NOT NULL
          OR NULLIF(trim(COALESCE(v_session.training_filter, '{}'::jsonb)->>'sourceKind'), '') IS NOT NULL
          OR NULLIF(trim(COALESCE(v_session.training_filter, '{}'::jsonb)->>'externalId'), '') IS NOT NULL,
        0,
        0,
        0,
        0,
        0
      );
      IF v_projected_card IS NULL THEN
        v_evidence_reason := 'projection-missing';
      ELSIF jsonb_typeof(v_entry.raw) IS DISTINCT FROM 'object' THEN
        v_evidence_reason := 'model-invalid';
      ELSIF v_schema_key = 'user-entry-v1'
        AND (
          NULLIF(trim(v_entry.headword), '') IS NULL
          OR NOT (
            NULLIF(trim(v_entry.raw->>'definition'), '') IS NOT NULL
            OR NULLIF(trim(v_entry.raw->'translation'->>'text'), '') IS NOT NULL
            OR NULLIF(trim(v_entry.raw->'example'->>'source'), '') IS NOT NULL
            OR NULLIF(trim(v_entry.raw->>'notes'), '') IS NOT NULL
          )
        ) THEN
        v_evidence_reason := 'model-invalid';
      ELSIF 'definitions' = ANY(COALESCE(v_render_capabilities, ARRAY[]::text[]))
        AND v_schema_key <> 'user-entry-v1'
        AND jsonb_typeof(v_entry.raw->'meanings') IS DISTINCT FROM 'array' THEN
        v_evidence_reason := 'model-invalid';
      ELSIF v_member.card_type_id = 'definition-to-word' AND (
        (v_schema_key = 'user-entry-v1'
          AND NULLIF(trim(v_entry.raw->>'definition'), '') IS NULL)
        OR (v_schema_key <> 'user-entry-v1'
          AND NOT EXISTS (
            SELECT 1
            FROM jsonb_array_elements(COALESCE(v_entry.raw->'meanings', '[]'::jsonb)) meaning
            WHERE NULLIF(trim(meaning->>'definition'), '') IS NOT NULL
          ))
      ) THEN
        v_evidence_reason := 'reverse-definition-missing';
      END IF;
      IF v_evidence_reason IS NULL THEN
        v_platform_group := public.read_platform_v2_training_group(
          p_user_id,
          v_member.entry_id,
          50
        );
        IF v_platform_group->>'error' = 'presentation_identity_incomplete'
           OR (
             v_platform_group->>'error' IS NULL
             AND NOT EXISTS (
               SELECT 1
               FROM jsonb_array_elements(COALESCE(v_platform_group->'items', '[]'::jsonb)) item
               WHERE item->>'id' = v_member.entry_id::text
             )
           ) THEN
          v_evidence_reason := 'projection-missing';
        END IF;
      END IF;
    END IF;
  END IF;

  IF v_evidence_reason IS DISTINCT FROM p_reason THEN
    RAISE EXCEPTION
      'training session unavailable evidence mismatch: requested %, observed %',
      p_reason,
      COALESCE(v_evidence_reason, 'member-renderable');
  END IF;

  SELECT member.* INTO v_expected_member
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.consumed_at IS NULL
    AND member.unavailable_at IS NULL
  ORDER BY member.ordinal
  LIMIT 1;
  IF NOT FOUND
     OR v_expected_member.entry_id IS DISTINCT FROM v_member.entry_id
     OR v_expected_member.card_type_id IS DISTINCT FROM v_member.card_type_id THEN
    RETURN jsonb_build_object(
      'status', 'out-of-order',
      'ordinal', v_member.ordinal,
      'expectedOrdinal', v_expected_member.ordinal
    );
  END IF;

  UPDATE public.training_session_members
  SET unavailable_at = private.training_reference_now_v1(),
      unavailable_reason = p_reason
  WHERE session_id = v_member.session_id
    AND ordinal = v_member.ordinal;

  SELECT count(*)::integer INTO v_remaining
  FROM public.training_session_members member
  WHERE member.session_id = v_member.session_id
    AND member.consumed_at IS NULL
    AND member.unavailable_at IS NULL;

  IF v_remaining = 0 THEN
    UPDATE public.training_sessions
    SET completed_at = COALESCE(completed_at, private.training_reference_now_v1())
    WHERE id = v_member.session_id;
  END IF;

  RETURN jsonb_build_object(
    'status', CASE WHEN v_remaining = 0 THEN 'unavailable-complete' ELSE 'unavailable' END,
    'ordinal', v_member.ordinal,
    'reason', p_reason,
    'remaining', v_remaining
  );
END;
$$;


--
-- Name: mark_training_session_member_unavailable_latch_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mark_training_session_member_unavailable_latch_v1(p_user_id uuid, p_session_id uuid, p_entry_id uuid, p_card_type_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_result jsonb;
  v_session public.training_sessions%rowtype;
  v_replacement record;
  v_card_keys text[];
  v_ratio integer;
  v_completed_actions integer;
  v_queue_turn text;
  v_filtered boolean;
  v_next_ordinal integer;
  v_remaining integer;
  v_was_unavailable boolean := false;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;

  -- Match the action-consumption lock order: session before member. The
  -- private evidence check takes the same locks, so a retry cannot deadlock
  -- with an accepted action for this session.
  PERFORM 1
  FROM public.training_sessions session
  WHERE session.id = p_session_id
    AND session.user_id = p_user_id
  FOR UPDATE;

  SELECT member.unavailable_at IS NOT NULL INTO v_was_unavailable
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.entry_id = p_entry_id
    AND member.card_type_id = p_card_type_id
  FOR UPDATE;

  v_result := private.mark_training_session_member_unavailable(
    p_user_id, p_session_id, p_entry_id, p_card_type_id, p_reason
  );
  IF v_result->>'status' NOT IN ('unavailable', 'unavailable-complete') THEN
    RETURN v_result;
  END IF;
  IF v_was_unavailable THEN
    RETURN v_result;
  END IF;

  SELECT * INTO v_session
  FROM public.training_sessions session
  WHERE session.id = p_session_id AND session.user_id = p_user_id
  FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not-member'); END IF;

  SELECT count(*)::integer INTO v_completed_actions
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id AND member.consumed_at IS NOT NULL;
  -- Explicit sessions retain their original rhythm even if preferences change.
  -- Pre-existing sessions have no latch and keep their historical fallback.
  SELECT COALESCE(
    v_session.new_review_ratio,
    LEAST(5, GREATEST(1, settings.new_review_ratio)),
    2
  ) INTO v_ratio
  FROM (SELECT 1) seed
  LEFT JOIN user_settings settings ON settings.user_id = p_user_id;
  v_queue_turn := CASE
    WHEN v_session.card_filter <> 'both' THEN 'auto'
    WHEN mod(v_completed_actions, v_ratio + 1) = 0 THEN 'new'
    ELSE 'review'
  END;
  SELECT COALESCE(array_agg(member.entry_id::text || ':' || member.card_type_id), ARRAY[]::text[])
    INTO v_card_keys
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id;
  v_filtered := private.training_filter_target_date(v_session.training_filter) IS NOT NULL
    OR NULLIF(v_session.training_filter->>'sourceId', '') IS NOT NULL
    OR NULLIF(trim(v_session.training_filter->>'sourceKind'), '') IS NOT NULL
    OR NULLIF(trim(v_session.training_filter->>'externalId'), '') IS NOT NULL;

  SELECT candidate.* INTO v_replacement
  FROM private.training_scheduler_candidates_v2(
    p_user_id, v_session.card_type_ids, v_session.list_id, v_session.list_type,
    v_session.card_filter, v_queue_turn, ARRAY[]::uuid[], v_card_keys,
    v_session.training_filter, v_filtered, false
  ) candidate
  WHERE candidate.queue_source IN ('new', 'learning', 'review')
  ORDER BY candidate.selection_order
  LIMIT 1;

  IF FOUND AND v_completed_actions < v_session.requested_total THEN
    SELECT COALESCE(max(member.ordinal), 0) + 1 INTO v_next_ordinal
    FROM public.training_session_members member
    WHERE member.session_id = p_session_id;
    INSERT INTO public.training_session_members (
      session_id, ordinal, entry_id, card_type_id, queue_source
    ) VALUES (
      p_session_id, v_next_ordinal, v_replacement.entry_id,
      v_replacement.card_type_id, v_replacement.queue_source
    );
    UPDATE public.training_sessions
    SET completed_at = NULL, exhausted_at = NULL, completion_reason = NULL
    WHERE id = p_session_id;
    RETURN jsonb_build_object(
      'status', 'unavailable-replaced',
      'ordinal', v_result->'ordinal',
      'reason', p_reason,
      'replacementOrdinal', v_next_ordinal
    );
  END IF;

  SELECT count(*)::integer INTO v_remaining
  FROM public.training_session_members member
  WHERE member.session_id = p_session_id
    AND member.consumed_at IS NULL
    AND member.unavailable_at IS NULL;
  IF v_remaining = 0 THEN
    UPDATE public.training_sessions
    SET completed_at = COALESCE(completed_at, private.training_reference_now_v1()),
        exhausted_at = COALESCE(exhausted_at, private.training_reference_now_v1()),
        completion_reason = COALESCE(completion_reason, 'exhausted')
    WHERE id = p_session_id;
    RETURN jsonb_build_object(
      'status', 'unavailable-exhausted',
      'ordinal', v_result->'ordinal',
      'reason', p_reason,
      'remaining', 0
    );
  END IF;
  RETURN v_result;
END;
$$;


--
-- Name: merge_owned_entry_edit_v1(jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.merge_owned_entry_edit_v1(p_existing jsonb, p_incoming jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE merged jsonb;
BEGIN
  IF jsonb_typeof(p_incoming) IS DISTINCT FROM 'object' THEN
    RAISE EXCEPTION 'invalid_user_entry' USING ERRCODE='22023';
  END IF;
  IF NOT (p_existing ? 'meanings') OR p_incoming ? 'meanings' THEN RETURN p_incoming; END IF;
  merged:=p_existing||p_incoming;
  IF p_incoming ? 'definition' AND p_incoming->'definition' IS DISTINCT FROM p_existing->'definition' THEN
    IF jsonb_array_length(p_existing->'meanings')<>1 THEN
      RAISE EXCEPTION 'rich_entry_edit_requires_content' USING ERRCODE='22023';
    END IF;
    merged:=jsonb_set(merged,'{meanings,0,definition}',p_incoming->'definition');
  END IF;
  RETURN merged;
END;
$$;


--
-- Name: mutate_collection_share_v1(uuid, text, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.mutate_collection_share_v1(p_operation_id uuid, p_action text, p_collection_id uuid, p_expected_revision integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); root private.collection_sharing_roots%rowtype;
  request jsonb; replay jsonb; invitation_code text;
BEGIN
  IF p_action IS NULL OR p_action NOT IN ('open','rotate','close') OR p_collection_id IS NULL
    OR p_expected_revision IS NULL OR p_expected_revision<0 OR p_expected_revision>=2147483646 THEN
    RAISE EXCEPTION 'invalid_share_command' USING ERRCODE='22023';
  END IF;
  request:=jsonb_build_object('action',p_action,'collectionId',p_collection_id,'expectedRevision',p_expected_revision);
  replay:=private.begin_collection_share_command_v1(p_operation_id,request);
  IF replay IS NOT NULL THEN RETURN replay; END IF;
  -- Collection before root: creation and ordinary membership FK writes serialize.
  PERFORM 1 FROM public.user_word_lists l WHERE l.id=p_collection_id AND l.user_id=principal FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501'; END IF;
  IF p_action='open' THEN
    -- Same list→membership→root order as copy preparation. This also fences
    -- UPDATE/DELETE before the first root exists.
    PERFORM 1 FROM public.user_word_list_items item WHERE item.list_id=p_collection_id ORDER BY item.word_id FOR UPDATE;
    PERFORM private.lock_sharing_author_scope_v1(principal,true);
    INSERT INTO private.collection_sharing_roots(owner_user_id,collection_id)
      VALUES(principal,p_collection_id) ON CONFLICT(collection_id) DO NOTHING;
  END IF;
  PERFORM private.lock_sharing_author_scope_v1(principal,true);
  SELECT * INTO root FROM private.collection_sharing_roots r WHERE r.collection_id=p_collection_id FOR UPDATE;
  IF NOT FOUND OR root.owner_user_id<>principal THEN RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501'; END IF;
  IF root.revision<>p_expected_revision THEN RAISE EXCEPTION 'share_revision_conflict' USING ERRCODE='40001'; END IF;
  IF p_action='open' AND NOT root.is_open THEN
    IF EXISTS(SELECT 1 FROM public.user_word_list_items item
      JOIN public.word_entries entry ON entry.id=item.word_id
      JOIN public.dictionaries d ON d.id=entry.dictionary_id
      WHERE item.list_id=p_collection_id AND d.kind='user' AND d.owner_user_id IS DISTINCT FROM principal) THEN
      RAISE EXCEPTION 'share_copy_required' USING ERRCODE='22023';
    END IF;
    UPDATE private.collection_sharing_roots SET is_open=true,access_lifetime=gen_random_uuid(),revision=revision+1 WHERE id=root.id;
    invitation_code:=private.generate_collection_share_code_v1();
    INSERT INTO private.collection_sharing_invitations(root_id,role,code,secret_hash)
      VALUES(root.id,'viewer',invitation_code,sha256(convert_to(invitation_code,'UTF8')))
      ON CONFLICT(root_id,role) DO UPDATE SET code=excluded.code,secret_hash=excluded.secret_hash,
        generation=gen_random_uuid(),created_at=now();
  ELSIF p_action='rotate' THEN
    IF NOT root.is_open THEN RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501'; END IF;
    invitation_code:=private.generate_collection_share_code_v1();
    UPDATE private.collection_sharing_invitations i
      SET code=invitation_code,secret_hash=sha256(convert_to(invitation_code,'UTF8')),
        generation=gen_random_uuid(),created_at=now()
      WHERE i.root_id=root.id AND i.role='viewer';
    IF NOT FOUND THEN RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501'; END IF;
    UPDATE private.collection_sharing_roots SET revision=revision+1 WHERE id=root.id;
  ELSIF p_action='close' AND root.is_open THEN
    UPDATE private.collection_sharing_roots SET is_open=false,access_lifetime=gen_random_uuid(),revision=revision+1 WHERE id=root.id;
  END IF;
  RETURN private.finish_collection_share_command_v1(p_operation_id,request,
    jsonb_build_object('action',p_action,'rootId',root.id,'collectionId',p_collection_id));
END;
$$;


--
-- Name: next_ordinary_meaning_available_at_v1(timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.next_ordinary_meaning_available_at_v1(p_activated_at timestamp with time zone, p_timezone text) RETURNS timestamp with time zone
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT (
    (
      private.training_calendar_local_date_v1(
        p_activated_at,
        private.training_schedule_timezone_v1(p_timezone)
      ) + 1
    )::timestamp AT TIME ZONE private.training_schedule_timezone_v1(p_timezone)
  );
$$;


--
-- Name: normalize_list_card_policy(text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_list_card_policy(p_card_policy text, p_existing text DEFAULT 'inherit'::text) RETURNS text
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT CASE
        WHEN NULLIF(trim(COALESCE(p_card_policy, '')), '') IS NULL
            THEN COALESCE(p_existing, 'inherit')
        WHEN trim(p_card_policy) IN ('inherit', 'prefer', 'restrict')
            THEN trim(p_card_policy)
        ELSE 'invalid'
    END;
$$;


--
-- Name: normalize_source_context_v2_learning_source(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_source_context_v2_learning_source() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
BEGIN
    IF NEW.metadata->>'contractVersion' IS DISTINCT FROM 'source-context-v2' THEN
        RETURN NEW;
    END IF;

    IF NEW.kind = 'youtube_video' THEN
        IF NEW.provider IS DISTINCT FROM 'youtube'
           OR NEW.external_id IS NULL
           OR NEW.external_id !~ '^[A-Za-z0-9_-]{11}$' THEN
            RAISE EXCEPTION 'invalid_v2_canonical_source';
        END IF;

        NEW.canonical_url := 'https://www.youtube.com/watch?v=' || NEW.external_id;
        NEW.title := NULL;
        NEW.language_code := NULLIF(left(lower(replace(COALESCE(NEW.language_code, ''), '_', '-')), 16), '');
        NEW.metadata := jsonb_build_object('contractVersion', 'source-context-v2');
        NEW.source_identity_key := md5(concat_ws(
            '|',
            NEW.kind,
            NEW.provider,
            NEW.external_id,
            NEW.canonical_url
        ));

        RETURN NEW;
    END IF;

    IF NEW.kind = 'web_page' THEN
        IF NEW.provider IS DISTINCT FROM 'web'
           OR NEW.external_id IS NULL
           OR NEW.external_id !~ '^private:web_page:[a-f0-9]{64}$'
           OR NEW.canonical_url IS NULL
           OR NEW.canonical_url !~ '^https?://'
           OR NEW.canonical_url ~ '#'
           OR NEW.canonical_url ~ '://[^/]*@' THEN
            RAISE EXCEPTION 'invalid_v2_private_source';
        END IF;
    ELSIF NEW.kind = 'text_document' THEN
        IF NEW.provider IS DISTINCT FROM 'pontix'
           OR NEW.external_id IS NULL
           OR NEW.external_id !~ '^private:text_document:[a-f0-9]{64}$'
           OR NEW.canonical_url IS NOT NULL THEN
            RAISE EXCEPTION 'invalid_v2_private_source';
        END IF;
    ELSIF NEW.kind = 'ebook' THEN
        IF NEW.provider IS NULL
           OR NEW.external_id IS NULL
           OR NEW.external_id !~ '^private:ebook:[a-f0-9]{64}$'
           OR NEW.canonical_url IS NOT NULL THEN
            RAISE EXCEPTION 'invalid_v2_private_source';
        END IF;
    ELSE
        RAISE EXCEPTION 'invalid_v2_canonical_source';
    END IF;

    NEW.title := NULL;
    NEW.language_code := NULLIF(left(lower(replace(COALESCE(NEW.language_code, ''), '_', '-')), 16), '');
    NEW.metadata := jsonb_build_object(
        'contractVersion', 'source-context-v2',
        'privateSource', true
    );
    NEW.source_identity_key := md5(concat_ws(
        '|',
        NEW.kind,
        NEW.provider,
        NEW.external_id,
        COALESCE(NEW.canonical_url, '')
    ));

    RETURN NEW;
END;
$_$;


--
-- Name: normalize_training_part_of_speech_v1(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.normalize_training_part_of_speech_v1(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
  SELECT CASE lower(trim(regexp_replace(COALESCE(p_value, ''), '[().;:, ]+$', '', 'g')))
    WHEN 'zn' THEN 'zn' WHEN 'znw' THEN 'zn' WHEN 'zelfstandig naamwoord' THEN 'zn'
    WHEN 'ww' THEN 'ww' WHEN 'werkwoord' THEN 'ww'
    WHEN 'bn' THEN 'bn' WHEN 'bijvoeglijk naamwoord' THEN 'bn'
    WHEN 'bw' THEN 'bw' WHEN 'bijwoord' THEN 'bw'
    WHEN 'vz' THEN 'vz' WHEN 'voorzetsel' THEN 'vz'
    WHEN 'vnw' THEN 'vnw' WHEN 'voornaamwoord' THEN 'vnw'
    WHEN 'vw' THEN 'vw' WHEN 'voegwoord' THEN 'vw'
    WHEN 'tw' THEN 'tw' WHEN 'telwoord' THEN 'tw'
    WHEN 'lidw' THEN 'lidw' WHEN 'lidwoord' THEN 'lidw'
    WHEN 'tsw' THEN 'tsw' WHEN 'tussenwerpsel' THEN 'tsw'
    WHEN 'afk' THEN 'afk' WHEN 'afkorting' THEN 'afk'
    ELSE NULL
  END;
$_$;


--
-- Name: owned_entry_content_atom_v1(text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.owned_entry_content_atom_v1(p_path text, p_kind text, p_text text, p_parent text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT CASE WHEN NULLIF(trim(p_text),'') IS NULL THEN '[]'::jsonb ELSE
    jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
      'inputKey',p_path,'kind',p_kind,'sourcePath',p_path,'parentInputKey',p_parent,
      'sourceText',normalize(trim(p_text),NFC),
      'sourceTextFingerprint',encode(sha256(convert_to(p_kind||chr(31)||trim(p_text),'UTF8')),'hex')
    ))) END;
$$;


--
-- Name: perform_platform_v2_card_action_non_session_latch_v1(uuid, text, uuid, text, text, uuid, text, text, uuid, jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perform_platform_v2_card_action_non_session_latch_v1(p_user_id uuid, p_action_id text, p_entry_id uuid, p_card_type_id text, p_state_revision text, p_active_known_mark_id uuid, p_known_mark_revision text, p_review_result text, p_client_event_id uuid, p_source_context jsonb, p_auth_kind text, p_connected_client_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_jwt_role text := COALESCE(
        NULLIF(current_setting('request.jwt.claim.role', true), ''),
        (
            NULLIF(current_setting('request.jwt.claims', true), '')::jsonb
        )->>'role'
    );
BEGIN
    IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'missing_user_id';
    END IF;

    PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);

    RETURN public.perform_platform_v2_card_action(
        p_user_id,
        p_action_id,
        p_entry_id,
        p_card_type_id,
        p_state_revision,
        p_active_known_mark_id,
        p_known_mark_revision,
        p_review_result,
        p_client_event_id,
        p_source_context,
        p_auth_kind,
        p_connected_client_id
    );
END;
$$;


--
-- Name: perform_platform_v2_card_action_session_latch_v1(uuid, text, uuid, text, text, uuid, text, text, uuid, jsonb, text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perform_platform_v2_card_action_session_latch_v1(p_user_id uuid, p_action_id text, p_entry_id uuid, p_card_type_id text, p_state_revision text, p_active_known_mark_id uuid, p_known_mark_revision text, p_review_result text, p_client_event_id uuid, p_source_context jsonb, p_auth_kind text, p_connected_client_id text, p_training_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_jwt_role text := COALESCE(
    NULLIF(current_setting('request.jwt.claim.role', true), ''),
    (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role'
  );
  v_response jsonb;
  v_consumption jsonb;
  v_binding public.training_session_action_bindings%rowtype;
BEGIN
  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;
  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);

  v_response := private.perform_platform_v2_card_action_non_session_latch_v1(
    p_user_id, p_action_id, p_entry_id, p_card_type_id, p_state_revision,
    p_active_known_mark_id, p_known_mark_revision, p_review_result,
    p_client_event_id, p_source_context, p_auth_kind, p_connected_client_id
  );

  IF p_training_session_id IS NOT NULL
     AND p_action_id IN ('start-learning', 'mark-known', 'review-card')
     AND v_response->>'status' IN ('accepted', 'duplicate') THEN
    IF v_response->>'status' = 'accepted' THEN
      INSERT INTO public.training_session_action_bindings (
        user_id, client_event_id, session_id, entry_id, card_type_id
      ) VALUES (
        p_user_id, p_client_event_id, p_training_session_id,
        p_entry_id, p_card_type_id
      ) ON CONFLICT (user_id, client_event_id) DO NOTHING;
    END IF;

    SELECT * INTO v_binding
    FROM public.training_session_action_bindings AS binding
    WHERE binding.user_id = p_user_id
      AND binding.client_event_id = p_client_event_id
    FOR UPDATE;
    IF NOT FOUND
       OR v_binding.session_id IS DISTINCT FROM p_training_session_id
       OR v_binding.entry_id IS DISTINCT FROM p_entry_id
       OR v_binding.card_type_id IS DISTINCT FROM p_card_type_id THEN
      RAISE EXCEPTION 'training_session_action_binding_conflict';
    END IF;

    v_consumption := private.consume_training_session_member(
      p_user_id, p_training_session_id, p_entry_id, p_card_type_id
    );
    IF v_consumption->>'status' NOT IN (
      'consumed', 'consumed-complete', 'duplicate'
    ) THEN
      RAISE EXCEPTION 'training_session_member_not_available';
    END IF;
  END IF;

  IF v_response->>'status' = 'accepted'
     AND p_action_id IN ('start-learning', 'review-card', 'mark-known') THEN
    UPDATE public.user_card_action_events AS event
    SET presentation_mode = 'word-in-context',
        presentation_content_node_id = member.context_content_node_id,
        presentation_source_text_fingerprint = member.context_source_text_fingerprint,
        presentation_hint_opened = member.context_hint_opened
    FROM public.training_sessions AS session
    JOIN public.training_session_members AS member
      ON member.session_id = session.id
    WHERE session.id = p_training_session_id
      AND session.user_id = p_user_id
      AND session.training_filter->>'presentationMode' = 'word-in-context'
      AND member.entry_id = p_entry_id
      AND member.card_type_id = p_card_type_id
      AND member.context_content_node_id IS NOT NULL
      AND event.id = (v_response->>'eventId')::uuid
      AND event.user_id = p_user_id;
  END IF;

  RETURN v_response;
END;
$$;


--
-- Name: perform_platform_v2_card_action_without_verifiable_receipt(uuid, text, uuid, text, text, uuid, text, text, uuid, jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perform_platform_v2_card_action_without_verifiable_receipt(p_user_id uuid, p_action_id text, p_entry_id uuid, p_card_type_id text, p_state_revision text, p_active_known_mark_id uuid, p_known_mark_revision text, p_review_result text, p_client_event_id uuid, p_source_context jsonb, p_auth_kind text, p_connected_client_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
    v_status_revision text;
    v_scheduler_phase text;
    v_existing_receipt public.platform_v2_action_receipts%rowtype;
    v_existing_event public.user_card_action_events%rowtype;
    v_active_mark public.user_card_known_marks%rowtype;
    v_action_payload jsonb;
    v_action_payload_hash text;
    v_event_id uuid := gen_random_uuid();
    v_mark_id uuid := gen_random_uuid();
    v_mark_revision uuid := gen_random_uuid();
    v_response jsonb;
    v_source jsonb;
    v_artifact jsonb;
    v_location jsonb;
    v_context jsonb;
    v_source_id uuid;
    v_artifact_id uuid;
    v_location_id uuid;
    v_source_identity_key text;
    v_artifact_identity_key text;
    v_locator_key text;
    v_locator_kind text;
    v_context_text text;
    v_context_text_hash text;
    v_clicked_form text;
    v_start_ms integer;
    v_end_ms integer;
    v_phrase_index integer;
    v_jwt_role text := COALESCE(
        NULLIF(current_setting('request.jwt.claim.role', true), ''),
        (
            NULLIF(
                current_setting('request.jwt.claims', true),
                ''
            )::jsonb
        )->>'role'
    );
BEGIN
    IF NOT (
        (
            (select auth.uid()) IS NOT NULL
            AND p_user_id IS NOT DISTINCT FROM (select auth.uid())
        )
        OR v_jwt_role = 'service_role'
    ) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;
    IF p_action_id NOT IN (
        'start-learning',
        'mark-known',
        'undo-known',
        'review-card'
    ) THEN
        RAISE EXCEPTION 'unsupported_action';
    END IF;
    IF p_action_id = 'review-card'
       AND (
           p_review_result IS NULL
           OR p_review_result NOT IN ('fail', 'hard', 'success', 'easy')
       ) THEN
        RAISE EXCEPTION 'missing_or_invalid_result';
    END IF;
    IF p_action_id <> 'review-card' AND p_review_result IS NOT NULL THEN
        RAISE EXCEPTION 'unexpected_review_result';
    END IF;
    IF p_client_event_id IS NULL THEN
        RAISE EXCEPTION 'missing_client_event_id';
    END IF;
    IF COALESCE(NULLIF(trim(p_auth_kind), ''), 'first_party')
       NOT IN ('first_party', 'connected_client') THEN
        RAISE EXCEPTION 'invalid_platform_auth_kind';
    END IF;
    IF p_auth_kind = 'connected_client'
       AND NULLIF(trim(p_connected_client_id), '') IS NULL THEN
        RAISE EXCEPTION 'missing_connected_client_id';
    END IF;
    IF p_auth_kind = 'connected_client'
       AND NOT EXISTS (
           SELECT 1
             FROM public.connected_clients c
             JOIN public.connected_client_grants g
               ON g.client_id = c.client_id
            WHERE c.client_id = trim(p_connected_client_id)
              AND c.status = 'active'
              AND g.user_id = p_user_id
              AND g.revoked_at IS NULL
              AND 'platform:write' = ANY(g.scopes)
       ) THEN
        RAISE EXCEPTION 'invalid_connected_client_grant';
    END IF;
    IF p_auth_kind = 'connected_client'
       AND NULLIF(p_source_context#>>'{client,id}', '') IS NOT NULL
       AND p_source_context#>>'{client,id}'
           IS DISTINCT FROM p_connected_client_id THEN
        RAISE EXCEPTION 'client_identity_mismatch';
    END IF;
    IF p_source_context IS NOT NULL
       AND p_source_context->>'contractVersion'
           IS DISTINCT FROM 'source-context-v2' THEN
        RAISE EXCEPTION 'invalid_source_context_version';
    END IF;

    v_action_payload := jsonb_strip_nulls(jsonb_build_object(
        'contractVersion', 'platform-action-v2',
        'userId', p_user_id,
        'actionId', p_action_id,
        'entryId', p_entry_id,
        'cardTypeId', p_card_type_id,
        'stateRevision', p_state_revision,
        'activeKnownMarkId', p_active_known_mark_id,
        'knownMarkRevision', p_known_mark_revision,
        'reviewResult', p_review_result,
        'authKind', COALESCE(NULLIF(trim(p_auth_kind), ''), 'first_party'),
        'connectedClientId', CASE
            WHEN p_auth_kind = 'connected_client'
                THEN NULLIF(trim(p_connected_client_id), '')
            ELSE NULL
        END,
        'source', p_source_context->'source',
        'artifact', p_source_context->'artifact',
        'location', p_source_context->'location',
        'selection', p_source_context->'selection',
        'context', p_source_context->'context'
    ));
    v_action_payload_hash := encode(
        digest(v_action_payload::text, 'sha256'),
        'hex'
    );

    PERFORM pg_advisory_xact_lock(
        hashtext(p_user_id::text || ':' || p_client_event_id::text)
    );

    SELECT *
      INTO v_existing_receipt
      FROM public.platform_v2_action_receipts
     WHERE user_id = p_user_id
       AND client_event_id = p_client_event_id;
    IF FOUND THEN
        IF v_existing_receipt.action_payload_hash <> v_action_payload_hash THEN
            RAISE EXCEPTION 'platform_action_idempotency_conflict';
        END IF;
        RETURN v_existing_receipt.response || jsonb_build_object(
            'status', 'duplicate'
        );
    END IF;

    PERFORM id FROM public.word_entries WHERE id=p_entry_id FOR SHARE;
    SELECT dictionary_id
      INTO v_dictionary_id
      FROM private.current_training_review_entries_v1(p_user_id,p_card_type_id)
     WHERE id = p_entry_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'entry_not_found';
    END IF;
    PERFORM private.lock_shared_learning_source_v1(p_user_id,p_entry_id);
    IF NOT (private.entry_access_v1(p_user_id,p_entry_id,'train') OR (
    COALESCE(NULLIF(trim(p_auth_kind),''),'first_party')='first_party'
    AND private.current_training_entry_permitted_v1(p_user_id,p_entry_id,p_card_type_id))) THEN
        RAISE EXCEPTION 'entry_not_accessible';
    END IF;

    SELECT *
      INTO v_existing_event
      FROM public.user_card_action_events
     WHERE user_id = p_user_id
       AND client_event_id = p_client_event_id::text;
    IF FOUND THEN
        RAISE EXCEPTION 'platform_action_idempotency_conflict';
    END IF;

    IF p_action_id IN ('start-learning', 'review-card') THEN
        PERFORM private.require_training_pair_available_v1(
            p_user_id, 'meaning', p_entry_id, NULL, NULL, p_card_type_id);
    END IF;

    IF p_card_type_id IN ('word-to-definition','definition-to-word') THEN
      PERFORM pg_advisory_xact_lock(hashtext('training-headword:'||p_user_id::text||':'||private.training_headword_group_v1(p_entry_id)::text));
      PERFORM pg_advisory_xact_lock(hashtext('shared-meaning-known:'||p_user_id::text||':'||p_entry_id::text));
    END IF;
    PERFORM pg_advisory_xact_lock(
        hashtext(
            p_user_id::text
            || ':'
            || p_entry_id::text
            || ':'
            || p_card_type_id
        )
    );

    SELECT
        state_revision::text,
        CASE
            WHEN COALESCE(hidden, false) THEN 'hidden'
            WHEN frozen_until IS NOT NULL AND frozen_until > private.training_reference_now_v1()
                THEN 'frozen'
            WHEN COALESCE(in_learning, false) THEN 'learning'
            WHEN COALESCE(fsrs_reps, 0) > 0
              OR last_reviewed_at IS NOT NULL THEN 'reviewing'
            WHEN COALESCE(seen_count, 0) > 0
              OR COALESCE(click_count, 0) > 0 THEN 'encountered'
            ELSE 'not-started'
        END
      INTO v_status_revision, v_scheduler_phase
      FROM public.user_card_status
     WHERE user_id = p_user_id
       AND entry_id = p_entry_id
       AND card_type_id = p_card_type_id
     FOR UPDATE;

    IF NOT FOUND THEN
        IF p_state_revision <> 'untracked' THEN
            RAISE EXCEPTION 'platform_card_state_conflict';
        END IF;
        INSERT INTO public.user_card_status (
            user_id,
            entry_id,
            card_type_id,
            next_review_at,
            last_seen_at,
            click_count,
            seen_count,
            success_count,
            hidden,
            in_learning,
            fsrs_reps,
            fsrs_lapses,
            fsrs_enabled
        )
        VALUES (
            p_user_id,
            p_entry_id,
            p_card_type_id,
            NULL,
            NULL,
            0,
            0,
            0,
            false,
            false,
            0,
            0,
            false
        )
        RETURNING state_revision::text, 'not-started'
        INTO v_status_revision, v_scheduler_phase;
    ELSIF v_status_revision IS DISTINCT FROM p_state_revision THEN
        RAISE EXCEPTION 'platform_card_state_conflict';
    END IF;

    SELECT *
      INTO v_active_mark
      FROM public.user_card_known_marks
     WHERE user_id = p_user_id
       AND entry_id = p_entry_id
       AND card_type_id = p_card_type_id
       AND cleared_at IS NULL
     FOR UPDATE;

    IF p_action_id = 'mark-known' AND FOUND THEN
        RAISE EXCEPTION 'platform_card_already_known';
    END IF;
    IF p_action_id IN ('start-learning', 'review-card') AND FOUND THEN
        RAISE EXCEPTION 'card_is_known';
    END IF;
    IF p_action_id = 'undo-known' THEN
        IF NOT FOUND
           OR v_active_mark.id IS DISTINCT FROM p_active_known_mark_id
           OR v_active_mark.revision::text
              IS DISTINCT FROM p_known_mark_revision THEN
            RAISE EXCEPTION 'platform_known_mark_conflict';
        END IF;
    END IF;

    IF (
        p_action_id = 'start-learning'
        AND v_scheduler_phase NOT IN ('not-started', 'encountered')
    ) OR (
        p_action_id = 'review-card'
        AND v_scheduler_phase NOT IN ('learning', 'reviewing')
    ) OR (
        p_action_id = 'mark-known'
        AND v_scheduler_phase NOT IN (
            'not-started',
            'encountered',
            'learning',
            'reviewing'
        )
    ) THEN
        RAISE EXCEPTION 'platform_action_not_available';
    END IF;

    v_source := CASE
        WHEN jsonb_typeof(p_source_context->'source') = 'object'
            THEN p_source_context->'source'
        ELSE NULL
    END;
    v_artifact := CASE
        WHEN jsonb_typeof(p_source_context->'artifact') = 'object'
            THEN p_source_context->'artifact'
        ELSE NULL
    END;
    v_location := CASE
        WHEN jsonb_typeof(p_source_context->'location') = 'object'
            THEN p_source_context->'location'
        ELSE NULL
    END;
    v_context := CASE
        WHEN jsonb_typeof(p_source_context->'context') = 'object'
            THEN p_source_context->'context'
        ELSE NULL
    END;
    v_clicked_form := NULLIF(
        left(
            trim(
                COALESCE(
                    v_context->>'clickedForm',
                    p_source_context#>>'{selection,clickedForm}',
                    ''
                )
            ),
            160
        ),
        ''
    );
    v_context_text := NULLIF(
        left(COALESCE(v_context->>'text', ''), 1000),
        ''
    );
    v_context_text_hash := CASE
        WHEN v_context_text IS NULL THEN NULL
        ELSE md5(v_context_text)
    END;

    IF v_source IS NOT NULL THEN
        v_source_identity_key := md5(concat_ws(
            '|',
            COALESCE(NULLIF(trim(v_source->>'kind'), ''), 'unknown'),
            COALESCE(NULLIF(trim(v_source->>'provider'), ''), ''),
            COALESCE(
                NULLIF(
                    trim(
                        COALESCE(
                            v_source->>'externalId',
                            v_source->>'external_id'
                        )
                    ),
                    ''
                ),
                ''
            ),
            COALESCE(
                NULLIF(
                    trim(
                        COALESCE(
                            v_source->>'url',
                            v_source->>'canonicalUrl',
                            v_source->>'canonical_url'
                        )
                    ),
                    ''
                ),
                ''
            )
        ));

        INSERT INTO public.learning_sources (
            source_identity_key,
            kind,
            provider,
            external_id,
            canonical_url,
            title,
            language_code,
            metadata,
            first_seen_at,
            last_seen_at
        )
        VALUES (
            v_source_identity_key,
            COALESCE(NULLIF(left(trim(v_source->>'kind'), 80), ''), 'unknown'),
            NULLIF(left(trim(v_source->>'provider'), 80), ''),
            NULLIF(
                left(
                    trim(
                        COALESCE(
                            v_source->>'externalId',
                            v_source->>'external_id'
                        )
                    ),
                    240
                ),
                ''
            ),
            NULLIF(
                left(
                    trim(
                        COALESCE(
                            v_source->>'url',
                            v_source->>'canonicalUrl',
                            v_source->>'canonical_url'
                        )
                    ),
                    2048
                ),
                ''
            ),
            NULLIF(left(trim(v_source->>'title'), 500), ''),
            NULLIF(
                left(
                    trim(
                        COALESCE(
                            v_source->>'languageCode',
                            v_source->>'language_code'
                        )
                    ),
                    16
                ),
                ''
            ),
            jsonb_build_object(
                'contractVersion',
                'source-context-v2'
            ),
            private.training_reference_now_v1(),
            private.training_reference_now_v1()
        )
        ON CONFLICT (source_identity_key) DO UPDATE
        SET last_seen_at = private.training_reference_now_v1()
        RETURNING id INTO v_source_id;
    END IF;

    IF v_artifact IS NOT NULL THEN
        IF v_source_id IS NULL THEN
            RAISE EXCEPTION 'artifact_requires_source';
        END IF;
        v_artifact_identity_key := encode(
            digest(
                jsonb_build_object(
                    'sourceId',
                    v_source_id,
                    'artifact',
                    v_artifact
                )::text,
                'sha256'
            ),
            'hex'
        );

        INSERT INTO public.learning_source_artifacts (
            source_id,
            artifact_identity_key,
            artifact_kind,
            producer,
            snapshot_revision_id,
            text_source_id,
            text_source_revision_id,
            text_content_fingerprint,
            timing_evidence_revision_id,
            phrase_set_revision_id,
            builder_version,
            language_code,
            quality,
            metadata,
            first_seen_at,
            last_seen_at
        )
        VALUES (
            v_source_id,
            v_artifact_identity_key,
            left(v_artifact->>'artifactKind', 80),
            left(v_artifact->>'producer', 80),
            NULLIF(left(COALESCE(v_artifact->>'snapshotRevisionId', ''), 160), ''),
            NULLIF(left(COALESCE(v_artifact->>'textSourceId', ''), 160), ''),
            NULLIF(left(COALESCE(v_artifact->>'textSourceRevisionId', ''), 160), ''),
            NULLIF(left(COALESCE(v_artifact->>'textContentFingerprint', ''), 160), ''),
            NULLIF(left(COALESCE(v_artifact->>'timingEvidenceRevisionId', ''), 160), ''),
            NULLIF(left(COALESCE(v_artifact->>'phraseSetRevisionId', ''), 160), ''),
            NULLIF(left(COALESCE(v_artifact->>'builderVersion', ''), 80), ''),
            NULLIF(left(COALESCE(v_artifact->>'languageCode', ''), 16), ''),
            NULLIF(left(COALESCE(v_artifact->>'quality', ''), 80), ''),
            '{}'::jsonb,
            private.training_reference_now_v1(),
            private.training_reference_now_v1()
        )
        ON CONFLICT (source_id, artifact_identity_key) DO UPDATE
        SET last_seen_at = private.training_reference_now_v1(),
            quality = COALESCE(
                excluded.quality,
                learning_source_artifacts.quality
            )
        RETURNING id INTO v_artifact_id;
    END IF;

    IF v_location IS NOT NULL OR v_context_text_hash IS NOT NULL THEN
        IF v_source_id IS NULL THEN
            RAISE EXCEPTION 'location_requires_source';
        END IF;
        v_locator_kind := COALESCE(
            NULLIF(left(trim(v_location->>'kind'), 80), ''),
            'context'
        );
        v_start_ms := private.safe_jsonb_int(
            COALESCE(v_location->>'startMs', v_location->>'start_ms')
        );
        v_end_ms := private.safe_jsonb_int(
            COALESCE(v_location->>'endMs', v_location->>'end_ms')
        );
        v_phrase_index := private.safe_jsonb_int(
            COALESCE(
                v_location->>'phraseIndex',
                v_location->>'phrase_index'
            )
        );
        v_locator_key := md5(jsonb_strip_nulls(jsonb_build_object(
            'kind', v_locator_kind,
            'artifactId', v_artifact_id,
            'startMs', v_start_ms,
            'endMs', v_end_ms,
            'phraseIndex', v_phrase_index,
            'contextTextHash', v_context_text_hash
        ))::text);

        INSERT INTO public.learning_source_locations (
            source_id,
            artifact_id,
            locator_key,
            locator_kind,
            start_ms,
            end_ms,
            phrase_index,
            text_hash,
            context_text,
            metadata,
            first_seen_at,
            last_seen_at
        )
        VALUES (
            v_source_id,
            v_artifact_id,
            v_locator_key,
            v_locator_kind,
            v_start_ms,
            v_end_ms,
            v_phrase_index,
            v_context_text_hash,
            v_context_text,
            jsonb_strip_nulls(jsonb_build_object(
                'diagnostics',
                p_source_context->'diagnostics'
            )),
            private.training_reference_now_v1(),
            private.training_reference_now_v1()
        )
        ON CONFLICT (source_id, locator_key) DO UPDATE
        SET artifact_id = COALESCE(
                learning_source_locations.artifact_id,
                excluded.artifact_id
            ),
            last_seen_at = private.training_reference_now_v1(),
            context_text = COALESCE(
                learning_source_locations.context_text,
                excluded.context_text
            ),
            metadata = learning_source_locations.metadata
                || excluded.metadata
        RETURNING id INTO v_location_id;
    END IF;

    INSERT INTO public.user_card_action_events (
        id,
        user_id,
        entry_id,
        card_type_id,
        action,
        result,
        client_event_id,
        turn_id,
        action_payload_hash,
        source_context,
        source_id,
        artifact_id,
        location_id,
        clicked_form,
        context_text_hash,
        auth_kind,
        connected_client_id,
        created_at
    )
    VALUES (
        v_event_id,
        p_user_id,
        p_entry_id,
        p_card_type_id,
        p_action_id,
        p_review_result,
        p_client_event_id::text,
        CASE
            WHEN p_action_id = 'review-card' THEN p_client_event_id
            ELSE NULL
        END,
        v_action_payload_hash,
        p_source_context,
        v_source_id,
        v_artifact_id,
        v_location_id,
        v_clicked_form,
        v_context_text_hash,
        COALESCE(NULLIF(trim(p_auth_kind), ''), 'first_party'),
        CASE
            WHEN p_auth_kind = 'connected_client'
                THEN NULLIF(trim(p_connected_client_id), '')
            ELSE NULL
        END,
        private.training_reference_now_v1()
    );

    IF p_action_id = 'mark-known' THEN
        INSERT INTO public.user_card_known_marks (
            id,
            user_id,
            entry_id,
            card_type_id,
            revision,
            mark_event_id
        )
        VALUES (
            v_mark_id,
            p_user_id,
            p_entry_id,
            p_card_type_id,
            v_mark_revision,
            v_event_id
        );
    ELSIF p_action_id = 'undo-known' THEN
        UPDATE public.user_card_known_marks
           SET cleared_at = private.training_reference_now_v1(),
               undo_event_id = v_event_id
         WHERE id = v_active_mark.id
           AND cleared_at IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'platform_known_mark_conflict';
        END IF;
    ELSIF p_action_id = 'start-learning' THEN
        PERFORM private.current_training_start_learning_entry_card_v1(
            p_user_id,
            p_entry_id,
            p_card_type_id
        );
    ELSE
        PERFORM private.current_training_handle_card_review_v1(
            p_user_id,
            p_entry_id,
            p_card_type_id,
            p_review_result,
            p_client_event_id
        );
    END IF;

    IF p_action_id IN ('mark-known', 'undo-known') THEN
        UPDATE public.user_card_status
           SET state_revision = gen_random_uuid()
         WHERE user_id = p_user_id
           AND entry_id = p_entry_id
           AND card_type_id = p_card_type_id;
    END IF;

    v_response := jsonb_build_object(
        'status', 'accepted',
        'actionId', p_action_id,
        'clientEventId', p_client_event_id,
        'eventId', v_event_id,
        'sourceId', v_source_id,
        'artifactId', v_artifact_id,
        'locationId', v_location_id,
        'card', private.platform_v2_card_state_json(
            p_user_id,
            p_entry_id,
            p_card_type_id
        )
    );

    INSERT INTO public.platform_v2_action_receipts (
        user_id,
        client_event_id,
        action_payload_hash,
        event_id,
        response
    )
    VALUES (
        p_user_id,
        p_client_event_id,
        v_action_payload_hash,
        v_event_id,
        v_response
    );

    RETURN v_response;
END;
$$;


--
-- Name: perform_platform_v2_idiom_exercise_action_v1(uuid, uuid, text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perform_platform_v2_idiom_exercise_action_v1(p_user_id uuid, p_target_id uuid, p_state_revision text, p_review_result text, p_client_event_id uuid, p_training_session_id uuid DEFAULT NULL::uuid, p_source_context jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_target private.platform_v2_training_exercise_targets%rowtype;
    v_node private.platform_v2_content_nodes%rowtype;
    v_state public.user_training_exercise_state%rowtype;
    v_receipt public.platform_v2_training_exercise_action_receipts%rowtype;
    v_existing_event public.user_training_exercise_action_events%rowtype;
    v_source_context jsonb;
    v_action_payload jsonb;
    v_existing_payload jsonb;
    v_action_payload_hash text;
    v_event_id uuid := gen_random_uuid();
    v_grade smallint;
    v_params numeric[];
    v_target_retention numeric;
    v_compute jsonb;
    v_interval numeric;
    v_now timestamptz := private.training_reference_now_v1();
    v_response jsonb;
BEGIN
    IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;
    IF p_target_id IS NULL THEN RAISE EXCEPTION 'missing_target_id'; END IF;
    IF p_state_revision IS NULL THEN RAISE EXCEPTION 'missing_state_revision'; END IF;
    IF p_review_result NOT IN ('fail', 'hard', 'success', 'easy') THEN
        RAISE EXCEPTION 'invalid_review_result';
    END IF;
    IF p_client_event_id IS NULL THEN RAISE EXCEPTION 'missing_client_event_id'; END IF;

    v_source_context := NULLIF(
        jsonb_strip_nulls(jsonb_build_object(
            'contractVersion', p_source_context->>'contractVersion',
            'source', p_source_context->'source',
            'artifact', p_source_context->'artifact',
            'location', p_source_context->'location',
            'selection', p_source_context->'selection',
            'context', p_source_context->'context'
        )),
        '{}'::jsonb
    );
    v_action_payload := private.platform_v2_training_exercise_action_payload_v1(
        p_user_id,
        p_target_id,
        p_review_result,
        p_client_event_id,
        p_training_session_id,
        v_source_context
    );
    v_action_payload_hash := encode(digest(v_action_payload::text, 'sha256'), 'hex');

    PERFORM pg_advisory_xact_lock(
        hashtext(p_user_id::text || ':exercise:' || p_client_event_id::text)
    );

    SELECT *
      INTO v_receipt
      FROM public.platform_v2_training_exercise_action_receipts AS receipt
     WHERE receipt.user_id = p_user_id
       AND receipt.client_event_id = p_client_event_id
     FOR UPDATE;
    IF FOUND THEN
        SELECT *
          INTO v_existing_event
          FROM public.user_training_exercise_action_events AS event
         WHERE event.id = v_receipt.event_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'training_exercise_action_receipt_event_missing';
        END IF;
        v_existing_payload := private.platform_v2_training_exercise_action_payload_v1(
            v_existing_event.user_id,
            v_existing_event.target_id,
            v_existing_event.result,
            v_existing_event.client_event_id,
            v_existing_event.session_id,
            v_existing_event.source_context
        );
        IF v_existing_payload IS DISTINCT FROM v_action_payload THEN
            RAISE EXCEPTION 'training_exercise_action_idempotency_conflict';
        END IF;
        RETURN v_receipt.response || jsonb_build_object('status', 'duplicate');
    END IF;

    SELECT *
      INTO v_existing_event
      FROM public.user_training_exercise_action_events AS event
     WHERE event.user_id = p_user_id
       AND event.client_event_id = p_client_event_id;
    IF FOUND THEN
        RAISE EXCEPTION 'training_exercise_action_idempotency_conflict';
    END IF;

    IF p_training_session_id IS NOT NULL THEN
        PERFORM private.require_active_training_session_v1(
            p_user_id,
            p_training_session_id
        );
    END IF;

    SELECT *
      INTO v_target
      FROM private.platform_v2_training_exercise_targets
     WHERE id = p_target_id
       AND family = 'idiom';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'training_exercise_target_not_found';
    END IF;

    SELECT *
      INTO v_node
      FROM private.platform_v2_content_nodes
     WHERE id = v_target.content_node_id
       AND entry_id = v_target.entry_id
       AND kind = 'idiom'
       AND binding_state = 'active'
       AND source_text_fingerprint = v_target.source_text_fingerprint;
    IF NOT FOUND OR v_target.visibility_state <> 'active' THEN
        RAISE EXCEPTION 'training_exercise_target_unavailable';
    END IF;
    PERFORM id FROM public.word_entries WHERE id=v_target.entry_id FOR SHARE;
    PERFORM private.lock_shared_learning_source_v1(p_user_id,v_target.entry_id);
SELECT *
      INTO v_target
      FROM private.platform_v2_training_exercise_targets
     WHERE id = p_target_id
       AND family = 'idiom';
    IF NOT FOUND THEN
        RAISE EXCEPTION 'training_exercise_target_not_found';
    END IF;

    SELECT *
      INTO v_node
      FROM private.platform_v2_content_nodes
     WHERE id = v_target.content_node_id
       AND entry_id = v_target.entry_id
       AND kind = 'idiom'
       AND binding_state = 'active'
       AND source_text_fingerprint = v_target.source_text_fingerprint;
    IF NOT FOUND OR v_target.visibility_state <> 'active' THEN
        RAISE EXCEPTION 'training_exercise_target_unavailable';
    END IF;
    
    IF NOT (private.platform_v2_training_ordinary_meaning_eligible_v1(p_user_id,v_target.entry_id) OR private.current_training_target_permitted_v1(p_user_id,p_target_id,p_training_session_id)) THEN
        RAISE EXCEPTION 'training_exercise_source_not_eligible';
    END IF;

    PERFORM private.require_training_pair_available_v1(
        p_user_id, 'idiom', v_target.entry_id, v_target.content_node_id,
        v_target.source_text_fingerprint, NULL);

    PERFORM pg_advisory_xact_lock(
        hashtext(p_user_id::text || ':exercise-target:' || p_target_id::text)
    );

    SELECT *
      INTO v_state
      FROM public.user_training_exercise_state AS state
     WHERE state.user_id = p_user_id
       AND state.target_id = p_target_id
     FOR UPDATE;

    SELECT COALESCE(settings.target_retention, 0.9)
      INTO v_target_retention
      FROM public.user_settings AS settings
     WHERE settings.user_id = p_user_id;
    v_target_retention := COALESCE(v_target_retention, 0.9);

    IF v_state.target_id IS NULL THEN
        IF p_state_revision <> 'untracked' THEN
            RAISE EXCEPTION 'training_exercise_state_conflict';
        END IF;
        INSERT INTO public.user_training_exercise_state (
            user_id,
            target_id,
            fsrs_target_retention,
            next_review_at
        ) VALUES (
            p_user_id,
            p_target_id,
            v_target_retention,
            v_now
        ) RETURNING * INTO v_state;
    ELSIF v_state.state_revision::text IS DISTINCT FROM p_state_revision THEN
        RAISE EXCEPTION 'training_exercise_state_conflict';
    END IF;

    v_grade := CASE p_review_result
        WHEN 'fail' THEN 1
        WHEN 'hard' THEN 2
        WHEN 'success' THEN 3
        WHEN 'easy' THEN 4
    END;
    v_params := fsrs6_parameters();
    v_compute := fsrs6_compute(
        v_state.fsrs_stability,
        v_state.fsrs_difficulty,
        v_state.last_reviewed_at,
        v_grade,
        COALESCE(v_state.fsrs_target_retention, v_target_retention),
        v_state.fsrs_reps,
        v_state.fsrs_lapses,
        v_params
    );
    v_interval := (v_compute->>'interval')::numeric;

    UPDATE public.user_training_exercise_state
       SET fsrs_stability = (v_compute->>'stability')::numeric,
           fsrs_difficulty = (v_compute->>'difficulty')::numeric,
           fsrs_reps = (v_compute->>'reps')::integer,
           fsrs_lapses = (v_compute->>'lapses')::integer,
           fsrs_last_grade = v_grade,
           fsrs_last_interval = v_interval,
           fsrs_target_retention = COALESCE(v_state.fsrs_target_retention, v_target_retention),
           fsrs_params_version = 'fsrs-6-default',
           fsrs_enabled = true,
           next_review_at = v_now + (v_interval || ' days')::interval,
           last_seen_at = v_now,
           last_reviewed_at = v_now,
           seen_count = COALESCE(v_state.seen_count, 0) + 1,
           success_count = COALESCE(v_state.success_count, 0)
               + CASE WHEN v_grade >= 3 THEN 1 ELSE 0 END,
           last_result = p_review_result,
           in_learning = false,
           learning_due_at = NULL
     WHERE user_id = p_user_id
       AND target_id = p_target_id;

    INSERT INTO public.user_training_exercise_action_events (
        id,
        user_id,
        target_id,
        session_id,
        action,
        result,
        client_event_id,
        action_payload_hash,
        source_context,
        created_at
    ) VALUES (
        v_event_id,
        p_user_id,
        p_target_id,
        p_training_session_id,
        'review-exercise',
        p_review_result,
        p_client_event_id,
        v_action_payload_hash,
        v_source_context,
        v_now
    );

    v_response := jsonb_build_object(
        'status', 'accepted',
        'actionId', 'review-exercise',
        'clientEventId', p_client_event_id,
        'eventId', v_event_id,
        'targetId', p_target_id,
        'targetKey', v_target.target_key,
        'family', 'idiom',
        'direction', v_target.direction,
        'state', private.platform_v2_training_exercise_state_json_v1(
            p_user_id,
            p_target_id
        )
    );

    INSERT INTO public.platform_v2_training_exercise_action_receipts (
        user_id,
        client_event_id,
        target_id,
        action_payload_hash,
        event_id,
        response,
        created_at
    ) VALUES (
        p_user_id,
        p_client_event_id,
        p_target_id,
        v_action_payload_hash,
        v_event_id,
        v_response,
        v_now
    );

    IF p_training_session_id IS NOT NULL THEN
        PERFORM private.consume_platform_v2_training_exercise_session_member_v1(
            p_user_id,
            p_training_session_id,
            p_target_id
        );
    END IF;

    RETURN v_response;
END;
$$;


--
-- Name: perform_platform_v2_translation_exercise_action_v1(uuid, uuid, text, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.perform_platform_v2_translation_exercise_action_v1(p_user_id uuid, p_target_id uuid, p_state_revision text, p_review_result text, p_client_event_id uuid, p_training_session_id uuid DEFAULT NULL::uuid, p_source_context jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_target private.platform_v2_training_exercise_targets%rowtype;
    v_node private.platform_v2_content_nodes%rowtype;
    v_state public.user_training_exercise_state%rowtype;
    v_receipt public.platform_v2_training_exercise_action_receipts%rowtype;
    v_existing_event public.user_training_exercise_action_events%rowtype;
    v_source_context jsonb;
    v_action_payload jsonb;
    v_existing_payload jsonb;
    v_action_payload_hash text;
    v_event_id uuid := gen_random_uuid();
    v_grade smallint;
    v_params numeric[];
    v_target_retention numeric;
    v_compute jsonb;
    v_interval numeric;
    v_now timestamptz := private.training_reference_now_v1();
    v_response jsonb;
BEGIN
    IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;
    IF p_target_id IS NULL THEN RAISE EXCEPTION 'missing_target_id'; END IF;
    IF p_state_revision IS NULL THEN RAISE EXCEPTION 'missing_state_revision'; END IF;
    IF p_review_result NOT IN ('fail', 'hard', 'success', 'easy') THEN
        RAISE EXCEPTION 'invalid_review_result';
    END IF;
    IF p_client_event_id IS NULL THEN RAISE EXCEPTION 'missing_client_event_id'; END IF;

    v_source_context := NULLIF(jsonb_strip_nulls(jsonb_build_object(
        'contractVersion', p_source_context->>'contractVersion',
        'source', p_source_context->'source',
        'artifact', p_source_context->'artifact',
        'location', p_source_context->'location',
        'selection', p_source_context->'selection',
        'context', p_source_context->'context'
    )), '{}'::jsonb);
    v_action_payload := private.platform_v2_training_exercise_action_payload_v1(
        p_user_id, p_target_id, p_review_result, p_client_event_id,
        p_training_session_id, v_source_context
    );
    v_action_payload_hash := encode(digest(v_action_payload::text, 'sha256'), 'hex');

    PERFORM pg_advisory_xact_lock(hashtext(p_user_id::text || ':exercise:' || p_client_event_id::text));
    SELECT * INTO v_receipt
      FROM public.platform_v2_training_exercise_action_receipts AS receipt
     WHERE receipt.user_id = p_user_id AND receipt.client_event_id = p_client_event_id
     FOR UPDATE;
    IF FOUND THEN
        SELECT * INTO v_existing_event
          FROM public.user_training_exercise_action_events AS event
         WHERE event.id = v_receipt.event_id;
        IF NOT FOUND THEN RAISE EXCEPTION 'training_exercise_action_receipt_event_missing'; END IF;
        v_existing_payload := private.platform_v2_training_exercise_action_payload_v1(
            v_existing_event.user_id, v_existing_event.target_id, v_existing_event.result,
            v_existing_event.client_event_id, v_existing_event.session_id,
            v_existing_event.source_context
        );
        IF v_existing_payload IS DISTINCT FROM v_action_payload THEN
            RAISE EXCEPTION 'training_exercise_action_idempotency_conflict';
        END IF;
        RETURN v_receipt.response || jsonb_build_object('status', 'duplicate');
    END IF;

    SELECT * INTO v_existing_event
      FROM public.user_training_exercise_action_events AS event
     WHERE event.user_id = p_user_id AND event.client_event_id = p_client_event_id;
    IF FOUND THEN RAISE EXCEPTION 'training_exercise_action_idempotency_conflict'; END IF;
    IF p_training_session_id IS NOT NULL THEN
        PERFORM private.require_active_training_session_v1(p_user_id, p_training_session_id);
    END IF;

    SELECT * INTO v_target
      FROM private.platform_v2_training_exercise_targets
     WHERE id = p_target_id AND family = 'translation' AND direction = 'recall';
    IF NOT FOUND THEN RAISE EXCEPTION 'training_exercise_target_not_found'; END IF;
    SELECT * INTO v_node
      FROM private.platform_v2_content_nodes
     WHERE id = v_target.content_node_id
       AND entry_id = v_target.entry_id
       AND kind = 'example'
       AND binding_state = 'active'
       AND source_text_fingerprint = v_target.source_text_fingerprint;
    IF NOT FOUND OR v_target.visibility_state <> 'active' THEN
        RAISE EXCEPTION 'training_exercise_target_unavailable';
    END IF;
    PERFORM id FROM public.word_entries WHERE id=v_target.entry_id FOR SHARE;
    PERFORM private.lock_shared_learning_source_v1(p_user_id,v_target.entry_id);
SELECT * INTO v_target
      FROM private.platform_v2_training_exercise_targets
     WHERE id = p_target_id AND family = 'translation' AND direction = 'recall';
    IF NOT FOUND THEN RAISE EXCEPTION 'training_exercise_target_not_found'; END IF;
    SELECT * INTO v_node
      FROM private.platform_v2_content_nodes
     WHERE id = v_target.content_node_id
       AND entry_id = v_target.entry_id
       AND kind = 'example'
       AND binding_state = 'active'
       AND source_text_fingerprint = v_target.source_text_fingerprint;
    IF NOT FOUND OR v_target.visibility_state <> 'active' THEN
        RAISE EXCEPTION 'training_exercise_target_unavailable';
    END IF;
    
    IF NOT (private.platform_v2_training_ordinary_meaning_eligible_v1(p_user_id,v_target.entry_id) OR private.current_training_target_permitted_v1(p_user_id,p_target_id,p_training_session_id)) THEN
        RAISE EXCEPTION 'training_exercise_source_not_eligible';
    END IF;

    PERFORM private.require_training_pair_available_v1(
        p_user_id, 'translation', v_target.entry_id, v_target.content_node_id,
        v_target.source_text_fingerprint, NULL);

    PERFORM pg_advisory_xact_lock(hashtext(p_user_id::text || ':exercise-target:' || p_target_id::text));
    SELECT * INTO v_state
      FROM public.user_training_exercise_state AS state
     WHERE state.user_id = p_user_id AND state.target_id = p_target_id
     FOR UPDATE;
    SELECT COALESCE(settings.target_retention, 0.9) INTO v_target_retention
      FROM public.user_settings AS settings WHERE settings.user_id = p_user_id;
    v_target_retention := COALESCE(v_target_retention, 0.9);
    IF v_state.target_id IS NULL THEN
        IF p_state_revision <> 'untracked' THEN RAISE EXCEPTION 'training_exercise_state_conflict'; END IF;
        INSERT INTO public.user_training_exercise_state(user_id, target_id, fsrs_target_retention, next_review_at)
        VALUES (p_user_id, p_target_id, v_target_retention, v_now)
        RETURNING * INTO v_state;
    ELSIF v_state.state_revision::text IS DISTINCT FROM p_state_revision THEN
        RAISE EXCEPTION 'training_exercise_state_conflict';
    END IF;

    v_grade := CASE p_review_result WHEN 'fail' THEN 1 WHEN 'hard' THEN 2 WHEN 'success' THEN 3 WHEN 'easy' THEN 4 END;
    v_params := fsrs6_parameters();
    v_compute := fsrs6_compute(
        v_state.fsrs_stability, v_state.fsrs_difficulty, v_state.last_reviewed_at,
        v_grade, COALESCE(v_state.fsrs_target_retention, v_target_retention),
        v_state.fsrs_reps, v_state.fsrs_lapses, v_params
    );
    v_interval := (v_compute->>'interval')::numeric;
    UPDATE public.user_training_exercise_state
       SET fsrs_stability = (v_compute->>'stability')::numeric,
           fsrs_difficulty = (v_compute->>'difficulty')::numeric,
           fsrs_reps = (v_compute->>'reps')::integer,
           fsrs_lapses = (v_compute->>'lapses')::integer,
           fsrs_last_grade = v_grade,
           fsrs_last_interval = v_interval,
           fsrs_target_retention = COALESCE(v_state.fsrs_target_retention, v_target_retention),
           fsrs_params_version = 'fsrs-6-default',
           fsrs_enabled = true,
           next_review_at = v_now + (v_interval || ' days')::interval,
           last_seen_at = v_now,
           last_reviewed_at = v_now,
           seen_count = COALESCE(v_state.seen_count, 0) + 1,
           success_count = COALESCE(v_state.success_count, 0) + CASE WHEN v_grade >= 3 THEN 1 ELSE 0 END,
           last_result = p_review_result,
           in_learning = false,
           learning_due_at = NULL
     WHERE user_id = p_user_id AND target_id = p_target_id;

    INSERT INTO public.user_training_exercise_action_events(
        id, user_id, target_id, session_id, action, result, client_event_id,
        action_payload_hash, source_context, created_at
    ) VALUES (
        v_event_id, p_user_id, p_target_id, p_training_session_id, 'review-exercise',
        p_review_result, p_client_event_id, v_action_payload_hash, v_source_context, v_now
    );
    v_response := jsonb_build_object(
        'status', 'accepted', 'actionId', 'review-exercise',
        'clientEventId', p_client_event_id, 'eventId', v_event_id,
        'targetId', p_target_id, 'targetKey', v_target.target_key,
        'family', 'translation', 'direction', 'recall',
        'state', private.platform_v2_training_exercise_state_json_v1(p_user_id, p_target_id)
    );
    INSERT INTO public.platform_v2_training_exercise_action_receipts(
        user_id, client_event_id, target_id, action_payload_hash,
        event_id, response, created_at
    ) VALUES (
        p_user_id, p_client_event_id, p_target_id, v_action_payload_hash,
        v_event_id, v_response, v_now
    );
    IF p_training_session_id IS NOT NULL THEN
        PERFORM private.consume_platform_v2_training_exercise_session_member_v1(
            p_user_id, p_training_session_id, p_target_id
        );
    END IF;
    RETURN v_response;
END;
$$;


--
-- Name: platform_v2_card_state_json(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_card_state_json(p_user_id uuid, p_entry_id uuid, p_card_type_id text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    SELECT jsonb_build_object(
        'entryId', p_entry_id,
        'cardTypeId', p_card_type_id,
        'scheduler', jsonb_strip_nulls(jsonb_build_object(
            'phase', CASE
                WHEN COALESCE(s.hidden, false) THEN 'hidden'
                WHEN s.frozen_until IS NOT NULL AND s.frozen_until > now()
                    THEN 'frozen'
                WHEN COALESCE(s.in_learning, false) THEN 'learning'
                WHEN COALESCE(s.fsrs_reps, 0) > 0
                  OR s.last_reviewed_at IS NOT NULL THEN 'reviewing'
                WHEN COALESCE(s.seen_count, 0) > 0
                  OR COALESCE(s.click_count, 0) > 0 THEN 'encountered'
                ELSE 'not-started'
            END,
            'repeatCount', COALESCE(s.click_count, 0),
            'lastSeenAt', s.last_seen_at,
            'frozenUntil', s.frozen_until
        )),
        'knownMark', CASE
            WHEN k.id IS NULL THEN 'null'::jsonb
            ELSE jsonb_build_object(
                'markId', k.id,
                'revision', k.revision,
                'markedAt', k.marked_at
            )
        END,
        'stateRevision', COALESCE(s.state_revision::text, 'untracked')
    )
    FROM (SELECT 1) seed
    LEFT JOIN public.user_card_status s
      ON s.user_id = p_user_id
     AND s.entry_id = p_entry_id
     AND s.card_type_id = p_card_type_id
    LEFT JOIN public.user_card_known_marks k
      ON k.user_id = p_user_id
     AND k.entry_id = p_entry_id
     AND k.card_type_id = p_card_type_id
     AND k.cleared_at IS NULL;
$$;


--
-- Name: platform_v2_diagnostic_locator_ordinals(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_diagnostic_locator_ordinals(p_locator text) RETURNS integer[]
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_temp'
    AS $$
    SELECT COALESCE(
        array_agg((matched.value)[1]::integer),
        ARRAY[]::integer[]
    )
    FROM regexp_matches(COALESCE(p_locator, ''), '([0-9]+)', 'g')
        AS matched(value);
$$;


--
-- Name: platform_v2_idiom_exercise_candidates_v1(uuid, text, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_idiom_exercise_candidates_v1(p_user_id uuid, p_direction text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_candidate record;
    v_target_id uuid;
    v_target_key text;
    v_count integer := 0;
    v_error text;
    v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
    v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
BEGIN
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'missing_user_id';
    END IF;
    IF p_direction NOT IN ('direct', 'reverse') THEN
        RAISE EXCEPTION 'invalid_idiom_exercise_direction';
    END IF;

    FOR v_candidate IN
        WITH source_nodes AS (
            SELECT
                node.id AS content_node_id,
                node.entry_id,
                node.diagnostic_locator AS expression_source_path,
                node.source_text_fingerprint,
                node.created_at,
                encode(
                    digest(
                        node.id::text || ':' || node.source_text_fingerprint,
                        'sha256'
                    ),
                    'hex'
                ) AS source_revision
              FROM private.platform_v2_content_nodes AS node
             WHERE node.kind = 'idiom'
               AND node.binding_state = 'active'
               AND private.platform_v2_training_ordinary_meaning_eligible_v1(
                   p_user_id,
                   node.entry_id
               )
               AND EXISTS (
                   SELECT 1
                     FROM private.platform_v2_content_nodes AS explanation
                    WHERE explanation.parent_content_node_id = node.id
                      AND explanation.kind = 'idiom-explanation'
                      AND explanation.binding_state = 'active'
                      AND NULLIF(btrim(explanation.diagnostic_locator), '') IS NOT NULL
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM private.platform_v2_training_exercise_targets AS stale
                    WHERE stale.entry_id = node.entry_id
                      AND stale.content_node_id = node.id
                      AND stale.family = 'idiom'
                      AND stale.direction = p_direction
                      AND stale.source_text_fingerprint
                            IS DISTINCT FROM node.source_text_fingerprint
               )
        ),
        shaped AS (
            SELECT
                source_nodes.*,
                explanation.diagnostic_locator AS explanation_source_path,
                COALESCE(examples.items, '[]'::jsonb) AS examples,
                target.id AS target_id,
                state.fsrs_enabled,
                state.next_review_at,
                state.fsrs_last_interval,
                state.hidden,
                state.frozen_until,
                CASE
                    WHEN state.target_id IS NULL
                      OR COALESCE(state.fsrs_enabled, false) = false
                        THEN 0
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                         AND COALESCE(state.fsrs_last_interval, 0) < 1
                        THEN 1
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                        THEN 2
                    ELSE 3
                END AS queue_rank
              FROM source_nodes
              JOIN LATERAL (
                  SELECT child.diagnostic_locator
                    FROM private.platform_v2_content_nodes AS child
                   WHERE child.parent_content_node_id = source_nodes.content_node_id
                     AND child.kind = 'idiom-explanation'
                     AND child.binding_state = 'active'
                     AND NULLIF(btrim(child.diagnostic_locator), '') IS NOT NULL
                   ORDER BY child.created_at, child.id
                   LIMIT 1
              ) AS explanation ON true
              LEFT JOIN LATERAL (
                  SELECT jsonb_agg(child.diagnostic_locator ORDER BY child.created_at, child.id) AS items
                    FROM private.platform_v2_content_nodes AS child
                   WHERE child.parent_content_node_id = source_nodes.content_node_id
                     AND child.kind = 'example'
                     AND child.binding_state = 'active'
                     AND NULLIF(btrim(child.diagnostic_locator), '') IS NOT NULL
              ) AS examples ON true
              LEFT JOIN private.platform_v2_training_exercise_targets AS target
                ON target.entry_id = source_nodes.entry_id
               AND target.content_node_id = source_nodes.content_node_id
               AND target.family = 'idiom'
               AND target.direction = p_direction
              LEFT JOIN public.user_training_exercise_state AS state
                ON state.user_id = p_user_id
               AND state.target_id = target.id
        )
        SELECT *
          FROM shaped
         WHERE COALESCE(hidden, false) = false
               AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
                 WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
                   AND exclusion.pair_key=private.training_pair_key_v1(
                     'idiom', shaped.entry_id, shaped.content_node_id, shaped.source_text_fingerprint, NULL))
           AND (
               frozen_until IS NULL
               OR frozen_until <= private.training_reference_now_v1()
           )
         ORDER BY queue_rank, next_review_at NULLS FIRST, created_at, content_node_id
         OFFSET v_offset
         LIMIT v_limit
    LOOP
        BEGIN
            v_target_id := private.ensure_platform_v2_training_exercise_target_v1(
                v_candidate.entry_id,
                v_candidate.content_node_id,
                'idiom',
                p_direction,
                v_candidate.source_revision,
                v_candidate.source_text_fingerprint
            );
        EXCEPTION WHEN raise_exception THEN
            v_error := SQLERRM;
            IF v_error IN (
                'training_exercise_target_rebind_requires_new_node',
                'training_exercise_target_source_not_active'
            ) THEN
                CONTINUE;
            END IF;
            RAISE;
        END;

        SELECT target_key
          INTO v_target_key
          FROM private.platform_v2_training_exercise_targets
         WHERE id = v_target_id;

        RETURN NEXT jsonb_build_object(
            'targetId', v_target_id,
            'targetKey', v_target_key,
            'family', 'idiom',
            'direction', p_direction,
            'entryId', v_candidate.entry_id,
            'contentNodeId', v_candidate.content_node_id,
            'expressionSourcePath', v_candidate.expression_source_path,
            'explanationSourcePath', v_candidate.explanation_source_path,
            'exampleSourcePaths', v_candidate.examples,
            'sourceRevision', v_candidate.source_revision,
            'sourceTextFingerprint', v_candidate.source_text_fingerprint,
            'queueSource', CASE
                WHEN v_candidate.target_id IS NULL THEN 'new'
                WHEN COALESCE(v_candidate.fsrs_enabled, false) = false THEN 'new'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                     AND COALESCE(v_candidate.fsrs_last_interval, 0) < 1
                    THEN 'learning'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                    THEN 'review'
                ELSE 'practice'
            END,
            'state', private.platform_v2_training_exercise_state_json_v1(
                p_user_id,
                v_target_id
            )
        );
        v_count := v_count + 1;
        EXIT WHEN v_count >= v_limit;
    END LOOP;
END;
$$;


--
-- Name: platform_v2_idiom_exercise_candidates_v1_with_material(jsonb, uuid, text, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_idiom_exercise_candidates_v1_with_material(p_material_filter jsonb, p_user_id uuid, p_direction text, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_candidate record;
    v_target_id uuid;
    v_target_key text;
    v_count integer := 0;
    v_error text;
    v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 100);
    v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
BEGIN
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'missing_user_id';
    END IF;
    IF p_direction NOT IN ('direct', 'reverse') THEN
        RAISE EXCEPTION 'invalid_idiom_exercise_direction';
    END IF;

    FOR v_candidate IN
        WITH source_nodes AS (
            SELECT
                node.id AS content_node_id,
                node.entry_id,
                node.diagnostic_locator AS expression_source_path,
                node.source_text_fingerprint,
                node.created_at,
                encode(
                    digest(
                        node.id::text || ':' || node.source_text_fingerprint,
                        'sha256'
                    ),
                    'hex'
                ) AS source_revision
              FROM private.platform_v2_content_nodes AS node
             WHERE node.kind = 'idiom'
               AND node.binding_state = 'active'
               AND EXISTS (SELECT 1 FROM private.active_word_entries material_entry
                 WHERE material_entry.id=node.entry_id
                   AND private.training_material_entry_selected_v1(
                     material_entry.language_code,material_entry.dictionary_id,p_material_filter))
               AND private.platform_v2_training_ordinary_meaning_eligible_v1(
                   p_user_id,
                   node.entry_id
               )
               AND EXISTS (
                   SELECT 1
                     FROM private.platform_v2_content_nodes AS explanation
                    WHERE explanation.parent_content_node_id = node.id
                      AND explanation.kind = 'idiom-explanation'
                      AND explanation.binding_state = 'active'
                      AND NULLIF(btrim(explanation.diagnostic_locator), '') IS NOT NULL
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM private.platform_v2_training_exercise_targets AS stale
                    WHERE stale.entry_id = node.entry_id
                      AND stale.content_node_id = node.id
                      AND stale.family = 'idiom'
                      AND stale.direction = p_direction
                      AND stale.source_text_fingerprint
                            IS DISTINCT FROM node.source_text_fingerprint
               )
        ),
        shaped AS (
            SELECT
                source_nodes.*,
                explanation.diagnostic_locator AS explanation_source_path,
                COALESCE(examples.items, '[]'::jsonb) AS examples,
                target.id AS target_id,
                state.fsrs_enabled,
                state.next_review_at,
                state.fsrs_last_interval,
                state.hidden,
                state.frozen_until,
                CASE
                    WHEN state.target_id IS NULL
                      OR COALESCE(state.fsrs_enabled, false) = false
                        THEN 0
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                         AND COALESCE(state.fsrs_last_interval, 0) < 1
                        THEN 1
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                        THEN 2
                    ELSE 3
                END AS queue_rank
              FROM source_nodes
              JOIN LATERAL (
                  SELECT child.diagnostic_locator
                    FROM private.platform_v2_content_nodes AS child
                   WHERE child.parent_content_node_id = source_nodes.content_node_id
                     AND child.kind = 'idiom-explanation'
                     AND child.binding_state = 'active'
                     AND NULLIF(btrim(child.diagnostic_locator), '') IS NOT NULL
                   ORDER BY child.created_at, child.id
                   LIMIT 1
              ) AS explanation ON true
              LEFT JOIN LATERAL (
                  SELECT jsonb_agg(child.diagnostic_locator ORDER BY child.created_at, child.id) AS items
                    FROM private.platform_v2_content_nodes AS child
                   WHERE child.parent_content_node_id = source_nodes.content_node_id
                     AND child.kind = 'example'
                     AND child.binding_state = 'active'
                     AND NULLIF(btrim(child.diagnostic_locator), '') IS NOT NULL
              ) AS examples ON true
              LEFT JOIN private.platform_v2_training_exercise_targets AS target
                ON target.entry_id = source_nodes.entry_id
               AND target.content_node_id = source_nodes.content_node_id
               AND target.family = 'idiom'
               AND target.direction = p_direction
              LEFT JOIN public.user_training_exercise_state AS state
                ON state.user_id = p_user_id
               AND state.target_id = target.id
        )
        SELECT *
          FROM shaped
         WHERE COALESCE(hidden, false) = false
               AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
                 WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
                   AND exclusion.pair_key=private.training_pair_key_v1(
                     'idiom', shaped.entry_id, shaped.content_node_id, shaped.source_text_fingerprint, NULL))
           AND (
               frozen_until IS NULL
               OR frozen_until <= private.training_reference_now_v1()
           )
         ORDER BY queue_rank, next_review_at NULLS FIRST, created_at, content_node_id
         OFFSET v_offset
         LIMIT v_limit
    LOOP
        BEGIN
            v_target_id := private.ensure_platform_v2_training_exercise_target_v1(
                v_candidate.entry_id,
                v_candidate.content_node_id,
                'idiom',
                p_direction,
                v_candidate.source_revision,
                v_candidate.source_text_fingerprint
            );
        EXCEPTION WHEN raise_exception THEN
            v_error := SQLERRM;
            IF v_error IN (
                'training_exercise_target_rebind_requires_new_node',
                'training_exercise_target_source_not_active'
            ) THEN
                CONTINUE;
            END IF;
            RAISE;
        END;

        SELECT target_key
          INTO v_target_key
          FROM private.platform_v2_training_exercise_targets
         WHERE id = v_target_id;

        RETURN NEXT jsonb_build_object(
            'targetId', v_target_id,
            'targetKey', v_target_key,
            'family', 'idiom',
            'direction', p_direction,
            'entryId', v_candidate.entry_id,
            'contentNodeId', v_candidate.content_node_id,
            'expressionSourcePath', v_candidate.expression_source_path,
            'explanationSourcePath', v_candidate.explanation_source_path,
            'exampleSourcePaths', v_candidate.examples,
            'sourceRevision', v_candidate.source_revision,
            'sourceTextFingerprint', v_candidate.source_text_fingerprint,
            'queueSource', CASE
                WHEN v_candidate.target_id IS NULL THEN 'new'
                WHEN COALESCE(v_candidate.fsrs_enabled, false) = false THEN 'new'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                     AND COALESCE(v_candidate.fsrs_last_interval, 0) < 1
                    THEN 'learning'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                    THEN 'review'
                ELSE 'practice'
            END,
            'state', private.platform_v2_training_exercise_state_json_v1(
                p_user_id,
                v_target_id
            )
        );
        v_count := v_count + 1;
        EXIT WHEN v_count >= v_limit;
    END LOOP;
END;
$$;


--
-- Name: platform_v2_idiom_exercise_candidates_v2(uuid, text, integer, integer, uuid, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_idiom_exercise_candidates_v2(p_user_id uuid, p_direction text, p_limit integer, p_offset integer, p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_candidate record;
    v_target_id uuid;
    v_target_key text;
    v_error text;
    v_limit integer := GREATEST(COALESCE(p_limit, 20), 1);
    v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
BEGIN
    PERFORM private.training_review_early_v1(p_training_filter,p_card_filter);
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'missing_user_id';
    END IF;
    IF p_direction NOT IN ('direct', 'reverse') THEN
        RAISE EXCEPTION 'invalid_idiom_exercise_direction';
    END IF;
    IF p_card_filter NOT IN ('new', 'review', 'both') THEN
        RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
    END IF;

    FOR v_candidate IN
        WITH source_nodes AS (
            SELECT * FROM private.training_idiom_source_nodes_v1(
                p_user_id, p_direction, p_list_id, p_list_type, p_training_filter
            )
        ),
        shaped AS (
            SELECT
                source_nodes.*,
                explanation.diagnostic_locator AS explanation_source_path,
                COALESCE(examples.items, '[]'::jsonb) AS examples,
                target.id AS target_id,
                state.fsrs_enabled,
                (COALESCE(state.fsrs_reps,0)>0 OR state.last_reviewed_at IS NOT NULL) introduced,
                state.next_review_at,
                state.fsrs_last_interval,
                state.hidden,
                state.frozen_until,
                CASE
                    WHEN state.target_id IS NULL
                      OR COALESCE(state.fsrs_enabled, false) = false
                        THEN 0
                    WHEN private.training_review_early_v1(p_training_filter,p_card_filter)
                        THEN CASE WHEN COALESCE(state.fsrs_last_interval,0)<1 THEN 1 ELSE 2 END
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                         AND COALESCE(state.fsrs_last_interval, 0) < 1
                        THEN 1
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                        THEN 2
                    ELSE 3
                END AS queue_rank
              FROM source_nodes
              JOIN LATERAL (
                  SELECT child.diagnostic_locator
                    FROM private.platform_v2_content_nodes AS child
                   WHERE child.parent_content_node_id = source_nodes.content_node_id
                     AND child.kind = 'idiom-explanation'
                     AND child.binding_state = 'active'
                     AND NULLIF(btrim(child.diagnostic_locator), '') IS NOT NULL
                   ORDER BY child.created_at, child.id
                   LIMIT 1
              ) AS explanation ON true
              LEFT JOIN LATERAL (
                  SELECT jsonb_agg(child.diagnostic_locator ORDER BY child.created_at, child.id) AS items
                    FROM private.platform_v2_content_nodes AS child
                   WHERE child.parent_content_node_id = source_nodes.content_node_id
                     AND child.kind = 'example'
                     AND child.binding_state = 'active'
                     AND NULLIF(btrim(child.diagnostic_locator), '') IS NOT NULL
              ) AS examples ON true
              LEFT JOIN private.platform_v2_training_exercise_targets AS target
                ON target.entry_id = source_nodes.entry_id
               AND target.content_node_id = source_nodes.content_node_id
               AND target.family = 'idiom'
               AND target.direction = p_direction
              LEFT JOIN public.user_training_exercise_state AS state
                ON state.user_id = p_user_id
               AND state.target_id = target.id
        ), ranked AS (
            SELECT shaped.*,
                   row_number() OVER (
                       PARTITION BY CASE WHEN queue_rank = 0 THEN 0 ELSE 1 END
                       ORDER BY CASE WHEN private.training_review_early_v1(p_training_filter,p_card_filter) THEN 0 ELSE queue_rank END,
                                next_review_at NULLS FIRST, created_at, content_node_id
                   ) AS queue_ordinal
              FROM shaped
             WHERE COALESCE(hidden, false) = false
               AND (NOT private.training_review_early_v1(p_training_filter,p_card_filter)
                 OR (introduced AND fsrs_enabled=true))
               AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
                 WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
                   AND exclusion.pair_key=private.training_pair_key_v1(
                     'idiom', shaped.entry_id, shaped.content_node_id, shaped.source_text_fingerprint, NULL))
               AND (
                   frozen_until IS NULL
                   OR frozen_until <= private.training_reference_now_v1()
               )
               AND (
                   (p_card_filter IN ('both', 'new') AND queue_rank = 0)
                   OR (p_card_filter IN ('both', 'review') AND queue_rank IN (1, 2))
               )
        )
        SELECT *
          FROM ranked
         WHERE queue_ordinal > v_offset
           AND queue_ordinal <= v_offset::bigint + v_limit::bigint
         ORDER BY CASE WHEN private.training_review_early_v1(p_training_filter,p_card_filter) THEN 0 ELSE queue_rank END,
                  next_review_at NULLS FIRST, created_at, content_node_id
    LOOP
        BEGIN
            v_target_id := private.ensure_platform_v2_training_exercise_target_v1(
                v_candidate.entry_id,
                v_candidate.content_node_id,
                'idiom',
                p_direction,
                v_candidate.source_revision,
                v_candidate.source_text_fingerprint
            );
        EXCEPTION WHEN raise_exception THEN
            v_error := SQLERRM;
            IF v_error IN (
                'training_exercise_target_rebind_requires_new_node',
                'training_exercise_target_source_not_active'
            ) THEN
                CONTINUE;
            END IF;
            RAISE;
        END;

        SELECT target_key
          INTO v_target_key
          FROM private.platform_v2_training_exercise_targets
         WHERE id = v_target_id;

        RETURN NEXT jsonb_build_object(
            'targetId', v_target_id,
            'targetKey', v_target_key,
            'family', 'idiom',
            'direction', p_direction,
            'entryId', v_candidate.entry_id,
            'contentNodeId', v_candidate.content_node_id,
            'expressionSourcePath', v_candidate.expression_source_path,
            'explanationSourcePath', v_candidate.explanation_source_path,
            'exampleSourcePaths', v_candidate.examples,
            'sourceRevision', v_candidate.source_revision,
            'sourceTextFingerprint', v_candidate.source_text_fingerprint,
            'queueSource', CASE
                WHEN v_candidate.target_id IS NULL THEN 'new'
                WHEN COALESCE(v_candidate.fsrs_enabled, false) = false THEN 'new'
                WHEN private.training_review_early_v1(p_training_filter,p_card_filter)
                    THEN CASE WHEN COALESCE(v_candidate.fsrs_last_interval,0)<1 THEN 'learning' ELSE 'review' END
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                     AND COALESCE(v_candidate.fsrs_last_interval, 0) < 1
                    THEN 'learning'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                    THEN 'review'
                ELSE 'practice'
            END,
            'state', private.platform_v2_training_exercise_state_json_v1(
                p_user_id,
                v_target_id
            )
        );
    END LOOP;
END;
$$;


--
-- Name: platform_v2_report_atom_revision(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_report_atom_revision(p_entry_id uuid) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
    SELECT encode(
        digest(
            'platform-v2-report-atoms-v1:' || COALESCE(
                jsonb_agg(
                    jsonb_build_object(
                        'atomOrder', atom.atom_order,
                        'role', atom.role,
                        'contentNodeId', atom.content_node_id,
                        'text', atom.source_text
                    ) ORDER BY atom.atom_order
                )::text,
                '[]'
            ),
            'sha256'
        ),
        'hex'
    )
    FROM private.platform_v2_report_atom_source(p_entry_id) AS atom;
$$;


--
-- Name: platform_v2_report_atom_revision_or_null(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_report_atom_revision_or_null(p_entry_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    RETURN private.platform_v2_report_atom_revision(p_entry_id);
EXCEPTION WHEN OTHERS THEN
    RETURN NULL;
END;
$$;


--
-- Name: platform_v2_report_atom_source(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_report_atom_source(p_entry_id uuid) RETURNS TABLE(atom_order integer, role text, content_node_id uuid, source_text text)
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    IF EXISTS (
        SELECT 1
        FROM private.platform_v2_content_nodes AS node
        WHERE node.entry_id = p_entry_id
          AND node.binding_state = 'active'
          AND (node.canonical_source_text IS NULL OR node.source_order IS NULL)
    ) THEN
        RAISE EXCEPTION 'report_atom_projection_unverifiable';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM private.platform_v2_content_nodes AS node
        LEFT JOIN private.platform_v2_content_nodes AS parent
          ON parent.id = node.parent_content_node_id
        WHERE node.entry_id = p_entry_id
          AND node.binding_state = 'active'
          AND (
              (node.kind = 'idiom-explanation' AND node.parent_content_node_id IS NULL)
              OR (
                node.parent_content_node_id IS NOT NULL
                AND node.kind IN ('idiom-explanation', 'example')
                AND (
                    parent.entry_id IS DISTINCT FROM p_entry_id
                    OR parent.binding_state IS DISTINCT FROM 'active'
                    OR parent.kind IS DISTINCT FROM 'idiom'
                )
              )
          )
    ) THEN
        RAISE EXCEPTION 'report_atom_projection_unverifiable';
    END IF;

    RETURN QUERY
    WITH entry_atom AS (
        SELECT
            '0000000000'::text AS ordering,
            'headword'::text AS role,
            NULL::uuid AS content_node_id,
            normalize(trim(entry.headword), NFC) AS source_text
        FROM private.active_word_entries AS entry
        WHERE entry.id = p_entry_id
    ), node_atoms AS (
        SELECT
            CASE
                WHEN node.kind = 'definition' THEN
                    '10|' || lpad(node.source_order::text, 10, '0')
                WHEN node.kind = 'usage-pattern' THEN
                    '20|' || lpad(node.source_order::text, 10, '0')
                WHEN node.kind = 'idiom' THEN
                    '30|' || lpad(node.source_order::text, 10, '0') || '|0|0000000000'
                WHEN parent.kind = 'idiom' AND node.kind = 'idiom-explanation' THEN
                    '30|' || lpad(parent.source_order::text, 10, '0') || '|1|'
                        || lpad(node.source_order::text, 10, '0')
                WHEN parent.kind = 'idiom' AND node.kind = 'example' THEN
                    '30|' || lpad(parent.source_order::text, 10, '0') || '|2|'
                        || lpad(node.source_order::text, 10, '0')
                WHEN node.kind = 'example' AND node.parent_content_node_id IS NULL THEN
                    '40|' || lpad(node.source_order::text, 10, '0')
                WHEN node.kind = 'usage-note' THEN
                    '50|' || lpad(node.source_order::text, 10, '0')
                ELSE NULL
            END AS ordering,
            node.kind AS role,
            node.id AS content_node_id,
            node.canonical_source_text AS source_text
        FROM private.platform_v2_content_nodes AS node
        LEFT JOIN private.platform_v2_content_nodes AS parent
          ON parent.id = node.parent_content_node_id
        WHERE node.entry_id = p_entry_id
          AND node.binding_state = 'active'
    ), ordered AS (
        SELECT * FROM entry_atom
        UNION ALL
        SELECT * FROM node_atoms WHERE ordering IS NOT NULL
    )
    SELECT
        row_number() OVER (ORDER BY ordering)::integer,
        ordered.role,
        ordered.content_node_id,
        ordered.source_text
    FROM ordered
    ORDER BY ordering;
END;
$$;


--
-- Name: platform_v2_report_card_content_canonical(jsonb, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_report_card_content_canonical(p_atoms jsonb, p_omitted_atom_count integer) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_atom jsonb;
    v_parts text[] := ARRAY[]::text[];
BEGIN
    FOR v_atom IN SELECT value FROM jsonb_array_elements(p_atoms) LOOP
        v_parts := array_append(
            v_parts,
            '{"contentNodeId":'
            || CASE
                WHEN v_atom->'contentNodeId' = 'null'::jsonb THEN 'null'
                ELSE to_json(v_atom->>'contentNodeId')::text
            END
            || ',"role":' || to_json(v_atom->>'role')::text
            || ',"text":' || to_json(v_atom->>'text')::text
            || ',"truncated":' || lower((v_atom->>'truncated')::boolean::text)
            || '}'
        );
    END LOOP;
    RETURN '{"atoms":[' || array_to_string(v_parts, ',')
        || '],"omittedAtomCount":' || p_omitted_atom_count::text || '}';
END;
$$;


--
-- Name: platform_v2_text_at_diagnostic_locator(jsonb, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_text_at_diagnostic_locator(p_raw jsonb, p_locator text, p_kind text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_locator text;
    v_path text[];
    v_value jsonb;
    v_text text;
BEGIN
    v_locator := regexp_replace(COALESCE(p_locator, ''), '^raw\.', '');
    v_locator := regexp_replace(v_locator, '\[([0-9]+)\]', '.\1', 'g');
    v_path := regexp_split_to_array(v_locator, '\.');
    v_value := p_raw #> v_path;

    IF jsonb_typeof(v_value) = 'string' THEN
        v_text := v_value #>> '{}';
    ELSIF jsonb_typeof(v_value) = 'object' AND p_kind = 'idiom' THEN
        v_text := v_value->>'expression';
    ELSIF jsonb_typeof(v_value) = 'object' AND p_kind = 'example' THEN
        v_text := COALESCE(v_value->>'source', v_value->>'text');
    ELSE
        v_text := NULL;
    END IF;

    v_text := NULLIF(trim(v_text), '');
    RETURN CASE WHEN v_text IS NULL THEN NULL ELSE normalize(v_text, NFC) END;
END;
$$;


--
-- Name: platform_v2_training_entry_group_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_training_entry_group_v1(p_entry_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    SELECT COALESCE(source_group.id, user_group.id)
      FROM public.word_entries AS entry
      LEFT JOIN private.source_entry_bindings AS binding
        ON binding.word_entry_id = entry.id
       AND binding.binding_state = 'active'
      LEFT JOIN private.platform_v2_headword_groups AS source_group
        ON source_group.management_kind = 'source'
       AND source_group.dictionary_id = binding.dictionary_id
       AND source_group.identity_scheme_version = binding.identity_scheme_version
       AND source_group.source_group_key = binding.source_group_key
      LEFT JOIN private.platform_v2_headword_groups AS user_group
        ON user_group.management_kind = 'user'
       AND user_group.singleton_entry_id = entry.id
     WHERE entry.id = p_entry_id
     LIMIT 1;
$$;


--
-- Name: platform_v2_training_exercise_action_payload_v1(uuid, uuid, text, uuid, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_training_exercise_action_payload_v1(p_user_id uuid, p_target_id uuid, p_review_result text, p_client_event_id uuid, p_training_session_id uuid, p_source_context jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
    SELECT jsonb_strip_nulls(jsonb_build_object(
        'contractVersion', 'platform-training-exercise-action-v1',
        'userId', p_user_id,
        'actionId', 'review-exercise',
        'targetId', p_target_id,
        'reviewResult', p_review_result,
        'clientEventId', p_client_event_id,
        'trainingSessionId', p_training_session_id,
        'sourceContext', NULLIF(
            jsonb_strip_nulls(jsonb_build_object(
                'contractVersion', p_source_context->>'contractVersion',
                'source', p_source_context->'source',
                'artifact', p_source_context->'artifact',
                'location', p_source_context->'location',
                'selection', p_source_context->'selection',
                'context', p_source_context->'context'
            )),
            '{}'::jsonb
        )
    ));
$$;


--
-- Name: platform_v2_training_exercise_state_json_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_training_exercise_state_json_v1(p_user_id uuid, p_target_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    SELECT CASE
        WHEN state.target_id IS NULL THEN NULL::jsonb
        ELSE jsonb_build_object(
            'stateRevision', state.state_revision,
            'fsrsStability', state.fsrs_stability,
            'fsrsDifficulty', state.fsrs_difficulty,
            'fsrsReps', state.fsrs_reps,
            'fsrsLapses', state.fsrs_lapses,
            'fsrsLastGrade', state.fsrs_last_grade,
            'fsrsLastInterval', state.fsrs_last_interval,
            'fsrsTargetRetention', state.fsrs_target_retention,
            'fsrsParamsVersion', state.fsrs_params_version,
            'fsrsEnabled', state.fsrs_enabled,
            'nextReviewAt', state.next_review_at,
            'lastSeenAt', state.last_seen_at,
            'lastReviewedAt', state.last_reviewed_at,
            'seenCount', state.seen_count,
            'successCount', state.success_count,
            'lastResult', state.last_result,
            'hidden', state.hidden,
            'frozenUntil', state.frozen_until,
            'inLearning', state.in_learning,
            'learningDueAt', state.learning_due_at
        )
    END
      FROM (SELECT 1) AS seed
      LEFT JOIN public.user_training_exercise_state AS state
        ON state.user_id = p_user_id
       AND state.target_id = p_target_id;
$$;


--
-- Name: platform_v2_training_ordinary_meaning_eligible_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_training_ordinary_meaning_eligible_v1(p_user_id uuid, p_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    WITH target_entry AS MATERIALIZED (
        SELECT entry.id
          FROM private.active_word_entries AS entry
         WHERE entry.id = p_entry_id
           AND private.entry_access_v1(p_user_id,entry.id,'train')
    ), target_source_group AS MATERIALIZED (
        SELECT target.id AS target_entry_id,
               source_group.id AS group_id,
               source_group.dictionary_id,
               source_group.identity_scheme_version,
               source_group.source_group_key
          FROM target_entry AS target
          LEFT JOIN private.source_entry_bindings AS binding
            ON binding.word_entry_id = target.id
           AND binding.binding_state = 'active'
          LEFT JOIN private.platform_v2_headword_groups AS source_group
            ON source_group.management_kind = 'source'
           AND source_group.dictionary_id = binding.dictionary_id
           AND source_group.identity_scheme_version =
               binding.identity_scheme_version
           AND source_group.source_group_key = binding.source_group_key
    ), grouped_entries AS (
        -- Unbound and user-owned entries have no source siblings. A user
        -- headword group is a singleton, so the direct entry is equivalent.
        SELECT target.target_entry_id AS id
          FROM target_source_group AS target
         WHERE target.group_id IS NULL

        UNION ALL

        SELECT sibling.word_entry_id AS id
          FROM target_source_group AS target
          JOIN private.source_entry_bindings AS sibling
            ON sibling.dictionary_id = target.dictionary_id
           AND sibling.identity_scheme_version =
               target.identity_scheme_version
           AND sibling.source_group_key = target.source_group_key
           AND sibling.binding_state = 'active'
         WHERE target.group_id IS NOT NULL
    )
    SELECT EXISTS (
        SELECT 1
          FROM grouped_entries AS grouped
          JOIN private.active_word_entries AS entry ON entry.id = grouped.id
         WHERE private.entry_access_v1(p_user_id,entry.id,'train')
           AND (
               EXISTS (
                   SELECT 1
                     FROM public.user_card_status AS status
                    WHERE status.user_id = p_user_id
                      AND status.entry_id = grouped.id
                      AND status.card_type_id IN (
                          'word-to-definition', 'definition-to-word'
                      )
                      AND (
                          COALESCE(status.in_learning, false)
                          OR COALESCE(status.fsrs_enabled, false)
                          OR COALESCE(status.fsrs_reps, 0) > 0
                          OR status.last_reviewed_at IS NOT NULL
                      )
               )
               OR EXISTS (
                   SELECT 1
                     FROM public.user_card_known_marks AS known
                    WHERE known.user_id = p_user_id
                      AND known.entry_id = grouped.id
                      AND known.card_type_id IN (
                          'word-to-definition', 'definition-to-word'
                      )
                      AND known.cleared_at IS NULL
               )
           )
    );
$$;


--
-- Name: platform_v2_translation_exercise_candidates_v1(uuid, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_translation_exercise_candidates_v1(p_user_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_candidate record;
    v_target_id uuid;
    v_target_key text;
    v_count integer := 0;
    v_error text;
    v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 1000);
    v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
BEGIN
    IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;

    FOR v_candidate IN
        WITH source_nodes AS (
            SELECT
                node.id AS content_node_id,
                node.entry_id,
                node.diagnostic_locator AS source_path,
                node.source_text_fingerprint,
                node.created_at,
                encode(digest(
                    node.id::text || ':' || node.source_text_fingerprint,
                    'sha256'
                ), 'hex') AS source_revision
              FROM private.platform_v2_content_nodes AS node
             WHERE node.kind = 'example'
               AND node.binding_state = 'active'
               AND NULLIF(btrim(node.diagnostic_locator), '') IS NOT NULL
               AND node.diagnostic_locator ~ '^raw\.meanings\[[0-9]+\]\.examples\[[0-9]+\]$'
               AND private.platform_v2_training_ordinary_meaning_eligible_v1(
                   p_user_id, node.entry_id
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM private.platform_v2_training_exercise_targets AS stale
                    WHERE stale.entry_id = node.entry_id
                      AND stale.content_node_id = node.id
                      AND stale.family = 'translation'
                      AND stale.direction = 'recall'
                      AND stale.source_text_fingerprint
                            IS DISTINCT FROM node.source_text_fingerprint
               )
        ),
        shaped AS (
            SELECT
                source_nodes.*,
                target.id AS target_id,
                state.fsrs_enabled,
                state.next_review_at,
                state.fsrs_last_interval,
                state.hidden,
                state.frozen_until,
                CASE
                    WHEN state.target_id IS NULL
                      OR COALESCE(state.fsrs_enabled, false) = false THEN 0
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                         AND COALESCE(state.fsrs_last_interval, 0) < 1 THEN 1
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                        THEN 2
                    ELSE 3
                END AS queue_rank
              FROM source_nodes
              LEFT JOIN private.platform_v2_training_exercise_targets AS target
                ON target.entry_id = source_nodes.entry_id
               AND target.content_node_id = source_nodes.content_node_id
               AND target.family = 'translation'
               AND target.direction = 'recall'
              LEFT JOIN public.user_training_exercise_state AS state
                ON state.user_id = p_user_id
               AND state.target_id = target.id
        )
        SELECT *
         FROM shaped
         WHERE COALESCE(hidden, false) = false
               AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
                 WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
                   AND exclusion.pair_key=private.training_pair_key_v1(
                     'translation', shaped.entry_id, shaped.content_node_id, shaped.source_text_fingerprint, NULL))
           AND (frozen_until IS NULL OR frozen_until <= private.training_reference_now_v1())
           AND queue_rank < 3
         ORDER BY queue_rank, next_review_at NULLS FIRST, created_at, content_node_id
         OFFSET v_offset
         LIMIT v_limit
    LOOP
        BEGIN
            v_target_id := private.ensure_platform_v2_training_exercise_target_v1(
                v_candidate.entry_id,
                v_candidate.content_node_id,
                'translation',
                'recall',
                v_candidate.source_revision,
                v_candidate.source_text_fingerprint
            );
        EXCEPTION WHEN raise_exception THEN
            v_error := SQLERRM;
            IF v_error IN (
                'training_exercise_target_rebind_requires_new_node',
                'training_exercise_target_source_not_active'
            ) THEN CONTINUE; END IF;
            RAISE;
        END;

        SELECT target_key INTO v_target_key
          FROM private.platform_v2_training_exercise_targets
         WHERE id = v_target_id;

        RETURN NEXT jsonb_build_object(
            'targetId', v_target_id,
            'targetKey', v_target_key,
            'family', 'translation',
            'direction', 'recall',
            'entryId', v_candidate.entry_id,
            'contentNodeId', v_candidate.content_node_id,
            'sourcePath', v_candidate.source_path,
            'sourceRevision', v_candidate.source_revision,
            'sourceTextFingerprint', v_candidate.source_text_fingerprint,
            'queueSource', CASE
                WHEN v_candidate.target_id IS NULL THEN 'new'
                WHEN COALESCE(v_candidate.fsrs_enabled, false) = false THEN 'new'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                     AND COALESCE(v_candidate.fsrs_last_interval, 0) < 1 THEN 'learning'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                    THEN 'review'
                ELSE 'practice'
            END,
            'state', private.platform_v2_training_exercise_state_json_v1(
                p_user_id, v_target_id
            )
        );
        v_count := v_count + 1;
        EXIT WHEN v_count >= v_limit;
    END LOOP;
END;
$_$;


--
-- Name: platform_v2_translation_exercise_candidates_v1_with_material(jsonb, uuid, integer, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_translation_exercise_candidates_v1_with_material(p_material_filter jsonb, p_user_id uuid, p_limit integer DEFAULT 20, p_offset integer DEFAULT 0) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_candidate record;
    v_target_id uuid;
    v_target_key text;
    v_count integer := 0;
    v_error text;
    v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 1000);
    v_offset integer := GREATEST(COALESCE(p_offset, 0), 0);
BEGIN
    IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;

    FOR v_candidate IN
        WITH source_nodes AS (
            SELECT
                node.id AS content_node_id,
                node.entry_id,
                node.diagnostic_locator AS source_path,
                node.source_text_fingerprint,
                node.created_at,
                encode(digest(
                    node.id::text || ':' || node.source_text_fingerprint,
                    'sha256'
                ), 'hex') AS source_revision
              FROM private.platform_v2_content_nodes AS node
             WHERE node.kind = 'example'
               AND node.binding_state = 'active'
               AND EXISTS (SELECT 1 FROM private.active_word_entries material_entry
                 WHERE material_entry.id=node.entry_id
                   AND private.training_material_entry_selected_v1(
                     material_entry.language_code,material_entry.dictionary_id,p_material_filter))
               AND NULLIF(btrim(node.diagnostic_locator), '') IS NOT NULL
               AND node.diagnostic_locator ~ '^raw\.meanings\[[0-9]+\]\.examples\[[0-9]+\]$'
               AND private.platform_v2_training_ordinary_meaning_eligible_v1(
                   p_user_id, node.entry_id
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM private.platform_v2_training_exercise_targets AS stale
                    WHERE stale.entry_id = node.entry_id
                      AND stale.content_node_id = node.id
                      AND stale.family = 'translation'
                      AND stale.direction = 'recall'
                      AND stale.source_text_fingerprint
                            IS DISTINCT FROM node.source_text_fingerprint
               )
        ),
        shaped AS (
            SELECT
                source_nodes.*,
                target.id AS target_id,
                state.fsrs_enabled,
                state.next_review_at,
                state.fsrs_last_interval,
                state.hidden,
                state.frozen_until,
                CASE
                    WHEN state.target_id IS NULL
                      OR COALESCE(state.fsrs_enabled, false) = false THEN 0
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                         AND COALESCE(state.fsrs_last_interval, 0) < 1 THEN 1
                    WHEN state.next_review_at <= private.training_reference_now_v1()
                        THEN 2
                    ELSE 3
                END AS queue_rank
              FROM source_nodes
              LEFT JOIN private.platform_v2_training_exercise_targets AS target
                ON target.entry_id = source_nodes.entry_id
               AND target.content_node_id = source_nodes.content_node_id
               AND target.family = 'translation'
               AND target.direction = 'recall'
              LEFT JOIN public.user_training_exercise_state AS state
                ON state.user_id = p_user_id
               AND state.target_id = target.id
        )
        SELECT *
         FROM shaped
         WHERE COALESCE(hidden, false) = false
               AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
                 WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
                   AND exclusion.pair_key=private.training_pair_key_v1(
                     'translation', shaped.entry_id, shaped.content_node_id, shaped.source_text_fingerprint, NULL))
           AND (frozen_until IS NULL OR frozen_until <= private.training_reference_now_v1())
           AND queue_rank < 3
         ORDER BY queue_rank, next_review_at NULLS FIRST, created_at, content_node_id
         OFFSET v_offset
         LIMIT v_limit
    LOOP
        BEGIN
            v_target_id := private.ensure_platform_v2_training_exercise_target_v1(
                v_candidate.entry_id,
                v_candidate.content_node_id,
                'translation',
                'recall',
                v_candidate.source_revision,
                v_candidate.source_text_fingerprint
            );
        EXCEPTION WHEN raise_exception THEN
            v_error := SQLERRM;
            IF v_error IN (
                'training_exercise_target_rebind_requires_new_node',
                'training_exercise_target_source_not_active'
            ) THEN CONTINUE; END IF;
            RAISE;
        END;

        SELECT target_key INTO v_target_key
          FROM private.platform_v2_training_exercise_targets
         WHERE id = v_target_id;

        RETURN NEXT jsonb_build_object(
            'targetId', v_target_id,
            'targetKey', v_target_key,
            'family', 'translation',
            'direction', 'recall',
            'entryId', v_candidate.entry_id,
            'contentNodeId', v_candidate.content_node_id,
            'sourcePath', v_candidate.source_path,
            'sourceRevision', v_candidate.source_revision,
            'sourceTextFingerprint', v_candidate.source_text_fingerprint,
            'queueSource', CASE
                WHEN v_candidate.target_id IS NULL THEN 'new'
                WHEN COALESCE(v_candidate.fsrs_enabled, false) = false THEN 'new'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                     AND COALESCE(v_candidate.fsrs_last_interval, 0) < 1 THEN 'learning'
                WHEN v_candidate.next_review_at <= private.training_reference_now_v1()
                    THEN 'review'
                ELSE 'practice'
            END,
            'state', private.platform_v2_training_exercise_state_json_v1(
                p_user_id, v_target_id
            )
        );
        v_count := v_count + 1;
        EXIT WHEN v_count >= v_limit;
    END LOOP;
END;
$_$;


--
-- Name: platform_v2_translation_exercise_candidates_v2(uuid, integer, integer, uuid, text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_translation_exercise_candidates_v2(p_user_id uuid, p_limit integer, p_offset integer, p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb) RETURNS SETOF jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
  WITH source_nodes AS MATERIALIZED (
    SELECT *
      FROM private.training_translation_source_nodes_v1(
        p_user_id, p_list_id, p_list_type, p_training_filter
      )
  ), shaped AS (
    SELECT source_nodes.*,
           target.id AS target_id,
           state.fsrs_enabled,
           state.next_review_at,
           state.fsrs_last_interval,
           state.hidden,
           state.frozen_until,
           CASE
             WHEN state.target_id IS NULL
               OR COALESCE(state.fsrs_enabled, false) = false THEN 0
             WHEN state.next_review_at <= private.training_reference_now_v1()
               AND COALESCE(state.fsrs_last_interval, 0) < 1 THEN 1
             WHEN state.next_review_at <= private.training_reference_now_v1() THEN 2
             ELSE 3
           END AS queue_rank
      FROM source_nodes
      LEFT JOIN private.platform_v2_training_exercise_targets AS target
        ON target.entry_id = source_nodes.entry_id
       AND target.content_node_id = source_nodes.content_node_id
       AND target.family = 'translation'
       AND target.direction = 'recall'
      LEFT JOIN public.user_training_exercise_state AS state
        ON state.user_id = p_user_id
       AND state.target_id = target.id
  ), ranked AS (
    SELECT shaped.*,
           row_number() OVER (
             PARTITION BY CASE WHEN queue_rank = 0 THEN 0 ELSE 1 END
             ORDER BY queue_rank, next_review_at NULLS FIRST,
                      created_at, content_node_id
           ) AS queue_ordinal
      FROM shaped
     WHERE COALESCE(hidden, false) = false
       AND NOT EXISTS (
         SELECT 1
           FROM private.training_pair_exclusions AS exclusion
          WHERE exclusion.user_id = p_user_id
            AND exclusion.restored_at IS NULL
            AND exclusion.pair_key = private.training_pair_key_v1(
              'translation', shaped.entry_id, shaped.content_node_id,
              shaped.source_text_fingerprint, NULL
            )
       )
       AND (frozen_until IS NULL
            OR frozen_until <= private.training_reference_now_v1())
       AND (
         (p_card_filter IN ('both', 'new') AND queue_rank = 0)
         OR (p_card_filter IN ('both', 'review') AND queue_rank IN (1, 2))
       )
  ), selected AS MATERIALIZED (
    SELECT *
      FROM ranked
     WHERE queue_ordinal > GREATEST(COALESCE(p_offset, 0), 0)
       AND queue_ordinal <= GREATEST(COALESCE(p_offset, 0), 0)::bigint
         + LEAST(GREATEST(COALESCE(p_limit, 20), 1), 1000)
     ORDER BY queue_rank, next_review_at NULLS FIRST,
              created_at, content_node_id
  ), ensured AS (
    INSERT INTO private.platform_v2_training_exercise_targets (
      entry_id, content_node_id, family, direction,
      source_revision, source_text_fingerprint
    )
    SELECT entry_id, content_node_id, 'translation', 'recall',
           source_revision, source_text_fingerprint
      FROM selected
    ON CONFLICT (entry_id, content_node_id, family, direction)
    DO UPDATE
       SET source_revision = EXCLUDED.source_revision,
           visibility_state = 'active',
           retired_at = NULL,
           retirement_reason = NULL,
           updated_at = private.training_reference_now_v1()
     WHERE platform_v2_training_exercise_targets.source_text_fingerprint
             = EXCLUDED.source_text_fingerprint
       AND (
         platform_v2_training_exercise_targets.source_revision
           IS DISTINCT FROM EXCLUDED.source_revision
         OR platform_v2_training_exercise_targets.visibility_state <> 'active'
         OR platform_v2_training_exercise_targets.retired_at IS NOT NULL
         OR platform_v2_training_exercise_targets.retirement_reason IS NOT NULL
       )
    RETURNING id, entry_id, content_node_id, target_key
  ), target_rows AS MATERIALIZED (
    SELECT target.id, target.entry_id, target.content_node_id,
           target.target_key
      FROM private.platform_v2_training_exercise_targets AS target
      JOIN selected
        ON selected.entry_id = target.entry_id
       AND selected.content_node_id = target.content_node_id
     WHERE target.family = 'translation'
       AND target.direction = 'recall'
    UNION
    SELECT id, entry_id, content_node_id, target_key
      FROM ensured
  )
  SELECT jsonb_build_object(
           'targetId', target.id,
           'targetKey', target.target_key,
           'family', 'translation',
           'direction', 'recall',
           'entryId', selected.entry_id,
           'contentNodeId', selected.content_node_id,
           'sourcePath', selected.source_path,
           'sourceRevision', selected.source_revision,
           'sourceTextFingerprint', selected.source_text_fingerprint,
           'queueSource', CASE
             WHEN selected.target_id IS NULL THEN 'new'
             WHEN COALESCE(selected.fsrs_enabled, false) = false THEN 'new'
             WHEN selected.next_review_at <= private.training_reference_now_v1()
               AND COALESCE(selected.fsrs_last_interval, 0) < 1 THEN 'learning'
             WHEN selected.next_review_at <= private.training_reference_now_v1()
               THEN 'review'
             ELSE 'practice'
           END,
           'state', CASE
             WHEN state.target_id IS NULL THEN NULL::jsonb
             ELSE jsonb_build_object(
               'stateRevision', state.state_revision,
               'fsrsStability', state.fsrs_stability,
               'fsrsDifficulty', state.fsrs_difficulty,
               'fsrsReps', state.fsrs_reps,
               'fsrsLapses', state.fsrs_lapses,
               'fsrsLastGrade', state.fsrs_last_grade,
               'fsrsLastInterval', state.fsrs_last_interval,
               'fsrsTargetRetention', state.fsrs_target_retention,
               'fsrsParamsVersion', state.fsrs_params_version,
               'fsrsEnabled', state.fsrs_enabled,
               'nextReviewAt', state.next_review_at,
               'lastSeenAt', state.last_seen_at,
               'lastReviewedAt', state.last_reviewed_at,
               'seenCount', state.seen_count,
               'successCount', state.success_count,
               'lastResult', state.last_result,
               'hidden', state.hidden,
               'frozenUntil', state.frozen_until,
               'inLearning', state.in_learning,
               'learningDueAt', state.learning_due_at
             )
           END
         )
    FROM selected
    JOIN target_rows AS target
      ON target.entry_id = selected.entry_id
     AND target.content_node_id = selected.content_node_id
    LEFT JOIN public.user_training_exercise_state AS state
      ON state.user_id = p_user_id
     AND state.target_id = target.id
   ORDER BY selected.queue_rank, selected.next_review_at NULLS FIRST,
            selected.created_at, selected.content_node_id;
$$;


--
-- Name: platform_v2_user_entry_content_nodes(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.platform_v2_user_entry_content_nodes(p_raw jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE nodes jsonb:='[]'::jsonb; meaning jsonb; item jsonb; child jsonb;
  mi integer; ei integer; ii integer; ci integer; prefix text; idiom_path text;
BEGIN
  IF NOT (p_raw ? 'meanings') THEN RETURN private.simple_user_entry_content_nodes_v1(p_raw); END IF;
  FOR meaning,mi IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(p_raw->'meanings') WITH ORDINALITY LOOP
    prefix:='raw.meanings['||mi||']';
    nodes:=nodes||private.owned_entry_content_atom_v1(prefix||'.definition','definition',meaning->>'definition');
    nodes:=nodes||private.owned_entry_content_atom_v1(prefix||'.context','usage-pattern',meaning->>'context');
    FOR item,ei IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(COALESCE(meaning->'examples','[]')) WITH ORDINALITY LOOP
      nodes:=nodes||private.owned_entry_content_atom_v1(prefix||'.examples['||ei||']','example',item#>>'{}');
    END LOOP;
    FOR item,ii IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(COALESCE(meaning->'idioms','[]')) WITH ORDINALITY LOOP
      idiom_path:=prefix||'.idioms['||ii||']';
      IF jsonb_typeof(item)='string' THEN
        nodes:=nodes||private.owned_entry_content_atom_v1(idiom_path,'idiom',item#>>'{}');
      ELSE
        nodes:=nodes||private.owned_entry_content_atom_v1(idiom_path,'idiom',item->>'expression');
        nodes:=nodes||private.owned_entry_content_atom_v1(idiom_path||'.explanation','idiom-explanation',item->>'explanation',idiom_path);
        FOR child,ci IN SELECT value,(ordinality-1)::integer FROM jsonb_array_elements(COALESCE(item->'examples','[]')) WITH ORDINALITY LOOP
          nodes:=nodes||private.owned_entry_content_atom_v1(idiom_path||'.examples['||ci||']','example',child#>>'{}',idiom_path);
        END LOOP;
      END IF;
    END LOOP;
    IF jsonb_array_length(nodes)>1000 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
  END LOOP;
  nodes:=nodes||private.owned_entry_content_atom_v1('raw.notes','usage-note',p_raw->>'notes');
  IF jsonb_array_length(nodes)>1000 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
  RETURN nodes;
END;
$$;


--
-- Name: pointer_only_dictionary_entry_ids_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.pointer_only_dictionary_entry_ids_v1() RETURNS uuid[]
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    SELECT COALESCE(array_agg(entry.id), ARRAY[]::uuid[])
    FROM public.word_entries AS entry
    WHERE private.is_pointer_only_dictionary_entry_v1(entry.raw);
$$;


--
-- Name: portable_owned_entry_content_v1(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.portable_owned_entry_content_v1(p_raw jsonb, p_overlay_note text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  result jsonb := '{}'::jsonb;
  meanings jsonb := '[]'::jsonb;
  meaning jsonb; normalized jsonb; idiom jsonb; idioms jsonb; key text;
  notes text[] := ARRAY[]::text[];
  definition text;
  alternate jsonb; alternates jsonb; field_value jsonb; nested_value jsonb;
BEGIN
  IF jsonb_typeof(p_raw) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
  IF octet_length(p_raw::text)>1048576 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
  FOREACH key IN ARRAY ARRAY['definition','notes'] LOOP
    IF p_raw ? key AND p_raw->key<>'null'::jsonb AND jsonb_typeof(p_raw->key)<>'string' THEN
      RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
    END IF;
  END LOOP;
  -- An asset URL is not an independent permission or a durable asset snapshot.
  IF p_raw ? 'images' AND p_raw->'images'<>'null'::jsonb AND jsonb_typeof(p_raw->'images')<>'array' THEN
    RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
  END IF;
  IF jsonb_typeof(p_raw->'images')='array' AND jsonb_array_length(p_raw->'images')>0 THEN
    RAISE EXCEPTION 'copy_asset_snapshot_unsupported' USING ERRCODE='22023';
  END IF;
  IF p_raw ? 'meanings' AND jsonb_typeof(p_raw->'meanings')<>'array' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
  IF COALESCE(jsonb_array_length(p_raw->'meanings'),0)>100 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
  FOR meaning IN SELECT value FROM jsonb_array_elements(COALESCE(p_raw->'meanings','[]'::jsonb)) LOOP
    IF jsonb_typeof(meaning)<>'object' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    normalized := '{}'::jsonb;
    FOREACH key IN ARRAY ARRAY['definition','context','pronunciation_note'] LOOP
      IF meaning ? key AND meaning->key<>'null'::jsonb THEN
        IF jsonb_typeof(meaning->key)<>'string' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
        normalized := normalized || jsonb_build_object(key,private.copy_instructional_json_v1(meaning->key));
      END IF;
    END LOOP;
    IF NOT normalized ? 'definition' AND meaning ? 'text' THEN
      IF jsonb_typeof(meaning->'text')<>'string' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
      normalized := normalized || jsonb_build_object('definition',private.copy_instructional_json_v1(meaning->'text'));
    END IF;
    FOREACH key IN ARRAY ARRAY['examples','synonyms','antonyms','usage_labels'] LOOP
      IF meaning ? key THEN normalized := normalized || jsonb_build_object(key,private.copy_text_array_v1(meaning->key)); END IF;
    END LOOP;
    FOREACH key IN ARRAY ARRAY['translations','grammar'] LOOP
      IF meaning ? key AND meaning->key<>'null'::jsonb THEN
        IF jsonb_typeof(meaning->key)<>'object' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
        FOR field_value IN SELECT value FROM jsonb_each(meaning->key) LOOP
          IF jsonb_typeof(field_value)='array' THEN PERFORM private.copy_text_array_v1(field_value);
          ELSIF jsonb_typeof(field_value) NOT IN ('string','boolean','number','null') THEN
            RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
          END IF;
        END LOOP;
        normalized := normalized || jsonb_build_object(key,private.copy_instructional_json_v1(meaning->key));
      END IF;
    END LOOP;
    idioms := '[]'::jsonb;
    IF meaning ? 'idioms' AND jsonb_typeof(meaning->'idioms')<>'array' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    IF COALESCE(jsonb_array_length(meaning->'idioms'),0)>1000 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
    FOR idiom IN SELECT value FROM jsonb_array_elements(COALESCE(meaning->'idioms','[]'::jsonb)) LOOP
      IF jsonb_typeof(idiom)='string' THEN idioms:=idioms||jsonb_build_array(private.copy_instructional_json_v1(idiom));
      ELSIF jsonb_typeof(idiom)='object' AND jsonb_typeof(idiom->'expression')='string' THEN
        IF idiom ? 'explanation' AND idiom->'explanation'<>'null'::jsonb AND jsonb_typeof(idiom->'explanation')<>'string' THEN
          RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
        END IF;
        idioms:=idioms||jsonb_build_array(jsonb_strip_nulls(jsonb_build_object(
          'expression',private.copy_instructional_json_v1(idiom->'expression'),
          'explanation',CASE WHEN idiom ? 'explanation' THEN private.copy_instructional_json_v1(idiom->'explanation') END,
          'examples',private.copy_text_array_v1(idiom->'examples')
        )));
      ELSE RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    END LOOP;
    IF meaning ? 'idioms' THEN normalized:=normalized||jsonb_build_object('idioms',idioms); END IF;
    IF NULLIF(meaning->>'note','') IS NOT NULL THEN
      IF jsonb_typeof(meaning->'note')<>'string' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
      notes:=array_append(notes,meaning->>'note');
    END IF;
    IF meaning ? 'cross_references' AND meaning->'cross_references'<>'null'::jsonb THEN
      IF jsonb_typeof(meaning->'cross_references')<>'array' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
      normalized:=normalized||jsonb_build_object('cross_references',private.copy_instructional_json_v1(
        private.shared_instructional_raw_v1(meaning->'cross_references','reference')));
    END IF;
    meanings:=meanings||jsonb_build_array(normalized);
  END LOOP;

  IF jsonb_array_length(meanings)>0 AND (
     (p_raw ? 'example' AND p_raw->'example'<>'null'::jsonb) OR
     (p_raw ? 'translation' AND p_raw->'translation'<>'null'::jsonb)) THEN
    normalized:=private.portable_owned_entry_content_v1(jsonb_strip_nulls(jsonb_build_object(
      'example',p_raw->'example','translation',p_raw->'translation')));
    result:=result||(normalized-'meanings');
  END IF;
  IF jsonb_array_length(meanings)>0 AND NOT EXISTS(SELECT 1 FROM unnest(notes) item WHERE NULLIF(trim(item),'') IS NOT NULL)
     AND jsonb_array_length(private.platform_v2_user_entry_content_nodes(jsonb_build_object('meanings',meanings)))=0
     AND (NULLIF(trim(p_raw->>'definition'),'') IS NOT NULL OR
          (p_raw ? 'example' AND p_raw->'example'<>'null'::jsonb)) THEN
    normalized:=private.portable_owned_entry_content_v1(jsonb_strip_nulls(jsonb_build_object(
      'definition',p_raw->'definition','example',p_raw->'example')));
    meanings:=jsonb_set(meanings,'{0}',(meanings->0)||(normalized#>'{meanings,0}'));
    IF normalized ? 'example' THEN result:=result||jsonb_build_object('example',normalized->'example'); END IF;
  END IF;
  IF jsonb_array_length(meanings)=0 THEN
    definition:=COALESCE(NULLIF(p_raw->>'definition',''),NULLIF(p_raw->>'notes',''));
    meaning:=jsonb_strip_nulls(jsonb_build_object('definition',definition));
    IF p_raw ? 'example' AND p_raw->'example'<>'null'::jsonb THEN
      IF jsonb_typeof(p_raw->'example')<>'object' OR jsonb_typeof(p_raw#>'{example,source}')<>'string' THEN
        RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
      END IF;
      IF p_raw#>'{example,translation}' IS NOT NULL AND p_raw#>'{example,translation}'<>'null'::jsonb
         AND jsonb_typeof(p_raw#>'{example,translation}')<>'string' THEN
        RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
      END IF;
      meaning:=meaning||jsonb_build_object('examples',jsonb_build_array(p_raw#>>'{example,source}'));
      result:=result||jsonb_build_object('example',jsonb_strip_nulls(jsonb_build_object(
        'source',private.copy_instructional_json_v1(p_raw#>'{example,source}'),
        'translation',CASE WHEN jsonb_typeof(p_raw#>'{example,translation}')='string' THEN private.copy_instructional_json_v1(p_raw#>'{example,translation}') END)));
    END IF;
    IF p_raw ? 'translation' AND p_raw->'translation'<>'null'::jsonb AND
       (jsonb_typeof(p_raw->'translation')<>'object' OR
        jsonb_typeof(p_raw#>'{translation,text}') IS DISTINCT FROM 'string' OR
        (p_raw#>'{translation,languageCode}' IS NOT NULL AND jsonb_typeof(p_raw#>'{translation,languageCode}') IS DISTINCT FROM 'string')) THEN
      RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023';
    END IF;
    IF jsonb_typeof(p_raw->'translation')='object' AND NULLIF(p_raw#>>'{translation,text}','') IS NOT NULL THEN
      result:=result||jsonb_build_object('translation',jsonb_strip_nulls(jsonb_build_object('languageCode',p_raw#>>'{translation,languageCode}','text',p_raw#>>'{translation,text}')));
      meaning:=meaning||jsonb_build_object('translations',jsonb_build_object(COALESCE(p_raw#>>'{translation,languageCode}','unknown'),p_raw#>>'{translation,text}'));
    END IF;
    meanings:=jsonb_build_array(meaning);
  END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(meanings) item WHERE
    NULLIF(item->>'definition','') IS NOT NULL OR jsonb_array_length(COALESCE(item->'examples','[]'))>0
    OR jsonb_array_length(COALESCE(item->'idioms','[]'))>0 OR item ? 'translations') THEN
    RAISE EXCEPTION 'copy_content_unsupported' USING ERRCODE='22023';
  END IF;
  IF NULLIF(p_raw->>'notes','') IS NOT NULL AND p_raw->>'notes' IS DISTINCT FROM definition THEN
    notes:=array_prepend(p_raw->>'notes',notes);
  END IF;
  IF NULLIF(p_overlay_note,'') IS NOT NULL THEN notes:=array_append(notes,p_overlay_note); END IF;
  result:=result||jsonb_build_object('meanings',meanings);
  IF cardinality(notes)>0 THEN result:=result||jsonb_build_object('notes',array_to_string(notes,E'\n\n')); END IF;
  FOREACH key IN ARRAY ARRAY['plural','diminutive','verb_forms','inflected_form','comparative','superlative','derivations','conjugation_table','pronunciation','pronunciation_ipa','pronunciation_with_stress'] LOOP
    IF p_raw ? key THEN
      field_value:=p_raw->key;
      IF key='conjugation_table' THEN
        IF jsonb_typeof(field_value)<>'object' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
        FOR nested_value IN SELECT value FROM jsonb_each(field_value) LOOP
          IF jsonb_typeof(nested_value)<>'object' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
          FOR alternate IN SELECT value FROM jsonb_each(nested_value) LOOP
            IF jsonb_typeof(alternate)='array' THEN PERFORM private.copy_text_array_v1(alternate);
            ELSIF jsonb_typeof(alternate)<>'string' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
          END LOOP;
        END LOOP;
      ELSIF jsonb_typeof(field_value)='array' THEN PERFORM private.copy_text_array_v1(field_value);
      ELSIF jsonb_typeof(field_value) NOT IN ('string','null') THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
      result:=result||jsonb_build_object(key,private.copy_instructional_json_v1(field_value));
    END IF;
  END LOOP;
  IF p_raw ? 'alternate_headwords' THEN
    IF jsonb_typeof(p_raw->'alternate_headwords')<>'array' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    IF jsonb_array_length(p_raw->'alternate_headwords')>1000 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
    alternates:='[]'::jsonb;
    FOR alternate IN SELECT value FROM jsonb_array_elements(p_raw->'alternate_headwords') LOOP
      IF jsonb_typeof(alternate)='string' THEN alternates:=alternates||jsonb_build_array(private.copy_instructional_json_v1(alternate));
      ELSIF jsonb_typeof(alternate)='object' THEN
        normalized:='{}'::jsonb;
        FOREACH key IN ARRAY ARRAY['headword','gender','plural'] LOOP
          IF alternate ? key THEN
            IF jsonb_typeof(alternate->key)<>'string' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
            normalized:=normalized||jsonb_build_object(key,private.copy_instructional_json_v1(alternate->key));
          END IF;
        END LOOP;
        alternates:=alternates||jsonb_build_array(normalized);
      ELSE RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    END LOOP;
    result:=result||jsonb_build_object('alternate_headwords',alternates);
  END IF;
  IF p_raw ? 'cross_reference' AND p_raw->'cross_reference'<>'null'::jsonb THEN
    IF jsonb_typeof(p_raw->'cross_reference') NOT IN ('string','object') THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    result:=result||jsonb_build_object('cross_reference',private.copy_instructional_json_v1(
      private.shared_instructional_raw_v1(p_raw->'cross_reference','reference')));
  END IF;
  IF p_raw ? 'reference_tables' AND p_raw->'reference_tables'<>'null'::jsonb THEN
    IF jsonb_typeof(p_raw->'reference_tables')<>'array' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    result:=result||jsonb_build_object('reference_tables',private.copy_instructional_json_v1(
      private.shared_instructional_raw_v1(p_raw->'reference_tables','reference-table')));
  END IF;
  IF p_raw ? 'displayPronunciation' AND p_raw->'displayPronunciation'<>'null'::jsonb THEN
    IF jsonb_typeof(p_raw->'displayPronunciation')<>'string' THEN RAISE EXCEPTION 'copy_content_invalid' USING ERRCODE='22023'; END IF;
    result:=result||jsonb_build_object('displayPronunciation',private.copy_instructional_json_v1(p_raw->'displayPronunciation'));
  END IF;
  -- Preserve only the rendered homograph number, never its source container.
  field_value:=COALESCE(NULLIF(p_raw#>'{source_identity,homograph_number}','null'::jsonb),NULLIF(p_raw#>'{_source,homograph_number}','null'::jsonb),p_raw->'homograph_number');
  IF jsonb_typeof(field_value)='number' AND (field_value#>>'{}')::numeric>0
    AND trunc((field_value#>>'{}')::numeric)=(field_value#>>'{}')::numeric THEN
    result:=result||jsonb_build_object('homograph_number',field_value);
  END IF;
  IF octet_length(result::text)>131072 THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;

  IF jsonb_array_length(private.platform_v2_user_entry_content_nodes(result))=0 AND NOT EXISTS(
    SELECT 1 FROM jsonb_array_elements(meanings) AS translated_meaning(content)
    CROSS JOIN LATERAL jsonb_each(COALESCE(translated_meaning.content->'translations','{}')) translated
    WHERE (jsonb_typeof(translated.value)='string' AND NULLIF(trim(translated.value#>>'{}'),'') IS NOT NULL)
       OR (jsonb_typeof(translated.value)='array' AND EXISTS(
         SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(translated.value)='array' THEN translated.value ELSE '[]' END) item
         WHERE NULLIF(trim(item#>>'{}'),'') IS NOT NULL))) THEN
    RAISE EXCEPTION 'copy_content_unsupported' USING ERRCODE='22023';
  END IF;
  RETURN result;
EXCEPTION WHEN SQLSTATE '22023' THEN
  IF SQLERRM='shared_content_unsupported' THEN RAISE EXCEPTION 'copy_content_too_large' USING ERRCODE='22023'; END IF;
  RAISE;
END;
$$;


--
-- Name: prevent_training_membership_identity_update_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_training_membership_identity_update_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF OLD.consumed_at IS NOT NULL THEN RAISE EXCEPTION 'training_session_membership_immutable'; END IF;
    RETURN OLD;
  END IF;
  IF OLD.session_id IS DISTINCT FROM NEW.session_id
     OR OLD.ordinal IS DISTINCT FROM NEW.ordinal
     OR OLD.entry_id IS DISTINCT FROM NEW.entry_id
     OR OLD.card_type_id IS DISTINCT FROM NEW.card_type_id
     OR OLD.queue_source IS DISTINCT FROM NEW.queue_source THEN
    RAISE EXCEPTION 'training_session_membership_immutable';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: prevent_training_session_exercise_membership_identity_update_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.prevent_training_session_exercise_membership_identity_update_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE'
       AND (
           OLD.session_id IS DISTINCT FROM NEW.session_id
           OR OLD.target_id IS DISTINCT FROM NEW.target_id
           OR OLD.ordinal IS DISTINCT FROM NEW.ordinal
           OR OLD.queue_source IS DISTINCT FROM NEW.queue_source
       ) THEN
        RAISE EXCEPTION 'training_exercise_session_membership_immutable';
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: preview_collection_share_v1(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.preview_collection_share_v1(p_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE principal uuid:=(select auth.uid()); root private.collection_sharing_roots%rowtype;
  collection_name text; available boolean; count_entries integer;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF p_code IS NULL OR p_code !~ '^[0-9A-HJKMNP-TV-Z]{26}$' THEN RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501'; END IF;
  SELECT r.* INTO root FROM private.collection_sharing_invitations i
    JOIN private.collection_sharing_roots r ON r.id=i.root_id
    WHERE i.secret_hash=sha256(convert_to(p_code,'UTF8')) AND i.role='viewer' AND r.is_open;
  IF NOT FOUND THEN RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501'; END IF;
  SELECT l.name INTO collection_name FROM public.user_word_lists l WHERE l.id=root.collection_id;
  available:=root.owner_user_id=principal OR EXISTS(SELECT 1 FROM private.shared_collection_ids_v1(principal) scope WHERE scope.root_id=root.id);
  -- Preview counts only offered author entries or dictionary entries the caller
  -- can browse; a closed third-party catalogue contributes no identifying count.
  WITH members AS MATERIALIZED (
    SELECT e.id,e.dictionary_id,e.management_kind FROM public.user_word_list_items item
    JOIN private.active_word_entries e ON e.id=item.word_id WHERE item.list_id=root.collection_id
  ), dictionaries AS MATERIALIZED (
    SELECT d.id,d.kind,d.owner_user_id,public.can_browse_dictionary(principal,d.id) AS readable
    FROM (SELECT DISTINCT dictionary_id FROM members) selected JOIN public.dictionaries d ON d.id=selected.dictionary_id
  ) SELECT count(*)::integer INTO count_entries FROM members e LEFT JOIN dictionaries d ON d.id=e.dictionary_id
  WHERE e.dictionary_id IS NULL OR (d.kind='user' AND d.owner_user_id=root.owner_user_id AND e.management_kind='user') OR d.readable;
  RETURN jsonb_build_object('rootId',root.id,'collectionId',root.collection_id,
    'name',collection_name,'offeredRole','viewer','available',available,'entryCount',count_entries,
    'role',CASE WHEN root.owner_user_id=principal THEN 'owner' WHEN available THEN 'viewer' END);
END;
$_$;


--
-- Name: project_platform_v2_bounded_report_atoms(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.project_platform_v2_bounded_report_atoms(p_user_id uuid, p_entry_id uuid, p_content_revision text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_current_revision text;
    v_total integer;
    v_included integer := 0;
    v_atoms jsonb := '[]'::jsonb;
    v_candidate_atoms jsonb;
    v_atom jsonb;
    v_text text;
    v_truncated boolean;
    v_source record;
BEGIN
    PERFORM public.read_platform_v2_presentation_identity(
        p_user_id,
        ARRAY[p_entry_id],
        false
    );
    v_current_revision := private.platform_v2_report_atom_revision(p_entry_id);
    IF p_content_revision IS DISTINCT FROM v_current_revision THEN
        RAISE EXCEPTION 'stale_report_content_revision';
    END IF;
    SELECT count(*)::integer INTO v_total
    FROM private.platform_v2_report_atom_source(p_entry_id);

    FOR v_source IN
        SELECT *
        FROM private.platform_v2_report_atom_source(p_entry_id)
        ORDER BY atom_order
    LOOP
        EXIT WHEN v_included >= 32;
        v_text := substring(normalize(v_source.source_text, NFC) FROM 1 FOR 1500);
        v_truncated := v_text IS DISTINCT FROM normalize(v_source.source_text, NFC);
        v_atom := jsonb_build_object(
            'role', v_source.role,
            'contentNodeId', v_source.content_node_id,
            'text', v_text,
            'truncated', v_truncated
        );
        v_candidate_atoms := v_atoms || jsonb_build_array(v_atom);
        EXIT WHEN octet_length(convert_to(
            private.platform_v2_report_card_content_canonical(
                v_candidate_atoms,
                v_total - (v_included + 1)
            ),
            'UTF8'
        )) > 49152;
        v_atoms := v_candidate_atoms;
        v_included := v_included + 1;
    END LOOP;

    RETURN jsonb_build_object(
        'atoms', v_atoms,
        'omittedAtomCount', v_total - v_included
    );
END;
$$;


--
-- Name: project_training_scheduler_candidate_v1(uuid, uuid, text, text, jsonb, boolean, bigint, bigint, bigint, bigint, bigint); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.project_training_scheduler_candidate_v1(p_user_id uuid, p_entry_id uuid, p_card_type_id text, p_queue_source text, p_training_filter jsonb, p_filtered boolean, p_new_today bigint, p_daily_new_limit bigint, p_new_pool_size bigint, p_learning_due_count bigint, p_review_pool_size bigint) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
SELECT jsonb_build_object(
  'id',entry.id,'dictionary_id',entry.dictionary_id,'language_code',entry.language_code,
  'headword',entry.headword,'part_of_speech',entry.part_of_speech,'gender',entry.gender,
  'raw',CASE WHEN EXISTS(SELECT 1 FROM public.dictionaries dictionary
    WHERE dictionary.id=entry.dictionary_id AND dictionary.kind='user' AND dictionary.owner_user_id IS DISTINCT FROM p_user_id)
    THEN private.shared_instructional_raw_v1(entry.raw) ELSE entry.raw END,(public.dictionary_source_settings_v1()->>'sourceRankKey'), entry.source_rank,'is_nt2_2000',entry.is_nt2_2000,
  'meanings_count',(SELECT count(*) FROM private.active_word_entries sibling
    WHERE sibling.headword=entry.headword AND private.entry_access_v1(p_user_id,sibling.id,'train') AND sibling.language_code=entry.language_code
      AND ((entry.dictionary_id IS NULL AND sibling.dictionary_id IS NULL)
        OR sibling.dictionary_id=entry.dictionary_id)),
  'mode',p_card_type_id,
  'stats',jsonb_build_object(
    'source',p_queue_source,'mode',p_card_type_id,'next_review',status.next_review_at,
    'interval',status.fsrs_last_interval,'reps',status.fsrs_reps,
    'stability',status.fsrs_stability,'difficulty',status.fsrs_difficulty,
    'clicks',status.click_count,'new_today',p_new_today,
    'daily_new_limit',p_daily_new_limit,'new_pool_size',p_new_pool_size,
    'learning_due_count',p_learning_due_count,'review_pool_size',p_review_pool_size,
    'reason',CASE WHEN p_filtered THEN 'filtered' ELSE p_queue_source END
  ) || CASE WHEN p_filtered
    THEN jsonb_build_object('training_filter',COALESCE(p_training_filter,'{}'))
    ELSE '{}'::jsonb END
)
FROM private.active_word_entries entry
LEFT JOIN user_card_status status ON status.user_id=p_user_id
  AND status.entry_id=entry.id AND status.card_type_id=p_card_type_id
WHERE entry.id=p_entry_id AND private.entry_access_v1(p_user_id,entry.id,'train');
$$;


--
-- Name: read_collection_share_command_core_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_collection_share_command_core_v1(p_operation_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
 SELECT private.collection_share_command_response_v1(private.read_collection_share_receipt_v1(p_operation_id))
$$;


--
-- Name: read_collection_share_owner_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_collection_share_owner_v1(p_collection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); root_id uuid;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.user_word_lists l WHERE l.id=p_collection_id AND l.user_id=principal) THEN
    RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501';
  END IF;
  SELECT r.id INTO root_id FROM private.collection_sharing_roots r WHERE r.collection_id=p_collection_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('collectionId',p_collection_id,'rootId',NULL,
    'isOpen',false,'revision',0,'invitationCode',NULL,'available',true,'role','owner'); END IF;
  RETURN private.collection_share_projection_v1(principal,jsonb_build_object('rootId',root_id,'collectionId',p_collection_id));
END;
$$;


--
-- Name: read_collection_share_receipt_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_collection_share_receipt_v1(p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); facts jsonb;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF p_operation_id IS NULL THEN RAISE EXCEPTION 'invalid_share_command' USING ERRCODE='22023'; END IF;
  SELECT r.response INTO facts FROM private.collection_sharing_command_receipts r
    WHERE r.user_id=principal AND r.operation_id=p_operation_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('operationId',p_operation_id,'status','unknown'); END IF;
  RETURN private.collection_share_projection_v1(principal,facts);
END;
$$;


--
-- Name: read_platform_v2_content_node_bindings(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_platform_v2_content_node_bindings(p_entry_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'contentNodeId', node.id,
                'sourcePath', node.diagnostic_locator,
                'kind', node.kind,
                'parentContentNodeId', node.parent_content_node_id,
                'sourceTextFingerprint', node.source_text_fingerprint
            )
            ORDER BY node.created_at, node.id
        ),
        '[]'::jsonb
    )
    FROM private.platform_v2_content_nodes AS node
    WHERE node.entry_id = p_entry_id
      AND node.binding_state = 'active';
$$;


--
-- Name: read_platform_v2_library_group_base_v1(uuid, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_platform_v2_library_group_base_v1(p_user_id uuid, p_entry_id uuid, p_group_entry_bound integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_group_id uuid;
    v_entry_count integer;
    v_items jsonb;
BEGIN
    IF p_user_id IS NULL OR p_entry_id IS NULL THEN
        RETURN jsonb_build_object('error', 'entry_not_accessible');
    END IF;

    SELECT COALESCE(source_group.id, user_group.id)
    INTO v_group_id
    FROM private.active_word_entries AS entry
    JOIN public.dictionaries AS dictionary
      ON dictionary.id = entry.dictionary_id
    LEFT JOIN private.source_entry_bindings AS binding
      ON binding.word_entry_id = entry.id
     AND binding.binding_state = 'active'
    LEFT JOIN private.platform_v2_headword_groups AS source_group
      ON source_group.management_kind = 'source'
     AND source_group.dictionary_id = binding.dictionary_id
     AND source_group.identity_scheme_version = binding.identity_scheme_version
     AND source_group.source_group_key = binding.source_group_key
    LEFT JOIN private.platform_v2_headword_groups AS user_group
      ON user_group.management_kind = 'user'
     AND user_group.singleton_entry_id = entry.id
    WHERE entry.id=p_entry_id AND private.entry_access_v1(p_user_id,entry.id,'browse');

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'entry_not_accessible');
    END IF;
    IF v_group_id IS NULL THEN
        RETURN jsonb_build_object(
            'error',
            'presentation_identity_incomplete'
        );
    END IF;

    WITH group_members AS MATERIALIZED (
        SELECT
            entry.*,
            dictionary AS dictionary_record,
            binding.sense_ordinal AS presentation_ordinal
        FROM private.platform_v2_headword_groups AS headword_group
        JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.binding_state = 'active'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
        JOIN private.active_word_entries AS entry
          ON entry.id = binding.word_entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
        WHERE headword_group.id = v_group_id AND private.entry_access_v1(p_user_id,entry.id,'browse')

        UNION ALL

        SELECT
            entry.*,
            dictionary AS dictionary_record,
            entry.meaning_id AS presentation_ordinal
        FROM private.platform_v2_headword_groups AS headword_group
        JOIN private.active_word_entries AS entry
          ON headword_group.management_kind = 'user'
         AND entry.id = headword_group.singleton_entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
        WHERE headword_group.id = v_group_id AND private.entry_access_v1(p_user_id,entry.id,'browse')
    )
    SELECT
        count(*),
        jsonb_agg(
            private.entry_payload_for_reader_v1(p_user_id,to_jsonb(group_members))
                - 'dictionary_record'
                - 'presentation_ordinal'
                || jsonb_build_object(
                    'dictionary',
                    private.dictionary_metadata_for_entry_read_v1(p_user_id,group_members.dictionary_record)
                )
            ORDER BY group_members.presentation_ordinal, group_members.id
        )
    INTO v_entry_count, v_items
    FROM group_members;

    IF v_entry_count = 0
       OR NOT EXISTS (
           SELECT 1
           FROM jsonb_array_elements(COALESCE(v_items, '[]'::jsonb)) AS item
           WHERE item->>'id' = p_entry_id::text
       ) THEN
        RETURN jsonb_build_object(
            'error',
            'presentation_identity_incomplete'
        );
    END IF;
    IF v_entry_count > v_group_entry_bound THEN
        RETURN jsonb_build_object(
            'error',
            'group-too-large',
            'entryCount',
            v_entry_count,
            'entryBound',
            v_group_entry_bound
        );
    END IF;

    RETURN jsonb_build_object(
        'items',
        v_items,
        'page',
        jsonb_build_object(
            'selectedTierComplete',
            true,
            'nextGroupCursor',
            NULL
        )
    );
END;
$$;


--
-- Name: read_platform_v2_presentation_identity_report_base_v1(uuid, uuid[], boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_platform_v2_presentation_identity_report_base_v1(p_user_id uuid, p_entry_ids uuid[], p_catalog boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_requested_count integer;
    v_visible_count integer;
    v_identity_count integer;
    v_entries jsonb;
BEGIN
    IF p_entry_ids IS NULL
       OR cardinality(p_entry_ids) = 0 THEN
        RETURN jsonb_build_object('entries', '[]'::jsonb);
    END IF;

    IF p_catalog AND p_user_id IS NOT NULL THEN
        RAISE EXCEPTION 'platform_v2_invalid_principal';
    END IF;
    IF NOT p_catalog AND p_user_id IS NULL THEN
        RAISE EXCEPTION 'platform_v2_invalid_principal';
    END IF;

    SELECT count(DISTINCT requested.entry_id)
    INTO v_requested_count
    FROM unnest(p_entry_ids) AS requested(entry_id);

    SELECT count(DISTINCT entry.id)
    INTO v_visible_count
    FROM unnest(p_entry_ids) AS requested(entry_id)
    JOIN private.active_word_entries AS entry
      ON entry.id = requested.entry_id
    JOIN public.dictionaries AS dictionary
      ON dictionary.id = entry.dictionary_id
    WHERE (
        p_catalog
        AND dictionary.kind <> 'user'
        AND dictionary.visibility IN ('system', 'public')
    )
    OR (NOT p_catalog AND private.entry_access_v1(p_user_id,entry.id,'browse'));

    IF v_visible_count <> v_requested_count THEN
        RAISE EXCEPTION 'platform_v2_entry_not_accessible';
    END IF;

    WITH requested AS (
        SELECT entry_id, ordinal
        FROM unnest(p_entry_ids) WITH ORDINALITY
            AS requested(entry_id, ordinal)
    ),
    resolved AS (
        SELECT
            requested.ordinal,
            entry.id AS entry_id,
            COALESCE(source_group.id, user_group.id) AS headword_group_id,
            COALESCE(binding.sense_ordinal, entry.meaning_id) AS meaning_ordinal
        FROM requested
        JOIN private.active_word_entries AS entry
          ON entry.id = requested.entry_id
        LEFT JOIN private.source_entry_bindings AS binding
          ON binding.word_entry_id = entry.id
         AND binding.binding_state = 'active'
        LEFT JOIN private.platform_v2_headword_groups AS source_group
          ON source_group.management_kind = 'source'
         AND source_group.dictionary_id = binding.dictionary_id
         AND source_group.identity_scheme_version =
             binding.identity_scheme_version
         AND source_group.source_group_key = binding.source_group_key
        LEFT JOIN private.platform_v2_headword_groups AS user_group
          ON user_group.management_kind = 'user'
         AND user_group.singleton_entry_id = entry.id
    )
    SELECT
        count(*) FILTER (WHERE headword_group_id IS NOT NULL),
        jsonb_agg(
            jsonb_build_object(
                'entryId', entry_id,
                'headwordGroupId', headword_group_id,
                'meaningOrdinal', meaning_ordinal,
                'contentNodeBindings',
                    private.read_platform_v2_content_node_bindings(entry_id)
            )
            ORDER BY ordinal
        )
    INTO v_identity_count, v_entries
    FROM resolved;

    IF v_identity_count <> cardinality(p_entry_ids) THEN
        RAISE EXCEPTION 'platform_v2_identity_missing';
    END IF;

    RETURN jsonb_build_object('entries', COALESCE(v_entries, '[]'::jsonb));
END;
$$;


--
-- Name: read_platform_v2_training_group_base_v1(uuid, uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_platform_v2_training_group_base_v1(p_user_id uuid, p_entry_id uuid, p_group_entry_bound integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_group_entry_bound integer :=
        LEAST(GREATEST(COALESCE(p_group_entry_bound, 50), 1), 100);
    v_group_id uuid;
    v_entry_count integer;
    v_items jsonb;
BEGIN
    IF p_user_id IS NULL OR p_entry_id IS NULL THEN
        RETURN jsonb_build_object('error', 'entry_not_accessible');
    END IF;

    SELECT COALESCE(source_group.id, user_group.id)
    INTO v_group_id
    FROM private.active_word_entries AS entry
    JOIN public.dictionaries AS dictionary
      ON dictionary.id = entry.dictionary_id
    LEFT JOIN private.source_entry_bindings AS binding
      ON binding.word_entry_id = entry.id
     AND binding.binding_state = 'active'
    LEFT JOIN private.platform_v2_headword_groups AS source_group
      ON source_group.management_kind = 'source'
     AND source_group.dictionary_id = binding.dictionary_id
     AND source_group.identity_scheme_version = binding.identity_scheme_version
     AND source_group.source_group_key = binding.source_group_key
    LEFT JOIN private.platform_v2_headword_groups AS user_group
      ON user_group.management_kind = 'user'
     AND user_group.singleton_entry_id = entry.id
    WHERE entry.id=p_entry_id AND private.entry_access_v1(p_user_id,entry.id,'train');

    IF NOT FOUND THEN
        RETURN jsonb_build_object('error', 'entry_not_accessible');
    END IF;
    IF v_group_id IS NULL THEN
        RETURN jsonb_build_object(
            'error',
            'presentation_identity_incomplete'
        );
    END IF;

    WITH group_members AS MATERIALIZED (
        SELECT
            entry.*,
            dictionary AS dictionary_record,
            binding.sense_ordinal AS presentation_ordinal
        FROM private.platform_v2_headword_groups AS headword_group
        JOIN private.source_entry_bindings AS binding
          ON headword_group.management_kind = 'source'
         AND binding.binding_state = 'active'
         AND binding.dictionary_id = headword_group.dictionary_id
         AND binding.identity_scheme_version =
             headword_group.identity_scheme_version
         AND binding.source_group_key = headword_group.source_group_key
        JOIN private.active_word_entries AS entry
          ON entry.id = binding.word_entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
        WHERE headword_group.id = v_group_id AND private.entry_access_v1(p_user_id,entry.id,'train')

        UNION ALL

        SELECT
            entry.*,
            dictionary AS dictionary_record,
            entry.meaning_id AS presentation_ordinal
        FROM private.platform_v2_headword_groups AS headword_group
        JOIN private.active_word_entries AS entry
          ON headword_group.management_kind = 'user'
         AND entry.id = headword_group.singleton_entry_id
        JOIN public.dictionaries AS dictionary
          ON dictionary.id = entry.dictionary_id
        WHERE headword_group.id = v_group_id AND private.entry_access_v1(p_user_id,entry.id,'train')
    )
    SELECT
        count(*),
        jsonb_agg(
            private.entry_payload_for_reader_v1(p_user_id,to_jsonb(group_members))
                - 'dictionary_record'
                - 'presentation_ordinal'
                || jsonb_build_object(
                    'dictionary',
                    private.dictionary_metadata_for_entry_read_v1(p_user_id,group_members.dictionary_record)
                )
            ORDER BY group_members.presentation_ordinal, group_members.id
        )
    INTO v_entry_count, v_items
    FROM group_members;

    IF v_entry_count = 0
       OR NOT EXISTS (
           SELECT 1
           FROM jsonb_array_elements(COALESCE(v_items, '[]'::jsonb)) AS item
           WHERE item->>'id' = p_entry_id::text
       ) THEN
        RETURN jsonb_build_object(
            'error',
            'presentation_identity_incomplete'
        );
    END IF;
    IF v_entry_count > v_group_entry_bound THEN
        RETURN jsonb_build_object(
            'error',
            'group-too-large',
            'entryCount',
            v_entry_count,
            'entryBound',
            v_group_entry_bound
        );
    END IF;

    RETURN jsonb_build_object(
        'items',
        v_items,
        'page',
        jsonb_build_object(
            'selectedTierComplete',
            true,
            'nextGroupCursor',
            NULL
        )
    );
END;
$$;


--
-- Name: read_received_collection_page_v1(uuid, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.read_received_collection_page_v1(p_after uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid());
BEGIN
 IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF p_limit IS NULL OR p_limit NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'invalid_catalog_request' USING ERRCODE='22023'; END IF;
 RETURN (
  WITH candidates AS MATERIALIZED (
   SELECT l.id,l.name,l.created_at,s.owner_user_id FROM private.live_collection_sharing_subscriptions_v1 s
   JOIN public.user_word_lists l ON l.id=s.collection_id
   WHERE s.user_id=principal AND s.owner_user_id<>principal AND (p_after IS NULL OR l.id>p_after)
   ORDER BY l.id LIMIT p_limit+1
  ), page AS MATERIALIZED (SELECT * FROM candidates ORDER BY id LIMIT p_limit),
  members AS MATERIALIZED (
   SELECT page.id AS collection_id,entry.id,entry.dictionary_id FROM page
   JOIN public.user_word_list_items item ON item.list_id=page.id
   JOIN private.active_word_entries entry ON entry.id=item.word_id
  ), dictionaries AS MATERIALIZED (
   SELECT dictionary.id,dictionary.kind,dictionary.owner_user_id,
    CASE WHEN dictionary.kind<>'user' THEN public.can_browse_dictionary(principal,dictionary.id) ELSE false END AS readable
   FROM (SELECT DISTINCT dictionary_id FROM members) selected JOIN public.dictionaries dictionary ON dictionary.id=selected.dictionary_id
  ), shared AS MATERIALIZED (
   SELECT DISTINCT granted.entry_id FROM private.shared_author_entry_memberships_v1 granted
   WHERE granted.user_id=principal AND granted.entry_id IN(SELECT id FROM members)
  ), counts AS MATERIALIZED (
   SELECT member.collection_id,count(*) AS item_count FROM members member LEFT JOIN dictionaries dictionary ON dictionary.id=member.dictionary_id
   WHERE member.dictionary_id IS NULL OR dictionary.readable OR
    (dictionary.kind='user' AND (dictionary.owner_user_id=principal OR member.id IN(SELECT entry_id FROM shared)))
   GROUP BY member.collection_id
  )
  SELECT jsonb_build_object('revision',COALESCE((SELECT revision FROM private.collection_label_catalogs WHERE user_id=principal),0),
   'collections',COALESCE((SELECT jsonb_agg(jsonb_build_object(
    'id',page.id,'name',page.name,'createdAt',page.created_at,'ownerUserId',page.owner_user_id,'role','viewer',
    'itemCount',COALESCE((SELECT item_count FROM counts WHERE collection_id=page.id),0),
    'labelIds',COALESCE((SELECT jsonb_agg(label_id ORDER BY label_id) FROM private.received_collection_label_placements placement
      WHERE placement.user_id=principal AND placement.collection_id=page.id),'[]'::jsonb)
   ) ORDER BY page.id) FROM page),'[]'::jsonb),
   'nextCursor',CASE WHEN (SELECT count(*) FROM candidates)>p_limit THEN (SELECT id FROM page ORDER BY id DESC LIMIT 1) ELSE NULL END)
 );
END;
$$;


--
-- Name: readable_material_entry_ids_v1(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.readable_material_entry_ids_v1(p_user_id uuid, p_material jsonb) RETURNS TABLE(entry_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  WITH members AS MATERIALIZED (
    SELECT entry.id,entry.dictionary_id FROM private.library_material_entry_ids_v1(p_user_id,p_material) member
    JOIN private.active_word_entries entry ON entry.id=member.entry_id
  ), dictionaries AS MATERIALIZED (
    SELECT dictionary.id,dictionary.kind,dictionary.owner_user_id,
      CASE WHEN dictionary.kind<>'user' THEN public.can_browse_dictionary(p_user_id,dictionary.id) ELSE false END AS readable
    FROM (SELECT DISTINCT dictionary_id FROM members) selected
    JOIN public.dictionaries dictionary ON dictionary.id=selected.dictionary_id
  ), shared AS MATERIALIZED (
    SELECT DISTINCT grant_entry.entry_id FROM private.shared_author_entry_memberships_v1 grant_entry
    JOIN members ON members.id=grant_entry.entry_id WHERE grant_entry.user_id=p_user_id
  )
  SELECT member.id FROM members member LEFT JOIN dictionaries dictionary ON dictionary.id=member.dictionary_id
  WHERE member.dictionary_id IS NULL OR dictionary.readable
    OR (dictionary.kind='user' AND (dictionary.owner_user_id=p_user_id OR member.id IN (SELECT entry_id FROM shared)))
$$;


--
-- Name: received_collection_training_available_v1(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.received_collection_training_available_v1(p_user_id uuid, p_list_id uuid, p_language_code text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
 SELECT EXISTS(
  SELECT 1 FROM private.live_collection_sharing_subscriptions_v1 scope
  WHERE scope.user_id=p_user_id AND scope.collection_id=p_list_id AND scope.owner_user_id<>p_user_id
   AND EXISTS(SELECT 1 FROM public.user_word_list_items item
    JOIN private.active_word_entries entry ON entry.id=item.word_id
    WHERE item.list_id=scope.collection_id AND entry.language_code=p_language_code
     AND private.entry_access_v1(p_user_id,entry.id,'train'))
 )
$$;


--
-- Name: reconcile_platform_v2_content_nodes(uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reconcile_platform_v2_content_nodes(p_entry_id uuid, p_source_revision text, p_nodes jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    IF jsonb_typeof(p_nodes) IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'platform_v2_invalid_content_nodes';
    END IF;
    IF EXISTS (
        SELECT 1
        FROM jsonb_array_elements(p_nodes) AS node(value)
        WHERE node.value ? 'sourceText'
          AND (
              jsonb_typeof(node.value->'sourceText') IS DISTINCT FROM 'string'
              OR NULLIF(trim(node.value->>'sourceText'), '') IS NULL
          )
    ) THEN
        RAISE EXCEPTION 'platform_v2_invalid_content_node_text';
    END IF;

    v_result := private.reconcile_platform_v2_content_nodes_identity_v1(
        p_entry_id,
        p_source_revision,
        p_nodes
    );

    UPDATE private.platform_v2_content_nodes
    SET source_order = NULL,
        updated_at = now()
    WHERE entry_id = p_entry_id
      AND binding_state = 'active';

    WITH incoming AS (
        SELECT
            node.ordinality::integer AS source_order,
            node.value->>'inputKey' AS input_key,
            CASE
                WHEN node.value ? 'sourceText'
                    THEN normalize(trim(node.value->>'sourceText'), NFC)
                ELSE NULL
            END AS source_text
        FROM jsonb_array_elements(p_nodes) WITH ORDINALITY AS node(value, ordinality)
    ), resolved AS (
        SELECT
            (result_node.value->>'contentNodeId')::uuid AS content_node_id,
            incoming.source_order,
            incoming.source_text
        FROM jsonb_array_elements(v_result->'nodes') AS result_node(value)
        JOIN incoming
          ON incoming.input_key = result_node.value->>'inputKey'
    )
    UPDATE private.platform_v2_content_nodes AS node
    SET canonical_source_text = resolved.source_text,
        source_order = resolved.source_order,
        updated_at = now()
    FROM resolved
    WHERE node.id = resolved.content_node_id;

    RETURN v_result;
END;
$$;


--
-- Name: reconcile_platform_v2_content_nodes_identity_v1(uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reconcile_platform_v2_content_nodes_identity_v1(p_entry_id uuid, p_source_revision text, p_nodes jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_node record;
    v_existing_id uuid;
    v_candidate_count integer;
    v_parent_id uuid;
    v_decision text;
    v_result jsonb;
BEGIN
    IF NOT EXISTS (
        SELECT 1
        FROM public.word_entries
        WHERE id = p_entry_id
    ) THEN
        RAISE EXCEPTION 'platform_v2_entry_not_found';
    END IF;
    IF NULLIF(trim(p_source_revision), '') IS NULL
       OR jsonb_typeof(p_nodes) <> 'array' THEN
        RAISE EXCEPTION 'platform_v2_invalid_content_nodes';
    END IF;

    CREATE TEMP TABLE IF NOT EXISTS pg_temp.platform_v2_incoming_nodes (
        sequence_number integer NOT NULL,
        input_key text PRIMARY KEY,
        kind text NOT NULL,
        source_path text NOT NULL,
        source_native_key text,
        source_text_fingerprint text NOT NULL,
        parent_input_key text,
        content_node_id uuid,
        decision text
    ) ON COMMIT DROP;
    TRUNCATE pg_temp.platform_v2_incoming_nodes;

    INSERT INTO pg_temp.platform_v2_incoming_nodes (
        sequence_number,
        input_key,
        kind,
        source_path,
        source_native_key,
        source_text_fingerprint,
        parent_input_key
    )
    SELECT
        node.ordinality::integer,
        NULLIF(trim(node.value->>'inputKey'), ''),
        NULLIF(trim(node.value->>'kind'), ''),
        NULLIF(trim(node.value->>'sourcePath'), ''),
        NULLIF(trim(node.value->>'sourceNativeKey'), ''),
        NULLIF(trim(node.value->>'sourceTextFingerprint'), ''),
        NULLIF(trim(node.value->>'parentInputKey'), '')
    FROM jsonb_array_elements(p_nodes) WITH ORDINALITY AS node(value, ordinality);

    IF EXISTS (
        SELECT 1
        FROM pg_temp.platform_v2_incoming_nodes
        WHERE input_key IS NULL
           OR source_path IS NULL
           OR source_text_fingerprint IS NULL
           OR kind NOT IN (
                'definition',
                'usage-pattern',
                'example',
                'idiom',
                'idiom-explanation',
                'usage-note'
           )
    ) THEN
        RAISE EXCEPTION 'platform_v2_invalid_content_node';
    END IF;

    IF EXISTS (
        SELECT 1
        FROM pg_temp.platform_v2_incoming_nodes
        WHERE source_native_key IS NOT NULL
        GROUP BY kind, source_native_key
        HAVING count(*) > 1
    ) THEN
        RAISE EXCEPTION 'platform_v2_duplicate_native_content_identity';
    END IF;

    FOR v_node IN
        SELECT *
        FROM pg_temp.platform_v2_incoming_nodes
        ORDER BY sequence_number
    LOOP
        v_existing_id := NULL;
        v_candidate_count := 0;

        IF v_node.source_native_key IS NOT NULL THEN
            SELECT id
            INTO v_existing_id
            FROM private.platform_v2_content_nodes
            WHERE entry_id = p_entry_id
              AND kind = v_node.kind
              AND source_native_key = v_node.source_native_key;
            v_decision := CASE
                WHEN v_existing_id IS NULL THEN 'new-native'
                ELSE 'preserve-native'
            END;
        ELSE
            SELECT count(*), min(id::text)::uuid
            INTO v_candidate_count, v_existing_id
            FROM private.platform_v2_content_nodes
            WHERE entry_id = p_entry_id
              AND kind = v_node.kind
              AND source_native_key IS NULL
              AND source_text_fingerprint =
                  v_node.source_text_fingerprint
              AND binding_state = 'active'
              AND id NOT IN (
                  SELECT content_node_id
                  FROM pg_temp.platform_v2_incoming_nodes
                  WHERE content_node_id IS NOT NULL
              );

            IF (
                SELECT count(*)
                FROM pg_temp.platform_v2_incoming_nodes
                WHERE kind = v_node.kind
                  AND source_native_key IS NULL
                  AND source_text_fingerprint =
                      v_node.source_text_fingerprint
            ) > 1 THEN
                v_existing_id := NULL;
                v_decision := 'new-ambiguous-duplicate';
            ELSIF v_candidate_count = 1 THEN
                v_decision := 'preserve-unambiguous-fingerprint';
            ELSE
                v_existing_id := NULL;
                v_decision := CASE
                    WHEN v_candidate_count > 1
                        THEN 'new-ambiguous-existing'
                    ELSE 'new-unmatched'
                END;
            END IF;
        END IF;

        IF v_existing_id IS NULL THEN
            INSERT INTO private.platform_v2_content_nodes (
                entry_id,
                kind,
                binding_state,
                first_source_revision,
                last_source_revision,
                source_native_key,
                source_text_fingerprint,
                diagnostic_locator,
                identity_evidence,
                reconciliation_decision
            )
            VALUES (
                p_entry_id,
                v_node.kind,
                'active',
                p_source_revision,
                p_source_revision,
                v_node.source_native_key,
                v_node.source_text_fingerprint,
                v_node.source_path,
                jsonb_strip_nulls(jsonb_build_object(
                    'sourceNativeKey', v_node.source_native_key,
                    'sourceTextFingerprint',
                        v_node.source_text_fingerprint
                )),
                jsonb_build_object('decision', v_decision)
            )
            RETURNING id INTO v_existing_id;
        ELSE
            UPDATE private.platform_v2_content_nodes
            SET binding_state = 'active',
                last_source_revision = p_source_revision,
                source_text_fingerprint =
                    v_node.source_text_fingerprint,
                diagnostic_locator = v_node.source_path,
                reconciliation_decision =
                    jsonb_build_object('decision', v_decision),
                updated_at = now()
            WHERE id = v_existing_id;
        END IF;

        UPDATE pg_temp.platform_v2_incoming_nodes
        SET content_node_id = v_existing_id,
            decision = v_decision
        WHERE input_key = v_node.input_key;
    END LOOP;

    FOR v_node IN
        SELECT *
        FROM pg_temp.platform_v2_incoming_nodes
    LOOP
        v_parent_id := NULL;
        IF v_node.parent_input_key IS NOT NULL THEN
            SELECT content_node_id
            INTO v_parent_id
            FROM pg_temp.platform_v2_incoming_nodes
            WHERE input_key = v_node.parent_input_key;

            IF v_parent_id IS NULL THEN
                RAISE EXCEPTION 'platform_v2_content_node_parent_not_found';
            END IF;
        END IF;

        UPDATE private.platform_v2_content_nodes
        SET parent_content_node_id = v_parent_id,
            updated_at = now()
        WHERE id = v_node.content_node_id;
    END LOOP;

    UPDATE private.platform_v2_content_nodes
    SET binding_state = 'retired',
        last_source_revision = p_source_revision,
        reconciliation_decision =
            jsonb_build_object('decision', 'retire-missing'),
        updated_at = now()
    WHERE entry_id = p_entry_id
      AND binding_state = 'active'
      AND id NOT IN (
          SELECT content_node_id
          FROM pg_temp.platform_v2_incoming_nodes
      );

    SELECT jsonb_build_object(
        'entryId', p_entry_id,
        'sourceRevision', p_source_revision,
        'nodes',
        COALESCE(
            jsonb_agg(
                jsonb_build_object(
                    'inputKey', input_key,
                    'contentNodeId', content_node_id,
                    'decision', decision
                )
                ORDER BY sequence_number
            ),
            '[]'::jsonb
        )
    )
    INTO v_result
    FROM pg_temp.platform_v2_incoming_nodes;

    RETURN v_result;
END;
$$;


--
-- Name: reconcile_platform_v2_source_batch_v1(jsonb, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reconcile_platform_v2_source_batch_v1(p_rows jsonb, p_drain_after_batch boolean DEFAULT true) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_row record;
  v_owns_import boolean := false;
BEGIN
  IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_rows) = 0
     OR jsonb_array_length(p_rows) > 500 THEN
    RAISE EXCEPTION 'platform_v2_invalid_source_batch';
  END IF;

  IF to_regclass('pg_temp.platform_v2_import_refresh_entries') IS NULL THEN
    PERFORM private.begin_platform_v2_source_import_v1();
    v_owns_import := true;
  END IF;

  CREATE TEMP TABLE pg_temp.platform_v2_import_source_rows (
    dictionary_id uuid NOT NULL,
    identity_scheme_version text NOT NULL,
    source_entry_key text NOT NULL,
    source_group_key text NOT NULL,
    sense_ordinal integer NOT NULL,
    word_entry_id uuid NOT NULL,
    run_id uuid NOT NULL,
    manifest_checksum text NOT NULL,
    content_fingerprint_version text NOT NULL,
    content_fingerprint text NOT NULL,
    identity_evidence jsonb NOT NULL,
    reconciliation_decision jsonb NOT NULL,
    nodes jsonb NOT NULL
  ) ON COMMIT DROP;

  INSERT INTO pg_temp.platform_v2_import_source_rows
  SELECT *
  FROM jsonb_to_recordset(p_rows) AS source(
    dictionary_id uuid,
    identity_scheme_version text,
    source_entry_key text,
    source_group_key text,
    sense_ordinal integer,
    word_entry_id uuid,
    run_id uuid,
    manifest_checksum text,
    content_fingerprint_version text,
    content_fingerprint text,
    identity_evidence jsonb,
    reconciliation_decision jsonb,
    nodes jsonb
  );

  INSERT INTO private.source_entry_bindings (
    dictionary_id,
    identity_scheme_version,
    source_entry_key,
    source_group_key,
    sense_ordinal,
    word_entry_id,
    binding_state,
    first_seen_run_id,
    last_seen_run_id,
    manifest_checksum,
    content_fingerprint_version,
    content_fingerprint,
    identity_evidence,
    reconciliation_decision
  )
  SELECT source.dictionary_id,
         source.identity_scheme_version,
         source.source_entry_key,
         source.source_group_key,
         source.sense_ordinal,
         source.word_entry_id,
         'active',
         source.run_id,
         source.run_id,
         source.manifest_checksum,
         source.content_fingerprint_version,
         source.content_fingerprint,
         source.identity_evidence,
         source.reconciliation_decision
  FROM pg_temp.platform_v2_import_source_rows AS source
  ON CONFLICT (
    dictionary_id, identity_scheme_version, source_entry_key
  ) DO UPDATE SET
    source_group_key = excluded.source_group_key,
    sense_ordinal = excluded.sense_ordinal,
    word_entry_id = excluded.word_entry_id,
    binding_state = 'active',
    last_seen_run_id = excluded.last_seen_run_id,
    manifest_checksum = excluded.manifest_checksum,
    content_fingerprint_version = excluded.content_fingerprint_version,
    content_fingerprint = excluded.content_fingerprint,
    identity_evidence = excluded.identity_evidence,
    reconciliation_decision = excluded.reconciliation_decision,
    updated_at = now();

  FOR v_row IN
    SELECT source.word_entry_id,
           source.manifest_checksum,
           source.nodes
    FROM pg_temp.platform_v2_import_source_rows AS source
  LOOP
    PERFORM private.reconcile_platform_v2_content_nodes(
      v_row.word_entry_id,
      v_row.manifest_checksum,
      v_row.nodes
    );
  END LOOP;

  DROP TABLE pg_temp.platform_v2_import_source_rows;
  IF v_owns_import THEN
    RETURN private.finish_platform_v2_source_import_v1();
  END IF;
  IF p_drain_after_batch THEN
    RETURN private.drain_platform_v2_source_import_v1();
  END IF;

  RETURN 0;
END;
$$;


--
-- Name: reconcile_platform_v2_user_entry(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reconcile_platform_v2_user_entry() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    IF NEW.management_kind = 'user' THEN
        PERFORM private.reconcile_platform_v2_content_nodes(
            NEW.id,
            'user-entry-v1:'
                || encode(digest(NEW.raw::text, 'sha256'), 'hex'),
            private.platform_v2_user_entry_content_nodes(NEW.raw)
        );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: record_ordinary_meaning_activation_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.record_ordinary_meaning_activation_v1(p_user_id uuid, p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_timezone text;
  v_activated_at timestamptz := now();
BEGIN
  IF p_user_id IS NULL OR p_entry_id IS NULL THEN
    RETURN;
  END IF;

  -- Source groups are the only durable multi-meaning identity.  User-owned
  -- entries are singleton groups and retain their existing new-card behavior.
  IF NOT EXISTS (
    SELECT 1
    FROM private.source_entry_bindings binding
    JOIN private.platform_v2_content_nodes node
      ON node.entry_id = binding.word_entry_id
     AND node.binding_state = 'active'
     AND node.parent_content_node_id IS NULL
     AND node.kind = 'definition'
    WHERE binding.word_entry_id = p_entry_id
      AND binding.binding_state = 'active'
  ) THEN
    RETURN;
  END IF;

  SELECT private.training_schedule_timezone_v1(settings.training_schedule_timezone)
  INTO v_timezone
  FROM public.user_settings settings
  WHERE settings.user_id = p_user_id;
  v_timezone := COALESCE(v_timezone, 'UTC');

  INSERT INTO private.ordinary_meaning_introduction_unlocks_v1 (
    user_id, entry_id, activated_at, activation_timezone, available_at
  ) VALUES (
    p_user_id,
    p_entry_id,
    v_activated_at,
    v_timezone,
    private.next_ordinary_meaning_available_at_v1(v_activated_at, v_timezone)
  )
  ON CONFLICT (user_id, entry_id) DO NOTHING;
END;
$$;


--
-- Name: refresh_unrenderable_ordinary_direct_entries_v1(uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_unrenderable_ordinary_direct_entries_v1(p_entry_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(cardinality(p_entry_ids), 0) = 0 THEN
    RETURN;
  END IF;

  DELETE FROM private.unrenderable_ordinary_direct_entries_v1 AS projection
  USING unnest(p_entry_ids) AS affected(entry_id)
  WHERE projection.entry_id = affected.entry_id;

  WITH affected AS MATERIALIZED (
    SELECT DISTINCT entry_id FROM unnest(p_entry_ids) AS input(entry_id)
  ), root_content AS MATERIALIZED (
    SELECT node.entry_id,
           bool_or(node.kind = 'definition') AS has_definition,
           bool_or(node.kind = 'example') AS has_example
    FROM private.platform_v2_content_nodes AS node
    JOIN affected ON affected.entry_id = node.entry_id
    WHERE node.binding_state = 'active'
      AND node.parent_content_node_id IS NULL
      AND node.kind IN ('definition', 'example')
    GROUP BY node.entry_id
  ), eligible_bound AS MATERIALIZED (
    SELECT DISTINCT current_binding.word_entry_id
    FROM private.source_entry_bindings AS current_binding
    JOIN affected ON affected.entry_id = current_binding.word_entry_id
    JOIN private.source_entry_bindings AS predecessor_binding
      ON predecessor_binding.dictionary_id = current_binding.dictionary_id
     AND predecessor_binding.identity_scheme_version =
         current_binding.identity_scheme_version
     AND predecessor_binding.source_group_key = current_binding.source_group_key
     AND predecessor_binding.sense_ordinal < current_binding.sense_ordinal
     AND predecessor_binding.binding_state = 'active'
    JOIN private.platform_v2_content_nodes AS predecessor_definition
      ON predecessor_definition.entry_id = predecessor_binding.word_entry_id
     AND predecessor_definition.binding_state = 'active'
     AND predecessor_definition.parent_content_node_id IS NULL
     AND predecessor_definition.kind = 'definition'
    WHERE current_binding.binding_state = 'active'
  )
  INSERT INTO private.unrenderable_ordinary_direct_entries_v1 (
    entry_id, updated_at
  )
  SELECT entry.id, now()
  FROM affected
  JOIN public.word_entries AS entry ON entry.id = affected.entry_id
  JOIN root_content ON root_content.entry_id = entry.id
  LEFT JOIN private.source_entry_bindings AS current_binding
    ON current_binding.word_entry_id = entry.id
   AND current_binding.binding_state = 'active'
  LEFT JOIN eligible_bound ON eligible_bound.word_entry_id = entry.id
  WHERE root_content.has_definition
    AND NOT root_content.has_example
    AND (
      eligible_bound.word_entry_id IS NOT NULL
      OR (
        current_binding.word_entry_id IS NULL
        AND COALESCE(entry.meaning_id, 1) > 1
      )
    );
END;
$$;


--
-- Name: refresh_unrenderable_ordinary_direct_entry_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_unrenderable_ordinary_direct_entry_v1(p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  DELETE FROM private.unrenderable_ordinary_direct_entries_v1
  WHERE entry_id = p_entry_id;

  INSERT INTO private.unrenderable_ordinary_direct_entries_v1 (
    entry_id, updated_at
  )
  SELECT entry.id, now()
  FROM public.word_entries entry
  WHERE entry.id = p_entry_id
    AND EXISTS (
      SELECT 1
      FROM private.platform_v2_content_nodes definition
      WHERE definition.entry_id = entry.id
        AND definition.binding_state = 'active'
        AND definition.parent_content_node_id IS NULL
        AND definition.kind = 'definition'
    )
    AND NOT EXISTS (
      SELECT 1
      FROM private.platform_v2_content_nodes example
      WHERE example.entry_id = entry.id
        AND example.binding_state = 'active'
        AND example.parent_content_node_id IS NULL
        AND example.kind = 'example'
    )
    AND (
      EXISTS (
        SELECT 1
        FROM private.source_entry_bindings current_binding
        JOIN private.source_entry_bindings predecessor_binding
          ON predecessor_binding.dictionary_id = current_binding.dictionary_id
         AND predecessor_binding.identity_scheme_version = current_binding.identity_scheme_version
         AND predecessor_binding.source_group_key = current_binding.source_group_key
         AND predecessor_binding.sense_ordinal < current_binding.sense_ordinal
         AND predecessor_binding.binding_state = 'active'
        JOIN private.platform_v2_content_nodes predecessor_definition
          ON predecessor_definition.entry_id = predecessor_binding.word_entry_id
         AND predecessor_definition.binding_state = 'active'
         AND predecessor_definition.parent_content_node_id IS NULL
         AND predecessor_definition.kind = 'definition'
        WHERE current_binding.word_entry_id = entry.id
          AND current_binding.binding_state = 'active'
      )
      OR (
        NOT EXISTS (
          SELECT 1 FROM private.source_entry_bindings binding
          WHERE binding.word_entry_id = entry.id
            AND binding.binding_state = 'active'
        )
        AND COALESCE(entry.meaning_id, 1) > 1
      )
    );
END;
$$;


--
-- Name: refresh_unrenderable_ordinary_direct_group_v1(uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.refresh_unrenderable_ordinary_direct_group_v1(p_dictionary_id uuid, p_identity_scheme_version text, p_source_group_key text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_entry record;
BEGIN
  FOR v_entry IN
    SELECT binding.word_entry_id
    FROM private.source_entry_bindings binding
    WHERE binding.dictionary_id = p_dictionary_id
      AND binding.identity_scheme_version = p_identity_scheme_version
      AND binding.source_group_key = p_source_group_key
      AND binding.binding_state = 'active'
  LOOP
    PERFORM private.refresh_unrenderable_ordinary_direct_entry_v1(
      v_entry.word_entry_id
    );
  END LOOP;
END;
$$;


--
-- Name: reject_action_receipt_projection_rewrite(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reject_action_receipt_projection_rewrite() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF OLD.request_projection IS NOT NULL
       AND NEW.request_projection IS DISTINCT FROM OLD.request_projection THEN
        RAISE EXCEPTION 'platform_action_receipt_projection_immutable';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: reject_known_card_scheduler_mutation(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.reject_known_card_scheduler_mutation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_old_is_known boolean := false;
    v_new_is_known boolean := false;
BEGIN
    IF TG_OP = 'DELETE'
       AND (
           NOT EXISTS (
               SELECT 1
                 FROM auth.users u
                WHERE u.id = OLD.user_id
           )
           OR NOT EXISTS (
               SELECT 1
                 FROM public.word_entries e
                WHERE e.id = OLD.entry_id
           )
       ) THEN
        RETURN OLD;
    END IF;

    SELECT EXISTS (
        SELECT 1
          FROM public.user_card_known_marks k
         WHERE k.user_id = OLD.user_id
           AND k.entry_id = OLD.entry_id
           AND k.card_type_id = OLD.card_type_id
           AND k.cleared_at IS NULL
    )
    INTO v_old_is_known;

    IF TG_OP = 'UPDATE' THEN
        SELECT EXISTS (
            SELECT 1
              FROM public.user_card_known_marks k
             WHERE k.user_id = NEW.user_id
               AND k.entry_id = NEW.entry_id
               AND k.card_type_id = NEW.card_type_id
               AND k.cleared_at IS NULL
        )
        INTO v_new_is_known;
    END IF;

    IF NOT v_old_is_known AND NOT v_new_is_known THEN
        RETURN COALESCE(NEW, OLD);
    END IF;

    IF TG_OP = 'UPDATE'
       AND ROW(NEW.user_id, NEW.entry_id, NEW.card_type_id)
           IS DISTINCT FROM
           ROW(OLD.user_id, OLD.entry_id, OLD.card_type_id) THEN
        RAISE EXCEPTION 'card_is_known';
    END IF;

    IF TG_OP = 'DELETE' OR ROW(
        NEW.fsrs_stability,
        NEW.fsrs_difficulty,
        NEW.fsrs_reps,
        NEW.fsrs_lapses,
        NEW.fsrs_last_grade,
        NEW.fsrs_last_interval,
        NEW.fsrs_target_retention,
        NEW.fsrs_params_version,
        NEW.fsrs_enabled,
        NEW.next_review_at,
        NEW.last_reviewed_at,
        NEW.success_count,
        NEW.last_result,
        NEW.hidden,
        NEW.frozen_until,
        NEW.in_learning,
        NEW.learning_due_at
    ) IS DISTINCT FROM ROW(
        OLD.fsrs_stability,
        OLD.fsrs_difficulty,
        OLD.fsrs_reps,
        OLD.fsrs_lapses,
        OLD.fsrs_last_grade,
        OLD.fsrs_last_interval,
        OLD.fsrs_target_retention,
        OLD.fsrs_params_version,
        OLD.fsrs_enabled,
        OLD.next_review_at,
        OLD.last_reviewed_at,
        OLD.success_count,
        OLD.last_result,
        OLD.hidden,
        OLD.frozen_until,
        OLD.in_learning,
        OLD.learning_due_at
    ) THEN
        RAISE EXCEPTION 'card_is_known';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: replan_training_session_remainder_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.replan_training_session_remainder_v1(p_user_id uuid, p_session_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
  v_session public.training_sessions%rowtype;
  v_completed integer;
  v_remaining integer;
  v_ordinal integer;
  v_excluded text[];
  v_count integer;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  -- Fast read keeps warm snapshots cheap; the locked read below is authoritative.
  IF NOT EXISTS (SELECT 1 FROM public.training_sessions s JOIN public.training_active_runs a ON a.session_id=s.id
    WHERE s.id=p_session_id AND s.user_id=p_user_id AND a.user_id=p_user_id
      AND s.exercise_family='meaning' AND s.completed_at IS NULL
      AND s.expires_at>private.training_reference_now_v1()
      AND s.external_state_revision>s.planned_state_revision) THEN RETURN false; END IF;
  PERFORM private.require_active_training_session_v1(p_user_id,p_session_id);
  SELECT * INTO v_session FROM public.training_sessions
    WHERE id=p_session_id AND user_id=p_user_id FOR UPDATE;
  IF v_session.external_state_revision<=v_session.planned_state_revision OR v_session.completed_at IS NOT NULL THEN RETURN false; END IF;
  SELECT count(*)::integer INTO v_completed FROM public.training_session_members
    WHERE session_id=p_session_id AND consumed_at IS NOT NULL;
  v_remaining:=GREATEST(v_session.requested_total-v_completed,0);
  INSERT INTO private.training_session_replan_history(session_id,revision,prior_members,replanned_at)
    SELECT p_session_id,v_session.external_state_revision,COALESCE(jsonb_agg(to_jsonb(m) ORDER BY ordinal),'[]'),private.training_reference_now_v1()
    FROM public.training_session_members m WHERE session_id=p_session_id AND consumed_at IS NULL AND unavailable_at IS NULL;
  DELETE FROM public.training_session_members WHERE session_id=p_session_id AND consumed_at IS NULL AND unavailable_at IS NULL;
  SELECT COALESCE(max(ordinal),0),COALESCE(array_agg(entry_id::text||':'||card_type_id),ARRAY[]::text[])
    INTO v_ordinal,v_excluded FROM public.training_session_members WHERE session_id=p_session_id;
  IF v_remaining>0 THEN
    INSERT INTO public.training_session_members(session_id,ordinal,entry_id,card_type_id,queue_source)
      SELECT p_session_id,v_ordinal+m.session_ordinal,m.entry_id,m.card_type_id,m.queue_source
      FROM private.training_session_members_v1(p_user_id,v_session.card_type_ids,v_session.list_id,v_session.list_type,
        v_session.card_filter,v_session.training_filter,v_remaining::text,v_session.new_review_ratio,v_excluded) m;
  END IF;
  -- Re-freeze contextual examples using the same rotation rule as migration175.
  IF v_session.training_filter->>'presentationMode'='word-in-context' THEN
    WITH examples AS (
      SELECT m.entry_id,n.id AS node_id,n.source_text_fingerprint,
        row_number() OVER(PARTITION BY m.entry_id ORDER BY n.source_order NULLS LAST,n.created_at,n.id)-1 AS example_index,
        count(*) OVER(PARTITION BY m.entry_id) AS example_count
      FROM public.training_session_members m JOIN private.platform_v2_content_nodes n ON n.entry_id=m.entry_id
      WHERE m.session_id=p_session_id AND m.consumed_at IS NULL AND m.unavailable_at IS NULL
        AND n.kind='example' AND n.binding_state='active'
        AND NULLIF(btrim(n.diagnostic_locator),'') IS NOT NULL
        AND n.diagnostic_locator ~ '^raw\.meanings\[[0-9]+\]\.examples\[[0-9]+\]$'
    ), chosen AS (
      SELECT e.* FROM examples e LEFT JOIN public.user_card_status s
        ON s.user_id=p_user_id AND s.entry_id=e.entry_id AND s.card_type_id='definition-to-word'
      WHERE e.example_index=mod(GREATEST(COALESCE(s.fsrs_reps,0),0)::bigint,e.example_count)
    ) UPDATE public.training_session_members m SET context_content_node_id=c.node_id,context_source_text_fingerprint=c.source_text_fingerprint
      FROM chosen c WHERE m.session_id=p_session_id AND m.entry_id=c.entry_id AND m.card_type_id='definition-to-word'
        AND m.consumed_at IS NULL AND m.unavailable_at IS NULL;
  END IF;
  SELECT count(*)::integer INTO v_count FROM public.training_session_members
    WHERE session_id=p_session_id AND consumed_at IS NULL AND unavailable_at IS NULL;
  UPDATE public.training_sessions SET planned_state_revision=external_state_revision,
    planned_total=v_completed+v_count,
    planned_new=(SELECT count(*)::integer FROM public.training_session_members WHERE session_id=p_session_id AND queue_source='new' AND (unavailable_at IS NULL OR consumed_at IS NOT NULL)),
    planned_review=(SELECT count(*)::integer FROM public.training_session_members WHERE session_id=p_session_id AND queue_source IN ('learning','review') AND (unavailable_at IS NULL OR consumed_at IS NOT NULL)),
    planned_practice=(SELECT count(*)::integer FROM public.training_session_members WHERE session_id=p_session_id AND queue_source='practice' AND (unavailable_at IS NULL OR consumed_at IS NOT NULL)),
    completed_at=CASE WHEN v_count=0 THEN private.training_reference_now_v1() ELSE NULL END,
    exhausted_at=CASE WHEN v_count=0 AND v_completed<requested_total THEN private.training_reference_now_v1() ELSE NULL END,
    completion_reason=CASE WHEN v_count=0 THEN CASE WHEN v_completed>=requested_total THEN 'completed' ELSE 'exhausted' END ELSE NULL END
    WHERE id=p_session_id;
  RETURN true;
END;
$_$;


--
-- Name: require_active_training_session_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_active_training_session_v1(p_user_id uuid, p_session_id uuid) RETURNS bigint
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_generation bigint;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;

  -- The same advisory lock is used by start/continue and new actions. It
  -- makes takeover-versus-grade deterministic even before the active row
  -- exists for a brand new learner.
  PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));

  SELECT active.generation INTO v_generation
  FROM public.training_active_runs AS active
  WHERE active.user_id = p_user_id
    AND active.session_id = p_session_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'training_session_superseded';
  END IF;
  RETURN v_generation;
END;
$$;


--
-- Name: require_collection_sharing_writes_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_collection_sharing_writes_v1() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE enabled boolean;
BEGIN
 IF (select auth.uid()) IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 SELECT new_writes_enabled INTO enabled FROM private.collection_sharing_rollout WHERE singleton FOR SHARE;
 IF NOT COALESCE(enabled,false) THEN RAISE EXCEPTION 'sharing_writes_disabled' USING ERRCODE='55000'; END IF;
END;
$$;


--
-- Name: require_training_pair_available_v1(uuid, text, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.require_training_pair_available_v1(p_user_id uuid, p_family text, p_entry_id uuid, p_node_id uuid, p_fingerprint text, p_card_type_id text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_pair_key text := private.training_pair_key_v1(p_family,p_entry_id,p_node_id,p_fingerprint,p_card_type_id);
BEGIN
  IF p_user_id IS NULL OR v_pair_key IS NULL THEN RAISE EXCEPTION 'invalid_exclusion_target'; END IF;
  IF p_family='meaning' AND p_card_type_id IN ('word-to-definition','definition-to-word') THEN
    PERFORM pg_advisory_xact_lock(hashtext('training-headword:'||p_user_id::text||':'||
      private.training_headword_group_v1(p_entry_id)::text));
  END IF;
  PERFORM pg_advisory_xact_lock(hashtext('training-pair:'||p_user_id::text||':'||v_pair_key));
  IF private.training_pair_excluded_v1(p_user_id,p_family,p_entry_id,p_node_id,p_fingerprint,p_card_type_id) THEN
    RAISE EXCEPTION 'training_pair_excluded';
  END IF;
END;
$$;


--
-- Name: resolve_dictionary_lookup_candidates_v1(uuid, text, text, uuid[], boolean, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resolve_dictionary_lookup_candidates_v1(p_user_id uuid, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_public_catalog boolean DEFAULT false, p_limit integer DEFAULT 10) RETURNS TABLE(entry_id uuid, resolved_by text, matched_text text, tier_rank integer, match_rank integer, headword text, meaning_id integer, dictionary_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_limit int := LEAST(GREATEST(COALESCE(p_limit, 10), 1), 50);
BEGIN
    IF v_raw_query IS NULL THEN
        RETURN;
    END IF;

    v_query := lower(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);

    RETURN QUERY
    WITH eligible_dictionaries AS MATERIALIZED (
        SELECT d.id, d.kind, d.owner_user_id
        FROM dictionaries d
        WHERE CASE
            WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
            ELSE p_user_id IS NOT NULL AND can_access_dictionary(p_user_id, d.id, 'read')
        END
    ),
    headword_candidates AS MATERIALIZED (
        SELECT
            w.id AS entry_id,
            'exact-headword'::text AS resolved_by,
            w.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN w.headword = v_raw_query THEN 0
                WHEN lower(w.headword) = v_query THEN 1
                ELSE 2
            END AS match_rank,
            w.headword,
            w.meaning_id,
            w.dictionary_id
        FROM private.active_word_entries w
        JOIN eligible_dictionaries d ON d.id = w.dictionary_id
        WHERE (v_language_code IS NULL OR w.language_code = v_language_code)
          AND (array_length(v_dictionary_ids, 1) IS NULL OR w.dictionary_id = ANY(v_dictionary_ids))
          AND (
              lower(w.headword) = v_query
              OR normalize_dictionary_search_text_unaccent(w.headword) = v_query_unaccent
          )
        ORDER BY
            CASE
                WHEN w.headword = v_raw_query THEN 0
                WHEN lower(w.headword) = v_query THEN 1
                ELSE 2
            END ASC,
            lower(w.headword) ASC,
            w.meaning_id ASC,
            w.id ASC
        LIMIT v_limit
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (w.id)
            w.id AS entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            f.form AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN f.form = v_raw_query THEN 0
                WHEN lower(f.form) = v_query THEN 1
                ELSE 2
            END AS match_rank,
            w.headword,
            w.meaning_id,
            w.dictionary_id
        FROM word_forms f
        JOIN private.active_word_entries w ON w.id = f.word_id
        JOIN eligible_dictionaries d ON d.id = w.dictionary_id
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND (v_language_code IS NULL OR f.language_code = v_language_code)
          AND f.language_code = w.language_code
          AND (
              (f.dictionary_id IS NULL AND w.dictionary_id IS NULL)
              OR f.dictionary_id = w.dictionary_id
          )
          AND (array_length(v_dictionary_ids, 1) IS NULL OR w.dictionary_id = ANY(v_dictionary_ids))
          AND (
              lower(f.form) = v_query
              OR normalize_dictionary_search_text_unaccent(f.form) = v_query_unaccent
          )
        ORDER BY
            w.id,
            CASE
                WHEN f.form = v_raw_query THEN 0
                WHEN lower(f.form) = v_query THEN 1
                ELSE 2
            END ASC,
            lower(f.form) ASC
    )
    SELECT *
    FROM (
        SELECT * FROM headword_candidates
        UNION ALL
        SELECT * FROM form_candidates
    ) c
    ORDER BY c.tier_rank ASC, c.match_rank ASC, lower(c.headword) ASC, c.meaning_id ASC, c.entry_id ASC
    LIMIT v_limit;
END;
$$;


--
-- Name: resolve_dictionary_lookup_candidates_v2(uuid, text, text, uuid[], integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resolve_dictionary_lookup_candidates_v2(p_user_id uuid, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 10) RETURNS TABLE(entry_id uuid, resolved_by text, matched_text text, tier_rank integer, match_rank integer, headword text, meaning_id integer, dictionary_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_limit int := LEAST(GREATEST(COALESCE(p_limit, 10), 1), 50);
BEGIN
    IF p_user_id IS NULL OR v_raw_query IS NULL THEN
        RETURN;
    END IF;

    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);

    RETURN QUERY
    WITH user_context AS MATERIALIZED (
        SELECT COALESCE(
            (SELECT subscription_tier FROM user_settings WHERE user_id = p_user_id),
            'free'
        ) AS subscription_tier
    ),
    eligible_dictionaries AS MATERIALIZED (
        SELECT d.id, d.kind, d.owner_user_id
        FROM dictionaries d
        WHERE public.can_browse_dictionary(p_user_id, d.id)
          AND (array_length(v_dictionary_ids, 1) IS NULL OR d.id = ANY(v_dictionary_ids))
    ),
    indexed_headword_matches AS MATERIALIZED (
        SELECT
            s.entry_id,
            'exact-headword'::text AS resolved_by,
            s.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN s.headword = v_raw_query THEN 0
                WHEN s.normalized_headword = v_query THEN 1
                ELSE 2
            END AS match_rank,
            s.headword,
            s.meaning_id,
            s.dictionary_id
        FROM dictionary_search_documents s
        JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
        WHERE (v_language_code IS NULL OR s.language_code = v_language_code)
          AND s.normalized_headword = v_query

        UNION ALL

        SELECT
            s.entry_id,
            'exact-headword'::text AS resolved_by,
            s.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN s.headword = v_raw_query THEN 0
                WHEN s.normalized_headword = v_query THEN 1
                ELSE 2
            END AS match_rank,
            s.headword,
            s.meaning_id,
            s.dictionary_id
        FROM dictionary_search_documents s
        JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
        WHERE (v_language_code IS NULL OR s.language_code = v_language_code)
          AND s.normalized_headword_unaccent = v_query_unaccent
          AND s.normalized_headword <> v_query
    ),
    legacy_user_headword_matches AS MATERIALIZED (
        SELECT
            w.id AS entry_id,
            'exact-headword'::text AS resolved_by,
            w.headword AS matched_text,
            1 AS tier_rank,
            CASE
                WHEN w.headword = v_raw_query THEN 0
                WHEN lower(w.headword) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            w.headword,
            w.meaning_id,
            w.dictionary_id
        FROM private.active_word_entries w
        JOIN eligible_dictionaries ed ON ed.id = w.dictionary_id
        LEFT JOIN dictionary_search_documents s ON s.entry_id = w.id
        WHERE NOT EXISTS (SELECT 1 FROM indexed_headword_matches)
          AND s.entry_id IS NULL
          AND ed.kind = 'user'
          AND (v_language_code IS NULL OR w.language_code = v_language_code)
          AND (
              lower(w.headword) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(w.headword) = v_query_unaccent
          )
    ),
    headword_matches AS MATERIALIZED (
        SELECT * FROM indexed_headword_matches
        UNION ALL
        SELECT * FROM legacy_user_headword_matches
    ),
    headword_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (hm.entry_id)
            hm.entry_id,
            hm.resolved_by,
            hm.matched_text,
            hm.tier_rank,
            hm.match_rank,
            hm.headword,
            hm.meaning_id,
            hm.dictionary_id
        FROM headword_matches hm
        ORDER BY
            hm.entry_id,
            hm.match_rank ASC,
            normalize_dictionary_search_text(hm.headword) ASC,
            hm.meaning_id ASC
        LIMIT v_limit
    ),
    indexed_form_matches AS MATERIALIZED (
        SELECT
            s.entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            f.display_text AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN f.display_text = v_raw_query THEN 0
                WHEN f.normalized_text = v_query THEN 1
                ELSE 2
            END AS match_rank,
            s.headword,
            s.meaning_id,
            s.dictionary_id
        FROM dictionary_search_fields f
        JOIN dictionary_search_documents s ON s.entry_id = f.entry_id
        JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND f.field_group = 'form'
          AND (v_language_code IS NULL OR f.language_code = v_language_code)
          AND f.normalized_text = v_query

        UNION ALL

        SELECT
            s.entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            f.display_text AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN f.display_text = v_raw_query THEN 0
                WHEN f.normalized_text = v_query THEN 1
                ELSE 2
            END AS match_rank,
            s.headword,
            s.meaning_id,
            s.dictionary_id
        FROM dictionary_search_fields f
        JOIN dictionary_search_documents s ON s.entry_id = f.entry_id
        JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND f.field_group = 'form'
          AND (v_language_code IS NULL OR f.language_code = v_language_code)
          AND f.normalized_text_unaccent = v_query_unaccent
          AND f.normalized_text <> v_query
    ),
    legacy_user_form_matches AS MATERIALIZED (
        SELECT
            w.id AS entry_id,
            'lemma-or-inflection'::text AS resolved_by,
            f.form AS matched_text,
            2 AS tier_rank,
            CASE
                WHEN f.form = v_raw_query THEN 0
                WHEN lower(f.form) = lower(v_raw_query) THEN 1
                ELSE 2
            END AS match_rank,
            w.headword,
            w.meaning_id,
            w.dictionary_id
        FROM word_forms f
        JOIN private.active_word_entries w ON w.id = f.word_id
        JOIN eligible_dictionaries ed ON ed.id = w.dictionary_id
        LEFT JOIN dictionary_search_documents s ON s.entry_id = w.id
        WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
          AND NOT EXISTS (SELECT 1 FROM indexed_form_matches)
          AND s.entry_id IS NULL
          AND ed.kind = 'user'
          AND (v_language_code IS NULL OR f.language_code = v_language_code)
          AND f.language_code = w.language_code
          AND (
              (f.dictionary_id IS NULL AND w.dictionary_id IS NULL)
              OR f.dictionary_id = w.dictionary_id
          )
          AND (
              lower(f.form) = lower(v_raw_query)
              OR normalize_dictionary_search_text_unaccent(f.form) = v_query_unaccent
          )
    ),
    form_matches AS MATERIALIZED (
        SELECT * FROM indexed_form_matches
        UNION ALL
        SELECT * FROM legacy_user_form_matches
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (fm.entry_id)
            fm.entry_id,
            fm.resolved_by,
            fm.matched_text,
            fm.tier_rank,
            fm.match_rank,
            fm.headword,
            fm.meaning_id,
            fm.dictionary_id
        FROM form_matches fm
        ORDER BY
            fm.entry_id,
            fm.match_rank ASC,
            normalize_dictionary_search_text(fm.matched_text) ASC
    )
    SELECT *
    FROM (
        SELECT * FROM headword_candidates
        UNION ALL
        SELECT * FROM form_candidates
    ) c
    ORDER BY
        c.tier_rank ASC,
        c.match_rank ASC,
        normalize_dictionary_search_text(c.headword) ASC,
        c.meaning_id ASC,
        c.entry_id ASC
    LIMIT v_limit;
END;
$$;


--
-- Name: resolve_public_dictionary_lookup_candidates_indexed_v1(text, text, uuid[], integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resolve_public_dictionary_lookup_candidates_indexed_v1(p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 10) RETURNS TABLE(entry_id uuid, resolved_by text, matched_text text, tier_rank integer, match_rank integer, headword text, meaning_id integer, dictionary_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_limit int := LEAST(GREATEST(COALESCE(p_limit, 10), 1), 50);
BEGIN
    IF v_raw_query IS NULL THEN
        RETURN;
    END IF;

    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);

    RETURN QUERY
    WITH eligible_dictionaries AS MATERIALIZED (
        SELECT d.id
        FROM dictionaries d
        WHERE d.visibility IN ('system', 'public')
          AND (array_length(v_dictionary_ids, 1) IS NULL OR d.id = ANY(v_dictionary_ids))
    ),
    headword_candidates AS MATERIALIZED (
        SELECT *
        FROM (
            SELECT
                s.entry_id,
                'exact-headword'::text AS resolved_by,
                s.headword AS matched_text,
                1 AS tier_rank,
                CASE
                    WHEN s.headword = v_raw_query THEN 0
                    WHEN s.normalized_headword = v_query THEN 1
                    ELSE 2
                END AS match_rank,
                s.headword,
                s.meaning_id,
                s.dictionary_id
            FROM dictionary_search_documents s
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE (v_language_code IS NULL OR s.language_code = v_language_code)
              AND s.normalized_headword = v_query

            UNION ALL

            SELECT
                s.entry_id,
                'exact-headword'::text AS resolved_by,
                s.headword AS matched_text,
                1 AS tier_rank,
                CASE
                    WHEN s.headword = v_raw_query THEN 0
                    WHEN s.normalized_headword = v_query THEN 1
                    ELSE 2
                END AS match_rank,
                s.headword,
                s.meaning_id,
                s.dictionary_id
            FROM dictionary_search_documents s
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE (v_language_code IS NULL OR s.language_code = v_language_code)
              AND s.normalized_headword_unaccent = v_query_unaccent
              AND s.normalized_headword <> v_query
        ) headword_matches
        ORDER BY
            headword_matches.match_rank ASC,
            normalize_dictionary_search_text(headword_matches.headword) ASC,
            headword_matches.meaning_id ASC,
            headword_matches.entry_id ASC
        LIMIT v_limit
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (form_matches.entry_id)
            form_matches.entry_id,
            form_matches.resolved_by,
            form_matches.matched_text,
            form_matches.tier_rank,
            form_matches.match_rank,
            form_matches.headword,
            form_matches.meaning_id,
            form_matches.dictionary_id
        FROM (
            SELECT
                s.entry_id,
                'lemma-or-inflection'::text AS resolved_by,
                f.display_text AS matched_text,
                2 AS tier_rank,
                CASE
                    WHEN f.display_text = v_raw_query THEN 0
                    WHEN f.normalized_text = v_query THEN 1
                    ELSE 2
                END AS match_rank,
                s.headword,
                s.meaning_id,
                s.dictionary_id
            FROM dictionary_search_fields f
            JOIN dictionary_search_documents s ON s.entry_id = f.entry_id
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
              AND f.field_group = 'form'
              AND (v_language_code IS NULL OR f.language_code = v_language_code)
              AND f.normalized_text = v_query

            UNION ALL

            SELECT
                s.entry_id,
                'lemma-or-inflection'::text AS resolved_by,
                f.display_text AS matched_text,
                2 AS tier_rank,
                CASE
                    WHEN f.display_text = v_raw_query THEN 0
                    WHEN f.normalized_text = v_query THEN 1
                    ELSE 2
                END AS match_rank,
                s.headword,
                s.meaning_id,
                s.dictionary_id
            FROM dictionary_search_fields f
            JOIN dictionary_search_documents s ON s.entry_id = f.entry_id
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
              AND f.field_group = 'form'
              AND (v_language_code IS NULL OR f.language_code = v_language_code)
              AND f.normalized_text_unaccent = v_query_unaccent
              AND f.normalized_text <> v_query
        ) form_matches
        ORDER BY
            form_matches.entry_id,
            form_matches.match_rank ASC,
            normalize_dictionary_search_text(form_matches.matched_text) ASC
    )
    SELECT *
    FROM (
        SELECT * FROM headword_candidates
        UNION ALL
        SELECT * FROM form_candidates
    ) c
    ORDER BY
        c.tier_rank ASC,
        c.match_rank ASC,
        normalize_dictionary_search_text(c.headword) ASC,
        c.meaning_id ASC,
        c.entry_id ASC
    LIMIT v_limit;
END;
$$;


--
-- Name: resolve_training_material_selection_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.resolve_training_material_selection_v1(p_user_id uuid, p_list_id uuid, p_list_type text, p_filter jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_uid uuid := (SELECT auth.uid());
  v_preferences jsonb;
  v_language text;
  v_allowed jsonb;
  v_filter jsonb := COALESCE(p_filter, '{}'::jsonb);
BEGIN
  IF v_uid IS NULL OR p_user_id IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF jsonb_typeof(v_filter) <> 'object' THEN RAISE EXCEPTION 'invalid_training_filter'; END IF;
  SELECT settings.material_preferences, settings.language_code
    INTO v_preferences, v_language FROM public.user_settings settings
    WHERE settings.user_id = p_user_id;
  v_preferences := COALESCE(v_preferences,
    '{"schemaVersion":1,"learningLanguages":[],"disabledDictionaryIds":[]}'::jsonb);
  v_language := COALESCE(v_language, 'nl');
  IF v_filter ? 'dictionaryScope' THEN
    v_language := v_filter#>>'{dictionaryScope,languageCode}';
  ELSIF p_list_id IS NOT NULL THEN
    IF p_list_type = 'user' THEN
      SELECT COALESCE(list.primary_language_code,list.language_code,v_language)
        INTO v_language FROM public.user_word_lists list
        WHERE list.id=p_list_id AND (list.user_id=p_user_id
    OR list.id IN (SELECT collection_id FROM private.shared_collection_ids_v1(p_user_id)));
    ELSE
      SELECT COALESCE(list.primary_language_code,list.language_code,v_language)
        INTO v_language FROM public.word_lists list WHERE list.id=p_list_id;
    END IF;
    IF NOT FOUND THEN RAISE EXCEPTION 'training_material_unavailable'; END IF;
  END IF;
  IF jsonb_array_length(v_preferences->'learningLanguages') = 0 THEN
    v_allowed := 'null'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(item->>'code'), '[]'::jsonb) INTO v_allowed
      FROM jsonb_array_elements(v_preferences->'learningLanguages') item
      WHERE item->'paused' = 'false'::jsonb;
    IF NOT (v_allowed ? v_language) THEN RAISE EXCEPTION 'training_material_unavailable'; END IF;
  END IF;
  -- Caller-supplied snapshots are never authoritative for a new run or plan.
  v_filter := (v_filter - 'materialSelection') || jsonb_build_object('materialSelection',
    jsonb_build_object('schemaVersion',1,'allowedLanguageCodes',v_allowed,
      'disabledDictionaryIds',v_preferences->'disabledDictionaryIds'));
  IF v_filter ? 'dictionaryScope' AND NOT EXISTS (
    SELECT 1 FROM public.dictionaries dictionary
    WHERE dictionary.language_code=v_language
      AND (public.can_access_dictionary(p_user_id,dictionary.id,'read') OR (
    dictionary.kind='user' AND EXISTS (SELECT 1 FROM private.shared_author_entry_memberships_v1 shared
      JOIN private.active_word_entries shared_entry ON shared_entry.id=shared.entry_id
      WHERE shared.user_id=p_user_id AND shared_entry.dictionary_id=dictionary.id)))
      AND private.training_material_entry_selected_v1(dictionary.language_code,dictionary.id,v_filter)
      AND (v_filter#>>'{dictionaryScope,mode}' = 'all' OR
        (v_filter#>'{dictionaryScope,dictionaryIds}') ? dictionary.id::text)
  ) THEN RAISE EXCEPTION 'training_material_unavailable'; END IF;
  RETURN v_filter;
END;
$$;


--
-- Name: safe_jsonb_int(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.safe_jsonb_int(p_value text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
BEGIN
    IF p_value IS NULL OR p_value !~ '^-?[0-9]+$' THEN
        RETURN NULL;
    END IF;
    RETURN p_value::integer;
EXCEPTION WHEN others THEN
    RETURN NULL;
END;
$_$;


--
-- Name: search_dictionary_alphabetical_group_v1(uuid, boolean, text, text, uuid[], integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.search_dictionary_alphabetical_group_v1(p_user_id uuid, p_public_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 6, p_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_limit int := LEAST(GREATEST(COALESCE(p_limit, 6), 1), 100);
    v_before_limit int := GREATEST(LEAST(COALESCE(p_limit, 6), 100) / 2, 0);
    v_cursor jsonb := private.decode_dictionary_search_cursor_v1(p_cursor);
    v_items jsonb := '[]'::jsonb;
    v_has_more boolean := false;
    v_next_cursor text := NULL;
    v_last jsonb;
BEGIN
    IF v_raw_query IS NULL THEN
        RETURN jsonb_build_object(
            'id', 'alphabetical',
            'total', NULL,
            'count', jsonb_build_object('value', NULL, 'relation', 'unknown'),
            'items', '[]'::jsonb,
            'page', jsonb_build_object('limit', v_limit, 'nextCursor', NULL, 'hasMore', false)
        );
    END IF;

    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);

    WITH eligible_dictionaries AS MATERIALIZED (
        SELECT d.id, d.slug, d.name, d.kind
        FROM dictionaries d
        WHERE CASE
            WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
            ELSE p_user_id IS NOT NULL AND can_browse_dictionary(p_user_id, d.id, 'read')
        END
          AND (array_length(v_dictionary_ids, 1) IS NULL OR d.id = ANY(v_dictionary_ids))
    ),
    before_rows AS (
        SELECT *
        FROM (
            SELECT
                s.entry_id,
                s.dictionary_id,
                s.language_code,
                s.headword,
                s.meaning_id,
                s.part_of_speech,
                s.summary_definition,
                s.normalized_headword_unaccent,
                s.normalized_headword,
                ed.slug AS dictionary_slug,
                ed.name AS dictionary_name,
                ed.kind AS dictionary_kind
            FROM dictionary_search_documents s
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE v_cursor = '{}'::jsonb
              AND (v_language_code IS NULL OR s.language_code = v_language_code)
              AND (
                  s.normalized_headword_unaccent,
                  s.normalized_headword,
                  s.dictionary_id,
                  s.meaning_id,
                  s.entry_id
              ) < (
                  v_query_unaccent,
                  v_query,
                  '00000000-0000-0000-0000-000000000000'::uuid,
                  -1,
                  '00000000-0000-0000-0000-000000000000'::uuid
              )
            ORDER BY
                s.normalized_headword_unaccent DESC,
                s.normalized_headword DESC,
                s.dictionary_id DESC,
                s.meaning_id DESC,
                s.entry_id DESC
            LIMIT v_before_limit
        ) previous_page
    ),
    after_rows AS (
        SELECT
            s.entry_id,
            s.dictionary_id,
            s.language_code,
            s.headword,
            s.meaning_id,
            s.part_of_speech,
            s.summary_definition,
            s.normalized_headword_unaccent,
            s.normalized_headword,
            ed.slug AS dictionary_slug,
            ed.name AS dictionary_name,
            ed.kind AS dictionary_kind
        FROM dictionary_search_documents s
        JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
        WHERE (v_language_code IS NULL OR s.language_code = v_language_code)
          AND (
              (
                  v_cursor <> '{}'::jsonb
                  AND (
                      s.normalized_headword_unaccent,
                      s.normalized_headword,
                      s.dictionary_id,
                      s.meaning_id,
                      s.entry_id
                  ) > (
                      COALESCE(v_cursor->>'headwordSort', ''),
                      COALESCE(v_cursor->>'normalizedHeadword', ''),
                      COALESCE((v_cursor->>'dictionaryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
                      COALESCE((v_cursor->>'meaningId')::int, -1),
                      COALESCE((v_cursor->>'entryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid)
                  )
              )
              OR (
                  v_cursor = '{}'::jsonb
                  AND s.normalized_headword_unaccent >= v_query_unaccent
              )
          )
        ORDER BY
            s.normalized_headword_unaccent,
            s.normalized_headword,
            s.dictionary_id,
            s.meaning_id,
            s.entry_id
        LIMIT v_limit + 1
    ),
    centered_rows AS (
        SELECT * FROM before_rows
        UNION ALL
        SELECT * FROM after_rows
    ),
    ordered_rows AS (
        SELECT *
        FROM centered_rows
        ORDER BY
            normalized_headword_unaccent,
            normalized_headword,
            dictionary_id,
            meaning_id,
            entry_id
    ),
    visible_page AS (
        SELECT *, row_number() OVER () AS rn FROM ordered_rows
    ),
    payloads AS (
        SELECT
            jsonb_build_object(
                'kind', 'entry',
                'entry', jsonb_strip_nulls(jsonb_build_object(
                    'id', entry_id,
                    'languageCode', language_code,
                    'headword', headword,
                    'meaningId', meaning_id,
                    'partOfSpeech', part_of_speech,
                    'summaryDefinition', summary_definition
                )),
                'dictionary', jsonb_strip_nulls(jsonb_build_object(
                    'id', dictionary_id,
                    'slug', dictionary_slug,
                    'name', dictionary_name,
                    'kind', dictionary_kind
                )),
                'match', jsonb_build_object(
                    'relation', 'alphabetical',
                    'matchedText', headword,
                    'sourcePath', 'dictionary_search_documents.normalized_headword_unaccent'
                )
            ) AS payload,
            jsonb_build_object(
                'group', 'alphabetical',
                'headwordSort', normalized_headword_unaccent,
                'normalizedHeadword', normalized_headword,
                'dictionaryId', dictionary_id,
                'meaningId', meaning_id,
                'entryId', entry_id
            ) AS cursor_payload,
            rn
        FROM visible_page
        WHERE rn <= v_limit
    )
    SELECT
        COALESCE(jsonb_agg(payload ORDER BY rn), '[]'::jsonb),
        EXISTS(SELECT 1 FROM visible_page WHERE rn > v_limit),
        (array_agg(cursor_payload ORDER BY rn DESC))[1]
    INTO v_items, v_has_more, v_last
    FROM payloads;

    IF v_has_more AND v_last IS NOT NULL THEN
        v_next_cursor := private.encode_dictionary_search_cursor_v1(v_last);
    END IF;

    RETURN jsonb_build_object(
        'id', 'alphabetical',
        'total', NULL,
        'count', jsonb_build_object('value', NULL, 'relation', 'unknown'),
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'limit', v_limit,
            'nextCursor', v_next_cursor,
            'hasMore', COALESCE(v_has_more, false)
        )
    );
END;
$$;


--
-- Name: search_dictionary_body_group_v1(uuid, boolean, text, text, uuid[], text, integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.search_dictionary_body_group_v1(p_user_id uuid, p_public_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_group text DEFAULT 'examples'::text, p_limit integer DEFAULT 6, p_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query_unaccent text;
    v_match_terms text[] := ARRAY[]::text[];
    v_term_query text;
    v_ts_query tsquery;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_group text := COALESCE(NULLIF(trim(p_group), ''), 'examples');
    v_limit int := LEAST(GREATEST(COALESCE(p_limit, 6), 1), 100);
    v_cursor jsonb := private.decode_dictionary_search_cursor_v1(p_cursor);
    v_items jsonb := '[]'::jsonb;
    v_has_more boolean := false;
    v_next_cursor text := NULL;
    v_last jsonb;
BEGIN
    IF v_raw_query IS NULL OR v_group NOT IN ('examples', 'definitions') THEN
        RETURN jsonb_build_object(
            'id', v_group,
            'total', NULL,
            'count', jsonb_build_object('value', NULL, 'relation', 'unknown'),
            'items', '[]'::jsonb,
            'page', jsonb_build_object('limit', v_limit, 'nextCursor', NULL, 'hasMore', false)
        );
    END IF;

    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);
    v_ts_query := plainto_tsquery('simple', v_query_unaccent);

    IF length(v_query_unaccent) >= 3 THEN
        WITH matching_entries AS MATERIALIZED (
            SELECT DISTINCT f.entry_id
            FROM dictionary_search_fields f
            JOIN dictionaries d ON d.id = f.dictionary_id
            WHERE f.field_group = 'form'
              AND f.extraction_version >= 2
              AND f.normalized_text_unaccent = v_query_unaccent
              AND (v_language_code IS NULL OR f.language_code = v_language_code)
              AND (array_length(v_dictionary_ids, 1) IS NULL OR f.dictionary_id = ANY(v_dictionary_ids))
              AND CASE
                  WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
                  ELSE p_user_id IS NOT NULL AND can_browse_dictionary(p_user_id, d.id, 'read')
              END
        )
        SELECT COALESCE(array_agg(term ORDER BY term), ARRAY[]::text[])
        INTO v_match_terms
        FROM (
            SELECT DISTINCT f.normalized_text_unaccent AS term
            FROM dictionary_search_fields f
            JOIN matching_entries m ON m.entry_id = f.entry_id
            WHERE f.field_group = 'form'
              AND f.extraction_version >= 2
              AND f.normalized_text_unaccent ~ '^[[:alnum:]]+$'

            UNION

            SELECT v_query_unaccent AS term
            WHERE v_query_unaccent ~ '^[[:alnum:]]+$'
        ) terms;

        v_term_query := CASE
            WHEN cardinality(v_match_terms) > 0
            THEN '(^|[^[:alnum:]])(' || array_to_string(v_match_terms, '|') || ')([^[:alnum:]]|$)'
            ELSE NULL
        END;
    END IF;

    WITH eligible_dictionaries AS MATERIALIZED (
        SELECT d.id
        FROM dictionaries d
        WHERE CASE
            WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
            ELSE p_user_id IS NOT NULL AND can_browse_dictionary(p_user_id, d.id, 'read')
        END
          AND (array_length(v_dictionary_ids, 1) IS NULL OR d.id = ANY(v_dictionary_ids))
    ),
    fts_page AS MATERIALIZED (
        SELECT
            f.entry_id,
            f.dictionary_id,
            f.language_code,
            f.field_group,
            f.field_kind,
            f.display_text,
            f.source_path,
            f.meaning_ordinal,
            f.item_ordinal,
            0 AS rank
        FROM dictionary_search_fields f
        JOIN eligible_dictionaries ed ON ed.id = f.dictionary_id
        WHERE (v_language_code IS NULL OR f.language_code = v_language_code)
          AND f.extraction_version >= 2
          AND (
              CASE
                  WHEN v_group = 'examples' THEN f.field_group IN ('example', 'idiom')
                  ELSE f.field_group IN ('definition', 'context', 'note')
              END
          )
          AND f.field_tsv @@ v_ts_query
          AND (
              v_cursor = '{}'::jsonb
              OR (0, f.meaning_ordinal, f.item_ordinal, f.entry_id, f.source_path) >
                 (
                    COALESCE((v_cursor->>'rank')::int, -1),
                    COALESCE((v_cursor->>'meaningOrdinal')::int, -1),
                    COALESCE((v_cursor->>'itemOrdinal')::int, -1),
                    COALESCE((v_cursor->>'entryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
                    COALESCE(v_cursor->>'sourcePath', '')
                 )
          )
        ORDER BY f.meaning_ordinal, f.item_ordinal, f.entry_id, f.source_path
        LIMIT v_limit + 1
    ),
    substring_page AS MATERIALIZED (
        SELECT
            f.entry_id,
            f.dictionary_id,
            f.language_code,
            f.field_group,
            f.field_kind,
            f.display_text,
            f.source_path,
            f.meaning_ordinal,
            f.item_ordinal,
            1 AS rank
        FROM dictionary_search_fields f
        JOIN eligible_dictionaries ed ON ed.id = f.dictionary_id
        WHERE v_term_query IS NOT NULL
          AND length(v_query_unaccent) >= 3
          AND (
              COALESCE((v_cursor->>'rank')::int, 0) >= 1
              OR (SELECT count(*) FROM fts_page) <= v_limit
          )
          AND (v_language_code IS NULL OR f.language_code = v_language_code)
          AND f.extraction_version >= 2
          AND (
              CASE
                  WHEN v_group = 'examples' THEN f.field_group IN ('example', 'idiom')
                  ELSE f.field_group IN ('definition', 'context', 'note')
              END
          )
          AND f.normalized_text_unaccent ~ v_term_query
          AND NOT (f.field_tsv @@ v_ts_query)
          AND (
              v_cursor = '{}'::jsonb
              OR (1, f.meaning_ordinal, f.item_ordinal, f.entry_id, f.source_path) >
                 (
                    COALESCE((v_cursor->>'rank')::int, -1),
                    COALESCE((v_cursor->>'meaningOrdinal')::int, -1),
                    COALESCE((v_cursor->>'itemOrdinal')::int, -1),
                    COALESCE((v_cursor->>'entryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
                    COALESCE(v_cursor->>'sourcePath', '')
                 )
          )
        ORDER BY f.meaning_ordinal, f.item_ordinal, f.entry_id, f.source_path
        LIMIT v_limit + 1
    ),
    page_fields AS MATERIALIZED (
        SELECT *
        FROM (
            SELECT * FROM fts_page
            UNION ALL
            SELECT * FROM substring_page
        ) matches
        ORDER BY rank, meaning_ordinal, item_ordinal, entry_id, source_path
        LIMIT v_limit + 1
    ),
    hydrated AS (
        SELECT
            p.*,
            s.headword,
            s.meaning_id,
            s.part_of_speech,
            s.summary_definition,
            d.slug AS dictionary_slug,
            d.name AS dictionary_name,
            d.kind AS dictionary_kind,
            row_number() OVER (ORDER BY p.rank, p.meaning_ordinal, p.item_ordinal, p.entry_id, p.source_path) AS rn
        FROM page_fields p
        JOIN dictionary_search_documents s ON s.entry_id = p.entry_id
        JOIN dictionaries d ON d.id = p.dictionary_id
    ),
    payloads AS (
        SELECT
            jsonb_build_object(
                'kind', 'field-match',
                'resultKey', entry_id::text || ':' || source_path,
                'entry', jsonb_strip_nulls(jsonb_build_object(
                    'id', entry_id,
                    'languageCode', language_code,
                    'headword', headword,
                    'meaningId', meaning_id,
                    'partOfSpeech', part_of_speech,
                    'summaryDefinition', summary_definition
                )),
                'dictionary', jsonb_strip_nulls(jsonb_build_object(
                    'id', dictionary_id,
                    'slug', dictionary_slug,
                    'name', dictionary_name,
                    'kind', dictionary_kind
                )),
                'field', jsonb_strip_nulls(jsonb_build_object(
                    'kind', COALESCE(field_kind, field_group),
                    'group', field_group,
                    'sourcePath', source_path,
                    'text', display_text
                )),
                'match', jsonb_build_object('matchedText', v_raw_query)
            ) AS payload,
            jsonb_build_object(
                'group', v_group,
                'rank', rank,
                'meaningOrdinal', meaning_ordinal,
                'itemOrdinal', item_ordinal,
                'entryId', entry_id,
                'sourcePath', source_path
            ) AS cursor_payload,
            rn
        FROM hydrated
        WHERE rn <= v_limit
    )
    SELECT
        COALESCE(jsonb_agg(payload ORDER BY rn), '[]'::jsonb),
        EXISTS(SELECT 1 FROM hydrated WHERE rn > v_limit),
        (array_agg(cursor_payload ORDER BY rn DESC))[1]
    INTO v_items, v_has_more, v_last
    FROM payloads;

    IF v_has_more AND v_last IS NOT NULL THEN
        v_next_cursor := private.encode_dictionary_search_cursor_v1(v_last);
    END IF;

    RETURN jsonb_build_object(
        'id', v_group,
        'total', NULL,
        'count', jsonb_build_object('value', NULL, 'relation', 'unknown'),
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object('limit', v_limit, 'nextCursor', v_next_cursor, 'hasMore', COALESCE(v_has_more, false))
    );
END;
$_$;


--
-- Name: search_dictionary_group_keyset_v1(uuid, boolean, text, text, uuid[], text, integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.search_dictionary_group_keyset_v1(p_user_id uuid, p_public_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_group text DEFAULT 'headwords'::text, p_limit integer DEFAULT 6, p_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_group text := COALESCE(NULLIF(trim(p_group), ''), 'headwords');
BEGIN
    IF v_group = 'headwords' THEN
        RETURN private.search_dictionary_headwords_group_v1(
            p_user_id, p_public_catalog, p_query, p_language_code, p_dictionary_ids, p_limit, p_cursor
        );
    END IF;

    IF v_group IN ('examples', 'definitions') THEN
        RETURN private.search_dictionary_body_group_v1(
            p_user_id, p_public_catalog, p_query, p_language_code, p_dictionary_ids, v_group, p_limit, p_cursor
        );
    END IF;

    IF v_group = 'alphabetical' THEN
        RETURN private.search_dictionary_alphabetical_group_v1(
            p_user_id, p_public_catalog, p_query, p_language_code, p_dictionary_ids, p_limit, p_cursor
        );
    END IF;

    RETURN private.search_dictionary_group_v1(
        p_user_id, p_public_catalog, p_query, p_language_code, p_dictionary_ids, v_group, p_limit, p_cursor
    );
END;
$$;


--
-- Name: search_dictionary_group_v1(uuid, boolean, text, text, uuid[], text, integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.search_dictionary_group_v1(p_user_id uuid, p_public_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_group text DEFAULT 'headwords'::text, p_limit integer DEFAULT 6, p_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_like_query text;
    v_ts_query tsquery;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_group text := COALESCE(NULLIF(trim(p_group), ''), 'headwords');
    v_limit int := LEAST(GREATEST(COALESCE(p_limit, 6), 1), 100);
    v_cursor jsonb := private.decode_dictionary_search_cursor_v1(p_cursor);
    v_items jsonb := '[]'::jsonb;
    v_total int := 0;
    v_has_more boolean := false;
    v_next_cursor text := NULL;
    v_last jsonb;
BEGIN
    IF v_raw_query IS NULL THEN
        RETURN jsonb_build_object(
            'id', v_group,
            'total', 0,
            'items', '[]'::jsonb,
            'page', jsonb_build_object('limit', v_limit, 'nextCursor', NULL, 'hasMore', false)
        );
    END IF;

    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);
    v_like_query := '%' || v_query_unaccent || '%';
    v_ts_query := plainto_tsquery('simple', v_query_unaccent);

    IF v_group = 'headwords' THEN
        WITH eligible_dictionaries AS MATERIALIZED (
            SELECT d.id, d.slug, d.name, d.kind, d.visibility, d.owner_user_id
            FROM dictionaries d
            WHERE CASE
                WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
                ELSE p_user_id IS NOT NULL AND can_access_dictionary(p_user_id, d.id, 'read')
            END
        ),
        candidates AS MATERIALIZED (
            SELECT
                d.entry_id,
                d.dictionary_id,
                d.language_code,
                d.headword,
                d.meaning_id,
                d.part_of_speech,
                d.summary_definition,
                ed.slug AS dictionary_slug,
                ed.name AS dictionary_name,
                ed.kind AS dictionary_kind,
                'exact'::text AS relation,
                d.headword AS matched_text,
                'dictionary_search_documents.headword'::text AS source_path,
                CASE
                    WHEN d.headword = v_raw_query THEN 0
                    WHEN d.normalized_headword = v_query THEN 1
                    ELSE 2
                END AS rank
            FROM dictionary_search_documents d
            JOIN eligible_dictionaries ed ON ed.id = d.dictionary_id
            WHERE (v_language_code IS NULL OR d.language_code = v_language_code)
              AND (array_length(v_dictionary_ids, 1) IS NULL OR d.dictionary_id = ANY(v_dictionary_ids))
              AND (
                  d.normalized_headword = v_query
                  OR d.normalized_headword_unaccent = v_query_unaccent
              )

            UNION ALL

            SELECT
                d.entry_id,
                d.dictionary_id,
                d.language_code,
                d.headword,
                d.meaning_id,
                d.part_of_speech,
                d.summary_definition,
                ed.slug,
                ed.name,
                ed.kind,
                'inflection',
                f.display_text,
                f.source_path,
                CASE
                    WHEN f.display_text = v_raw_query THEN 3
                    WHEN f.normalized_text = v_query THEN 4
                    ELSE 5
                END AS rank
            FROM dictionary_search_fields f
            JOIN dictionary_search_documents d ON d.entry_id = f.entry_id
            JOIN eligible_dictionaries ed ON ed.id = d.dictionary_id
            WHERE f.field_group = 'form'
              AND (v_language_code IS NULL OR d.language_code = v_language_code)
              AND (array_length(v_dictionary_ids, 1) IS NULL OR d.dictionary_id = ANY(v_dictionary_ids))
              AND (
                  f.normalized_text = v_query
                  OR f.normalized_text_unaccent = v_query_unaccent
              )
        ),
        deduped AS MATERIALIZED (
            SELECT DISTINCT ON (entry_id)
                *,
                lower(headword) AS headword_sort
            FROM candidates
            ORDER BY entry_id, rank, lower(headword), meaning_id
        ),
        counted AS (
            SELECT COUNT(*)::int AS total FROM deduped
        ),
        page_rows AS (
            SELECT *
            FROM deduped
            WHERE (v_cursor = '{}'::jsonb)
               OR (rank, headword_sort, meaning_id, entry_id) >
                  (
                    COALESCE((v_cursor->>'rank')::int, -1),
                    COALESCE(v_cursor->>'headwordSort', ''),
                    COALESCE((v_cursor->>'meaningId')::int, -1),
                    COALESCE((v_cursor->>'entryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid)
                  )
            ORDER BY rank, headword_sort, meaning_id, entry_id
            LIMIT v_limit + 1
        ),
        visible_page AS (
            SELECT *, row_number() OVER () AS rn FROM page_rows
        ),
        payloads AS (
            SELECT
                jsonb_build_object(
                    'kind', 'entry',
                    'entry', jsonb_strip_nulls(jsonb_build_object(
                        'id', entry_id,
                        'languageCode', language_code,
                        'headword', headword,
                        'meaningId', meaning_id,
                        'partOfSpeech', part_of_speech,
                        'summaryDefinition', summary_definition
                    )),
                    'dictionary', jsonb_strip_nulls(jsonb_build_object(
                        'id', dictionary_id,
                        'slug', dictionary_slug,
                        'name', dictionary_name,
                        'kind', dictionary_kind
                    )),
                    'match', jsonb_strip_nulls(jsonb_build_object(
                        'relation', relation,
                        'matchedText', matched_text,
                        'sourcePath', source_path
                    ))
                ) AS payload,
                jsonb_build_object(
                    'group', v_group,
                    'rank', rank,
                    'headwordSort', headword_sort,
                    'meaningId', meaning_id,
                    'entryId', entry_id
                ) AS cursor_payload,
                rn
            FROM visible_page
            WHERE rn <= v_limit
        )
        SELECT
            counted.total,
            COALESCE(jsonb_agg(payload ORDER BY rn), '[]'::jsonb),
            EXISTS(SELECT 1 FROM visible_page WHERE rn > v_limit),
            (array_agg(cursor_payload ORDER BY rn DESC))[1]
        INTO v_total, v_items, v_has_more, v_last
        FROM counted
        LEFT JOIN payloads ON true
        GROUP BY counted.total;

    ELSIF v_group IN ('examples', 'definitions') THEN
        WITH eligible_dictionaries AS MATERIALIZED (
            SELECT d.id, d.slug, d.name, d.kind, d.visibility, d.owner_user_id
            FROM dictionaries d
            WHERE CASE
                WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
                ELSE p_user_id IS NOT NULL AND can_access_dictionary(p_user_id, d.id, 'read')
            END
        ),
        matches AS MATERIALIZED (
            SELECT
                d.entry_id,
                d.dictionary_id,
                d.language_code,
                d.headword,
                d.meaning_id,
                d.part_of_speech,
                d.summary_definition,
                ed.slug AS dictionary_slug,
                ed.name AS dictionary_name,
                ed.kind AS dictionary_kind,
                f.field_group,
                f.field_kind,
                f.display_text,
                f.source_path,
                f.ordinal,
                lower(d.headword) AS headword_sort,
                CASE WHEN f.field_tsv @@ v_ts_query THEN 0 ELSE 1 END AS rank
            FROM dictionary_search_fields f
            JOIN dictionary_search_documents d ON d.entry_id = f.entry_id
            JOIN eligible_dictionaries ed ON ed.id = d.dictionary_id
            WHERE (v_language_code IS NULL OR d.language_code = v_language_code)
              AND (array_length(v_dictionary_ids, 1) IS NULL OR d.dictionary_id = ANY(v_dictionary_ids))
              AND (
                  CASE
                      WHEN v_group = 'examples' THEN f.field_group IN ('example', 'idiom')
                      ELSE f.field_group IN ('definition', 'context', 'note')
                  END
              )
              AND (
                  f.field_tsv @@ v_ts_query
                  OR f.normalized_text_unaccent LIKE v_like_query
              )
        ),
        counted AS (
            SELECT COUNT(*)::int AS total FROM matches
        ),
        page_rows AS (
            SELECT *
            FROM matches
            WHERE (v_cursor = '{}'::jsonb)
               OR (rank, headword_sort, meaning_id, entry_id, source_path) >
                  (
                    COALESCE((v_cursor->>'rank')::int, -1),
                    COALESCE(v_cursor->>'headwordSort', ''),
                    COALESCE((v_cursor->>'meaningId')::int, -1),
                    COALESCE((v_cursor->>'entryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid),
                    COALESCE(v_cursor->>'sourcePath', '')
                  )
            ORDER BY rank, headword_sort, meaning_id, entry_id, source_path
            LIMIT v_limit + 1
        ),
        visible_page AS (
            SELECT *, row_number() OVER () AS rn FROM page_rows
        ),
        payloads AS (
            SELECT
                jsonb_build_object(
                    'kind', 'field-match',
                    'resultKey', entry_id::text || ':' || source_path,
                    'entry', jsonb_strip_nulls(jsonb_build_object(
                        'id', entry_id,
                        'languageCode', language_code,
                        'headword', headword,
                        'meaningId', meaning_id,
                        'partOfSpeech', part_of_speech,
                        'summaryDefinition', summary_definition
                    )),
                    'dictionary', jsonb_strip_nulls(jsonb_build_object(
                        'id', dictionary_id,
                        'slug', dictionary_slug,
                        'name', dictionary_name,
                        'kind', dictionary_kind
                    )),
                    'field', jsonb_strip_nulls(jsonb_build_object(
                        'kind', COALESCE(field_kind, field_group),
                        'group', field_group,
                        'sourcePath', source_path,
                        'text', display_text
                    )),
                    'match', jsonb_build_object('matchedText', v_raw_query)
                ) AS payload,
                jsonb_build_object(
                    'group', v_group,
                    'rank', rank,
                    'headwordSort', headword_sort,
                    'meaningId', meaning_id,
                    'entryId', entry_id,
                    'sourcePath', source_path
                ) AS cursor_payload,
                rn
            FROM visible_page
            WHERE rn <= v_limit
        )
        SELECT
            counted.total,
            COALESCE(jsonb_agg(payload ORDER BY rn), '[]'::jsonb),
            EXISTS(SELECT 1 FROM visible_page WHERE rn > v_limit),
            (array_agg(cursor_payload ORDER BY rn DESC))[1]
        INTO v_total, v_items, v_has_more, v_last
        FROM counted
        LEFT JOIN payloads ON true
        GROUP BY counted.total;

    ELSIF v_group = 'alphabetical' THEN
        WITH eligible_dictionaries AS MATERIALIZED (
            SELECT d.id, d.slug, d.name, d.kind, d.visibility, d.owner_user_id
            FROM dictionaries d
            WHERE CASE
                WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
                ELSE p_user_id IS NOT NULL AND can_access_dictionary(p_user_id, d.id, 'read')
            END
        ),
        docs AS MATERIALIZED (
            SELECT
                d.entry_id,
                d.dictionary_id,
                d.language_code,
                d.headword,
                d.meaning_id,
                d.part_of_speech,
                d.summary_definition,
                d.normalized_headword_unaccent,
                ed.slug AS dictionary_slug,
                ed.name AS dictionary_name,
                ed.kind AS dictionary_kind
            FROM dictionary_search_documents d
            JOIN eligible_dictionaries ed ON ed.id = d.dictionary_id
            WHERE (v_language_code IS NULL OR d.language_code = v_language_code)
              AND (array_length(v_dictionary_ids, 1) IS NULL OR d.dictionary_id = ANY(v_dictionary_ids))
        ),
        counted AS (
            SELECT COUNT(*)::int AS total FROM docs
        ),
        page_rows AS (
            SELECT *
            FROM docs
            WHERE (
                    v_cursor <> '{}'::jsonb
                    AND (normalized_headword_unaccent, meaning_id, entry_id) >
                        (
                            COALESCE(v_cursor->>'headwordSort', ''),
                            COALESCE((v_cursor->>'meaningId')::int, -1),
                            COALESCE((v_cursor->>'entryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid)
                        )
                  )
               OR (
                    v_cursor = '{}'::jsonb
                    AND normalized_headword_unaccent >= v_query_unaccent
                  )
            ORDER BY normalized_headword_unaccent, meaning_id, entry_id
            LIMIT v_limit + 1
        ),
        visible_page AS (
            SELECT *, row_number() OVER () AS rn FROM page_rows
        ),
        payloads AS (
            SELECT
                jsonb_build_object(
                    'kind', 'entry',
                    'entry', jsonb_strip_nulls(jsonb_build_object(
                        'id', entry_id,
                        'languageCode', language_code,
                        'headword', headword,
                        'meaningId', meaning_id,
                        'partOfSpeech', part_of_speech,
                        'summaryDefinition', summary_definition
                    )),
                    'dictionary', jsonb_strip_nulls(jsonb_build_object(
                        'id', dictionary_id,
                        'slug', dictionary_slug,
                        'name', dictionary_name,
                        'kind', dictionary_kind
                    )),
                    'match', jsonb_build_object(
                        'relation', 'alphabetical',
                        'matchedText', headword,
                        'sourcePath', 'dictionary_search_documents.normalized_headword_unaccent'
                    )
                ) AS payload,
                jsonb_build_object(
                    'group', v_group,
                    'headwordSort', normalized_headword_unaccent,
                    'meaningId', meaning_id,
                    'entryId', entry_id
                ) AS cursor_payload,
                rn
            FROM visible_page
            WHERE rn <= v_limit
        )
        SELECT
            counted.total,
            COALESCE(jsonb_agg(payload ORDER BY rn), '[]'::jsonb),
            EXISTS(SELECT 1 FROM visible_page WHERE rn > v_limit),
            (array_agg(cursor_payload ORDER BY rn DESC))[1]
        INTO v_total, v_items, v_has_more, v_last
        FROM counted
        LEFT JOIN payloads ON true
        GROUP BY counted.total;

    ELSE
        RETURN jsonb_build_object(
            'id', v_group,
            'total', 0,
            'items', '[]'::jsonb,
            'page', jsonb_build_object('limit', v_limit, 'nextCursor', NULL, 'hasMore', false)
        );
    END IF;

    IF v_has_more AND v_last IS NOT NULL THEN
        v_next_cursor := private.encode_dictionary_search_cursor_v1(v_last);
    END IF;

    RETURN jsonb_build_object(
        'id', v_group,
        'total', COALESCE(v_total, 0),
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object(
            'limit', v_limit,
            'nextCursor', v_next_cursor,
            'hasMore', COALESCE(v_has_more, false)
        )
    );
END;
$$;


--
-- Name: search_dictionary_headwords_group_v1(uuid, boolean, text, text, uuid[], integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.search_dictionary_headwords_group_v1(p_user_id uuid, p_public_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 6, p_cursor text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query text;
    v_query_unaccent text;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_limit int := LEAST(GREATEST(COALESCE(p_limit, 6), 1), 100);
    v_cursor jsonb := private.decode_dictionary_search_cursor_v1(p_cursor);
    v_items jsonb := '[]'::jsonb;
    v_total int := 0;
    v_has_more boolean := false;
    v_next_cursor text := NULL;
    v_last jsonb;
BEGIN
    IF v_raw_query IS NULL THEN
        RETURN jsonb_build_object(
            'id', 'headwords',
            'total', 0,
            'count', jsonb_build_object('value', 0, 'relation', 'eq'),
            'items', '[]'::jsonb,
            'page', jsonb_build_object('limit', v_limit, 'nextCursor', NULL, 'hasMore', false)
        );
    END IF;

    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);

    WITH eligible_dictionaries AS MATERIALIZED (
        SELECT d.id, d.slug, d.name, d.kind
        FROM dictionaries d
        WHERE CASE
            WHEN p_public_catalog THEN d.visibility IN ('system', 'public')
            ELSE p_user_id IS NOT NULL AND can_browse_dictionary(p_user_id, d.id, 'read')
        END
          AND (array_length(v_dictionary_ids, 1) IS NULL OR d.id = ANY(v_dictionary_ids))
    ),
    headword_candidates AS MATERIALIZED (
        SELECT *
        FROM (
            SELECT
                s.entry_id,
                s.dictionary_id,
                s.language_code,
                s.headword,
                s.meaning_id,
                s.part_of_speech,
                s.summary_definition,
                s.normalized_headword,
                ed.slug AS dictionary_slug,
                ed.name AS dictionary_name,
                ed.kind AS dictionary_kind,
                'exact'::text AS relation,
                s.headword AS matched_text,
                'dictionary_search_documents.headword'::text AS source_path,
                CASE
                    WHEN s.headword = v_raw_query THEN 0
                    WHEN s.normalized_headword = v_query THEN 1
                    ELSE 2
                END AS rank
            FROM dictionary_search_documents s
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE (v_language_code IS NULL OR s.language_code = v_language_code)
              AND s.normalized_headword = v_query

            UNION ALL

            SELECT
                s.entry_id,
                s.dictionary_id,
                s.language_code,
                s.headword,
                s.meaning_id,
                s.part_of_speech,
                s.summary_definition,
                s.normalized_headword,
                ed.slug,
                ed.name,
                ed.kind,
                'exact',
                s.headword,
                'dictionary_search_documents.headword',
                CASE
                    WHEN s.headword = v_raw_query THEN 0
                    WHEN s.normalized_headword = v_query THEN 1
                    ELSE 2
                END AS rank
            FROM dictionary_search_documents s
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE (v_language_code IS NULL OR s.language_code = v_language_code)
              AND s.normalized_headword_unaccent = v_query_unaccent
              AND s.normalized_headword <> v_query
        ) matches
    ),
    form_candidates AS MATERIALIZED (
        SELECT DISTINCT ON (entry_id)
            entry_id,
            dictionary_id,
            language_code,
            headword,
            meaning_id,
            part_of_speech,
            summary_definition,
            normalized_headword,
            dictionary_slug,
            dictionary_name,
            dictionary_kind,
            relation,
            matched_text,
            source_path,
            rank
        FROM (
            SELECT
                s.entry_id,
                s.dictionary_id,
                s.language_code,
                s.headword,
                s.meaning_id,
                s.part_of_speech,
                s.summary_definition,
                s.normalized_headword,
                ed.slug AS dictionary_slug,
                ed.name AS dictionary_name,
                ed.kind AS dictionary_kind,
                'inflection'::text AS relation,
                f.display_text AS matched_text,
                f.source_path,
                CASE
                    WHEN f.display_text = v_raw_query THEN 3
                    WHEN f.normalized_text = v_query THEN 4
                    ELSE 5
                END AS rank
            FROM dictionary_search_fields f
            JOIN dictionary_search_documents s ON s.entry_id = f.entry_id
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
              AND f.field_group = 'form'
              AND (v_language_code IS NULL OR f.language_code = v_language_code)
              AND f.normalized_text = v_query

            UNION ALL

            SELECT
                s.entry_id,
                s.dictionary_id,
                s.language_code,
                s.headword,
                s.meaning_id,
                s.part_of_speech,
                s.summary_definition,
                s.normalized_headword,
                ed.slug,
                ed.name,
                ed.kind,
                'inflection',
                f.display_text,
                f.source_path,
                CASE
                    WHEN f.display_text = v_raw_query THEN 3
                    WHEN f.normalized_text = v_query THEN 4
                    ELSE 5
                END AS rank
            FROM dictionary_search_fields f
            JOIN dictionary_search_documents s ON s.entry_id = f.entry_id
            JOIN eligible_dictionaries ed ON ed.id = s.dictionary_id
            WHERE NOT EXISTS (SELECT 1 FROM headword_candidates)
              AND f.field_group = 'form'
              AND (v_language_code IS NULL OR f.language_code = v_language_code)
              AND f.normalized_text_unaccent = v_query_unaccent
              AND f.normalized_text <> v_query
        ) matches
        ORDER BY entry_id, rank, normalized_headword, meaning_id
    ),
    deduped AS MATERIALIZED (
        SELECT DISTINCT ON (entry_id) *
        FROM (
            SELECT * FROM headword_candidates
            UNION ALL
            SELECT * FROM form_candidates
        ) candidates
        ORDER BY entry_id, rank, normalized_headword, meaning_id
    ),
    counted AS (
        SELECT COUNT(*)::int AS total FROM deduped
    ),
    page_rows AS (
        SELECT *
        FROM deduped
        WHERE (v_cursor = '{}'::jsonb)
           OR (rank, normalized_headword, meaning_id, entry_id) >
              (
                COALESCE((v_cursor->>'rank')::int, -1),
                COALESCE(v_cursor->>'headwordSort', ''),
                COALESCE((v_cursor->>'meaningId')::int, -1),
                COALESCE((v_cursor->>'entryId')::uuid, '00000000-0000-0000-0000-000000000000'::uuid)
              )
        ORDER BY rank, normalized_headword, meaning_id, entry_id
        LIMIT v_limit + 1
    ),
    visible_page AS (
        SELECT *, row_number() OVER () AS rn FROM page_rows
    ),
    payloads AS (
        SELECT
            jsonb_build_object(
                'kind', 'entry',
                'entry', jsonb_strip_nulls(jsonb_build_object(
                    'id', entry_id,
                    'languageCode', language_code,
                    'headword', headword,
                    'meaningId', meaning_id,
                    'partOfSpeech', part_of_speech,
                    'summaryDefinition', summary_definition
                )),
                'dictionary', jsonb_strip_nulls(jsonb_build_object(
                    'id', dictionary_id,
                    'slug', dictionary_slug,
                    'name', dictionary_name,
                    'kind', dictionary_kind
                )),
                'match', jsonb_strip_nulls(jsonb_build_object(
                    'relation', relation,
                    'matchedText', matched_text,
                    'sourcePath', source_path
                ))
            ) AS payload,
            jsonb_build_object(
                'group', 'headwords',
                'rank', rank,
                'headwordSort', normalized_headword,
                'meaningId', meaning_id,
                'entryId', entry_id
            ) AS cursor_payload,
            rn
        FROM visible_page
        WHERE rn <= v_limit
    )
    SELECT
        counted.total,
        COALESCE(jsonb_agg(payload ORDER BY rn), '[]'::jsonb),
        EXISTS(SELECT 1 FROM visible_page WHERE rn > v_limit),
        (array_agg(cursor_payload ORDER BY rn DESC))[1]
    INTO v_total, v_items, v_has_more, v_last
    FROM counted
    LEFT JOIN payloads ON true
    GROUP BY counted.total;

    IF v_has_more AND v_last IS NOT NULL THEN
        v_next_cursor := private.encode_dictionary_search_cursor_v1(v_last);
    END IF;

    RETURN jsonb_build_object(
        'id', 'headwords',
        'total', COALESCE(v_total, 0),
        'count', jsonb_build_object('value', COALESCE(v_total, 0), 'relation', 'eq'),
        'items', COALESCE(v_items, '[]'::jsonb),
        'page', jsonb_build_object('limit', v_limit, 'nextCursor', v_next_cursor, 'hasMore', COALESCE(v_has_more, false))
    );
END;
$$;


--
-- Name: send_app_event_v1(text, text, text, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.send_app_event_v1(p_topic text, p_kind text, p_resource text DEFAULT NULL::text, p_language text DEFAULT NULL::text, p_revision text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE dedupe text := 'app_event.sent_' || md5(p_topic || ':' || p_kind);
BEGIN
  -- Domain-wide user hints are coalesced per transaction. No durable delivery
  -- promise: reconnect reads and degraded polling recover missed messages.
  IF current_setting(dedupe, true) = txid_current()::text THEN RETURN; END IF;
  PERFORM set_config(dedupe, txid_current()::text, true);
  PERFORM realtime.send(jsonb_strip_nulls(jsonb_build_object(
    'version', 1, 'eventId', gen_random_uuid(), 'kind', p_kind,
    'resourceId', p_resource, 'language', p_language,
    'revision', p_revision, 'occurredAt', clock_timestamp())), 'app-event', p_topic, true);
EXCEPTION WHEN OTHERS THEN
  -- Realtime availability must never turn an accepted learning action into a failure.
  RAISE WARNING 'app_event_delivery_failed: %', SQLSTATE;
END $$;


--
-- Name: set_received_collection_labels_v1(uuid, bigint, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.set_received_collection_labels_v1(p_collection_id uuid, p_expected_revision bigint, p_label_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); root private.collection_sharing_roots%rowtype;
 revision integer; requested uuid[]; previous uuid[];
BEGIN
 IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF p_collection_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision NOT BETWEEN 0 AND 2147483646
   OR p_label_ids IS NULL OR cardinality(p_label_ids)>1000 OR COALESCE(array_ndims(p_label_ids),1)<>1 OR array_position(p_label_ids,NULL) IS NOT NULL THEN
  RAISE EXCEPTION 'invalid_label_operation' USING ERRCODE='22023';
 END IF;
 -- Preliminary access check avoids locking an outsider's arbitrary resource.
 IF NOT EXISTS(SELECT 1 FROM private.live_collection_sharing_subscriptions_v1 scope
  WHERE scope.user_id=principal AND scope.collection_id=p_collection_id AND scope.owner_user_id<>principal) THEN
  RAISE EXCEPTION 'collection_not_found' USING ERRCODE='42501';
 END IF;
 PERFORM 1 FROM auth.users WHERE id=principal FOR KEY SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 PERFORM 1 FROM public.user_word_lists WHERE id=p_collection_id FOR KEY SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'collection_not_found' USING ERRCODE='42501'; END IF;
 SELECT * INTO root FROM private.collection_sharing_roots r WHERE r.collection_id=p_collection_id FOR SHARE;
 IF NOT FOUND OR root.owner_user_id=principal OR NOT root.is_open OR NOT EXISTS(
  SELECT 1 FROM private.collection_sharing_subscriptions s WHERE s.user_id=principal AND s.root_id=root.id
   AND s.is_active AND s.access_lifetime=root.access_lifetime
 ) THEN RAISE EXCEPTION 'collection_not_found' USING ERRCODE='42501'; END IF;
 -- Recipient account -> source collection -> root -> own label catalog.
 -- Label deletion never takes sharing-root locks.
 INSERT INTO private.collection_label_catalogs(user_id) VALUES(principal) ON CONFLICT DO NOTHING;
 SELECT c.revision INTO revision FROM private.collection_label_catalogs c WHERE c.user_id=principal FOR UPDATE;
 IF revision<>p_expected_revision THEN RAISE EXCEPTION 'label_catalog_conflict' USING ERRCODE='40001'; END IF;
 SELECT COALESCE(array_agg(DISTINCT id ORDER BY id),ARRAY[]::uuid[]) INTO requested FROM unnest(p_label_ids) id;
 IF EXISTS(SELECT 1 FROM unnest(requested) requested_label(id) WHERE NOT EXISTS(
  SELECT 1 FROM private.collection_labels label WHERE label.user_id=principal AND label.id=requested_label.id
 )) THEN RAISE EXCEPTION 'label_not_found' USING ERRCODE='22023'; END IF;
 SELECT COALESCE(array_agg(label_id ORDER BY label_id),ARRAY[]::uuid[]) INTO previous
 FROM private.received_collection_label_placements WHERE user_id=principal AND collection_id=p_collection_id;
 IF requested IS DISTINCT FROM previous THEN
  IF revision>=2147483646 OR (SELECT count(*) FROM private.received_collection_label_placements WHERE user_id=principal)
    -cardinality(previous)+cardinality(requested)>10000 THEN
   RAISE EXCEPTION 'label_catalog_limit' USING ERRCODE='22023';
  END IF;
  DELETE FROM private.received_collection_label_placements WHERE user_id=principal AND collection_id=p_collection_id;
  INSERT INTO private.received_collection_label_placements(user_id,collection_id,label_id)
   SELECT principal,p_collection_id,id FROM unnest(requested) id;
  UPDATE private.collection_label_catalogs c SET revision=c.revision+1 WHERE c.user_id=principal RETURNING c.revision INTO revision;
 END IF;
 RETURN jsonb_build_object('collectionId',p_collection_id,'revision',revision,'labelIds',to_jsonb(requested));
END;
$$;


--
-- Name: shared_author_entry_ids_v1(uuid, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.shared_author_entry_ids_v1(p_user_id uuid, p_entry_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(entry_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT DISTINCT member.entry_id FROM private.shared_author_entry_memberships_v1 member
    WHERE p_entry_ids IS NULL AND member.user_id=p_user_id
  UNION ALL
  SELECT DISTINCT member.entry_id FROM private.shared_author_entry_memberships_v1 member
    WHERE p_entry_ids IS NOT NULL AND member.user_id=p_user_id AND member.entry_id=ANY(p_entry_ids)
$$;


--
-- Name: shared_collection_ids_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.shared_collection_ids_v1(p_user_id uuid) RETURNS TABLE(collection_id uuid, owner_user_id uuid, root_id uuid)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT scope.collection_id,scope.owner_user_id,scope.root_id
  FROM private.live_collection_sharing_subscriptions_v1 scope WHERE scope.user_id=p_user_id
$$;


--
-- Name: shared_instructional_raw_v1(jsonb, text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.shared_instructional_raw_v1(p_value jsonb, p_context text DEFAULT 'entry'::text, p_depth integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'private', 'pg_temp'
    AS $$
DECLARE result jsonb:='{}'; key text; value jsonb; context text; normalized_key text;
BEGIN
  IF p_depth>12 THEN RAISE EXCEPTION 'shared_content_unsupported' USING ERRCODE='22023'; END IF;
  IF jsonb_typeof(p_value)='array' AND p_context NOT IN ('entry','string','number','literal') THEN
    SELECT COALESCE(jsonb_agg(private.shared_instructional_raw_v1(item,p_context,p_depth+1) ORDER BY ordinal),'[]')
      INTO result FROM jsonb_array_elements(p_value) WITH ORDINALITY element(item,ordinal);
  ELSIF jsonb_typeof(p_value)<>'object' THEN
    RETURN CASE WHEN p_context IN ('map','literal')
      OR (p_context IN ('text','string','idiom','alternate','reference') AND jsonb_typeof(p_value) IN ('string','null'))
      OR (p_context='number' AND jsonb_typeof(p_value) IN ('number','null')) THEN p_value ELSE 'null'::jsonb END;
  ELSIF p_context IN ('text','string','number','literal') THEN RETURN 'null'::jsonb;
  ELSE
    FOR key,value IN SELECT * FROM jsonb_each(p_value) LOOP
      context:=NULL;
      IF p_context='entry' THEN
        IF key=ANY(ARRAY['headword','languageCode','language_code','meaning_id','meaningId','part_of_speech','partOfSpeech','gender',
          'definition','notes','plural','diminutive','verb_forms','inflected_form','comparative','superlative','derivations',
          'pronunciation','pronunciation_ipa','pronunciation_with_stress','displayPronunciation','homograph_number','images']) THEN
          context:=CASE WHEN key=ANY(ARRAY['meaning_id','meaningId','homograph_number']) THEN 'number'
            WHEN key=ANY(ARRAY['plural','diminutive','verb_forms','inflected_form','comparative','superlative','derivations','images']) THEN 'text' ELSE 'string' END;
        ELSIF key='meanings' THEN context:='meaning';
        ELSIF key='example' THEN context:='example';
        ELSIF key='translation' THEN context:='translation';
        ELSIF key='alternate_headwords' THEN context:='alternate';
        ELSIF key='cross_reference' THEN context:='reference';
        ELSIF key='reference_tables' THEN context:='reference-table';
        ELSIF key=ANY(ARRAY['source_identity','_source']) THEN context:='header-identity';
        ELSIF key=ANY(ARRAY['conjugation_table','morphology','audio_links']) THEN context:='map'; END IF;
      ELSIF p_context='meaning' THEN
        IF key=ANY(ARRAY['definition','text','context','note','pronunciation_note','examples','synonyms','antonyms','usage_labels']) THEN
          context:=CASE WHEN key=ANY(ARRAY['examples','synonyms','antonyms','usage_labels']) THEN 'text' ELSE 'string' END;
        ELSIF key='idioms' THEN context:='idiom';
        ELSIF key='cross_references' THEN context:='reference';
        ELSIF key=ANY(ARRAY['translations','grammar']) THEN context:='flat-map'; END IF;
      ELSIF p_context='example' AND key=ANY(ARRAY['source','translation']) THEN context:='string';
      ELSIF p_context='translation' AND key=ANY(ARRAY['text','languageCode']) THEN context:='string';
      ELSIF p_context='idiom' AND key=ANY(ARRAY['expression','explanation','examples']) THEN context:=CASE WHEN key='examples' THEN 'text' ELSE 'string' END;
      ELSIF p_context='alternate' AND key=ANY(ARRAY['headword','gender','plural']) THEN context:='string';
      ELSIF p_context='reference' AND key='headword' THEN context:='string';
      ELSIF p_context='reference-table' AND key='title' THEN context:='string';
      ELSIF p_context='reference-table' AND key='rows' THEN context:='reference-row';
      ELSIF p_context='reference-row' AND key=ANY(ARRAY['label','value']) THEN context:='string';
      ELSIF p_context='header-identity' AND key='homograph_number' THEN context:='number';
      ELSIF p_context='flat-map' THEN
        -- These labels and scalar values are rendered instructional data.
        -- Opaque nested objects are not part of the flat grammar/translation contract.
        IF jsonb_typeof(value) IN ('string','number','boolean','null') THEN context:='literal';
        ELSIF jsonb_typeof(value)='array' THEN context:='text'; END IF;
      ELSIF p_context='map' THEN
        -- Dynamic morphology/conjugation/asset keys are instructional by contract;
        -- reserved technical containers must still never travel through them.
        normalized_key:=lower(regexp_replace(key,'[_-]','','g'));
        IF normalized_key<>ALL(ARRAY['generation','source','sourcecontext','contexttext','connectedclientid',
          'sourceentryid','sourcecontextversion','sourceversion','draftsetid','candidateid','promptversion','generatedat','contentfingerprint',
          'diagnostics','debug','provider','model','metadata','sourcemeta']) THEN context:='map'; END IF;
      END IF;
      IF context IS NOT NULL THEN result:=result||jsonb_build_object(key,private.shared_instructional_raw_v1(value,context,p_depth+1)); END IF;
    END LOOP;
  END IF;
  IF octet_length(result::text)>1048576 THEN RAISE EXCEPTION 'shared_content_unsupported' USING ERRCODE='22023'; END IF;
  RETURN result;
END;
$$;


--
-- Name: shared_meaning_other_direction(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.shared_meaning_other_direction(p_card_type_id text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
    SELECT CASE p_card_type_id
        WHEN 'word-to-definition' THEN 'definition-to-word'
        WHEN 'definition-to-word' THEN 'word-to-definition'
        ELSE NULL
    END;
$$;


--
-- Name: simple_user_entry_content_nodes_v1(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.simple_user_entry_content_nodes_v1(p_raw jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_nodes jsonb := '[]'::jsonb;
    v_text text;
BEGIN
    v_text := NULLIF(trim(p_raw->>'definition'), '');
    IF v_text IS NOT NULL THEN
        v_nodes := v_nodes || jsonb_build_array(jsonb_build_object(
            'inputKey', 'definition',
            'kind', 'definition',
            'sourcePath', 'raw.definition',
            'sourceNativeKey', 'user-entry-v1:definition',
            'sourceTextFingerprint',
                encode(digest('definition' || chr(31) || v_text, 'sha256'), 'hex'),
            'sourceText', normalize(v_text, NFC)
        ));
    END IF;

    v_text := NULLIF(trim(p_raw#>>'{example,source}'), '');
    IF v_text IS NOT NULL THEN
        v_nodes := v_nodes || jsonb_build_array(jsonb_build_object(
            'inputKey', 'example',
            'kind', 'example',
            'sourcePath', 'raw.example.source',
            'sourceNativeKey', 'user-entry-v1:example',
            'sourceTextFingerprint',
                encode(digest('example' || chr(31) || v_text, 'sha256'), 'hex'),
            'sourceText', normalize(v_text, NFC)
        ));
    END IF;

    v_text := NULLIF(trim(p_raw->>'notes'), '');
    IF v_text IS NOT NULL THEN
        v_nodes := v_nodes || jsonb_build_array(jsonb_build_object(
            'inputKey', 'notes',
            'kind', 'usage-note',
            'sourcePath', 'raw.notes',
            'sourceNativeKey', 'user-entry-v1:notes',
            'sourceTextFingerprint',
                encode(digest('usage-note' || chr(31) || v_text, 'sha256'), 'hex'),
            'sourceText', normalize(v_text, NFC)
        ));
    END IF;

    RETURN v_nodes;
END;
$$;


--
-- Name: start_platform_v2_idiom_training_session_v1(uuid, text, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.start_platform_v2_idiom_training_session_v1(p_user_id uuid, p_direction text, p_session_size text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_session_id uuid := gen_random_uuid();
    v_filter jsonb;
    v_size text := COALESCE(NULLIF(btrim(p_session_size), ''), '10');
    v_requested_total integer;
    v_request_hash text;
    v_receipt public.training_exercise_run_start_receipts%rowtype;
    v_candidate jsonb;
    v_candidates jsonb[] := ARRAY[]::jsonb[];
    v_candidate_offset integer := 0;
    v_candidate_page_size integer;
    v_candidate_page_count integer;
    v_candidate_count integer := 0;
    v_candidate_new_count integer := 0;
    v_candidate_review_count integer := 0;
    v_saw_practice boolean;
    v_new_candidates jsonb[] := ARRAY[]::jsonb[];
    v_review_candidates jsonb[] := ARRAY[]::jsonb[];
    v_new_index integer := 1;
    v_review_index integer := 1;
    v_reviews_since_new integer := 0;
    v_ratio integer := 2;
    v_target_id uuid;
    v_queue_source text;
    v_ordinal integer := 0;
    v_planned_new integer;
    v_planned_review integer;
    v_planned_total integer;
    v_now timestamptz := private.training_reference_now_v1();
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;
    IF p_direction NOT IN ('direct', 'reverse') THEN
        RAISE EXCEPTION 'invalid_idiom_exercise_direction';
    END IF;
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION 'missing_idiom_training_session_request_id';
    END IF;
    IF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
        RAISE EXCEPTION 'invalid idiom training session size: %', v_size;
    END IF;
    v_requested_total := v_size::integer;
    v_request_hash := encode(digest(jsonb_build_object(
        'exerciseFamily', 'idiom',
        'direction', p_direction,
        'sessionSize', v_size
    )::text, 'sha256'), 'hex');

    -- The same request is safe to retry. The receipt does not reclaim an old
    -- run; it returns that run's authoritative status.
    PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));
    SELECT *
      INTO v_receipt
      FROM public.training_exercise_run_start_receipts AS receipt
     WHERE receipt.user_id = p_user_id
       AND receipt.request_id = p_request_id
     FOR UPDATE;
    IF FOUND THEN
        IF v_receipt.request_hash IS DISTINCT FROM v_request_hash THEN
            RAISE EXCEPTION 'idiom_training_session_start_idempotency_conflict';
        END IF;
        RETURN private.training_idiom_session_response_v1(p_user_id, v_receipt.session_id);
    END IF;

    v_filter := private.resolve_training_material_selection_v1(p_user_id,NULL,'curated','{}'::jsonb);

    INSERT INTO public.training_sessions (
        id,
        user_id,
        exercise_family,
        session_size,
        card_type_ids,
        list_type,
        card_filter,
        training_filter,
        requested_total,
        created_at
    ) VALUES (
        v_session_id,
        p_user_id,
        'idiom',
        v_size,
        ARRAY['idiom:' || p_direction],
        'curated',
        'both',
        v_filter,
        v_requested_total,
        v_now
    );

    -- Candidate ordering and eligibility remain owned by migration 154. The
    -- loop pages until it has enough candidates from both immediate queues.
    -- The candidate RPC sorts practice last; once that tail is observed there
    -- cannot be another new/review row, so the loop does not scan the whole
    -- future-practice pool.
    LOOP
        v_candidate_page_size := LEAST(100, v_requested_total);
        EXIT WHEN v_candidate_page_size <= 0;
        v_candidate_page_count := 0;
        v_saw_practice := false;

        FOR v_candidate IN
            SELECT candidate.item
              FROM private.platform_v2_idiom_exercise_candidates_v1_with_material(
                  v_filter, p_user_id,
                  p_direction,
                  v_candidate_page_size,
                  v_candidate_offset
              ) AS candidate(item)
        LOOP
            v_candidate_page_count := v_candidate_page_count + 1;
            IF v_candidate->>'queueSource' = 'practice' THEN
                v_saw_practice := true;
            ELSIF v_candidate->>'queueSource' = 'new' THEN
                v_candidates := array_append(v_candidates, v_candidate);
                v_candidate_count := v_candidate_count + 1;
                v_candidate_new_count := v_candidate_new_count + 1;
            ELSIF v_candidate->>'queueSource' IN ('learning', 'review') THEN
                v_candidates := array_append(v_candidates, v_candidate);
                v_candidate_count := v_candidate_count + 1;
                v_candidate_review_count := v_candidate_review_count + 1;
            END IF;
        END LOOP;

        EXIT WHEN v_candidate_page_count = 0
            OR (
                v_candidate_new_count >= v_requested_total
                AND v_candidate_review_count >= v_requested_total
            )
            OR v_saw_practice;
        v_candidate_offset := v_candidate_offset + v_candidate_page_size;
    END LOOP;

    -- Reuse the learner's soft new/review preference. It is a preference for
    -- ordering, never a quota: whichever category is available is used.
    FOR v_candidate IN SELECT item FROM unnest(v_candidates) AS item LOOP
        IF v_candidate->>'queueSource' = 'new' THEN
            v_new_candidates := array_append(v_new_candidates, v_candidate);
        ELSE
            v_review_candidates := array_append(v_review_candidates, v_candidate);
        END IF;
    END LOOP;

    SELECT LEAST(5, GREATEST(1, COALESCE(settings.new_review_ratio, 2)))::integer
      INTO v_ratio
      FROM public.user_settings AS settings
     WHERE settings.user_id = p_user_id;
    v_ratio := COALESCE(v_ratio, 2);

    WHILE v_ordinal < v_requested_total
      AND (
          v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0)
          OR v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0)
      )
    LOOP
        IF v_ordinal = 0
           AND v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSIF v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0)
              AND (
                  v_new_index > COALESCE(array_length(v_new_candidates, 1), 0)
                  OR v_reviews_since_new < v_ratio
              ) THEN
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        ELSIF v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSE
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        END IF;

        v_target_id := NULLIF(v_candidate->>'targetId', '')::uuid;
        v_queue_source := NULLIF(v_candidate->>'queueSource', '');
        IF v_target_id IS NULL
           OR v_queue_source IS NULL
           OR v_queue_source NOT IN ('new', 'learning', 'review') THEN
            RAISE EXCEPTION 'invalid_idiom_session_candidate';
        END IF;
        v_ordinal := v_ordinal + 1;
        INSERT INTO public.training_session_exercise_members (
            session_id, target_id, ordinal, queue_source
        ) VALUES (
            v_session_id, v_target_id, v_ordinal, v_queue_source
        );
    END LOOP;

    SELECT count(*) FILTER (WHERE queue_source = 'new')::integer,
           count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer,
           count(*)::integer
      INTO v_planned_new, v_planned_review, v_planned_total
      FROM public.training_session_exercise_members AS member
     WHERE member.session_id = v_session_id;

    UPDATE public.training_sessions
       SET planned_new = COALESCE(v_planned_new, 0),
           planned_review = COALESCE(v_planned_review, 0),
           planned_practice = 0,
           planned_total = COALESCE(v_planned_total, 0),
           completed_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           exhausted_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           completion_reason = CASE
               WHEN COALESCE(v_planned_total, 0) = 0 THEN 'exhausted'
           END
     WHERE id = v_session_id;

    INSERT INTO public.training_exercise_run_start_receipts (
        user_id, request_id, exercise_family, direction, session_size,
        request_hash, session_id, created_at
    ) VALUES (
        p_user_id, p_request_id, 'idiom', p_direction, v_size,
        v_request_hash, v_session_id, v_now
    );

    RETURN private.training_idiom_session_response_v1(p_user_id, v_session_id);
END;
$_$;


--
-- Name: start_platform_v2_idiom_training_session_v2(uuid, text, text, uuid, uuid, text, text, jsonb, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.start_platform_v2_idiom_training_session_v2(p_user_id uuid, p_direction text, p_session_size text, p_request_id uuid, p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_new_review_ratio integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_session_id uuid := gen_random_uuid();
    v_size text := COALESCE(NULLIF(btrim(p_session_size), ''), '10');
    v_filter jsonb := COALESCE(p_training_filter, '{}'::jsonb);
    v_requested_total integer;
    v_request_hash text;
    v_receipt public.training_exercise_run_start_receipts%rowtype;
    v_candidate jsonb;
    v_candidates jsonb[] := ARRAY[]::jsonb[];
    v_new_candidates jsonb[] := ARRAY[]::jsonb[];
    v_review_candidates jsonb[] := ARRAY[]::jsonb[];
    v_new_index integer := 1;
    v_review_index integer := 1;
    v_reviews_since_new integer := 0;
    v_ratio integer := 2;
    v_target_id uuid;
    v_queue_source text;
    v_ordinal integer := 0;
    v_planned_new integer;
    v_planned_review integer;
    v_planned_total integer;
    v_now timestamptz := private.training_reference_now_v1();
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;
    IF p_direction IS NULL OR p_direction NOT IN ('direct', 'reverse', 'mixed') THEN
        RAISE EXCEPTION 'invalid_idiom_exercise_direction';
    END IF;
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION 'missing_idiom_training_session_request_id';
    END IF;
    IF p_card_filter NOT IN ('new', 'review', 'both') THEN
        RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
    END IF;
    IF p_new_review_ratio IS NULL OR p_new_review_ratio NOT BETWEEN 1 AND 5 THEN
        RAISE EXCEPTION 'invalid new/review ratio: %', p_new_review_ratio;
    END IF;
    IF jsonb_typeof(v_filter) <> 'object' THEN
        RAISE EXCEPTION 'invalid_training_filter';
    END IF;
    PERFORM private.training_review_early_v1(v_filter,p_card_filter);
    IF v_size='all-due-today' AND private.training_review_early_v1(v_filter,p_card_filter) THEN
        v_requested_total := 2147483647;
    ELSIF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
        RAISE EXCEPTION 'invalid idiom training session size: %', v_size;
    END IF;
    IF v_size<>'all-due-today' THEN v_requested_total := v_size::integer; END IF;
    -- A single-queue run never uses the rhythm. Match the ordinary Training
    -- contract so irrelevant slider values do not change retry identity.
    v_ratio := CASE WHEN p_card_filter = 'both' THEN p_new_review_ratio ELSE 2 END;

    -- These arrays describe selections, not an order. Canonicalize before
    -- storing and hashing so a reordered retry returns the original run.
    IF jsonb_typeof(v_filter->'partOfSpeech') = 'array' THEN
        v_filter := jsonb_set(v_filter, '{partOfSpeech}', (
            SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
            FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(
                v_filter->'partOfSpeech'
            ) AS item(value)) AS selected
        ));
    END IF;
    IF jsonb_typeof(v_filter->'nounArticles') = 'array' THEN
        v_filter := jsonb_set(v_filter, '{nounArticles}', (
            SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
            FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(
                v_filter->'nounArticles'
            ) AS item(value)) AS selected
        ));
    END IF;
    IF jsonb_typeof(v_filter #> '{dictionaryScope,dictionaryIds}') = 'array' THEN
        v_filter := jsonb_set(v_filter, '{dictionaryScope,dictionaryIds}', (
            SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
            FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(
                v_filter #> '{dictionaryScope,dictionaryIds}'
            ) AS item(value)) AS selected
        ));
    END IF;
    v_request_hash := encode(digest(jsonb_build_object(
        'exerciseFamily', 'idiom',
        'direction', p_direction,
        'sessionSize', v_size,
        'listId', p_list_id,
        'listType', COALESCE(p_list_type, 'curated'),
        'cardFilter', p_card_filter,
        'trainingFilter', v_filter,
        'newReviewRatio', v_ratio
    )::text, 'sha256'), 'hex');

    -- The same request is safe to retry. The receipt does not reclaim an old
    -- run; it returns that run's authoritative status.
    PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));
    SELECT *
      INTO v_receipt
      FROM public.training_exercise_run_start_receipts AS receipt
     WHERE receipt.user_id = p_user_id
       AND receipt.request_id = p_request_id
     FOR UPDATE;
    IF FOUND THEN
        IF v_receipt.request_hash IS DISTINCT FROM v_request_hash THEN
            RAISE EXCEPTION 'idiom_training_session_start_idempotency_conflict';
        END IF;
        RETURN private.training_idiom_session_response_v1(p_user_id, v_receipt.session_id);
    END IF;

    v_filter := private.resolve_training_material_selection_v1(p_user_id,p_list_id,p_list_type,v_filter);

    INSERT INTO public.training_sessions (
        id,
        user_id,
        exercise_family,
        session_size,
        card_type_ids,
        list_id,
        list_type,
        card_filter,
        training_filter,
        requested_total,
        new_review_ratio,
        created_at
    ) VALUES (
        v_session_id,
        p_user_id,
        'idiom',
        v_size,
        CASE WHEN p_direction = 'mixed' THEN ARRAY['idiom:direct','idiom:reverse']
          ELSE ARRAY['idiom:' || p_direction] END,
        p_list_id,
        COALESCE(p_list_type, 'curated'),
        p_card_filter,
        v_filter,
        v_requested_total,
        v_ratio,
        v_now
    );

    -- One candidate read limits each immediate queue independently. A skewed
    -- pool cannot trigger repeated corpus/group scans just to fill the other
    -- side of the optional rhythm.
    FOR v_candidate IN
        SELECT candidate.item
          FROM unnest(CASE WHEN p_direction = 'mixed'
                    THEN ARRAY['direct','reverse'] ELSE ARRAY[p_direction] END)
               WITH ORDINALITY AS selected(direction, direction_order)
          CROSS JOIN LATERAL private.platform_v2_idiom_exercise_candidates_v2(
              p_user_id, selected.direction, v_requested_total, 0,
              p_list_id, p_list_type, p_card_filter, v_filter
          ) WITH ORDINALITY AS candidate(item, position)
          -- Round-robin the bounded directional pools, then retain the existing
          -- new/review rhythm. A missing direction never prevents filling a run.
          ORDER BY CASE WHEN private.training_review_early_v1(v_filter,p_card_filter)
                     THEN (candidate.item#>>'{state,nextReviewAt}')::timestamptz END,
                   candidate.position, selected.direction_order
    LOOP
        IF v_candidate->>'queueSource' = 'new' THEN
            v_candidates := array_append(v_candidates, v_candidate);
        ELSIF v_candidate->>'queueSource' IN ('learning', 'review') THEN
            v_candidates := array_append(v_candidates, v_candidate);
        END IF;
    END LOOP;

    -- Apply the selected soft new/review rhythm. It is a preference for
    -- ordering, never a quota: whichever category is available is used.
    FOR v_candidate IN SELECT item FROM unnest(v_candidates) AS item LOOP
        IF v_candidate->>'queueSource' = 'new' THEN
            v_new_candidates := array_append(v_new_candidates, v_candidate);
        ELSE
            v_review_candidates := array_append(v_review_candidates, v_candidate);
        END IF;
    END LOOP;

    WHILE v_ordinal < v_requested_total
      AND (
          v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0)
          OR v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0)
      )
    LOOP
        IF v_ordinal = 0
           AND v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSIF v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0)
              AND (
                  v_new_index > COALESCE(array_length(v_new_candidates, 1), 0)
                  OR v_reviews_since_new < v_ratio
              ) THEN
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        ELSIF v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSE
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        END IF;

        v_target_id := NULLIF(v_candidate->>'targetId', '')::uuid;
        v_queue_source := NULLIF(v_candidate->>'queueSource', '');
        IF v_target_id IS NULL
           OR v_queue_source IS NULL
           OR v_queue_source NOT IN ('new', 'learning', 'review') THEN
            RAISE EXCEPTION 'invalid_idiom_session_candidate';
        END IF;
        v_ordinal := v_ordinal + 1;
        INSERT INTO public.training_session_exercise_members (
            session_id, target_id, ordinal, queue_source
        ) VALUES (
            v_session_id, v_target_id, v_ordinal, v_queue_source
        );
    END LOOP;

    SELECT count(*) FILTER (WHERE queue_source = 'new')::integer,
           count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer,
           count(*)::integer
      INTO v_planned_new, v_planned_review, v_planned_total
      FROM public.training_session_exercise_members AS member
     WHERE member.session_id = v_session_id;

    UPDATE public.training_sessions
       SET requested_total = CASE WHEN v_size='all-due-today' THEN COALESCE(v_planned_total,0) ELSE requested_total END,
           planned_new = COALESCE(v_planned_new, 0),
           planned_review = COALESCE(v_planned_review, 0),
           planned_practice = 0,
           planned_total = COALESCE(v_planned_total, 0),
           completed_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           exhausted_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           completion_reason = CASE
               WHEN COALESCE(v_planned_total, 0) = 0 THEN 'exhausted'
           END
     WHERE id = v_session_id;

    INSERT INTO public.training_exercise_run_start_receipts (
        user_id, request_id, exercise_family, direction, session_size,
        request_hash, session_id, created_at
    ) VALUES (
        p_user_id, p_request_id, 'idiom', p_direction, v_size,
        v_request_hash, v_session_id, v_now
    );

    RETURN private.training_idiom_session_response_v1(p_user_id, v_session_id);
END;
$_$;


--
-- Name: start_platform_v2_translation_training_session_v1(uuid, text, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.start_platform_v2_translation_training_session_v1(p_user_id uuid, p_session_size text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_session_id uuid := gen_random_uuid();
    v_filter jsonb;
    v_size text := COALESCE(NULLIF(btrim(p_session_size), ''), '10');
    v_requested_total integer;
    v_request_hash text;
    v_receipt public.training_exercise_run_start_receipts%rowtype;
    v_candidate jsonb;
    v_candidates jsonb[] := ARRAY[]::jsonb[];
    v_new_candidates jsonb[] := ARRAY[]::jsonb[];
    v_review_candidates jsonb[] := ARRAY[]::jsonb[];
    v_new_index integer := 1;
    v_review_index integer := 1;
    v_reviews_since_new integer := 0;
    v_ratio integer := 2;
    v_target_id uuid;
    v_queue_source text;
    v_ordinal integer := 0;
    v_planned_new integer;
    v_planned_review integer;
    v_planned_total integer;
    v_now timestamptz := private.training_reference_now_v1();
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;
    IF p_request_id IS NULL THEN RAISE EXCEPTION 'missing_translation_training_session_request_id'; END IF;
    IF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
        RAISE EXCEPTION 'invalid translation training session size: %', v_size;
    END IF;
    v_requested_total := v_size::integer;
    v_request_hash := encode(digest(jsonb_build_object(
        'exerciseFamily', 'translation',
        'direction', 'recall',
        'sessionSize', v_size
    )::text, 'sha256'), 'hex');

    PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));
    SELECT * INTO v_receipt
      FROM public.training_exercise_run_start_receipts AS receipt
     WHERE receipt.user_id = p_user_id AND receipt.request_id = p_request_id
     FOR UPDATE;
    IF FOUND THEN
        IF v_receipt.request_hash IS DISTINCT FROM v_request_hash THEN
            RAISE EXCEPTION 'translation_training_session_start_idempotency_conflict';
        END IF;
        RETURN private.training_translation_session_response_v1(p_user_id, v_receipt.session_id);
    END IF;

    v_filter := private.resolve_training_material_selection_v1(p_user_id,NULL,'curated','{}'::jsonb);

    INSERT INTO public.training_sessions (
        id, user_id, exercise_family, session_size, card_type_ids,
        list_type, card_filter, training_filter, requested_total, created_at
    ) VALUES (
        v_session_id, p_user_id, 'translation', v_size, ARRAY['translation:recall'],
        'curated', 'both', v_filter, v_requested_total, v_now
    );

    -- Request more than the final size so the soft new/review preference can
    -- still be applied without treating either category as a quota.
    FOR v_candidate IN
        SELECT candidate.item
          FROM private.platform_v2_translation_exercise_candidates_v1_with_material(
              v_filter, p_user_id, LEAST(1000, GREATEST(100, v_requested_total * 8)), 0
          ) AS candidate(item)
    LOOP
        EXIT WHEN v_candidate->>'queueSource' = 'practice';
        IF v_candidate->>'queueSource' = 'new' THEN
            v_new_candidates := array_append(v_new_candidates, v_candidate);
        ELSIF v_candidate->>'queueSource' IN ('learning', 'review') THEN
            v_review_candidates := array_append(v_review_candidates, v_candidate);
        END IF;
    END LOOP;

    SELECT LEAST(5, GREATEST(1, COALESCE(settings.new_review_ratio, 2)))::integer
      INTO v_ratio
      FROM public.user_settings AS settings
     WHERE settings.user_id = p_user_id;
    v_ratio := COALESCE(v_ratio, 2);

    WHILE v_ordinal < v_requested_total
      AND (v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0)
           OR v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0))
    LOOP
        IF v_ordinal = 0
           AND v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSIF v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0)
              AND (v_new_index > COALESCE(array_length(v_new_candidates, 1), 0)
                   OR v_reviews_since_new < v_ratio) THEN
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        ELSIF v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSE
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        END IF;

        v_target_id := NULLIF(v_candidate->>'targetId', '')::uuid;
        v_queue_source := NULLIF(v_candidate->>'queueSource', '');
        IF v_target_id IS NULL OR v_queue_source NOT IN ('new', 'learning', 'review') THEN
            RAISE EXCEPTION 'invalid_translation_session_candidate';
        END IF;
        v_ordinal := v_ordinal + 1;
        INSERT INTO public.training_session_exercise_members(session_id, target_id, ordinal, queue_source)
        VALUES (v_session_id, v_target_id, v_ordinal, v_queue_source);
    END LOOP;

    SELECT count(*) FILTER (WHERE queue_source = 'new')::integer,
           count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer,
           count(*)::integer
      INTO v_planned_new, v_planned_review, v_planned_total
      FROM public.training_session_exercise_members
     WHERE session_id = v_session_id;
    UPDATE public.training_sessions
       SET planned_new = COALESCE(v_planned_new, 0),
           planned_review = COALESCE(v_planned_review, 0),
           planned_practice = 0,
           planned_total = COALESCE(v_planned_total, 0),
           completed_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           exhausted_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           completion_reason = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN 'exhausted' END
     WHERE id = v_session_id;

    INSERT INTO public.training_exercise_run_start_receipts(
        user_id, request_id, exercise_family, direction, session_size,
        request_hash, session_id, created_at
    ) VALUES (
        p_user_id, p_request_id, 'translation', 'recall', v_size,
        v_request_hash, v_session_id, v_now
    );
    RETURN private.training_translation_session_response_v1(p_user_id, v_session_id);
END;
$_$;


--
-- Name: start_platform_v2_translation_training_session_v2(uuid, text, uuid, uuid, text, text, jsonb, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.start_platform_v2_translation_training_session_v2(p_user_id uuid, p_session_size text, p_request_id uuid, p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_new_review_ratio integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_session_id uuid := gen_random_uuid();
    v_size text := COALESCE(NULLIF(btrim(p_session_size), ''), '10');
    v_filter jsonb := COALESCE(p_training_filter, '{}'::jsonb);
    v_requested_total integer;
    v_request_hash text;
    v_receipt public.training_exercise_run_start_receipts%rowtype;
    v_candidate jsonb;
    v_candidates jsonb[] := ARRAY[]::jsonb[];
    v_new_candidates jsonb[] := ARRAY[]::jsonb[];
    v_review_candidates jsonb[] := ARRAY[]::jsonb[];
    v_new_index integer := 1;
    v_review_index integer := 1;
    v_reviews_since_new integer := 0;
    v_ratio integer := 2;
    v_target_id uuid;
    v_queue_source text;
    v_ordinal integer := 0;
    v_planned_new integer;
    v_planned_review integer;
    v_planned_total integer;
    v_now timestamptz := private.training_reference_now_v1();
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;
    IF p_request_id IS NULL THEN
        RAISE EXCEPTION 'missing_translation_training_session_request_id';
    END IF;
    IF p_card_filter IS NULL OR p_card_filter NOT IN ('new', 'review', 'both') THEN
        RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
    END IF;
    IF p_new_review_ratio IS NULL OR p_new_review_ratio NOT BETWEEN 1 AND 5 THEN
        RAISE EXCEPTION 'invalid new/review ratio: %', p_new_review_ratio;
    END IF;
    IF jsonb_typeof(v_filter) <> 'object' THEN
        RAISE EXCEPTION 'invalid_training_filter';
    END IF;
    IF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
        RAISE EXCEPTION 'invalid translation training session size: %', v_size;
    END IF;
    v_requested_total := v_size::integer;
    -- A single-queue run never uses the rhythm. Match the ordinary Training
    -- contract so irrelevant slider values do not change retry identity.
    v_ratio := CASE WHEN p_card_filter = 'both' THEN p_new_review_ratio ELSE 2 END;

    -- These arrays describe selections, not an order. Canonicalize before
    -- storing and hashing so a reordered retry returns the original run.
    IF jsonb_typeof(v_filter->'partOfSpeech') = 'array' THEN
        v_filter := jsonb_set(v_filter, '{partOfSpeech}', (
            SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
            FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(
                v_filter->'partOfSpeech'
            ) AS item(value)) AS selected
        ));
    END IF;
    IF jsonb_typeof(v_filter->'nounArticles') = 'array' THEN
        v_filter := jsonb_set(v_filter, '{nounArticles}', (
            SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
            FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(
                v_filter->'nounArticles'
            ) AS item(value)) AS selected
        ));
    END IF;
    IF jsonb_typeof(v_filter #> '{dictionaryScope,dictionaryIds}') = 'array' THEN
        v_filter := jsonb_set(v_filter, '{dictionaryScope,dictionaryIds}', (
            SELECT COALESCE(jsonb_agg(value ORDER BY value), '[]'::jsonb)
            FROM (SELECT DISTINCT value FROM jsonb_array_elements_text(
                v_filter #> '{dictionaryScope,dictionaryIds}'
            ) AS item(value)) AS selected
        ));
    END IF;
    v_request_hash := encode(digest(jsonb_build_object(
        'exerciseFamily', 'translation',
        'direction', 'recall',
        'sessionSize', v_size,
        'listId', p_list_id,
        'listType', COALESCE(p_list_type, 'curated'),
        'cardFilter', p_card_filter,
        'trainingFilter', v_filter,
        'newReviewRatio', v_ratio
    )::text, 'sha256'), 'hex');

    -- The same request is safe to retry. The receipt does not reclaim an old
    -- run; it returns that run's authoritative status.
    PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));
    SELECT *
      INTO v_receipt
      FROM public.training_exercise_run_start_receipts AS receipt
     WHERE receipt.user_id = p_user_id
       AND receipt.request_id = p_request_id
     FOR UPDATE;
    IF FOUND THEN
        IF v_receipt.request_hash IS DISTINCT FROM v_request_hash THEN
            RAISE EXCEPTION 'translation_training_session_start_idempotency_conflict';
        END IF;
        RETURN private.training_translation_session_response_v1(p_user_id, v_receipt.session_id);
    END IF;

    v_filter := private.resolve_training_material_selection_v1(p_user_id,p_list_id,p_list_type,v_filter);

    INSERT INTO public.training_sessions (
        id,
        user_id,
        exercise_family,
        session_size,
        card_type_ids,
        list_id,
        list_type,
        card_filter,
        training_filter,
        requested_total,
        new_review_ratio,
        created_at
    ) VALUES (
        v_session_id,
        p_user_id,
        'translation',
        v_size,
        ARRAY['translation:' || 'recall'],
        p_list_id,
        COALESCE(p_list_type, 'curated'),
        p_card_filter,
        v_filter,
        v_requested_total,
        v_ratio,
        v_now
    );

    -- One candidate read limits each immediate queue independently. A skewed
    -- pool cannot trigger repeated corpus/group scans just to fill the other
    -- side of the optional rhythm.
    FOR v_candidate IN
        SELECT candidate.item
          FROM private.platform_v2_translation_exercise_candidates_v2(
              p_user_id, v_requested_total, 0,
              p_list_id, p_list_type, p_card_filter, v_filter
          ) AS candidate(item)
    LOOP
        IF v_candidate->>'queueSource' = 'new' THEN
            v_candidates := array_append(v_candidates, v_candidate);
        ELSIF v_candidate->>'queueSource' IN ('learning', 'review') THEN
            v_candidates := array_append(v_candidates, v_candidate);
        END IF;
    END LOOP;

    -- Apply the selected soft new/review rhythm. It is a preference for
    -- ordering, never a quota: whichever category is available is used.
    FOR v_candidate IN SELECT item FROM unnest(v_candidates) AS item LOOP
        IF v_candidate->>'queueSource' = 'new' THEN
            v_new_candidates := array_append(v_new_candidates, v_candidate);
        ELSE
            v_review_candidates := array_append(v_review_candidates, v_candidate);
        END IF;
    END LOOP;

    WHILE v_ordinal < v_requested_total
      AND (
          v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0)
          OR v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0)
      )
    LOOP
        IF v_ordinal = 0
           AND v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSIF v_review_index <= COALESCE(array_length(v_review_candidates, 1), 0)
              AND (
                  v_new_index > COALESCE(array_length(v_new_candidates, 1), 0)
                  OR v_reviews_since_new < v_ratio
              ) THEN
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        ELSIF v_new_index <= COALESCE(array_length(v_new_candidates, 1), 0) THEN
            v_candidate := v_new_candidates[v_new_index];
            v_new_index := v_new_index + 1;
            v_reviews_since_new := 0;
        ELSE
            v_candidate := v_review_candidates[v_review_index];
            v_review_index := v_review_index + 1;
            v_reviews_since_new := v_reviews_since_new + 1;
        END IF;

        v_target_id := NULLIF(v_candidate->>'targetId', '')::uuid;
        v_queue_source := NULLIF(v_candidate->>'queueSource', '');
        IF v_target_id IS NULL
           OR v_queue_source IS NULL
           OR v_queue_source NOT IN ('new', 'learning', 'review') THEN
            RAISE EXCEPTION 'invalid_translation_session_candidate';
        END IF;
        v_ordinal := v_ordinal + 1;
        INSERT INTO public.training_session_exercise_members (
            session_id, target_id, ordinal, queue_source
        ) VALUES (
            v_session_id, v_target_id, v_ordinal, v_queue_source
        );
    END LOOP;

    SELECT count(*) FILTER (WHERE queue_source = 'new')::integer,
           count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer,
           count(*)::integer
      INTO v_planned_new, v_planned_review, v_planned_total
      FROM public.training_session_exercise_members AS member
     WHERE member.session_id = v_session_id;

    UPDATE public.training_sessions
       SET planned_new = COALESCE(v_planned_new, 0),
           planned_review = COALESCE(v_planned_review, 0),
           planned_practice = 0,
           planned_total = COALESCE(v_planned_total, 0),
           completed_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           exhausted_at = CASE WHEN COALESCE(v_planned_total, 0) = 0 THEN v_now END,
           completion_reason = CASE
               WHEN COALESCE(v_planned_total, 0) = 0 THEN 'exhausted'
           END
     WHERE id = v_session_id;

    INSERT INTO public.training_exercise_run_start_receipts (
        user_id, request_id, exercise_family, direction, session_size,
        request_hash, session_id, created_at
    ) VALUES (
        p_user_id, p_request_id, 'translation', 'recall', v_size,
        v_request_hash, v_session_id, v_now
    );

    RETURN private.training_translation_session_response_v1(p_user_id, v_session_id);
END;
$_$;


--
-- Name: start_training_session_latch_v1(uuid, text[], uuid, text, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.start_training_session_latch_v1(p_user_id uuid, p_card_type_ids text[] DEFAULT ARRAY['word-to-definition'::text], p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT 'curated'::text, p_card_filter text DEFAULT 'both'::text, p_training_filter jsonb DEFAULT '{}'::jsonb, p_session_size text DEFAULT '10'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
  v_session_id uuid := gen_random_uuid();
  v_filter jsonb := COALESCE(p_training_filter, '{}'::jsonb);
  v_modes text[] := COALESCE(
    ARRAY(
      SELECT DISTINCT trim(mode)
      FROM unnest(COALESCE(p_card_type_ids, ARRAY['word-to-definition']::text[])) requested(mode)
      WHERE trim(mode) <> ''
      ORDER BY 1
    ), ARRAY['word-to-definition']::text[]
  );
  v_size text := COALESCE(NULLIF(trim(p_session_size), ''), '10');
  v_requested_total integer;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF p_card_filter NOT IN ('new', 'review', 'both') THEN
    RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
  END IF;
  IF v_size = 'all-due-today' THEN
    v_requested_total := NULL;
  ELSIF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
    RAISE EXCEPTION 'invalid training session size: %', v_size;
  ELSE
    v_requested_total := v_size::integer;
  END IF;

  INSERT INTO public.training_sessions (
    id, user_id, session_size, card_type_ids, list_id, list_type,
    card_filter, training_filter, requested_total
  ) VALUES (
    v_session_id, p_user_id, v_size, v_modes, p_list_id,
    COALESCE(p_list_type, 'curated'), p_card_filter, v_filter,
    COALESCE(v_requested_total, 0)
  );

  INSERT INTO public.training_session_members (
    session_id, ordinal, entry_id, card_type_id, queue_source
  )
  SELECT v_session_id, member.session_ordinal,
    member.entry_id, member.card_type_id, member.queue_source
  FROM private.training_session_members_v1(
    p_user_id, v_modes, p_list_id, COALESCE(p_list_type, 'curated'),
    p_card_filter, v_filter, v_size
  ) member;

  UPDATE public.training_sessions session
  SET planned_new = counts.planned_new,
      planned_review = counts.planned_review,
      planned_practice = 0,
      planned_total = counts.planned_total,
      requested_total = COALESCE(v_requested_total, counts.planned_total),
      completed_at = CASE WHEN counts.planned_total = 0 THEN private.training_reference_now_v1() ELSE NULL END,
      exhausted_at = CASE WHEN counts.planned_total = 0 THEN private.training_reference_now_v1() ELSE NULL END,
      completion_reason = CASE WHEN counts.planned_total = 0 THEN 'exhausted' ELSE NULL END
  FROM (
    SELECT count(*) FILTER (WHERE queue_source = 'new')::integer AS planned_new,
      count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer AS planned_review,
      count(*)::integer AS planned_total
    FROM public.training_session_members member
    WHERE member.session_id = v_session_id
  ) counts
  WHERE session.id = v_session_id;

  RETURN (
    SELECT jsonb_build_object(
      'sessionId', session.id,
      'sessionSize', session.session_size,
      'requestedTotal', session.requested_total,
      'plannedNew', session.planned_new,
      'plannedReview', session.planned_review,
      'plannedPractice', session.planned_practice,
      'plannedTotal', session.planned_total,
      'plannedAt', session.created_at
    )
    FROM public.training_sessions session
    WHERE session.id = v_session_id
  );
END;
$_$;


--
-- Name: start_training_session_latch_v1(uuid, text[], uuid, text, text, jsonb, text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.start_training_session_latch_v1(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text, p_new_review_ratio integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
  v_session_id uuid := gen_random_uuid();
  v_filter jsonb := COALESCE(p_training_filter, '{}'::jsonb);
  v_modes text[] := COALESCE(
    ARRAY(
      SELECT DISTINCT trim(mode)
      FROM unnest(COALESCE(p_card_type_ids, ARRAY['word-to-definition']::text[])) requested(mode)
      WHERE trim(mode) <> ''
      ORDER BY 1
    ), ARRAY['word-to-definition']::text[]
  );
  v_size text := COALESCE(NULLIF(trim(p_session_size), ''), '10');
  v_requested_total integer;
  v_dictionary_mode text := NULLIF(trim(v_filter#>>'{dictionaryScope,mode}'), '');
  v_dictionary_language text := NULLIF(trim(v_filter#>>'{dictionaryScope,languageCode}'), '');
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF v_filter->>'presentationMode' = 'word-in-context'
     AND v_modes IS DISTINCT FROM ARRAY['definition-to-word']::text[] THEN
    RAISE EXCEPTION 'word_context_requires_reverse_mode';
  END IF;
  PERFORM private.training_review_early_v1(v_filter,p_card_filter);
  IF p_card_filter NOT IN ('new', 'review', 'both') THEN
    RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
  END IF;
  IF p_card_filter = 'both' AND (
    p_new_review_ratio IS NULL OR p_new_review_ratio NOT BETWEEN 1 AND 5
  ) THEN
    RAISE EXCEPTION 'invalid new/review ratio: %', p_new_review_ratio;
  END IF;
  IF v_size = 'all-due-today' THEN
    v_requested_total := NULL;
  ELSIF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
    RAISE EXCEPTION 'invalid training session size: %', v_size;
  ELSE
    v_requested_total := v_size::integer;
  END IF;

  v_filter := private.resolve_training_material_selection_v1(p_user_id,p_list_id,p_list_type,v_filter);

  IF v_filter ? 'dictionaryScope' THEN
    IF p_list_id IS NOT NULL
       OR v_dictionary_mode NOT IN ('all', 'selected')
       OR v_dictionary_mode IS NULL
       OR v_dictionary_language IS NULL THEN
      RAISE EXCEPTION 'training_material_unavailable';
    END IF;
    IF NOT EXISTS (
      SELECT 1
      FROM public.dictionaries dictionary
      WHERE dictionary.language_code = v_dictionary_language
        AND (public.can_access_dictionary(p_user_id,dictionary.id,'read') OR (
    dictionary.kind='user' AND EXISTS (SELECT 1 FROM private.shared_author_entry_memberships_v1 shared
      JOIN private.active_word_entries shared_entry ON shared_entry.id=shared.entry_id
      WHERE shared.user_id=p_user_id AND shared_entry.dictionary_id=dictionary.id)))
        AND (
          v_dictionary_mode = 'all'
          OR EXISTS (
            SELECT 1
            FROM jsonb_array_elements_text(
              CASE WHEN jsonb_typeof(v_filter#>'{dictionaryScope,dictionaryIds}') = 'array'
                THEN v_filter#>'{dictionaryScope,dictionaryIds}'
                ELSE '[]'::jsonb END
            ) requested(id)
            WHERE requested.id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
              AND requested.id::uuid = dictionary.id
          )
        )
    ) THEN
      RAISE EXCEPTION 'training_material_unavailable';
    END IF;
  END IF;

  INSERT INTO public.training_sessions (
    id, user_id, session_size, card_type_ids, list_id, list_type,
    card_filter, training_filter, requested_total, new_review_ratio
  ) VALUES (
    v_session_id, p_user_id, v_size, v_modes, p_list_id,
    COALESCE(p_list_type, 'curated'), p_card_filter, v_filter,
    COALESCE(v_requested_total, 0),
    CASE WHEN p_card_filter = 'both' THEN p_new_review_ratio ELSE 2 END
  );

  INSERT INTO public.training_session_members (
    session_id, ordinal, entry_id, card_type_id, queue_source
  )
  SELECT v_session_id, member.session_ordinal,
    member.entry_id, member.card_type_id, member.queue_source
  FROM private.training_session_members_v1(
    p_user_id, v_modes, p_list_id, COALESCE(p_list_type, 'curated'),
    p_card_filter, v_filter, v_size,
    CASE WHEN p_card_filter = 'both' THEN p_new_review_ratio ELSE 2 END
  ) member;

  IF v_filter->>'presentationMode' = 'word-in-context' THEN
    WITH examples AS (
      SELECT member.entry_id, node.id AS node_id,
             node.source_text_fingerprint,
             row_number() OVER (
               PARTITION BY member.entry_id
               ORDER BY node.source_order NULLS LAST, node.created_at, node.id
             ) - 1 AS example_index,
             count(*) OVER (PARTITION BY member.entry_id) AS example_count
      FROM public.training_session_members AS member
      JOIN private.platform_v2_content_nodes AS node
        ON node.entry_id = member.entry_id
       AND node.kind = 'example'
       AND node.binding_state = 'active'
       AND NULLIF(btrim(node.diagnostic_locator), '') IS NOT NULL
       AND node.diagnostic_locator ~ '^raw\.meanings\[[0-9]+\]\.examples\[[0-9]+\]$'
      WHERE member.session_id = v_session_id
    ), selected AS (
      SELECT examples.*
      FROM examples
      LEFT JOIN public.user_card_status AS reverse_state
        ON reverse_state.user_id = p_user_id
       AND reverse_state.entry_id = examples.entry_id
       AND reverse_state.card_type_id = 'definition-to-word'
      WHERE examples.example_index =
        mod(GREATEST(COALESCE(reverse_state.fsrs_reps,0),0)::bigint,
            examples.example_count)
    )
    UPDATE public.training_session_members AS member
    SET context_content_node_id = selected.node_id,
        context_source_text_fingerprint = selected.source_text_fingerprint
    FROM selected
    WHERE member.session_id = v_session_id
      AND member.entry_id = selected.entry_id
      AND member.card_type_id = 'definition-to-word';

    IF EXISTS (
      SELECT 1 FROM public.training_session_members AS member
      WHERE member.session_id = v_session_id
        AND (member.context_content_node_id IS NULL
          OR member.context_source_text_fingerprint IS NULL)
    ) THEN
      RAISE EXCEPTION 'word_context_example_unavailable';
    END IF;
  END IF;

  UPDATE public.training_sessions session
  SET planned_new = counts.planned_new,
      planned_review = counts.planned_review,
      planned_practice = 0,
      planned_total = counts.planned_total,
      requested_total = COALESCE(v_requested_total, counts.planned_total),
      completed_at = CASE WHEN counts.planned_total = 0 THEN private.training_reference_now_v1() ELSE NULL END,
      exhausted_at = CASE WHEN counts.planned_total = 0 THEN private.training_reference_now_v1() ELSE NULL END,
      completion_reason = CASE WHEN counts.planned_total = 0 THEN 'exhausted' ELSE NULL END
  FROM (
    SELECT count(*) FILTER (WHERE queue_source = 'new')::integer AS planned_new,
      count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer AS planned_review,
      count(*)::integer AS planned_total
    FROM public.training_session_members member
    WHERE member.session_id = v_session_id
  ) counts
  WHERE session.id = v_session_id;

  RETURN (
    SELECT jsonb_build_object(
      'sessionId', session.id,
      'sessionSize', session.session_size,
      'requestedTotal', session.requested_total,
      'plannedNew', session.planned_new,
      'plannedReview', session.planned_review,
      'plannedPractice', session.planned_practice,
      'plannedTotal', session.planned_total,
      'plannedAt', session.created_at
    )
    FROM public.training_sessions session
    WHERE session.id = v_session_id
  );
END;
$_$;


--
-- Name: sync_default_training_scope_entry_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_default_training_scope_entry_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF NEW.is_nt2_2000 = true
     AND NOT private.is_pointer_only_dictionary_entry_v1(NEW.raw) THEN
    INSERT INTO private.default_training_scope_entries_v1(entry_id, dictionary_id)
    VALUES (NEW.id, NEW.dictionary_id)
    ON CONFLICT (entry_id) DO UPDATE
    SET dictionary_id = EXCLUDED.dictionary_id;
  ELSE
    DELETE FROM private.default_training_scope_entries_v1
    WHERE entry_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_ordinary_meaning_known_activation_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_ordinary_meaning_known_activation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF NEW.card_type_id IN ('word-to-definition', 'definition-to-word')
     AND NEW.cleared_at IS NULL THEN
    PERFORM private.record_ordinary_meaning_activation_v1(
      NEW.user_id, NEW.entry_id
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_ordinary_meaning_status_activation_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_ordinary_meaning_status_activation_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_is_active boolean;
BEGIN
  IF NEW.card_type_id NOT IN ('word-to-definition', 'definition-to-word') THEN
    RETURN NEW;
  END IF;

  v_is_active := COALESCE(NEW.in_learning, false)
    OR COALESCE(NEW.fsrs_enabled, false)
    OR COALESCE(NEW.fsrs_reps, 0) > 0
    OR NEW.last_reviewed_at IS NOT NULL;
  IF v_is_active THEN
    PERFORM private.record_ordinary_meaning_activation_v1(
      NEW.user_id, NEW.entry_id
    );
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: sync_platform_v2_training_exercise_target_visibility_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_platform_v2_training_exercise_target_visibility_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
BEGIN
    IF NEW.binding_state = 'retired' THEN
        UPDATE private.platform_v2_training_exercise_targets
           SET visibility_state = 'retired',
               retired_at = COALESCE(retired_at, private.training_reference_now_v1()),
               retirement_reason = 'source-node-retired',
               updated_at = private.training_reference_now_v1()
         WHERE content_node_id = NEW.id
           AND visibility_state = 'active';
    ELSIF NEW.binding_state = 'active' THEN
        UPDATE private.platform_v2_training_exercise_targets target
           SET visibility_state = CASE
                   WHEN target.source_text_fingerprint = NEW.source_text_fingerprint
                       THEN 'active'
                   ELSE 'retired'
               END,
               retired_at = CASE
                   WHEN target.source_text_fingerprint = NEW.source_text_fingerprint
                       THEN NULL
                   ELSE COALESCE(target.retired_at, private.training_reference_now_v1())
               END,
               retirement_reason = CASE
                   WHEN target.source_text_fingerprint = NEW.source_text_fingerprint
                       THEN NULL
                   ELSE 'source-node-fingerprint-changed'
               END,
               updated_at = private.training_reference_now_v1()
         WHERE target.content_node_id = NEW.id
           AND (
               target.visibility_state IS DISTINCT FROM CASE
                   WHEN target.source_text_fingerprint = NEW.source_text_fingerprint
                       THEN 'active'
                   ELSE 'retired'
               END
               OR target.source_text_fingerprint = NEW.source_text_fingerprint
                   AND target.retired_at IS NOT NULL
           );
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: sync_shared_meaning_known_mark(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_shared_meaning_known_mark() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_other_card_type text := private.shared_meaning_other_direction(NEW.card_type_id);
BEGIN
    -- The sibling write below fires this trigger too. The originating mutation
    -- owns the entry-wide lock and performs the complete pair update.
    IF pg_trigger_depth() > 1 OR v_other_card_type IS NULL
       OR NEW.mark_scope <> 'meaning' THEN
        RETURN NEW;
    END IF;

    PERFORM pg_advisory_xact_lock(
        hashtext('shared-meaning-known:' || NEW.user_id::text || ':' || NEW.entry_id::text)
    );

    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.user_card_known_marks (
            id,
            user_id,
            entry_id,
            card_type_id,
            revision,
            marked_at,
            mark_event_id,
            mark_scope
        )
        SELECT
            gen_random_uuid(),
            NEW.user_id,
            NEW.entry_id,
            v_other_card_type,
            gen_random_uuid(),
            NEW.marked_at,
            NEW.mark_event_id,
            NEW.mark_scope
        WHERE NOT EXISTS (
            SELECT 1
            FROM public.user_card_known_marks sibling
            WHERE sibling.user_id = NEW.user_id
              AND sibling.entry_id = NEW.entry_id
              AND sibling.card_type_id = v_other_card_type
              AND sibling.cleared_at IS NULL
        );
    ELSIF OLD.cleared_at IS NULL AND NEW.cleared_at IS NOT NULL THEN
        UPDATE public.user_card_known_marks sibling
           SET cleared_at = NEW.cleared_at,
               undo_event_id = NEW.undo_event_id
         WHERE sibling.user_id = NEW.user_id
           AND sibling.entry_id = NEW.entry_id
           AND sibling.card_type_id = v_other_card_type
           AND sibling.mark_scope = 'meaning'
           AND sibling.mark_event_id = NEW.mark_event_id
           AND sibling.cleared_at IS NULL;
    END IF;

    -- A card state revision is a UI concurrency token. The scheduler payload is
    -- unchanged, but a sibling display must not retain an actionable stale
    -- Known capability after this entry-level decision.
    UPDATE public.user_card_status
       SET state_revision = gen_random_uuid()
     WHERE user_id = NEW.user_id
       AND entry_id = NEW.entry_id
       AND card_type_id = v_other_card_type;

    RETURN NEW;
END;
$$;


--
-- Name: sync_training_schedule_timezone_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_training_schedule_timezone_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_timezone text := NULLIF(trim(NEW.training_filter->>'timezone'), '');
BEGIN
  IF v_timezone IS NULL THEN
    RETURN NEW;
  END IF;

  UPDATE public.user_settings settings
  SET training_schedule_timezone = private.training_schedule_timezone_v1(v_timezone)
  WHERE settings.user_id = NEW.user_id;
  RETURN NEW;
END;
$$;


--
-- Name: sync_unrenderable_ordinary_direct_binding_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_unrenderable_ordinary_direct_binding_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF to_regclass('pg_temp.platform_v2_import_refresh_entries') IS NOT NULL THEN
    IF TG_OP <> 'INSERT' THEN
      INSERT INTO pg_temp.platform_v2_import_refresh_entries (entry_id)
      VALUES (OLD.word_entry_id)
      ON CONFLICT DO NOTHING;
      INSERT INTO pg_temp.platform_v2_import_refresh_groups (
        dictionary_id, identity_scheme_version, source_group_key
      ) VALUES (
        OLD.dictionary_id, OLD.identity_scheme_version, OLD.source_group_key
      ) ON CONFLICT DO NOTHING;
    END IF;
    IF TG_OP <> 'DELETE' THEN
      INSERT INTO pg_temp.platform_v2_import_refresh_entries (entry_id)
      VALUES (NEW.word_entry_id)
      ON CONFLICT DO NOTHING;
      INSERT INTO pg_temp.platform_v2_import_refresh_groups (
        dictionary_id, identity_scheme_version, source_group_key
      ) VALUES (
        NEW.dictionary_id, NEW.identity_scheme_version, NEW.source_group_key
      ) ON CONFLICT DO NOTHING;
    END IF;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  IF TG_OP <> 'INSERT' THEN
    PERFORM private.refresh_unrenderable_ordinary_direct_group_v1(
      OLD.dictionary_id, OLD.identity_scheme_version, OLD.source_group_key
    );
  END IF;
  IF TG_OP <> 'DELETE' THEN
    PERFORM private.refresh_unrenderable_ordinary_direct_group_v1(
      NEW.dictionary_id, NEW.identity_scheme_version, NEW.source_group_key
    );
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: sync_unrenderable_ordinary_direct_entry_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.sync_unrenderable_ordinary_direct_entry_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_binding private.source_entry_bindings%rowtype;
  v_entry_id uuid := CASE
    WHEN TG_OP = 'DELETE' THEN OLD.entry_id ELSE NEW.entry_id
  END;
BEGIN
  IF to_regclass('pg_temp.platform_v2_import_refresh_entries') IS NOT NULL THEN
    INSERT INTO pg_temp.platform_v2_import_refresh_entries (entry_id)
    VALUES (v_entry_id)
    ON CONFLICT DO NOTHING;

    INSERT INTO pg_temp.platform_v2_import_refresh_groups (
      dictionary_id, identity_scheme_version, source_group_key
    )
    SELECT binding.dictionary_id,
           binding.identity_scheme_version,
           binding.source_group_key
    FROM private.source_entry_bindings AS binding
    WHERE binding.word_entry_id = v_entry_id
      AND binding.binding_state = 'active'
    ON CONFLICT DO NOTHING;
    RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
  END IF;

  SELECT * INTO v_binding
  FROM private.source_entry_bindings AS binding
  WHERE binding.word_entry_id = v_entry_id
    AND binding.binding_state = 'active';
  IF FOUND THEN
    PERFORM private.refresh_unrenderable_ordinary_direct_group_v1(
      v_binding.dictionary_id,
      v_binding.identity_scheme_version,
      v_binding.source_group_key
    );
  ELSE
    PERFORM private.refresh_unrenderable_ordinary_direct_entry_v1(v_entry_id);
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END;
$$;


--
-- Name: training_authoritative_timezone_v1(uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_authoritative_timezone_v1(p_user_id uuid, p_requested_timezone text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT private.training_schedule_timezone_v1(
    CASE
      WHEN p_user_id IS NULL
        THEN COALESCE(NULLIF(trim(p_requested_timezone), ''), 'UTC')
      ELSE private.training_user_timezone_v1(p_user_id)
    END
  );
$$;


--
-- Name: FUNCTION training_authoritative_timezone_v1(p_user_id uuid, p_requested_timezone text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.training_authoritative_timezone_v1(p_user_id uuid, p_requested_timezone text) IS 'Returns the persisted learner timezone for authenticated scheduler/reporting paths; request timezone is only a fallback for unauthenticated internal calendar helpers.';


--
-- Name: training_calendar_local_date_v1(timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_calendar_local_date_v1(p_timestamp timestamp with time zone, p_timezone text) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT (
    p_timestamp AT TIME ZONE private.training_schedule_timezone_v1(p_timezone)
  )::date;
$$;


--
-- Name: FUNCTION training_calendar_local_date_v1(p_timestamp timestamp with time zone, p_timezone text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.training_calendar_local_date_v1(p_timestamp timestamp with time zone, p_timezone text) IS 'Calendar date helper retained for next-local-midnight introduction unlocks.';


--
-- Name: training_collection_catalog_cohort_v1(uuid, text, text, uuid, text, integer, uuid[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_collection_catalog_cohort_v1(p_user_id uuid, p_query text, p_language_code text, p_after_id uuid, p_after_key text, p_limit integer, p_collection_ids uuid[] DEFAULT NULL::uuid[]) RETURNS TABLE(collection_id uuid, collection_name text, ownership text, available_item_count bigint, name_key text, eligible boolean)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
 WITH resources AS MATERIALIZED (
  SELECT list.id,list.name,list.user_id AS owner_id,COALESCE(list.primary_language_code,list.language_code) AS language_code,
   'owned'::text AS ownership,lower(list.name) COLLATE "C" AS name_key
  FROM public.user_word_lists list WHERE list.user_id=p_user_id AND (p_collection_ids IS NULL OR list.id=ANY(p_collection_ids))
  UNION ALL
  SELECT list.id,list.name,scope.owner_user_id,COALESCE(list.primary_language_code,list.language_code),
   'received',lower(list.name) COLLATE "C"
  FROM private.live_collection_sharing_subscriptions_v1 scope
  JOIN public.user_word_lists list ON list.id=scope.collection_id
  WHERE scope.user_id=p_user_id AND scope.owner_user_id<>p_user_id AND (p_collection_ids IS NULL OR list.id=ANY(p_collection_ids))
 ), cohort AS MATERIALIZED (
  SELECT * FROM resources WHERE strpos(lower(name),lower(p_query))>0
   AND (p_after_id IS NULL OR (name_key,id)>(p_after_key COLLATE "C",p_after_id))
  ORDER BY name_key COLLATE "C",id LIMIT p_limit
 ), members AS MATERIALIZED (
  SELECT cohort.id AS collection_id,cohort.owner_id,cohort.ownership,entry.id,entry.dictionary_id,entry.management_kind,entry.language_code
  FROM cohort JOIN public.user_word_list_items item ON item.list_id=cohort.id
  JOIN private.active_word_entries entry ON entry.id=item.word_id
 ), dictionaries AS MATERIALIZED (
  SELECT dictionary.id,dictionary.kind,dictionary.owner_user_id,
   CASE WHEN dictionary.kind<>'user' THEN public.can_access_dictionary(p_user_id,dictionary.id,'read') ELSE false END AS readable
  FROM (SELECT DISTINCT dictionary_id FROM members) selected JOIN public.dictionaries dictionary ON dictionary.id=selected.dictionary_id
 ), borrowed AS MATERIALIZED (
  SELECT DISTINCT member.id FROM members member JOIN dictionaries dictionary ON dictionary.id=member.dictionary_id
  WHERE dictionary.kind='user' AND dictionary.owner_user_id<>p_user_id
   AND NOT(member.ownership='received' AND dictionary.owner_user_id=member.owner_id AND member.management_kind='user')
 ), borrowed_shared AS MATERIALIZED (
  SELECT DISTINCT grant_entry.entry_id FROM private.shared_author_entry_memberships_v1 grant_entry
  WHERE grant_entry.user_id=p_user_id AND grant_entry.entry_id IN(SELECT id FROM borrowed)
 ), counts AS MATERIALIZED (
  SELECT member.collection_id,count(*) FILTER(WHERE p_language_code IS NULL OR member.language_code=p_language_code) AS item_count,
   count(DISTINCT member.language_code) AS language_count
  FROM members member LEFT JOIN dictionaries dictionary ON dictionary.id=member.dictionary_id
  WHERE member.dictionary_id IS NULL OR dictionary.readable OR (dictionary.kind='user' AND
   (dictionary.owner_user_id=p_user_id OR
    (member.ownership='received' AND dictionary.owner_user_id=member.owner_id AND member.management_kind='user') OR
    member.id IN(SELECT entry_id FROM borrowed_shared)))
  GROUP BY member.collection_id
 ) SELECT cohort.id,cohort.name,cohort.ownership,COALESCE(counts.item_count,0),cohort.name_key,
   CASE WHEN cohort.ownership='received' THEN COALESCE(counts.item_count,0)>0
    ELSE p_language_code IS NULL OR cohort.language_code=p_language_code OR
     (COALESCE(counts.language_count,0)>1 AND COALESCE(counts.item_count,0)>0) END
 FROM cohort LEFT JOIN counts ON counts.collection_id=cohort.id
 ORDER BY cohort.name_key COLLATE "C",cohort.id
$$;


--
-- Name: training_extra_source_entries_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_extra_source_entries_v1(p_user_id uuid, p_list_id uuid, p_list_type text, p_training_filter jsonb) RETURNS TABLE(entry_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
  v_filter jsonb := COALESCE(p_training_filter, '{}'::jsonb);
  v_dictionary_scope jsonb;
  v_dictionary_mode text;
  v_dictionary_language text;
  v_date_window text;
  v_source_id uuid;
  v_target_date date;
  v_timezone text;
  v_activity_requested boolean;
BEGIN
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;
  IF jsonb_typeof(v_filter) <> 'object' THEN
    RAISE EXCEPTION 'invalid_training_filter';
  END IF;
  IF p_list_type IS NOT NULL AND p_list_type NOT IN ('curated', 'user') THEN
    RAISE EXCEPTION 'invalid_training_list_type';
  END IF;

  v_date_window := COALESCE(NULLIF(trim(v_filter->>'dateWindow'), ''), 'all');
  IF v_date_window NOT IN ('all', 'today', 'yesterday', 'daysAgo') THEN
    RAISE EXCEPTION 'invalid_training_date_window';
  END IF;
  IF v_date_window = 'daysAgo' AND (
    COALESCE(v_filter->>'daysAgo', '') !~ '^[0-9]{1,3}$'
    OR (v_filter->>'daysAgo')::integer > 365
  ) THEN
    RAISE EXCEPTION 'invalid_training_days_ago';
  END IF;

  IF v_filter ? 'dictionaryScope' THEN
    v_dictionary_scope := v_filter->'dictionaryScope';
    v_dictionary_mode := NULLIF(trim(v_dictionary_scope->>'mode'), '');
    v_dictionary_language := NULLIF(trim(v_dictionary_scope->>'languageCode'), '');
    IF p_list_id IS NOT NULL OR jsonb_typeof(v_dictionary_scope) <> 'object'
       OR v_dictionary_mode IS NULL OR v_dictionary_mode NOT IN ('all', 'selected')
       OR v_dictionary_language IS NULL THEN
      RAISE EXCEPTION 'training_material_unavailable';
    END IF;
    IF v_dictionary_mode = 'selected' AND (
      jsonb_typeof(v_dictionary_scope->'dictionaryIds') IS DISTINCT FROM 'array'
      OR jsonb_array_length(v_dictionary_scope->'dictionaryIds') = 0
      OR EXISTS (
        SELECT 1
        FROM jsonb_array_elements_text(v_dictionary_scope->'dictionaryIds') AS requested(id)
        WHERE requested.id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      )
    ) THEN
      RAISE EXCEPTION 'training_material_unavailable';
    END IF;
  END IF;

  IF NULLIF(v_filter->>'sourceId', '') IS NOT NULL THEN
    IF v_filter->>'sourceId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION 'invalid_training_source_id';
    END IF;
    v_source_id := (v_filter->>'sourceId')::uuid;
  END IF;
  v_activity_requested := v_date_window <> 'all'
    OR v_source_id IS NOT NULL
    OR NULLIF(trim(v_filter->>'sourceKind'), '') IS NOT NULL
    OR NULLIF(trim(v_filter->>'externalId'), '') IS NOT NULL;
  v_target_date := private.training_filter_target_date_at(
    v_filter, private.training_reference_now_v1()
  );
  v_timezone := private.training_schedule_timezone_v1(
    COALESCE(
      NULLIF(trim(v_filter->>'timezone'), ''),
      private.training_user_timezone_v1(p_user_id)
    )
  );

  RETURN QUERY
  WITH shared_entries AS MATERIALIZED (
    SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(p_user_id) shared
  ), readable_dictionaries AS MATERIALIZED (
    SELECT dictionary.id, dictionary.language_code,dictionary.kind,dictionary.owner_user_id
    FROM public.dictionaries AS dictionary
    WHERE public.can_access_dictionary(p_user_id, dictionary.id, 'read')
    OR (dictionary.kind='user' AND EXISTS(SELECT 1 FROM shared_entries shared
      JOIN private.active_word_entries shared_entry ON shared_entry.id=shared.entry_id WHERE shared_entry.dictionary_id=dictionary.id))
  ), selected_dictionaries AS MATERIALIZED (
    SELECT requested.id::uuid AS id
    FROM jsonb_array_elements_text(
      CASE WHEN v_dictionary_mode = 'selected'
        THEN v_dictionary_scope->'dictionaryIds'
        ELSE '[]'::jsonb END
    ) AS requested(id)
  ), scope AS MATERIALIZED (
    SELECT default_scope.entry_id AS id
    FROM private.default_training_scope_entries_v1 AS default_scope
    WHERE p_list_id IS NULL AND v_dictionary_mode IS NULL

    UNION ALL
    SELECT item.word_id AS id
    FROM public.word_list_items AS item
    WHERE p_list_id IS NOT NULL AND v_dictionary_mode IS NULL
      AND COALESCE(p_list_type, 'curated') = 'curated'
      AND item.list_id = p_list_id

    UNION ALL
    SELECT item.word_id AS id
    FROM public.user_word_list_items AS item
    JOIN public.user_word_lists AS list ON list.id = item.list_id
    WHERE p_list_id IS NOT NULL AND v_dictionary_mode IS NULL
      AND p_list_type = 'user' AND (list.user_id = p_user_id OR list.id IN (SELECT shared.collection_id FROM private.shared_collection_ids_v1(p_user_id) shared))
      AND item.list_id = p_list_id

    UNION ALL
    SELECT entry.id
    FROM private.active_word_entries AS entry
    JOIN readable_dictionaries AS dictionary ON dictionary.id = entry.dictionary_id
    WHERE v_dictionary_mode IN ('all', 'selected')
      AND entry.language_code = v_dictionary_language
      AND dictionary.language_code = v_dictionary_language
      AND (v_dictionary_mode = 'all' OR EXISTS (
        SELECT 1 FROM selected_dictionaries AS selected
        WHERE selected.id = entry.dictionary_id
      ))
  )
  SELECT DISTINCT entry.id
  FROM scope
  JOIN private.active_word_entries AS entry ON entry.id = scope.id
  LEFT JOIN readable_dictionaries AS dictionary ON dictionary.id = entry.dictionary_id
  WHERE (entry.dictionary_id IS NULL OR dictionary.id IS NOT NULL)
    AND (entry.dictionary_id IS NULL OR dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id
      OR entry.id IN (SELECT shared.entry_id FROM shared_entries shared))
    AND private.training_material_entry_selected_v1(entry.language_code,entry.dictionary_id,v_filter)
    AND NOT private.is_pointer_only_dictionary_entry_v1(entry.raw)
    AND private.training_lexical_candidate_matches_v1(
      entry.part_of_speech, entry.gender, v_filter
    )
    AND (NOT v_activity_requested OR EXISTS (
      SELECT 1
      FROM public.user_card_action_events AS event
      LEFT JOIN public.learning_sources AS source ON source.id = event.source_id
      WHERE event.user_id = p_user_id AND event.entry_id = entry.id
        AND event.card_type_id IN ('word-to-definition', 'definition-to-word')
        AND (v_target_date IS NULL OR
          private.training_filter_local_date(event.created_at, v_timezone) = v_target_date)
        AND (v_source_id IS NULL OR event.source_id = v_source_id)
        AND (NULLIF(trim(v_filter->>'sourceKind'), '') IS NULL
          OR source.kind = v_filter->>'sourceKind'
          OR source.provider = v_filter->>'sourceKind'
          OR (v_filter->>'sourceKind' = 'youtube' AND
            (source.kind IN ('youtube', 'youtube_video') OR source.provider = 'youtube')))
        AND (NULLIF(trim(v_filter->>'externalId'), '') IS NULL
          OR source.external_id = v_filter->>'externalId')
    ));
END;
$_$;


--
-- Name: training_filter_local_date(timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_filter_local_date(p_timestamp timestamp with time zone, p_timezone text) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT private.training_study_day_date_v1(
    p_timestamp,
    private.training_authoritative_timezone_v1((select auth.uid()), p_timezone)
  );
$$;


--
-- Name: FUNCTION training_filter_local_date(p_timestamp timestamp with time zone, p_timezone text); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.training_filter_local_date(p_timestamp timestamp with time zone, p_timezone text) IS 'Study-day date (04:00-to-04:00) used by source/date training filters.';


--
-- Name: training_filter_target_date(jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_filter_target_date(p_filter jsonb) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_target_date date;
BEGIN
  v_target_date := private.training_filter_target_date_at(p_filter, private.training_reference_now_v1());
  RETURN v_target_date;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$$;


--
-- Name: training_filter_target_date_at(jsonb, timestamp with time zone); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_filter_target_date_at(p_filter jsonb, p_reference_now timestamp with time zone) RETURNS date
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_timezone text := private.training_authoritative_timezone_v1((select auth.uid()), NULL);
  v_window text := COALESCE(NULLIF(trim(p_filter->>'dateWindow'), ''), 'all');
  v_days_ago int;
  v_today date;
BEGIN
  v_today := private.training_study_day_date_v1(
    COALESCE(p_reference_now, now()),
    v_timezone
  );

  IF v_window = 'today' THEN
    RETURN v_today;
  END IF;
  IF v_window = 'yesterday' THEN
    RETURN v_today - 1;
  END IF;
  IF v_window = 'daysAgo' THEN
    v_days_ago := GREATEST(0, LEAST(365, COALESCE(NULLIF(p_filter->>'daysAgo', '')::int, 0)));
    RETURN v_today - v_days_ago;
  END IF;

  RETURN NULL;
EXCEPTION WHEN others THEN
  RETURN NULL;
END;
$$;


--
-- Name: FUNCTION training_filter_target_date_at(p_filter jsonb, p_reference_now timestamp with time zone); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.training_filter_target_date_at(p_filter jsonb, p_reference_now timestamp with time zone) IS 'Deterministic study-day target-date resolver using the authenticated learner timezone when the filter omits one.';


--
-- Name: training_headword_group_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_headword_group_v1(p_entry_id uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT COALESCE(source_group.id, user_group.id)
  FROM public.word_entries entry
  LEFT JOIN private.source_entry_bindings binding
    ON binding.word_entry_id=entry.id AND binding.binding_state='active'
  LEFT JOIN private.platform_v2_headword_groups source_group
    ON source_group.management_kind='source'
    AND source_group.dictionary_id=binding.dictionary_id
    AND source_group.identity_scheme_version=binding.identity_scheme_version
    AND source_group.source_group_key=binding.source_group_key
  LEFT JOIN private.platform_v2_headword_groups user_group
    ON user_group.management_kind='user' AND user_group.singleton_entry_id=entry.id
  WHERE entry.id=p_entry_id;
$$;


--
-- Name: training_idiom_session_response_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_idiom_session_response_v1(p_user_id uuid, p_session_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
    SELECT private.training_session_run_response_v1(p_user_id, session.id)
        || jsonb_build_object(
            'contractVersion', 'platform-idiom-exercise-session-v2',
            'exerciseFamily', 'idiom',
            'direction', CASE WHEN session.card_type_ids @> ARRAY['idiom:direct','idiom:reverse']
              THEN 'mixed' ELSE split_part(session.card_type_ids[1], ':', 2) END,
            'completedActions', COALESCE(completed.actions, 0),
            'completionReason', session.completion_reason,
            'members', COALESCE(members.items, '[]'::jsonb)
        )
      FROM public.training_sessions AS session
      LEFT JOIN LATERAL (
          SELECT count(*)::integer AS actions
            FROM public.training_session_exercise_members AS member
           WHERE member.session_id = session.id
             AND member.consumed_at IS NOT NULL
      ) AS completed ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_agg(jsonb_build_object(
              'ordinal', member.ordinal,
              'targetId', member.target_id,
              'queueSource', member.queue_source,
              'consumedAt', member.consumed_at,
              'unavailableAt', member.unavailable_at,
              'unavailableReason', member.unavailable_reason,
              'entryId', target.entry_id,
              'contentNodeId', target.content_node_id,
              'family', target.family,
              'direction', target.direction
          ) ORDER BY member.ordinal) AS items
            FROM public.training_session_exercise_members AS member
            JOIN private.platform_v2_training_exercise_targets AS target
              ON target.id = member.target_id
            JOIN private.active_word_entries AS entry
              ON entry.id = target.entry_id
           WHERE member.session_id = session.id
             AND private.entry_access_v1(p_user_id,entry.id,'train')
             AND private.platform_v2_training_ordinary_meaning_eligible_v1(
                 p_user_id,
                 target.entry_id
             )
      ) AS members ON true
     WHERE session.id = p_session_id
       AND session.user_id = p_user_id
       AND session.exercise_family = 'idiom';
$$;


--
-- Name: training_idiom_source_nodes_v1(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_idiom_source_nodes_v1(p_user_id uuid, p_direction text, p_list_id uuid, p_list_type text, p_training_filter jsonb) RETURNS TABLE(content_node_id uuid, entry_id uuid, expression_source_path text, source_text_fingerprint text, created_at timestamp with time zone, source_revision text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
        WITH shared_entries AS MATERIALIZED (
    SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(p_user_id) shared
  ), readable_dictionaries AS MATERIALIZED (
            SELECT dictionary.id,(dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id) AS full_access
              FROM public.dictionaries AS dictionary
             WHERE public.can_access_dictionary(p_user_id, dictionary.id, 'read')
    OR (dictionary.kind='user' AND EXISTS(SELECT 1 FROM shared_entries shared
      JOIN private.active_word_entries shared_entry ON shared_entry.id=shared.entry_id WHERE shared_entry.dictionary_id=dictionary.id))
        ), eligible_seed AS MATERIALIZED (
            SELECT status.entry_id
              FROM public.user_card_status AS status
              JOIN private.active_word_entries AS entry ON entry.id = status.entry_id
              LEFT JOIN readable_dictionaries AS readable
                ON readable.id = entry.dictionary_id
             WHERE status.user_id = p_user_id
               AND status.card_type_id IN ('word-to-definition', 'definition-to-word')
               AND (
                   COALESCE(status.in_learning, false)
                   OR COALESCE(status.fsrs_enabled, false)
                   OR COALESCE(status.fsrs_reps, 0) > 0
                   OR status.last_reviewed_at IS NOT NULL
               )
               AND (entry.dictionary_id IS NULL OR (readable.id IS NOT NULL
    AND (readable.full_access OR entry.id IN (SELECT shared.entry_id FROM shared_entries shared))))
            UNION
            SELECT known.entry_id
              FROM public.user_card_known_marks AS known
              JOIN private.active_word_entries AS entry ON entry.id = known.entry_id
              LEFT JOIN readable_dictionaries AS readable
                ON readable.id = entry.dictionary_id
             WHERE known.user_id = p_user_id
               AND known.card_type_id IN ('word-to-definition', 'definition-to-word')
               AND known.cleared_at IS NULL
               AND (entry.dictionary_id IS NULL OR (readable.id IS NOT NULL
    AND (readable.full_access OR entry.id IN (SELECT shared.entry_id FROM shared_entries shared))))
        ), eligible_source_groups AS MATERIALIZED (
            SELECT DISTINCT source_group.id
              FROM eligible_seed AS seed
              JOIN private.source_entry_bindings AS binding
                ON binding.word_entry_id = seed.entry_id
               AND binding.binding_state = 'active'
              JOIN private.platform_v2_headword_groups AS source_group
                ON source_group.management_kind = 'source'
               AND source_group.dictionary_id = binding.dictionary_id
               AND source_group.identity_scheme_version = binding.identity_scheme_version
               AND source_group.source_group_key = binding.source_group_key
        ), source_entries AS MATERIALIZED (
            SELECT entry_id
              FROM private.training_extra_source_entries_v1(
                  p_user_id, p_list_id, p_list_type, p_training_filter
              )
        ), source_nodes AS (
            SELECT
                node.id AS content_node_id,
                node.entry_id,
                node.diagnostic_locator AS expression_source_path,
                node.source_text_fingerprint,
                node.created_at,
                encode(
                    digest(
                        node.id::text || ':' || node.source_text_fingerprint,
                        'sha256'
                    ),
                    'hex'
                ) AS source_revision
              FROM private.platform_v2_content_nodes AS node
              LEFT JOIN private.source_entry_bindings AS source_binding
                ON source_binding.word_entry_id = node.entry_id
               AND source_binding.binding_state = 'active'
              LEFT JOIN private.platform_v2_headword_groups AS source_group
                ON source_group.management_kind = 'source'
               AND source_group.dictionary_id = source_binding.dictionary_id
               AND source_group.identity_scheme_version = source_binding.identity_scheme_version
               AND source_group.source_group_key = source_binding.source_group_key
              LEFT JOIN eligible_source_groups AS eligible_group
                ON eligible_group.id = source_group.id
              LEFT JOIN eligible_seed AS direct_seed
                ON direct_seed.entry_id = node.entry_id
             WHERE node.kind = 'idiom'
               AND node.binding_state = 'active'
               AND EXISTS (
                   SELECT 1 FROM source_entries AS source_entry
                   WHERE source_entry.entry_id = node.entry_id
               )
               AND (
                   eligible_group.id IS NOT NULL
                   OR (source_group.id IS NULL AND direct_seed.entry_id IS NOT NULL)
               )
               AND (
                   SELECT count(*)
                     FROM private.platform_v2_content_nodes AS explanation
                    WHERE explanation.parent_content_node_id = node.id
                      AND explanation.kind = 'idiom-explanation'
                      AND explanation.binding_state = 'active'
               ) = 1
               AND EXISTS (
                   SELECT 1
                     FROM private.platform_v2_content_nodes AS explanation
                    WHERE explanation.parent_content_node_id = node.id
                      AND explanation.kind = 'idiom-explanation'
                      AND explanation.binding_state = 'active'
                      AND NULLIF(btrim(explanation.diagnostic_locator), '') IS NOT NULL
               )
               AND NOT EXISTS (
                   SELECT 1
                     FROM private.platform_v2_training_exercise_targets AS stale
                    WHERE stale.entry_id = node.entry_id
                      AND stale.content_node_id = node.id
                      AND stale.family = 'idiom'
                      AND stale.direction = p_direction
                      AND stale.source_text_fingerprint
                            IS DISTINCT FROM node.source_text_fingerprint
               )
        )
        SELECT * FROM source_nodes;
$$;


--
-- Name: training_lexical_candidate_matches_v1(text, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_lexical_candidate_matches_v1(p_part_of_speech text, p_gender text, p_training_filter jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_filter jsonb := COALESCE(p_training_filter, '{}'::jsonb);
  v_requested_pos text[] := ARRAY[]::text[];
  v_requested_articles text[] := ARRAY[]::text[];
  v_entry_pos text;
  v_entry_gender text;
BEGIN
  IF NOT (v_filter ? 'partOfSpeech' OR v_filter ? 'nounArticles') THEN
    RETURN true;
  END IF;

  IF v_filter ? 'partOfSpeech' THEN
    IF jsonb_typeof(v_filter->'partOfSpeech') <> 'array' THEN RETURN false; END IF;
    SELECT COALESCE(array_agg(DISTINCT value), ARRAY[]::text[])
      INTO v_requested_pos
    FROM jsonb_array_elements_text(v_filter->'partOfSpeech') AS item(value);
    IF EXISTS (
      SELECT 1 FROM unnest(v_requested_pos) AS item(value)
      WHERE value IS NULL
        OR value NOT IN ('zn','ww','bn','bw','vz','vnw','vw','tw','lidw','tsw','afk')
    ) THEN RETURN false; END IF;
  END IF;

  IF v_filter ? 'nounArticles' THEN
    IF jsonb_typeof(v_filter->'nounArticles') <> 'array' THEN RETURN false; END IF;
    SELECT COALESCE(array_agg(DISTINCT lower(value)), ARRAY[]::text[])
      INTO v_requested_articles
    FROM jsonb_array_elements_text(v_filter->'nounArticles') AS item(value);
    IF EXISTS (
      SELECT 1 FROM unnest(v_requested_articles) AS item(value)
      WHERE value IS NULL OR value NOT IN ('de','het')
    ) THEN RETURN false; END IF;
  END IF;

  v_entry_pos := private.normalize_training_part_of_speech_v1(p_part_of_speech);
  v_entry_gender := lower(trim(p_gender));

  IF cardinality(v_requested_pos) > 0
     AND (v_entry_pos IS NULL OR NOT (v_entry_pos = ANY(v_requested_pos))) THEN
    RETURN false;
  END IF;

  IF cardinality(v_requested_articles) > 0 THEN
    -- Articles narrow selected nouns. Explicitly selected non-noun categories
    -- remain eligible; with no POS selection, article filtering selects nouns.
    IF v_entry_pos = 'zn' THEN
      RETURN COALESCE(v_entry_gender = ANY(v_requested_articles), false);
    END IF;
    RETURN cardinality(v_requested_pos) > 0
      AND v_entry_pos IS NOT NULL
      AND v_entry_pos = ANY(v_requested_pos);
  END IF;

  RETURN true;
END;
$$;


--
-- Name: training_local_daily_stats_v1(uuid, text[], uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_local_daily_stats_v1(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text, p_timezone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_modes text[] := p_modes;
  v_list_type text := COALESCE(p_list_type, 'curated');
  v_timezone text;
  v_now timestamptz := clock_timestamp();
  v_study_day_start timestamptz;
  v_study_day_end timestamptz;
BEGIN
  IF v_modes IS NULL OR cardinality(v_modes) = 0 THEN
    v_modes := ARRAY['word-to-definition'];
  END IF;

  v_timezone := private.training_schedule_timezone_v1(
    COALESCE(
      NULLIF(trim(p_timezone), ''),
      private.training_user_timezone_v1(p_user_id),
      'UTC'
    )
  );

  SELECT bounds.start_at, bounds.end_at
  INTO v_study_day_start, v_study_day_end
  FROM private.training_study_day_bounds_v1(v_now, v_timezone) bounds;

  RETURN (
    WITH accessible_entries AS (
      SELECT w.id
      FROM word_entries w
      WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
        AND (
              (p_list_id IS NULL AND w.is_nt2_2000 = true)
           OR (p_list_id IS NOT NULL AND v_list_type = 'curated' AND EXISTS (
                  SELECT 1 FROM word_list_items li
                  WHERE li.list_id = p_list_id AND li.word_id = w.id
              ))
           OR (p_list_id IS NOT NULL AND v_list_type = 'user' AND EXISTS (
                  SELECT 1 FROM user_word_list_items li
                  JOIN user_word_lists l ON l.id = li.list_id
                  WHERE li.list_id = p_list_id
                    AND li.word_id = w.id
                    AND l.user_id = p_user_id
              ))
        )
    ), introduced_cards AS (
      SELECT e.entry_id, e.card_type_id
      FROM user_card_action_events e
      WHERE e.user_id = p_user_id
        AND e.card_type_id = ANY(v_modes)
        AND e.action = 'start-learning'
        AND e.created_at >= v_study_day_start
        AND e.created_at < v_study_day_end
      UNION
      SELECT rl.word_id, rl.mode
      FROM user_review_log rl
      WHERE rl.user_id = p_user_id
        AND rl.mode = ANY(v_modes)
        AND rl.review_type = 'new'
        AND rl.reviewed_at >= v_study_day_start
        AND rl.reviewed_at < v_study_day_end
    ), introduced_metrics AS (
      SELECT
        COUNT(DISTINCT introduced.entry_id)::int AS new_words_today,
        COUNT(*)::int AS new_cards_today
      FROM introduced_cards introduced
      JOIN accessible_entries accessible ON accessible.id = introduced.entry_id
    ), learning_metrics AS (
      SELECT COUNT(*)::int AS learning_started_today
      FROM (
        SELECT DISTINCT e.entry_id, e.card_type_id
        FROM user_card_action_events e
        JOIN accessible_entries accessible ON accessible.id = e.entry_id
        WHERE e.user_id = p_user_id
          AND e.card_type_id = ANY(v_modes)
          AND e.action = 'start-learning'
          AND e.created_at >= v_study_day_start
          AND e.created_at < v_study_day_end
      ) started
    ), graduated_metrics AS (
      SELECT COUNT(DISTINCT rl.word_id)::int AS graduated_new_words_today
      FROM user_review_log rl
      JOIN accessible_entries accessible ON accessible.id = rl.word_id
      WHERE rl.user_id = p_user_id
        AND rl.mode = ANY(v_modes)
        AND rl.review_type = 'new'
        AND rl.reviewed_at >= v_study_day_start
        AND rl.reviewed_at < v_study_day_end
        AND rl.interval_after >= 1.0
    ), review_metrics AS (
      SELECT
        COUNT(DISTINCT rl.word_id)::int AS review_words_done,
        COUNT(*)::int AS review_cards_done
      FROM user_review_log rl
      JOIN accessible_entries accessible ON accessible.id = rl.word_id
      WHERE rl.user_id = p_user_id
        AND rl.mode = ANY(v_modes)
        AND rl.review_type = 'review'
        AND rl.reviewed_at >= v_study_day_start
        AND rl.reviewed_at < v_study_day_end
    ), due_metrics AS (
      SELECT
        COUNT(DISTINCT s.entry_id)::int AS review_words_due,
        COUNT(*)::int AS review_cards_due
      FROM user_card_status s
      JOIN accessible_entries accessible ON accessible.id = s.entry_id
      JOIN private.active_word_entries available ON available.id = s.entry_id
      WHERE s.user_id = p_user_id
        AND s.card_type_id = ANY(v_modes)
        AND s.next_review_at < v_study_day_end
        AND (s.frozen_until IS NULL OR s.frozen_until <= v_now)
        AND s.hidden = false
        AND s.fsrs_enabled = true
        AND (s.card_type_id NOT IN ('word-to-definition','definition-to-word') OR NOT EXISTS (
          SELECT 1 FROM private.training_headword_exclusions exclusion
          WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
            AND exclusion.entry_id=s.entry_id))
        AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
          WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
            AND exclusion.pair_key=private.training_pair_key_v1(
              'meaning',s.entry_id,NULL,NULL,s.card_type_id))
        AND NOT EXISTS (
          SELECT 1
          FROM user_review_log rl
          WHERE rl.user_id = s.user_id
            AND rl.word_id = s.entry_id
            AND rl.mode = s.card_type_id
            AND rl.review_type = 'new'
            AND rl.reviewed_at >= v_study_day_start
            AND rl.reviewed_at < v_study_day_end
        )
    )
    SELECT jsonb_build_object(
      'newWordsToday', introduced.new_words_today,
      'newCardsToday', introduced.new_cards_today,
      'learningStartedToday', learning.learning_started_today,
      'graduatedNewWordsToday', graduated.graduated_new_words_today,
      'reviewWordsDone', reviews.review_words_done,
      'reviewCardsDone', reviews.review_cards_done,
      'reviewWordsDue', due.review_words_due,
      'reviewCardsDue', due.review_cards_due
    )
    FROM introduced_metrics introduced
    CROSS JOIN learning_metrics learning
    CROSS JOIN graduated_metrics graduated
    CROSS JOIN review_metrics reviews
    CROSS JOIN due_metrics due
  );
END;
$$;


--
-- Name: training_material_entry_selected_v1(text, uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_material_entry_selected_v1(p_language_code text, p_dictionary_id uuid, p_filter jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $$
  SELECT CASE WHEN NOT COALESCE(p_filter ? 'materialSelection', false) THEN true
    ELSE COALESCE(
      ((p_filter#>'{materialSelection,allowedLanguageCodes}') = 'null'::jsonb
        OR (p_filter#>'{materialSelection,allowedLanguageCodes}') ? p_language_code)
      AND (p_dictionary_id IS NULL OR NOT
        ((p_filter#>'{materialSelection,disabledDictionaryIds}') ? p_dictionary_id::text)), false)
    END;
$$;


--
-- Name: training_ordinary_direct_recall_renderable_v1(uuid, integer, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_ordinary_direct_recall_renderable_v1(p_entry_id uuid, p_meaning_id integer, p_card_type_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_card_type_id <> 'word-to-definition' THEN true
    WHEN COALESCE(p_meaning_id, 1) <= 1 THEN true
    -- Idiom-only meanings have no row here and retain their legacy ordinary
    -- path until #332 moves them to their independent exercise family.
    WHEN EXISTS (
      SELECT 1
      FROM private.unrenderable_ordinary_direct_entries_v1 unrenderable
      WHERE unrenderable.entry_id = p_entry_id
    ) THEN false
    ELSE true
  END;
$$;


--
-- Name: training_pair_excluded_v1(uuid, text, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_pair_excluded_v1(p_user_id uuid, p_family text, p_entry_id uuid, p_node_id uuid, p_fingerprint text, p_card_type_id text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT EXISTS (SELECT 1 FROM private.training_pair_exclusions
    WHERE user_id = p_user_id AND restored_at IS NULL
      AND pair_key = private.training_pair_key_v1(
        p_family,p_entry_id,p_node_id,p_fingerprint,p_card_type_id))
    OR (p_family='meaning' AND p_card_type_id IN ('word-to-definition','definition-to-word')
      AND EXISTS (SELECT 1 FROM private.training_headword_exclusions
        WHERE user_id=p_user_id AND restored_at IS NULL
          AND entry_id=p_entry_id));
$$;


--
-- Name: training_pair_key_v1(text, uuid, uuid, text, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_pair_key_v1(p_family text, p_entry_id uuid, p_node_id uuid, p_fingerprint text, p_card_type_id text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT CASE
    WHEN p_family = 'meaning' THEN
      'entry:' || p_entry_id::text || ':' || CASE
        WHEN p_card_type_id IN ('word-to-definition','definition-to-word') THEN 'recall'
        ELSE p_card_type_id END
    WHEN p_family IN ('idiom','translation') THEN
      'node:' || p_family || ':' || p_entry_id::text || ':' || p_node_id::text || ':' || p_fingerprint
    ELSE NULL END;
$$;


--
-- Name: training_recipe_eligible_cards_v1(uuid, text[], uuid, text, text, text, uuid[], text[], jsonb, boolean, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_recipe_eligible_cards_v1(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_entry_ids uuid[], p_exclude_card_keys text[], p_training_filter jsonb, p_filtered boolean, p_enforce_daily_limits boolean) RETURNS TABLE(entry_id uuid, card_type_id text, fsrs_enabled boolean, introduced boolean, next_review_at timestamp with time zone, intrinsic_source text)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    SET enable_nestloop TO 'off'
    SET jit TO 'off'
    AS $_$
 
WITH shared_entries AS MATERIALIZED (
      SELECT entry_id FROM private.shared_author_entry_ids_v1(p_user_id)
    ), shared_dictionaries AS MATERIALIZED (
      SELECT DISTINCT entry.dictionary_id FROM shared_entries shared
      JOIN private.active_word_entries entry ON entry.id=shared.entry_id
    ), args AS (
  SELECT CASE
      WHEN p_card_type_ids IS NULL OR cardinality(p_card_type_ids)=0
        THEN ARRAY['word-to-definition']::text[]
      ELSE ARRAY(
        SELECT DISTINCT trim(mode)
        FROM unnest(p_card_type_ids) requested(mode)
        WHERE trim(mode)<>'' ORDER BY 1
      )
    END modes,
    COALESCE(p_training_filter,'{}') filter_data,
    COALESCE(p_list_type,'curated') list_type,
    COALESCE(p_exclude_entry_ids,ARRAY[]::uuid[]) excluded_entries,
    COALESCE(p_exclude_card_keys,ARRAY[]::text[]) excluded_cards
), reference_now AS MATERIALIZED (
  SELECT private.training_reference_now_v1() AS now_at
), filter_values AS (
  SELECT args.*,
    private.training_filter_target_date(filter_data) target_date,
    private.training_schedule_timezone_v1(
      COALESCE(
        NULLIF(trim(filter_data->>'timezone'),''),
        private.training_user_timezone_v1(p_user_id)
      )
    ) timezone,
    reference_now.now_at,
    bounds.start_at study_day_start,
    bounds.end_at study_day_end,
    CASE WHEN NULLIF(filter_data->>'sourceId','') ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      THEN (filter_data->>'sourceId')::uuid END source_id,
    NULLIF(trim(filter_data->>'sourceKind'),'') source_kind,
    NULLIF(trim(filter_data->>'externalId'),'') external_id,
    NULLIF(trim(filter_data#>>'{dictionaryScope,mode}'),'') dictionary_mode,
    NULLIF(trim(filter_data#>>'{dictionaryScope,languageCode}'),'') dictionary_language
  FROM args
  CROSS JOIN reference_now
  CROSS JOIN LATERAL private.training_study_day_bounds_v1(
    reference_now.now_at,
    private.training_schedule_timezone_v1(
      COALESCE(
        NULLIF(trim(args.filter_data->>'timezone'),''),
        private.training_user_timezone_v1(p_user_id)
      )
    )
  ) bounds
), mode_order AS (
  SELECT requested_mode.card_type_id,random() mode_random
  FROM filter_values
  CROSS JOIN unnest(filter_values.modes) requested_mode(card_type_id)
), cohort_context AS (
  SELECT md5(concat_ws('|',
    p_user_id::text,
    array_to_string(filter_values.modes,','),
    COALESCE(p_list_id::text,''),
    filter_values.list_type,
    p_card_filter,
    filter_values.filter_data::text
  )) cohort_seed
  FROM filter_values
), limits AS (
  SELECT COALESCE(settings.daily_new_limit,10)::bigint new_limit,
    COALESCE(settings.daily_review_limit,200)::bigint review_limit
  FROM (SELECT 1) seed
  LEFT JOIN user_settings settings ON settings.user_id=p_user_id
), daily AS (
  SELECT count(DISTINCT log.word_id) FILTER (WHERE log.review_type='new') new_today,
    count(*) FILTER (WHERE log.review_type='review') review_today
  FROM user_review_log log, filter_values
  WHERE log.user_id=p_user_id
    AND log.mode=ANY(filter_values.modes)
    AND log.reviewed_at >= filter_values.study_day_start
    AND log.reviewed_at < filter_values.study_day_end
), readable_dictionaries AS MATERIALIZED (
  SELECT dictionary.id,dictionary.language_code
  FROM dictionaries dictionary
  WHERE (
      (can_access_dictionary(p_user_id,dictionary.id,'read') AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id))
      OR (dictionary.kind='user' AND dictionary.id IN (SELECT dictionary_id FROM shared_dictionaries)))
), selected_dictionaries AS MATERIALIZED (
  SELECT DISTINCT requested.id::uuid AS id
  FROM filter_values
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE WHEN jsonb_typeof(filter_values.filter_data#>'{dictionaryScope,dictionaryIds}')='array'
      THEN filter_values.filter_data#>'{dictionaryScope,dictionaryIds}'
      ELSE '[]'::jsonb END
  ) requested(id)
  WHERE requested.id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
), raw_scope AS MATERIALIZED (
  SELECT scope_entry.entry_id AS id
  FROM private.default_training_scope_entries_v1 scope_entry
  CROSS JOIN filter_values
  LEFT JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=scope_entry.dictionary_id
  WHERE p_list_id IS NULL
    AND filter_values.dictionary_mode IS NULL
    AND NOT (filter_values.filter_data ? 'partOfSpeech'
      OR filter_values.filter_data ? 'nounArticles')
    AND NOT (scope_entry.entry_id=ANY(filter_values.excluded_entries))
    AND (scope_entry.dictionary_id IS NULL OR readable_dictionary.id IS NOT NULL)
  UNION ALL
  SELECT scope_entry.entry_id AS id
  FROM private.default_training_scope_entries_v1 scope_entry
  CROSS JOIN filter_values
  LEFT JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=scope_entry.dictionary_id
  JOIN private.active_word_entries lexical_entry ON lexical_entry.id=scope_entry.entry_id
  WHERE p_list_id IS NULL
    AND filter_values.dictionary_mode IS NULL
    AND (filter_values.filter_data ? 'partOfSpeech'
      OR filter_values.filter_data ? 'nounArticles')
    AND NOT (scope_entry.entry_id=ANY(filter_values.excluded_entries))
    AND (scope_entry.dictionary_id IS NULL OR readable_dictionary.id IS NOT NULL)
    AND private.training_lexical_candidate_matches_v1(
      lexical_entry.part_of_speech, lexical_entry.gender,
      filter_values.filter_data
    )
  UNION ALL
  SELECT entry.id
  FROM private.active_word_entries entry
  CROSS JOIN filter_values
  LEFT JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=entry.dictionary_id
  WHERE p_list_id IS NOT NULL
    AND filter_values.dictionary_mode IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM private.active_word_entries pointer_entry
      WHERE pointer_entry.id=entry.id
        AND private.is_pointer_only_dictionary_entry_v1(pointer_entry.raw)
    )
    AND NOT (entry.id=ANY(filter_values.excluded_entries))
    AND (entry.dictionary_id IS NULL OR readable_dictionary.id IS NOT NULL)
    AND ((filter_values.list_type='curated' AND EXISTS (
        SELECT 1 FROM word_list_items item
        WHERE item.list_id=p_list_id AND item.word_id=entry.id
      ))
      OR (filter_values.list_type='user' AND EXISTS (
        SELECT 1 FROM user_word_list_items item
        JOIN user_word_lists list ON list.id=item.list_id
        WHERE item.list_id=p_list_id AND item.word_id=entry.id AND (list.user_id=p_user_id
      OR list.id IN (SELECT collection_id FROM private.shared_collection_ids_v1(p_user_id)))
      )))
    AND CASE
      WHEN filter_values.filter_data ? 'partOfSpeech'
        OR filter_values.filter_data ? 'nounArticles'
      THEN private.training_lexical_candidate_matches_v1(
        entry.part_of_speech, entry.gender, filter_values.filter_data
      )
      ELSE true
    END
  UNION ALL
  SELECT entry.id
  FROM private.active_word_entries entry
  CROSS JOIN filter_values
  JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=entry.dictionary_id
   AND readable_dictionary.language_code=filter_values.dictionary_language
  WHERE p_list_id IS NULL
    AND filter_values.dictionary_mode IN ('all','selected')
    AND entry.language_code=filter_values.dictionary_language
    AND NOT (entry.id=ANY(filter_values.excluded_entries))
    AND (filter_values.dictionary_mode='all' OR EXISTS (
      SELECT 1 FROM selected_dictionaries selected
      WHERE selected.id=entry.dictionary_id
    ))
    AND NOT EXISTS (
      SELECT 1 FROM private.active_word_entries pointer_entry
      WHERE pointer_entry.id=entry.id
        AND private.is_pointer_only_dictionary_entry_v1(pointer_entry.raw)
    )
    AND CASE
      WHEN filter_values.filter_data ? 'partOfSpeech'
        OR filter_values.filter_data ? 'nounArticles'
      THEN private.training_lexical_candidate_matches_v1(
        entry.part_of_speech, entry.gender, filter_values.filter_data
      )
      ELSE true
    END
), scope AS MATERIALIZED (
    SELECT raw_scope.id FROM raw_scope
    JOIN private.active_word_entries material_entry ON material_entry.id=raw_scope.id
    LEFT JOIN public.dictionaries authority_dictionary ON authority_dictionary.id=material_entry.dictionary_id
    CROSS JOIN filter_values material_filter
    WHERE (material_entry.dictionary_id IS NULL OR authority_dictionary.kind<>'user'
      OR authority_dictionary.owner_user_id=p_user_id OR material_entry.id IN (SELECT entry_id FROM shared_entries))
      AND private.training_material_entry_selected_v1(
      material_entry.language_code,material_entry.dictionary_id,material_filter.filter_data)
  ), matched AS (
  SELECT event.entry_id,event.card_type_id,max(event.created_at) latest_event_at
  FROM user_card_action_events event
  LEFT JOIN learning_sources source ON source.id=event.source_id
  CROSS JOIN filter_values
  WHERE event.user_id=p_user_id
    AND event.card_type_id=ANY(filter_values.modes)
    AND (filter_values.target_date IS NULL OR
      private.training_filter_local_date(event.created_at,filter_values.timezone)=filter_values.target_date)
    AND (filter_values.source_id IS NULL OR event.source_id=filter_values.source_id)
    AND (filter_values.source_kind IS NULL OR source.kind=filter_values.source_kind
      OR source.provider=filter_values.source_kind
      OR (filter_values.source_kind='youtube' AND
        (source.kind IN ('youtube','youtube_video') OR source.provider='youtube')))
    AND (filter_values.external_id IS NULL OR source.external_id=filter_values.external_id)
  GROUP BY event.entry_id,event.card_type_id
), study_day_new_words AS MATERIALIZED (
  SELECT DISTINCT log.word_id
  FROM user_review_log log, filter_values
  WHERE log.user_id=p_user_id
    AND log.mode=ANY(filter_values.modes)
    AND log.review_type='new'
    AND log.reviewed_at >= filter_values.study_day_start
    AND log.reviewed_at < filter_values.study_day_end
), study_day_new_cards AS MATERIALIZED (
  SELECT DISTINCT log.word_id,log.mode AS card_type_id
  FROM user_review_log log, filter_values
  WHERE log.user_id=p_user_id
    AND log.mode=ANY(filter_values.modes)
    AND log.review_type='new'
    AND log.reviewed_at >= filter_values.study_day_start
    AND log.reviewed_at < filter_values.study_day_end
), known_cards AS MATERIALIZED (
  SELECT known.entry_id,known.card_type_id
  FROM user_card_known_marks known,filter_values
  WHERE known.user_id=p_user_id
    AND known.card_type_id=ANY(filter_values.modes)
    AND known.cleared_at IS NULL
), learner_status AS MATERIALIZED (
  SELECT status.*
  FROM user_card_status status,filter_values
  WHERE status.user_id=p_user_id
    AND status.card_type_id=ANY(filter_values.modes)
), unrenderable_direct_entries AS MATERIALIZED (
  SELECT entry_id FROM private.unrenderable_ordinary_direct_entries_v1
), active_source_bindings AS MATERIALIZED (
  SELECT binding.dictionary_id, binding.identity_scheme_version,
    binding.source_group_key, binding.sense_ordinal, binding.word_entry_id
  FROM private.source_entry_bindings binding
  WHERE binding.binding_state = 'active'
), source_bound_entries AS MATERIALIZED (
  SELECT binding.word_entry_id AS entry_id
  FROM active_source_bindings binding
), scoped_source_groups AS NOT MATERIALIZED (
  SELECT DISTINCT binding.dictionary_id, binding.identity_scheme_version,
    binding.source_group_key
  FROM active_source_bindings binding
  JOIN scope ON scope.id = binding.word_entry_id
), active_source_definitions AS MATERIALIZED (
  SELECT definition.entry_id
  FROM private.platform_v2_content_nodes definition
  WHERE definition.binding_state = 'active'
    AND definition.parent_content_node_id IS NULL
    AND definition.kind = 'definition'
), ordinary_source_introductions AS MATERIALIZED (
  SELECT binding.word_entry_id AS entry_id,
    lag(binding.word_entry_id) OVER (
      PARTITION BY binding.dictionary_id, binding.identity_scheme_version,
        binding.source_group_key
      ORDER BY binding.sense_ordinal, binding.word_entry_id
    ) AS predecessor_entry_id
  FROM active_source_bindings binding
  JOIN scoped_source_groups source_group
    USING (dictionary_id, identity_scheme_version, source_group_key)
  JOIN active_source_definitions definition
    ON definition.entry_id = binding.word_entry_id
  -- Active bindings and exception entry IDs are non-null by schema. Hashing
  -- this small exception set avoids one index probe per scoped meaning.
  WHERE binding.word_entry_id NOT IN (
    SELECT unrenderable.entry_id FROM unrenderable_direct_entries unrenderable
  )
), cards AS (
  SELECT scope.id entry_id,mode_order.card_type_id,status.fsrs_enabled,
    status.fsrs_last_interval,status.next_review_at,status.hidden,status.frozen_until,
    (COALESCE(status.fsrs_reps,0)>0 OR status.last_reviewed_at IS NOT NULL) introduced,
    status.entry_id IS NOT NULL has_status,matched.entry_id IS NOT NULL matches_filter,
    matched.latest_event_at,mode_order.mode_random,
    filter_values.now_at reference_now,
    study_day_new_words.word_id IS NOT NULL new_seen_today,
    study_day_new_cards.word_id IS NOT NULL new_card_seen_today,
    CASE
      WHEN private.training_review_early_v1(p_training_filter,p_card_filter)
        AND status.fsrs_enabled=true THEN
          CASE WHEN COALESCE(status.fsrs_last_interval,0)<1 THEN 'learning' ELSE 'review' END
      WHEN status.fsrs_enabled=true AND COALESCE(status.fsrs_last_interval,0)<1
        AND status.next_review_at<=filter_values.now_at THEN 'learning'
      WHEN status.fsrs_enabled=true AND status.fsrs_last_interval>=1
        AND status.next_review_at<=filter_values.now_at THEN 'review'
      WHEN status.entry_id IS NULL OR COALESCE(status.fsrs_enabled,false)=false THEN 'new'
      ELSE 'practice'
    END intrinsic_source
  FROM scope
  CROSS JOIN filter_values CROSS JOIN mode_order
  LEFT JOIN learner_status status ON status.entry_id=scope.id
    AND status.card_type_id=mode_order.card_type_id
  LEFT JOIN matched ON matched.entry_id=scope.id AND matched.card_type_id=mode_order.card_type_id
  LEFT JOIN study_day_new_words ON study_day_new_words.word_id=scope.id
  LEFT JOIN study_day_new_cards ON study_day_new_cards.word_id=scope.id
    AND study_day_new_cards.card_type_id=mode_order.card_type_id
  LEFT JOIN known_cards ON known_cards.entry_id=scope.id
    AND known_cards.card_type_id=mode_order.card_type_id
  WHERE NOT ((scope.id::text||':'||mode_order.card_type_id)=ANY(filter_values.excluded_cards))
    AND known_cards.entry_id IS NULL
    AND (mode_order.card_type_id NOT IN ('word-to-definition','definition-to-word') OR NOT EXISTS (
      SELECT 1 FROM private.training_headword_exclusions exclusion
      WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
        AND exclusion.entry_id=scope.id))
    AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
      WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
        AND exclusion.pair_key=private.training_pair_key_v1(
          'meaning', scope.id, NULL, NULL, mode_order.card_type_id))
), eligible AS (
  SELECT cards.*
  FROM cards
  LEFT JOIN unrenderable_direct_entries unrenderable
    ON unrenderable.entry_id = cards.entry_id
  LEFT JOIN source_bound_entries source_bound
    ON source_bound.entry_id = cards.entry_id
  LEFT JOIN ordinary_source_introductions introduction
    ON introduction.entry_id = cards.entry_id
  LEFT JOIN private.ordinary_meaning_introduction_unlocks_v1 predecessor_unlock
    ON predecessor_unlock.user_id = p_user_id
   AND predecessor_unlock.entry_id = introduction.predecessor_entry_id
  WHERE COALESCE(hidden,false)=false AND (frozen_until IS NULL OR frozen_until<=reference_now)
    AND (NOT private.training_review_early_v1(p_training_filter,p_card_filter)
      OR (cards.introduced AND cards.fsrs_enabled=true))
    AND CASE
      WHEN (SELECT filter_data->>'presentationMode' FROM filter_values)
        = 'word-in-context'
      THEN private.training_word_context_candidate_v1(
        p_user_id, cards.entry_id, cards.card_type_id)
      ELSE true
    END
    AND (
      card_type_id <> 'word-to-definition'
      OR unrenderable.entry_id IS NULL
    )
    AND (
      intrinsic_source <> 'new'
      OR (
        card_type_id = 'definition-to-word'
        AND COALESCE((SELECT filter_data->>'presentationMode' FROM filter_values), '')
          = 'word-in-context'
      )
      OR (
        card_type_id = 'word-to-definition'
        AND (
          source_bound.entry_id IS NULL
          OR (
            introduction.entry_id IS NOT NULL
            AND (
              introduction.predecessor_entry_id IS NULL
              OR predecessor_unlock.available_at <= reference_now
            )
          )
        )
      )
    )
    AND CASE WHEN p_filtered THEN
      matches_filter AND has_status AND
      (p_card_filter='both' OR (p_card_filter='review' AND fsrs_enabled=true)
        OR (p_card_filter='new' AND COALESCE(fsrs_enabled,false)=false))
    ELSE NOT has_status OR fsrs_enabled=true END
)
 SELECT entry_id,card_type_id,fsrs_enabled,introduced,next_review_at,intrinsic_source FROM eligible;
 $_$;


--
-- Name: training_reference_now_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_reference_now_v1() RETURNS timestamp with time zone
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  configured_now text := current_setting('training.test_reference_now', true);
BEGIN
  IF configured_now IS NULL OR btrim(configured_now) = '' THEN
    RETURN statement_timestamp();
  END IF;

  RETURN configured_now::timestamptz;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow THEN
  RAISE EXCEPTION 'invalid training.test_reference_now';
END;
$$;


--
-- Name: FUNCTION training_reference_now_v1(); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.training_reference_now_v1() IS 'Real SQL request timestamp, with a transaction-local test-only override for deterministic temporal evidence.';


--
-- Name: training_review_early_v1(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_review_early_v1(p_filter jsonb, p_card_filter text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
  IF NOT COALESCE(p_filter,'{}'::jsonb) ? 'reviewTiming' THEN RETURN false; END IF;
  IF p_filter->>'reviewTiming' IS DISTINCT FROM 'early' OR p_card_filter IS DISTINCT FROM 'review' THEN
    RAISE EXCEPTION 'invalid_training_review_timing';
  END IF;
  RETURN true;
END;
$$;


--
-- Name: training_schedule_timezone_v1(text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_schedule_timezone_v1(p_timezone text) RETURNS text
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_timezone text := COALESCE(NULLIF(trim(p_timezone), ''), 'UTC');
BEGIN
  -- Ask PostgreSQL to resolve the IANA name now.  A malformed client value
  -- must not make scheduler eligibility error or become durable state.
  PERFORM now() AT TIME ZONE v_timezone;
  RETURN v_timezone;
EXCEPTION WHEN others THEN
  RETURN 'UTC';
END;
$$;


--
-- Name: training_scheduler_candidates_v2(uuid, text[], uuid, text, text, text, uuid[], text[], jsonb, boolean, boolean); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_scheduler_candidates_v2(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_entry_ids uuid[], p_exclude_card_keys text[], p_training_filter jsonb, p_filtered boolean, p_enforce_daily_limits boolean) RETURNS TABLE(entry_id uuid, card_type_id text, queue_source text, selection_order bigint, new_today bigint, daily_new_limit bigint, new_pool_size bigint, learning_due_count bigint, review_pool_size bigint)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    SET enable_nestloop TO 'off'
    AS $_$
WITH shared_entries AS MATERIALIZED (
      SELECT entry_id FROM private.shared_author_entry_ids_v1(p_user_id)
    ), shared_dictionaries AS MATERIALIZED (
      SELECT DISTINCT entry.dictionary_id FROM shared_entries shared
      JOIN private.active_word_entries entry ON entry.id=shared.entry_id
    ), args AS (
  SELECT CASE
      WHEN p_card_type_ids IS NULL OR cardinality(p_card_type_ids)=0
        THEN ARRAY['word-to-definition']::text[]
      ELSE ARRAY(
        SELECT DISTINCT trim(mode)
        FROM unnest(p_card_type_ids) requested(mode)
        WHERE trim(mode)<>'' ORDER BY 1
      )
    END modes,
    COALESCE(p_training_filter,'{}') filter_data,
    COALESCE(p_list_type,'curated') list_type,
    COALESCE(p_exclude_entry_ids,ARRAY[]::uuid[]) excluded_entries,
    COALESCE(p_exclude_card_keys,ARRAY[]::text[]) excluded_cards
), reference_now AS MATERIALIZED (
  SELECT private.training_reference_now_v1() AS now_at
), filter_values AS (
  SELECT args.*,
    private.training_filter_target_date(filter_data) target_date,
    private.training_schedule_timezone_v1(
      COALESCE(
        NULLIF(trim(filter_data->>'timezone'),''),
        private.training_user_timezone_v1(p_user_id)
      )
    ) timezone,
    reference_now.now_at,
    bounds.start_at study_day_start,
    bounds.end_at study_day_end,
    CASE WHEN NULLIF(filter_data->>'sourceId','') ~
      '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
      THEN (filter_data->>'sourceId')::uuid END source_id,
    NULLIF(trim(filter_data->>'sourceKind'),'') source_kind,
    NULLIF(trim(filter_data->>'externalId'),'') external_id,
    NULLIF(trim(filter_data#>>'{dictionaryScope,mode}'),'') dictionary_mode,
    NULLIF(trim(filter_data#>>'{dictionaryScope,languageCode}'),'') dictionary_language
  FROM args
  CROSS JOIN reference_now
  CROSS JOIN LATERAL private.training_study_day_bounds_v1(
    reference_now.now_at,
    private.training_schedule_timezone_v1(
      COALESCE(
        NULLIF(trim(args.filter_data->>'timezone'),''),
        private.training_user_timezone_v1(p_user_id)
      )
    )
  ) bounds
), mode_order AS (
  SELECT requested_mode.card_type_id,random() mode_random
  FROM filter_values
  CROSS JOIN unnest(filter_values.modes) requested_mode(card_type_id)
), cohort_context AS (
  SELECT md5(concat_ws('|',
    p_user_id::text,
    array_to_string(filter_values.modes,','),
    COALESCE(p_list_id::text,''),
    filter_values.list_type,
    p_card_filter,
    filter_values.filter_data::text
  )) cohort_seed
  FROM filter_values
), limits AS (
  SELECT COALESCE(settings.daily_new_limit,10)::bigint new_limit,
    COALESCE(settings.daily_review_limit,200)::bigint review_limit
  FROM (SELECT 1) seed
  LEFT JOIN user_settings settings ON settings.user_id=p_user_id
), daily AS (
  SELECT count(DISTINCT log.word_id) FILTER (WHERE log.review_type='new') new_today,
    count(*) FILTER (WHERE log.review_type='review') review_today
  FROM user_review_log log, filter_values
  WHERE log.user_id=p_user_id
    AND log.mode=ANY(filter_values.modes)
    AND log.reviewed_at >= filter_values.study_day_start
    AND log.reviewed_at < filter_values.study_day_end
), readable_dictionaries AS MATERIALIZED (
  SELECT dictionary.id,dictionary.language_code
  FROM dictionaries dictionary
  WHERE (
      (can_access_dictionary(p_user_id,dictionary.id,'read') AND (dictionary.kind<>'user' OR dictionary.owner_user_id=p_user_id))
      OR (dictionary.kind='user' AND dictionary.id IN (SELECT dictionary_id FROM shared_dictionaries)))
), selected_dictionaries AS MATERIALIZED (
  SELECT DISTINCT requested.id::uuid AS id
  FROM filter_values
  CROSS JOIN LATERAL jsonb_array_elements_text(
    CASE WHEN jsonb_typeof(filter_values.filter_data#>'{dictionaryScope,dictionaryIds}')='array'
      THEN filter_values.filter_data#>'{dictionaryScope,dictionaryIds}'
      ELSE '[]'::jsonb END
  ) requested(id)
  WHERE requested.id ~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$'
), raw_scope AS MATERIALIZED (
  SELECT scope_entry.entry_id AS id
  FROM private.default_training_scope_entries_v1 scope_entry
  CROSS JOIN filter_values
  LEFT JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=scope_entry.dictionary_id
  WHERE p_list_id IS NULL
    AND filter_values.dictionary_mode IS NULL
    AND NOT (filter_values.filter_data ? 'partOfSpeech'
      OR filter_values.filter_data ? 'nounArticles')
    AND NOT (scope_entry.entry_id=ANY(filter_values.excluded_entries))
    AND (scope_entry.dictionary_id IS NULL OR readable_dictionary.id IS NOT NULL)
  UNION ALL
  SELECT scope_entry.entry_id AS id
  FROM private.default_training_scope_entries_v1 scope_entry
  CROSS JOIN filter_values
  LEFT JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=scope_entry.dictionary_id
  JOIN private.active_word_entries lexical_entry ON lexical_entry.id=scope_entry.entry_id
  WHERE p_list_id IS NULL
    AND filter_values.dictionary_mode IS NULL
    AND (filter_values.filter_data ? 'partOfSpeech'
      OR filter_values.filter_data ? 'nounArticles')
    AND NOT (scope_entry.entry_id=ANY(filter_values.excluded_entries))
    AND (scope_entry.dictionary_id IS NULL OR readable_dictionary.id IS NOT NULL)
    AND private.training_lexical_candidate_matches_v1(
      lexical_entry.part_of_speech, lexical_entry.gender,
      filter_values.filter_data
    )
  UNION ALL
  SELECT entry.id
  FROM private.active_word_entries entry
  CROSS JOIN filter_values
  LEFT JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=entry.dictionary_id
  WHERE p_list_id IS NOT NULL
    AND filter_values.dictionary_mode IS NULL
    AND NOT EXISTS (
      SELECT 1
      FROM private.active_word_entries pointer_entry
      WHERE pointer_entry.id=entry.id
        AND private.is_pointer_only_dictionary_entry_v1(pointer_entry.raw)
    )
    AND NOT (entry.id=ANY(filter_values.excluded_entries))
    AND (entry.dictionary_id IS NULL OR readable_dictionary.id IS NOT NULL)
    AND ((filter_values.list_type='curated' AND EXISTS (
        SELECT 1 FROM word_list_items item
        WHERE item.list_id=p_list_id AND item.word_id=entry.id
      ))
      OR (filter_values.list_type='user' AND EXISTS (
        SELECT 1 FROM user_word_list_items item
        JOIN user_word_lists list ON list.id=item.list_id
        WHERE item.list_id=p_list_id AND item.word_id=entry.id AND (list.user_id=p_user_id
      OR list.id IN (SELECT collection_id FROM private.shared_collection_ids_v1(p_user_id)))
      )))
    AND CASE
      WHEN filter_values.filter_data ? 'partOfSpeech'
        OR filter_values.filter_data ? 'nounArticles'
      THEN private.training_lexical_candidate_matches_v1(
        entry.part_of_speech, entry.gender, filter_values.filter_data
      )
      ELSE true
    END
  UNION ALL
  SELECT entry.id
  FROM private.active_word_entries entry
  CROSS JOIN filter_values
  JOIN readable_dictionaries readable_dictionary
    ON readable_dictionary.id=entry.dictionary_id
   AND readable_dictionary.language_code=filter_values.dictionary_language
  WHERE p_list_id IS NULL
    AND filter_values.dictionary_mode IN ('all','selected')
    AND entry.language_code=filter_values.dictionary_language
    AND NOT (entry.id=ANY(filter_values.excluded_entries))
    AND (filter_values.dictionary_mode='all' OR EXISTS (
      SELECT 1 FROM selected_dictionaries selected
      WHERE selected.id=entry.dictionary_id
    ))
    AND NOT EXISTS (
      SELECT 1 FROM private.active_word_entries pointer_entry
      WHERE pointer_entry.id=entry.id
        AND private.is_pointer_only_dictionary_entry_v1(pointer_entry.raw)
    )
    AND CASE
      WHEN filter_values.filter_data ? 'partOfSpeech'
        OR filter_values.filter_data ? 'nounArticles'
      THEN private.training_lexical_candidate_matches_v1(
        entry.part_of_speech, entry.gender, filter_values.filter_data
      )
      ELSE true
    END
), scope AS MATERIALIZED (
    SELECT raw_scope.id FROM raw_scope
    JOIN private.active_word_entries material_entry ON material_entry.id=raw_scope.id
    LEFT JOIN public.dictionaries authority_dictionary ON authority_dictionary.id=material_entry.dictionary_id
    CROSS JOIN filter_values material_filter
    WHERE (material_entry.dictionary_id IS NULL OR authority_dictionary.kind<>'user'
      OR authority_dictionary.owner_user_id=p_user_id OR material_entry.id IN (SELECT entry_id FROM shared_entries))
      AND private.training_material_entry_selected_v1(
      material_entry.language_code,material_entry.dictionary_id,material_filter.filter_data)
  ), matched AS (
  SELECT event.entry_id,event.card_type_id,max(event.created_at) latest_event_at
  FROM user_card_action_events event
  LEFT JOIN learning_sources source ON source.id=event.source_id
  CROSS JOIN filter_values
  WHERE event.user_id=p_user_id
    AND event.card_type_id=ANY(filter_values.modes)
    AND (filter_values.target_date IS NULL OR
      private.training_filter_local_date(event.created_at,filter_values.timezone)=filter_values.target_date)
    AND (filter_values.source_id IS NULL OR event.source_id=filter_values.source_id)
    AND (filter_values.source_kind IS NULL OR source.kind=filter_values.source_kind
      OR source.provider=filter_values.source_kind
      OR (filter_values.source_kind='youtube' AND
        (source.kind IN ('youtube','youtube_video') OR source.provider='youtube')))
    AND (filter_values.external_id IS NULL OR source.external_id=filter_values.external_id)
  GROUP BY event.entry_id,event.card_type_id
), study_day_new_words AS MATERIALIZED (
  SELECT DISTINCT log.word_id
  FROM user_review_log log, filter_values
  WHERE log.user_id=p_user_id
    AND log.mode=ANY(filter_values.modes)
    AND log.review_type='new'
    AND log.reviewed_at >= filter_values.study_day_start
    AND log.reviewed_at < filter_values.study_day_end
), study_day_new_cards AS MATERIALIZED (
  SELECT DISTINCT log.word_id,log.mode AS card_type_id
  FROM user_review_log log, filter_values
  WHERE log.user_id=p_user_id
    AND log.mode=ANY(filter_values.modes)
    AND log.review_type='new'
    AND log.reviewed_at >= filter_values.study_day_start
    AND log.reviewed_at < filter_values.study_day_end
), known_cards AS MATERIALIZED (
  SELECT known.entry_id,known.card_type_id
  FROM user_card_known_marks known,filter_values
  WHERE known.user_id=p_user_id
    AND known.card_type_id=ANY(filter_values.modes)
    AND known.cleared_at IS NULL
), learner_status AS MATERIALIZED (
  SELECT status.*
  FROM user_card_status status,filter_values
  WHERE status.user_id=p_user_id
    AND status.card_type_id=ANY(filter_values.modes)
), unrenderable_direct_entries AS MATERIALIZED (
  SELECT entry_id FROM private.unrenderable_ordinary_direct_entries_v1
), active_source_bindings AS MATERIALIZED (
  SELECT binding.dictionary_id, binding.identity_scheme_version,
    binding.source_group_key, binding.sense_ordinal, binding.word_entry_id
  FROM private.source_entry_bindings binding
  WHERE binding.binding_state = 'active'
), source_bound_entries AS MATERIALIZED (
  SELECT binding.word_entry_id AS entry_id
  FROM active_source_bindings binding
), scoped_source_groups AS NOT MATERIALIZED (
  SELECT DISTINCT binding.dictionary_id, binding.identity_scheme_version,
    binding.source_group_key
  FROM active_source_bindings binding
  JOIN scope ON scope.id = binding.word_entry_id
), active_source_definitions AS MATERIALIZED (
  SELECT definition.entry_id
  FROM private.platform_v2_content_nodes definition
  WHERE definition.binding_state = 'active'
    AND definition.parent_content_node_id IS NULL
    AND definition.kind = 'definition'
), ordinary_source_introductions AS MATERIALIZED (
  SELECT binding.word_entry_id AS entry_id,
    lag(binding.word_entry_id) OVER (
      PARTITION BY binding.dictionary_id, binding.identity_scheme_version,
        binding.source_group_key
      ORDER BY binding.sense_ordinal, binding.word_entry_id
    ) AS predecessor_entry_id
  FROM active_source_bindings binding
  JOIN scoped_source_groups source_group
    USING (dictionary_id, identity_scheme_version, source_group_key)
  JOIN active_source_definitions definition
    ON definition.entry_id = binding.word_entry_id
  -- Active bindings and exception entry IDs are non-null by schema. Hashing
  -- this small exception set avoids one index probe per scoped meaning.
  WHERE binding.word_entry_id NOT IN (
    SELECT unrenderable.entry_id FROM unrenderable_direct_entries unrenderable
  )
), cards AS (
  SELECT scope.id entry_id,mode_order.card_type_id,status.fsrs_enabled,
    status.fsrs_last_interval,status.next_review_at,status.hidden,status.frozen_until,
    (COALESCE(status.fsrs_reps,0)>0 OR status.last_reviewed_at IS NOT NULL) introduced,
    status.entry_id IS NOT NULL has_status,matched.entry_id IS NOT NULL matches_filter,
    matched.latest_event_at,mode_order.mode_random,
    filter_values.now_at reference_now,
    study_day_new_words.word_id IS NOT NULL new_seen_today,
    study_day_new_cards.word_id IS NOT NULL new_card_seen_today,
    CASE
      WHEN private.training_review_early_v1(p_training_filter,p_card_filter)
        AND status.fsrs_enabled=true THEN
          CASE WHEN COALESCE(status.fsrs_last_interval,0)<1 THEN 'learning' ELSE 'review' END
      WHEN status.fsrs_enabled=true AND COALESCE(status.fsrs_last_interval,0)<1
        AND status.next_review_at<=filter_values.now_at THEN 'learning'
      WHEN status.fsrs_enabled=true AND status.fsrs_last_interval>=1
        AND status.next_review_at<=filter_values.now_at THEN 'review'
      WHEN status.entry_id IS NULL OR COALESCE(status.fsrs_enabled,false)=false THEN 'new'
      ELSE 'practice'
    END intrinsic_source
  FROM scope
  CROSS JOIN filter_values CROSS JOIN mode_order
  LEFT JOIN learner_status status ON status.entry_id=scope.id
    AND status.card_type_id=mode_order.card_type_id
  LEFT JOIN matched ON matched.entry_id=scope.id AND matched.card_type_id=mode_order.card_type_id
  LEFT JOIN study_day_new_words ON study_day_new_words.word_id=scope.id
  LEFT JOIN study_day_new_cards ON study_day_new_cards.word_id=scope.id
    AND study_day_new_cards.card_type_id=mode_order.card_type_id
  LEFT JOIN known_cards ON known_cards.entry_id=scope.id
    AND known_cards.card_type_id=mode_order.card_type_id
  WHERE NOT ((scope.id::text||':'||mode_order.card_type_id)=ANY(filter_values.excluded_cards))
    AND known_cards.entry_id IS NULL
    AND (mode_order.card_type_id NOT IN ('word-to-definition','definition-to-word') OR NOT EXISTS (
      SELECT 1 FROM private.training_headword_exclusions exclusion
      WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
        AND exclusion.entry_id=scope.id))
    AND NOT EXISTS (SELECT 1 FROM private.training_pair_exclusions exclusion
      WHERE exclusion.user_id=p_user_id AND exclusion.restored_at IS NULL
        AND exclusion.pair_key=private.training_pair_key_v1(
          'meaning', scope.id, NULL, NULL, mode_order.card_type_id))
), eligible AS (
  SELECT cards.*
  FROM cards
  LEFT JOIN unrenderable_direct_entries unrenderable
    ON unrenderable.entry_id = cards.entry_id
  LEFT JOIN source_bound_entries source_bound
    ON source_bound.entry_id = cards.entry_id
  LEFT JOIN ordinary_source_introductions introduction
    ON introduction.entry_id = cards.entry_id
  LEFT JOIN private.ordinary_meaning_introduction_unlocks_v1 predecessor_unlock
    ON predecessor_unlock.user_id = p_user_id
   AND predecessor_unlock.entry_id = introduction.predecessor_entry_id
  WHERE COALESCE(hidden,false)=false AND (frozen_until IS NULL OR frozen_until<=reference_now)
    AND (NOT private.training_review_early_v1(p_training_filter,p_card_filter)
      OR (cards.introduced AND cards.fsrs_enabled=true))
    AND CASE
      WHEN (SELECT filter_data->>'presentationMode' FROM filter_values)
        = 'word-in-context'
      THEN private.training_word_context_candidate_v1(
        p_user_id, cards.entry_id, cards.card_type_id)
      ELSE true
    END
    AND (
      card_type_id <> 'word-to-definition'
      OR unrenderable.entry_id IS NULL
    )
    AND (
      intrinsic_source <> 'new'
      OR (
        card_type_id = 'definition-to-word'
        AND COALESCE((SELECT filter_data->>'presentationMode' FROM filter_values), '')
          = 'word-in-context'
      )
      OR (
        card_type_id = 'word-to-definition'
        AND (
          source_bound.entry_id IS NULL
          OR (
            introduction.entry_id IS NOT NULL
            AND (
              introduction.predecessor_entry_id IS NULL
              OR predecessor_unlock.available_at <= reference_now
            )
          )
        )
      )
    )
    AND CASE WHEN p_filtered THEN
      matches_filter AND has_status AND
      (p_card_filter='both' OR (p_card_filter='review' AND fsrs_enabled=true)
        OR (p_card_filter='new' AND COALESCE(fsrs_enabled,false)=false))
    ELSE NOT has_status OR fsrs_enabled=true END
), new_word_ranks AS (
  SELECT unseen.entry_id,
    row_number() OVER (
      ORDER BY md5(cohort_context.cohort_seed||':'||unseen.entry_id::text)
    ) new_word_ordinal,
    count(*) OVER () new_word_count
  FROM (
    SELECT DISTINCT entry_id FROM eligible
    WHERE intrinsic_source='new' AND NOT new_seen_today
  ) unseen CROSS JOIN cohort_context
), ranked AS (
  SELECT eligible.*,
    row_number() OVER (
      PARTITION BY eligible.intrinsic_source
      ORDER BY CASE WHEN eligible.intrinsic_source IN ('review','learning') THEN eligible.next_review_at END,
        md5(eligible.entry_id::text||':'||eligible.card_type_id)
    ) source_ordinal,
    new_word_ranks.new_word_ordinal,
    COALESCE((SELECT max(new_word_count) FROM new_word_ranks),0) new_word_count,
    count(*) FILTER (WHERE intrinsic_source='review') OVER () review_count
  FROM eligible
  LEFT JOIN new_word_ranks ON new_word_ranks.entry_id=eligible.entry_id
), classified AS (
  SELECT ranked.*,
    GREATEST(0,limits.new_limit-COALESCE(daily.new_today,0)) new_remaining,
    GREATEST(0,limits.review_limit-COALESCE(daily.review_today,0)) review_remaining
  FROM ranked CROSS JOIN limits CROSS JOIN daily
), scheduled AS (
  SELECT classified.*,
    CASE
      WHEN private.training_review_early_v1(p_training_filter,p_card_filter) THEN intrinsic_source
      WHEN p_filtered AND (
        p_card_filter = 'both'
        OR (p_card_filter = 'new' AND intrinsic_source = 'new')
        OR (p_card_filter = 'review' AND intrinsic_source IN ('review', 'learning'))
      ) THEN intrinsic_source
      WHEN p_filtered THEN NULL
      WHEN intrinsic_source='learning' AND p_card_filter IN ('both','review') THEN 'learning'
      WHEN intrinsic_source='review' AND p_card_filter<>'new' THEN 'review'
      WHEN intrinsic_source='new' AND p_card_filter<>'review' THEN 'new'
      ELSE 'practice'
    END queue_source
  FROM classified
), diagnostics AS (
  SELECT
    CASE WHEN p_filtered THEN
      count(*) FILTER (
        WHERE matches_filter AND has_status AND COALESCE(hidden,false)=false
          AND (frozen_until IS NULL OR frozen_until<=reference_now)
          AND COALESCE(fsrs_enabled,false)=false
      )
    ELSE (
      SELECT count(*)
      FROM scope
      LEFT JOIN (SELECT DISTINCT entry_id FROM learner_status) pool_status
        ON pool_status.entry_id=scope.id
      WHERE pool_status.entry_id IS NULL
    ) END AS new_pool_size,
    count(*) FILTER (
      WHERE (NOT p_filtered OR matches_filter) AND has_status
        AND COALESCE(hidden,false)=false
        AND (frozen_until IS NULL OR frozen_until<=reference_now)
        AND COALESCE(fsrs_enabled,false)=true
        AND COALESCE(fsrs_last_interval,0)<1 AND next_review_at<=reference_now
    ) AS learning_due_count,
    count(*) FILTER (
      WHERE (NOT p_filtered OR matches_filter) AND has_status
        AND COALESCE(hidden,false)=false
        AND (frozen_until IS NULL OR frozen_until<=reference_now)
        AND COALESCE(fsrs_enabled,false)=true
        AND fsrs_last_interval>=1 AND next_review_at<=reference_now
    ) AS review_pool_size
  FROM cards
), ordered AS (
  SELECT scheduled.*,
    CASE
      WHEN p_filtered AND p_queue_turn='review' AND queue_source IN ('review','learning') THEN 0
      WHEN p_filtered AND p_queue_turn='new' AND queue_source='new' THEN 0
      WHEN NOT p_filtered AND p_queue_turn='new' AND queue_source='new' THEN 0
      WHEN NOT p_filtered AND p_queue_turn='new' AND queue_source='learning' THEN 1
      WHEN NOT p_filtered AND p_queue_turn='new' AND queue_source='review' THEN 2
      WHEN queue_source='review' THEN 1
      WHEN queue_source='learning' THEN 2
      WHEN queue_source='new' THEN 3
      ELSE 4
    END source_rank
  FROM scheduled WHERE queue_source IS NOT NULL
)
SELECT entry_id,card_type_id,queue_source,
  row_number() OVER (ORDER BY
    CASE WHEN private.training_review_early_v1(p_training_filter,p_card_filter) THEN 0 ELSE source_rank END,
    CASE WHEN private.training_review_early_v1(p_training_filter,p_card_filter) THEN next_review_at END,
    CASE WHEN p_filtered THEN latest_event_at END DESC NULLS LAST,
    CASE WHEN queue_source IN ('review','learning') THEN next_review_at END,
    CASE WHEN queue_source IN ('new','practice') THEN mode_random END,
    CASE WHEN queue_source IN ('new','practice') THEN random() END) selection_order,
  COALESCE(daily.new_today,0),limits.new_limit,COALESCE(diagnostics.new_pool_size,0),
  COALESCE(diagnostics.learning_due_count,0),LEAST(COALESCE(diagnostics.review_pool_size,0),10)
FROM ordered CROSS JOIN daily CROSS JOIN limits CROSS JOIN diagnostics;
$_$;


--
-- Name: FUNCTION training_scheduler_candidates_v2(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_entry_ids uuid[], p_exclude_card_keys text[], p_training_filter jsonb, p_filtered boolean, p_enforce_daily_limits boolean); Type: COMMENT; Schema: private; Owner: -
--

COMMENT ON FUNCTION private.training_scheduler_candidates_v2(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_entry_ids uuid[], p_exclude_card_keys text[], p_training_filter jsonb, p_filtered boolean, p_enforce_daily_limits boolean) IS 'Canonical Training candidates with accessible dictionary or collection scope, learner-local study-day, pre-queue Dutch lexical filters, and scoped predecessor ordering; finite session size is the only budget.';


--
-- Name: training_session_members_v1(uuid, text[], uuid, text, text, jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_session_members_v1(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text) RETURNS TABLE(entry_id uuid, card_type_id text, queue_source text, session_ordinal integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
WITH RECURSIVE requested AS (
  SELECT CASE WHEN p_session_size = 'all-due-today' THEN NULL
              ELSE p_session_size::integer END AS requested_total
), candidates AS MATERIALIZED (
  SELECT candidate.entry_id,
    candidate.card_type_id,
    candidate.queue_source,
    candidate.selection_order,
    CASE WHEN candidate.queue_source = 'new' THEN 'new' ELSE 'review' END AS category
  FROM private.training_scheduler_candidates_v2(
    p_user_id, p_card_type_ids, p_list_id, COALESCE(p_list_type, 'curated'),
    p_card_filter, 'auto', ARRAY[]::uuid[], ARRAY[]::text[],
    COALESCE(p_training_filter, '{}'::jsonb),
    private.training_filter_target_date(COALESCE(p_training_filter, '{}'::jsonb)) IS NOT NULL
      OR NULLIF(COALESCE(p_training_filter, '{}'::jsonb)->>'sourceId', '') IS NOT NULL
      OR NULLIF(trim(COALESCE(p_training_filter, '{}'::jsonb)->>'sourceKind'), '') IS NOT NULL
      OR NULLIF(trim(COALESCE(p_training_filter, '{}'::jsonb)->>'externalId'), '') IS NOT NULL,
    false
  ) candidate
  WHERE candidate.queue_source IN ('new', 'learning', 'review')
), ranked AS MATERIALIZED (
  SELECT candidates.*,
    row_number() OVER (
      PARTITION BY category ORDER BY selection_order
    )::integer AS category_rank
  FROM candidates
), policy AS MATERIALIZED (
  SELECT
    count(*) FILTER (WHERE category = 'new')::integer AS available_new,
    count(*) FILTER (WHERE category = 'review')::integer AS available_review,
    LEAST(5, GREATEST(1, COALESCE(settings.new_review_ratio, 2)))::integer AS ratio,
    COALESCE(
      requested.requested_total,
      count(*) FILTER (WHERE category IN ('new', 'review'))::integer
    ) AS target_total
  FROM ranked
  CROSS JOIN requested
  LEFT JOIN user_settings settings ON settings.user_id = p_user_id
  GROUP BY requested.requested_total, settings.new_review_ratio
), sequence(
  session_ordinal, phase, new_taken, review_taken, category, category_rank
) AS (
  SELECT
    1,
    1,
    CASE WHEN choice.category = 'new' THEN 1 ELSE 0 END,
    CASE WHEN choice.category = 'review' THEN 1 ELSE 0 END,
    choice.category,
    1
  FROM policy
  CROSS JOIN LATERAL (
    SELECT CASE
      WHEN policy.available_new > 0 THEN 'new'
      WHEN policy.available_review > 0 THEN 'review'
    END AS category
  ) choice
  WHERE policy.target_total > 0
    AND choice.category IS NOT NULL

  UNION ALL

  SELECT
    sequence.session_ordinal + 1,
    CASE
      WHEN choice.category = 'new' THEN 1
      WHEN sequence.phase >= policy.ratio THEN 0
      ELSE sequence.phase + 1
    END,
    sequence.new_taken + CASE WHEN choice.category = 'new' THEN 1 ELSE 0 END,
    sequence.review_taken + CASE WHEN choice.category = 'review' THEN 1 ELSE 0 END,
    choice.category,
    CASE WHEN choice.category = 'new'
      THEN sequence.new_taken + 1
      ELSE sequence.review_taken + 1
    END
  FROM sequence
  CROSS JOIN policy
  CROSS JOIN LATERAL (
    SELECT CASE
      WHEN sequence.phase = 0 AND sequence.new_taken < policy.available_new THEN 'new'
      WHEN sequence.phase = 0 AND sequence.review_taken < policy.available_review THEN 'review'
      WHEN sequence.phase > 0 AND sequence.review_taken < policy.available_review THEN 'review'
      WHEN sequence.phase > 0 AND sequence.new_taken < policy.available_new THEN 'new'
    END AS category
  ) choice
  WHERE sequence.session_ordinal < policy.target_total
    AND choice.category IS NOT NULL
)
SELECT ranked.entry_id,
  ranked.card_type_id,
  ranked.queue_source,
  sequence.session_ordinal
FROM sequence
JOIN ranked
  ON ranked.category = sequence.category
 AND ranked.category_rank = sequence.category_rank
ORDER BY sequence.session_ordinal;
$$;


--
-- Name: training_session_members_v1(uuid, text[], uuid, text, text, jsonb, text, integer); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_session_members_v1(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text, p_new_review_ratio integer) RETURNS TABLE(entry_id uuid, card_type_id text, queue_source text, session_ordinal integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
 SELECT * FROM private.training_session_members_v1($1,$2,$3,$4,$5,$6,$7,$8,ARRAY[]::text[]);
$_$;


--
-- Name: training_session_members_v1(uuid, text[], uuid, text, text, jsonb, text, integer, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_session_members_v1(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text, p_new_review_ratio integer, p_exclude_card_keys text[]) RETURNS TABLE(entry_id uuid, card_type_id text, queue_source text, session_ordinal integer)
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
WITH RECURSIVE requested AS (
  SELECT CASE WHEN p_session_size = 'all-due-today' THEN NULL
              ELSE p_session_size::integer END AS requested_total
), candidates AS MATERIALIZED (
  SELECT candidate.entry_id,
    candidate.card_type_id,
    candidate.queue_source,
    candidate.selection_order,
    CASE WHEN candidate.queue_source = 'new' THEN 'new' ELSE 'review' END AS category
  FROM private.training_scheduler_candidates_v2(
    p_user_id, p_card_type_ids, p_list_id, COALESCE(p_list_type, 'curated'),
    p_card_filter, 'auto', ARRAY[]::uuid[], COALESCE(p_exclude_card_keys,ARRAY[]::text[]),
    COALESCE(p_training_filter, '{}'::jsonb),
    private.training_filter_target_date(COALESCE(p_training_filter, '{}'::jsonb)) IS NOT NULL
      OR NULLIF(COALESCE(p_training_filter, '{}'::jsonb)->>'sourceId', '') IS NOT NULL
      OR NULLIF(trim(COALESCE(p_training_filter, '{}'::jsonb)->>'sourceKind'), '') IS NOT NULL
      OR NULLIF(trim(COALESCE(p_training_filter, '{}'::jsonb)->>'externalId'), '') IS NOT NULL,
    false
  ) candidate
  WHERE candidate.queue_source IN ('new', 'learning', 'review')
), ranked AS MATERIALIZED (
  SELECT candidates.*,
    row_number() OVER (
      PARTITION BY category ORDER BY selection_order
    )::integer AS category_rank
  FROM candidates
), policy AS MATERIALIZED (
  SELECT
    count(*) FILTER (WHERE category = 'new')::integer AS available_new,
    count(*) FILTER (WHERE category = 'review')::integer AS available_review,
    p_new_review_ratio AS ratio,
    COALESCE(
      requested.requested_total,
      count(*) FILTER (WHERE category IN ('new', 'review'))::integer
    ) AS target_total
  FROM ranked
  CROSS JOIN requested
  GROUP BY requested.requested_total
), sequence(
  session_ordinal, phase, new_taken, review_taken, category, category_rank
) AS (
  SELECT
    1,
    1,
    CASE WHEN choice.category = 'new' THEN 1 ELSE 0 END,
    CASE WHEN choice.category = 'review' THEN 1 ELSE 0 END,
    choice.category,
    1
  FROM policy
  CROSS JOIN LATERAL (
    SELECT CASE
      WHEN policy.available_new > 0 THEN 'new'
      WHEN policy.available_review > 0 THEN 'review'
    END AS category
  ) choice
  WHERE policy.target_total > 0
    AND choice.category IS NOT NULL

  UNION ALL

  SELECT
    sequence.session_ordinal + 1,
    CASE
      WHEN choice.category = 'new' THEN 1
      WHEN sequence.phase >= policy.ratio THEN 0
      ELSE sequence.phase + 1
    END,
    sequence.new_taken + CASE WHEN choice.category = 'new' THEN 1 ELSE 0 END,
    sequence.review_taken + CASE WHEN choice.category = 'review' THEN 1 ELSE 0 END,
    choice.category,
    CASE WHEN choice.category = 'new'
      THEN sequence.new_taken + 1
      ELSE sequence.review_taken + 1
    END
  FROM sequence
  CROSS JOIN policy
  CROSS JOIN LATERAL (
    SELECT CASE
      WHEN sequence.phase = 0 AND sequence.new_taken < policy.available_new THEN 'new'
      WHEN sequence.phase = 0 AND sequence.review_taken < policy.available_review THEN 'review'
      WHEN sequence.phase > 0 AND sequence.review_taken < policy.available_review THEN 'review'
      WHEN sequence.phase > 0 AND sequence.new_taken < policy.available_new THEN 'new'
    END AS category
  ) choice
  WHERE sequence.session_ordinal < policy.target_total
    AND choice.category IS NOT NULL
)
SELECT ranked.entry_id,
  ranked.card_type_id,
  ranked.queue_source,
  sequence.session_ordinal
FROM sequence
JOIN ranked
  ON ranked.category = sequence.category
 AND ranked.category_rank = sequence.category_rank
ORDER BY sequence.session_ordinal;
$$;


--
-- Name: training_session_run_response_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_session_run_response_v1(p_user_id uuid, p_session_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
    SELECT jsonb_build_object(
        'sessionId', session.id,
        'sessionSize', session.session_size,
        'requestedTotal', session.requested_total,
        'plannedNew', session.planned_new,
        'plannedReview', session.planned_review,
        'plannedPractice', session.planned_practice,
        'plannedTotal', session.planned_total,
        'plannedAt', session.created_at,
        'runStatus', CASE
            WHEN active.session_id = session.id THEN 'active'
            ELSE 'superseded'
        END,
        'runGeneration', CASE
            WHEN active.session_id = session.id THEN active.generation
            ELSE NULL
        END
    )
      FROM public.training_sessions AS session
      LEFT JOIN public.training_active_runs AS active
        ON active.user_id = session.user_id
     WHERE session.id = p_session_id
       AND session.user_id = p_user_id;
$$;


--
-- Name: training_study_day_bounds_v1(timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_study_day_bounds_v1(p_now timestamp with time zone, p_timezone text) RETURNS TABLE(study_date date, start_at timestamp with time zone, end_at timestamp with time zone)
    LANGUAGE sql STABLE ROWS 1
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  WITH timezone AS (
    SELECT private.training_authoritative_timezone_v1((select auth.uid()), p_timezone) AS timezone
  ), normalized AS (
    SELECT
      timezone.timezone,
      private.training_study_day_date_v1(
        p_now,
        timezone.timezone
      ) AS study_date
    FROM timezone
  )
  SELECT
    normalized.study_date,
    (
      normalized.study_date::timestamp + interval '4 hours'
    ) AT TIME ZONE normalized.timezone,
    (
      (normalized.study_date + 1)::timestamp + interval '4 hours'
    ) AT TIME ZONE normalized.timezone
  FROM normalized;
$$;


--
-- Name: training_study_day_date_v1(timestamp with time zone, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_study_day_date_v1(p_timestamp timestamp with time zone, p_timezone text) RETURNS date
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT (
    (
      p_timestamp AT TIME ZONE private.training_schedule_timezone_v1(p_timezone)
    ) - interval '4 hours'
  )::date;
$$;


--
-- Name: training_translation_session_response_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_translation_session_response_v1(p_user_id uuid, p_session_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
    SELECT private.training_session_run_response_v1(p_user_id, session.id)
        || jsonb_build_object(
            'contractVersion', 'platform-translation-exercise-session-v1',
            'exerciseFamily', 'translation',
            'direction', 'recall',
            'completedActions', COALESCE(completed.actions, 0),
            'completionReason', session.completion_reason,
            'members', COALESCE(members.items, '[]'::jsonb)
        )
      FROM public.training_sessions AS session
      LEFT JOIN LATERAL (
          SELECT count(*)::integer AS actions
            FROM public.training_session_exercise_members AS member
           WHERE member.session_id = session.id AND member.consumed_at IS NOT NULL
      ) AS completed ON true
      LEFT JOIN LATERAL (
          SELECT jsonb_agg(jsonb_build_object(
              'ordinal', member.ordinal,
              'targetId', member.target_id,
              'queueSource', member.queue_source,
              'consumedAt', member.consumed_at,
              'unavailableAt', member.unavailable_at,
              'unavailableReason', member.unavailable_reason,
              'entryId', target.entry_id,
              'contentNodeId', target.content_node_id,
              'family', target.family,
              'direction', target.direction
          ) ORDER BY member.ordinal) AS items
            FROM public.training_session_exercise_members AS member
            JOIN private.platform_v2_training_exercise_targets AS target
              ON target.id = member.target_id
            JOIN private.active_word_entries AS entry ON entry.id = target.entry_id
           WHERE member.session_id = session.id
             AND target.family = 'translation'
             AND private.entry_access_v1(p_user_id,entry.id,'train')
             AND private.platform_v2_training_ordinary_meaning_eligible_v1(p_user_id, target.entry_id)
      ) AS members ON true
     WHERE session.id = p_session_id
       AND session.user_id = p_user_id
       AND session.exercise_family = 'translation';
$$;


--
-- Name: training_translation_source_nodes_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_translation_source_nodes_v1(p_user_id uuid, p_list_id uuid, p_list_type text, p_training_filter jsonb) RETURNS TABLE(content_node_id uuid, entry_id uuid, source_path text, source_text_fingerprint text, created_at timestamp with time zone, source_revision text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
  WITH shared_entries AS MATERIALIZED (
    SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(p_user_id) shared
  ), source_entries AS MATERIALIZED (
    SELECT entry_id
      FROM private.training_extra_source_entries_v1(
        p_user_id, p_list_id, p_list_type, p_training_filter
      )
  ), learned_entries AS MATERIALIZED (
    SELECT DISTINCT state.entry_id
      FROM (
        SELECT status.entry_id
          FROM public.user_card_status AS status
         WHERE status.user_id = p_user_id
           AND status.card_type_id IN (
             'word-to-definition', 'definition-to-word'
           )
           AND (
             COALESCE(status.in_learning, false)
             OR COALESCE(status.fsrs_enabled, false)
             OR COALESCE(status.fsrs_reps, 0) > 0
             OR status.last_reviewed_at IS NOT NULL
           )
        UNION ALL
        SELECT known.entry_id
          FROM public.user_card_known_marks AS known
         WHERE known.user_id = p_user_id
           AND known.card_type_id IN (
             'word-to-definition', 'definition-to-word'
           )
           AND known.cleared_at IS NULL
      ) AS state
  ), source_context AS MATERIALIZED (
    SELECT source.entry_id,
           entry.dictionary_id,
           binding.dictionary_id AS binding_dictionary_id,
           binding.identity_scheme_version,
           binding.source_group_key
      FROM source_entries AS source
      JOIN private.active_word_entries AS entry
        ON entry.id = source.entry_id
      LEFT JOIN private.source_entry_bindings AS binding
        ON binding.word_entry_id = entry.id
       AND binding.binding_state = 'active'
  ), learned_context AS MATERIALIZED (
    SELECT learned.entry_id,
           entry.dictionary_id,
           binding.dictionary_id AS binding_dictionary_id,
           binding.identity_scheme_version,
           binding.source_group_key
      FROM learned_entries AS learned
      JOIN private.active_word_entries AS entry
        ON entry.id = learned.entry_id
      LEFT JOIN private.source_entry_bindings AS binding
        ON binding.word_entry_id = entry.id
       AND binding.binding_state = 'active'
  ), dictionary_ids AS MATERIALIZED (
    SELECT dictionary_id
      FROM source_context
     WHERE dictionary_id IS NOT NULL
    UNION
    SELECT dictionary_id
      FROM learned_context
     WHERE dictionary_id IS NOT NULL
  ), dictionary_access AS MATERIALIZED (
    SELECT dictionary_id,
           public.can_access_dictionary(
             p_user_id, dictionary_id, 'read'
           ) AS can_read
      FROM dictionary_ids
  ), accessible_learned AS MATERIALIZED (
    SELECT learned.*
      FROM learned_context AS learned
     WHERE learned.dictionary_id IS NULL OR learned.entry_id IN (SELECT shared.entry_id FROM shared_entries shared)
        OR EXISTS (
          SELECT 1
            FROM dictionary_access AS access
           WHERE access.dictionary_id = learned.dictionary_id
             AND access.can_read
        )
  ), eligible_groups AS MATERIALIZED (
    SELECT DISTINCT source_group.dictionary_id,
           source_group.identity_scheme_version,
           source_group.source_group_key
      FROM private.platform_v2_headword_groups AS source_group
      JOIN accessible_learned AS learned
        ON learned.binding_dictionary_id = source_group.dictionary_id
       AND learned.identity_scheme_version = source_group.identity_scheme_version
       AND learned.source_group_key = source_group.source_group_key
     WHERE source_group.management_kind = 'source'
  ), eligible_entries AS MATERIALIZED (
    SELECT source.entry_id
      FROM source_context AS source
     WHERE (
       source.dictionary_id IS NULL OR source.entry_id IN (SELECT shared.entry_id FROM shared_entries shared)
       OR EXISTS (
         SELECT 1
           FROM dictionary_access AS access
          WHERE access.dictionary_id = source.dictionary_id
            AND access.can_read
       )
     )
       AND (
         EXISTS (
           SELECT 1
             FROM accessible_learned AS learned
            WHERE learned.entry_id = source.entry_id
         )
         OR EXISTS (
           SELECT 1
             FROM eligible_groups AS source_group
            WHERE source_group.dictionary_id = source.binding_dictionary_id
              AND source_group.identity_scheme_version = source.identity_scheme_version
              AND source_group.source_group_key = source.source_group_key
         )
       )
  ), source_nodes AS (
    SELECT node.id AS content_node_id,
           node.entry_id,
           node.diagnostic_locator AS source_path,
           node.source_text_fingerprint,
           node.created_at,
           encode(digest(
             node.id::text || ':' || node.source_text_fingerprint,
             'sha256'
           ), 'hex') AS source_revision
      FROM private.platform_v2_content_nodes AS node
      JOIN eligible_entries AS eligible
        ON eligible.entry_id = node.entry_id
     WHERE node.kind = 'example'
       AND node.binding_state = 'active'
       AND NULLIF(btrim(node.diagnostic_locator), '') IS NOT NULL
       AND node.diagnostic_locator ~ '^raw\.meanings\[[0-9]+\]\.examples\[[0-9]+\]$'
       AND NOT EXISTS (
         SELECT 1
           FROM private.platform_v2_training_exercise_targets AS stale
          WHERE stale.entry_id = node.entry_id
            AND stale.content_node_id = node.id
            AND stale.family = 'translation'
            AND stale.direction = 'recall'
            AND stale.source_text_fingerprint
                  IS DISTINCT FROM node.source_text_fingerprint
       )
  )
  SELECT * FROM source_nodes;
$_$;


--
-- Name: training_user_timezone_v1(uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_user_timezone_v1(p_user_id uuid) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT private.training_schedule_timezone_v1(
    COALESCE(
      NULLIF(trim(settings.training_schedule_timezone), ''),
      'UTC'
    )
  )
  FROM public.user_settings settings
  WHERE settings.user_id = p_user_id
  UNION ALL
  SELECT 'UTC'
  WHERE NOT EXISTS (
    SELECT 1
    FROM public.user_settings settings
    WHERE settings.user_id = p_user_id
  )
  LIMIT 1;
$$;


--
-- Name: training_word_context_candidate_v1(uuid, uuid, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_word_context_candidate_v1(p_user_id uuid, p_entry_id uuid, p_card_type_id text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
BEGIN
  IF p_card_type_id <> 'definition-to-word' THEN RETURN false; END IF;
  RETURN EXISTS (
    SELECT 1 FROM private.platform_v2_content_nodes AS example
    WHERE example.entry_id = p_entry_id
      AND example.kind = 'example'
      AND example.binding_state = 'active'
      AND NULLIF(btrim(example.diagnostic_locator), '') IS NOT NULL
      AND example.diagnostic_locator ~ '^raw\.meanings\[[0-9]+\]\.examples\[[0-9]+\]$'
  ) AND (
    EXISTS (
      SELECT 1 FROM public.user_card_status AS familiar
      WHERE familiar.user_id = p_user_id
        AND familiar.entry_id = p_entry_id
        AND familiar.card_type_id IN ('word-to-definition','definition-to-word')
        AND (COALESCE(familiar.in_learning,false)
          OR COALESCE(familiar.fsrs_enabled,false)
          OR COALESCE(familiar.fsrs_reps,0) > 0
          OR familiar.last_reviewed_at IS NOT NULL)
    )
    OR EXISTS (
      SELECT 1 FROM public.user_card_known_marks AS familiar_known
      WHERE familiar_known.user_id = p_user_id
        AND familiar_known.entry_id = p_entry_id
        AND familiar_known.card_type_id IN ('word-to-definition','definition-to-word')
        AND familiar_known.cleared_at IS NULL
    )
  );
END;
$_$;


--
-- Name: training_word_context_entry_available_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.training_word_context_entry_available_v1(p_user_id uuid, p_session_id uuid, p_entry_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
  SELECT EXISTS(
    SELECT 1 FROM public.training_sessions session
    JOIN public.training_active_runs active ON active.user_id=session.user_id AND active.session_id=session.id
    JOIN public.word_entries entry ON entry.id=p_entry_id
    WHERE session.id=p_session_id AND session.user_id=p_user_id
      AND session.completed_at IS NULL AND session.superseded_at IS NULL
      AND session.expires_at>private.training_reference_now_v1()
      AND ((private.author_entry_active_v1(p_entry_id) AND private.entry_access_v1(p_user_id,p_entry_id,'train')) OR (
        private.current_training_entry_permitted_v1(p_user_id,p_entry_id,'definition-to-word')
        AND EXISTS(SELECT 1 FROM private.training_current_card_permits permit
          WHERE permit.user_id=p_user_id AND permit.session_id=p_session_id
            AND permit.entry_id=p_entry_id AND permit.card_type_id='definition-to-word'
            AND permit.target_id IS NULL)
      ))
  );
$$;


--
-- Name: unsubscribe_collection_share_v1(uuid, uuid); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.unsubscribe_collection_share_v1(p_operation_id uuid, p_collection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); root private.collection_sharing_roots%rowtype; request jsonb; replay jsonb;
BEGIN
  IF p_collection_id IS NULL THEN RAISE EXCEPTION 'invalid_share_command' USING ERRCODE='22023'; END IF;
  request:=jsonb_build_object('action','unsubscribe','collectionId',p_collection_id);
  replay:=private.begin_collection_share_command_v1(p_operation_id,request);
  IF replay IS NOT NULL THEN RETURN replay; END IF;
  PERFORM private.lock_sharing_author_scope_v1(r.owner_user_id,true) FROM private.collection_sharing_roots r WHERE r.collection_id=p_collection_id;
  SELECT * INTO root FROM private.collection_sharing_roots r WHERE r.collection_id=p_collection_id FOR UPDATE;
  IF NOT FOUND OR root.owner_user_id=principal OR NOT EXISTS(SELECT 1 FROM private.collection_sharing_subscriptions s
    WHERE s.root_id=root.id AND s.user_id=principal) THEN
    RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501';
  END IF;
  UPDATE private.collection_sharing_subscriptions SET is_active=false WHERE user_id=principal AND root_id=root.id;
  RETURN private.finish_collection_share_command_v1(p_operation_id,request,
    jsonb_build_object('action','unsubscribe','rootId',root.id,'collectionId',p_collection_id));
END;
$$;


--
-- Name: validate_list_training_intent(text, text, text[]); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_list_training_intent(p_default_scenario_id text, p_card_policy text, p_card_type_ids text[]) RETURNS void
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
    IF p_card_policy NOT IN ('inherit', 'prefer', 'restrict') THEN
        RAISE EXCEPTION 'invalid_card_policy';
    END IF;

    IF p_default_scenario_id IS NOT NULL
       AND NOT EXISTS (
           SELECT 1
           FROM training_scenarios
           WHERE id = p_default_scenario_id
       ) THEN
        RAISE EXCEPTION 'scenario_not_found';
    END IF;

    IF p_card_type_ids IS NOT NULL
       AND EXISTS (
           SELECT 1
           FROM unnest(p_card_type_ids) AS card_type_id
           WHERE NULLIF(trim(card_type_id), '') IS NULL
       ) THEN
        RAISE EXCEPTION 'invalid_card_type_ids';
    END IF;
END;
$$;


--
-- Name: validate_platform_v2_content_node(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_platform_v2_content_node() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_parent_entry_id uuid;
BEGIN
    IF NEW.parent_content_node_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT entry_id
    INTO v_parent_entry_id
    FROM private.platform_v2_content_nodes
    WHERE id = NEW.parent_content_node_id;

    IF NOT FOUND
       OR v_parent_entry_id IS DISTINCT FROM NEW.entry_id
       OR NEW.parent_content_node_id = NEW.id THEN
        RAISE EXCEPTION 'platform_v2_content_node_parent_mismatch';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_platform_v2_headword_group(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_platform_v2_headword_group() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_dictionary public.dictionaries%rowtype;
    v_entry public.word_entries%rowtype;
BEGIN
    SELECT *
    INTO v_dictionary
    FROM public.dictionaries
    WHERE id = NEW.dictionary_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'platform_v2_group_dictionary_not_found';
    END IF;

    IF NEW.management_kind = 'source' THEN
        IF v_dictionary.kind = 'user' THEN
            RAISE EXCEPTION 'platform_v2_group_management_mismatch';
        END IF;
        RETURN NEW;
    END IF;

    SELECT *
    INTO v_entry
    FROM public.word_entries
    WHERE id = NEW.singleton_entry_id;

    IF NOT FOUND
       OR v_entry.dictionary_id IS DISTINCT FROM NEW.dictionary_id
       OR v_entry.management_kind <> 'user'
       OR v_dictionary.kind <> 'user'
       OR v_dictionary.owner_user_id IS DISTINCT FROM NEW.owner_user_id THEN
        RAISE EXCEPTION 'platform_v2_group_entry_mismatch';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_platform_v2_training_exercise_target_v1(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_platform_v2_training_exercise_target_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_node record;
BEGIN
    IF NEW.family = 'meaning' THEN
        RETURN NEW;
    END IF;

    SELECT entry_id, kind, binding_state, source_text_fingerprint
      INTO v_node
      FROM private.platform_v2_content_nodes
     WHERE id = NEW.content_node_id;

    IF NOT FOUND OR v_node.entry_id IS DISTINCT FROM NEW.entry_id THEN
        RAISE EXCEPTION 'training_exercise_content_node_entry_mismatch';
    END IF;
    IF v_node.binding_state IS DISTINCT FROM 'active' THEN
        RAISE EXCEPTION 'training_exercise_content_node_not_active';
    END IF;
    IF v_node.source_text_fingerprint IS DISTINCT FROM NEW.source_text_fingerprint THEN
        RAISE EXCEPTION 'training_exercise_source_fingerprint_mismatch';
    END IF;
    IF NEW.family = 'idiom' AND v_node.kind IS DISTINCT FROM 'idiom' THEN
        RAISE EXCEPTION 'training_exercise_idiom_node_required';
    END IF;
    IF NEW.family = 'translation' AND v_node.kind IS DISTINCT FROM 'example' THEN
        RAISE EXCEPTION 'training_exercise_sentence_node_required';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: validate_simple_user_entry_v1(jsonb, text); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_simple_user_entry_v1(p_payload jsonb, p_dictionary_language_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_payload jsonb := COALESCE(p_payload, '{}'::jsonb);
    v_headword text := NULLIF(trim(v_payload->>'headword'), '');
    v_language_code text := NULLIF(trim(v_payload->>'languageCode'), '');
BEGIN
    IF jsonb_typeof(v_payload) <> 'object' THEN
        RAISE EXCEPTION 'invalid_user_entry';
    END IF;

    IF v_headword IS NULL OR v_language_code IS NULL THEN
        RAISE EXCEPTION 'invalid_user_entry';
    END IF;

    IF v_language_code <> p_dictionary_language_code THEN
        RAISE EXCEPTION 'language_mismatch';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM languages WHERE code = v_language_code) THEN
        RAISE EXCEPTION 'language_not_found';
    END IF;

    IF NOT (
        NULLIF(trim(v_payload->>'definition'), '') IS NOT NULL
        OR (
            jsonb_typeof(v_payload->'translation') = 'object'
            AND NULLIF(trim(v_payload#>>'{translation,text}'), '') IS NOT NULL
        )
        OR (
            jsonb_typeof(v_payload->'example') = 'object'
            AND NULLIF(trim(v_payload#>>'{example,source}'), '') IS NOT NULL
        )
        OR NULLIF(trim(v_payload->>'notes'), '') IS NOT NULL
    ) THEN
        RAISE EXCEPTION 'invalid_user_entry';
    END IF;

    RETURN jsonb_strip_nulls(
        jsonb_build_object(
            'headword', v_headword,
            'languageCode', v_language_code,
            'definition', NULLIF(trim(v_payload->>'definition'), ''),
            'translation', CASE
                WHEN jsonb_typeof(v_payload->'translation') = 'object' THEN
                    jsonb_strip_nulls(jsonb_build_object(
                        'languageCode', NULLIF(trim(v_payload#>>'{translation,languageCode}'), ''),
                        'text', NULLIF(trim(v_payload#>>'{translation,text}'), '')
                    ))
                ELSE NULL
            END,
            'example', CASE
                WHEN jsonb_typeof(v_payload->'example') = 'object' THEN
                    jsonb_strip_nulls(jsonb_build_object(
                        'source', NULLIF(trim(v_payload#>>'{example,source}'), ''),
                        'translation', NULLIF(trim(v_payload#>>'{example,translation}'), '')
                    ))
                ELSE NULL
            END,
            'partOfSpeech', NULLIF(trim(v_payload->>'partOfSpeech'), ''),
            'gender', NULLIF(trim(v_payload->>'gender'), ''),
            'notes', NULLIF(trim(v_payload->>'notes'), ''),
            'tags', CASE
                WHEN jsonb_typeof(v_payload->'tags') = 'array' THEN v_payload->'tags'
                ELSE NULL
            END,
            'sourceEntryId', NULLIF(trim(v_payload->>'sourceEntryId'), ''),
            'generation', CASE
                WHEN jsonb_typeof(v_payload->'generation') = 'object' THEN v_payload->'generation'
                ELSE NULL
            END
        )
    );
END;
$$;


--
-- Name: validate_source_entry_binding(); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.validate_source_entry_binding() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_entry_dictionary_id uuid;
    v_management_kind text;
BEGIN
    IF NEW.word_entry_id IS NULL THEN
        RETURN NEW;
    END IF;

    SELECT dictionary_id, management_kind
    INTO v_entry_dictionary_id, v_management_kind
    FROM public.word_entries
    WHERE id = NEW.word_entry_id;

    IF v_entry_dictionary_id IS DISTINCT FROM NEW.dictionary_id
       OR v_management_kind <> 'source' THEN
        RAISE EXCEPTION 'source_binding_entry_mismatch';
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: verify_diagnostic_displayed_translation_atoms(uuid, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verify_diagnostic_displayed_translation_atoms(p_entry_id uuid, p_atoms jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_atom jsonb;
    v_artifact jsonb;
    v_expected_text text;
    v_bounded_text text;
    v_translation record;
BEGIN
    IF jsonb_array_length(p_atoms) = 0 THEN RETURN true; END IF;
    IF (
        SELECT count(DISTINCT atom->'artifact'->>'targetLanguageCode')
        FROM jsonb_array_elements(p_atoms) atom
    ) <> 1 THEN
        RAISE EXCEPTION 'translation_atom_not_supported';
    END IF;

    FOR v_atom IN SELECT value FROM jsonb_array_elements(p_atoms) LOOP
        v_artifact := v_atom->'artifact';
        IF v_atom->>'role' IS DISTINCT FROM 'displayed-translation'
           OR v_atom->'contentNodeId' IS DISTINCT FROM v_artifact->'contentNodeId'
        THEN RAISE EXCEPTION 'translation_atom_not_supported'; END IF;

        IF v_artifact->>'targetKind' = 'entry' THEN
            IF NOT private.jsonb_has_exact_keys(v_artifact, ARRAY[
                'targetKind','entryId','contentNodeId','translationId',
                'targetLanguageCode','sourceContentFingerprint',
                'translationPolicyVersion','providerRevision'
            ]) OR v_artifact->>'entryId' IS DISTINCT FROM p_entry_id::text
               OR v_artifact->'contentNodeId' <> 'null'::jsonb
            THEN RAISE EXCEPTION 'translation_atom_not_supported'; END IF;
            SELECT translation.overlay
              INTO v_translation
              FROM public.word_entry_translations translation
             WHERE translation.id = (v_artifact->>'translationId')::uuid
               AND translation.word_entry_id = p_entry_id
               AND translation.status = 'ready'
               AND translation.target_lang = v_artifact->>'targetLanguageCode'
               AND translation.source_content_revision = v_artifact->>'sourceContentFingerprint'
               AND translation.translation_policy_version = v_artifact->>'translationPolicyVersion'
               AND translation.provider_revision IS NOT DISTINCT FROM v_artifact->>'providerRevision';
            v_expected_text := NULLIF(trim(v_translation.overlay->>'headword'), '');
        ELSIF v_artifact->>'targetKind' = 'content-node' THEN
            IF NOT private.jsonb_has_exact_keys(v_artifact, ARRAY[
                'targetKind','entryId','contentNodeId','translationId',
                'targetLanguageCode','sourceTextFingerprint',
                'translationPolicyVersion','providerRevision'
            ]) OR v_artifact->>'entryId' IS DISTINCT FROM p_entry_id::text
            THEN RAISE EXCEPTION 'translation_atom_not_supported'; END IF;
            SELECT translation.overlay, node.diagnostic_locator, node.kind
              INTO v_translation
              FROM public.word_entry_translations translation
              JOIN private.platform_v2_content_nodes node
                ON node.entry_id = translation.word_entry_id
               AND node.id::text = v_artifact->>'contentNodeId'
               AND node.binding_state = 'active'
             WHERE translation.word_entry_id = p_entry_id
               AND translation.status = 'ready'
               AND translation.target_lang = v_artifact->>'targetLanguageCode'
               AND translation.translation_policy_version = v_artifact->>'translationPolicyVersion'
               AND translation.provider_revision IS NOT DISTINCT FROM v_artifact->>'providerRevision'
               AND node.source_text_fingerprint = v_artifact->>'sourceTextFingerprint'
               AND encode(digest(
                    translation.id::text || ':' || node.id::text,
                    'sha256'
               ), 'hex') = v_artifact->>'translationId';
            v_expected_text := private.diagnostic_translation_text_at_locator(
                v_translation.overlay,
                v_translation.diagnostic_locator,
                v_translation.kind
            );
        ELSE
            RAISE EXCEPTION 'translation_atom_not_supported';
        END IF;

        IF v_expected_text IS NULL THEN RAISE EXCEPTION 'stale_target'; END IF;
        v_expected_text := normalize(v_expected_text, NFC);
        v_bounded_text := substring(v_expected_text FROM 1 FOR 1500);
        IF v_atom->>'text' IS DISTINCT FROM v_bounded_text
           OR (v_atom->>'truncated')::boolean
                IS DISTINCT FROM (v_bounded_text IS DISTINCT FROM v_expected_text)
        THEN RAISE EXCEPTION 'translation_atom_not_supported'; END IF;
    END LOOP;
    RETURN true;
EXCEPTION WHEN invalid_text_representation THEN
    RAISE EXCEPTION 'translation_atom_not_supported';
END;
$$;


--
-- Name: verify_diagnostic_report_target(uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: private; Owner: -
--

CREATE FUNCTION private.verify_diagnostic_report_target(p_user_id uuid, p_target jsonb, p_card_content jsonb, p_observations jsonb) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_entry_id uuid;
    v_target_kind text := p_target->>'kind';
    v_expected_card_content jsonb;
    v_source_atoms jsonb;
    v_translation_atoms jsonb;
    v_report_content_revision text;
    v_action_projection jsonb;
    v_action_verified boolean;
    v_card_state jsonb;
    v_node jsonb;
BEGIN
    IF jsonb_typeof(p_target) IS DISTINCT FROM 'object'
       OR v_target_kind NOT IN ('entry', 'sense-card', 'content-node',
          'translation-artifact', 'training-action', 'app-operation') THEN
        RAISE EXCEPTION 'invalid_target';
    END IF;
    v_entry_id := private.diagnostic_report_target_entry_id(p_target);
    IF v_entry_id IS NOT NULL THEN
        PERFORM public.read_platform_v2_presentation_identity(
            p_user_id, ARRAY[v_entry_id], false
        );
    END IF;

    IF v_target_kind <> 'app-operation' THEN
        IF p_card_content IS NULL THEN
            RAISE EXCEPTION 'card_content_mismatch';
        END IF;
        v_report_content_revision := CASE
            WHEN v_target_kind IN ('entry', 'sense-card', 'training-action')
                THEN p_target->>'contentRevision'
            ELSE private.platform_v2_report_atom_revision(v_entry_id)
        END;
        v_expected_card_content := private.project_platform_v2_bounded_report_atoms(
            p_user_id,
            v_entry_id,
            v_report_content_revision
        );
        SELECT COALESCE(jsonb_agg(atom.value ORDER BY atom.ordinality), '[]'::jsonb)
          INTO v_source_atoms
          FROM jsonb_array_elements(p_card_content->'atoms') WITH ORDINALITY atom(value, ordinality)
         WHERE atom.value->>'role' <> 'displayed-translation';
        SELECT COALESCE(jsonb_agg(atom.value ORDER BY atom.ordinality), '[]'::jsonb)
          INTO v_translation_atoms
          FROM jsonb_array_elements(p_card_content->'atoms') WITH ORDINALITY atom(value, ordinality)
         WHERE atom.value->>'role' = 'displayed-translation';
        IF v_source_atoms IS DISTINCT FROM v_expected_card_content->'atoms'
           OR (p_card_content->>'omittedAtomCount')::integer
                < (v_expected_card_content->>'omittedAtomCount')::integer
           OR (
                jsonb_array_length(v_translation_atoms) = 0
                AND v_target_kind <> 'translation-artifact'
                AND (p_card_content->>'omittedAtomCount')::integer
                    IS DISTINCT FROM (v_expected_card_content->>'omittedAtomCount')::integer
           ) THEN
            RAISE EXCEPTION 'report_atoms_mismatch';
        END IF;
        IF jsonb_array_length(v_translation_atoms) > 0 AND EXISTS (
            SELECT 1
              FROM jsonb_array_elements(p_card_content->'atoms')
                   WITH ORDINALITY atom(value, ordinality)
             WHERE atom.value->>'role' <> 'displayed-translation'
               AND atom.ordinality > (
                   SELECT min(candidate.ordinality)
                     FROM jsonb_array_elements(p_card_content->'atoms')
                          WITH ORDINALITY candidate(value, ordinality)
                    WHERE candidate.value->>'role' = 'displayed-translation'
               )
        ) THEN
            RAISE EXCEPTION 'report_atoms_mismatch';
        END IF;
        PERFORM private.verify_diagnostic_displayed_translation_atoms(
            v_entry_id,
            v_translation_atoms
        );
    ELSIF p_card_content IS NOT NULL THEN
        RAISE EXCEPTION 'card_content_mismatch';
    END IF;

    IF v_target_kind = 'sense-card' THEN
        v_card_state := private.platform_v2_card_state_json(
            p_user_id,
            v_entry_id,
            p_target->>'cardTypeId'
        );
        IF v_card_state->>'stateRevision' IS DISTINCT FROM p_target->>'stateRevision' THEN
            RAISE EXCEPTION 'stale_target';
        END IF;
    END IF;

    IF v_target_kind = 'content-node' THEN
        SELECT jsonb_build_object(
            'kind', kind,
            'sourceTextFingerprint', source_text_fingerprint
        ) INTO v_node
        FROM private.platform_v2_content_nodes
        WHERE id::text = p_target->>'contentNodeId'
          AND entry_id = v_entry_id
          AND binding_state = 'active';
        IF v_node IS NULL
           OR v_node->>'kind' IS DISTINCT FROM p_target->>'nodeKind'
           OR v_node->>'sourceTextFingerprint' IS DISTINCT FROM p_target->>'sourceTextFingerprint' THEN
            RAISE EXCEPTION 'stale_target';
        END IF;
    END IF;

    IF v_target_kind = 'training-action' THEN
        v_action_projection := jsonb_build_object(
            'contractVersion', 'platform-action-report-verification-v1',
            'entryId', p_target->>'entryId',
            'cardTypeId', p_target->>'cardTypeId',
            'stateRevision', p_target->>'stateRevision',
            'actionId', p_target->>'actionId',
            'clientEventId', p_target->>'clientEventId',
            'reviewResult', p_target->'reviewResult',
            'activeKnownMarkId', p_target->'activeKnownMarkId',
            'knownMarkRevision', p_target->'knownMarkRevision'
        );
        v_action_verified := public.verify_platform_v2_action_receipt_as_principal(
            p_user_id,
            v_action_projection
        );
        IF v_action_verified THEN
            RETURN 'committed';
        END IF;
        IF EXISTS (
            SELECT 1 FROM public.platform_v2_action_receipts receipt
            WHERE receipt.user_id = p_user_id
              AND receipt.client_event_id = (p_target->>'clientEventId')::uuid
        ) OR p_observations#>>'{actionObservation,clientObservedOutcome}'
            IN ('accepted', 'duplicate') THEN
            RAISE EXCEPTION 'action_target_mismatch';
        END IF;
        RETURN 'not-found';
    END IF;

    IF v_target_kind = 'translation-artifact' THEN
        IF jsonb_array_length(v_translation_atoms) > 0
           AND NOT EXISTS (
               SELECT 1 FROM jsonb_array_elements(v_translation_atoms) atom
               WHERE atom->'artifact' = p_target - 'kind'
           ) THEN
            RAISE EXCEPTION 'translation_atom_not_supported';
        END IF;
        IF p_target->>'targetKind' = 'entry' AND NOT EXISTS (
            SELECT 1 FROM public.word_entry_translations translation
            WHERE translation.id = (p_target->>'translationId')::uuid
              AND translation.word_entry_id = v_entry_id
              AND translation.status = 'ready'
              AND translation.target_lang = p_target->>'targetLanguageCode'
              AND translation.source_content_revision = p_target->>'sourceContentFingerprint'
              AND translation.translation_policy_version = p_target->>'translationPolicyVersion'
              AND translation.provider_revision IS NOT DISTINCT FROM p_target->>'providerRevision'
        ) THEN RAISE EXCEPTION 'stale_target'; END IF;
        IF p_target->>'targetKind' = 'content-node' AND NOT EXISTS (
            SELECT 1
              FROM public.word_entry_translations translation
              JOIN private.platform_v2_content_nodes node
                ON node.entry_id = translation.word_entry_id
               AND node.id::text = p_target->>'contentNodeId'
               AND node.binding_state = 'active'
             WHERE translation.word_entry_id = v_entry_id
               AND translation.status = 'ready'
               AND translation.target_lang = p_target->>'targetLanguageCode'
               AND translation.translation_policy_version = p_target->>'translationPolicyVersion'
               AND translation.provider_revision IS NOT DISTINCT FROM p_target->>'providerRevision'
               AND node.source_text_fingerprint = p_target->>'sourceTextFingerprint'
               AND encode(digest(
                    translation.id::text || ':' || node.id::text,
                    'sha256'
               ), 'hex') = p_target->>'translationId'
        ) THEN RAISE EXCEPTION 'stale_target'; END IF;
    END IF;
    RETURN NULL;
END;
$$;


--
-- Name: acknowledge_current_training_card_v1(uuid, uuid, uuid, text, bigint, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.acknowledge_current_training_card_v1(p_user_id uuid, p_session_id uuid, p_entry_id uuid, p_card_type_id text, p_content_version bigint, p_state_revision text, p_target_id uuid DEFAULT NULL::uuid, p_direction text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  issuance_author uuid; issuance_roots uuid[]; generation bigint;
  source public.word_entries%rowtype;
  session public.training_sessions%rowtype;
  target private.platform_v2_training_exercise_targets%rowtype;
  existing private.training_current_card_permits%rowtype;
  expected_id uuid;
  state_revision text;
  reference_now timestamptz:=private.training_reference_now_v1();
BEGIN
  generation:=private.require_active_training_session_v1(p_user_id,p_session_id);
  SELECT * INTO session FROM public.training_sessions WHERE id=p_session_id AND user_id=p_user_id;
  IF NOT FOUND OR session.completed_at IS NOT NULL OR session.superseded_at IS NOT NULL OR session.expires_at<=reference_now THEN
    RAISE EXCEPTION 'training_session_not_active' USING ERRCODE='42501';
  END IF;
  IF p_card_type_id IS NULL OR NOT p_card_type_id=ANY(session.card_type_ids)
    OR p_content_version IS NULL OR p_content_version<1 OR p_state_revision IS NULL THEN
    RAISE EXCEPTION 'current_training_target_invalid' USING ERRCODE='22023';
  END IF;
  -- Same lock order as actions: user/run authority, then exact entry/archive.
  SELECT * INTO source FROM public.word_entries WHERE id=p_entry_id FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'current_training_entry_unavailable' USING ERRCODE='42501';
  END IF;
  IF source.content_version<>p_content_version THEN RAISE EXCEPTION 'current_training_content_changed' USING ERRCODE='40001'; END IF;
  SELECT * INTO existing FROM private.training_current_card_permits WHERE user_id=p_user_id;
  IF FOUND AND existing.session_id=p_session_id AND existing.entry_id=p_entry_id AND existing.card_type_id=p_card_type_id
    AND existing.target_id IS NOT DISTINCT FROM p_target_id AND existing.direction IS NOT DISTINCT FROM p_direction
    AND existing.content_version=p_content_version AND existing.state_revision=p_state_revision
    AND private.current_training_permit_valid_v1(existing) THEN
    RETURN jsonb_build_object('permitId',existing.permit_id,'expiresAt',existing.expires_at,'runGeneration',existing.run_generation,
      'entryId',existing.entry_id,'cardTypeId',existing.card_type_id,'targetId',existing.target_id,'contentVersion',existing.content_version);
  END IF;
  SELECT dictionary.owner_user_id INTO issuance_author FROM public.dictionaries dictionary
    WHERE dictionary.id=source.dictionary_id AND dictionary.kind='user'
      AND dictionary.owner_user_id IS DISTINCT FROM p_user_id AND source.management_kind='user';
  IF issuance_author IS NOT NULL THEN
    PERFORM private.lock_sharing_author_scope_v1(issuance_author,false);
    -- Revoke and membership changes lock roots too. Recheck entry authority in
    -- a subsequent statement after waiting, not in the lock statement snapshot.
    SELECT COALESCE(array_agg(locked.id),ARRAY[]::uuid[]) INTO issuance_roots FROM (
    SELECT root.id FROM private.collection_sharing_roots root
    JOIN private.collection_sharing_subscriptions subscription ON subscription.root_id=root.id
    JOIN public.user_word_list_items item ON item.list_id=root.collection_id
    WHERE subscription.user_id=p_user_id AND subscription.is_active
      AND subscription.access_lifetime=root.access_lifetime AND root.is_open
      AND root.owner_user_id=issuance_author AND item.word_id=p_entry_id
    ORDER BY root.id FOR SHARE OF root) locked;
  END IF;
  IF (issuance_author IS NOT NULL AND NOT EXISTS(
      SELECT 1 FROM private.shared_author_entry_memberships_v1 shared
      WHERE shared.user_id=p_user_id AND shared.entry_id=p_entry_id AND shared.root_id=ANY(issuance_roots)))
    OR NOT private.entry_access_v1(p_user_id,p_entry_id,'train') THEN
    RAISE EXCEPTION 'current_training_entry_unavailable' USING ERRCODE='42501';
  END IF;
  IF source.archived_at IS NOT NULL THEN RAISE EXCEPTION 'current_training_entry_unavailable' USING ERRCODE='42501'; END IF;
  IF p_target_id IS NULL THEN
    IF p_direction IS NOT NULL THEN RAISE EXCEPTION 'current_training_target_invalid' USING ERRCODE='22023'; END IF;
    SELECT member.entry_id INTO expected_id FROM public.training_session_members member
      WHERE member.session_id=p_session_id AND member.card_type_id=p_card_type_id
        AND member.consumed_at IS NULL AND member.unavailable_at IS NULL
      ORDER BY member.ordinal LIMIT 1;
    IF expected_id IS DISTINCT FROM p_entry_id THEN RAISE EXCEPTION 'current_training_target_not_next' USING ERRCODE='42501'; END IF;
    SELECT COALESCE((SELECT state.state_revision::text FROM public.user_card_status state
      WHERE state.user_id=p_user_id AND state.entry_id=p_entry_id AND state.card_type_id=p_card_type_id),'untracked') INTO state_revision;
  ELSE
    SELECT * INTO target FROM private.platform_v2_training_exercise_targets WHERE id=p_target_id;
    IF NOT FOUND OR target.entry_id<>p_entry_id OR target.family NOT IN('idiom','translation')
      OR target.direction IS DISTINCT FROM p_direction OR target.visibility_state<>'active'
      OR p_card_type_id<>target.family||':'||target.direction THEN
      RAISE EXCEPTION 'current_training_target_invalid' USING ERRCODE='42501';
    END IF;
    IF target.content_node_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM private.platform_v2_content_nodes node
      WHERE node.id=target.content_node_id AND node.entry_id=p_entry_id AND node.binding_state='active'
        AND node.source_text_fingerprint=target.source_text_fingerprint) THEN
      RAISE EXCEPTION 'current_training_content_changed' USING ERRCODE='40001';
    END IF;
    SELECT member.target_id INTO expected_id FROM public.training_session_exercise_members member
      WHERE member.session_id=p_session_id AND member.consumed_at IS NULL AND member.unavailable_at IS NULL
      ORDER BY member.ordinal LIMIT 1;
    IF expected_id IS DISTINCT FROM p_target_id THEN RAISE EXCEPTION 'current_training_target_not_next' USING ERRCODE='42501'; END IF;
    SELECT COALESCE((SELECT state.state_revision::text FROM public.user_training_exercise_state state
      WHERE state.user_id=p_user_id AND state.target_id=p_target_id),'untracked') INTO state_revision;
  END IF;
  IF state_revision IS DISTINCT FROM p_state_revision THEN RAISE EXCEPTION 'current_training_state_changed' USING ERRCODE='40001'; END IF;
  INSERT INTO private.training_current_card_permits(user_id,session_id,run_generation,entry_id,card_type_id,content_version,
    state_revision,target_id,direction,source_revision,source_text_fingerprint,shared_author_dictionary_id,shared_author_user_id,issued_at,expires_at)
  VALUES(p_user_id,p_session_id,generation,p_entry_id,p_card_type_id,p_content_version,p_state_revision,p_target_id,p_direction,
    target.source_revision,target.source_text_fingerprint,CASE WHEN issuance_author IS NOT NULL THEN source.dictionary_id END,issuance_author,reference_now,LEAST(session.expires_at,reference_now+interval '30 minutes'))
  ON CONFLICT(user_id) DO UPDATE SET permit_id=gen_random_uuid(),session_id=EXCLUDED.session_id,run_generation=EXCLUDED.run_generation,
    entry_id=EXCLUDED.entry_id,card_type_id=EXCLUDED.card_type_id,content_version=EXCLUDED.content_version,
    state_revision=EXCLUDED.state_revision,target_id=EXCLUDED.target_id,direction=EXCLUDED.direction,
    source_revision=EXCLUDED.source_revision,source_text_fingerprint=EXCLUDED.source_text_fingerprint,
    shared_author_dictionary_id=EXCLUDED.shared_author_dictionary_id,shared_author_user_id=EXCLUDED.shared_author_user_id,issued_at=EXCLUDED.issued_at,expires_at=EXCLUDED.expires_at RETURNING * INTO existing;
  RETURN jsonb_build_object('permitId',existing.permit_id,'expiresAt',existing.expires_at,'runGeneration',existing.run_generation,
    'entryId',existing.entry_id,'cardTypeId',existing.card_type_id,'targetId',existing.target_id,'contentVersion',existing.content_version);
END;
$$;


--
-- Name: add_entry_to_user_list(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_entry_to_user_list(p_user_id uuid, p_list_id uuid, p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM user_word_lists
        WHERE id = p_list_id
          AND user_id = p_user_id
    ) THEN
        RAISE EXCEPTION 'list_not_found';
    END IF;

    SELECT dictionary_id INTO v_dictionary_id
    FROM private.active_word_entries
    WHERE id = p_entry_id FOR SHARE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'entry_not_found';
    END IF;

    IF v_dictionary_id IS NOT NULL
       AND NOT can_access_dictionary(p_user_id, v_dictionary_id, 'read') THEN
        RAISE EXCEPTION 'entry_not_accessible';
    END IF;

    INSERT INTO user_word_list_items (list_id, word_id)
    VALUES (p_list_id, p_entry_id)
    ON CONFLICT (list_id, word_id) DO NOTHING;
END;
$$;


--
-- Name: admin_admission_mutate(uuid, text, text[], text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_admission_mutate(p_operator uuid, p_action text, p_emails text[], p_mode text, p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE c private.admission_control; e text; old_status text; new_status text; result jsonb='[]';
BEGIN
 PERFORM private.admission_operator(p_operator);
 IF p_request_id IS NULL OR p_action IS NULL OR p_action NOT IN ('approve','reject','revoke','invite','mode') THEN RAISE EXCEPTION 'invalid_admission_action'; END IF;
 SELECT * INTO STRICT c FROM private.admission_control WHERE singleton FOR UPDATE;
 IF p_action='mode' THEN
  IF p_mode IS NULL OR p_mode NOT IN ('invite-only','approval-required','open') THEN RAISE EXCEPTION 'invalid_admission_mode'; END IF;
  IF c.mode<>p_mode THEN
   UPDATE private.admission_control SET mode=p_mode,updated_at=now() WHERE singleton;
   INSERT INTO public.admin_audit_events(operator_user_id,action,outcome,target_type,target_id,request_id)
   VALUES(p_operator,'admission.mode','success','admission_mode',p_mode,p_request_id);
  END IF;
  RETURN jsonb_build_object('mode',p_mode);
 END IF;
 IF cardinality(p_emails) IS NULL OR cardinality(p_emails)<1 OR cardinality(p_emails)>100 THEN RAISE EXCEPTION 'invalid_admission_batch'; END IF;
 -- Validate the complete batch before changing any row, deterministic order for concurrent operators.
 IF EXISTS(SELECT 1 FROM unnest(p_emails) x WHERE x IS NULL OR length(btrim(x))>320 OR btrim(x)!~'^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') THEN RAISE EXCEPTION 'invalid_admission_email'; END IF;
 FOR e IN SELECT DISTINCT lower(btrim(x)) FROM unnest(p_emails) x ORDER BY 1 LOOP
  SELECT status INTO old_status FROM private.admission_requests WHERE email=e FOR UPDATE;
  IF old_status IS NULL AND p_action<>'invite' THEN
   result=result||jsonb_build_array(jsonb_build_object('email',e,'outcome','not_found'));CONTINUE;
  END IF;
  IF p_action='reject' AND old_status IN ('approved','revoked') THEN
   result=result||jsonb_build_array(jsonb_build_object('email',e,'outcome','unchanged'));CONTINUE;
  END IF;
  new_status=CASE p_action WHEN 'approve' THEN 'approved' WHEN 'invite' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'revoked' END;
  IF new_status IS NOT DISTINCT FROM old_status THEN
   result=result||jsonb_build_array(jsonb_build_object('email',e,'outcome','unchanged'));CONTINUE;
  END IF;
  INSERT INTO private.admission_requests(email,status,decided_by) VALUES(e,new_status,p_operator)
  ON CONFLICT(email) DO UPDATE SET status=EXCLUDED.status,decided_by=p_operator,updated_at=now();
  INSERT INTO public.admin_audit_events(operator_user_id,action,outcome,target_type,target_id,request_id)
  VALUES(p_operator,'admission.'||p_action,'success','admission_email',CASE WHEN length(e)<=160 THEN e ELSE encode(sha256(convert_to(e,'UTF8')),'hex') END,p_request_id);
  result=result||jsonb_build_array(jsonb_build_object('email',e,'outcome','changed','status',new_status));
 END LOOP;
 RETURN jsonb_build_object('results',result);
END;
$_$;


--
-- Name: admin_admission_page(uuid, text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_admission_page(p_operator uuid, p_status text DEFAULT NULL::text, p_query text DEFAULT NULL::text, p_page integer DEFAULT 1) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE items jsonb; c private.admission_control;
BEGIN
 PERFORM private.admission_operator(p_operator);
 IF p_page IS NULL OR p_page<1 OR p_page>10000 OR (p_status IS NOT NULL AND p_status NOT IN ('pending','approved','rejected','revoked')) THEN RAISE EXCEPTION 'invalid_admission_query'; END IF;
 SELECT * INTO c FROM private.admission_control WHERE singleton;
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]'::jsonb) INTO items FROM(
  SELECT email,user_id,status,created_at,updated_at FROM private.admission_requests
  WHERE (p_status IS NULL OR status=p_status) AND (nullif(btrim(p_query),'') IS NULL OR position(lower(btrim(p_query)) IN email)>0)
  ORDER BY created_at DESC,email LIMIT 51 OFFSET (p_page-1)*50
 ) x;
 RETURN jsonb_build_object('items',items,'enabled',c.enabled,'mode',c.mode,'page',p_page);
END;
$$;


--
-- Name: admin_replace_dictionary_access_group(text, text, uuid[], uuid, uuid, inet, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_replace_dictionary_access_group(p_key text, p_name text, p_member_ids uuid[], p_operator_user_id uuid, p_request_id uuid, p_client_ip inet, p_user_agent text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.admin_operators
        WHERE user_id = p_operator_user_id
          AND is_active
          AND permissions @> ARRAY['publication.manage']::text[]
    ) THEN
        RAISE EXCEPTION 'admin_operator_not_authorized';
    END IF;

    v_result := public.replace_dictionary_access_group(p_key, p_name, p_member_ids);
    INSERT INTO public.admin_audit_events (
        operator_user_id, action, outcome, target_type, target_id, request_id, client_ip, user_agent
    ) VALUES (
        p_operator_user_id, 'dictionary.audience.updated', 'success', 'dictionary_access_group',
        v_result->>'key', p_request_id, p_client_ip, left(p_user_agent, 1024)
    );
    RETURN v_result;
END;
$$;


--
-- Name: admin_replace_dictionary_audience(uuid, text[], uuid[], uuid, uuid, inet, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_replace_dictionary_audience(p_dictionary_id uuid, p_group_keys text[], p_user_ids uuid[], p_operator_user_id uuid, p_request_id uuid, p_client_ip inet, p_user_agent text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.admin_operators
        WHERE user_id = p_operator_user_id
          AND is_active
          AND permissions @> ARRAY['publication.manage']::text[]
    ) THEN
        RAISE EXCEPTION 'admin_operator_not_authorized';
    END IF;

    v_result := public.replace_dictionary_audience(p_dictionary_id, p_group_keys, p_user_ids);
    INSERT INTO public.admin_audit_events (
        operator_user_id, action, outcome, target_type, target_id, request_id, client_ip, user_agent
    ) VALUES (
        p_operator_user_id, 'dictionary.audience.updated', 'success', 'dictionary',
        p_dictionary_id::text, p_request_id, p_client_ip, left(p_user_agent, 1024)
    );
    RETURN v_result;
END;
$$;


--
-- Name: admin_set_dictionary_publication(uuid, text, text[], uuid[], uuid, uuid, inet, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_set_dictionary_publication(p_dictionary_id uuid, p_publication_state text, p_group_keys text[], p_user_ids uuid[], p_operator_user_id uuid, p_request_id uuid, p_client_ip inet, p_user_agent text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    IF NOT EXISTS (
        SELECT 1 FROM public.admin_operators
        WHERE user_id = p_operator_user_id
          AND is_active
          AND permissions @> ARRAY['publication.manage']::text[]
    ) THEN
        RAISE EXCEPTION 'admin_operator_not_authorized';
    END IF;

    v_result := public.set_dictionary_publication(
        p_dictionary_id, p_publication_state, p_group_keys, p_user_ids
    );
    IF v_result IS NULL THEN RETURN NULL; END IF;

    INSERT INTO public.admin_audit_events (
        operator_user_id, action, outcome, target_type, target_id, request_id, client_ip, user_agent
    ) VALUES (
        p_operator_user_id, 'dictionary.publication.updated', 'success', 'dictionary',
        p_dictionary_id::text, p_request_id, p_client_ip, left(p_user_agent, 1024)
    );
    IF p_group_keys IS NOT NULL THEN
        INSERT INTO public.admin_audit_events (
            operator_user_id, action, outcome, target_type, target_id, request_id, client_ip, user_agent
        ) VALUES (
            p_operator_user_id, 'dictionary.audience.updated', 'success', 'dictionary',
            p_dictionary_id::text, p_request_id, p_client_ip, left(p_user_agent, 1024)
        );
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: admin_user_registry_page(text, uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admin_user_registry_page(p_query text DEFAULT NULL::text, p_user_id uuid DEFAULT NULL::uuid, p_page integer DEFAULT 1, p_page_size integer DEFAULT 25) RETURNS TABLE(user_id uuid, email text, created_at timestamp with time zone, last_sign_in_at timestamp with time zone, personal_list_count integer, personal_entry_link_count integer)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE
  v_query text := nullif(btrim(p_query), '');
BEGIN
  IF p_page IS NULL OR p_page < 1 OR p_page > 10000
     OR p_page_size IS NULL OR p_page_size < 1 OR p_page_size > 100 THEN
    RAISE EXCEPTION 'invalid_admin_user_page';
  END IF;

  RETURN QUERY
  WITH selected_users AS MATERIALIZED (
    SELECT
      account.id,
      account.email::text,
      account.created_at,
      account.last_sign_in_at
    FROM auth.users AS account
    WHERE (p_user_id IS NULL OR account.id = p_user_id)
      AND (EXISTS (
        SELECT 1 FROM public.user_settings AS learner_profile
        WHERE learner_profile.user_id = account.id
      ) OR NOT EXISTS (
        SELECT 1
        FROM public.admin_operators AS operator_account
        WHERE operator_account.user_id = account.id
           OR operator_account.email = lower(btrim(coalesce(account.email, '')))
      ))
      AND (
        v_query IS NULL
        OR strpos(lower(coalesce(account.email, '')), lower(v_query)) > 0
        OR strpos(account.id::text, lower(v_query)) > 0
      )
    ORDER BY account.created_at DESC, account.id ASC
    LIMIT (p_page_size + 1)
    OFFSET (p_page - 1) * p_page_size
  )
  SELECT
    selected.id,
    selected.email,
    selected.created_at,
    selected.last_sign_in_at,
    count(DISTINCT personal_list.id)::integer,
    count(personal_item.word_id)::integer
  FROM selected_users AS selected
  LEFT JOIN public.user_word_lists AS personal_list
    ON personal_list.user_id = selected.id
  LEFT JOIN public.user_word_list_items AS personal_item
    ON personal_item.list_id = personal_list.id
  GROUP BY selected.id, selected.email, selected.created_at, selected.last_sign_in_at
  ORDER BY selected.created_at DESC, selected.id ASC;
END;
$$;


--
-- Name: admission_check_user(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admission_check_user(p_user_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('enabled',c.enabled,'allowed',private.admission_allowed(p_user_id))
 FROM private.admission_control c WHERE c.singleton;
$$;


--
-- Name: admission_enforce(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admission_enforce() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF current_setting('role',true) IN ('anon','authenticated')
    AND NOT(current_setting('role',true)='authenticated' AND coalesce(current_setting('request.path',true),'')='/rpc/admission_request')
    AND NOT coalesce(private.admission_allowed((SELECT auth.uid())),false) THEN
  RAISE EXCEPTION 'admission_required' USING ERRCODE='42501';
 END IF;
END;
$$;


--
-- Name: admission_request(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.admission_request() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c private.admission_control; u auth.users; r private.admission_requests; previous_status text;
BEGIN
 -- Lock control first consistently with operator mutation; mode/grant transition is serialized.
 SELECT * INTO STRICT c FROM private.admission_control WHERE singleton FOR SHARE;
 IF NOT c.enabled THEN RETURN jsonb_build_object('enabled',false,'status','approved','mode',c.mode); END IF;
 SELECT * INTO u FROM auth.users WHERE id=(SELECT auth.uid());
 IF u.id IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE='42501'; END IF;
 IF u.email IS NULL OR u.email_confirmed_at IS NULL THEN
  RETURN jsonb_build_object('enabled',true,'status','unconfirmed','mode',c.mode);
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('admission:'||lower(btrim(u.email)),0));
 SELECT status INTO previous_status FROM private.admission_requests WHERE email=lower(btrim(u.email));
 INSERT INTO private.admission_requests(email,user_id,status)
 VALUES(lower(btrim(u.email)),u.id,CASE WHEN c.mode='open' THEN 'approved' ELSE 'pending' END)
 ON CONFLICT(email) DO UPDATE SET user_id=EXCLUDED.user_id,
 status=CASE WHEN private.admission_requests.status='pending' AND c.mode='open' THEN 'approved' ELSE private.admission_requests.status END;
 SELECT * INTO STRICT r FROM private.admission_requests WHERE email=lower(btrim(u.email));
 IF r.status='approved' AND r.status IS DISTINCT FROM previous_status THEN
  INSERT INTO public.admin_audit_events(operator_user_id,action,outcome,target_type,target_id,request_id)
  VALUES(NULL,'admission.auto_approve','success','admission_email',CASE WHEN length(r.email)<=160 THEN r.email ELSE encode(sha256(convert_to(r.email,'UTF8')),'hex') END,gen_random_uuid());
 END IF;
 RETURN jsonb_build_object('enabled',true,'status',r.status,'mode',c.mode);
END;
$$;


--
-- Name: assert_editable_user_dictionary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assert_editable_user_dictionary(p_user_id uuid, p_dictionary_id uuid) RETURNS public.dictionaries
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_dictionary dictionaries%rowtype;
BEGIN
    SELECT * INTO v_dictionary
    FROM dictionaries
    WHERE id = p_dictionary_id;

    IF NOT FOUND
       OR v_dictionary.kind <> 'user'
       OR v_dictionary.owner_user_id IS DISTINCT FROM p_user_id
       OR NOT v_dictionary.is_editable
       OR v_dictionary.schema_key <> 'user-entry-v1'
       OR v_dictionary.schema_version <> 1 THEN
        RAISE EXCEPTION 'target_dictionary_not_editable'
            USING ERRCODE = '42501';
    END IF;

    RETURN v_dictionary;
END;
$$;


--
-- Name: assign_word_entry_default_dictionary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_word_entry_default_dictionary() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF NEW.dictionary_id IS NULL AND NEW.language_code = (public.dictionary_source_settings_v1()->>'languageCode') THEN
        SELECT id INTO NEW.dictionary_id
        FROM dictionaries
        WHERE language_code = NEW.language_code AND slug = (public.dictionary_source_settings_v1()->>'catalogKey');
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: can_access_dictionary(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_access_dictionary(p_user_id uuid, p_dictionary_id uuid, p_permission text DEFAULT 'read'::text) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dictionary public.dictionaries%rowtype;
  v_user_tier text;
  v_user_rank int;
  v_required_rank int;
BEGIN
  SELECT * INTO v_dictionary FROM public.dictionaries WHERE id = p_dictionary_id;
  IF NOT FOUND OR p_permission NOT IN ('read', 'write', 'admin') THEN RETURN false; END IF;
  IF p_user_id IS NOT NULL AND v_dictionary.owner_user_id = p_user_id THEN RETURN true; END IF;

  -- Publication state is an outer visibility gate. Entitlements and tiers
  -- refine access only while the dictionary is published.
  IF v_dictionary.publication_state = 'unpublished' THEN RETURN false; END IF;

  SELECT COALESCE(subscription_tier, 'free') INTO v_user_tier
    FROM public.user_settings WHERE user_id = p_user_id;
  v_user_tier := COALESCE(v_user_tier, 'free');
  v_user_rank := CASE v_user_tier WHEN 'admin' THEN 30 WHEN 'premium' THEN 20 ELSE 10 END;
  v_required_rank := CASE COALESCE(v_dictionary.minimum_subscription_tier, 'free')
    WHEN 'admin' THEN 30 WHEN 'premium' THEN 20 ELSE 10 END;

  IF p_permission = 'read' AND v_dictionary.publication_state = 'general'
     AND v_user_rank >= v_required_rank THEN RETURN true; END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.dictionary_entitlements e
    WHERE e.dictionary_id = p_dictionary_id
      AND ((e.subject_type = 'user' AND e.subject_key = p_user_id::text)
        OR (e.subject_type = 'tier' AND e.subject_key = v_user_tier)
        OR (e.subject_type = 'group' AND EXISTS (
          SELECT 1 FROM public.dictionary_access_group_members gm
          JOIN public.dictionary_access_groups g ON g.id = gm.group_id
          WHERE gm.user_id = p_user_id AND g.key = e.subject_key
        )))
      AND (e.permission = p_permission OR e.permission = 'admin'
        OR (p_permission = 'read' AND e.permission = 'write'))
      AND (v_dictionary.publication_state <> 'restricted' OR e.subject_type <> 'tier')
      AND (e.starts_at IS NULL OR e.starts_at <= now())
      AND (e.ends_at IS NULL OR e.ends_at > now())
  );
END;
$$;


--
-- Name: can_browse_dictionary(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_browse_dictionary(p_user_id uuid, p_dictionary_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
  v_dictionary public.dictionaries%rowtype;
BEGIN
  SELECT * INTO v_dictionary FROM public.dictionaries WHERE id = p_dictionary_id;
  IF NOT FOUND THEN RETURN false; END IF;
  IF p_user_id IS NOT NULL AND v_dictionary.owner_user_id = p_user_id THEN RETURN true; END IF;
  IF v_dictionary.kind = 'user' THEN RETURN false; END IF;
  IF v_dictionary.publication_state = 'general' THEN RETURN true; END IF;
  IF v_dictionary.publication_state <> 'restricted' OR p_user_id IS NULL THEN RETURN false; END IF;

  RETURN EXISTS (
    SELECT 1 FROM public.dictionary_entitlements e
    WHERE e.dictionary_id = p_dictionary_id
      AND e.subject_type IN ('user', 'group')
      AND ((e.subject_type = 'user' AND e.subject_key = p_user_id::text)
        OR (e.subject_type = 'group' AND EXISTS (
          SELECT 1 FROM public.dictionary_access_group_members gm
          JOIN public.dictionary_access_groups g ON g.id = gm.group_id
          WHERE gm.user_id = p_user_id AND g.key = e.subject_key
        )))
      AND e.permission IN ('read', 'write', 'admin')
      AND (e.starts_at IS NULL OR e.starts_at <= now())
      AND (e.ends_at IS NULL OR e.ends_at > now())
  );
END;
$$;


--
-- Name: can_browse_dictionary(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.can_browse_dictionary(p_user_id uuid, p_dictionary_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT p_permission = 'read'
       AND public.can_browse_dictionary(p_user_id, p_dictionary_id)
$$;


--
-- Name: checkpoint_dictionary_translation_part_v1(uuid, uuid, text, text, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.checkpoint_dictionary_translation_part_v1(p_job_id uuid, p_lease_token uuid, p_part_key text, p_part_fingerprint text, p_result jsonb, p_continue boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_job public.dictionary_translation_jobs; v_entry_id uuid; v_now timestamptz;
BEGIN
 SELECT word_entry_id INTO v_entry_id FROM public.dictionary_translation_jobs WHERE id=p_job_id;
 IF NOT FOUND THEN RETURN false; END IF;
 -- Preserve source -> job lock order used by enqueue and final publication.
 PERFORM id FROM public.word_entries WHERE archived_at IS NULL AND id=v_entry_id FOR SHARE;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT * INTO v_job FROM public.dictionary_translation_jobs WHERE id=p_job_id FOR UPDATE;
 v_now:=clock_timestamp();
 IF v_job.status<>'running' OR v_job.lease_token IS DISTINCT FROM p_lease_token OR v_job.lease_expires_at<=v_now
 OR v_job.source_row_revision IS DISTINCT FROM (public.dictionary_translation_source_v1(v_entry_id)->>'revision')
 THEN RETURN false; END IF;
 INSERT INTO public.dictionary_translation_job_parts(job_id,part_key,part_fingerprint,result)
 VALUES(p_job_id,p_part_key,p_part_fingerprint,p_result)
 ON CONFLICT(job_id,part_key) DO UPDATE SET part_fingerprint=EXCLUDED.part_fingerprint,result=EXCLUDED.result;
 IF p_continue THEN
   -- Successful continuation consumes no failure retry. Yield between parts so
   -- foreground cards can use the existing global concurrency/priority ceiling.
   UPDATE public.dictionary_translation_jobs SET status='queued',attempt=greatest(0,attempt-1),
     lease_token=NULL,lease_expires_at=NULL,available_at=v_now,updated_at=v_now
   WHERE id=p_job_id;
 END IF;
 RETURN true;
END;
$$;


--
-- Name: dictionary_translation_jobs; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.dictionary_translation_jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    word_entry_id uuid NOT NULL,
    target_lang text NOT NULL,
    provider text NOT NULL,
    source_fingerprint text NOT NULL,
    source_row_revision text NOT NULL,
    source_content_revision text NOT NULL,
    translation_policy_version text NOT NULL,
    provider_revision text NOT NULL,
    status text DEFAULT 'queued'::text NOT NULL,
    priority smallint DEFAULT 0 NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    available_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    started_at timestamp with time zone,
    finished_at timestamp with time zone,
    updated_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    error_code text,
    CONSTRAINT dictionary_translation_job_lease CHECK ((((status = 'running'::text) AND (lease_token IS NOT NULL) AND (lease_expires_at IS NOT NULL)) OR ((status <> 'running'::text) AND (lease_token IS NULL) AND (lease_expires_at IS NULL)))),
    CONSTRAINT dictionary_translation_jobs_attempt_check CHECK (((attempt >= 0) AND (attempt <= 3))),
    CONSTRAINT dictionary_translation_jobs_error_code_check CHECK ((error_code = ANY (ARRAY['provider_http_error'::text, 'provider_response_error'::text, 'provider_empty_response'::text, 'provider_timeout'::text, 'provider_network_error'::text, 'provider_fallback_error'::text, 'provider_unknown_error'::text, 'source_changed'::text]))),
    CONSTRAINT dictionary_translation_jobs_priority_check CHECK (((priority >= 0) AND (priority <= 10))),
    CONSTRAINT dictionary_translation_jobs_provider_check CHECK ((provider = ANY (ARRAY['openai'::text, 'deepl'::text, 'gemini'::text]))),
    CONSTRAINT dictionary_translation_jobs_provider_revision_check CHECK (((length(provider_revision) >= 1) AND (length(provider_revision) <= 128))),
    CONSTRAINT dictionary_translation_jobs_source_content_revision_check CHECK (((length(source_content_revision) >= 1) AND (length(source_content_revision) <= 128))),
    CONSTRAINT dictionary_translation_jobs_source_fingerprint_check CHECK (((length(source_fingerprint) >= 1) AND (length(source_fingerprint) <= 128))),
    CONSTRAINT dictionary_translation_jobs_source_row_revision_check CHECK ((length(source_row_revision) = 64)),
    CONSTRAINT dictionary_translation_jobs_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'ready'::text, 'failed'::text, 'superseded'::text]))),
    CONSTRAINT dictionary_translation_jobs_target_lang_check CHECK ((target_lang ~ '^[a-z]{2,3}(-[a-z0-9]{2,8}){0,3}$'::text)),
    CONSTRAINT dictionary_translation_jobs_translation_policy_version_check CHECK (((length(translation_policy_version) >= 1) AND (length(translation_policy_version) <= 256)))
);


--
-- Name: claim_dictionary_translation_job_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.claim_dictionary_translation_job_v1() RETURNS SETOF public.dictionary_translation_jobs
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_now timestamptz := clock_timestamp();
BEGIN
  -- Fixed global provider concurrency, even if a deploy briefly overlaps workers.
  PERFORM pg_advisory_xact_lock(674, 1);
  v_now := clock_timestamp();
  UPDATE public.dictionary_translation_jobs SET
    status = CASE WHEN attempt >= 3 THEN 'failed' ELSE 'queued' END,
    available_at = v_now + interval '5 seconds', lease_token = NULL, lease_expires_at = NULL,
    error_code = 'provider_timeout', updated_at = v_now,
    finished_at = CASE WHEN attempt >= 3 THEN v_now ELSE NULL END
  WHERE status = 'running' AND lease_expires_at <= v_now;
  IF (SELECT count(*) FROM public.dictionary_translation_jobs WHERE status = 'running') >= 2 THEN RETURN; END IF;
  RETURN QUERY UPDATE public.dictionary_translation_jobs SET status = 'running',
    attempt = attempt + 1, lease_token = gen_random_uuid(),
    lease_expires_at = v_now + interval '60 seconds', started_at = v_now, updated_at = v_now
  WHERE id = (SELECT id FROM public.dictionary_translation_jobs
    WHERE status = 'queued' AND available_at <= v_now AND attempt < 3
      -- Speculation must leave capacity for a later visible-card request.
      AND (priority > 0 OR NOT EXISTS (
        SELECT 1 FROM public.dictionary_translation_jobs active
        WHERE active.status = 'running' AND active.priority = 0))
    ORDER BY priority DESC, available_at, created_at, id LIMIT 1 FOR UPDATE SKIP LOCKED)
  RETURNING *;
END $$;


--
-- Name: command_collection_share_v1(uuid, text, uuid, integer, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.command_collection_share_v1(p_operation_id uuid, p_action text, p_collection_id uuid DEFAULT NULL::uuid, p_expected_revision integer DEFAULT NULL::integer, p_code text DEFAULT NULL::text, p_reconcile_only boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE principal uuid:=(select auth.uid()); request jsonb; replay jsonb; terminal private.collection_share_terminal_rejections%rowtype; message text;
BEGIN
 IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF p_reconcile_only IS NULL OR p_operation_id IS NULL OR p_action IS NULL OR p_action NOT IN('open','rotate','close','accept','unsubscribe') OR
  (p_action IN('open','rotate','close') AND (p_collection_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision NOT BETWEEN 0 AND 2147483645 OR p_code IS NOT NULL)) OR
  (p_action='accept' AND (p_collection_id IS NOT NULL OR p_expected_revision IS NOT NULL OR p_code IS NULL OR p_code !~ '^[0-9A-HJKMNP-TV-Z]{26}$')) OR
  (p_action='unsubscribe' AND (p_collection_id IS NULL OR p_expected_revision IS NOT NULL OR p_code IS NOT NULL)) THEN
  RAISE EXCEPTION 'invalid_share_command' USING ERRCODE='22023';
 END IF;
 PERFORM 1 FROM auth.users WHERE id=principal FOR KEY SHARE NOWAIT;
 IF NOT FOUND THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 request:=CASE p_action WHEN 'accept' THEN jsonb_build_object('action','accept','code',p_code) WHEN 'unsubscribe' THEN jsonb_build_object('action','unsubscribe','collectionId',p_collection_id) ELSE jsonb_build_object('action',p_action,'collectionId',p_collection_id,'expectedRevision',p_expected_revision) END;
 -- This transaction-level mutex is outside the rollback block below.
 replay:=private.begin_collection_share_command_v1(p_operation_id,request);
 IF replay IS NOT NULL THEN RETURN private.collection_share_command_response_v1(replay); END IF;
 SELECT * INTO terminal FROM private.collection_share_terminal_rejections WHERE user_id=principal AND operation_id=p_operation_id;
 IF FOUND THEN
  IF terminal.request_hash<>sha256(convert_to(request::text,'UTF8')) THEN RAISE EXCEPTION 'share_operation_conflict' USING ERRCODE='22023'; END IF;
  RETURN jsonb_build_object('operationId',p_operation_id,'status','rejected','action',terminal.action,'collectionId',terminal.collection_id,'reason',terminal.reason);
 END IF;
 BEGIN
  RETURN private.collection_share_command_core_v1(p_operation_id,p_action,p_collection_id,p_expected_revision,p_code,p_reconcile_only);
 EXCEPTION WHEN serialization_failure OR invalid_parameter_value OR insufficient_privilege THEN
  GET STACKED DIAGNOSTICS message=MESSAGE_TEXT;
  IF p_reconcile_only OR p_action NOT IN('open','rotate','close') OR message NOT IN('share_revision_conflict','share_copy_required','share_unavailable') THEN RAISE; END IF;
  INSERT INTO private.collection_share_terminal_rejections(user_id,operation_id,request_hash,action,collection_id,reason)
   VALUES(principal,p_operation_id,sha256(convert_to(request::text,'UTF8')),p_action,p_collection_id,message);
  RETURN jsonb_build_object('operationId',p_operation_id,'status','rejected','action',p_action,'collectionId',p_collection_id,'reason',message);
 END;
END;
$_$;


--
-- Name: complete_dictionary_translation_job_v1(uuid, uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_dictionary_translation_job_v1(p_job_id uuid, p_lease_token uuid, p_overlay jsonb, p_note text DEFAULT NULL::text) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_job public.dictionary_translation_jobs; v_source_revision text;
BEGIN
  SELECT * INTO v_job FROM public.dictionary_translation_jobs WHERE id = p_job_id;
  IF NOT FOUND THEN RETURN false; END IF;
  PERFORM id FROM public.word_entries WHERE archived_at IS NULL AND id = v_job.word_entry_id FOR SHARE;
  IF NOT FOUND THEN RETURN false; END IF;
  v_source_revision := public.dictionary_translation_source_v1(v_job.word_entry_id)->>'revision';
  SELECT * INTO v_job FROM public.dictionary_translation_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.status <> 'running' OR v_job.lease_token IS DISTINCT FROM p_lease_token
      OR v_job.lease_expires_at <= clock_timestamp() THEN RETURN false; END IF;
  IF v_job.source_row_revision IS DISTINCT FROM v_source_revision THEN
    UPDATE public.dictionary_translation_jobs SET status = 'superseded', error_code = 'source_changed',
      lease_token = NULL, lease_expires_at = NULL, finished_at = clock_timestamp(), updated_at = clock_timestamp()
    WHERE id = p_job_id;
    RETURN false;
  END IF;
  IF p_overlay IS NULL OR jsonb_typeof(p_overlay) <> 'object' THEN
    RAISE EXCEPTION 'invalid translation overlay';
  END IF;
  INSERT INTO public.word_entry_translations (
    word_entry_id, target_lang, provider, status, overlay, note, source_fingerprint,
    source_content_revision, translation_policy_version, provider_revision, error_message, updated_at
  ) VALUES (v_job.word_entry_id, v_job.target_lang, v_job.provider, 'ready', p_overlay, p_note,
    v_job.source_fingerprint, v_job.source_content_revision, v_job.translation_policy_version,
    v_job.provider_revision, NULL, clock_timestamp())
  ON CONFLICT (word_entry_id, target_lang, provider) DO UPDATE SET status = 'ready', overlay = excluded.overlay,
    note = excluded.note, source_fingerprint = excluded.source_fingerprint,
    source_content_revision = excluded.source_content_revision, translation_policy_version = excluded.translation_policy_version,
    provider_revision = excluded.provider_revision, error_message = NULL, updated_at = excluded.updated_at;
  UPDATE public.dictionary_translation_jobs SET status = 'ready', lease_token = NULL, lease_expires_at = NULL,
    finished_at = clock_timestamp(), updated_at = clock_timestamp(), error_code = NULL WHERE id = p_job_id;
  RETURN true;
END $$;


--
-- Name: copy_collection_independent_entries_v1(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_collection_independent_entries_v1(p_operation_id uuid, p_list_id uuid, p_expected_revision text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE principal uuid:=(select auth.uid()); plan jsonb; receipt private.collection_copy_receipts%rowtype;
BEGIN
 IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 IF p_operation_id IS NULL OR p_list_id IS NULL OR p_expected_revision IS NULL OR p_expected_revision !~ '^[a-f0-9]{64}$' THEN
  RAISE EXCEPTION 'invalid_copy_request' USING ERRCODE='22023';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('collection-owned-copy:'||principal||':'||p_operation_id,0));
 SELECT * INTO receipt FROM private.collection_copy_receipts WHERE user_id=principal AND operation_id=p_operation_id;
 IF FOUND THEN
  IF receipt.list_id IS DISTINCT FROM p_list_id OR receipt.expected_revision IS DISTINCT FROM p_expected_revision THEN
   RAISE EXCEPTION 'copy_operation_conflict' USING ERRCODE='22023';
  END IF;
  RETURN jsonb_build_object('operationId',p_operation_id,'listId',p_list_id,'status','completed','copiedCount',receipt.copied_count);
 END IF;
 plan:=private.collection_copy_plan_v1(principal,p_list_id);
 IF plan->>'canCopy' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'copy_source_unavailable' USING ERRCODE='42501'; END IF;
 RETURN private.commit_collection_copy_plan_v1(principal,p_operation_id,p_list_id,p_expected_revision,plan);
END;
$_$;


--
-- Name: copy_entry_to_user_dictionary(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_entry_to_user_dictionary(p_user_id uuid, p_source_entry_id uuid, p_target_dictionary_id uuid DEFAULT NULL::uuid, p_overrides jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE key text; copied uuid;
BEGIN
 IF (SELECT auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (SELECT auth.uid()) THEN
  RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';
 END IF;
 IF p_source_entry_id IS NULL OR jsonb_typeof(COALESCE(p_overrides,'{}'))<>'object' OR octet_length(COALESCE(p_overrides,'{}')::text)>131072 THEN
  RAISE EXCEPTION 'invalid_copy_request' USING ERRCODE='22023';
 END IF;
 key:=encode(sha256(convert_to(jsonb_build_object('source',p_source_entry_id,'target',p_target_dictionary_id,'overrides',COALESCE(p_overrides,'{}'))::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('legacy-owned-copy:'||p_user_id||':'||key,0));
 SELECT copied_entry_id INTO copied FROM private.legacy_entry_copy_receipts WHERE user_id=p_user_id AND request_key=key;
 IF FOUND THEN RETURN copied; END IF;
 BEGIN
  copied:=private.copy_legacy_owned_entry_v1(p_user_id,p_source_entry_id,p_target_dictionary_id,p_overrides);
 EXCEPTION WHEN SQLSTATE '22023' THEN
  IF SQLERRM='copy_content_unsupported' THEN RAISE EXCEPTION 'invalid_user_entry'; ELSE RAISE; END IF;
 END;
 INSERT INTO private.legacy_entry_copy_receipts(user_id,request_key,copied_entry_id) VALUES(p_user_id,key,copied);
 RETURN copied;
END;
$$;


--
-- Name: copy_independent_entry_v1(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.copy_independent_entry_v1(p_operation_id uuid, p_source_entry_id uuid, p_expected_revision text, p_target_dictionary_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  RETURN private.copy_independent_entry_core_v1(p_operation_id,p_source_entry_id,p_expected_revision,p_target_dictionary_id,true);
END;
$$;


--
-- Name: create_user_dictionary_entry(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_dictionary_entry(p_user_id uuid, p_dictionary_id uuid DEFAULT NULL::uuid, p_entry jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
    v_dictionary dictionaries%rowtype;
    v_payload jsonb;
    v_word_id uuid;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    v_dictionary_id := COALESCE(
        p_dictionary_id,
        ensure_user_dictionary(
            p_user_id,
            COALESCE(NULLIF(trim(p_entry->>'languageCode'), ''), 'nl'),
            'My dictionary'
        )
    );
    v_dictionary := assert_editable_user_dictionary(p_user_id, v_dictionary_id);
    v_payload := validate_user_entry_v1_payload(p_entry, v_dictionary.language_code);

    IF EXISTS (
        SELECT 1
        FROM word_entries
        WHERE dictionary_id = v_dictionary_id
          AND language_code = v_payload->>'languageCode'
          AND headword = v_payload->>'headword'
          AND meaning_id = 1
    ) THEN
        RAISE EXCEPTION 'duplicate_user_entry';
    END IF;

    INSERT INTO word_entries (
        dictionary_id,
        language_code,
        headword,
        meaning_id,
        part_of_speech,
        gender,
        is_nt2_2000,
        raw
    )
    VALUES (
        v_dictionary_id,
        v_payload->>'languageCode',
        v_payload->>'headword',
        1,
        v_payload->>'partOfSpeech',
        v_payload->>'gender',
        false,
        v_payload
    )
    RETURNING id INTO v_word_id;

    RETURN v_word_id;
END;
$$;


--
-- Name: create_user_word_list(uuid, text, text, text, text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_user_word_list(p_user_id uuid, p_name text, p_description text DEFAULT NULL::text, p_language_code text DEFAULT 'nl'::text, p_primary_language_code text DEFAULT NULL::text, p_default_scenario_id text DEFAULT NULL::text, p_card_policy text DEFAULT 'inherit'::text, p_card_type_ids text[] DEFAULT NULL::text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_list user_word_lists%ROWTYPE;
    v_name text;
    v_language_code text;
    v_primary_language_code text;
    v_default_scenario_id text;
    v_card_policy text;
    v_card_type_ids text[];
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    v_name := NULLIF(trim(p_name), '');
    IF v_name IS NULL THEN
        RAISE EXCEPTION 'invalid_list_name';
    END IF;

    v_language_code := NULLIF(trim(COALESCE(p_language_code, 'nl')), '');
    v_primary_language_code := NULLIF(
        trim(COALESCE(p_primary_language_code, v_language_code)),
        ''
    );
    v_default_scenario_id := NULLIF(trim(COALESCE(p_default_scenario_id, '')), '');
    v_card_policy := private.normalize_list_card_policy(p_card_policy, 'inherit');
    v_card_type_ids := CASE
        WHEN p_card_type_ids IS NULL THEN NULL
        ELSE ARRAY(
            SELECT DISTINCT trim(card_type_id)
            FROM unnest(p_card_type_ids) AS card_type_id
            WHERE NULLIF(trim(card_type_id), '') IS NOT NULL
            ORDER BY trim(card_type_id)
        )
    END;
    IF v_card_type_ids IS NOT NULL AND array_length(v_card_type_ids, 1) IS NULL THEN
        v_card_type_ids := NULL;
    END IF;

    IF v_language_code IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM languages WHERE code = v_language_code) THEN
        RAISE EXCEPTION 'language_not_found';
    END IF;

    IF v_primary_language_code IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM languages WHERE code = v_primary_language_code) THEN
        RAISE EXCEPTION 'language_not_found';
    END IF;

    PERFORM private.validate_list_training_intent(
        v_default_scenario_id,
        v_card_policy,
        v_card_type_ids
    );

    INSERT INTO user_word_lists (
        user_id,
        name,
        description,
        language_code,
        primary_language_code,
        default_scenario_id,
        card_policy,
        card_type_ids
    )
    VALUES (
        p_user_id,
        v_name,
        NULLIF(p_description, ''),
        v_language_code,
        v_primary_language_code,
        v_default_scenario_id,
        v_card_policy,
        v_card_type_ids
    )
    RETURNING * INTO v_list;

    RETURN jsonb_build_object(
        'id', v_list.id,
        'name', v_list.name,
        'description', v_list.description,
        'language_code', v_list.language_code,
        'primary_language_code', v_list.primary_language_code,
        'default_scenario_id', v_list.default_scenario_id,
        'card_policy', v_list.card_policy,
        'card_type_ids', v_list.card_type_ids,
        'created_at', v_list.created_at,
        'user_word_list_items', jsonb_build_array(jsonb_build_object('count', 0))
    );
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'duplicate_user_list';
END;
$$;


--
-- Name: delete_expired_diagnostic_envelopes(timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_expired_diagnostic_envelopes(p_now timestamp with time zone DEFAULT now()) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE v_count integer;
BEGIN
  IF COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''),
      (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role') IS DISTINCT FROM 'service_role'
  THEN RAISE EXCEPTION 'unauthorized'; END IF;
  DELETE FROM public.diagnostic_envelopes WHERE expires_at <= p_now;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


--
-- Name: delete_user_dictionary_entry(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_dictionary_entry(p_user_id uuid, p_entry_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE entry public.word_entries%rowtype;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';
  END IF;
  SELECT * INTO entry FROM public.word_entries WHERE id=p_entry_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'entry_not_found'; END IF;
  PERFORM public.assert_editable_user_dictionary(p_user_id,entry.dictionary_id);
  IF entry.management_kind IS DISTINCT FROM 'user' THEN
    RAISE EXCEPTION 'author_entry_archive_forbidden' USING ERRCODE='42501';
  END IF;
  IF entry.archived_at IS NOT NULL THEN RETURN; END IF;
  UPDATE public.word_entries SET archived_at=clock_timestamp() WHERE id=p_entry_id;
  DELETE FROM public.dictionary_search_documents WHERE entry_id=p_entry_id;
END;
$$;


--
-- Name: delete_user_word_list(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.delete_user_word_list(p_user_id uuid, p_list_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    DELETE FROM user_word_lists
    WHERE id = p_list_id
      AND user_id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'list_not_found';
    END IF;
END;
$$;


