--
-- Name: enqueue_dictionary_translation_job_v1(uuid, text, text, text, text, text, text, integer, boolean, boolean, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enqueue_dictionary_translation_job_v1(p_word_entry_id uuid, p_target_lang text, p_provider text, p_source_fingerprint text, p_source_content_revision text, p_translation_policy_version text, p_provider_revision text, p_priority integer DEFAULT 0, p_retry_failed boolean DEFAULT false, p_refresh_ready boolean DEFAULT false, p_observed_cache_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS public.dictionary_translation_jobs
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_job public.dictionary_translation_jobs; v_now timestamptz := clock_timestamp(); v_restart boolean; v_cache_updated_at timestamptz; v_source_revision text;
BEGIN
  -- Match publication/deletion lock order: source first, then job/cache.
  PERFORM id FROM public.word_entries WHERE archived_at IS NULL AND id = p_word_entry_id FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'translation_source_missing'; END IF;
  v_source_revision := public.dictionary_translation_source_v1(p_word_entry_id)->>'revision';
  -- Serialize different revisions of the same shared cache slot, not all jobs.
  PERFORM pg_advisory_xact_lock(hashtextextended(
    p_word_entry_id::text || ':' || p_target_lang || ':' || p_provider, 674));
  v_now := clock_timestamp();
  SELECT * INTO v_job FROM public.dictionary_translation_jobs
  WHERE word_entry_id = p_word_entry_id AND target_lang = p_target_lang AND provider = p_provider
    AND source_fingerprint = p_source_fingerprint AND source_content_revision = p_source_content_revision
    AND translation_policy_version = p_translation_policy_version AND provider_revision = p_provider_revision
    AND source_row_revision = v_source_revision
  FOR UPDATE;
  IF FOUND AND v_job.status <> 'superseded' THEN
    v_restart := v_job.status = 'failed' AND (p_retry_failed OR v_job.error_code = 'source_changed') AND v_job.finished_at <= v_now - interval '1 minute';
    IF v_job.status = 'ready' AND p_refresh_ready THEN
      SELECT updated_at INTO v_cache_updated_at FROM public.word_entry_translations
        WHERE word_entry_id = p_word_entry_id AND target_lang = p_target_lang AND provider = p_provider FOR UPDATE;
      -- An enqueue request that read the cache before a concurrent completion
      -- cannot invalidate the newly published ready result.
      v_restart := v_cache_updated_at IS NOT DISTINCT FROM p_observed_cache_updated_at;
    END IF;
    IF v_restart THEN
      UPDATE public.dictionary_translation_jobs SET status = 'superseded', lease_token = NULL,
        lease_expires_at = NULL, updated_at = v_now, finished_at = v_now
      WHERE word_entry_id = p_word_entry_id AND target_lang = p_target_lang AND provider = p_provider
        AND status IN ('queued', 'running');
    END IF;
    UPDATE public.dictionary_translation_jobs SET
      priority = greatest(priority, least(10, greatest(0, p_priority))),
      status = CASE WHEN v_restart THEN 'queued' ELSE status END,
      attempt = CASE WHEN v_restart THEN 0 ELSE attempt END,
      available_at = CASE WHEN v_restart THEN v_now ELSE available_at END,
      error_code = CASE WHEN v_restart THEN NULL ELSE error_code END,
      finished_at = CASE WHEN v_restart THEN NULL ELSE finished_at END,
      updated_at = CASE WHEN v_restart THEN v_now ELSE updated_at END
    WHERE id = v_job.id RETURNING * INTO v_job;
    RETURN v_job;
  END IF;
  UPDATE public.dictionary_translation_jobs SET status = 'superseded', lease_token = NULL,
    lease_expires_at = NULL, updated_at = v_now, finished_at = v_now
  WHERE word_entry_id = p_word_entry_id AND target_lang = p_target_lang AND provider = p_provider
    AND status IN ('queued', 'running');
  INSERT INTO public.dictionary_translation_jobs (
    word_entry_id, target_lang, provider, source_fingerprint, source_content_revision,
    translation_policy_version, provider_revision, source_row_revision, priority
  ) VALUES (p_word_entry_id, p_target_lang, p_provider, p_source_fingerprint, p_source_content_revision,
    p_translation_policy_version, p_provider_revision, v_source_revision, least(10, greatest(0, p_priority)))
  ON CONFLICT ON CONSTRAINT dictionary_translation_job_identity DO UPDATE SET
    status = 'queued', attempt = 0, available_at = v_now, lease_token = NULL,
    lease_expires_at = NULL, finished_at = NULL, error_code = NULL, updated_at = v_now,
    priority = excluded.priority
  RETURNING * INTO v_job;
  RETURN v_job;
END $$;


--
-- Name: ensure_platform_v2_training_exercise_target_as_principal_v1(uuid, uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_platform_v2_training_exercise_target_as_principal_v1(p_entry_id uuid, p_content_node_id uuid, p_family text, p_direction text, p_source_revision text, p_source_text_fingerprint text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_jwt_role text := COALESCE(
        NULLIF(current_setting('request.jwt.claim.role', true), ''),
        (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role'
    );
BEGIN
    IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    RETURN private.ensure_platform_v2_training_exercise_target_v1(
        p_entry_id,
        p_content_node_id,
        p_family,
        p_direction,
        p_source_revision,
        p_source_text_fingerprint
    );
END;
$$;


--
-- Name: ensure_user_dictionary(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_user_dictionary(p_user_id uuid, p_language_code text DEFAULT 'nl'::text, p_name text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
    v_language_code text := COALESCE(NULLIF(trim(p_language_code), ''), 'nl');
    v_name text := COALESCE(NULLIF(trim(p_name), ''), 'My dictionary');
    v_slug text;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM languages WHERE code = v_language_code) THEN
        RAISE EXCEPTION 'language_not_found';
    END IF;

    v_slug := 'user-' || replace(p_user_id::text, '-', '') || '-' || v_language_code;

    INSERT INTO dictionaries (
        language_code,
        slug,
        name,
        description,
        kind,
        visibility,
        owner_user_id,
        is_editable,
        minimum_subscription_tier,
        schema_key,
        schema_version,
        source_provider
    )
    VALUES (
        v_language_code,
        v_slug,
        v_name,
        'Private user-owned editable dictionary.',
        'user',
        'private',
        p_user_id,
        true,
        'free',
        'user-entry-v1',
        1,
        'user'
    )
    ON CONFLICT (language_code, slug) DO UPDATE
    SET name = excluded.name,
        owner_user_id = excluded.owner_user_id,
        is_editable = true,
        schema_key = 'user-entry-v1',
        schema_version = 1,
        updated_at = now()
    RETURNING id INTO v_dictionary_id;

    RETURN v_dictionary_id;
END;
$$;


--
-- Name: fail_dictionary_translation_job_v1(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fail_dictionary_translation_job_v1(p_job_id uuid, p_lease_token uuid, p_error_code text, p_retryable boolean) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_job public.dictionary_translation_jobs;
BEGIN
  SELECT * INTO v_job FROM public.dictionary_translation_jobs WHERE id = p_job_id FOR UPDATE;
  IF NOT FOUND OR v_job.status <> 'running' OR v_job.lease_token IS DISTINCT FROM p_lease_token
      OR v_job.lease_expires_at <= clock_timestamp() THEN RETURN false; END IF;
  UPDATE public.dictionary_translation_jobs SET
    status = CASE WHEN p_retryable AND attempt < 3 THEN 'queued' ELSE 'failed' END,
    available_at = clock_timestamp() + make_interval(secs => CASE attempt WHEN 1 THEN 5 ELSE 20 END),
    error_code = p_error_code, lease_token = NULL, lease_expires_at = NULL, updated_at = clock_timestamp(),
    finished_at = CASE WHEN p_retryable AND attempt < 3 THEN NULL ELSE clock_timestamp() END
  WHERE id = p_job_id;
  RETURN true;
END $$;


--
-- Name: fetch_dictionary_entry_by_id_gated(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fetch_dictionary_entry_by_id_gated(p_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_entry jsonb;
BEGIN
    v_user_id := (select auth.uid());

    SELECT jsonb_build_object(
        'id', w.id,
        'dictionary_id', w.dictionary_id,
        'dictionary_name', d.name,
        'dictionary_slug', d.slug,
        'dictionary_kind', d.kind,
        'language_code', w.language_code,
        'headword', w.headword,
        'meaning_id', w.meaning_id,
        'part_of_speech', w.part_of_speech,
        'gender', w.gender,
        'raw', w.raw,
        'is_nt2_2000', w.is_nt2_2000,
        'meanings_count', (
            SELECT COUNT(*)
            FROM private.active_word_entries we
            WHERE we.headword = w.headword AND private.entry_access_v1(v_user_id,we.id,'browse')
              AND we.language_code = w.language_code
              AND (
                    (w.dictionary_id IS NULL AND we.dictionary_id IS NULL)
                 OR we.dictionary_id = w.dictionary_id
              )
        )
    )
    INTO v_entry
    FROM private.active_word_entries w
    LEFT JOIN dictionaries d ON d.id = w.dictionary_id
    WHERE w.id = p_entry_id
      AND private.entry_access_v1(v_user_id,w.id,'browse');

    RETURN private.entry_payload_for_reader_v1(v_user_id,v_entry);
END;
$$;


--
-- Name: fetch_dictionary_entry_gated(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fetch_dictionary_entry_gated(p_headword text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_normalized text;
    v_lookup_headword text;
    v_result jsonb;
BEGIN
    v_user_id := (select auth.uid());
    IF v_user_id IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    v_normalized := btrim(COALESCE(p_headword, ''));
    IF v_normalized = '' THEN
        RETURN '[]'::jsonb;
    END IF;

    SELECT w.headword INTO v_lookup_headword
    FROM private.active_word_entries w
    WHERE w.headword = v_normalized
      AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
    ORDER BY
      CASE
        WHEN w.dictionary_id IS NOT NULL AND EXISTS (
          SELECT 1 FROM dictionaries d
          WHERE d.id = w.dictionary_id
            AND d.owner_user_id = v_user_id
        ) THEN 0
        ELSE 1
      END,
      w.headword ASC,
      w.meaning_id ASC NULLS LAST
    LIMIT 1;

    IF v_lookup_headword IS NULL AND lower(v_normalized) <> v_normalized THEN
        SELECT w.headword INTO v_lookup_headword
        FROM private.active_word_entries w
        WHERE w.headword = lower(v_normalized)
          AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
        ORDER BY
          CASE
            WHEN w.dictionary_id IS NOT NULL AND EXISTS (
              SELECT 1 FROM dictionaries d
              WHERE d.id = w.dictionary_id
                AND d.owner_user_id = v_user_id
            ) THEN 0
            ELSE 1
          END,
          w.headword ASC,
          w.meaning_id ASC NULLS LAST
        LIMIT 1;
    END IF;

    IF v_lookup_headword IS NULL THEN
        SELECT w.headword INTO v_lookup_headword
        FROM word_forms f
        JOIN private.active_word_entries w ON w.id = f.word_id
        WHERE f.form = lower(v_normalized)
          AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
        ORDER BY
          CASE
            WHEN w.dictionary_id IS NOT NULL AND EXISTS (
              SELECT 1 FROM dictionaries d
              WHERE d.id = w.dictionary_id
                AND d.owner_user_id = v_user_id
            ) THEN 0
            ELSE 1
          END,
          f.headword ASC,
          w.meaning_id ASC NULLS LAST
        LIMIT 1;
    END IF;

    IF v_lookup_headword IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    WITH candidates AS (
        SELECT
            w.*,
            d.language_code AS dictionary_language_code,
            d.slug AS dictionary_slug,
            d.name AS dictionary_name,
            d.kind AS dictionary_kind,
            d.visibility AS dictionary_visibility,
            d.owner_user_id,
            d.is_editable AS dictionary_is_editable,
            d.schema_key AS dictionary_schema_key,
            d.schema_version AS dictionary_schema_version,
            COUNT(*) OVER (
                PARTITION BY w.dictionary_id, w.language_code, w.headword
            ) AS meanings_count
        FROM private.active_word_entries w
        LEFT JOIN dictionaries d ON d.id = w.dictionary_id
        WHERE w.headword = v_lookup_headword
          AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
    ),
    candidate_payloads AS (
        SELECT jsonb_strip_nulls(jsonb_build_object(
            'id', c.id,
            'dictionary_id', c.dictionary_id,
            'language_code', c.language_code,
            'headword', c.headword,
            'meaning_id', c.meaning_id,
            'part_of_speech', c.part_of_speech,
            'gender', c.gender,
            'raw', c.raw,
            'is_nt2_2000', c.is_nt2_2000,
            'meanings_count', COALESCE(c.meanings_count, 1),
            'dictionary', CASE
                WHEN c.dictionary_id IS NULL THEN NULL
                ELSE jsonb_build_object(
                    'id', c.dictionary_id,
                    'language_code', c.dictionary_language_code,
                    'slug', c.dictionary_slug,
                    'name', c.dictionary_name,
                    'kind', c.dictionary_kind,
                    'visibility', c.dictionary_visibility,
                    'owner_user_id', c.owner_user_id,
                    'is_editable', c.dictionary_is_editable,
                    'schema_key', c.dictionary_schema_key,
                    'schema_version', c.dictionary_schema_version
                )
            END,
            'stats', (
                SELECT jsonb_build_object(
                    'click_count', s.click_count,
                    'last_seen_at', s.last_seen_at
                )
                FROM user_card_status s
                WHERE s.user_id = v_user_id
                  AND s.entry_id = c.id
                ORDER BY s.last_seen_at DESC NULLS LAST
                LIMIT 1
            )
        )) AS payload,
        CASE
            WHEN c.owner_user_id = v_user_id THEN 0
            WHEN c.dictionary_kind = 'curated' THEN 1
            ELSE 2
        END AS dictionary_rank,
        c.language_code,
        c.headword,
        c.meaning_id
        FROM candidates c
    )
    SELECT COALESCE(
        jsonb_agg(payload ORDER BY dictionary_rank, language_code, headword, meaning_id),
        '[]'::jsonb
    )
    INTO v_result
    FROM candidate_payloads;

    RETURN v_result;
END;
$$;


--
-- Name: fetch_library_collection_entries(uuid, text, jsonb, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fetch_library_collection_entries(p_list_id uuid, p_list_type text, p_filters jsonb, p_query text DEFAULT NULL::text, p_language_code text DEFAULT NULL::text, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
  principal uuid := (select auth.uid());
  parts jsonb;
  selection jsonb;
  article text;
  maximum integer;
  page_offset bigint;
  page_limit integer;
  payload jsonb;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'not_authenticated' USING ERRCODE = '42501'; END IF;
  IF p_list_id IS NULL OR p_list_type IS NULL OR p_list_type NOT IN ('user','curated')
     OR p_page IS NULL OR p_page < 1 OR p_page_size IS NULL OR p_page_size NOT BETWEEN 1 AND 100
     OR (p_language_code IS NOT NULL AND (length(p_language_code) NOT BETWEEN 2 AND 16))
     OR length(COALESCE(p_query,'')) > 1000 THEN
    RAISE EXCEPTION 'invalid_collection_scope' USING ERRCODE = '22023';
  END IF;
  IF p_filters IS NULL OR jsonb_typeof(p_filters) <> 'object' THEN
    RAISE EXCEPTION 'invalid_library_filters' USING ERRCODE = '22023';
  END IF;
  IF EXISTS(SELECT 1 FROM jsonb_object_keys(p_filters) k WHERE k NOT IN ('parts','article')) THEN
    RAISE EXCEPTION 'invalid_library_filters' USING ERRCODE = '22023';
  END IF;
  parts := COALESCE(p_filters->'parts','[]'::jsonb);
  IF jsonb_typeof(parts) <> 'array' THEN
    RAISE EXCEPTION 'invalid_library_filters' USING ERRCODE = '22023';
  END IF;
  IF jsonb_array_length(parts) > 10 OR EXISTS (
    SELECT 1 FROM jsonb_array_elements(parts) x WHERE jsonb_typeof(x) <> 'string'
    OR x #>> '{}' NOT IN ('noun','verb','adjective','adverb','pronoun','preposition','conjunction','numeral','article','interjection')
  ) THEN RAISE EXCEPTION 'invalid_library_filters' USING ERRCODE = '22023'; END IF;
  article := p_filters->>'article';
  IF article IS NOT NULL AND (article NOT IN ('de','het') OR NOT (parts ? 'noun')) THEN
    RAISE EXCEPTION 'invalid_library_filters' USING ERRCODE = '22023';
  END IF;
  selection := jsonb_build_object('parts',parts,'article',article);
  maximum := CASE WHEN public.get_user_tier(principal) IN ('premium','admin') THEN NULL ELSE 100 END;
  page_offset := (p_page::bigint - 1) * p_page_size;
  page_limit := GREATEST(0,LEAST(p_page_size,COALESCE(maximum::bigint-page_offset,p_page_size)))::integer;

  -- Resolve membership and ownership once; no client-supplied principal and no
  -- filtering of a previously paginated result. Both count and items use scoped.
  WITH members AS MATERIALIZED (
    SELECT li.word_id, COALESCE(li.rank,999999) AS sort_rank, NULL::timestamptz AS added_at
    FROM public.word_list_items li
    WHERE p_list_type='curated' AND li.list_id=p_list_id
    UNION ALL
    SELECT li.word_id, 0 AS sort_rank, li.added_at
    FROM public.user_word_list_items li
    JOIN public.user_word_lists list ON list.id=li.list_id AND list.user_id=principal
    WHERE p_list_type='user' AND li.list_id=p_list_id
  ), scoped AS MATERIALIZED (
    SELECT w.id,w.dictionary_id,w.language_code,w.headword,w.part_of_speech,w.gender,w.raw,w.is_nt2_2000,
           members.sort_rank,members.added_at
    FROM members JOIN private.active_word_entries w ON w.id=members.word_id
    WHERE (w.dictionary_id IS NULL OR public.can_browse_dictionary(principal,w.dictionary_id))
      AND (p_language_code IS NULL OR w.language_code=p_language_code)
      AND (NULLIF(trim(p_query),'') IS NULL OR w.headword ILIKE '%' || trim(p_query) || '%')
      AND private.library_entry_matches_filters_v1(w.part_of_speech,w.gender,selection)
  ), page AS (
    SELECT * FROM scoped
    ORDER BY sort_rank ASC,added_at DESC NULLS LAST,headword ASC,id ASC
    OFFSET page_offset LIMIT page_limit
  )
  SELECT jsonb_build_object(
    'items',COALESCE((SELECT jsonb_agg(to_jsonb(page) ORDER BY sort_rank ASC,added_at DESC NULLS LAST,headword ASC,id ASC) FROM page),'[]'::jsonb),
    'total',(SELECT count(*) FROM scoped),
    'is_locked',maximum IS NOT NULL AND page_offset>=maximum,
    'max_allowed',maximum
  ) INTO payload;
  RETURN payload;
END;
$$;


--
-- Name: fetch_words_for_list_gated(uuid, text, text, text, boolean, boolean, boolean, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fetch_words_for_list_gated(p_list_id uuid, p_list_type text DEFAULT 'curated'::text, p_query text DEFAULT NULL::text, p_part_of_speech text DEFAULT NULL::text, p_is_nt2 boolean DEFAULT NULL::boolean, p_filter_frozen boolean DEFAULT NULL::boolean, p_filter_hidden boolean DEFAULT NULL::boolean, p_page integer DEFAULT 1, p_page_size integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_tier text;
    v_offset int;
    v_limit int;
    v_total int;
    v_max_allowed int;
    v_items jsonb;
BEGIN
    v_user_id := (select auth.uid());
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('items', '[]'::jsonb, 'total', 0, 'is_locked', true, 'max_allowed', 0);
    END IF;

    v_tier := get_user_tier(v_user_id);
    v_max_allowed := CASE WHEN v_tier IN ('premium', 'admin') THEN NULL ELSE 100 END;
    v_offset := (GREATEST(p_page, 1) - 1) * p_page_size;
    v_limit := p_page_size;

    IF p_list_type <> 'curated'
       AND NOT EXISTS (SELECT 1 FROM user_word_lists WHERE id = p_list_id AND user_id = v_user_id) THEN
        RETURN jsonb_build_object('items', '[]'::jsonb, 'total', 0, 'is_locked', false, 'max_allowed', v_max_allowed);
    END IF;

    IF p_list_type = 'curated' THEN
        WITH visible_entries AS (
            SELECT w.*, COALESCE(li.rank, 999999) AS sort_rank
            FROM private.active_word_entries w
            JOIN word_list_items li ON li.word_id = w.id
            WHERE li.list_id = p_list_id
              AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
              AND (p_query IS NULL OR w.headword ILIKE '%' || p_query || '%')
              AND (p_part_of_speech IS NULL OR w.part_of_speech = p_part_of_speech)
              AND (p_is_nt2 IS NULL OR w.is_nt2_2000 = p_is_nt2)
              AND (p_filter_hidden IS NULL OR p_filter_hidden = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND COALESCE(s.hidden, false) = true))
              AND (p_filter_frozen IS NULL OR p_filter_frozen = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND s.frozen_until IS NOT NULL AND s.frozen_until > now()))
        )
        SELECT COUNT(*) INTO v_total
        FROM visible_entries;
    ELSE
        WITH visible_entries AS (
            SELECT w.*, li.added_at
            FROM private.active_word_entries w
            JOIN user_word_list_items li ON li.word_id = w.id
            WHERE li.list_id = p_list_id
              AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
              AND (p_query IS NULL OR w.headword ILIKE '%' || p_query || '%')
              AND (p_part_of_speech IS NULL OR w.part_of_speech = p_part_of_speech)
              AND (p_is_nt2 IS NULL OR w.is_nt2_2000 = p_is_nt2)
              AND (p_filter_hidden IS NULL OR p_filter_hidden = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND COALESCE(s.hidden, false) = true))
              AND (p_filter_frozen IS NULL OR p_filter_frozen = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND s.frozen_until IS NOT NULL AND s.frozen_until > now()))
        )
        SELECT COUNT(*) INTO v_total
        FROM visible_entries;
    END IF;

    IF v_max_allowed IS NOT NULL AND v_offset >= v_max_allowed THEN
        RETURN jsonb_build_object('items', '[]'::jsonb, 'total', v_total, 'is_locked', true, 'max_allowed', v_max_allowed);
    END IF;

    IF v_max_allowed IS NOT NULL AND (v_offset + v_limit) > v_max_allowed THEN
        v_limit := v_max_allowed - v_offset;
    END IF;

    IF p_list_type = 'curated' THEN
        WITH visible_entries AS (
            SELECT w.*, COALESCE(li.rank, 999999) AS sort_rank
            FROM private.active_word_entries w
            JOIN word_list_items li ON li.word_id = w.id
            WHERE li.list_id = p_list_id
              AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
              AND (p_query IS NULL OR w.headword ILIKE '%' || p_query || '%')
              AND (p_part_of_speech IS NULL OR w.part_of_speech = p_part_of_speech)
              AND (p_is_nt2 IS NULL OR w.is_nt2_2000 = p_is_nt2)
              AND (p_filter_hidden IS NULL OR p_filter_hidden = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND COALESCE(s.hidden, false) = true))
              AND (p_filter_frozen IS NULL OR p_filter_frozen = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND s.frozen_until IS NOT NULL AND s.frozen_until > now()))
        )
        SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.sort_rank, t.headword), '[]'::jsonb) INTO v_items
        FROM (
            SELECT id, dictionary_id, language_code, headword, part_of_speech, gender, raw, is_nt2_2000, sort_rank
            FROM visible_entries
            ORDER BY sort_rank ASC, headword ASC
            OFFSET v_offset LIMIT v_limit
        ) t;
    ELSE
        WITH visible_entries AS (
            SELECT w.*, li.added_at
            FROM private.active_word_entries w
            JOIN user_word_list_items li ON li.word_id = w.id
            WHERE li.list_id = p_list_id
              AND (w.dictionary_id IS NULL OR can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
              AND (p_query IS NULL OR w.headword ILIKE '%' || p_query || '%')
              AND (p_part_of_speech IS NULL OR w.part_of_speech = p_part_of_speech)
              AND (p_is_nt2 IS NULL OR w.is_nt2_2000 = p_is_nt2)
              AND (p_filter_hidden IS NULL OR p_filter_hidden = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND COALESCE(s.hidden, false) = true))
              AND (p_filter_frozen IS NULL OR p_filter_frozen = false
                   OR EXISTS (SELECT 1 FROM user_card_status s WHERE s.user_id = v_user_id AND s.entry_id = w.id AND s.frozen_until IS NOT NULL AND s.frozen_until > now()))
        )
        SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb), '[]'::jsonb) INTO v_items
        FROM (
            SELECT id, dictionary_id, language_code, headword, part_of_speech, gender, raw, is_nt2_2000
            FROM visible_entries
            ORDER BY added_at DESC, headword ASC
            OFFSET v_offset LIMIT v_limit
        ) t;
    END IF;

    RETURN jsonb_build_object(
        'items', v_items,
        'total', v_total,
        'is_locked', v_max_allowed IS NOT NULL AND v_total > v_max_allowed,
        'max_allowed', v_max_allowed
    );
END;
$$;


--
-- Name: fsrs6_compute(numeric, numeric, timestamp with time zone, smallint, numeric, integer, integer, numeric[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fsrs6_compute(p_stability numeric, p_difficulty numeric, p_last_review_at timestamp with time zone, p_grade smallint, p_target_retention numeric, p_reps integer, p_lapses integer, p_params numeric[]) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
    w0 numeric := p_params[1];
    w1 numeric := p_params[2];
    w2 numeric := p_params[3];
    w3 numeric := p_params[4];
    w4 numeric := p_params[5];
    w5 numeric := p_params[6];
    w6 numeric := p_params[7];
    w7 numeric := p_params[8];
    w8 numeric := p_params[9];
    w9 numeric := p_params[10];
    w10 numeric := p_params[11];
    w11 numeric := p_params[12];
    w12 numeric := p_params[13];
    w13 numeric := p_params[14];
    w14 numeric := p_params[15];
    w15 numeric := p_params[16];
    w16 numeric := p_params[17];
    w17 numeric := p_params[18];
    w18 numeric := p_params[19];
    w19 numeric := p_params[20];
    w20 numeric := p_params[21];
    new_stability numeric;
    new_difficulty numeric;
    new_interval numeric;
    elapsed_days numeric;
    retrievability numeric;
    reps_out int := coalesce(p_reps, 0);
    lapses_out int := coalesce(p_lapses, 0);
    same_day boolean := false;
    d0_easy numeric;
    tmp_d numeric;
BEGIN
    IF p_grade < 1 OR p_grade > 4 THEN
        RAISE EXCEPTION 'grade must be 1..4';
    END IF;

    IF p_stability IS NULL OR p_difficulty IS NULL THEN
        CASE p_grade
            WHEN 1 THEN new_stability := w0;
            WHEN 2 THEN new_stability := w1;
            WHEN 3 THEN new_stability := w2;
            WHEN 4 THEN new_stability := w3;
        END CASE;
        new_difficulty := w4 - exp(w5 * (p_grade - 1)) + 1;
        new_interval := fsrs6_interval(new_stability, p_target_retention, w20);
        reps_out := 1;
        lapses_out := CASE WHEN p_grade = 1 THEN 1 ELSE 0 END;
        RETURN jsonb_build_object(
            'stability', round(new_stability, 6),
            'difficulty', round(greatest(1, least(10, new_difficulty)), 6),
            'interval', round(new_interval, 6),
            'retrievability', 0.9,
            'elapsed', 0,
            'same_day', false,
            'reps', reps_out,
            'lapses', lapses_out
        );
    END IF;

    elapsed_days := greatest(0.0, extract(epoch from (
        private.training_reference_now_v1() - coalesce(p_last_review_at, private.training_reference_now_v1())
    )) / 86400);
    retrievability := power(1 + (power(0.9, -1/w20) - 1) * elapsed_days / greatest(p_stability, 0.0001), -w20);
    same_day := p_last_review_at IS NOT NULL
      AND (p_last_review_at::date = private.training_reference_now_v1()::date);

    -- The updated difficulty is returned to the caller, but FSRS stability
    -- uses the difficulty that existed before this review.
    tmp_d := p_difficulty + (-w6 * (p_grade - 3)) * (10 - p_difficulty) / 9;
    d0_easy := w4 - exp(w5 * 3) + 1;
    new_difficulty := w7 * d0_easy + (1 - w7) * tmp_d;
    new_difficulty := greatest(1, least(10, new_difficulty));
    reps_out := reps_out + 1;
    IF p_grade = 1 THEN
        lapses_out := lapses_out + 1;
    END IF;

    IF same_day THEN
        -- fsrs-rs v4.1.1 uses the short-term stability update for every
        -- rating at delta_t = 0. Successful ratings are clamped so that
        -- short-term practice cannot reduce existing stability.
        new_stability := p_stability * exp(w17 * (p_grade - 3 + w18)) * power(p_stability, -w19);
        IF p_grade >= 3 THEN
            new_stability := greatest(p_stability, new_stability);
        END IF;
    ELSIF p_grade = 1 THEN
        new_stability := w11 * power(p_difficulty, -w12) * (power(p_stability + 1, w13) - 1) * exp(w14 * (1 - retrievability));
        new_stability := greatest(new_stability, p_stability / exp(w17 * w18));
    ELSE
        new_stability := p_stability * (
            exp(w8) *
            (11 - p_difficulty) *
            power(p_stability, -w9) *
            (exp(w10 * (1 - retrievability)) - 1) *
            (CASE WHEN p_grade = 2 THEN w15 ELSE 1 END) *
            (CASE WHEN p_grade = 4 THEN w16 ELSE 1 END)
            + 1
        );
    END IF;
    new_interval := fsrs6_interval(new_stability, p_target_retention, w20);

    RETURN jsonb_build_object(
        'stability', round(new_stability, 6),
        'difficulty', round(new_difficulty, 6),
        'interval', round(new_interval, 6),
        'retrievability', round(retrievability, 6),
        'elapsed', round(elapsed_days, 6),
        'same_day', same_day,
        'reps', reps_out,
        'lapses', lapses_out
    );
END;
$$;


--
-- Name: fsrs6_interval(numeric, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fsrs6_interval(p_stability numeric, p_retention numeric, p_w20 numeric) RETURNS numeric
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE
    factor numeric;
BEGIN
    IF p_stability IS NULL OR p_stability <= 0 THEN
        RETURN NULL;
    END IF;
    factor := power(0.9, -1/p_w20) - 1;
    RETURN p_stability / factor * (power(p_retention, -1/p_w20) - 1);
END;
$$;


--
-- Name: fsrs6_parameters(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fsrs6_parameters() RETURNS numeric[]
    LANGUAGE sql IMMUTABLE
    AS $$
    SELECT array[
        0.212,   -- w0 S0(again)
        1.2931,  -- w1 S0(hard)
        2.3065,  -- w2 S0(good)
        8.2956,  -- w3 S0(easy)
        6.4133,  -- w4 D base
        0.8334,  -- w5 D exponent
        3.0194,  -- w6 delta D scale
        0.001,   -- w7 mean reversion weight
        1.8722,  -- w8 stability scale
        0.1666,  -- w9 stability S power
        0.796,   -- w10 stability R scale
        1.4835,  -- w11 post-lapse scale
        0.0614,  -- w12 post-lapse D power (negative in formula)
        0.2629,  -- w13 post-lapse S power
        1.6483,  -- w14 post-lapse R scale
        0.6014,  -- w15 hard penalty
        1.8729,  -- w16 easy bonus
        0.5425,  -- w17 same-day scale
        0.0912,  -- w18 same-day offset
        0.0658,  -- w19 same-day S power
        0.1542   -- w20 decay
    ];
$$;


--
-- Name: get_active_training_scope(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_training_scope(p_user_id uuid, p_language_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_language_code text := COALESCE(NULLIF(trim(p_language_code), ''), 'nl');
    v_scope user_training_scopes%rowtype;
    v_active_list_id uuid;
    v_active_list_type text;
    v_valid boolean := false;
    v_result jsonb;
BEGIN
    IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT *
    INTO v_scope
    FROM user_training_scopes
    WHERE user_id = p_user_id
      AND language_code = v_language_code;

    v_active_list_id := v_scope.active_list_id;
    v_active_list_type := v_scope.active_list_type;

    IF v_scope.user_id IS NOT NULL AND v_scope.active_list_id IS NOT NULL THEN
        IF v_scope.active_list_type = 'curated' THEN
            SELECT EXISTS (
                SELECT 1
                FROM word_lists l
                WHERE l.id = v_scope.active_list_id
                  AND l.language_code = v_language_code
            )
            INTO v_valid;
        ELSIF v_scope.active_list_type = 'user' THEN
            SELECT EXISTS (
                SELECT 1
                FROM user_word_lists l
                WHERE l.id = v_scope.active_list_id
                  AND ((l.user_id = p_user_id AND (
                    COALESCE(l.primary_language_code, l.language_code) = v_language_code
                    OR (l.primary_language_code IS NULL AND l.language_code = v_language_code)
                    OR EXISTS(SELECT 1 FROM private.training_collection_catalog_cohort_v1(
                      p_user_id,'',v_language_code,NULL,NULL,1,ARRAY[l.id]) material WHERE material.eligible)
                  )) OR private.received_collection_training_available_v1(p_user_id,l.id,v_language_code))
            )
            INTO v_valid;
        END IF;
    END IF;

    -- Return a repaired/default scope for stale list references, but do not
    -- persist that repair from a read RPC.
    IF v_scope.user_id IS NOT NULL AND v_scope.active_list_id IS NOT NULL AND NOT v_valid THEN
        v_active_list_id := NULL;
        v_active_list_type := NULL;
    END IF;

    SELECT jsonb_build_object(
        'language_code', v_language_code,
        'active_list_id', v_active_list_id,
        'active_list_type', v_active_list_type,
        'active_scenario', COALESCE(v_scope.active_scenario, settings.active_scenario, 'understanding'),
        'card_filter', COALESCE(v_scope.card_filter, settings.card_filter, 'both'),
        'modes_enabled', COALESCE(v_scope.modes_enabled, settings.modes_enabled, ARRAY['word-to-definition']::text[]),
        'new_review_ratio', COALESCE(v_scope.new_review_ratio, settings.new_review_ratio, 2),
        'has_saved_scope', v_scope.user_id IS NOT NULL,
        'is_valid', COALESCE(v_valid, false)
    )
    INTO v_result
    FROM user_settings settings
    WHERE settings.user_id = p_user_id;

    v_result:=COALESCE(v_result, jsonb_build_object(
        'language_code', v_language_code,
        'active_list_id', NULL,
        'active_list_type', NULL,
        'active_scenario', 'understanding',
        'card_filter', 'both',
        'modes_enabled', ARRAY['word-to-definition']::text[],
        'new_review_ratio', 2,
        'has_saved_scope', false,
        'is_valid', false
    ));
    IF v_scope.active_list_type='user' AND v_scope.active_list_id IS NOT NULL
       AND (v_scope.active_list_owner_user_id IS NOT NULL AND v_scope.active_list_owner_user_id<>p_user_id
        OR EXISTS(SELECT 1 FROM public.user_word_lists list WHERE list.id=v_scope.active_list_id AND list.user_id<>p_user_id)) THEN
      v_result:=v_result||jsonb_build_object('active_list_ownership','received',
        'active_list_id',v_scope.active_list_id,'active_list_type','user','is_valid',v_valid,'has_saved_scope',true,
        'active_scenario',COALESCE(v_scope.active_scenario,v_result->>'active_scenario'),
        'card_filter',COALESCE(v_scope.card_filter,v_result->>'card_filter'),
        'modes_enabled',COALESCE(to_jsonb(v_scope.modes_enabled),v_result->'modes_enabled'),
        'new_review_ratio',COALESCE(v_scope.new_review_ratio,(v_result->>'new_review_ratio')::integer));
      IF NOT v_valid THEN
        v_result:=v_result||jsonb_build_object(
          'active_list_id',v_scope.active_list_id,'active_list_type','user','is_valid',false,
          'unavailable_reason','shared_collection_unavailable');
      END IF;
    END IF;
    RETURN v_result;
END;
$$;


--
-- Name: get_active_word_list(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_word_list(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_language_code text;
BEGIN
    IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT COALESCE(NULLIF(language_code, ''), 'nl')
    INTO v_language_code
    FROM user_settings
    WHERE user_id = p_user_id;

    RETURN get_active_training_scope(p_user_id, COALESCE(v_language_code, 'nl'));
END;
$$;


--
-- Name: get_available_dictionary_sources(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_dictionary_sources(p_user_id uuid, p_language_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_result jsonb;
BEGIN
    IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF v_language_code IS NULL THEN
        RETURN '[]'::jsonb;
    END IF;

    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'id', d.id,
                'language_code', d.language_code,
                'slug', d.slug,
                'name', d.name,
                'kind', d.kind,
                'visibility', d.visibility,
                'is_editable', d.is_editable,
                'entry_count', source_counts.entry_count
            )
            ORDER BY
                CASE WHEN d.kind = 'user' AND d.owner_user_id = p_user_id THEN 0 ELSE 1 END,
                d.name ASC,
                d.slug ASC
        ),
        '[]'::jsonb
    )
    INTO v_result
    FROM dictionaries d
    JOIN LATERAL (
        SELECT COUNT(*)::int AS entry_count
        FROM private.active_word_entries w
        WHERE w.dictionary_id = d.id
          AND w.language_code = d.language_code
    ) source_counts ON true
    WHERE d.language_code = v_language_code
      AND source_counts.entry_count > 0
      AND can_browse_dictionary(p_user_id, d.id, 'read');

    RETURN v_result;
END;
$$;


--
-- Name: get_available_learning_languages(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_learning_languages(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    WITH dictionary_counts AS (
        SELECT
            d.language_code,
            COUNT(*)::int AS dictionary_count
        FROM dictionaries d
        WHERE can_browse_dictionary(p_user_id, d.id, 'read')
          AND EXISTS (
            SELECT 1
            FROM private.active_word_entries w
            WHERE w.dictionary_id = d.id
              AND w.language_code = d.language_code
          )
        GROUP BY d.language_code
    ),
    curated_counts AS (
        SELECT
            l.language_code,
            COUNT(*)::int AS curated_list_count
        FROM word_lists l
        WHERE EXISTS (
            SELECT 1 FROM word_list_items item WHERE item.list_id = l.id
        )
        GROUP BY l.language_code
    ),
    user_counts AS (
        SELECT
            COALESCE(l.primary_language_code, l.language_code) AS language_code,
            COUNT(*)::int AS user_list_count
        FROM user_word_lists l
        WHERE l.user_id = p_user_id
          AND EXISTS (
            SELECT 1 FROM user_word_list_items item WHERE item.list_id = l.id
        )
        GROUP BY COALESCE(l.primary_language_code, l.language_code)
    ),
    available AS (
        SELECT language_code FROM dictionary_counts
        UNION
        SELECT language_code FROM curated_counts
        UNION
        SELECT language_code FROM user_counts
    )
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'code', lang.code,
                'label', lang.name,
                'dictionary_count', COALESCE(dictionary_counts.dictionary_count, 0),
                'curated_list_count', COALESCE(curated_counts.curated_list_count, 0),
                'user_list_count', COALESCE(user_counts.user_list_count, 0),
                'has_training_eligible_lists',
                    COALESCE(curated_counts.curated_list_count, 0)
                    + COALESCE(user_counts.user_list_count, 0) > 0
            )
            ORDER BY lang.code
        ),
        '[]'::jsonb
    )
    INTO v_result
    FROM available
    JOIN languages lang ON lang.code = available.language_code
    LEFT JOIN dictionary_counts ON dictionary_counts.language_code = lang.code
    LEFT JOIN curated_counts ON curated_counts.language_code = lang.code
    LEFT JOIN user_counts ON user_counts.language_code = lang.code;

    RETURN v_result;
END;
$$;


--
-- Name: get_available_word_lists(uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_available_word_lists(p_user_id uuid, p_language_code text DEFAULT NULL::text, p_list_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_result jsonb;
BEGIN
    IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    WITH entry_sources AS MATERIALIZED (
        SELECT id, dictionary_id FROM private.active_word_entries
    ), selected_lists AS MATERIALIZED (
        SELECT id FROM public.word_lists
        WHERE (p_list_type IS NULL OR p_list_type = 'curated')
          AND (v_language_code IS NULL OR language_code = v_language_code)
    ), curated_source_counts AS MATERIALIZED (
        SELECT item.list_id, entry.dictionary_id, count(*)::int AS item_count,
            entry.dictionary_id IS NULL
                OR public.can_browse_dictionary(p_user_id, entry.dictionary_id) AS accessible
        FROM public.word_list_items item
        JOIN selected_lists selected ON selected.id = item.list_id
        JOIN entry_sources entry ON entry.id = item.word_id
        GROUP BY item.list_id, entry.dictionary_id
    ), curated AS (
        SELECT jsonb_build_object(
            'id', l.id,
            'list_type', 'curated',
            'name', l.name,
            'description', l.description,
            'language_code', l.language_code,
            'primary_language_code', l.primary_language_code,
            'is_mixed_language', false,
            'is_primary', l.is_primary,
            'sort_order', l.sort_order,
            'word_list_items', jsonb_build_array(jsonb_build_object(
                'count', availability.item_count,
                'available_count', availability.available_item_count,
                'unavailable_source_count', availability.unavailable_source_count
            ))
        ) AS row,
        COALESCE(l.sort_order, 2147483647) AS sort_order,
        l.is_primary,
        l.name,
        NULL::timestamptz AS created_at
        FROM word_lists l
        CROSS JOIN LATERAL (
            SELECT
                COALESCE(sum(source.item_count), 0)::int AS item_count,
                COALESCE(sum(source.item_count) FILTER (WHERE source.accessible), 0)::int
                    AS available_item_count,
                count(*) FILTER (
                    WHERE source.dictionary_id IS NOT NULL AND NOT source.accessible
                )::int AS unavailable_source_count
            FROM curated_source_counts source
            WHERE source.list_id = l.id
        ) AS availability
        WHERE (p_list_type IS NULL OR p_list_type = 'curated')
          AND (v_language_code IS NULL OR l.language_code = v_language_code)
    ),
    user_lists AS (
        SELECT jsonb_build_object(
            'id', l.id,
            'list_type', 'user',
            'name', l.name,
            'description', l.description,
            'language_code', l.language_code,
            'primary_language_code', l.primary_language_code,
            'is_mixed_language', item_languages.language_count > 1,
            'created_at', l.created_at,
            'user_word_list_items', jsonb_build_array(jsonb_build_object(
                'count', availability.item_count,
                'available_count', availability.available_item_count,
                'unavailable_source_count', availability.unavailable_source_count
            ))
        ) AS row,
        2147483647 AS sort_order,
        false AS is_primary,
        l.name,
        l.created_at
        FROM user_word_lists l
        JOIN LATERAL (
            SELECT
                COUNT(*)::int AS item_count,
                COUNT(DISTINCT w.language_code)::int AS language_count
            FROM user_word_list_items item
            JOIN private.active_word_entries w ON w.id = item.word_id
            WHERE item.list_id = l.id
        ) item_languages ON true
        JOIN LATERAL (
            SELECT
                COALESCE(sum(source.item_count), 0)::int AS item_count,
                COALESCE(sum(source.item_count) FILTER (WHERE source.accessible), 0)::int
                    AS available_item_count,
                count(*) FILTER (
                    WHERE source.dictionary_id IS NOT NULL AND NOT source.accessible
                )::int AS unavailable_source_count
            FROM (
                SELECT
                    entry.dictionary_id,
                    count(*)::int AS item_count,
                    entry.dictionary_id IS NULL
                        OR can_browse_dictionary(p_user_id, entry.dictionary_id)
                        AS accessible
                FROM user_word_list_items item
                JOIN private.active_word_entries entry ON entry.id = item.word_id
                WHERE item.list_id = l.id
                GROUP BY entry.dictionary_id
            ) AS source
        ) AS availability ON true
        WHERE (p_list_type IS NULL OR p_list_type = 'user')
          AND l.user_id = p_user_id
          AND (
            v_language_code IS NULL
            OR item_languages.language_count > 1
            OR (
                item_languages.language_count <= 1
                AND (
                    COALESCE(l.primary_language_code, l.language_code) = v_language_code
                    OR (l.primary_language_code IS NULL AND l.language_code = v_language_code)
                )
            )
          )
    ),
    combined AS (
        SELECT row, 0 AS group_order, sort_order, is_primary, name, created_at
        FROM curated
        UNION ALL
        SELECT row, 1 AS group_order, sort_order, is_primary, name, created_at
        FROM user_lists
    )
    SELECT COALESCE(
        jsonb_agg(row ORDER BY group_order, sort_order, is_primary DESC, name ASC, created_at DESC),
        '[]'::jsonb
    )
    INTO v_result
    FROM combined;

    RETURN v_result;
END;
$$;


--
-- Name: get_card_user_state(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_card_user_state(p_user_id uuid, p_word_id uuid, p_mode text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
    v_result jsonb;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT dictionary_id INTO v_dictionary_id
    FROM word_entries
    WHERE id = p_word_id;

    IF NOT FOUND THEN
        RETURN NULL;
    END IF;

    IF v_dictionary_id IS NOT NULL
       AND NOT can_access_dictionary(p_user_id, v_dictionary_id, 'read') THEN
        RETURN NULL;
    END IF;

    SELECT jsonb_build_object(
        'fsrs_last_interval', s.fsrs_last_interval,
        'fsrs_reps', s.fsrs_reps,
        'fsrs_stability', s.fsrs_stability,
        'fsrs_difficulty', s.fsrs_difficulty,
        'fsrs_lapses', s.fsrs_lapses,
        'fsrs_last_grade', s.fsrs_last_grade,
        'fsrs_params_version', s.fsrs_params_version,
        'click_count', s.click_count,
        'seen_count', s.seen_count,
        'success_count', s.success_count,
        'last_seen_at', s.last_seen_at,
        'last_reviewed_at', s.last_reviewed_at,
        'next_review_at', s.next_review_at,
        'hidden', s.hidden,
        'frozen_until', s.frozen_until,
        'in_learning', s.in_learning,
        'learning_due_at', s.learning_due_at
    )
    INTO v_result
    FROM user_card_status s
    WHERE s.user_id = p_user_id
      AND s.entry_id = p_word_id
      AND s.card_type_id = p_mode;

    RETURN v_result;
END;
$$;


