--
-- Name: FUNCTION get_detailed_training_stats(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_detailed_training_stats(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text) IS 'Authenticated training statistics using the learner timezone stored in user settings.';


--
-- Name: get_detailed_training_stats(uuid, text[], uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_detailed_training_stats(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text, p_timezone text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  base_stats jsonb;
  local_stats jsonb;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;

  base_stats := private.get_detailed_training_stats_utc_legacy_v1(
    p_user_id, p_modes, p_list_id, p_list_type
  );
  local_stats := private.training_local_daily_stats_v1(
    p_user_id,
    p_modes,
    p_list_id,
    p_list_type,
    private.training_user_timezone_v1(p_user_id)
  );
  RETURN COALESCE(base_stats, '{}'::jsonb) || COALESCE(local_stats, '{}'::jsonb);
END;
$$;


--
-- Name: FUNCTION get_detailed_training_stats(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text, p_timezone text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_detailed_training_stats(p_user_id uuid, p_modes text[], p_list_id uuid, p_list_type text, p_timezone text) IS 'Authenticated stats projection using the persisted learner-local 04:00 study day; the timezone argument is retained for compatibility.';


