-- Name: get_dictionary_search_backfill_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_dictionary_search_backfill_status(p_run_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'runId', id,
                'status', status,
                'extractionVersion', extraction_version,
                'batchSize', batch_size,
                'processedEntryCount', processed_entry_count,
                'totalEntryCount', total_entry_count,
                'lastEntryId', last_entry_id,
                'lastError', last_error,
                'startedAt', started_at,
                'updatedAt', updated_at,
                'completedAt', completed_at
            )
            ORDER BY updated_at DESC
        ),
        '[]'::jsonb
    )
    FROM dictionary_search_backfill_runs
    WHERE p_run_id IS NULL OR id = p_run_id;
$$;


