--
-- Name: get_meaning_learning_progress_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_meaning_learning_progress_v1(p_entry_id uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
    SELECT public.get_meanings_learning_progress_v1(ARRAY[p_entry_id]) -> 0;
$$;


--
-- Name: get_meanings_learning_progress_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_meanings_learning_progress_v1(p_entry_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid := auth.uid();
    v_result jsonb;
BEGIN
    IF v_user_id IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;
    IF p_entry_ids IS NULL OR cardinality(p_entry_ids) > 1250 THEN
        RAISE EXCEPTION 'meaning_progress_limit';
    END IF;
    IF EXISTS (
        WITH shared_entries AS MATERIALIZED (
          SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(v_user_id,p_entry_ids) shared
        ) SELECT 1 FROM unnest(p_entry_ids) target(id)
        LEFT JOIN public.word_entries entry ON entry.id = target.id
        WHERE entry.id IS NULL OR (
            entry.dictionary_id IS NOT NULL
            AND NOT public.can_access_dictionary(v_user_id, entry.dictionary_id, 'read')
            AND entry.id NOT IN (SELECT shared.entry_id FROM shared_entries shared)
        )
    ) THEN RAISE EXCEPTION 'meaning_unavailable'; END IF;

    WITH states AS MATERIALIZED (
        SELECT * FROM public.get_platform_v2_card_states_for_entries(
            v_user_id, p_entry_ids,
            ARRAY['word-to-definition','definition-to-word']::text[]
        )
    ), snapshots AS (
        SELECT entry.id, jsonb_build_object(
            'entryId', entry.id,
            'headword', entry.headword,
            'exclusionId', exclusion.id,
            'directions', jsonb_agg(jsonb_build_object(
                'cardTypeId', state.card_type_id,
                'stateRevision', COALESCE(state.state_revision::text, 'untracked'),
                'knownMarkId', state.known_mark_id,
                'knownMarkRevision', state.known_mark_revision,
                'knownMarkedAt', state.known_marked_at,
                'phase', CASE
                    WHEN state.hidden THEN 'hidden'
                    WHEN state.frozen_until > private.training_reference_now_v1() THEN 'frozen'
                    WHEN state.in_learning THEN 'learning'
                    WHEN state.fsrs_reps > 0 OR state.last_reviewed_at IS NOT NULL THEN 'reviewing'
                    ELSE 'new'
                END,
                'presentations', COALESCE(state.seen_count, 0),
                'gradedAttempts', COALESCE(state.fsrs_reps, 0),
                'lastGrade', state.fsrs_last_grade,
                'lastReviewedAt', state.last_reviewed_at,
                'nextReviewAt', COALESCE(state.learning_due_at, state.next_review_at),
                'stability', state.fsrs_stability,
                'difficulty', state.fsrs_difficulty
            ) ORDER BY state.card_type_id DESC)
        ) value
        FROM states state
        JOIN public.word_entries entry ON entry.id = state.entry_id
        LEFT JOIN private.training_headword_exclusions exclusion
            ON exclusion.user_id = v_user_id AND exclusion.entry_id = entry.id
            AND exclusion.restored_at IS NULL
        GROUP BY entry.id, entry.headword, exclusion.id
    )
    SELECT COALESCE(jsonb_agg(
        value || jsonb_build_object('revision', encode(digest(value::text, 'sha256'), 'hex'))
        ORDER BY id
    ), '[]'::jsonb) INTO v_result FROM snapshots;
    RETURN v_result;
END;
$$;


--
-- Name: get_next_card(uuid, text[], uuid[], uuid, text, text, text, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_card(p_user_id uuid, p_card_type_ids text[], p_exclude_entry_ids uuid[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_card_keys text[]) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM public.get_next_card(
    p_user_id,
    p_card_type_ids,
    p_exclude_entry_ids,
    p_list_id,
    p_list_type,
    p_card_filter,
    p_queue_turn,
    p_exclude_card_keys,
    false
  );
END;
$$;


--
-- Name: get_next_card(uuid, text[], uuid[], uuid, text, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_card(p_user_id uuid, p_card_type_ids text[], p_exclude_entry_ids uuid[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_card_keys text[], p_allow_practice boolean) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  selected record;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  SELECT * INTO selected
  FROM private.training_scheduler_candidates_v2(
    p_user_id, p_card_type_ids, p_list_id, p_list_type, p_card_filter,
    p_queue_turn, p_exclude_entry_ids, p_exclude_card_keys, '{}', false, true
  ) candidate
  WHERE p_allow_practice OR candidate.queue_source <> 'practice'
  ORDER BY candidate.selection_order
  LIMIT 1;
  IF selected.entry_id IS NOT NULL THEN
    RETURN NEXT private.project_training_scheduler_candidate_v1(
      p_user_id, selected.entry_id, selected.card_type_id, selected.queue_source,
      '{}', false, selected.new_today, selected.daily_new_limit,
      selected.new_pool_size, selected.learning_due_count, selected.review_pool_size
    );
  END IF;
END;
$$;


--
-- Name: get_next_filtered_card(uuid, text[], uuid[], uuid, text, text, text, text[], jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_filtered_card(p_user_id uuid, p_card_type_ids text[], p_exclude_entry_ids uuid[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_card_keys text[], p_training_filter jsonb) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM public.get_next_filtered_card(
    p_user_id,
    p_card_type_ids,
    p_exclude_entry_ids,
    p_list_id,
    p_list_type,
    p_card_filter,
    p_queue_turn,
    p_exclude_card_keys,
    p_training_filter,
    false
  );
END;
$$;


--
-- Name: get_next_filtered_card(uuid, text[], uuid[], uuid, text, text, text, text[], jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_filtered_card(p_user_id uuid, p_card_type_ids text[], p_exclude_entry_ids uuid[], p_list_id uuid, p_list_type text, p_card_filter text, p_queue_turn text, p_exclude_card_keys text[], p_training_filter jsonb, p_allow_practice boolean) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  selected record;
  filter_data jsonb := COALESCE(p_training_filter, '{}');
  activity_filtered boolean;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  activity_filtered := private.training_filter_target_date(filter_data) IS NOT NULL
    OR NULLIF(filter_data->>'sourceId', '') IS NOT NULL
    OR NULLIF(trim(filter_data->>'sourceKind'), '') IS NOT NULL
    OR NULLIF(trim(filter_data->>'externalId'), '') IS NOT NULL;

  SELECT * INTO selected
  FROM private.training_scheduler_candidates_v2(
    p_user_id, p_card_type_ids, p_list_id, p_list_type,
    CASE WHEN p_card_filter = 'review' AND p_allow_practice THEN 'both'
         ELSE p_card_filter END,
    p_queue_turn, p_exclude_entry_ids, p_exclude_card_keys,
    filter_data, activity_filtered, true
  ) candidate
  WHERE (p_allow_practice OR candidate.queue_source <> 'practice')
    AND NOT (p_card_filter = 'review' AND p_allow_practice
      AND candidate.queue_source = 'new')
  ORDER BY candidate.selection_order
  LIMIT 1;

  IF selected.entry_id IS NOT NULL THEN
    RETURN NEXT private.project_training_scheduler_candidate_v1(
      p_user_id, selected.entry_id, selected.card_type_id, selected.queue_source,
      filter_data, activity_filtered, selected.new_today,
      selected.daily_new_limit, selected.new_pool_size,
      selected.learning_due_count, selected.review_pool_size
    );
  END IF;
END;
$$;


--
-- Name: get_next_training_session_card(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_training_session_card(p_user_id uuid, p_session_id uuid) RETURNS SETOF jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
  SELECT *
  FROM public.get_next_training_session_card(
    p_user_id,
    p_session_id,
    ARRAY[]::text[]
  );
$$;


--
-- Name: get_next_training_session_card(uuid, uuid, text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_training_session_card(p_user_id uuid, p_session_id uuid, p_exclude_card_keys text[]) RETURNS SETOF jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  PERFORM private.training_reference_now_v1();
  IF NOT EXISTS (
    SELECT 1 FROM public.training_active_runs
    WHERE user_id = p_user_id AND session_id = p_session_id
  ) THEN
    RETURN;
  END IF;
  PERFORM private.replan_training_session_remainder_v1(p_user_id,p_session_id);
  RETURN QUERY
  SELECT * FROM private.get_next_training_session_card_latch_v1(
    p_user_id, p_session_id, p_exclude_card_keys
  );
END;
$$;


--
-- Name: get_platform_v2_card_states_for_entries(uuid, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_platform_v2_card_states_for_entries(p_user_id uuid, p_entry_ids uuid[], p_card_type_ids text[] DEFAULT NULL::text[]) RETURNS TABLE(entry_id uuid, card_type_id text, click_count integer, seen_count integer, success_count integer, last_seen_at timestamp with time zone, last_reviewed_at timestamp with time zone, next_review_at timestamp with time zone, hidden boolean, frozen_until timestamp with time zone, in_learning boolean, learning_due_at timestamp with time zone, fsrs_stability numeric, fsrs_difficulty numeric, fsrs_reps integer, fsrs_lapses integer, fsrs_last_grade smallint, fsrs_last_interval numeric, fsrs_params_version text, state_revision uuid, known_mark_id uuid, known_mark_revision uuid, known_marked_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    IF (select auth.uid()) IS NULL
       OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;
    IF p_entry_ids IS NULL OR array_length(p_entry_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    WITH shared_entries AS MATERIALIZED (
      SELECT shared.entry_id FROM private.shared_author_entry_ids_v1(p_user_id,p_entry_ids) shared
    ), requested_entries AS (
        SELECT DISTINCT requested.entry_id
        FROM unnest(p_entry_ids) AS requested(entry_id)
    ), requested_card_types AS (
        SELECT DISTINCT requested.entry_id, card_choice.card_type_id
        FROM requested_entries requested
        CROSS JOIN LATERAL (
            SELECT unnest(p_card_type_ids) AS card_type_id
            WHERE p_card_type_ids IS NOT NULL
              AND array_length(p_card_type_ids, 1) IS NOT NULL
            UNION
            SELECT status.card_type_id
            FROM public.user_card_status status
            WHERE (p_card_type_ids IS NULL
                   OR array_length(p_card_type_ids, 1) IS NULL)
              AND status.user_id = p_user_id
              AND status.entry_id = requested.entry_id
            UNION
            SELECT known.card_type_id
            FROM public.user_card_known_marks known
            WHERE (p_card_type_ids IS NULL
                   OR array_length(p_card_type_ids, 1) IS NULL)
              AND known.user_id = p_user_id
              AND known.entry_id = requested.entry_id
              AND known.cleared_at IS NULL
        ) card_choice
    )
    SELECT
        requested.entry_id,
        requested.card_type_id,
        status.click_count,
        status.seen_count,
        status.success_count,
        status.last_seen_at,
        status.last_reviewed_at,
        status.next_review_at,
        status.hidden,
        status.frozen_until,
        status.in_learning,
        status.learning_due_at,
        status.fsrs_stability,
        status.fsrs_difficulty,
        status.fsrs_reps,
        status.fsrs_lapses,
        status.fsrs_last_grade,
        status.fsrs_last_interval,
        status.fsrs_params_version,
        status.state_revision,
        known.id,
        known.revision,
        known.marked_at
    FROM requested_card_types requested
    JOIN public.word_entries entry ON entry.id = requested.entry_id
    LEFT JOIN public.user_card_status status
      ON status.user_id = p_user_id
     AND status.entry_id = requested.entry_id
     AND status.card_type_id = requested.card_type_id
    LEFT JOIN public.user_card_known_marks known
      ON known.user_id = p_user_id
     AND known.entry_id = requested.entry_id
     AND known.card_type_id = requested.card_type_id
     AND known.cleared_at IS NULL
    WHERE entry.dictionary_id IS NULL
       OR public.can_access_dictionary(p_user_id, entry.dictionary_id, 'read')
       OR entry.id IN (SELECT shared.entry_id FROM shared_entries shared);
END;
$$;


--
-- Name: get_recent_training_activity_v1(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_training_activity_v1(p_limit integer DEFAULT 50) RETURNS TABLE(activity_id text, entry_id uuid, headword text, part_of_speech text, review_result text, card_type_id text, exercise_family text, exercise_direction text, target_id uuid, exercise_text text, reviewed_at timestamp with time zone, has_more boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid := (select auth.uid());
    v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 50);
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'unauthorized: authenticated user required';
    END IF;

    RETURN QUERY
    WITH activity AS MATERIALIZED (
        (SELECT
            w.id AS entry_id,
            w.headword,
            w.part_of_speech,
            'learning_started'::text AS review_result,
            e.card_type_id,
            e.created_at AS reviewed_at,
            'word-start:' || e.id::text AS activity_id,
            'meaning'::text AS exercise_family, NULL::text AS exercise_direction,
            NULL::uuid AS target_id, NULL::text AS exercise_text
        FROM public.user_card_action_events e
        JOIN public.word_entries w ON w.id = e.entry_id
        WHERE e.user_id = v_user_id
          AND e.action = 'start-learning'
          AND (
              w.dictionary_id IS NULL
              OR public.can_access_dictionary(v_user_id, w.dictionary_id, 'read')
          )
        ORDER BY e.created_at DESC, e.id DESC LIMIT v_limit + 1)
        UNION ALL
        (SELECT
            w.id AS entry_id,
            w.headword,
            w.part_of_speech,
            CASE rl.grade
                WHEN 1 THEN 'review_fail'
                WHEN 2 THEN 'review_hard'
                WHEN 3 THEN 'review_success'
                WHEN 4 THEN 'review_easy'
            END AS review_result,
            rl.mode AS card_type_id,
            rl.reviewed_at,
            'word-review:' || rl.id::text AS activity_id,
            'meaning'::text AS exercise_family, NULL::text AS exercise_direction,
            NULL::uuid AS target_id, NULL::text AS exercise_text
        FROM public.user_review_log rl
        JOIN public.word_entries w ON w.id = rl.word_id
        WHERE rl.user_id = v_user_id
          AND rl.grade BETWEEN 1 AND 4
          AND (
              w.dictionary_id IS NULL
              OR public.can_access_dictionary(v_user_id, w.dictionary_id, 'read')
          )
        ORDER BY rl.reviewed_at DESC, rl.id DESC LIMIT v_limit + 1)
        UNION ALL
        (SELECT w.id, w.headword, w.part_of_speech,
            CASE e.result WHEN 'fail' THEN 'review_fail' WHEN 'hard' THEN 'review_hard'
                WHEN 'success' THEN 'review_success' WHEN 'easy' THEN 'review_easy' END,
            NULL::text, e.created_at, 'exercise-review:' || e.id::text,
            t.family, t.direction, t.id,
            CASE WHEN w.archived_at IS NULL AND n.source_text_fingerprint = t.source_text_fingerprint
                THEN NULLIF(btrim(n.canonical_source_text), '') END
        FROM public.user_training_exercise_action_events e
        JOIN private.platform_v2_training_exercise_targets t ON t.id = e.target_id
        JOIN public.word_entries w ON w.id = t.entry_id
        LEFT JOIN private.platform_v2_content_nodes n ON n.id = t.content_node_id
        WHERE e.user_id = v_user_id
          AND e.action = 'review-exercise'
          AND e.result IN ('fail', 'hard', 'success', 'easy')
          AND t.family IN ('idiom', 'translation')
          AND (w.dictionary_id IS NULL
              OR public.can_access_dictionary(v_user_id, w.dictionary_id, 'read'))
        ORDER BY e.created_at DESC, e.id DESC LIMIT v_limit + 1)
    ), bounded AS MATERIALIZED (
        SELECT *
        FROM activity a
        ORDER BY a.reviewed_at DESC, a.activity_id DESC
        LIMIT v_limit + 1
    ), projection AS (
        SELECT (pg_catalog.count(*) > v_limit) AS has_more
        FROM bounded
    )
    SELECT
        b.activity_id,
        b.entry_id,
        b.headword,
        b.part_of_speech,
        b.review_result,
        b.card_type_id,
        b.exercise_family,
        b.exercise_direction,
        b.target_id,
        b.exercise_text,
        b.reviewed_at,
        p.has_more
    FROM bounded b
    CROSS JOIN projection p
    ORDER BY b.reviewed_at DESC, b.activity_id DESC
    LIMIT v_limit;
END;
$$;


--
-- Name: FUNCTION get_recent_training_activity_v1(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_recent_training_activity_v1(p_limit integer) IS 'Authenticated latest 50-action read projection of word and exercise history. No raw source context; stale node text is withheld; legacy history RPC remains available.';


--
-- Name: get_recent_training_history(uuid, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_training_history(p_user_id uuid, p_since timestamp with time zone DEFAULT (now() - '24:00:00'::interval), p_limit integer DEFAULT 50) RETURNS TABLE(id uuid, dictionary_id uuid, language_code text, headword text, part_of_speech text, gender text, raw jsonb, is_nt2_2000 boolean, meanings_count integer, event_type text, mode text, created_at timestamp with time zone, click_count integer, last_seen_at timestamp with time zone, fsrs_last_interval double precision, fsrs_reps integer, fsrs_stability double precision, next_review_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    RETURN QUERY
    SELECT
        w.id,
        w.dictionary_id,
        w.language_code,
        w.headword,
        w.part_of_speech,
        w.gender,
        CASE
            WHEN w.archived_at IS NOT NULL THEN '{}'::jsonb
            WHEN jsonb_typeof(w.raw) = 'object'
             AND NOT (w.raw ? 'meaning_id')
             AND w.meaning_id IS NOT NULL
                THEN jsonb_set(w.raw, '{meaning_id}', to_jsonb(w.meaning_id), true)
            ELSE w.raw
        END AS raw,
        w.is_nt2_2000,
        GREATEST((
            SELECT COUNT(*)::int
            FROM word_entries sibling
            WHERE sibling.headword = w.headword
              AND sibling.language_code = w.language_code
              AND (
                    (w.dictionary_id IS NULL AND sibling.dictionary_id IS NULL)
                 OR sibling.dictionary_id = w.dictionary_id
              )
        ), 1) AS meanings_count,
        e.event_type,
        e.mode,
        e.created_at,
        COALESCE(s.click_count, 0) AS click_count,
        COALESCE(s.last_seen_at, e.created_at) AS last_seen_at,
        s.fsrs_last_interval::double precision,
        s.fsrs_reps,
        s.fsrs_stability::double precision,
        s.next_review_at
    FROM user_events e
    JOIN word_entries w ON w.id = e.word_id
    LEFT JOIN user_card_status s
      ON s.user_id = e.user_id
     AND s.entry_id = e.word_id
     AND s.card_type_id = e.mode
    WHERE e.user_id = p_user_id
      AND e.created_at >= COALESCE(p_since, now() - interval '24 hours')
      AND (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
    ORDER BY e.created_at DESC
    LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
END;
$$;


--
-- Name: get_recent_training_review_history(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_recent_training_review_history(p_limit integer DEFAULT 50) RETURNS TABLE(entry_id uuid, headword text, part_of_speech text, review_result text, card_type_id text, reviewed_at timestamp with time zone, has_more boolean)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid := (select auth.uid());
    v_limit integer := LEAST(GREATEST(COALESCE(p_limit, 50), 1), 50);
BEGIN
    IF v_user_id IS NULL THEN
        RAISE EXCEPTION 'unauthorized: authenticated user required';
    END IF;

    RETURN QUERY
    WITH activity AS MATERIALIZED (
        SELECT
            w.id AS entry_id,
            w.headword,
            w.part_of_speech,
            'learning_started'::text AS review_result,
            e.card_type_id,
            e.created_at AS reviewed_at,
            e.id AS activity_id
        FROM public.user_card_action_events e
        JOIN public.word_entries w ON w.id = e.entry_id
        WHERE e.user_id = v_user_id
          AND e.action = 'start-learning'
          AND e.created_at >= pg_catalog.now() - interval '24 hours'
          AND (
              w.dictionary_id IS NULL
              OR public.can_access_dictionary(v_user_id, w.dictionary_id, 'read')
          )
        UNION ALL
        SELECT
            w.id AS entry_id,
            w.headword,
            w.part_of_speech,
            CASE rl.grade
                WHEN 1 THEN 'review_fail'
                WHEN 2 THEN 'review_hard'
                WHEN 3 THEN 'review_success'
                WHEN 4 THEN 'review_easy'
            END AS review_result,
            rl.mode AS card_type_id,
            rl.reviewed_at,
            rl.id AS activity_id
        FROM public.user_review_log rl
        JOIN public.word_entries w ON w.id = rl.word_id
        WHERE rl.user_id = v_user_id
          AND rl.reviewed_at >= pg_catalog.now() - interval '24 hours'
          AND rl.grade BETWEEN 1 AND 4
          AND (
              w.dictionary_id IS NULL
              OR public.can_access_dictionary(v_user_id, w.dictionary_id, 'read')
          )
    ), bounded AS MATERIALIZED (
        SELECT *
        FROM activity
        ORDER BY reviewed_at DESC, activity_id DESC
        LIMIT v_limit + 1
    ), projection AS (
        SELECT (pg_catalog.count(*) > v_limit) AS has_more
        FROM bounded
    )
    SELECT
        b.entry_id,
        b.headword,
        b.part_of_speech,
        b.review_result,
        b.card_type_id,
        b.reviewed_at,
        p.has_more
    FROM bounded b
    CROSS JOIN projection p
    ORDER BY b.reviewed_at DESC, b.activity_id DESC
    LIMIT v_limit;
END;
$$;


--
-- Name: FUNCTION get_recent_training_review_history(p_limit integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_recent_training_review_history(p_limit integer) IS 'Authenticated display-only projection of recent learning-started and graded review activity from the server-owned trailing 24-hour window.';


--
-- Name: get_scenario_stats(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scenario_stats(p_user_id uuid, p_scenario_id text, p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT 'curated'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_card_modes text[];
    v_graduation_threshold numeric;
    v_total int;
    v_learned int;
    v_in_progress int;
    v_new int;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT card_modes, graduation_threshold
    INTO v_card_modes, v_graduation_threshold
    FROM training_scenarios WHERE id = p_scenario_id;

    IF v_card_modes IS NULL THEN
        RETURN jsonb_build_object('error', 'Scenario not found');
    END IF;

    WITH accessible_entries AS (
        SELECT w.id
        FROM private.active_word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    ),
    word_min_stability AS (
        SELECT
            ae.id as word_id,
            MIN(COALESCE(s.fsrs_stability, 0)) as min_stability,
            COUNT(s.entry_id) as cards_started
        FROM accessible_entries ae
        LEFT JOIN user_card_status s ON s.entry_id = ae.id
            AND s.user_id = p_user_id
            AND s.card_type_id = ANY(v_card_modes)
            AND s.fsrs_enabled = true
            AND s.hidden = false
        GROUP BY ae.id
    )
    SELECT
        COUNT(*),
        COUNT(*) FILTER (WHERE min_stability >= v_graduation_threshold AND cards_started >= array_length(v_card_modes, 1)),
        COUNT(*) FILTER (WHERE cards_started > 0 AND (min_stability < v_graduation_threshold OR cards_started < array_length(v_card_modes, 1))),
        COUNT(*) FILTER (WHERE cards_started = 0)
    INTO v_total, v_learned, v_in_progress, v_new
    FROM word_min_stability;

    RETURN jsonb_build_object(
        'learned', COALESCE(v_learned, 0),
        'in_progress', COALESCE(v_in_progress, 0),
        'new', COALESCE(v_new, 0),
        'total', COALESCE(v_total, 0),
        'scenario_id', p_scenario_id,
        'card_modes', v_card_modes,
        'graduation_threshold', v_graduation_threshold
    );
END;
$$;


--
-- Name: get_scenario_word_stats(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_scenario_word_stats(p_user_id uuid, p_word_id uuid, p_scenario_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_card_modes text[];
    v_result jsonb;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT card_modes INTO v_card_modes
    FROM training_scenarios WHERE id = p_scenario_id;

    IF v_card_modes IS NULL THEN
        RETURN jsonb_build_object('error', 'Scenario not found');
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM private.active_word_entries w
        WHERE w.id = p_word_id
          AND (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
    ) THEN
        RETURN jsonb_build_object(
            'min_stability', null, 'avg_stability', null, 'max_stability', null,
            'cards_started', 0, 'cards_total', array_length(v_card_modes, 1), 'is_learned', false
        );
    END IF;

    SELECT jsonb_build_object(
        'min_stability', MIN(s.fsrs_stability),
        'avg_stability', AVG(s.fsrs_stability),
        'max_stability', MAX(s.fsrs_stability),
        'cards_started', COUNT(s.entry_id),
        'cards_total', array_length(v_card_modes, 1),
        'is_learned', COALESCE(MIN(s.fsrs_stability), 0) >= (
            SELECT graduation_threshold FROM training_scenarios WHERE id = p_scenario_id
        )
    ) INTO v_result
    FROM user_card_status s
    WHERE s.user_id = p_user_id
      AND s.entry_id = p_word_id
      AND s.card_type_id = ANY(v_card_modes)
      AND s.fsrs_enabled = true
      AND s.hidden = false;

    RETURN COALESCE(v_result, jsonb_build_object(
        'min_stability', null, 'avg_stability', null, 'max_stability', null,
        'cards_started', 0, 'cards_total', array_length(v_card_modes, 1), 'is_learned', false
    ));
END;
$$;


--
-- Name: get_training_active_time_v1(date, date, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_active_time_v1(p_start_date date, p_end_date date, p_language_code text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
 principal uuid := (select auth.uid());
 timezone text;
 days jsonb;
 coverage timestamptz;
BEGIN
 IF principal IS NULL THEN RETURN jsonb_build_object('error','unauthorized'); END IF;
 IF p_start_date IS NULL OR p_end_date IS NULL OR NOT isfinite(p_start_date) OR NOT isfinite(p_end_date)
  OR p_end_date<p_start_date OR p_end_date-p_start_date>365
  OR (p_language_code IS NOT NULL AND p_language_code !~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$') THEN
  RETURN jsonb_build_object('error','invalid_time_range'); END IF;
 timezone := private.training_user_timezone_v1(principal);
 SELECT started_at INTO coverage FROM private.training_active_time_coverage_v1 WHERE singleton;
 WITH bounds AS (
  SELECT study_date::date AS date,(study_date::date+time '04:00') AT TIME ZONE timezone AS starts,
   (study_date::date+1+time '04:00') AT TIME ZONE timezone AS ends
  FROM generate_series(0,p_end_date-p_start_date) AS offset_days(i)
  CROSS JOIN LATERAL (SELECT p_start_date+i AS study_date) d
 ), totals AS (
  SELECT b.date,floor(COALESCE(sum(extract(epoch FROM
   LEAST(t.observed_at,b.ends)-GREATEST(t.observed_at-t.active_ms*interval '1 millisecond',b.starts))*1000) FILTER (WHERE t.measurement_id IS NOT NULL),0))::bigint AS ms
  FROM bounds b LEFT JOIN private.training_active_time_v1 t
   ON t.user_id=principal AND t.observed_at>b.starts AND t.observed_at<b.ends+interval '30 seconds'
    AND t.observed_at-t.active_ms*interval '1 millisecond'<b.ends
    AND (p_language_code IS NULL OR t.language_code=p_language_code)
  GROUP BY b.date
 ) SELECT jsonb_agg(jsonb_build_object('date',date,'activeMilliseconds',ms) ORDER BY date) INTO days FROM totals;
 RETURN jsonb_build_object('coverageStartedAt',coverage,'timezone',timezone,'days',days);
END;
$_$;


--
-- Name: get_training_activity_days_v1(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_activity_days_v1(p_language_code text DEFAULT NULL::text, p_days integer DEFAULT 366) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
 principal uuid := (select auth.uid());
 v_timezone text;
 v_today date;
 v_first date;
 v_starts timestamptz;
 v_ends timestamptz;
 v_active jsonb;
 v_days jsonb;
BEGIN
 IF principal IS NULL THEN RETURN jsonb_build_object('error','unauthorized'); END IF;
 IF p_days IS NULL OR p_days NOT BETWEEN 1 AND 366
  OR (p_language_code IS NOT NULL AND p_language_code !~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$') THEN
  RETURN jsonb_build_object('error','invalid_activity_range'); END IF;
 v_timezone := private.training_user_timezone_v1(principal);
 v_today := private.training_study_day_date_v1(clock_timestamp(),v_timezone);
 v_first := v_today-(p_days-1);
 v_starts := (v_first+time '04:00') AT TIME ZONE v_timezone;
 v_ends := (v_today+1+time '04:00') AT TIME ZONE v_timezone;
 -- Measured time keeps a single attribution authority (migration 187).
 v_active := public.get_training_active_time_v1(v_first,v_today,p_language_code);
 IF v_active ? 'error' OR v_active->>'timezone' IS DISTINCT FROM v_timezone THEN
  RETURN jsonb_build_object('error','activity_unavailable'); END IF;
 WITH meaning_new AS (
  SELECT private.training_study_day_date_v1(e.created_at,v_timezone) AS day,e.entry_id,e.card_type_id
  FROM public.user_card_action_events e JOIN public.word_entries w ON w.id=e.entry_id
  WHERE e.user_id=principal AND e.action='start-learning' AND e.created_at>=v_starts AND e.created_at<v_ends
   AND (p_language_code IS NULL OR w.language_code=p_language_code)
  UNION
  SELECT private.training_study_day_date_v1(r.reviewed_at,v_timezone),r.word_id,r.mode
  FROM public.user_review_log r JOIN public.word_entries w ON w.id=r.word_id
  WHERE r.user_id=principal AND r.review_type='new' AND r.reviewed_at>=v_starts AND r.reviewed_at<v_ends
   AND (p_language_code IS NULL OR w.language_code=p_language_code)
 ), meaning_reviews AS (
  SELECT private.training_study_day_date_v1(r.reviewed_at,v_timezone) AS day,count(*) AS n
  FROM public.user_review_log r JOIN public.word_entries w ON w.id=r.word_id
  WHERE r.user_id=principal AND r.review_type='review' AND r.reviewed_at>=v_starts AND r.reviewed_at<v_ends
   AND (p_language_code IS NULL OR w.language_code=p_language_code)
  GROUP BY 1
 ), exercise AS (
  SELECT private.training_study_day_date_v1(e.created_at,v_timezone) AS day,
   NOT EXISTS (SELECT 1 FROM public.user_training_exercise_action_events earlier
    WHERE earlier.user_id=principal AND earlier.target_id=e.target_id
     AND earlier.action='review-exercise' AND earlier.created_at<e.created_at) AS introduced
  FROM public.user_training_exercise_action_events e
  JOIN private.platform_v2_training_exercise_targets t ON t.id=e.target_id
  JOIN public.word_entries w ON w.id=t.entry_id
  WHERE e.user_id=principal AND e.action='review-exercise' AND e.created_at>=v_starts AND e.created_at<v_ends
   AND (p_language_code IS NULL OR w.language_code=p_language_code)
 ), counts AS (
  SELECT day,sum(fresh)::integer AS fresh,sum(reviews)::integer AS reviews FROM (
   SELECT day,count(*) AS fresh,0::bigint AS reviews FROM meaning_new GROUP BY day
   UNION ALL SELECT day,0,n FROM meaning_reviews
   UNION ALL SELECT day,count(*) FILTER (WHERE introduced),count(*) FILTER (WHERE NOT introduced) FROM exercise GROUP BY day
  ) parts GROUP BY day
 )
 SELECT jsonb_agg(jsonb_build_object('date',d.date,'newCount',COALESCE(c.fresh,0),'reviewCount',COALESCE(c.reviews,0),
   'activeMilliseconds',(a->>'activeMilliseconds')::bigint) ORDER BY d.date)
 INTO v_days
 FROM jsonb_array_elements(v_active->'days') a
 CROSS JOIN LATERAL (SELECT (a->>'date')::date AS date) d
 LEFT JOIN counts c ON c.day=d.date;
 RETURN jsonb_build_object('timezone',v_timezone,'today',v_today,
  'coverageStartedAt',v_active->'coverageStartedAt','days',v_days);
END;
$_$;


--
-- Name: FUNCTION get_training_activity_days_v1(p_language_code text, p_days integer); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_training_activity_days_v1(p_language_code text, p_days integer) IS 'Own learner activity per learner-local 04:00 study day ending today; read-only, no scheduler state.';


--
-- Name: get_training_filter_sources(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_filter_sources(p_user_id uuid, p_limit integer DEFAULT 50) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    RETURN QUERY
    SELECT jsonb_build_object(
        'sourceId', s.id,
        'kind', s.kind,
        'provider', s.provider,
        'externalId', s.external_id,
        'title', s.title,
        'label',
            CASE
                WHEN s.kind IN ('youtube', 'youtube_video') OR s.provider = 'youtube'
                    THEN 'YouTube · ' || COALESCE(NULLIF(s.title, ''), NULLIF(s.external_id, ''), 'Untitled video')
                ELSE COALESCE(NULLIF(s.title, ''), NULLIF(s.external_id, ''), s.kind)
            END,
        'eventCount', COUNT(e.id),
        'lastSeenAt', MAX(e.created_at)
    )
    FROM user_card_action_events e
    JOIN learning_sources s ON s.id = e.source_id
    WHERE e.user_id = p_user_id
    GROUP BY s.id, s.kind, s.provider, s.external_id, s.title
    ORDER BY MAX(e.created_at) DESC
    LIMIT GREATEST(1, LEAST(200, COALESCE(p_limit, 50)));
END;
$$;


--
-- Name: get_training_material_progress_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_material_progress_v1(p_language_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
 principal uuid := (select auth.uid());
 v_now timestamptz := clock_timestamp();
 v_timezone text;
 v_start timestamptz;
 v_end timestamptz;
 v_disabled jsonb;
 v_materials jsonb;
BEGIN
 IF principal IS NULL THEN RETURN jsonb_build_object('error','unauthorized'); END IF;
 IF p_language_code IS NULL OR p_language_code !~ '^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$' THEN
  RETURN jsonb_build_object('error','invalid_material_scope'); END IF;
 v_timezone := private.training_user_timezone_v1(principal);
 SELECT bounds.start_at,bounds.end_at INTO v_start,v_end FROM private.training_study_day_bounds_v1(v_now,v_timezone) bounds;
 SELECT settings.material_preferences->'disabledDictionaryIds' INTO v_disabled
  FROM public.user_settings settings WHERE settings.user_id=principal;
 v_disabled := COALESCE(v_disabled,'[]'::jsonb);
 WITH readable AS (
  SELECT d.id,d.name,d.kind FROM public.dictionaries d
  WHERE d.language_code=p_language_code AND public.can_access_dictionary(principal,d.id,'read')
   AND (d.kind='user' OR NOT (v_disabled ? d.id::text))
 ), entries AS (
  SELECT w.id,w.dictionary_id FROM public.word_entries w
  WHERE w.language_code=p_language_code AND (w.dictionary_id IS NULL OR w.dictionary_id IN (SELECT id FROM readable))
 ), card_state AS (
  SELECT s.entry_id,
   bool_or(s.fsrs_enabled) AS started,
   count(*) FILTER (WHERE s.fsrs_enabled AND NOT s.hidden AND s.next_review_at<v_end
    AND (s.frozen_until IS NULL OR s.frozen_until<=v_now)
    AND NOT EXISTS (SELECT 1 FROM public.user_review_log r WHERE r.user_id=principal AND r.word_id=s.entry_id
     AND r.mode=s.card_type_id AND r.review_type='new' AND r.reviewed_at>=v_start AND r.reviewed_at<v_end)) AS due
  FROM public.user_card_status s JOIN entries e ON e.id=s.entry_id
  WHERE s.user_id=principal GROUP BY s.entry_id
 ), members AS (
  SELECT 'all'::text AS kind,NULL::uuid AS id,NULL::text AS list_type,e.id AS entry_id FROM entries e
  UNION ALL SELECT 'dictionary',e.dictionary_id,NULL,e.id FROM entries e WHERE e.dictionary_id IS NOT NULL
  UNION ALL SELECT DISTINCT 'collection',li.list_id,'curated',li.word_id
   FROM public.word_list_items li JOIN entries e ON e.id=li.word_id
  UNION ALL SELECT DISTINCT 'collection',li.list_id,'user',li.word_id
   FROM public.user_word_list_items li JOIN public.user_word_lists l ON l.id=li.list_id AND l.user_id=principal
   JOIN entries e ON e.id=li.word_id
 ), totals AS (
  SELECT m.kind,m.id,m.list_type,count(*)::integer AS total,
   (count(*) FILTER (WHERE c.started))::integer AS started,COALESCE(sum(c.due),0)::integer AS due
  FROM members m LEFT JOIN card_state c ON c.entry_id=m.entry_id GROUP BY m.kind,m.id,m.list_type
 ), named AS (
  SELECT t.*,COALESCE(r.name,cl.name,ul.name) AS name,r.kind AS dictionary_kind,
   CASE t.kind WHEN 'all' THEN 0 WHEN 'dictionary' THEN 1 ELSE 2 END AS rank,cl.sort_order
  FROM totals t
  LEFT JOIN readable r ON t.kind='dictionary' AND r.id=t.id
  LEFT JOIN public.word_lists cl ON t.kind='collection' AND t.list_type='curated' AND cl.id=t.id
  LEFT JOIN public.user_word_lists ul ON t.kind='collection' AND t.list_type='user' AND ul.id=t.id AND ul.user_id=principal
 )
 SELECT COALESCE(jsonb_agg(jsonb_strip_nulls(jsonb_build_object('kind',n.kind,'id',n.id,'listType',n.list_type,
   'name',n.name,'personal',CASE WHEN n.kind='dictionary' THEN n.dictionary_kind='user' WHEN n.kind='collection' THEN n.list_type='user' END,
   'total',n.total,'started',n.started,'due',n.due))
   ORDER BY n.rank,n.list_type NULLS FIRST,n.sort_order NULLS LAST,lower(n.name),n.id),'[]'::jsonb)
 INTO v_materials FROM (SELECT * FROM named WHERE kind='all' OR name IS NOT NULL
  ORDER BY rank,list_type NULLS FIRST,sort_order NULLS LAST,lower(name),id LIMIT 201) n;
 IF NOT v_materials @> '[{"kind":"all"}]'::jsonb THEN
  v_materials := jsonb_build_array(jsonb_build_object('kind','all','total',0,'started',0,'due',0))||v_materials;
 END IF;
 RETURN jsonb_build_object('languageCode',p_language_code,'materials',v_materials);
END;
$_$;


--
-- Name: FUNCTION get_training_material_progress_v1(p_language_code text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.get_training_material_progress_v1(p_language_code text) IS 'Own review queue and started/total meanings per enabled readable material in one language; read-only.';


--
-- Name: get_training_scenarios(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_scenarios() RETURNS SETOF jsonb
    LANGUAGE sql
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT jsonb_build_object(
        'id', id, 'name_en', name_en, 'name_nl', name_nl,
        'description', description, 'card_modes', card_modes,
        'graduation_threshold', graduation_threshold,
        'enabled', enabled, 'sort_order', sort_order
    )
    FROM training_scenarios
    ORDER BY sort_order, id;
$$;


--
-- Name: get_training_session_active_time_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_session_active_time_v1(p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid := (select auth.uid()); total bigint; receipts bigint;
BEGIN
 IF principal IS NULL THEN RETURN jsonb_build_object('error','unauthorized'); END IF;
 IF p_session_id IS NULL THEN RETURN jsonb_build_object('error','invalid_session'); END IF;
 -- Receipts retain owner identity if the expiring session read model is removed.
 SELECT sum(active_ms),count(*) INTO total,receipts
 FROM private.training_active_time_v1 WHERE user_id=principal AND session_id=p_session_id;
 IF receipts=0 AND NOT EXISTS(SELECT 1 FROM public.training_sessions WHERE id=p_session_id AND user_id=principal) THEN
  RETURN jsonb_build_object('error','session_not_owned');
 END IF;
 RETURN jsonb_build_object('sessionId',p_session_id,'activeMilliseconds',total,'measurementCount',receipts);
END $$;


--
-- Name: get_training_session_plan(uuid, text[], uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_session_plan(p_user_id uuid, p_card_type_ids text[] DEFAULT ARRAY['word-to-definition'::text], p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT 'curated'::text, p_card_filter text DEFAULT 'both'::text, p_training_filter jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  filter_data jsonb := COALESCE(p_training_filter, '{}');
  filtered boolean;
  valid boolean := true;
  planned_new bigint;
  planned_review bigint;
  planned_practice bigint;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF p_card_filter NOT IN ('new', 'review', 'both') THEN
    RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
  END IF;
  IF p_list_id IS NOT NULL THEN
    IF COALESCE(p_list_type, 'curated') = 'user' THEN
      SELECT EXISTS(
        SELECT 1 FROM user_word_lists list
        WHERE list.id = p_list_id AND list.user_id = p_user_id
      ) INTO valid;
    ELSIF COALESCE(p_list_type, 'curated') = 'curated' THEN
      SELECT EXISTS(SELECT 1 FROM word_lists list WHERE list.id = p_list_id) INTO valid;
    ELSE
      valid := false;
    END IF;
  END IF;
  IF NOT valid THEN
    RETURN jsonb_build_object(
      'plannedNew', 0, 'plannedReview', 0, 'plannedPractice', 0,
      'plannedTotal', 0, 'plannedAt', private.training_reference_now_v1()
    );
  END IF;
  filtered := private.training_filter_target_date(filter_data) IS NOT NULL
    OR NULLIF(filter_data ->> 'sourceId', '') IS NOT NULL
    OR NULLIF(trim(filter_data ->> 'sourceKind'), '') IS NOT NULL
    OR NULLIF(trim(filter_data ->> 'externalId'), '') IS NOT NULL;

  -- The plan and selector must share one eligibility relation.  The prior
  -- count-only fast path predates sequential introductions and could promise
  -- reverse/new or later-sense cards that a finite session cannot latch.
  SELECT count(*) FILTER (WHERE queue_source = 'new'),
    count(*) FILTER (WHERE queue_source IN ('learning', 'review')),
    count(*) FILTER (WHERE queue_source = 'practice')
  INTO planned_new, planned_review, planned_practice
  FROM private.training_scheduler_candidates_v2(
    p_user_id, p_card_type_ids, p_list_id, p_list_type,
    p_card_filter, 'auto', ARRAY[]::uuid[], ARRAY[]::text[], filter_data,
    filtered, true
  );

  planned_new := COALESCE(planned_new, 0);
  planned_review := COALESCE(planned_review, 0);
  planned_practice := COALESCE(planned_practice, 0);
  RETURN jsonb_build_object(
    'plannedNew', planned_new,
    'plannedReview', planned_review,
    'plannedPractice', planned_practice,
    'plannedTotal', planned_new + planned_review + planned_practice,
    'plannedAt', private.training_reference_now_v1()
  );
END;
$$;


--
-- Name: get_training_session_plan(uuid, text[], uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_session_plan(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
  v_size text := COALESCE(NULLIF(trim(p_session_size), ''), '10');
  v_requested_total integer;
  v_planned_new integer;
  v_planned_review integer;
  v_planned_total integer;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF p_card_filter NOT IN ('new', 'review', 'both') THEN
    RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
  END IF;
  IF v_size = 'all-due-today' THEN
    v_requested_total := NULL;
  ELSIF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
    RAISE EXCEPTION 'invalid training session size: %', v_size;
  ELSE
    v_requested_total := v_size::integer;
  END IF;

  SELECT count(*) FILTER (WHERE queue_source = 'new')::integer,
    count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer,
    count(*)::integer
  INTO v_planned_new, v_planned_review, v_planned_total
  FROM private.training_session_members_v1(
    p_user_id, p_card_type_ids, p_list_id, p_list_type,
    p_card_filter, COALESCE(p_training_filter, '{}'::jsonb), v_size
  );

  v_planned_new := COALESCE(v_planned_new, 0);
  v_planned_review := COALESCE(v_planned_review, 0);
  v_planned_total := COALESCE(v_planned_total, 0);
  RETURN jsonb_build_object(
    'requestedTotal', COALESCE(v_requested_total, v_planned_total),
    'plannedNew', v_planned_new,
    'plannedReview', v_planned_review,
    'plannedPractice', 0,
    'plannedTotal', v_planned_total,
    'plannedAt', clock_timestamp()
  );
END;
$_$;


--
-- Name: get_training_session_plan(uuid, text[], uuid, text, text, jsonb, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_session_plan(p_user_id uuid, p_card_type_ids text[], p_list_id uuid, p_list_type text, p_card_filter text, p_training_filter jsonb, p_session_size text, p_new_review_ratio integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
  v_size text := COALESCE(NULLIF(trim(p_session_size), ''), '10');
  v_requested_total integer;
  v_planned_new integer;
  v_planned_review integer;
  v_planned_total integer;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  IF p_card_filter NOT IN ('new', 'review', 'both') THEN
    RAISE EXCEPTION 'invalid card filter: %', p_card_filter;
  END IF;
  IF p_card_filter = 'both' AND (
    p_new_review_ratio IS NULL OR p_new_review_ratio NOT BETWEEN 1 AND 5
  ) THEN
    RAISE EXCEPTION 'invalid new/review ratio: %', p_new_review_ratio;
  END IF;
  IF v_size = 'all-due-today' THEN
    v_requested_total := NULL;
  ELSIF v_size !~ '^[1-9][0-9]*$' OR length(v_size) > 9 THEN
    RAISE EXCEPTION 'invalid training session size: %', v_size;
  ELSE
    v_requested_total := v_size::integer;
  END IF;

  SELECT count(*) FILTER (WHERE queue_source = 'new')::integer,
    count(*) FILTER (WHERE queue_source IN ('learning', 'review'))::integer,
    count(*)::integer
  INTO v_planned_new, v_planned_review, v_planned_total
  FROM private.training_session_members_v1(
    p_user_id, p_card_type_ids, p_list_id, p_list_type,
    p_card_filter, private.resolve_training_material_selection_v1(p_user_id,p_list_id,p_list_type,p_training_filter), v_size,
    CASE WHEN p_card_filter = 'both' THEN p_new_review_ratio ELSE 2 END
  );

  v_planned_new := COALESCE(v_planned_new, 0);
  v_planned_review := COALESCE(v_planned_review, 0);
  v_planned_total := COALESCE(v_planned_total, 0);
  RETURN jsonb_build_object(
    'requestedTotal', COALESCE(v_requested_total, v_planned_total),
    'plannedNew', v_planned_new,
    'plannedReview', v_planned_review,
    'plannedPractice', 0,
    'plannedTotal', v_planned_total,
    'plannedAt', clock_timestamp()
  );
END;
$_$;


--
-- Name: get_training_session_snapshot(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_session_snapshot(p_user_id uuid, p_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  v_snapshot jsonb;
  v_run jsonb;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
  END IF;
  PERFORM private.replan_training_session_remainder_v1(p_user_id,p_session_id);
  v_snapshot := private.get_training_session_snapshot_latch_v1(p_user_id, p_session_id);
  IF v_snapshot IS NULL THEN RETURN NULL; END IF;
  v_run := private.training_session_run_response_v1(p_user_id, p_session_id);
  RETURN v_snapshot || jsonb_build_object(
    'planRevision', (SELECT planned_state_revision FROM public.training_sessions WHERE id=p_session_id AND user_id=p_user_id),
    'runStatus', v_run->>'runStatus',
    'runGeneration', v_run->'runGeneration'
  );
END;
$$;


--
-- Name: get_training_stats(uuid, text[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_stats(p_user_id uuid, p_modes text[] DEFAULT ARRAY['word-to-definition'::text], p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT 'curated'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_today_count int;
    v_total_success int;
    v_total_items int;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF p_modes IS NULL OR array_length(p_modes, 1) IS NULL THEN
        p_modes := ARRAY['word-to-definition'];
    END IF;

    IF p_list_id IS NOT NULL AND p_list_type IS NULL THEN
        p_list_type := 'curated';
    END IF;

    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(*) INTO v_today_count
    FROM user_review_log rl
    JOIN accessible_entries ae ON ae.id = rl.word_id
    WHERE rl.user_id = p_user_id
      AND rl.mode = ANY(p_modes)
      AND rl.reviewed_at::date = current_date;

    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(DISTINCT s.entry_id) INTO v_total_success
    FROM user_card_status s
    JOIN accessible_entries ae ON ae.id = s.entry_id
    WHERE s.user_id = p_user_id
      AND s.card_type_id = ANY(p_modes)
      AND s.fsrs_enabled = true;

    WITH accessible_entries AS (
        SELECT w.id
        FROM word_entries w
        WHERE (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'))
          AND (
                (p_list_id IS NULL AND w.is_nt2_2000 = true)
             OR (p_list_id IS NOT NULL AND p_list_type = 'curated' AND EXISTS (
                    SELECT 1 FROM word_list_items li
                    WHERE li.list_id = p_list_id AND li.word_id = w.id
                ))
             OR (p_list_id IS NOT NULL AND p_list_type = 'user' AND EXISTS (
                    SELECT 1 FROM user_word_list_items li
                    JOIN user_word_lists l ON l.id = li.list_id
                    WHERE li.list_id = p_list_id AND li.word_id = w.id AND l.user_id = p_user_id
                ))
          )
    )
    SELECT COUNT(*) INTO v_total_items FROM accessible_entries scope JOIN private.active_word_entries available ON available.id=scope.id;

    RETURN jsonb_build_object(
        'today', v_today_count,
        'totalSuccess', v_total_success,
        'totalItems', v_total_items
    );
END;
$$;


--
-- Name: get_training_stats(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_training_stats(p_user_id uuid, p_mode text, p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT 'curated'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    RETURN get_training_stats(p_user_id, ARRAY[p_mode], p_list_id, p_list_type);
END;
$$;


