--
-- Name: get_user_card_states_for_entries(uuid, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_card_states_for_entries(p_user_id uuid, p_entry_ids uuid[], p_card_type_ids text[] DEFAULT NULL::text[]) RETURNS TABLE(entry_id uuid, card_type_id text, click_count integer, seen_count integer, success_count integer, last_seen_at timestamp with time zone, last_reviewed_at timestamp with time zone, next_review_at timestamp with time zone, hidden boolean, frozen_until timestamp with time zone, in_learning boolean, learning_due_at timestamp with time zone, fsrs_stability numeric, fsrs_difficulty numeric, fsrs_reps integer, fsrs_lapses integer, fsrs_last_grade smallint, fsrs_last_interval numeric, fsrs_params_version text)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF p_entry_ids IS NULL OR array_length(p_entry_ids, 1) IS NULL THEN
        RETURN;
    END IF;

    RETURN QUERY
    SELECT
        s.entry_id,
        s.card_type_id,
        s.click_count,
        s.seen_count,
        s.success_count,
        s.last_seen_at,
        s.last_reviewed_at,
        s.next_review_at,
        s.hidden,
        s.frozen_until,
        s.in_learning,
        s.learning_due_at,
        s.fsrs_stability,
        s.fsrs_difficulty,
        s.fsrs_reps,
        s.fsrs_lapses,
        s.fsrs_last_grade,
        s.fsrs_last_interval,
        s.fsrs_params_version
    FROM user_card_status s
    JOIN word_entries w ON w.id = s.entry_id
    WHERE s.user_id = p_user_id
      AND s.entry_id = ANY(p_entry_ids)
      AND (
        p_card_type_ids IS NULL
        OR array_length(p_card_type_ids, 1) IS NULL
        OR s.card_type_id = ANY(p_card_type_ids)
      )
      AND (w.dictionary_id IS NULL OR can_access_dictionary(p_user_id, w.dictionary_id, 'read'));
END;
$$;


--
-- Name: get_user_list_membership(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_list_membership(p_user_id uuid, p_list_id uuid, p_entry_ids uuid[]) RETURNS uuid[]
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_entry_ids uuid[];
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF NOT EXISTS (
        SELECT 1
        FROM user_word_lists
        WHERE id = p_list_id
          AND user_id = p_user_id
    ) THEN
        RAISE EXCEPTION 'user_list_not_found';
    END IF;

    SELECT COALESCE(array_agg(item.word_id ORDER BY item.word_id), ARRAY[]::uuid[])
    INTO v_entry_ids
    FROM user_word_list_items item
    WHERE item.list_id = p_list_id
      AND item.word_id = ANY(COALESCE(p_entry_ids, ARRAY[]::uuid[]));

    RETURN v_entry_ids;
END;
$$;


--
-- Name: get_user_list_memberships_for_entries(uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_list_memberships_for_entries(p_user_id uuid, p_entry_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    WITH requested(entry_id) AS (
        SELECT DISTINCT unnest(COALESCE(p_entry_ids, ARRAY[]::uuid[]))
    ),
    accessible_requested AS (
        SELECT requested.entry_id
        FROM requested
        JOIN private.active_word_entries entry ON entry.id = requested.entry_id
        WHERE entry.dictionary_id IS NULL
           OR can_access_dictionary(p_user_id, entry.dictionary_id, 'read')
    ),
    active_training_list AS (
        SELECT active_list_id, active_list_type
        FROM user_settings
        WHERE user_id = p_user_id
    ),
    curated_memberships AS (
        SELECT
            item.word_id AS entry_id,
            jsonb_build_object(
                'id', list.id,
                'kind', 'curated',
                'name', list.name,
                'description', list.description,
                'primary_language_code', list.primary_language_code,
                'item_count', (
                    SELECT COUNT(*)::int
                    FROM word_list_items count_item
                    WHERE count_item.list_id = list.id
                ),
                'editable', false,
                'read_only_reason', 'curated',
                'is_active_training_list',
                    COALESCE(active.active_list_type = 'curated'
                        AND active.active_list_id = list.id, false)
            ) AS list_payload
        FROM accessible_requested
        JOIN word_list_items item ON item.word_id = accessible_requested.entry_id
        JOIN word_lists list ON list.id = item.list_id
        LEFT JOIN active_training_list active ON true
        WHERE COALESCE(list.slug, '') <> (public.dictionary_source_settings_v1()->>'fullListSlug')
          AND lower(btrim(list.name)) <> lower(public.dictionary_source_settings_v1()->>'fullListName')
    ),
    user_memberships AS (
        SELECT
            item.word_id AS entry_id,
            jsonb_build_object(
                'id', list.id,
                'kind', 'user',
                'name', list.name,
                'description', list.description,
                'primary_language_code', list.primary_language_code,
                'item_count', (
                    SELECT COUNT(*)::int
                    FROM user_word_list_items count_item
                    WHERE count_item.list_id = list.id
                ),
                'editable', true,
                'read_only_reason', null,
                'is_active_training_list',
                    COALESCE(active.active_list_type = 'user'
                        AND active.active_list_id = list.id, false)
            ) AS list_payload
        FROM accessible_requested
        JOIN user_word_list_items item ON item.word_id = accessible_requested.entry_id
        JOIN user_word_lists list ON list.id = item.list_id
        LEFT JOIN active_training_list active ON true
        WHERE list.user_id = p_user_id
    ),
    memberships AS (
        SELECT entry_id, list_payload FROM curated_memberships
        UNION ALL
        SELECT entry_id, list_payload FROM user_memberships
    ),
    grouped AS (
        SELECT
            entry_id,
            jsonb_agg(
                list_payload
                ORDER BY list_payload->>'kind', list_payload->>'name'
            ) AS lists
        FROM memberships
        GROUP BY entry_id
    )
    SELECT COALESCE(
        jsonb_agg(
            jsonb_build_object(
                'entry_id', entry_id,
                'lists', lists
            )
            ORDER BY entry_id
        ),
        '[]'::jsonb
    )
    INTO v_result
    FROM grouped;

    RETURN v_result;
END;
$$;


--
-- Name: get_user_tier(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_user_tier(p_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_tier text;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT COALESCE(subscription_tier, 'free')
    INTO v_tier
    FROM user_settings
    WHERE user_id = p_user_id;

    RETURN COALESCE(v_tier, 'free');
END;
$$;


--
-- Name: get_word_list_summary(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_word_list_summary(p_user_id uuid, p_list_id uuid, p_list_type text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE original jsonb;
BEGIN
 IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
  RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user'; END IF;
 original:=private.get_word_list_summary_owner_base_v1(p_user_id,p_list_id,p_list_type);
 IF original IS NOT NULL OR p_list_type IS DISTINCT FROM 'user' THEN RETURN original; END IF;
 RETURN (
  SELECT jsonb_build_object('id',list.id,'name',list.name,'language_code',list.language_code,
   'primary_language_code',list.primary_language_code,'created_at',list.created_at,
   'ownership','received','editable',false,'is_mixed_language',counts.language_count>1,
   'user_word_list_items',jsonb_build_array(jsonb_build_object('count',counts.item_count,
    'available_count',counts.item_count,'unavailable_source_count',0)))
  FROM public.user_word_lists list
  CROSS JOIN LATERAL (
   SELECT count(*)::integer AS item_count,count(DISTINCT entry.language_code)::integer AS language_count
   FROM public.user_word_list_items item JOIN private.active_word_entries entry ON entry.id=item.word_id
   WHERE item.list_id=list.id AND private.entry_access_v1(p_user_id,entry.id,'train')
  ) counts
  WHERE list.id=p_list_id AND list.user_id<>p_user_id AND EXISTS(
   SELECT 1 FROM private.live_collection_sharing_subscriptions_v1 scope
   WHERE scope.user_id=p_user_id AND scope.collection_id=list.id)
 );
END;
$$;


--
-- Name: handle_card_review(uuid, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.handle_card_review(p_user_id uuid, p_entry_id uuid, p_card_type_id text, p_result text, p_turn_id uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_dictionary_id uuid;
    v_status user_card_status%rowtype;
    v_grade smallint;
    v_params numeric[];
    v_target numeric;
    v_compute jsonb;
    v_review_type text;
    v_scheduled timestamptz;
    v_interval numeric;
    v_meta jsonb;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT dictionary_id INTO v_dictionary_id
    FROM private.active_word_entries
    WHERE id = p_entry_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'word entry not found';
    END IF;

    PERFORM private.lock_shared_learning_source_v1(p_user_id,p_entry_id);
    IF NOT private.entry_access_v1(p_user_id,p_entry_id,'train') THEN
        RAISE EXCEPTION 'dictionary access denied';
    END IF;

    IF p_card_type_id IN ('word-to-definition','definition-to-word') THEN
      PERFORM pg_advisory_xact_lock(hashtext('training-headword:'||p_user_id::text||':'||
        private.training_headword_group_v1(p_entry_id)::text));
    END IF;
    PERFORM pg_advisory_xact_lock(hashtext('training-pair:' || p_user_id::text || ':' ||
        private.training_pair_key_v1('meaning', p_entry_id, NULL, NULL, p_card_type_id)));

    -- Reject before the consumed-turn shortcut; hide is no longer an action.
    IF p_result = 'hide' THEN
        RAISE EXCEPTION 'legacy_hide_disabled' USING ERRCODE = '22023';
    END IF;

    IF p_turn_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtext(p_turn_id::text));

        IF EXISTS (
            SELECT 1
            FROM user_review_log
            WHERE turn_id = p_turn_id
        ) THEN
            RETURN;
        END IF;
    END IF;

    PERFORM private.require_training_pair_available_v1(
        p_user_id, 'meaning', p_entry_id, NULL, NULL, p_card_type_id);

    IF p_result = 'freeze' THEN
        INSERT INTO user_card_status (
            user_id, entry_id, card_type_id, frozen_until, last_result, last_seen_at
        )
        VALUES (p_user_id, p_entry_id, p_card_type_id, private.training_reference_now_v1() + interval '1 day', 'freeze', private.training_reference_now_v1())
        ON CONFLICT (user_id, entry_id, card_type_id) DO UPDATE
        SET frozen_until = private.training_reference_now_v1() + interval '1 day',
            last_result = 'freeze',
            last_seen_at = private.training_reference_now_v1();

        INSERT INTO user_events (user_id, word_id, mode, event_type)
        VALUES (p_user_id, p_entry_id, p_card_type_id, 'freeze');
        RETURN;
    END IF;

    v_grade := CASE p_result
        WHEN 'fail' THEN 1
        WHEN 'hard' THEN 2
        WHEN 'success' THEN 3
        WHEN 'easy' THEN 4
        ELSE 1
    END;

    SELECT * INTO v_status
    FROM user_card_status
    WHERE user_id = p_user_id
      AND entry_id = p_entry_id
      AND card_type_id = p_card_type_id;

    IF p_turn_id IS NULL
        AND v_status.last_reviewed_at IS NOT NULL
        AND (private.training_reference_now_v1() - v_status.last_reviewed_at) < interval '10 seconds' THEN
        RETURN;
    END IF;

    v_params := fsrs6_parameters();
    SELECT COALESCE(target_retention, 0.9) INTO v_target
    FROM user_settings
    WHERE user_id = p_user_id;

    v_review_type := CASE WHEN v_status.fsrs_stability IS NULL THEN 'new' ELSE 'review' END;
    v_scheduled := v_status.next_review_at;

    v_compute := fsrs6_compute(
        v_status.fsrs_stability,
        v_status.fsrs_difficulty,
        v_status.last_reviewed_at,
        v_grade,
        v_target,
        v_status.fsrs_reps,
        v_status.fsrs_lapses,
        v_params
    );

    v_interval := (v_compute->>'interval')::numeric;
    v_meta := jsonb_build_object(
        'elapsed_days', (v_compute->>'elapsed')::numeric,
        'retrievability', (v_compute->>'retrievability')::numeric,
        'same_day', (v_compute->>'same_day')::boolean,
        'last_reviewed_at_before', v_status.last_reviewed_at
    );

    INSERT INTO user_card_status (
        user_id, entry_id, card_type_id,
        fsrs_stability, fsrs_difficulty, fsrs_reps, fsrs_lapses, fsrs_last_grade,
        fsrs_last_interval, fsrs_target_retention, fsrs_params_version, fsrs_enabled,
        next_review_at, last_result, last_seen_at, last_reviewed_at,
        click_count, seen_count
    )
    VALUES (
        p_user_id, p_entry_id, p_card_type_id,
        (v_compute->>'stability')::numeric,
        (v_compute->>'difficulty')::numeric,
        (v_compute->>'reps')::int,
        (v_compute->>'lapses')::int,
        v_grade,
        v_interval,
        v_target,
        'fsrs-6-default',
        true,
        private.training_reference_now_v1() + (v_interval || ' days')::interval,
        p_result,
        private.training_reference_now_v1(),
        private.training_reference_now_v1(),
        COALESCE(v_status.click_count, 0),
        COALESCE(v_status.seen_count, 0) + 1
    )
    ON CONFLICT (user_id, entry_id, card_type_id) DO UPDATE
    SET fsrs_stability = excluded.fsrs_stability,
        fsrs_difficulty = excluded.fsrs_difficulty,
        fsrs_reps = excluded.fsrs_reps,
        fsrs_lapses = excluded.fsrs_lapses,
        fsrs_last_grade = excluded.fsrs_last_grade,
        fsrs_last_interval = excluded.fsrs_last_interval,
        fsrs_target_retention = excluded.fsrs_target_retention,
        fsrs_params_version = excluded.fsrs_params_version,
        fsrs_enabled = true,
        next_review_at = excluded.next_review_at,
        last_result = excluded.last_result,
        last_seen_at = excluded.last_seen_at,
        last_reviewed_at = excluded.last_reviewed_at,
        seen_count = user_card_status.seen_count + 1;

    INSERT INTO user_review_log (
        user_id, word_id, mode, turn_id, grade, review_type,
        scheduled_at, reviewed_at,
        stability_before, difficulty_before,
        stability_after, difficulty_after,
        interval_after, params_version, metadata
    ) VALUES (
        p_user_id, p_entry_id, p_card_type_id, p_turn_id, v_grade, v_review_type,
        v_scheduled, private.training_reference_now_v1(),
        v_status.fsrs_stability, v_status.fsrs_difficulty,
        (v_compute->>'stability')::numeric,
        (v_compute->>'difficulty')::numeric,
        v_interval,
        'fsrs-6-default',
        v_meta
    );

    INSERT INTO user_events (user_id, word_id, mode, event_type)
    VALUES (p_user_id, p_entry_id, p_card_type_id, 'review_' || p_result);
END;
$$;


--
-- Name: heartbeat_dictionary_translation_job_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.heartbeat_dictionary_translation_job_v1(p_job_id uuid, p_lease_token uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE v_job public.dictionary_translation_jobs;
BEGIN
  SELECT * INTO v_job FROM public.dictionary_translation_jobs
    WHERE id = p_job_id FOR UPDATE;
  -- Check the clock after acquiring the row lock: waiting for a transaction
  -- must never revive a lease that expired during that wait.
  IF NOT FOUND OR v_job.status <> 'running' OR v_job.lease_token IS DISTINCT FROM p_lease_token
      OR v_job.lease_expires_at <= clock_timestamp() THEN RETURN false; END IF;
  UPDATE public.dictionary_translation_jobs SET lease_expires_at = clock_timestamp() + interval '60 seconds',
    updated_at = clock_timestamp() WHERE id = p_job_id;
  RETURN true;
END $$;


--
-- Name: is_valid_account_material_preferences_v1(jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.is_valid_account_material_preferences_v1(p_document jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog', 'pg_temp'
    AS $_$
DECLARE v_item jsonb; v_codes text[] := ARRAY[]::text[]; v_ids text[] := ARRAY[]::text[]; v_active integer := 0;
BEGIN
  IF p_document IS NULL OR jsonb_typeof(p_document) <> 'object'
    OR p_document->'schemaVersion' IS DISTINCT FROM '1'::jsonb
    OR jsonb_typeof(p_document->'learningLanguages') IS DISTINCT FROM 'array'
    OR jsonb_typeof(p_document->'disabledDictionaryIds') IS DISTINCT FROM 'array'
    OR (p_document - ARRAY['schemaVersion','learningLanguages','disabledDictionaryIds']) <> '{}'::jsonb
    OR octet_length(p_document::text) > 65536 THEN RETURN false; END IF;
  IF jsonb_array_length(p_document->'learningLanguages') > 100
    OR jsonb_array_length(p_document->'disabledDictionaryIds') > 1000 THEN RETURN false; END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_document->'learningLanguages') LOOP
    IF jsonb_typeof(v_item) <> 'object'
      OR jsonb_typeof(v_item->'code') IS DISTINCT FROM 'string'
      OR jsonb_typeof(v_item->'paused') IS DISTINCT FROM 'boolean'
      OR (v_item - ARRAY['code','paused']) <> '{}'::jsonb
      OR length(v_item->>'code') > 35 OR (v_item->>'code') !~ '^[a-z]{2,3}(-[a-z0-9]{2,8})*$'
      OR (v_item->>'code') = ANY(v_codes) THEN RETURN false; END IF;
    v_codes := array_append(v_codes, v_item->>'code');
    IF v_item->'paused' = 'false'::jsonb THEN v_active := v_active + 1; END IF;
  END LOOP;
  -- Empty is the backwards-compatible implicit language catalog. Once a
  -- learner configures an explicit ordered list, retain one active language.
  IF cardinality(v_codes) > 0 AND v_active = 0 THEN RETURN false; END IF;
  FOR v_item IN SELECT value FROM jsonb_array_elements(p_document->'disabledDictionaryIds') LOOP
    IF jsonb_typeof(v_item) <> 'string'
      OR (v_item #>> '{}') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
      OR (v_item #>> '{}') = ANY(v_ids) THEN RETURN false; END IF;
    v_ids := array_append(v_ids, v_item #>> '{}');
  END LOOP;
  RETURN true;
END;
$_$;


--
-- Name: lookup_dictionary_entries_v2(text, text, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_dictionary_entries_v2(p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_raw_query text;
    v_query text;
    v_query_unaccent text;
    v_language_code text := NULLIF(trim(COALESCE(p_language_code, '')), '');
    v_dictionary_ids uuid[] := COALESCE(p_dictionary_ids, ARRAY[]::uuid[]);
    v_resolved_entry_id uuid;
    v_resolved_headword text;
    v_resolved_language_code text;
    v_resolved_by text;
    v_matched_text text;
    v_items jsonb;
BEGIN
    v_user_id := (select auth.uid());
    IF v_user_id IS NULL THEN
        RETURN jsonb_build_object('query', p_query, 'resolution', NULL, 'items', '[]'::jsonb);
    END IF;

    v_raw_query := NULLIF(trim(COALESCE(p_query, '')), '');
    IF v_raw_query IS NULL THEN
        RETURN jsonb_build_object('query', p_query, 'resolution', NULL, 'items', '[]'::jsonb);
    END IF;

    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);

    WITH accessible_dictionaries AS MATERIALIZED (
        SELECT d.id, d.kind, d.owner_user_id
        FROM dictionaries d
        WHERE can_access_dictionary(v_user_id, d.id, 'read')
    ),
    visible_docs AS MATERIALIZED (
        SELECT
            s.*,
            ad.kind AS dictionary_kind,
            ad.owner_user_id
        FROM dictionary_search_documents s
        LEFT JOIN accessible_dictionaries ad ON ad.id = s.dictionary_id
        WHERE (s.dictionary_id IS NULL OR ad.id IS NOT NULL)
          AND (v_language_code IS NULL OR s.language_code = v_language_code)
          AND (array_length(v_dictionary_ids, 1) IS NULL OR s.dictionary_id = ANY(v_dictionary_ids))
    ),
    candidates AS (
        SELECT
            entry_id,
            headword,
            language_code,
            'exact-headword'::text AS resolved_by,
            headword AS matched_text,
            CASE WHEN headword = v_raw_query THEN 0 ELSE 1 END AS rank
        FROM visible_docs
        WHERE normalized_headword = v_query

        UNION ALL

        SELECT
            entry_id,
            headword,
            language_code,
            'normalized-headword',
            headword,
            2
        FROM visible_docs
        WHERE normalized_headword_unaccent = v_query_unaccent

        UNION ALL

        SELECT
            d.entry_id,
            d.headword,
            d.language_code,
            'word-form',
            f.display_text,
            3
        FROM visible_docs d
        JOIN dictionary_search_fields f ON f.entry_id = d.entry_id
        WHERE f.field_group = 'form'
          AND (
            f.normalized_text = v_query
            OR f.normalized_text_unaccent = v_query_unaccent
          )
    )
    SELECT entry_id, headword, language_code, resolved_by, matched_text
    INTO v_resolved_entry_id, v_resolved_headword, v_resolved_language_code, v_resolved_by, v_matched_text
    FROM candidates
    ORDER BY rank ASC, lower(headword) ASC
    LIMIT 1;

    IF v_resolved_entry_id IS NULL THEN
        RETURN jsonb_build_object(
            'query', v_raw_query,
            'resolution', jsonb_build_object(
                'resolved_by', NULL,
                'normalized', v_query,
                'normalized_unaccent', v_query_unaccent
            ),
            'items', '[]'::jsonb
        );
    END IF;

    WITH accessible_dictionaries AS MATERIALIZED (
        SELECT d.id, d.name, d.slug, d.kind, d.owner_user_id
        FROM dictionaries d
        WHERE can_access_dictionary(v_user_id, d.id, 'read')
    ),
    candidates AS (
        SELECT
            w.*,
            d.name AS dictionary_name,
            d.slug AS dictionary_slug,
            d.kind AS dictionary_kind,
            d.owner_user_id,
            COUNT(*) OVER (
                PARTITION BY w.dictionary_id, w.language_code, w.headword
            ) AS meanings_count,
            CASE
                WHEN d.kind = 'user' AND d.owner_user_id = v_user_id THEN 0
                WHEN d.kind = 'curated' THEN 1
                ELSE 2
            END AS dictionary_rank
        FROM private.active_word_entries w
        JOIN dictionary_search_documents s ON s.entry_id = w.id
        LEFT JOIN accessible_dictionaries d ON d.id = w.dictionary_id
        WHERE s.language_code = v_resolved_language_code
          AND s.normalized_headword = normalize_dictionary_search_text(v_resolved_headword)
          AND (w.dictionary_id IS NULL OR d.id IS NOT NULL)
          AND (array_length(v_dictionary_ids, 1) IS NULL OR w.dictionary_id = ANY(v_dictionary_ids))
    ),
    payloads AS (
        SELECT jsonb_strip_nulls(jsonb_build_object(
            'id', id,
            'dictionary_id', dictionary_id,
            'dictionary_name', dictionary_name,
            'dictionary_slug', dictionary_slug,
            'dictionary_kind', dictionary_kind,
            'language_code', language_code,
            'headword', headword,
            'meaning_id', meaning_id,
            'part_of_speech', part_of_speech,
            'gender', gender,
            'raw', raw,
            'is_nt2_2000', is_nt2_2000,
            'meanings_count', COALESCE(meanings_count, 1)
        )) AS payload,
        dictionary_rank,
        meaning_id
        FROM candidates
    )
    SELECT COALESCE(jsonb_agg(payload ORDER BY dictionary_rank, meaning_id), '[]'::jsonb)
    INTO v_items
    FROM payloads;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'resolution', jsonb_build_object(
            'resolved_by', v_resolved_by,
            'normalized', v_query,
            'normalized_unaccent', v_query_unaccent,
            'resolved_headword', v_resolved_headword,
            'matched_text', v_matched_text
        ),
        'items', COALESCE(v_items, '[]'::jsonb)
    );
END;
$$;


--
-- Name: lookup_dictionary_entries_v3(text, text, uuid[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_dictionary_entries_v3(p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_user_id uuid;
    v_raw_query text;
    v_query text;
    v_query_unaccent text;
    v_items jsonb;
    v_total int;
    v_resolved_by text;
BEGIN
    v_user_id := (select auth.uid());
    v_raw_query := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);

    IF v_user_id IS NULL OR v_raw_query IS NULL THEN
        RETURN jsonb_build_object(
            'query', p_query,
            'resolution', jsonb_build_object(
                'resolved_by', NULL,
                'normalized', v_query,
                'normalized_unaccent', v_query_unaccent
            ),
            'items', '[]'::jsonb,
            'total', 0
        );
    END IF;

    WITH resolved AS MATERIALIZED (
        SELECT *
        FROM private.resolve_dictionary_lookup_candidates_v2(
            v_user_id,
            v_raw_query,
            p_language_code,
            p_dictionary_ids,
            p_limit
        )
    ),
    hydrated AS (
        SELECT
            w.*,
            r.resolved_by,
            r.matched_text,
            r.tier_rank,
            r.match_rank,
            d.name AS dictionary_name,
            d.slug AS dictionary_slug,
            d.kind AS dictionary_kind,
            d.visibility AS dictionary_visibility,
            d.owner_user_id AS dictionary_owner_user_id,
            d.is_editable AS dictionary_is_editable,
            d.schema_key AS dictionary_schema_key,
            d.schema_version AS dictionary_schema_version,
            d.language_code AS dictionary_language_code,
            COUNT(*) OVER (
                PARTITION BY w.dictionary_id, w.language_code, w.headword
            ) AS meanings_count,
            CASE
                WHEN d.kind = 'user' AND d.owner_user_id = v_user_id THEN 0
                WHEN d.kind = 'curated' THEN 1
                ELSE 2
            END AS dictionary_rank
        FROM resolved r
        JOIN private.active_word_entries w ON w.id = r.entry_id
        JOIN dictionaries d ON d.id = w.dictionary_id
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', h.id,
                'dictionary_id', h.dictionary_id,
                'language_code', h.language_code,
                'headword', h.headword,
                'meaning_id', h.meaning_id,
                'part_of_speech', h.part_of_speech,
                'gender', h.gender,
                'raw', h.raw,
                'is_nt2_2000', h.is_nt2_2000,
                'meanings_count', COALESCE(h.meanings_count, 1),
                'dictionary', jsonb_build_object(
                    'id', h.dictionary_id,
                    'language_code', h.dictionary_language_code,
                    'slug', h.dictionary_slug,
                    'name', h.dictionary_name,
                    'kind', h.dictionary_kind,
                    'visibility', h.dictionary_visibility,
                    'owner_user_id', h.dictionary_owner_user_id,
                    'is_editable', h.dictionary_is_editable,
                    'schema_key', h.dictionary_schema_key,
                    'schema_version', h.dictionary_schema_version
                ),
                'dictionary_name', h.dictionary_name,
                'dictionary_slug', h.dictionary_slug,
                'dictionary_kind', h.dictionary_kind,
                'search_match_group', h.resolved_by,
                'search_matched_text', h.matched_text
            )) AS payload,
            h.tier_rank,
            h.match_rank,
            h.dictionary_rank,
            h.resolved_by,
            normalize_dictionary_search_text(h.headword) AS sort_headword,
            h.meaning_id,
            h.id
        FROM hydrated h
    )
    SELECT
        COUNT(*)::int,
        COALESCE(
            jsonb_agg(
                payload
                ORDER BY tier_rank, match_rank, dictionary_rank, sort_headword, meaning_id, id
            ),
            '[]'::jsonb
        ),
        (array_agg(resolved_by ORDER BY tier_rank, match_rank, dictionary_rank, sort_headword, meaning_id, id))[1]
    INTO v_total, v_items, v_resolved_by
    FROM payloads;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'resolution', jsonb_build_object(
            'resolved_by', v_resolved_by,
            'normalized', v_query,
            'normalized_unaccent', v_query_unaccent
        ),
        'items', COALESCE(v_items, '[]'::jsonb),
        'total', COALESCE(v_total, 0)
    );
END;
$$;


--
-- Name: lookup_platform_v2_entries(uuid, boolean, text, text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_platform_v2_entries(p_user_id uuid, p_catalog boolean, p_query text, p_language_code text DEFAULT NULL::text, p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_payload jsonb;
BEGIN
    v_payload := private.lookup_platform_v2_entries_base_v1(
        p_user_id,
        p_catalog,
        p_query,
        p_language_code,
        p_cursor,
        p_group_limit,
        p_group_entry_bound
    );

    RETURN private.attach_platform_v2_presentation_identity_v1(
        v_payload,
        p_user_id,
        p_catalog
    );
END;
$$;


--
-- Name: lookup_platform_v2_library_entries(uuid, text, text, uuid[], text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_platform_v2_library_entries(p_user_id uuid, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  preferences jsonb;
  allowed_codes jsonb;
  selection jsonb;
  dictionary_ids jsonb;
  payload jsonb;
BEGIN
  IF p_user_id IS NULL THEN RETURN jsonb_build_object('error','invalid_principal'); END IF;
  IF cardinality(p_dictionary_ids)>100 OR array_position(p_dictionary_ids,NULL) IS NOT NULL THEN
    RETURN jsonb_build_object('error','invalid_dictionary_scope');
  END IF;
  SELECT material_preferences INTO preferences FROM public.user_settings WHERE user_id=p_user_id;
  preferences := COALESCE(preferences,'{"schemaVersion":1,"learningLanguages":[],"disabledDictionaryIds":[]}'::jsonb);
  IF jsonb_array_length(preferences->'learningLanguages')=0 THEN
    allowed_codes := 'null'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(item->>'code' ORDER BY item->>'code'),'[]'::jsonb)
      INTO allowed_codes FROM jsonb_array_elements(preferences->'learningLanguages') item
      WHERE item->'paused'='false'::jsonb;
  END IF;
  IF p_dictionary_ids IS NULL THEN dictionary_ids := 'null'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(id ORDER BY id),'[]'::jsonb) INTO dictionary_ids
      FROM (SELECT DISTINCT unnest(p_dictionary_ids) id) canonical;
  END IF;
  selection := jsonb_build_object('materialSelection',jsonb_build_object(
    'schemaVersion',1,'allowedLanguageCodes',allowed_codes,
    'disabledDictionaryIds',COALESCE(preferences->'disabledDictionaryIds','[]'::jsonb)),
    'dictionaryIds',dictionary_ids);
  payload := private.lookup_platform_v2_library_entries_base_v1(
    p_user_id,false,p_query,p_language_code,p_cursor,p_group_limit,p_group_entry_bound,selection);
  RETURN private.attach_platform_v2_presentation_identity_v1(payload,p_user_id,false);
END;
$$;


--
-- Name: lookup_platform_v2_library_filtered_entries(uuid, text, text, uuid[], text, integer, integer, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_platform_v2_library_filtered_entries(p_user_id uuid, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50, p_filters jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE
  preferences jsonb;
  allowed_codes jsonb;
  selection jsonb;
  dictionary_ids jsonb;
  payload jsonb;
  parts jsonb;
  article text;
BEGIN
  IF p_user_id IS NULL THEN RETURN jsonb_build_object('error','invalid_principal'); END IF;
  IF cardinality(p_dictionary_ids)>100 OR array_position(p_dictionary_ids,NULL) IS NOT NULL THEN
    RETURN jsonb_build_object('error','invalid_dictionary_scope');
  END IF;
  IF p_filters IS NULL OR jsonb_typeof(p_filters)<>'object'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_filters) key WHERE key NOT IN ('parts','article')) THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  parts := COALESCE(p_filters->'parts','[]'::jsonb);
  IF jsonb_typeof(parts)<>'array' THEN RETURN jsonb_build_object('error','invalid_library_filters'); END IF;
  IF jsonb_array_length(parts)>10 OR EXISTS(SELECT 1 FROM jsonb_array_elements(parts) item
    WHERE jsonb_typeof(item)<>'string' OR item #>> '{}' NOT IN
      ('noun','verb','adjective','adverb','pronoun','preposition','conjunction','numeral','article','interjection')) THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  IF p_filters ? 'article' AND p_filters->'article'<>'null'::jsonb AND
    (jsonb_typeof(p_filters->'article')<>'string' OR p_filters->>'article' NOT IN ('de','het')) THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  article := p_filters->>'article';
  IF article IS NOT NULL AND NOT (parts ? 'noun') THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  SELECT COALESCE(jsonb_agg(part ORDER BY part),'[]'::jsonb) INTO parts
    FROM (SELECT DISTINCT value AS part FROM jsonb_array_elements_text(parts)) canonical;
  SELECT material_preferences INTO preferences FROM public.user_settings WHERE user_id=p_user_id;
  preferences := COALESCE(preferences,'{"schemaVersion":1,"learningLanguages":[],"disabledDictionaryIds":[]}'::jsonb);
  IF jsonb_array_length(preferences->'learningLanguages')=0 THEN
    allowed_codes := 'null'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(item->>'code' ORDER BY item->>'code'),'[]'::jsonb)
      INTO allowed_codes FROM jsonb_array_elements(preferences->'learningLanguages') item
      WHERE item->'paused'='false'::jsonb;
  END IF;
  IF p_dictionary_ids IS NULL THEN dictionary_ids := 'null'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(id ORDER BY id),'[]'::jsonb) INTO dictionary_ids
      FROM (SELECT DISTINCT unnest(p_dictionary_ids) id) canonical;
  END IF;
  selection := jsonb_build_object('materialSelection',jsonb_build_object(
    'schemaVersion',1,'allowedLanguageCodes',allowed_codes,
    'disabledDictionaryIds',COALESCE(preferences->'disabledDictionaryIds','[]'::jsonb)),
    'dictionaryIds',dictionary_ids,'parts',parts,'article',article);
  payload := private.lookup_platform_v2_library_filtered_entries_base_v1(
    p_user_id,false,p_query,p_language_code,p_cursor,p_group_limit,p_group_entry_bound,selection);
  RETURN private.attach_platform_v2_presentation_identity_v1(payload,p_user_id,false);
END;
$$;


--
-- Name: lookup_platform_v2_library_material_entries(uuid, text, text, uuid[], text, integer, integer, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_platform_v2_library_material_entries(p_user_id uuid, p_query text, p_language_code text DEFAULT NULL::text, p_dictionary_ids uuid[] DEFAULT NULL::uuid[], p_cursor text DEFAULT NULL::text, p_group_limit integer DEFAULT 10, p_group_entry_bound integer DEFAULT 50, p_filters jsonb DEFAULT '{}'::jsonb, p_material jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
  preferences jsonb;
  allowed_codes jsonb;
  selection jsonb;
  dictionary_ids jsonb;
  payload jsonb;
  parts jsonb;
  article text;
BEGIN
  
  IF p_material IS NULL OR jsonb_typeof(p_material)<>'object' THEN
    RETURN jsonb_build_object('error','invalid_material_scope');
  END IF;
  IF p_material->>'kind' IS NULL OR p_material->>'kind' NOT IN ('collection','label')
    OR p_material->>'id' IS NULL OR p_material->>'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_material) key WHERE key NOT IN ('kind','id','collectionType'))
    OR (p_material->>'kind'='label' AND p_material ? 'collectionType')
    OR (p_material->>'kind'='collection' AND (p_material->>'collectionType' IS NULL OR p_material->>'collectionType' NOT IN ('user','curated')))
    OR p_dictionary_ids IS NOT NULL THEN
    RETURN jsonb_build_object('error','invalid_material_scope');
  END IF;
  IF NOT (
    (p_material->>'kind'='label' AND EXISTS(SELECT 1 FROM private.collection_labels WHERE user_id=p_user_id AND id=(p_material->>'id')::uuid))
    OR (p_material->>'kind'='collection' AND p_material->>'collectionType'='user' AND (EXISTS(SELECT 1 FROM public.user_word_lists WHERE user_id=p_user_id AND id=(p_material->>'id')::uuid)
    OR EXISTS(SELECT 1 FROM private.shared_collection_ids_v1(p_user_id) shared WHERE shared.collection_id=(p_material->>'id')::uuid)))
    OR (p_material->>'kind'='collection' AND p_material->>'collectionType'='curated' AND EXISTS(SELECT 1 FROM public.word_lists WHERE id=(p_material->>'id')::uuid))
  ) THEN RETURN jsonb_build_object('error','material_not_accessible'); END IF;
  IF p_user_id IS NULL THEN RETURN jsonb_build_object('error','invalid_principal'); END IF;
  IF cardinality(p_dictionary_ids)>100 OR array_position(p_dictionary_ids,NULL) IS NOT NULL THEN
    RETURN jsonb_build_object('error','invalid_dictionary_scope');
  END IF;
  IF p_filters IS NULL OR jsonb_typeof(p_filters)<>'object'
    OR EXISTS(SELECT 1 FROM jsonb_object_keys(p_filters) key WHERE key NOT IN ('parts','article')) THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  parts := COALESCE(p_filters->'parts','[]'::jsonb);
  IF jsonb_typeof(parts)<>'array' THEN RETURN jsonb_build_object('error','invalid_library_filters'); END IF;
  IF jsonb_array_length(parts)>10 OR EXISTS(SELECT 1 FROM jsonb_array_elements(parts) item
    WHERE jsonb_typeof(item)<>'string' OR item #>> '{}' NOT IN
      ('noun','verb','adjective','adverb','pronoun','preposition','conjunction','numeral','article','interjection')) THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  IF p_filters ? 'article' AND p_filters->'article'<>'null'::jsonb AND
    (jsonb_typeof(p_filters->'article')<>'string' OR p_filters->>'article' NOT IN ('de','het')) THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  article := p_filters->>'article';
  IF article IS NOT NULL AND NOT (parts ? 'noun') THEN
    RETURN jsonb_build_object('error','invalid_library_filters');
  END IF;
  SELECT COALESCE(jsonb_agg(part ORDER BY part),'[]'::jsonb) INTO parts
    FROM (SELECT DISTINCT value AS part FROM jsonb_array_elements_text(parts)) canonical;
  SELECT material_preferences INTO preferences FROM public.user_settings WHERE user_id=p_user_id;
  preferences := COALESCE(preferences,'{"schemaVersion":1,"learningLanguages":[],"disabledDictionaryIds":[]}'::jsonb);
  IF jsonb_array_length(preferences->'learningLanguages')=0 THEN
    allowed_codes := 'null'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(item->>'code' ORDER BY item->>'code'),'[]'::jsonb)
      INTO allowed_codes FROM jsonb_array_elements(preferences->'learningLanguages') item
      WHERE item->'paused'='false'::jsonb;
  END IF;
  IF p_dictionary_ids IS NULL THEN dictionary_ids := 'null'::jsonb;
  ELSE
    SELECT COALESCE(jsonb_agg(id ORDER BY id),'[]'::jsonb) INTO dictionary_ids
      FROM (SELECT DISTINCT unnest(p_dictionary_ids) id) canonical;
  END IF;
  selection := jsonb_build_object('materialSelection',jsonb_build_object(
    'schemaVersion',1,'allowedLanguageCodes',allowed_codes,
    'disabledDictionaryIds',COALESCE(preferences->'disabledDictionaryIds','[]'::jsonb)),
    'dictionaryIds',dictionary_ids,'parts',parts,'article',article,'material',p_material);
  
  -- Bind cursors to the exact live membership set; additions/removals cannot silently skip pages.
  selection := selection || jsonb_build_object('materialRevision', (
    SELECT md5(COALESCE(string_agg(entry_id::text,',' ORDER BY entry_id),''))
    FROM private.library_material_entry_ids_v1(p_user_id,p_material)
  ));
  payload := private.lookup_platform_v2_library_material_filtered_entries_base_v1(
    p_user_id,false,p_query,p_language_code,p_cursor,p_group_limit,p_group_entry_bound,selection);
  
  IF NOT (payload ? 'error') THEN
    payload := jsonb_set(payload,'{page,unavailableEntryCount}', to_jsonb((
      SELECT count(*)::integer FROM private.library_material_entry_ids_v1(p_user_id,p_material) member
      JOIN public.word_entries entry ON entry.id=member.entry_id
      WHERE (p_language_code IS NULL OR entry.language_code=p_language_code)
        AND entry.id NOT IN (SELECT entry_id FROM private.readable_material_entry_ids_v1(p_user_id,p_material))
    )),true);
  END IF;
  RETURN private.attach_platform_v2_presentation_identity_v1(payload,p_user_id,false);
END;
$_$;


--
-- Name: lookup_public_catalog_entries_v1(text, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.lookup_public_catalog_entries_v1(p_query text, p_language_code text DEFAULT NULL::text, p_limit integer DEFAULT 10) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_raw_query text;
    v_query text;
    v_query_unaccent text;
    v_language_code text;
    v_items jsonb;
    v_total int;
    v_resolved_by text;
    v_public_entry_exists boolean;
    v_search_document_exists boolean;
BEGIN
    v_raw_query := NULLIF(trim(COALESCE(p_query, '')), '');
    v_query := normalize_dictionary_search_text(v_raw_query);
    v_query_unaccent := normalize_dictionary_search_text_unaccent(v_raw_query);
    v_language_code := NULLIF(trim(COALESCE(p_language_code, '')), '');

    IF v_raw_query IS NULL THEN
        RETURN jsonb_build_object(
            'query', p_query,
            'resolution', jsonb_build_object(
                'resolved_by', NULL,
                'normalized', v_query,
                'normalized_unaccent', v_query_unaccent
            ),
            'items', '[]'::jsonb,
            'total', 0
        );
    END IF;

    SELECT EXISTS (
        SELECT 1
        FROM private.active_word_entries w
        JOIN dictionaries d ON d.id = w.dictionary_id
        WHERE d.visibility IN ('system', 'public')
          AND (v_language_code IS NULL OR w.language_code = v_language_code)
        LIMIT 1
    )
    INTO v_public_entry_exists;

    SELECT EXISTS (
        SELECT 1
        FROM dictionary_search_documents s
        JOIN dictionaries d ON d.id = s.dictionary_id
        WHERE d.visibility IN ('system', 'public')
          AND (v_language_code IS NULL OR s.language_code = v_language_code)
        LIMIT 1
    )
    INTO v_search_document_exists;

    IF v_public_entry_exists AND NOT v_search_document_exists THEN
        RETURN jsonb_build_object(
            'error', 'search_index_not_ready',
            'query', v_raw_query,
            'resolution', jsonb_build_object(
                'resolved_by', NULL,
                'normalized', v_query,
                'normalized_unaccent', v_query_unaccent
            ),
            'items', '[]'::jsonb,
            'total', 0
        );
    END IF;

    WITH resolved AS MATERIALIZED (
        SELECT *
        FROM private.resolve_public_dictionary_lookup_candidates_indexed_v1(
            v_raw_query,
            p_language_code,
            NULL,
            p_limit
        )
    ),
    hydrated AS (
        SELECT
            w.*,
            r.resolved_by,
            r.matched_text,
            r.tier_rank,
            r.match_rank,
            d.name AS dictionary_name,
            d.slug AS dictionary_slug,
            d.kind AS dictionary_kind,
            d.visibility AS dictionary_visibility,
            d.owner_user_id AS dictionary_owner_user_id,
            d.is_editable AS dictionary_is_editable,
            d.schema_key AS dictionary_schema_key,
            d.schema_version AS dictionary_schema_version,
            d.language_code AS dictionary_language_code,
            COUNT(*) OVER (
                PARTITION BY w.dictionary_id, w.language_code, w.headword
            ) AS meanings_count,
            CASE
                WHEN d.kind = 'curated' THEN 1
                ELSE 2
            END AS dictionary_rank
        FROM resolved r
        JOIN private.active_word_entries w ON w.id = r.entry_id
        JOIN dictionaries d ON d.id = w.dictionary_id
        WHERE d.visibility IN ('system', 'public')
    ),
    payloads AS (
        SELECT
            jsonb_strip_nulls(jsonb_build_object(
                'id', h.id,
                'dictionary_id', h.dictionary_id,
                'language_code', h.language_code,
                'headword', h.headword,
                'meaning_id', h.meaning_id,
                'part_of_speech', h.part_of_speech,
                'gender', h.gender,
                'raw', h.raw,
                'is_nt2_2000', h.is_nt2_2000,
                'meanings_count', COALESCE(h.meanings_count, 1),
                'dictionary', jsonb_build_object(
                    'id', h.dictionary_id,
                    'language_code', h.dictionary_language_code,
                    'slug', h.dictionary_slug,
                    'name', h.dictionary_name,
                    'kind', h.dictionary_kind,
                    'visibility', h.dictionary_visibility,
                    'owner_user_id', h.dictionary_owner_user_id,
                    'is_editable', h.dictionary_is_editable,
                    'schema_key', h.dictionary_schema_key,
                    'schema_version', h.dictionary_schema_version
                ),
                'dictionary_name', h.dictionary_name,
                'dictionary_slug', h.dictionary_slug,
                'dictionary_kind', h.dictionary_kind,
                'search_match_group', h.resolved_by,
                'search_matched_text', h.matched_text
            )) AS payload,
            h.tier_rank,
            h.match_rank,
            h.dictionary_rank,
            h.resolved_by,
            normalize_dictionary_search_text(h.headword) AS sort_headword,
            h.meaning_id,
            h.id
        FROM hydrated h
    )
    SELECT
        COUNT(*)::int,
        COALESCE(
            jsonb_agg(
                payload
                ORDER BY tier_rank, match_rank, dictionary_rank, sort_headword, meaning_id, id
            ),
            '[]'::jsonb
        ),
        (array_agg(resolved_by ORDER BY tier_rank, match_rank, dictionary_rank, sort_headword, meaning_id, id))[1]
    INTO v_total, v_items, v_resolved_by
    FROM payloads;

    RETURN jsonb_build_object(
        'query', v_raw_query,
        'resolution', jsonb_build_object(
            'resolved_by', v_resolved_by,
            'normalized', v_query,
            'normalized_unaccent', v_query_unaccent
        ),
        'items', COALESCE(v_items, '[]'::jsonb),
        'total', COALESCE(v_total, 0)
    );
END;
$$;


--
-- Name: mark_platform_v2_idiom_training_session_member_unavailable(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_platform_v2_idiom_training_session_member_unavailable(p_user_id uuid, p_session_id uuid, p_target_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_session public.training_sessions%rowtype;
    v_member public.training_session_exercise_members%rowtype;
    v_expected public.training_session_exercise_members%rowtype;
    v_remaining integer;
    v_completed integer;
    v_now timestamptz := private.training_reference_now_v1();
BEGIN
  PERFORM private.require_active_training_session_v1(p_user_id,p_session_id);

    IF EXISTS(SELECT 1 FROM private.training_current_card_permits permit
      WHERE permit.user_id=p_user_id AND permit.session_id=p_session_id AND permit.target_id=p_target_id
        AND private.current_training_permit_valid_v1(permit)) THEN
      RAISE EXCEPTION 'current_training_card_protected' USING ERRCODE='42501';
    END IF;
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;
    IF p_reason NOT IN ('projection-missing', 'dictionary-access-revoked', 'entry-not-found', 'pair-excluded') THEN
        RAISE EXCEPTION 'invalid_idiom_session_unavailable_reason';
    END IF;
    PERFORM private.require_active_training_session_v1(p_user_id, p_session_id);

    SELECT *
      INTO v_session
      FROM public.training_sessions AS session
     WHERE session.id = p_session_id
       AND session.user_id = p_user_id
       AND session.exercise_family = 'idiom'
     FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'not-member');
    END IF;

    SELECT *
      INTO v_member
      FROM public.training_session_exercise_members AS member
     WHERE member.session_id = p_session_id
       AND member.target_id = p_target_id
     FOR UPDATE;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('status', 'not-member');
    END IF;
    IF v_member.consumed_at IS NOT NULL THEN
        RETURN jsonb_build_object('status', 'consumed', 'ordinal', v_member.ordinal);
    END IF;
    IF v_member.unavailable_at IS NOT NULL THEN
        RETURN jsonb_build_object(
            'status', 'unavailable',
            'ordinal', v_member.ordinal,
            'reason', v_member.unavailable_reason
        );
    END IF;

    SELECT *
      INTO v_expected
      FROM public.training_session_exercise_members AS member
     WHERE member.session_id = p_session_id
       AND member.consumed_at IS NULL
       AND member.unavailable_at IS NULL
     ORDER BY member.ordinal
     LIMIT 1;
    IF v_expected.target_id IS DISTINCT FROM p_target_id THEN
        RETURN jsonb_build_object(
            'status', 'out-of-order',
            'ordinal', v_member.ordinal,
            'expectedOrdinal', v_expected.ordinal
        );
    END IF;

    IF p_reason='pair-excluded' AND NOT EXISTS (
      SELECT 1 FROM private.platform_v2_training_exercise_targets target
      WHERE target.id=p_target_id AND private.training_pair_excluded_v1(
        p_user_id,'idiom',target.entry_id,target.content_node_id,target.source_text_fingerprint,NULL)
    ) THEN RAISE EXCEPTION 'training_session_unavailable_evidence_mismatch'; END IF;

    UPDATE public.training_session_exercise_members
       SET unavailable_at = v_now,
           unavailable_reason = p_reason
     WHERE session_id = p_session_id
       AND target_id = p_target_id;

    SELECT count(*) FILTER (
               WHERE member.consumed_at IS NULL
                 AND member.unavailable_at IS NULL
           )::integer,
           count(*) FILTER (WHERE member.consumed_at IS NOT NULL)::integer
      INTO v_remaining, v_completed
      FROM public.training_session_exercise_members AS member
     WHERE member.session_id = p_session_id;

    IF v_remaining = 0 THEN
        UPDATE public.training_sessions
           SET completed_at = COALESCE(completed_at, v_now),
               exhausted_at = COALESCE(exhausted_at, v_now),
               completion_reason = COALESCE(completion_reason, 'exhausted')
         WHERE id = p_session_id;
    END IF;

    RETURN jsonb_build_object(
        'status', CASE WHEN v_remaining = 0 THEN 'unavailable-exhausted' ELSE 'unavailable' END,
        'ordinal', v_member.ordinal,
        'reason', p_reason,
        'remaining', v_remaining,
        'completedActions', v_completed
    );
END;
$$;


--
-- Name: mark_platform_v2_translation_session_member_unavailable(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_platform_v2_translation_session_member_unavailable(p_user_id uuid, p_session_id uuid, p_target_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_session public.training_sessions%rowtype;
    v_member public.training_session_exercise_members%rowtype;
    v_expected public.training_session_exercise_members%rowtype;
    v_remaining integer;
    v_completed integer;
    v_now timestamptz := private.training_reference_now_v1();
BEGIN
  PERFORM private.require_active_training_session_v1(p_user_id,p_session_id);

    IF EXISTS(SELECT 1 FROM private.training_current_card_permits permit
      WHERE permit.user_id=p_user_id AND permit.session_id=p_session_id AND permit.target_id=p_target_id
        AND private.current_training_permit_valid_v1(permit)) THEN
      RAISE EXCEPTION 'current_training_card_protected' USING ERRCODE='42501';
    END IF;
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;
    IF p_reason NOT IN ('projection-missing', 'dictionary-access-revoked', 'entry-not-found', 'pair-excluded') THEN
        RAISE EXCEPTION 'invalid_translation_session_unavailable_reason';
    END IF;
    PERFORM private.require_active_training_session_v1(p_user_id, p_session_id);
    SELECT * INTO v_session
      FROM public.training_sessions
     WHERE id = p_session_id AND user_id = p_user_id AND exercise_family = 'translation'
     FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not-member'); END IF;
    SELECT * INTO v_member FROM public.training_session_exercise_members
     WHERE session_id = p_session_id AND target_id = p_target_id FOR UPDATE;
    IF NOT FOUND THEN RETURN jsonb_build_object('status', 'not-member'); END IF;
    IF v_member.consumed_at IS NOT NULL THEN
        RETURN jsonb_build_object('status', 'consumed', 'ordinal', v_member.ordinal);
    END IF;
    IF v_member.unavailable_at IS NOT NULL THEN
        RETURN jsonb_build_object('status', 'unavailable', 'ordinal', v_member.ordinal,
            'reason', v_member.unavailable_reason);
    END IF;
    SELECT * INTO v_expected FROM public.training_session_exercise_members
     WHERE session_id = p_session_id AND consumed_at IS NULL AND unavailable_at IS NULL
     ORDER BY ordinal LIMIT 1;
    IF v_expected.target_id IS DISTINCT FROM p_target_id THEN
        RETURN jsonb_build_object('status', 'out-of-order', 'ordinal', v_member.ordinal,
            'expectedOrdinal', v_expected.ordinal);
    END IF;
    IF p_reason='pair-excluded' AND NOT EXISTS (
      SELECT 1 FROM private.platform_v2_training_exercise_targets target
      WHERE target.id=p_target_id AND private.training_pair_excluded_v1(
        p_user_id,'translation',target.entry_id,target.content_node_id,target.source_text_fingerprint,NULL)
    ) THEN RAISE EXCEPTION 'training_session_unavailable_evidence_mismatch'; END IF;

    UPDATE public.training_session_exercise_members
       SET unavailable_at = v_now, unavailable_reason = p_reason
     WHERE session_id = p_session_id AND target_id = p_target_id;
    SELECT count(*) FILTER (WHERE consumed_at IS NULL AND unavailable_at IS NULL)::integer,
           count(*) FILTER (WHERE consumed_at IS NOT NULL)::integer
      INTO v_remaining, v_completed
      FROM public.training_session_exercise_members WHERE session_id = p_session_id;
    IF v_remaining = 0 THEN
        UPDATE public.training_sessions
           SET completed_at = COALESCE(completed_at, v_now),
               exhausted_at = COALESCE(exhausted_at, v_now),
               completion_reason = COALESCE(completion_reason, 'exhausted')
         WHERE id = p_session_id;
    END IF;
    RETURN jsonb_build_object(
        'status', CASE WHEN v_remaining = 0 THEN 'unavailable-exhausted' ELSE 'unavailable' END,
        'ordinal', v_member.ordinal, 'reason', p_reason,
        'remaining', v_remaining, 'completedActions', v_completed
    );
END;
$$;


--
-- Name: mark_training_session_member_unavailable(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_training_session_member_unavailable(p_user_id uuid, p_session_id uuid, p_entry_id uuid, p_card_type_id text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  PERFORM private.require_active_training_session_v1(p_user_id,p_session_id);

    IF EXISTS(SELECT 1 FROM private.training_current_card_permits permit
      WHERE permit.user_id=p_user_id AND permit.session_id=p_session_id AND permit.entry_id=p_entry_id
        AND permit.card_type_id=p_card_type_id AND permit.target_id IS NULL
        AND private.current_training_permit_valid_v1(permit)) THEN
      RAISE EXCEPTION 'current_training_card_protected' USING ERRCODE='42501';
    END IF;
  PERFORM private.training_reference_now_v1();
  PERFORM private.require_active_training_session_v1(p_user_id, p_session_id);
  RETURN private.mark_training_session_member_unavailable_latch_v1(
    p_user_id, p_session_id, p_entry_id, p_card_type_id, p_reason
  );
END;
$$;


--
-- Name: mark_training_word_context_hint_opened(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_training_word_context_hint_opened(p_user_id uuid, p_session_id uuid, p_entry_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  PERFORM private.require_active_training_session_v1(p_user_id,p_session_id);
  IF NOT EXISTS(SELECT 1 FROM public.training_session_members member
    WHERE member.session_id=p_session_id AND member.entry_id=p_entry_id
      AND member.card_type_id='definition-to-word' AND member.context_content_node_id IS NOT NULL
      AND member.consumed_at IS NULL AND member.unavailable_at IS NULL) THEN
    RETURN false;
  END IF;
  -- Match acknowledgement/action ordering: active run lock, then entry lock.
  -- Archive therefore commits either before this evidence check or after it.
  PERFORM private.lock_shared_learning_source_v1(p_user_id,p_entry_id);
  PERFORM id FROM public.word_entries WHERE id=p_entry_id FOR SHARE;
  IF NOT FOUND OR NOT private.training_word_context_entry_available_v1(p_user_id,p_session_id,p_entry_id) THEN
    RETURN false;
  END IF;
  UPDATE public.training_session_members member SET context_hint_opened=true
  FROM public.training_sessions session
  WHERE member.session_id=session.id AND session.id=p_session_id AND session.user_id=p_user_id
    AND session.training_filter->>'presentationMode'='word-in-context' AND session.superseded_at IS NULL
    AND member.entry_id=p_entry_id AND member.card_type_id='definition-to-word'
    AND member.context_content_node_id IS NOT NULL
    AND member.consumed_at IS NULL AND member.unavailable_at IS NULL
    AND EXISTS(SELECT 1 FROM private.platform_v2_content_nodes node
      WHERE node.id=member.context_content_node_id AND node.entry_id=member.entry_id
        AND node.kind='example' AND node.binding_state='active'
        AND node.source_text_fingerprint=member.context_source_text_fingerprint);
  RETURN FOUND;
END;
$$;


--
-- Name: mutate_collection_labels_v1(uuid, bigint, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mutate_collection_labels_v1(p_user_id uuid, p_expected_revision bigint, p_operation jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_type text;
    v_id uuid;
    v_parent_id uuid;
    v_collection_id uuid;
    v_name text;
    v_description text;
    v_label_ids uuid[];
    v_existing_ids uuid[];
    v_existing private.collection_labels%ROWTYPE;
    v_revision integer;
    v_parent_depth integer := 0;
    v_subtree_height integer := 1;
    v_cycle boolean;
    v_changed boolean := false;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;
    IF p_expected_revision IS NULL OR p_expected_revision < 0
       OR p_expected_revision > 2147483646
       OR jsonb_typeof(p_operation) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION 'invalid_label_operation';
    END IF;
    v_type := p_operation->>'type';
    IF v_type IS NULL OR v_type NOT IN ('create', 'update', 'delete', 'set-collection-labels') THEN
        RAISE EXCEPTION 'invalid_label_operation';
    END IF;
    IF (v_type = 'create' AND p_operation - ARRAY['type','id','name','description','parent_id'] <> '{}'::jsonb)
       OR (v_type = 'update' AND p_operation - ARRAY['type','id','name','description','parent_id'] <> '{}'::jsonb)
       OR (v_type = 'delete' AND p_operation - ARRAY['type','id'] <> '{}'::jsonb)
       OR (v_type = 'set-collection-labels' AND p_operation - ARRAY['type','collection_id','label_ids'] <> '{}'::jsonb) THEN
        RAISE EXCEPTION 'invalid_label_operation';
    END IF;
    BEGIN
        IF v_type = 'set-collection-labels' THEN
            v_collection_id := (p_operation->>'collection_id')::uuid;
            IF jsonb_typeof(p_operation->'label_ids') IS DISTINCT FROM 'array'
               OR jsonb_array_length(p_operation->'label_ids') > 1000
               OR EXISTS (SELECT 1 FROM jsonb_array_elements(p_operation->'label_ids') value
                          WHERE jsonb_typeof(value) <> 'string') THEN
                RAISE EXCEPTION 'invalid_label_operation';
            END IF;
            SELECT COALESCE(array_agg(DISTINCT value::uuid ORDER BY value::uuid), ARRAY[]::uuid[])
            INTO v_label_ids FROM jsonb_array_elements_text(p_operation->'label_ids');
            -- Match existing collection delete's collection -> catalog lock order.
            -- This lock prevents deletion through both RPC and direct SQL until
            -- assignment replacement has committed.
            PERFORM 1 FROM public.user_word_lists
            WHERE user_id = p_user_id AND id = v_collection_id FOR KEY SHARE;
            IF NOT FOUND THEN RAISE EXCEPTION 'collection_not_found'; END IF;
        ELSE
            v_id := COALESCE((p_operation->>'id')::uuid,
                CASE WHEN v_type = 'create' THEN gen_random_uuid() END);
            IF v_id IS NULL THEN RAISE EXCEPTION 'invalid_label_operation'; END IF;
        END IF;
        IF p_operation ? 'parent_id' THEN
            v_parent_id := (p_operation->>'parent_id')::uuid;
        END IF;
    EXCEPTION WHEN invalid_text_representation THEN
        RAISE EXCEPTION 'invalid_label_operation';
    END;

    INSERT INTO private.collection_label_catalogs(user_id) VALUES (p_user_id)
    ON CONFLICT (user_id) DO NOTHING;
    SELECT revision INTO v_revision FROM private.collection_label_catalogs
    WHERE user_id = p_user_id FOR UPDATE;
    IF v_revision <> p_expected_revision THEN RAISE EXCEPTION 'label_catalog_conflict'; END IF;

    IF v_type = 'set-collection-labels' THEN
        IF EXISTS (SELECT 1 FROM unnest(v_label_ids) requested(id)
                   LEFT JOIN private.collection_labels label ON label.user_id = p_user_id AND label.id = requested.id
                   WHERE label.id IS NULL) THEN RAISE EXCEPTION 'label_not_found'; END IF;
        SELECT COALESCE(array_agg(label_id ORDER BY label_id), ARRAY[]::uuid[])
        INTO v_existing_ids FROM private.collection_label_assignments
        WHERE user_id = p_user_id AND collection_id = v_collection_id;
        IF v_existing_ids IS DISTINCT FROM v_label_ids THEN
            IF (SELECT count(*) FROM private.collection_label_assignments WHERE user_id = p_user_id)
               - cardinality(v_existing_ids) + cardinality(v_label_ids) > 10000 THEN
                RAISE EXCEPTION 'label_catalog_limit';
            END IF;
            DELETE FROM private.collection_label_assignments
            WHERE user_id = p_user_id AND collection_id = v_collection_id;
            INSERT INTO private.collection_label_assignments(user_id, collection_id, label_id)
            SELECT p_user_id, v_collection_id, id FROM unnest(v_label_ids) requested(id);
            v_changed := true;
        END IF;
    ELSE
        IF v_type <> 'create' THEN
            SELECT * INTO v_existing FROM private.collection_labels
            WHERE user_id = p_user_id AND id = v_id;
            IF NOT FOUND THEN RAISE EXCEPTION 'label_not_found'; END IF;
            IF NOT p_operation ? 'parent_id' THEN v_parent_id := v_existing.parent_id; END IF;
        ELSIF EXISTS (SELECT 1 FROM private.collection_labels WHERE id = v_id) THEN
            RAISE EXCEPTION 'invalid_label_operation';
        END IF;
        IF v_type = 'delete' THEN
            -- Splice one level: children retain IDs, assignments and descendants.
            UPDATE private.collection_labels SET parent_id = v_existing.parent_id, updated_at = now()
            WHERE user_id = p_user_id AND parent_id = v_id;
            DELETE FROM private.collection_labels WHERE user_id = p_user_id AND id = v_id;
            v_changed := true;
        ELSE
            IF (p_operation ? 'name' AND jsonb_typeof(p_operation->'name') IS DISTINCT FROM 'string')
               OR (p_operation ? 'description' AND jsonb_typeof(p_operation->'description') NOT IN ('string','null')) THEN
                RAISE EXCEPTION 'invalid_label_operation';
            END IF;
            v_name := CASE WHEN p_operation ? 'name' THEN btrim(p_operation->>'name') ELSE v_existing.name END;
            v_description := CASE WHEN p_operation ? 'description' THEN p_operation->>'description' ELSE v_existing.description END;
            IF v_name IS NULL OR length(v_name) NOT BETWEEN 1 AND 100 OR length(v_description) > 1000 THEN
                RAISE EXCEPTION 'invalid_label_operation';
            END IF;
            IF v_parent_id IS NOT NULL THEN
                IF NOT EXISTS (SELECT 1 FROM private.collection_labels WHERE user_id = p_user_id AND id = v_parent_id) THEN
                    RAISE EXCEPTION 'label_not_found';
                END IF;
                WITH RECURSIVE ancestors AS (
                    SELECT id, parent_id, 1 AS depth FROM private.collection_labels
                    WHERE user_id = p_user_id AND id = v_parent_id
                    UNION ALL
                    SELECT parent.id, parent.parent_id, ancestor.depth + 1
                    FROM ancestors ancestor JOIN private.collection_labels parent
                      ON parent.user_id = p_user_id AND parent.id = ancestor.parent_id
                    WHERE ancestor.depth <= 16
                ) SELECT max(depth), bool_or(id = v_id) INTO v_parent_depth, v_cycle FROM ancestors;
                IF v_cycle THEN RAISE EXCEPTION 'label_cycle'; END IF;
            END IF;
            IF v_type = 'update' THEN
                WITH RECURSIVE descendants AS (
                    SELECT id, 1 AS height FROM private.collection_labels WHERE user_id = p_user_id AND id = v_id
                    UNION ALL
                    SELECT child.id, parent.height + 1 FROM descendants parent
                    JOIN private.collection_labels child ON child.user_id = p_user_id AND child.parent_id = parent.id
                    WHERE parent.height <= 16
                ) SELECT max(height) INTO v_subtree_height FROM descendants;
            END IF;
            IF v_parent_depth + v_subtree_height > 16 THEN RAISE EXCEPTION 'label_depth_limit'; END IF;
            IF v_type = 'create' THEN
                IF (SELECT count(*) FROM private.collection_labels WHERE user_id = p_user_id) >= 1000 THEN
                    RAISE EXCEPTION 'label_catalog_limit';
                END IF;
                INSERT INTO private.collection_labels(user_id, id, parent_id, name, description)
                VALUES (p_user_id, v_id, v_parent_id, v_name, v_description);
                v_changed := true;
            ELSIF (v_existing.name, v_existing.description, v_existing.parent_id)
                  IS DISTINCT FROM (v_name, v_description, v_parent_id) THEN
                UPDATE private.collection_labels SET name = v_name, description = v_description,
                    parent_id = v_parent_id, updated_at = now()
                WHERE user_id = p_user_id AND id = v_id;
                v_changed := true;
            END IF;
        END IF;
    END IF;
    IF v_changed THEN
        IF v_revision >= 2147483646 THEN RAISE EXCEPTION 'label_catalog_limit'; END IF;
        UPDATE private.collection_label_catalogs SET revision = revision + 1 WHERE user_id = p_user_id;
    END IF;
    RETURN public.read_collection_labels_v1(p_user_id);
END;
$$;


--
-- Name: normalize_dictionary_search_text(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_dictionary_search_text(p_text text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT regexp_replace(lower(btrim(COALESCE(p_text, ''))), '\s+', ' ', 'g');
$$;


--
-- Name: normalize_dictionary_search_text_unaccent(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_dictionary_search_text_unaccent(p_text text) RETURNS text
    LANGUAGE sql STABLE
    SET search_path TO 'public', 'pg_temp'
    AS $$
    SELECT unaccent(normalize_dictionary_search_text(p_text));
$$;


--
-- Name: perform_platform_card_action(uuid, uuid, text, text, text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_platform_card_action(p_user_id uuid, p_entry_id uuid, p_card_type_id text, p_action text, p_result text DEFAULT NULL::text, p_turn_id uuid DEFAULT NULL::uuid, p_client_event_id text DEFAULT NULL::text, p_source_context jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
    v_dictionary_id uuid;
    v_existing user_card_action_events%rowtype;
    v_source jsonb;
    v_location jsonb;
    v_context jsonb;
    v_source_id uuid;
    v_location_id uuid;
    v_kind text;
    v_provider text;
    v_external_id text;
    v_url text;
    v_title text;
    v_language_code text;
    v_source_identity_key text;
    v_locator_kind text;
    v_start_ms integer;
    v_end_ms integer;
    v_phrase_index integer;
    v_context_text text;
    v_context_text_hash text;
    v_clicked_form text;
    v_locator_key text;
    v_effective_result text;
    v_effective_turn_id uuid;
    v_action_payload jsonb;
    v_action_payload_hash text;
    v_event_id uuid;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF p_action NOT IN ('record-view', 'start-learning', 'mark-known', 'mark-unknown', 'review-card') THEN
        RAISE EXCEPTION 'unsupported_action';
    END IF;

    IF p_client_event_id IS NOT NULL AND length(trim(p_client_event_id)) = 0 THEN
        RAISE EXCEPTION 'invalid_client_event_id';
    END IF;

    SELECT dictionary_id INTO v_dictionary_id
    FROM private.active_word_entries
    WHERE id = p_entry_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'word entry not found';
    END IF;

    IF v_dictionary_id IS NOT NULL
       AND NOT can_access_dictionary(p_user_id, v_dictionary_id, 'read') THEN
        RAISE EXCEPTION 'dictionary access denied';
    END IF;

    v_effective_result := CASE p_action
        WHEN 'mark-known' THEN 'easy'
        WHEN 'mark-unknown' THEN 'fail'
        ELSE p_result
    END;

    IF p_action = 'review-card'
       AND v_effective_result NOT IN ('fail', 'hard', 'success', 'easy', 'freeze', 'hide') THEN
        RAISE EXCEPTION 'missing_or_invalid_result';
    END IF;

    IF p_action IN ('mark-known', 'mark-unknown', 'review-card') THEN
        v_effective_turn_id := COALESCE(p_turn_id, CASE
            WHEN p_client_event_id IS NOT NULL
             AND p_client_event_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
            THEN p_client_event_id::uuid
            ELSE NULL
        END);
    ELSE
        v_effective_turn_id := p_turn_id;
    END IF;

    IF p_source_context->>'contractVersion' = 'source-context-v2' THEN
        v_action_payload := jsonb_strip_nulls(jsonb_build_object(
            'contractVersion', 'source-context-v2',
            'userId', p_user_id,
            'entryId', p_entry_id,
            'cardTypeId', p_card_type_id,
            'action', p_action,
            'result', v_effective_result,
            'turnId', v_effective_turn_id,
            'source', p_source_context->'source',
            'artifact', p_source_context->'artifact',
            'location', p_source_context->'location',
            'selection', p_source_context->'selection',
            'context', p_source_context->'context'
        ));
        v_action_payload_hash := encode(extensions.digest(v_action_payload::text, 'sha256'), 'hex');
    ELSE
        v_action_payload := jsonb_strip_nulls(jsonb_build_object(
            'entryId', p_entry_id,
            'cardTypeId', p_card_type_id,
            'action', p_action,
            'result', v_effective_result,
            'turnId', v_effective_turn_id,
            'sourceContext', p_source_context
        ));
        v_action_payload_hash := md5(v_action_payload::text);
    END IF;

    IF p_client_event_id IS NOT NULL THEN
        PERFORM pg_advisory_xact_lock(hashtext(p_user_id::text || ':' || p_client_event_id));

        SELECT * INTO v_existing
        FROM user_card_action_events
        WHERE user_id = p_user_id
          AND client_event_id = p_client_event_id;

        IF FOUND THEN
            IF v_existing.action_payload_hash <> v_action_payload_hash THEN
                RAISE EXCEPTION 'platform_action_idempotency_conflict';
            END IF;

            RETURN jsonb_build_object(
                'status', 'duplicate',
                'eventId', v_existing.id,
                'sourceId', v_existing.source_id,
                'locationId', v_existing.location_id
            );
        END IF;
    END IF;

    v_source := CASE
        WHEN jsonb_typeof(p_source_context->'source') = 'object'
        THEN p_source_context->'source'
        ELSE NULL
    END;
    v_location := CASE
        WHEN jsonb_typeof(p_source_context->'location') = 'object'
        THEN p_source_context->'location'
        ELSE NULL
    END;
    v_context := CASE
        WHEN jsonb_typeof(p_source_context->'context') = 'object'
        THEN p_source_context->'context'
        ELSE NULL
    END;

    v_clicked_form := NULLIF(left(trim(COALESCE(v_context->>'clickedForm', '')), 160), '');
    v_context_text := NULLIF(left(COALESCE(v_context->>'text', ''), 1000), '');
    v_context_text_hash := CASE WHEN v_context_text IS NULL THEN NULL ELSE md5(v_context_text) END;

    IF v_source IS NOT NULL THEN
        v_kind := COALESCE(NULLIF(left(trim(v_source->>'kind'), 80), ''), 'unknown');
        v_provider := NULLIF(left(trim(v_source->>'provider'), 80), '');
        v_external_id := NULLIF(left(trim(COALESCE(v_source->>'externalId', v_source->>'external_id')), 240), '');
        v_url := NULLIF(left(trim(COALESCE(v_source->>'url', v_source->>'canonicalUrl', v_source->>'canonical_url')), 2048), '');
        v_title := NULLIF(left(trim(v_source->>'title'), 500), '');
        v_language_code := NULLIF(left(trim(COALESCE(v_source->>'languageCode', v_source->>'language_code')), 16), '');
        v_source_identity_key := md5(concat_ws('|', v_kind, COALESCE(v_provider, ''), COALESCE(v_external_id, ''), COALESCE(v_url, '')));

        INSERT INTO learning_sources (
            source_identity_key,
            kind,
            provider,
            external_id,
            canonical_url,
            title,
            language_code,
            metadata,
            first_seen_at,
            last_seen_at
        )
        VALUES (
            v_source_identity_key,
            v_kind,
            v_provider,
            v_external_id,
            v_url,
            v_title,
            v_language_code,
            jsonb_strip_nulls(jsonb_build_object(
                'contractVersion', p_source_context->>'contractVersion',
                'client', p_source_context->'client'
            )),
            now(),
            now()
        )
        ON CONFLICT (source_identity_key) DO UPDATE
        SET title = COALESCE(excluded.title, learning_sources.title),
            language_code = COALESCE(excluded.language_code, learning_sources.language_code),
            metadata = learning_sources.metadata || excluded.metadata,
            last_seen_at = now()
        RETURNING id INTO v_source_id;

        IF v_location IS NOT NULL OR v_context_text_hash IS NOT NULL THEN
            v_locator_kind := COALESCE(NULLIF(left(trim(v_location->>'kind'), 80), ''), 'context');
            v_start_ms := private.safe_jsonb_int(COALESCE(v_location->>'startMs', v_location->>'start_ms'));
            v_end_ms := private.safe_jsonb_int(COALESCE(v_location->>'endMs', v_location->>'end_ms'));
            v_phrase_index := private.safe_jsonb_int(COALESCE(v_location->>'phraseIndex', v_location->>'phrase_index'));
            v_locator_key := md5(jsonb_strip_nulls(jsonb_build_object(
                'kind', v_locator_kind,
                'startMs', v_start_ms,
                'endMs', v_end_ms,
                'phraseIndex', v_phrase_index,
                'contextTextHash', v_context_text_hash
            ))::text);

            INSERT INTO learning_source_locations (
                source_id,
                locator_key,
                locator_kind,
                start_ms,
                end_ms,
                phrase_index,
                text_hash,
                context_text,
                metadata,
                first_seen_at,
                last_seen_at
            )
            VALUES (
                v_source_id,
                v_locator_key,
                v_locator_kind,
                v_start_ms,
                v_end_ms,
                v_phrase_index,
                v_context_text_hash,
                v_context_text,
                jsonb_strip_nulls(jsonb_build_object(
                    'diagnostics', p_source_context->'diagnostics'
                )),
                now(),
                now()
            )
            ON CONFLICT (source_id, locator_key) DO UPDATE
            SET last_seen_at = now(),
                context_text = COALESCE(learning_source_locations.context_text, excluded.context_text),
                metadata = learning_source_locations.metadata || excluded.metadata
            RETURNING id INTO v_location_id;
        END IF;
    END IF;

    IF p_action = 'record-view' THEN
        PERFORM record_card_view(p_user_id, p_entry_id, p_card_type_id);
    ELSIF p_action = 'start-learning' THEN
        PERFORM start_learning_entry_card(p_user_id, p_entry_id, p_card_type_id);
    ELSE
        PERFORM handle_card_review(
            p_user_id,
            p_entry_id,
            p_card_type_id,
            v_effective_result,
            v_effective_turn_id
        );
    END IF;

    INSERT INTO user_card_action_events (
        user_id,
        entry_id,
        card_type_id,
        action,
        result,
        client_event_id,
        turn_id,
        source_id,
        location_id,
        clicked_form,
        context_text_hash,
        action_payload_hash,
        source_context,
        created_at
    )
    VALUES (
        p_user_id,
        p_entry_id,
        p_card_type_id,
        p_action,
        v_effective_result,
        p_client_event_id,
        v_effective_turn_id,
        v_source_id,
        v_location_id,
        v_clicked_form,
        v_context_text_hash,
        v_action_payload_hash,
        p_source_context,
        now()
    )
    RETURNING id INTO v_event_id;

    RETURN jsonb_build_object(
        'status', 'accepted',
        'eventId', v_event_id,
        'sourceId', v_source_id,
        'locationId', v_location_id
    );
END;
$_$;


--
-- Name: perform_platform_card_action(uuid, uuid, text, text, text, uuid, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_platform_card_action(p_user_id uuid, p_entry_id uuid, p_card_type_id text, p_action text, p_result text, p_turn_id uuid, p_client_event_id text, p_source_context jsonb, p_auth_kind text, p_connected_client_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE
    v_result jsonb;
    v_event_id uuid;
    v_source_id uuid;
    v_location_id uuid;
    v_artifact jsonb;
    v_artifact_id uuid;
    v_artifact_identity_key text;
    v_auth_kind text;
    v_connected_client_id text;
    v_existing_event_id uuid;
BEGIN
    v_auth_kind := COALESCE(NULLIF(trim(p_auth_kind), ''), 'first_party');
    IF v_auth_kind NOT IN ('first_party', 'connected_client') THEN
        RAISE EXCEPTION 'invalid_platform_auth_kind';
    END IF;

    IF v_auth_kind = 'connected_client' THEN
        v_connected_client_id := NULLIF(trim(p_connected_client_id), '');
        IF v_connected_client_id IS NULL THEN
            RAISE EXCEPTION 'missing_connected_client_id';
        END IF;
    ELSE
        v_connected_client_id := NULL;
    END IF;

    IF p_source_context->>'contractVersion' = 'source-context-v2'
       AND p_action IN ('review-card', 'mark-known', 'mark-unknown') THEN
        IF p_client_event_id IS NULL
           OR p_client_event_id !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN
            RAISE EXCEPTION 'v2_client_event_id_must_be_uuid';
        END IF;

        IF p_turn_id IS NULL OR p_turn_id IS DISTINCT FROM p_client_event_id::uuid THEN
            RAISE EXCEPTION 'v2_turn_id_mismatch';
        END IF;

        SELECT id INTO v_existing_event_id
        FROM user_card_action_events
        WHERE user_id = p_user_id
          AND client_event_id = p_client_event_id;

        IF v_existing_event_id IS NULL AND EXISTS (
            SELECT 1
            FROM user_review_log
            WHERE turn_id = p_client_event_id::uuid
        ) THEN
            RAISE EXCEPTION 'platform_review_turn_already_consumed';
        END IF;
    END IF;

    v_result := public.perform_platform_card_action(
        p_user_id,
        p_entry_id,
        p_card_type_id,
        p_action,
        p_result,
        p_turn_id,
        p_client_event_id,
        p_source_context
    );

    IF v_result ? 'eventId' THEN
        v_event_id := (v_result->>'eventId')::uuid;
        v_source_id := NULLIF(v_result->>'sourceId', '')::uuid;
        v_location_id := NULLIF(v_result->>'locationId', '')::uuid;

        IF p_source_context->>'contractVersion' = 'source-context-v2'
           AND jsonb_typeof(p_source_context->'artifact') = 'object'
           AND v_source_id IS NOT NULL THEN
            v_artifact := p_source_context->'artifact';
            v_artifact_identity_key := encode(extensions.digest(jsonb_build_object(
                'sourceId', v_source_id,
                'artifact', v_artifact
            )::text, 'sha256'), 'hex');

            INSERT INTO learning_source_artifacts (
                source_id,
                artifact_identity_key,
                artifact_kind,
                producer,
                snapshot_revision_id,
                text_source_id,
                text_source_revision_id,
                text_content_fingerprint,
                timing_evidence_revision_id,
                phrase_set_revision_id,
                builder_version,
                language_code,
                quality,
                metadata,
                first_seen_at,
                last_seen_at
            )
            VALUES (
                v_source_id,
                v_artifact_identity_key,
                left(v_artifact->>'artifactKind', 80),
                left(v_artifact->>'producer', 80),
                NULLIF(left(COALESCE(v_artifact->>'snapshotRevisionId', ''), 160), ''),
                NULLIF(left(COALESCE(v_artifact->>'textSourceId', ''), 160), ''),
                NULLIF(left(COALESCE(v_artifact->>'textSourceRevisionId', ''), 160), ''),
                NULLIF(left(COALESCE(v_artifact->>'textContentFingerprint', ''), 160), ''),
                NULLIF(left(COALESCE(v_artifact->>'timingEvidenceRevisionId', ''), 160), ''),
                NULLIF(left(COALESCE(v_artifact->>'phraseSetRevisionId', ''), 160), ''),
                NULLIF(left(COALESCE(v_artifact->>'builderVersion', ''), 80), ''),
                NULLIF(left(COALESCE(v_artifact->>'languageCode', ''), 16), ''),
                NULLIF(left(COALESCE(v_artifact->>'quality', ''), 80), ''),
                '{}'::jsonb,
                now(),
                now()
            )
            ON CONFLICT (source_id, artifact_identity_key) DO UPDATE
            SET last_seen_at = now(),
                quality = COALESCE(excluded.quality, learning_source_artifacts.quality)
            RETURNING id INTO v_artifact_id;

            IF v_location_id IS NOT NULL THEN
                UPDATE learning_source_locations
                SET artifact_id = v_artifact_id
                WHERE id = v_location_id;
            END IF;
        END IF;

        UPDATE user_card_action_events
        SET auth_kind = v_auth_kind,
            connected_client_id = v_connected_client_id,
            artifact_id = v_artifact_id
        WHERE id = v_event_id
          AND user_id = p_user_id;
    END IF;

    RETURN v_result || jsonb_build_object(
        'authKind', v_auth_kind,
        'connectedClientId', v_connected_client_id,
        'artifactId', v_artifact_id
    );
END;
$_$;


--
-- Name: perform_platform_v2_card_action(uuid, text, uuid, text, text, uuid, text, text, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_platform_v2_card_action(p_user_id uuid, p_action_id text, p_entry_id uuid, p_card_type_id text, p_state_revision text, p_active_known_mark_id uuid, p_known_mark_revision text, p_review_result text, p_client_event_id uuid, p_source_context jsonb, p_auth_kind text, p_connected_client_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_response jsonb;
    v_request_projection jsonb;
BEGIN
    v_response := private.perform_platform_v2_card_action_without_verifiable_receipt(
        p_user_id,
        p_action_id,
        p_entry_id,
        p_card_type_id,
        p_state_revision,
        p_active_known_mark_id,
        p_known_mark_revision,
        p_review_result,
        p_client_event_id,
        p_source_context,
        p_auth_kind,
        p_connected_client_id
    );

    IF v_response->>'status' = 'accepted' THEN
        v_request_projection := jsonb_build_object(
            'contractVersion', 'platform-action-report-verification-v1',
            'entryId', p_entry_id,
            'cardTypeId', p_card_type_id,
            'stateRevision', p_state_revision,
            'actionId', p_action_id,
            'clientEventId', p_client_event_id,
            'reviewResult', CASE
                WHEN p_action_id = 'review-card' THEN p_review_result
                ELSE NULL
            END,
            'activeKnownMarkId', CASE
                WHEN p_action_id = 'undo-known'
                    THEN p_active_known_mark_id
                ELSE NULL
            END,
            'knownMarkRevision', CASE
                WHEN p_action_id = 'undo-known'
                    THEN p_known_mark_revision
                ELSE NULL
            END
        );

        UPDATE public.platform_v2_action_receipts
           SET request_projection = v_request_projection
         WHERE user_id = p_user_id
           AND client_event_id = p_client_event_id
           AND request_projection IS NULL;

        IF NOT FOUND THEN
            RAISE EXCEPTION 'platform_action_receipt_projection_missing';
        END IF;
    END IF;

    RETURN v_response;
END;
$$;


--
-- Name: perform_platform_v2_card_action_as_principal(uuid, text, uuid, text, text, uuid, text, text, uuid, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_platform_v2_card_action_as_principal(p_user_id uuid, p_action_id text, p_entry_id uuid, p_card_type_id text, p_state_revision text, p_active_known_mark_id uuid, p_known_mark_revision text, p_review_result text, p_client_event_id uuid, p_source_context jsonb, p_auth_kind text, p_connected_client_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_jwt_role text := COALESCE(
    NULLIF(current_setting('request.jwt.claim.role', true), ''),
    (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role'
  );
BEGIN
  IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;
  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);

  IF p_auth_kind NOT IN ('first_party', 'connected_client') THEN
    RAISE EXCEPTION 'invalid_auth_kind';
  END IF;

  
      IF NOT EXISTS(SELECT 1 FROM public.platform_v2_action_receipts WHERE user_id=p_user_id AND client_event_id=p_client_event_id) THEN
        PERFORM id FROM public.word_entries WHERE id=p_entry_id FOR SHARE;
        IF EXISTS(SELECT 1 FROM public.word_entries WHERE id=p_entry_id AND archived_at IS NOT NULL)
          OR NOT private.entry_access_v1(p_user_id,p_entry_id,'train') THEN
          RAISE EXCEPTION 'entry_not_accessible' USING ERRCODE='42501';
        END IF;
      END IF;

  RETURN private.perform_platform_v2_card_action_non_session_latch_v1(
    p_user_id, p_action_id, p_entry_id, p_card_type_id, p_state_revision,
    p_active_known_mark_id, p_known_mark_revision, p_review_result,
    p_client_event_id, p_source_context, p_auth_kind, p_connected_client_id
  );
END;
$$;


--
-- Name: perform_platform_v2_card_action_as_principal(uuid, text, uuid, text, text, uuid, text, text, uuid, jsonb, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_platform_v2_card_action_as_principal(p_user_id uuid, p_action_id text, p_entry_id uuid, p_card_type_id text, p_state_revision text, p_active_known_mark_id uuid, p_known_mark_revision text, p_review_result text, p_client_event_id uuid, p_source_context jsonb, p_auth_kind text, p_connected_client_id text, p_training_session_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
  v_receipt_exists boolean;
  v_response jsonb;
BEGIN
  IF COALESCE(
    NULLIF(current_setting('request.jwt.claim.role', true), ''),
    (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role'
  ) IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'unauthorized';
  END IF;
  IF p_user_id IS NULL THEN RAISE EXCEPTION 'missing_user_id'; END IF;
  PERFORM set_config('request.jwt.claim.sub', p_user_id::text, true);

  -- Preserve shared receipt-before-active-run lock order across action families.
  PERFORM pg_advisory_xact_lock(hashtext(p_user_id::text || ':' || p_client_event_id::text));
  PERFORM pg_advisory_xact_lock(hashtext('training-active-run:' || p_user_id::text));

  -- The dedicated first-party Library server route passes an explicit null to
  -- identify an ordinary non-session action. Keep that trusted call path out
  -- of the 12-argument Connected Client compatibility overload.
  IF p_training_session_id IS NULL THEN
      IF NOT EXISTS(SELECT 1 FROM public.platform_v2_action_receipts WHERE user_id=p_user_id AND client_event_id=p_client_event_id) THEN
        PERFORM id FROM public.word_entries WHERE id=p_entry_id FOR SHARE;
        IF EXISTS(SELECT 1 FROM public.word_entries WHERE id=p_entry_id AND archived_at IS NOT NULL)
          OR NOT private.entry_access_v1(p_user_id,p_entry_id,'train') THEN
          RAISE EXCEPTION 'entry_not_accessible' USING ERRCODE='42501';
        END IF;
      END IF;

    v_response := private.perform_platform_v2_card_action_non_session_latch_v1(
      p_user_id, p_action_id, p_entry_id, p_card_type_id, p_state_revision,
      p_active_known_mark_id, p_known_mark_revision, p_review_result,
      p_client_event_id, p_source_context, p_auth_kind, p_connected_client_id
    );
    IF v_response->>'status'='accepted' THEN
      UPDATE public.training_sessions s SET external_state_revision=s.external_state_revision+1
      FROM public.training_active_runs a WHERE a.user_id=p_user_id AND a.session_id=s.id
        AND s.user_id=p_user_id AND s.exercise_family='meaning' AND s.completed_at IS NULL;
    END IF;
    RETURN v_response;
  END IF;

  -- A completed action remains reconcilable after a takeover. New actions are
  -- fenced before the underlying mutation sees them.
  PERFORM pg_advisory_xact_lock(
    hashtext(p_user_id::text || ':' || p_client_event_id::text)
  );
  SELECT EXISTS (
    SELECT 1 FROM public.platform_v2_action_receipts
    WHERE user_id = p_user_id AND client_event_id = p_client_event_id
  ) INTO v_receipt_exists;
  IF NOT v_receipt_exists THEN
    PERFORM private.replan_training_session_remainder_v1(p_user_id,p_training_session_id);
    PERFORM private.require_active_training_session_v1(
      p_user_id, p_training_session_id
    );
  END IF;

  IF p_auth_kind IS DISTINCT FROM 'first_party' THEN

      IF NOT EXISTS(SELECT 1 FROM public.platform_v2_action_receipts WHERE user_id=p_user_id AND client_event_id=p_client_event_id) THEN
        PERFORM id FROM public.word_entries WHERE id=p_entry_id FOR SHARE;
        IF EXISTS(SELECT 1 FROM public.word_entries WHERE id=p_entry_id AND archived_at IS NOT NULL)
          OR NOT private.entry_access_v1(p_user_id,p_entry_id,'train') THEN
          RAISE EXCEPTION 'entry_not_accessible' USING ERRCODE='42501';
        END IF;
      END IF;
END IF;
  RETURN private.perform_platform_v2_card_action_session_latch_v1(
    p_user_id, p_action_id, p_entry_id, p_card_type_id, p_state_revision,
    p_active_known_mark_id, p_known_mark_revision, p_review_result,
    p_client_event_id, p_source_context, p_auth_kind, p_connected_client_id,
    p_training_session_id
  );
END;
$$;


