 SELECT bool_and(to_regprocedure(signature) IS NOT NULL)
 FROM unnest(ARRAY[
  'public.fetch_dictionary_entry_by_id_gated(uuid)',
  'public.read_platform_v2_training_group(uuid,uuid,integer)',
  'public.lookup_dictionary_entries_v3(text,text,uuid[],integer)',
  'public.lookup_public_catalog_entries_v1(text,text,integer)'
 ]) required(signature)
$$;


