--
-- Name: preview_collection_share_v1(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.preview_collection_share_v1(p_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE preview jsonb; samples jsonb; principal uuid:=(select auth.uid());
BEGIN
 IF principal IS NULL OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=principal) THEN
  RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';
 END IF;
 -- This verifies the exact current invitation before any sample is selected.
 preview:=private.preview_collection_share_v1(p_code);
 WITH members AS MATERIALIZED (
  SELECT entry.id,entry.headword,entry.dictionary_id,entry.management_kind,item.added_at
  FROM public.user_word_list_items item
  JOIN private.active_word_entries entry ON entry.id=item.word_id
  WHERE item.list_id=(preview->>'collectionId')::uuid
 ), dictionaries AS MATERIALIZED (
  SELECT dictionary.id,dictionary.kind,dictionary.owner_user_id,
   CASE WHEN dictionary.kind<>'user' THEN public.can_browse_dictionary(principal,dictionary.id) ELSE false END AS readable
  FROM (SELECT DISTINCT dictionary_id FROM members) selected
  JOIN public.dictionaries dictionary ON dictionary.id=selected.dictionary_id
 ), offered AS MATERIALIZED (
  SELECT member.* FROM members member
  LEFT JOIN dictionaries dictionary ON dictionary.id=member.dictionary_id
  JOIN private.collection_sharing_roots root ON root.id=(preview->>'rootId')::uuid
  WHERE NULLIF(btrim(member.headword),'') IS NOT NULL AND (member.dictionary_id IS NULL OR dictionary.readable OR
   (dictionary.kind='user' AND dictionary.owner_user_id=root.owner_user_id AND member.management_kind='user'))
  ORDER BY member.added_at,member.id LIMIT 3
 ), snippets AS (
  SELECT offered.id,offered.added_at,
   left(offered.headword,200)||CASE WHEN length(offered.headword)>200 THEN '…' ELSE '' END AS headword,
   CASE WHEN definition.text IS NOT NULL THEN left(definition.text,300)||CASE WHEN length(definition.text)>300 THEN '…' ELSE '' END END AS definition
  FROM offered LEFT JOIN LATERAL (
   SELECT node.canonical_source_text AS text FROM private.platform_v2_content_nodes node
   WHERE node.entry_id=offered.id AND node.binding_state='active' AND node.kind='definition'
    AND node.parent_content_node_id IS NULL AND NULLIF(btrim(node.canonical_source_text),'') IS NOT NULL
   ORDER BY node.source_order NULLS LAST,node.id LIMIT 1
  ) definition ON true
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('headword',headword,'definition',definition) ORDER BY added_at,id),'[]'::jsonb)
 INTO samples FROM snippets;
 RETURN jsonb_build_object('collectionId',preview->'collectionId','name',preview->'name',
  'entryCount',preview->'entryCount','offeredRole',preview->'offeredRole','role',preview->'role',
  'alreadyAdded',preview->'available','samples',samples);
END;
$$;


