CREATE FUNCTION public.publish_app_release_v1(p_commit text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
BEGIN
  IF p_commit !~ '^[0-9a-f]{40}$' OR p_commit IS NULL THEN RAISE EXCEPTION 'invalid_release_commit'; END IF;
