--
-- Name: query_feedback_items_admin(text, text, uuid, text, text, text, text, timestamp with time zone, timestamp with time zone, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.query_feedback_items_admin(p_kind text DEFAULT NULL::text, p_target_kind text DEFAULT NULL::text, p_target_entry_id uuid DEFAULT NULL::uuid, p_status text DEFAULT NULL::text, p_source_client text DEFAULT NULL::text, p_app_build_version text DEFAULT NULL::text, p_safe_code text DEFAULT NULL::text, p_created_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_created_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 50) RETURNS TABLE(feedback_item_id uuid, report_id uuid, reporter_pseudonym text, source_client text, app_build_version text, kind text, problem_type text, target_kind text, target jsonb, source_context jsonb, comment_present boolean, sanitized_summary text, status text, resolution text, duplicate_of_id uuid, github_url text, commit_state text, safe_error_codes text[], created_at timestamp with time zone, updated_at timestamp with time zone)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
  IF COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''),
      (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role') IS DISTINCT FROM 'service_role'
  THEN RAISE EXCEPTION 'unauthorized'; END IF;
  RETURN QUERY SELECT
     item.id, item.report_id, item.reporter_pseudonym, item.source_client,
     item.app_build_version, item.kind, item.problem_type, item.target_kind,
     item.target, item.source_context, item.comment_present,
     item.sanitized_summary, item.status, item.resolution,
     item.duplicate_of_id, item.github_url, item.commit_state,
     item.safe_error_codes, item.created_at, item.updated_at
   FROM public.feedback_items item
   WHERE (p_kind IS NULL OR item.kind = p_kind)
     AND (p_target_kind IS NULL OR item.target_kind = p_target_kind)
     AND (p_target_entry_id IS NULL OR item.target->>'entryId' = p_target_entry_id::text)
     AND (p_status IS NULL OR item.status = p_status)
     AND (p_source_client IS NULL OR item.source_client = p_source_client)
     AND (p_app_build_version IS NULL OR item.app_build_version = p_app_build_version)
     AND (p_safe_code IS NULL OR p_safe_code = ANY(item.safe_error_codes))
     AND (p_created_from IS NULL OR item.created_at >= p_created_from)
     AND (p_created_to IS NULL OR item.created_at < p_created_to)
   ORDER BY item.created_at DESC LIMIT LEAST(GREATEST(p_limit, 1), 200);
END;
$$;


--
-- Name: read_author_entry_archive_status_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_author_entry_archive_status_v1(p_user_id uuid, p_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE entry public.word_entries%rowtype;
BEGIN
  IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
    RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501';
  END IF;
  SELECT * INTO entry FROM public.word_entries WHERE id=p_entry_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'entry_not_found' USING ERRCODE='P0002'; END IF;
  PERFORM public.assert_editable_user_dictionary(p_user_id,entry.dictionary_id);
  IF entry.management_kind IS DISTINCT FROM 'user' THEN RAISE EXCEPTION 'author_entry_archive_forbidden' USING ERRCODE='42501'; END IF;
  RETURN jsonb_build_object('entryId',entry.id,'archived',entry.archived_at IS NOT NULL,
    'archivedAt',entry.archived_at,'sourceVersion',entry.content_version);
END;
$$;


