--
-- Name: read_collection_labels_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_collection_labels_v1(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;
    -- One statement snapshot: revision and all projections describe one state.
    RETURN (
        SELECT jsonb_build_object(
            'revision', COALESCE((SELECT revision FROM private.collection_label_catalogs WHERE user_id = p_user_id), 0),
            'labels', COALESCE((
                SELECT jsonb_agg(jsonb_build_object(
                    'id', id, 'parent_id', parent_id, 'name', name,
                    'description', description, 'created_at', created_at, 'updated_at', updated_at
                ) ORDER BY created_at, id)
                FROM private.collection_labels WHERE user_id = p_user_id
            ), '[]'::jsonb),
            'assignments', COALESCE((
                SELECT jsonb_agg(jsonb_build_object('collection_id', collection_id, 'label_id', label_id)
                    ORDER BY collection_id, label_id)
                FROM private.collection_label_assignments WHERE user_id = p_user_id
            ), '[]'::jsonb)
        )
    );
END;
$$;


