--
-- Name: read_collection_share_forward_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_collection_share_forward_v1(p_collection_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); original_code text; current_generation boolean;
BEGIN
 IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
 SELECT subscription.accepted_invitation_code,
  COALESCE(subscription.accepted_invitation_generation=invitation.generation
   AND subscription.accepted_invitation_code=invitation.code,false)
 INTO original_code,current_generation
 FROM private.live_collection_sharing_subscriptions_v1 live
 JOIN private.collection_sharing_subscriptions subscription ON subscription.root_id=live.root_id AND subscription.user_id=live.user_id
 LEFT JOIN private.collection_sharing_invitations invitation ON invitation.root_id=live.root_id AND invitation.role='viewer'
 WHERE live.user_id=principal AND live.collection_id=p_collection_id AND live.owner_user_id<>principal;
 IF NOT FOUND THEN RAISE EXCEPTION 'share_unavailable' USING ERRCODE='42501'; END IF;
 RETURN jsonb_build_object('collectionId',p_collection_id,'canForward',current_generation,
  'invitationCode',CASE WHEN current_generation THEN original_code ELSE NULL END);
END;
$$;


