--
-- Name: read_current_training_entry_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_current_training_entry_v1(p_user_id uuid, p_session_id uuid, p_permit_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE permit private.training_current_card_permits%rowtype; source public.word_entries%rowtype; dictionary jsonb; identity jsonb;
BEGIN
  PERFORM private.require_active_training_session_v1(p_user_id,p_session_id);
  SELECT * INTO permit FROM private.training_current_card_permits
    WHERE user_id=p_user_id AND session_id=p_session_id AND permit_id=p_permit_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('error','current_training_permit_invalid'); END IF;
  SELECT * INTO source FROM public.word_entries WHERE id=permit.entry_id FOR SHARE;
  IF NOT FOUND OR NOT private.current_training_permit_valid_v1(permit) THEN
    RETURN jsonb_build_object('error','current_training_permit_invalid');
  END IF;
  SELECT private.dictionary_metadata_for_entry_read_v1(p_user_id,d) INTO dictionary FROM public.dictionaries d WHERE d.id=source.dictionary_id;
  SELECT jsonb_build_object('entryId',source.id,'headwordGroupId',COALESCE(source_group.id,user_group.id),
    'meaningOrdinal',COALESCE(binding.sense_ordinal,source.meaning_id),
    'contentNodeBindings',private.read_platform_v2_content_node_bindings(source.id)) INTO identity
  FROM (SELECT 1) anchor
  LEFT JOIN private.source_entry_bindings binding ON binding.word_entry_id=source.id AND binding.binding_state='active'
  LEFT JOIN private.platform_v2_headword_groups source_group ON source_group.management_kind='source'
    AND source_group.dictionary_id=binding.dictionary_id AND source_group.identity_scheme_version=binding.identity_scheme_version
    AND source_group.source_group_key=binding.source_group_key
  LEFT JOIN private.platform_v2_headword_groups user_group ON user_group.management_kind='user' AND user_group.singleton_entry_id=source.id;
  IF identity->>'headwordGroupId' IS NULL THEN RETURN jsonb_build_object('error','presentation_identity_incomplete'); END IF;
  RETURN jsonb_build_object('items',jsonb_build_array(private.entry_payload_for_reader_v1(p_user_id,to_jsonb(source))||jsonb_build_object('dictionary',dictionary,'platform_v2_identity',identity)),
    'currentTarget',jsonb_build_object('permitId',permit.permit_id,'sessionId',permit.session_id,
      'runGeneration',permit.run_generation,'entryId',permit.entry_id,'cardTypeId',permit.card_type_id,
      'targetId',permit.target_id,'direction',permit.direction,'contentVersion',permit.content_version,
      'stateRevision',permit.state_revision,'expiresAt',permit.expires_at),
    'page',jsonb_build_object('selectedTierComplete',true,'nextGroupCursor',NULL));
END;
$$;


--
-- Name: read_diagnostic_report_receipt_as_principal(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_diagnostic_report_receipt_as_principal(p_user_id uuid, p_report_id uuid, p_payload_hash text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $_$
DECLARE v_role text := COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''),
  (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role');
  v_receipt public.diagnostic_report_receipts%rowtype;
BEGIN
  IF v_role IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'unauthorized'; END IF;
  IF p_user_id IS NULL OR p_report_id IS NULL OR p_payload_hash !~ '^[0-9a-f]{64}$'
  THEN RAISE EXCEPTION 'invalid_report_identity'; END IF;
  SELECT * INTO v_receipt FROM public.diagnostic_report_receipts
   WHERE reporter_user_id=p_user_id AND report_id=p_report_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_receipt.payload_hash IS DISTINCT FROM p_payload_hash THEN
    RETURN jsonb_build_object('status','conflict','reportId',p_report_id);
  END IF;
  RETURN jsonb_build_object('status','duplicate','reportId',p_report_id,
    'feedbackItemId',v_receipt.feedback_item_id,'acceptedAt',v_receipt.accepted_at);
END;
$_$;


--
-- Name: read_entry_note_material_v1(uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_entry_note_material_v1(p_entry_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); result jsonb; scope jsonb;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF p_entry_ids IS NULL OR cardinality(p_entry_ids)<1 OR cardinality(p_entry_ids)>50
    OR array_position(p_entry_ids,NULL) IS NOT NULL THEN RAISE EXCEPTION 'invalid_note_scope' USING ERRCODE='22023'; END IF;
  IF EXISTS(SELECT 1 FROM unnest(p_entry_ids) entry(id) WHERE NOT private.entry_access_v1(principal,entry.id,'browse')) THEN
    RAISE EXCEPTION 'note_entry_unavailable' USING ERRCODE='42501';
  END IF;
  scope:=private.entry_note_scope_material_v1(principal,p_entry_ids);
  SELECT jsonb_build_object('entries',COALESCE(jsonb_agg(jsonb_build_object('entryId',entry.id,
    'notes',private.display_entry_notes_from_scope_v1(to_jsonb(entry),scope)) ORDER BY entry.id),'[]'::jsonb)) INTO result
  FROM private.active_word_entries entry WHERE entry.id=ANY(p_entry_ids);
  IF octet_length(result::text)>1048576 THEN RAISE EXCEPTION 'note_material_too_large' USING ERRCODE='22023'; END IF;
  RETURN result;
END;
$$;


--
-- Name: read_entry_note_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.read_entry_note_v1(p_entry_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); result jsonb;
BEGIN
  IF principal IS NULL OR NOT private.entry_access_v1(principal,p_entry_id,'browse') THEN
    RAISE EXCEPTION 'note_entry_unavailable' USING ERRCODE='42501';
  END IF;
  SELECT jsonb_build_object('entryId',p_entry_id,'notes',note.notes,'revision',COALESCE(clock.revision,0)::text) INTO result
  FROM (SELECT 1) anchor
  LEFT JOIN public.user_word_notes note ON note.user_id=principal AND note.word_entry_id=p_entry_id
  LEFT JOIN private.user_word_note_revisions clock ON clock.user_id=principal AND clock.word_entry_id=p_entry_id;
  RETURN result;
END;
$$;


