--
-- Name: submit_diagnostic_report_as_principal(uuid, text, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_diagnostic_report_as_principal(p_user_id uuid, p_source_client text, p_app_build_version text, p_report_id uuid, p_payload_hash text, p_canonical_payload text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $_$
DECLARE
    v_role text := COALESCE(NULLIF(current_setting('request.jwt.claim.role', true), ''),
      (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role');
    v_existing public.diagnostic_report_receipts%rowtype;
    v_feedback_id uuid;
    v_accepted_at timestamptz;
    v_commit_state text;
    v_safe_codes text[];
BEGIN
    IF v_role IS DISTINCT FROM 'service_role' THEN RAISE EXCEPTION 'unauthorized'; END IF;
    IF p_user_id IS NULL OR p_report_id IS NULL OR p_payload_hash !~ '^[0-9a-f]{64}$'
       OR p_payload->>'schemaVersion' IS DISTINCT FROM 'diagnostic-report-v1'
       OR p_payload->>'reportId' IS DISTINCT FROM p_report_id::text
       OR NOT (p_payload ?& ARRAY['schemaVersion','reportId','feedback','target','sourceContext','cardContent','observations'])
       OR (SELECT count(*) FROM jsonb_object_keys(p_payload)) <> 7
       OR octet_length(p_canonical_payload) > 65536
       OR p_canonical_payload::jsonb IS DISTINCT FROM p_payload
       OR NOT private.diagnostic_report_closed_shape(p_payload)
       OR encode(digest(convert_to(p_canonical_payload, 'UTF8'), 'sha256'), 'hex')
          IS DISTINCT FROM p_payload_hash THEN
        RAISE EXCEPTION 'invalid_report';
    END IF;
    IF p_source_client IS NULL OR length(p_source_client) NOT BETWEEN 1 AND 128
       OR p_app_build_version IS NULL OR length(p_app_build_version) NOT BETWEEN 1 AND 128 THEN
        RAISE EXCEPTION 'invalid_server_metadata';
    END IF;

    PERFORM pg_advisory_xact_lock(hashtextextended(p_user_id::text || ':' || p_report_id::text, 0));
    SELECT * INTO v_existing FROM public.diagnostic_report_receipts
      WHERE reporter_user_id = p_user_id AND report_id = p_report_id;
    IF FOUND THEN
        IF v_existing.payload_hash IS DISTINCT FROM p_payload_hash THEN
            RETURN jsonb_build_object('status', 'conflict', 'reportId', p_report_id);
        END IF;
        RETURN jsonb_build_object('status', 'duplicate', 'reportId', p_report_id,
          'feedbackItemId', v_existing.feedback_item_id, 'acceptedAt', v_existing.accepted_at);
    END IF;

    v_commit_state := private.verify_diagnostic_report_target(
        p_user_id,
        p_payload->'target',
        NULLIF(p_payload->'cardContent', 'null'::jsonb),
        p_payload->'observations'
    );
    SELECT COALESCE(array_agg(DISTINCT cause->>'safeCode'), '{}') INTO v_safe_codes
      FROM jsonb_array_elements(p_payload->'observations'->'errorChain') cause;

    INSERT INTO public.feedback_items (
        reporter_user_id, reporter_pseudonym, report_id, source_client, app_build_version, kind,
        problem_type, target_kind, target, source_context, comment_present,
        commit_state, safe_error_codes
    ) VALUES (
        p_user_id,
        'usr_' || substr(encode(digest('diagnostic-reporter-v1:' || p_user_id::text, 'sha256'), 'hex'), 1, 24),
        p_report_id, p_source_client, p_app_build_version,
        p_payload->'feedback'->>'kind', p_payload->'feedback'->>'problemType',
        p_payload->'target'->>'kind', p_payload->'target', p_payload->'sourceContext',
        p_payload->'feedback'->'comment' <> 'null'::jsonb,
        v_commit_state, v_safe_codes
    ) RETURNING id INTO v_feedback_id;

    INSERT INTO public.diagnostic_report_receipts (
        reporter_user_id, report_id, payload_hash, feedback_item_id
    ) VALUES (p_user_id, p_report_id, p_payload_hash, v_feedback_id)
    RETURNING accepted_at INTO v_accepted_at;

    INSERT INTO public.diagnostic_envelopes (
        feedback_item_id, reporter_user_id, report_id, payload_hash, canonical_payload
    ) VALUES (v_feedback_id, p_user_id, p_report_id, p_payload_hash, p_canonical_payload);

    RETURN jsonb_build_object('status', 'accepted', 'reportId', p_report_id,
      'feedbackItemId', v_feedback_id, 'acceptedAt', v_accepted_at,
      'commitState', v_commit_state);
END;
$_$;


--
-- Name: sync_dictionary_legacy_visibility(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_dictionary_legacy_visibility() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public', 'pg_temp'
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.publication_state IS NULL THEN
    NEW.publication_state := CASE NEW.visibility
      WHEN 'system' THEN 'general' WHEN 'public' THEN 'general'
      WHEN 'shared' THEN 'restricted' ELSE 'unpublished' END;
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.publication_state IS NOT DISTINCT FROM OLD.publication_state
     AND NEW.visibility IS DISTINCT FROM OLD.visibility THEN
    NEW.publication_state := CASE NEW.visibility
      WHEN 'system' THEN 'general' WHEN 'public' THEN 'general'
      WHEN 'shared' THEN 'restricted' ELSE 'unpublished' END;
  END IF;
  NEW.visibility := CASE NEW.publication_state
    WHEN 'general' THEN 'public'
    WHEN 'restricted' THEN 'shared'
    ELSE 'private'
  END;
  RETURN NEW;
END;
$$;


--
-- Name: update_active_training_scope(uuid, text, uuid, text, text, text, text[], integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_active_training_scope(p_user_id uuid, p_language_code text, p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT NULL::text, p_active_scenario text DEFAULT NULL::text, p_card_filter text DEFAULT NULL::text, p_modes_enabled text[] DEFAULT NULL::text[], p_new_review_ratio integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_language_code text := COALESCE(NULLIF(trim(p_language_code), ''), 'nl');
    v_list_type text;
    v_modes_enabled text[];
    v_list_owner_user_id uuid;
BEGIN
    IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    IF NOT EXISTS (SELECT 1 FROM languages WHERE code = v_language_code) THEN
        RAISE EXCEPTION 'invalid language_code %', v_language_code;
    END IF;

    v_list_type := CASE
        WHEN p_list_id IS NULL THEN NULL
        WHEN p_list_type IN ('curated', 'user') THEN p_list_type
        ELSE 'curated'
    END;

    IF p_list_id IS NOT NULL AND v_list_type='user' THEN
        -- Reject outsiders before attempting to lock their arbitrary source ID.
        -- Authority is checked again below after the parent has been protected.
        IF NOT EXISTS(SELECT 1 FROM public.user_word_lists list WHERE list.id=p_list_id AND
          (list.user_id=p_user_id OR private.received_collection_training_available_v1(p_user_id,list.id,v_language_code))) THEN
          RAISE EXCEPTION 'user list is not available for language %',v_language_code;
        END IF;
        PERFORM 1 FROM auth.users WHERE id=p_user_id FOR KEY SHARE NOWAIT;
        IF NOT FOUND THEN RAISE EXCEPTION 'unauthorized: account no longer exists'; END IF;
        SELECT list.user_id INTO v_list_owner_user_id FROM public.user_word_lists list
        WHERE list.id=p_list_id FOR KEY SHARE NOWAIT;
        IF NOT FOUND THEN RAISE EXCEPTION 'user list is not available for language %',v_language_code; END IF;
    END IF;

    IF p_list_id IS NOT NULL AND v_list_type = 'curated' AND NOT EXISTS (
        SELECT 1
        FROM word_lists l
        WHERE l.id = p_list_id
          AND l.language_code = v_language_code
    ) THEN
        RAISE EXCEPTION 'curated list is not available for language %', v_language_code;
    END IF;

    IF p_list_id IS NOT NULL AND v_list_type = 'user' AND NOT EXISTS (
        SELECT 1
        FROM user_word_lists l
        WHERE l.id = p_list_id
          AND ((l.user_id = p_user_id AND (
            COALESCE(l.primary_language_code, l.language_code) = v_language_code
            OR (l.primary_language_code IS NULL AND l.language_code = v_language_code)
            OR EXISTS(SELECT 1 FROM private.training_collection_catalog_cohort_v1(
              p_user_id,'',v_language_code,NULL,NULL,1,ARRAY[l.id]) material WHERE material.eligible)
          )) OR private.received_collection_training_available_v1(p_user_id,l.id,v_language_code))
    ) THEN
        RAISE EXCEPTION 'user list is not available for language %', v_language_code;
    END IF;

    v_modes_enabled := CASE
        WHEN p_modes_enabled IS NULL THEN NULL
        WHEN array_length(p_modes_enabled, 1) IS NULL THEN ARRAY['word-to-definition']::text[]
        ELSE p_modes_enabled
    END;

    INSERT INTO user_training_scopes (
        user_id,
        language_code,
        active_list_id,
        active_list_type,
        active_list_owner_user_id,
        active_scenario,
        card_filter,
        modes_enabled,
        new_review_ratio
    )
    VALUES (
        p_user_id,
        v_language_code,
        p_list_id,
        v_list_type,
        v_list_owner_user_id,
        COALESCE(p_active_scenario, 'understanding'),
        COALESCE(p_card_filter, 'both'),
        COALESCE(v_modes_enabled, ARRAY['word-to-definition']::text[]),
        COALESCE(p_new_review_ratio, 2)
    )
    ON CONFLICT (user_id, language_code) DO UPDATE
    SET active_list_id = excluded.active_list_id,
        active_list_type = excluded.active_list_type,
        active_list_owner_user_id = excluded.active_list_owner_user_id,
        active_scenario = COALESCE(p_active_scenario, user_training_scopes.active_scenario),
        card_filter = COALESCE(p_card_filter, user_training_scopes.card_filter),
        modes_enabled = COALESCE(v_modes_enabled, user_training_scopes.modes_enabled),
        new_review_ratio = COALESCE(p_new_review_ratio, user_training_scopes.new_review_ratio),
        updated_at = now();

    IF EXISTS (
        SELECT 1
        FROM user_settings
        WHERE user_id = p_user_id
          AND COALESCE(NULLIF(language_code, ''), 'nl') = v_language_code
    ) THEN
        INSERT INTO user_settings (user_id, active_list_id, active_list_type)
        VALUES (p_user_id, p_list_id, v_list_type)
        ON CONFLICT (user_id) DO UPDATE
        SET active_list_id = excluded.active_list_id,
            active_list_type = excluded.active_list_type,
            updated_at = now();
    END IF;

    RETURN get_active_training_scope(p_user_id, v_language_code);
END;
$$;


--
-- Name: update_active_word_list(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_active_word_list(p_user_id uuid, p_list_id uuid DEFAULT NULL::uuid, p_list_type text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_language_code text;
BEGIN
    IF p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    SELECT COALESCE(NULLIF(language_code, ''), 'nl')
    INTO v_language_code
    FROM user_settings
    WHERE user_id = p_user_id;

    PERFORM update_active_training_scope(
        p_user_id,
        COALESCE(v_language_code, 'nl'),
        p_list_id,
        p_list_type,
        NULL,
        NULL,
        NULL,
        NULL
    );
END;
$$;


--
-- Name: update_learning_preferences(uuid, text[], text, text, integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_learning_preferences(p_user_id uuid, p_modes_enabled text[] DEFAULT NULL::text[], p_card_filter text DEFAULT NULL::text, p_language_code text DEFAULT NULL::text, p_new_review_ratio integer DEFAULT NULL::integer, p_active_scenario text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_modes_enabled text[];
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized: user_id does not match authenticated user';
    END IF;

    v_modes_enabled := CASE
        WHEN p_modes_enabled IS NULL THEN NULL
        WHEN array_length(p_modes_enabled, 1) IS NULL THEN ARRAY['word-to-definition']::text[]
        ELSE p_modes_enabled
    END;

    INSERT INTO user_settings (
        user_id,
        modes_enabled,
        training_mode,
        card_filter,
        language_code,
        new_review_ratio,
        active_scenario
    )
    VALUES (
        p_user_id,
        COALESCE(v_modes_enabled, ARRAY['word-to-definition']::text[]),
        COALESCE(v_modes_enabled[1], 'word-to-definition'),
        COALESCE(p_card_filter, 'both'),
        COALESCE(p_language_code, 'nl'),
        COALESCE(p_new_review_ratio, 2),
        COALESCE(p_active_scenario, 'understanding')
    )
    ON CONFLICT (user_id) DO UPDATE
    SET modes_enabled = COALESCE(v_modes_enabled, user_settings.modes_enabled),
        training_mode = COALESCE(v_modes_enabled[1], user_settings.training_mode),
        card_filter = COALESCE(p_card_filter, user_settings.card_filter),
        language_code = COALESCE(p_language_code, user_settings.language_code),
        new_review_ratio = COALESCE(p_new_review_ratio, user_settings.new_review_ratio),
        active_scenario = COALESCE(p_active_scenario, user_settings.active_scenario),
        updated_at = now();
END;
$$;


--
-- Name: update_user_dictionary_entry(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_dictionary_entry(p_user_id uuid, p_entry_id uuid, p_entry jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_temp'
    AS $$
DECLARE
    v_existing word_entries%rowtype;
    v_dictionary dictionaries%rowtype;
    v_payload jsonb;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    SELECT * INTO v_existing
    FROM private.active_word_entries
    WHERE id = p_entry_id FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'entry_not_found';
    END IF;

    v_dictionary := assert_editable_user_dictionary(p_user_id, v_existing.dictionary_id);
    v_payload := validate_user_entry_v1_payload(private.merge_owned_entry_edit_v1(v_existing.raw,p_entry), v_dictionary.language_code);

    IF EXISTS (
        SELECT 1
        FROM word_entries
        WHERE dictionary_id = v_existing.dictionary_id
          AND language_code = v_payload->>'languageCode'
          AND headword = v_payload->>'headword'
          AND meaning_id = v_existing.meaning_id
          AND id <> p_entry_id
    ) THEN
        RAISE EXCEPTION 'duplicate_user_entry';
    END IF;

    UPDATE word_entries
    SET language_code = v_payload->>'languageCode',
        headword = v_payload->>'headword',
        part_of_speech = v_payload->>'partOfSpeech',
        gender = v_payload->>'gender',
        is_nt2_2000 = false,
        raw = v_payload
    WHERE id = p_entry_id;

    RETURN p_entry_id;
END;
$$;


--
-- Name: update_user_word_list(uuid, uuid, text, text, text, text, text, text, text[], boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_user_word_list(p_user_id uuid, p_list_id uuid, p_name text DEFAULT NULL::text, p_description text DEFAULT NULL::text, p_language_code text DEFAULT NULL::text, p_primary_language_code text DEFAULT NULL::text, p_default_scenario_id text DEFAULT NULL::text, p_card_policy text DEFAULT NULL::text, p_card_type_ids text[] DEFAULT NULL::text[], p_clear_default_scenario boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_existing user_word_lists%ROWTYPE;
    v_list user_word_lists%ROWTYPE;
    v_name text;
    v_language_code text;
    v_primary_language_code text;
    v_default_scenario_id text;
    v_card_policy text;
    v_card_type_ids text[];
    v_item_count int;
BEGIN
    IF (select auth.uid()) IS NULL OR p_user_id IS DISTINCT FROM (select auth.uid()) THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;

    SELECT * INTO v_existing
    FROM user_word_lists
    WHERE id = p_list_id
      AND user_id = p_user_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'list_not_found';
    END IF;

    v_name := COALESCE(NULLIF(trim(p_name), ''), v_existing.name);
    IF v_name IS NULL THEN
        RAISE EXCEPTION 'invalid_list_name';
    END IF;

    v_language_code := COALESCE(
        NULLIF(trim(p_language_code), ''),
        v_existing.language_code
    );
    v_primary_language_code := COALESCE(
        NULLIF(trim(p_primary_language_code), ''),
        v_existing.primary_language_code,
        v_language_code
    );
    v_default_scenario_id := CASE
        WHEN COALESCE(p_clear_default_scenario, false) THEN NULL
        ELSE COALESCE(
            NULLIF(trim(p_default_scenario_id), ''),
            v_existing.default_scenario_id
        )
    END;
    v_card_policy := private.normalize_list_card_policy(
        p_card_policy,
        v_existing.card_policy
    );
    v_card_type_ids := CASE
        WHEN p_card_type_ids IS NULL THEN v_existing.card_type_ids
        ELSE ARRAY(
            SELECT DISTINCT trim(card_type_id)
            FROM unnest(p_card_type_ids) AS card_type_id
            WHERE NULLIF(trim(card_type_id), '') IS NOT NULL
            ORDER BY trim(card_type_id)
        )
    END;
    IF v_card_type_ids IS NOT NULL AND array_length(v_card_type_ids, 1) IS NULL THEN
        v_card_type_ids := NULL;
    END IF;

    IF v_language_code IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM languages WHERE code = v_language_code) THEN
        RAISE EXCEPTION 'language_not_found';
    END IF;

    IF v_primary_language_code IS NOT NULL
       AND NOT EXISTS (SELECT 1 FROM languages WHERE code = v_primary_language_code) THEN
        RAISE EXCEPTION 'language_not_found';
    END IF;

    PERFORM private.validate_list_training_intent(
        v_default_scenario_id,
        v_card_policy,
        v_card_type_ids
    );

    UPDATE user_word_lists
    SET name = v_name,
        description = CASE
            WHEN p_description IS NULL THEN description
            ELSE NULLIF(p_description, '')
        END,
        language_code = v_language_code,
        primary_language_code = v_primary_language_code,
        default_scenario_id = v_default_scenario_id,
        card_policy = v_card_policy,
        card_type_ids = v_card_type_ids,
        updated_at = now()
    WHERE id = p_list_id
      AND user_id = p_user_id
    RETURNING * INTO v_list;

    SELECT COUNT(*) INTO v_item_count
    FROM user_word_list_items
    WHERE list_id = v_list.id;

    RETURN jsonb_build_object(
        'id', v_list.id,
        'name', v_list.name,
        'description', v_list.description,
        'language_code', v_list.language_code,
        'primary_language_code', v_list.primary_language_code,
        'default_scenario_id', v_list.default_scenario_id,
        'card_policy', v_list.card_policy,
        'card_type_ids', v_list.card_type_ids,
        'created_at', v_list.created_at,
        'user_word_list_items', jsonb_build_array(jsonb_build_object('count', v_item_count))
    );
EXCEPTION
    WHEN unique_violation THEN
        RAISE EXCEPTION 'duplicate_user_list';
END;
$$;


--
-- Name: validate_user_entry_v1_payload(jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_user_entry_v1_payload(p_payload jsonb, p_dictionary_language_code text) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'pg_temp'
    AS $$
DECLARE portable jsonb; base jsonb; definition text;
BEGIN
  IF NOT (p_payload ? 'meanings') THEN
    RETURN private.validate_simple_user_entry_v1(p_payload,p_dictionary_language_code);
  END IF;
  portable:=private.portable_owned_entry_content_v1(p_payload);
  SELECT item->>'definition' INTO definition
    FROM jsonb_array_elements(portable->'meanings') WITH ORDINALITY element(item,ordinal)
    WHERE NULLIF(trim(item->>'definition'),'') IS NOT NULL ORDER BY ordinal LIMIT 1;
  base:=private.validate_simple_user_entry_v1(
    p_payload || jsonb_build_object('definition',COALESCE(definition,'__rich_content_validation__')),
    p_dictionary_language_code);
  -- The rich projection owns notes too: they must not survive twice in nested/raw fields.
  RETURN (base-'notes'-'definition')||CASE WHEN definition IS NOT NULL THEN jsonb_build_object('definition',definition) ELSE '{}'::jsonb END||portable;
END;
$$;


--
-- Name: verify_platform_v2_action_receipt_as_principal(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_platform_v2_action_receipt_as_principal(p_user_id uuid, p_request_projection jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'private', 'extensions', 'pg_temp'
    AS $$
DECLARE
    v_action_id text;
    v_client_event_id uuid;
    v_jwt_role text := COALESCE(
        NULLIF(current_setting('request.jwt.claim.role', true), ''),
        (
            NULLIF(current_setting('request.jwt.claims', true), '')::jsonb
        )->>'role'
    );
BEGIN
    IF v_jwt_role IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;
    IF p_user_id IS NULL THEN
        RAISE EXCEPTION 'missing_user_id';
    END IF;
    IF jsonb_typeof(p_request_projection) IS DISTINCT FROM 'object'
       OR (
           SELECT count(*)
             FROM jsonb_object_keys(p_request_projection)
       ) <> 9
       OR NOT p_request_projection ?& ARRAY[
           'contractVersion',
           'entryId',
           'cardTypeId',
           'stateRevision',
           'actionId',
           'clientEventId',
           'reviewResult',
           'activeKnownMarkId',
           'knownMarkRevision'
       ]
       OR p_request_projection->>'contractVersion'
           IS DISTINCT FROM 'platform-action-report-verification-v1' THEN
        RETURN false;
    END IF;

    v_action_id := p_request_projection->>'actionId';
    IF v_action_id NOT IN (
        'start-learning',
        'mark-known',
        'undo-known',
        'review-card'
    ) THEN
        RETURN false;
    END IF;
    IF v_action_id = 'review-card' THEN
        IF p_request_projection->>'reviewResult'
               NOT IN ('fail', 'hard', 'success', 'easy')
           OR p_request_projection->'activeKnownMarkId' <> 'null'::jsonb
           OR p_request_projection->'knownMarkRevision' <> 'null'::jsonb THEN
            RETURN false;
        END IF;
    ELSIF v_action_id = 'undo-known' THEN
        IF p_request_projection->'reviewResult' <> 'null'::jsonb
           OR jsonb_typeof(p_request_projection->'activeKnownMarkId')
               IS DISTINCT FROM 'string'
           OR jsonb_typeof(p_request_projection->'knownMarkRevision')
               IS DISTINCT FROM 'string' THEN
            RETURN false;
        END IF;
    ELSIF p_request_projection->'reviewResult' <> 'null'::jsonb
       OR p_request_projection->'activeKnownMarkId' <> 'null'::jsonb
       OR p_request_projection->'knownMarkRevision' <> 'null'::jsonb THEN
        RETURN false;
    END IF;

    BEGIN
        v_client_event_id := (p_request_projection->>'clientEventId')::uuid;
        PERFORM (p_request_projection->>'entryId')::uuid;
    EXCEPTION
        WHEN invalid_text_representation THEN
            RETURN false;
    END;

    PERFORM pg_advisory_xact_lock(
        hashtext(p_user_id::text || ':' || v_client_event_id::text)
    );

    RETURN EXISTS (
        SELECT 1
          FROM public.platform_v2_action_receipts receipt
         WHERE receipt.user_id = p_user_id
           AND receipt.client_event_id = v_client_event_id
           AND receipt.request_projection = p_request_projection
    );
END;
$$;


--
-- Name: verify_platform_v2_bounded_report_atoms_as_principal(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_platform_v2_bounded_report_atoms_as_principal(p_user_id uuid, p_entry_id uuid, p_content_revision text, p_card_content jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'private', 'pg_temp'
    AS $$
DECLARE
    v_role text := COALESCE(
        NULLIF(current_setting('request.jwt.claim.role', true), ''),
        (NULLIF(current_setting('request.jwt.claims', true), '')::jsonb)->>'role'
    );
    v_expected jsonb;
BEGIN
    IF v_role IS DISTINCT FROM 'service_role' THEN
        RAISE EXCEPTION 'unauthorized';
    END IF;
    v_expected := private.project_platform_v2_bounded_report_atoms(
        p_user_id,
        p_entry_id,
        p_content_revision
    );
    IF p_card_content IS DISTINCT FROM v_expected THEN
        RAISE EXCEPTION 'report_atoms_mismatch';
    END IF;
    RETURN true;
END;
$$;


--
-- Name: write_entry_note_v1(uuid, bigint, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.write_entry_note_v1(p_entry_id uuid, p_expected_revision bigint, p_notes text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'private', 'pg_temp'
    AS $$
DECLARE principal uuid:=(select auth.uid()); revision bigint; previous text;
BEGIN
  IF principal IS NULL THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  IF p_expected_revision IS NULL OR p_expected_revision<0 OR octet_length(p_notes)>65536 THEN
    RAISE EXCEPTION 'invalid_note_request' USING ERRCODE='22023';
  END IF;
  PERFORM 1 FROM auth.users WHERE id=principal FOR KEY SHARE NOWAIT;
  IF NOT FOUND THEN RAISE EXCEPTION 'unauthorized' USING ERRCODE='42501'; END IF;
  PERFORM private.require_collection_sharing_writes_v1();
  -- Source precedes note/clock rows. Sharing-author admission holds live authority.
  PERFORM id FROM public.word_entries WHERE id=p_entry_id FOR UPDATE;
  PERFORM private.lock_shared_learning_source_v1(principal,p_entry_id);
  IF NOT private.entry_access_v1(principal,p_entry_id,'browse') THEN
    RAISE EXCEPTION 'note_entry_unavailable' USING ERRCODE='42501';
  END IF;
  SELECT COALESCE(clock.revision,0),note.notes INTO revision,previous
  FROM (SELECT 1) anchor
  LEFT JOIN private.user_word_note_revisions clock ON clock.user_id=principal AND clock.word_entry_id=p_entry_id
  LEFT JOIN public.user_word_notes note ON note.user_id=principal AND note.word_entry_id=p_entry_id;
  IF revision IS DISTINCT FROM p_expected_revision THEN RAISE EXCEPTION 'note_changed' USING ERRCODE='40001'; END IF;
  IF previous IS NOT DISTINCT FROM p_notes THEN RETURN public.read_entry_note_v1(p_entry_id); END IF;
  IF p_notes IS NULL THEN
    DELETE FROM public.user_word_notes WHERE user_id=principal AND word_entry_id=p_entry_id;
  ELSE
    INSERT INTO public.user_word_notes(user_id,word_entry_id,notes) VALUES(principal,p_entry_id,p_notes)
    ON CONFLICT(user_id,word_entry_id) DO UPDATE SET notes=excluded.notes,updated_at=clock_timestamp();
  END IF;
  RETURN public.read_entry_note_v1(p_entry_id);
END;
$$;


