    CONSTRAINT platform_v2_headword_groups_management_kind_check CHECK ((management_kind = ANY (ARRAY['source'::text, 'user'::text])))
);


--
-- Name: platform_v2_training_exercise_targets; Type: TABLE; Schema: private; Owner: -
--

CREATE TABLE private.platform_v2_training_exercise_targets (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    schema_version text DEFAULT 'training-exercise-v1'::text NOT NULL,
    entry_id uuid NOT NULL,
    content_node_id uuid,
    family text NOT NULL,
    direction text NOT NULL,
    source_revision text,
    source_text_fingerprint text,
    visibility_state text DEFAULT 'active'::text NOT NULL,
    retired_at timestamp with time zone,
    retirement_reason text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    target_key text GENERATED ALWAYS AS (((((((((schema_version || ':'::text) || family) || ':'::text) || direction) || ':'::text) || (entry_id)::text) || ':'::text) || COALESCE((content_node_id)::text, 'entry'::text))) STORED,
    CONSTRAINT platform_v2_training_exercise_target_shape_check CHECK ((((family = 'meaning'::text) AND (direction = ANY (ARRAY['direct'::text, 'reverse'::text])) AND (content_node_id IS NULL) AND (source_revision IS NULL) AND (source_text_fingerprint IS NULL)) OR ((family = 'idiom'::text) AND (direction = ANY (ARRAY['direct'::text, 'reverse'::text])) AND (content_node_id IS NOT NULL) AND (NULLIF(btrim(source_revision), ''::text) IS NOT NULL) AND (NULLIF(btrim(source_text_fingerprint), ''::text) IS NOT NULL)) OR ((family = 'translation'::text) AND (direction = 'recall'::text) AND (content_node_id IS NOT NULL) AND (NULLIF(btrim(source_revision), ''::text) IS NOT NULL) AND (NULLIF(btrim(source_text_fingerprint), ''::text) IS NOT NULL)))),
    CONSTRAINT platform_v2_training_exercise_target_visibility_check CHECK ((((visibility_state = 'active'::text) AND (retired_at IS NULL)) OR ((visibility_state = 'retired'::text) AND (retired_at IS NOT NULL)))),
    CONSTRAINT platform_v2_training_exercise_targets_direction_check CHECK ((direction = ANY (ARRAY['direct'::text, 'reverse'::text, 'recall'::text]))),
    CONSTRAINT platform_v2_training_exercise_targets_family_check CHECK ((family = ANY (ARRAY['meaning'::text, 'idiom'::text, 'translation'::text]))),
    CONSTRAINT platform_v2_training_exercise_targets_schema_version_check CHECK ((schema_version = 'training-exercise-v1'::text)),
    CONSTRAINT platform_v2_training_exercise_targets_visibility_state_check CHECK ((visibility_state = ANY (ARRAY['active'::text, 'retired'::text])))
);


