--
-- Name: shared_author_entry_memberships_v1; Type: VIEW; Schema: private; Owner: -
--

CREATE VIEW private.shared_author_entry_memberships_v1 AS
 SELECT scope.user_id,
    entry.id AS entry_id,
    scope.collection_id,
    scope.root_id
   FROM (((private.live_collection_sharing_subscriptions_v1 scope
     JOIN public.user_word_list_items item ON ((item.list_id = scope.collection_id)))
     JOIN private.active_word_entries entry ON ((entry.id = item.word_id)))
     JOIN public.dictionaries dictionary ON ((dictionary.id = entry.dictionary_id)))
  WHERE ((dictionary.kind = 'user'::text) AND (dictionary.owner_user_id = scope.owner_user_id) AND (entry.management_kind = 'user'::text));


