    CONSTRAINT user_training_exercise_action_events_action_check CHECK ((action = ANY (ARRAY['record-view'::text, 'start-learning'::text, 'mark-known'::text, 'undo-known'::text, 'review-card'::text, 'review-exercise'::text]))),
    CONSTRAINT user_training_exercise_action_events_result_check CHECK (((result IS NULL) OR (result = ANY (ARRAY['fail'::text, 'hard'::text, 'success'::text, 'easy'::text, 'hide'::text, 'freeze'::text]))))
);


--
-- Name: user_training_exercise_state; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.user_training_exercise_state (
    user_id uuid NOT NULL,
    target_id uuid NOT NULL,
    state_revision uuid DEFAULT gen_random_uuid() NOT NULL,
    fsrs_stability numeric,
    fsrs_difficulty numeric,
    fsrs_reps integer DEFAULT 0 NOT NULL,
    fsrs_lapses integer DEFAULT 0 NOT NULL,
    fsrs_last_grade smallint,
    fsrs_last_interval numeric,
    fsrs_target_retention numeric DEFAULT 0.9 NOT NULL,
    fsrs_params_version text DEFAULT 'fsrs-6-default'::text NOT NULL,
    fsrs_enabled boolean DEFAULT false NOT NULL,
    next_review_at timestamp with time zone DEFAULT now() NOT NULL,
    last_seen_at timestamp with time zone,
    last_reviewed_at timestamp with time zone,
    seen_count integer DEFAULT 0 NOT NULL,
    success_count integer DEFAULT 0 NOT NULL,
    last_result text,
    hidden boolean DEFAULT false NOT NULL,
    frozen_until timestamp with time zone,
    in_learning boolean DEFAULT false NOT NULL,
    learning_due_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL
);


--
-- Name: user_training_scopes; Type: TABLE; Schema: public; Owner: -
