    card_filter text DEFAULT 'both'::text,
    modes_enabled text[] DEFAULT ARRAY['word-to-definition'::text],
    new_review_ratio integer DEFAULT 2,
    created_at timestamp with time zone DEFAULT now(),
    updated_at timestamp with time zone DEFAULT now(),
    active_list_owner_user_id uuid,
    CONSTRAINT user_training_scopes_active_list_type_check CHECK ((active_list_type = ANY (ARRAY['curated'::text, 'user'::text]))),
    CONSTRAINT user_training_scopes_card_filter_check CHECK ((card_filter = ANY (ARRAY['new'::text, 'review'::text, 'both'::text])))
);


