CREATE TRIGGER trg_user_settings_seed AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.set_default_user_settings();

ALTER TABLE realtime.messages ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "app_events_guard_anon_read_v1" ON realtime.messages;
CREATE POLICY "app_events_guard_anon_read_v1" ON realtime.messages AS RESTRICTIVE FOR SELECT TO "anon" USING (((topic !~~ 'app:%'::text) AND (COALESCE(( SELECT realtime.topic() AS topic), ''::text) !~~ 'app:%'::text)));

DROP POLICY IF EXISTS "app_events_guard_anon_write_v1" ON realtime.messages;
CREATE POLICY "app_events_guard_anon_write_v1" ON realtime.messages AS RESTRICTIVE FOR INSERT TO "anon" WITH CHECK (((topic !~~ 'app:%'::text) AND (COALESCE(( SELECT realtime.topic() AS topic), ''::text) !~~ 'app:%'::text)));

DROP POLICY IF EXISTS "app_events_guard_read_v1" ON realtime.messages;
CREATE POLICY "app_events_guard_read_v1" ON realtime.messages AS RESTRICTIVE FOR SELECT TO "authenticated" USING ((((topic !~~ 'app:%'::text) AND (COALESCE(( SELECT realtime.topic() AS topic), ''::text) !~~ 'app:%'::text)) OR ((extension = 'broadcast'::text) AND (topic = ( SELECT realtime.topic() AS topic)) AND private.can_receive_app_event_v1(topic))));

DROP POLICY IF EXISTS "app_events_guard_write_v1" ON realtime.messages;
CREATE POLICY "app_events_guard_write_v1" ON realtime.messages AS RESTRICTIVE FOR INSERT TO "authenticated" WITH CHECK (((topic !~~ 'app:%'::text) AND (COALESCE(( SELECT realtime.topic() AS topic), ''::text) !~~ 'app:%'::text)));

DROP POLICY IF EXISTS "app_events_receive_v1" ON realtime.messages;
CREATE POLICY "app_events_receive_v1" ON realtime.messages AS PERMISSIVE FOR SELECT TO "authenticated" USING (((extension = 'broadcast'::text) AND (topic = ( SELECT realtime.topic() AS topic)) AND private.can_receive_app_event_v1(topic)));

DROP POLICY IF EXISTS "product_admission_fence" ON realtime.messages;
CREATE POLICY "product_admission_fence" ON realtime.messages AS RESTRICTIVE FOR ALL TO "anon","authenticated" USING (( SELECT private.admission_allowed(( SELECT auth.uid() AS uid)) AS admission_allowed)) WITH CHECK (( SELECT private.admission_allowed(( SELECT auth.uid() AS uid)) AS admission_allowed));


CREATE EVENT TRIGGER product_admission_new_table_fence ON ddl_command_end
 WHEN TAG IN ('CREATE TABLE','ALTER TABLE','GRANT','REVOKE')
 EXECUTE FUNCTION private.admission_attach_fences();
ALTER TABLE private.admission_control SET (autovacuum_enabled=true);

DO $$
DECLARE existing text;
BEGIN
 SELECT substring(x FROM '^pgrst.db_pre_request=(.*)$') INTO existing FROM pg_db_role_setting s CROSS JOIN LATERAL unnest(s.setconfig) x WHERE s.setrole IN (0,(SELECT oid FROM pg_roles WHERE rolname='authenticator')) AND s.setdatabase IN (0,(SELECT oid FROM pg_database WHERE datname=current_database())) AND x LIKE 'pgrst.db_pre_request=%' AND x NOT IN ('pgrst.db_pre_request=','pgrst.db_pre_request=public.admission_enforce') LIMIT 1;
 IF existing IS NOT NULL AND existing<>'' AND existing<>'public.admission_enforce' THEN RAISE EXCEPTION 'existing_pre_request_hook_requires_composition'; END IF;
 EXECUTE format('ALTER ROLE authenticator IN DATABASE %I SET pgrst.db_pre_request=%L',current_database(),'public.admission_enforce');
END;
$$;
NOTIFY pgrst,'reload config';

DO $install_pg_cron_if_missing$
BEGIN
    IF to_regclass('cron.job') IS NULL THEN
        EXECUTE 'CREATE EXTENSION IF NOT EXISTS pg_cron WITH SCHEMA pg_catalog';
    END IF;
END
$install_pg_cron_if_missing$;

SELECT cron.schedule(
    'admin-audit-retention-365-days',
    '17 3 * * *',
    $cron$DELETE FROM public.admin_audit_events
          WHERE created_at < now() - interval '365 days'$cron$
);


-- Pre-managed migration ledger. This contract-owned schema must exist before
-- the first numbered migration can be applied and recorded atomically.



CREATE TABLE IF NOT EXISTS public.app_db_contract_migrations (
  migration_id integer PRIMARY KEY,
  filename text NOT NULL UNIQUE,
  checksum_sha256 text NOT NULL CHECK (checksum_sha256 ~ '^[0-9a-f]{64}$'),
  contract_id text NOT NULL,
  app_commit text NOT NULL CHECK (app_commit ~ '^[0-9a-f]{40}$'),
  applied_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

CREATE TABLE IF NOT EXISTS public.app_db_contract_state (
  singleton boolean PRIMARY KEY DEFAULT true CHECK (singleton),
  contract_id text NOT NULL,
  migration_id integer NOT NULL,
  app_commit text NOT NULL CHECK (app_commit ~ '^[0-9a-f]{40}$'),
  verified_at timestamptz NOT NULL DEFAULT clock_timestamp()
);

ALTER TABLE public.app_db_contract_migrations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.app_db_contract_state ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.app_db_contract_migrations
FROM PUBLIC, anon, authenticated, service_role;
REVOKE ALL ON TABLE public.app_db_contract_state
FROM PUBLIC, anon, authenticated, service_role;
GRANT SELECT ON TABLE public.app_db_contract_state TO service_role;




